/* ---------- Tiện ích cấu hình ---------- */
const mu=()=>Math.log2(S.scs/15);
const isTDD=()=>BANDS[S.band].dx==='TDD';
const bwOpts=()=>BANDS[S.band].bws.filter(b=>NRB[S.scs]&&NRB[S.scs][b]);
function arfcn(f){return f<3000?Math.round(f/0.005):f<24250?Math.round(600000+(f-3000)/0.015):Math.round(2016667+(f-24250.08)/0.06);}
function dmrsSyms(dur,add,l0){
  if(dur<8||add===0)return[l0];
  if(dur<10)return[l0,7];
  if(dur<12)return add===1?[l0,9]:[l0,6,9];
  if(dur===12)return add===1?[l0,9]:add===2?[l0,6,9]:[l0,5,8,11];
  return add===1?[l0,11]:add===2?[l0,7,11]:[l0,5,8,11];
}
function slotType(i){if(!isTDD())return'D';const p=S.tdd;return p[i%p.length];}
function dlSymsOf(i){const t=slotType(i);return t==='D'?14:t==='S'?SSFS[S.ssf][0]:0;}
/* vị trí ứng viên SSB thứ idx: Case A (15 kHz) / Case C (30 kHz) / Case D (120 kHz) */
function ssbPos(idx){
  if(S.scs===120){const nv=[0,1,2,3,5,6,7,8,10,11,12,13,15,16,17,18];const sym=[4,8,16,20][idx%4]+28*nv[Math.floor(idx/4)];return{slot:Math.floor(sym/14),start:sym%14};}
  return{slot:Math.floor(idx/2),start:idx%2?8:2};
}
function ssbPlan(){
  const L=BANDS[S.band].lmax,ok=[];
  for(let i=0;i<L;i++){const p=ssbPos(i);if(p.start+3<dlSymsOf(p.slot))ok.push({idx:i,...p});}
  return{L,feasible:ok.length,used:ok.slice(0,S.nBeam),ok};
}
function normalize(){
  const b=BANDS[S.band];
  if(!b.scs.includes(S.scs))S.scs=b.scs[0];
  const bo=bwOpts();if(!bo.includes(S.bw))S.bw=bo[bo.length-1];
  if(!b.ants.includes(S.ant)){S.ant=b.ant;antDefaults();}
  const a=ANT[S.ant];
  if(a.beams===1)S.nBeam=1;
  S.nBeam=clamp(S.nBeam,1,b.lmax);
  S.layers=clamp(S.layers,1,a.layers);
  for(const i of [2,3,4])S['sd'+i]=clamp(S['sd'+i],b.fr===2?50:100,b.fr===2?800:5000);
  {const r=refD()*1.12;S.cx=clamp(S.cx,-r,r);S.cy=clamp(S.cy,-r,r);for(const o of S.obs){o.x=clamp(o.x,-r,r);o.y=clamp(o.y,-r,r);}}
  S.nObs=clamp(S.nObs,0,4);S.ux=clamp(S.ux,0,routeLen());
  if(S.bArr!=='custom'&&!BTECH[S.bTech].arr.includes(S.bArr)){const k=BTECH[S.bTech].def,p=BARR[k];S.bArr=k;S.bNh=p.nh;S.bNv=p.nv;S.bK=p.k;}
  S.bSlot=clamp(S.bSlot,0,15);
  if(S.mode==='LTE'){if(S.covRat==='nr')S.covRat='lte';if(S.psel.rat==='nr')S.psel={rat:'lte',slot:0};lteProcs();S.proc=clamp(S.proc,0,PROCS.LTE.length-1);S.layers=clamp(S.layers,1,4);}
  {const cc=caList().map((c,i)=>c.band!=='none'?i:-1).filter(i=>i>=0);if(cc.length&&!cc.includes(S.caPc))S.caPc=cc[0];S.caD=clamp(S.caD,30,S.caDmax);S.esHour=clamp(S.esHour,0,23);}
  if(!isTDD())S.slot=clamp(S.slot,0,9);
  const pr=PROCS[S.mode];if(S.proc>=pr.length)S.proc=0;
  S.step=clamp(S.step,0,pr[S.proc].steps.length-1);
}
function antDefaults(){
  const a=ANT[S.ant];S.pw=a.pw;S.layers=a.layers;
  S.nBeam=a.beams===1?1:Math.min(a.beams,BANDS[S.band].lmax);
  S.nBeam=Math.max(1,Math.min(S.nBeam,ssbPlan().feasible));
}
function bandDefaults(){
  const b=BANDS[S.band];S.scs=b.scs[0];S.bw=bwOpts().slice(-1)[0];S.ant=b.ant;S.slot=0;
  const od=refD(),setD=v=>{S.sd2=S.sd3=S.sd4=v;};
  if(b.fr===2){setD(300);S.scen='UMi';S.hbs=10;}else if(od<=400){setD(800);S.scen='UMa';S.hbs=25;}
  const kd=refD()/od;if(kd!==1){S.cx*=kd;S.cy*=kd;for(const o of S.obs){o.x*=kd;o.y*=kd;o.w*=kd;o.h*=kd;}}
  S.ux=refD()/4;antDefaults();
}

/* ---------- Tham số suy ra của cell ---------- */
function env(){
  const b=BANDS[S.band],a=ANT[S.ant],nrb=NRB[S.scs][S.bw],m=mu(),tdd=isTDD();
  let dl=1,ul=1;
  if(tdd){const [d,,u]=SSFS[S.ssf];let D=0,U=0;for(const ch of S.tdd){if(ch==='D')D+=14;else if(ch==='U')U+=14;else{D+=d;U+=u;}}dl=D/(S.tdd.length*14);ul=U/(S.tdd.length*14);}
  const fr2=b.fr===2,ohDL=fr2?0.18:0.14,ohUL=fr2?0.10:0.08,symRate=14*2**m*1000;
  const pTot=10*log10(S.pw*1000),pRE=pTot-10*log10(nrb*12);
  const qm=S.mod===256?8:6;
  const peakDL=S.layers*qm*(948/1024)*nrb*12*symRate*(1-ohDL)*dl/1e6;
  const peakUL=(fr2?2:Math.min(2,a.layers))*6*(948/1024)*nrb*12*symRate*(1-ohUL)*ul/1e6;
  const fft=2**Math.ceil(Math.log2(nrb*12));
  return{b,a,nrb,m,tdd,dl,ul,fr2,ohDL,ohUL,symRate,pTot,pRE,fG:b.f/1000,peakDL,peakUL,fft,fs:fft*S.scs/1000};
}

/* ---------- Suy hao đường truyền TR 38.901 ---------- */
function pathloss(scen,los,fG,d2,hB,hU){
  d2=Math.max(d2,10);const d3=Math.hypot(d2,hB-hU),c=3e8,fHz=fG*1e9;
  if(scen==='RMa'){
    const h=5,W=20,dbp=2*Math.PI*hB*hU*fHz/c;
    const g=d=>20*log10(40*Math.PI*d*fG/3)+Math.min(0.03*h**1.72,10)*log10(d)-Math.min(0.044*h**1.72,14.77)+0.002*log10(h)*d;
    const pl=d2<=dbp?g(d3):g(dbp)+40*log10(d3/dbp);
    if(los)return pl;
    const nl=161.04-7.1*log10(W)+7.5*log10(h)-(24.37-3.7*(h/hB)**2)*log10(hB)+(43.42-3.1*log10(hB))*(log10(d3)-3)+20*log10(fG)-(3.2*log10(11.75*hU)**2-4.97);
    return Math.max(pl,nl);
  }
  const dbp=4*(hB-1)*(hU-1)*fHz/c,dh2=(hB-hU)**2;
  if(scen==='UMi'){
    const pl=d2<=dbp?32.4+21*log10(d3)+20*log10(fG):32.4+40*log10(d3)+20*log10(fG)-9.5*log10(dbp*dbp+dh2);
    return los?pl:Math.max(pl,35.3*log10(d3)+22.4+21.3*log10(fG)-0.3*(hU-1.5));
  }
  const pl=d2<=dbp?28+22*log10(d3)+20*log10(fG):28+40*log10(d3)+20*log10(fG)-9*log10(dbp*dbp+dh2);
  return los?pl:Math.max(pl,13.54+39.08*log10(d3)+20*log10(fG)-0.6*(hU-1.5));
}
/* độ lợi tương đối của chùm SSB tốt nhất theo góc phương vị (mẫu parabol 3GPP) */
function beamGain(az,n){
  if(n<=1)return{g:-Math.min(12*(az/65)**2,25),idx:0};
  const w=120/n;let best=-99,bi=0;
  for(let i=0;i<n;i++){const c=-60+w*(i+0.5),g=-Math.min(12*((az-c)/w)**2,25);if(g>best){best=g;bi=i;}}
  return{g:best,idx:bi};
}
/* gNB1 ở giữa; ba trạm lân cận đặt theo khoảng cách (mét) và hướng tuỳ chỉnh; mỗi trạm ba sector, một sector quay về gNB1 */
let DRAGREF=null;
const refD=()=>DRAGREF||Math.max(S.sd2,S.sd3,S.sd4);
function sites(){
  const s=[null,{x:0,y:0,az:[0,120,240]}];
  for(const i of [2,3,4]){const a=S['sa'+i],d=S['sd'+i],r=a*Math.PI/180;s.push({x:d*Math.cos(r),y:d*Math.sin(r),az:[a+180,a+60,a+300].map(v=>v%360)});}
  return s;
}
function destPt(){
  const s=sites(),lim=refD()*1.1,mix=(a,b)=>{let x=(0.62*s[a].x+0.38*s[b].x)*1.5,y=(0.62*s[a].y+0.38*s[b].y)*1.5;const n=Math.hypot(x,y);if(n>lim){x*=lim/n;y*=lim/n;}return[x,y];};
  return{g2:[s[2].x,s[2].y],g3:[s[3].x,s[3].y],g4:[s[4].x,s[4].y],a45:mix(2,3),a75:mix(3,2),a315:mix(2,4),a165:mix(3,4),custom:[S.cx,S.cy]}[S.dest];
}
function routeLen(){const [x,y]=destPt();return Math.max(20,Math.hypot(x,y));}
function uePos(t){const [x,y]=destPt(),L=Math.hypot(x,y)||1;if(t===undefined)t=S.ux;return[x*t/L,y*t/L];}
function geo(i,x,y){
  const s=sites()[i],dx=x-s.x,dy=y-s.y,ang=Math.atan2(dy,dx)*180/Math.PI;let az=999,sec=0;
  s.az.forEach((a,k)=>{const r=((ang-a+900)%360)-180;if(Math.abs(r)<Math.abs(az)){az=r;sec=k;}});
  return{d:Math.hypot(dx,dy),az,sec};
}
/* vật cản: hình chữ nhật; sóng đi xuyên bị hấp thụ, phần vòng qua nhờ nhiễu xạ và tán xạ */
const OBST={bt:{t:'Nhà cao tầng bê tông',abs:25,sc:30},kinh:{t:'Toà nhà kính phủ kim loại',abs:32,sc:55},xuong:{t:'Nhà xưởng mái tôn',abs:18,sc:45},cay:{t:'Hàng cây, công viên',abs:8,sc:20},doi:{t:'Đồi hoặc công trình rất lớn',abs:40,sc:10}};
function segHit(ax,ay,bx,by,o){
  const w=o.w*S.obsScale/2,h=o.h*S.obsScale/2,dx=bx-ax,dy=by-ay;let t0=0,t1=1;
  for(const [p,qq] of [[-dx,ax-(o.x-w)],[dx,o.x+w-ax],[-dy,ay-(o.y-h)],[dy,o.y+h-ay]]){
    if(p===0){if(qq<0)return false;}else{const r=qq/p;if(p<0){if(r>t1)return false;if(r>t0)t0=r;}else{if(r<t0)return false;if(r<t1)t1=r;}}}
  return true;
}
function obsOne(o,fG){const kf=clamp(0.55+0.15*Math.log2(fG/0.7),0.5,1.4),A=o.abs*kf,Sc=6+24*(1-o.sc/100);return -10*log10(10**(-A/10)+10**(-Sc/10));}
function obsLoss(ax,ay,bx,by,fG){let L=0;for(let i=0;i<S.nObs;i++)if(segHit(ax,ay,bx,by,S.obs[i]))L+=obsOne(S.obs[i],fG);return L;}
function nrRsrp(i,x,y,E){
  const {d,az,sec}=geo(i,x,y),bg=beamGain(az,S.nBeam),s=sites()[i],ob=obsLoss(s.x,s.y,x,y,E.fG);
  const pl=pathloss(S.scen,S.los==='LOS',E.fG,d,S.hbs,1.5)+S.pen+ob;
  const gt=E.a.gT+(E.a.beams>1?-Math.min(12*(az/90)**2,20):bg.g);
  return{r:E.pRE+E.a.gS+bg.g-pl,s:E.pRE+gt-pl,pl,d,az,sec,beam:bg.idx,gt,ob};
}
/* cell LTE: tham số lấy từ cấu hình đang chọn (băng, băng thông, anten, công suất) */
const LTE={get f(){return LBANDS[S.lBand].f/1000;},get nrb(){return LTEBW[S.lteBw];},get pRE(){return 10*log10(LANT[S.lAnt].trx*S.lPw*1000)-10*log10(this.nrb*12);},get g(){return LANT[S.lAnt].g;}};
function lteRsrp(i,x,y){
  const {d,az,sec}=geo(i,x,y),g=LTE.g-Math.min(12*(az/65)**2,25),s=sites()[i],ob=obsLoss(s.x,s.y,x,y,LTE.f);
  const pl=pathloss(S.scen,S.los==='LOS',LTE.f,d,S.hbs,1.5)+S.pen*0.7+ob;
  return{r:LTE.pRE+g-pl,s:LTE.pRE+g-pl,pl,d,g,gt:g,ob,sec,az,beam:0};
}
/* 3G WCDMA 2100 MHz cùng trạm: 20 W, kênh hoa tiêu CPICH 2 W */
const UMTS={f:2.1,pTot:43,pC:33,g:17.5};
function umtsRx(i,x,y){
  const {d,az}=geo(i,x,y),g=UMTS.g-Math.min(12*(az/65)**2,25),s=sites()[i],ob=obsLoss(s.x,s.y,x,y,UMTS.f);
  const pl=pathloss(S.scen,S.los==='LOS',UMTS.f,d,S.hbs,1.5)+S.pen*0.75+ob;
  return{r:UMTS.pC+g-pl,tot:UMTS.pTot+g-pl,pl,d,g,ob};
}
/* nhiễu đường lên tại trạm phục vụ s: mỗi cell lân cận có một UE điển hình (cách trạm của nó khoảng một phần ba quãng tới trạm s) phát lên theo điều khiển công suất, nhân với tải */
function ulIot(rat,s,E){
  const ST=sites(),c=ST[s],ld=S.load/100;let I=0;
  const cf=rat==='nr'?{f:E.fG,hz:12*S.scs*1e3,nf:3.5,pm:S.uePw}:rat==='lte'?{f:LTE.f,hz:180e3,nf:3.5,pm:23}:{f:2.1,hz:3.84e6,nf:3,pm:21};
  const pl=(i,x,y)=>{const t=ST[i];return pathloss(S.scen,S.los==='LOS',cf.f,Math.hypot(x-t.x,y-t.y),S.hbs,1.5)+obsLoss(t.x,t.y,x,y,cf.f);};
  const gain=(i,x,y)=>{const az=geo(i,x,y).az;return rat==='nr'?E.a.gS+beamGain(az,S.nBeam).g:(rat==='lte'?LTE.g:17.5)-Math.min(12*(az/65)**2,25);};
  for(const j of [1,2,3,4]){if(j===s)continue;const mx=ST[j].x+(c.x-ST[j].x)*0.35,my=ST[j].y+(c.y-ST[j].y)*0.35,own=pl(j,mx,my);
    const tx=rat==='umts'?Math.min(cf.pm,-112+own-gain(j,mx,my)):Math.min(cf.pm-10,-96+0.8*own);
    I+=ld*10**((tx+gain(s,mx,my)-pl(s,mx,my))/10);}
  const N=-174+10*log10(cf.hz)+cf.nf,n=10**(N/10);let own=0;
  if(rat==='umts'){const e=Math.min(0.9,0.6*ld);own=n*e/(1-e);}
  const tot=I+own+n;
  return{I:10*log10(I+own+1e-30),N,iot:10*log10(tot/n),tot:10*log10(tot)};
}
function cqiOf(s,m256){let c=0;for(let i=0;i<15;i++)if(s>=CQI_TH[i])c=i+1;return m256?c:Math.min(c,11);}
const seOf=c=>c?QM[CQI[c-1][0]]*CQI[c-1][1]/1024:0;
function adapt(sinr,maxL,m256){
  let best={rank:1,cqi:0,se:0,tot:0};
  for(let r=1;r<=maxL;r++){const s=sinr-10*log10(r)-(r-1)*1.5,c=cqiOf(s,m256),tot=r*seOf(c);if(tot>best.tot)best={rank:r,cqi:c,se:seOf(c),tot};}
  return best;
}
function ulLink(pTx,nrb,scsk,gRx,pl,maxRank,symRate,oh,frac,iot){
  const N=-174+10*log10(scsk*1e3)+3.5+(iot===undefined?3*S.load/100:iot);
  let prb=nrb,s=pTx-10*log10(prb*12)+gRx-pl-N;
  if(s<0){prb=Math.max(1,Math.floor(nrb*10**(s/10)));s=pTx-10*log10(prb*12)+gRx-pl-N;}
  s=Math.min(s,25);const ad=adapt(s,maxRank,false);
  return{sinr:s,prb,rate:ad.tot*prb*12*symRate*(1-oh)*frac/1e6,ad};
}

/* ---------- Mô phỏng di động dọc đường đi: UE xuất phát từ gNB1, đo cả bốn trạm ---------- */
function simPath(E){
  const L=routeLen(),step=Math.max(2,L/400),n=Math.floor(L/step)+1,dT=S.speed/3.6*S.ttt/1000,L4=S.mode==='LTE',ns=S.mode!=='SA',ID=[1,2,3,4];
  const nr=new Int8Array(n),lte=new Int8Array(n),ev=[];
  const RR=t=>{const [x,y]=uePos(t);return ID.map(i=>nrRsrp(i,x,y,E).r);},LL=t=>{const [x,y]=uePos(t);return ID.map(i=>lteRsrp(i,x,y).r);};
  const best=(a,ex)=>{let b=-1;a.forEach((v,i)=>{if(i+1!==ex&&(b<0||v>a[b]))b=i;});return b+1;};
  const r0=RR(0);let s=best(r0,0),t0=null,tk='';
  if(ns&&!(r0[s-1]-S.hys>S.b1))s=0;
  if(L4)s=0;
  let ls=ns?best(LL(0),0):0,lt0=null,ltk=0;
  const arm=(k,x)=>{if(t0===null||tk!==k){t0=x;tk=k;}return x-t0>=dT;};
  for(let k=0;k<n;k++){
    const x=k*step,R=RR(x);
    if(L4){}
    else if(s===0){
      const b=best(R,0);
      if(R[b-1]-S.hys>S.b1){if(arm('b'+b,x)){s=b;ev.push({x,c:'nr',t:`B1 thoả: gNB${b} là cell NR mạnh nhất và vượt ngưỡng ${S.b1} dBm, eNB thêm gNB${b} làm nút phụ`});t0=null;}}
      else t0=null;
    }else{
      const o=best(R,s),rs=R[s-1];
      if(R[o-1]-S.hys>rs+S.a3Off){if(arm('a'+o,x)){ev.push({x,c:'nr',t:ns?`A3 thoả từ ${f0(t0)} m: gNB${o} là lân cận mạnh nhất, đổi PSCell từ gNB${s} sang gNB${o}`:`A3 thoả từ ${f0(t0)} m: gNB${o} là lân cận mạnh nhất, hết TTT thì handover từ gNB${s} sang gNB${o}`});s=o;t0=null;}}
      else if(ns&&rs+S.hys<S.a2){if(arm('a2',x)){ev.push({x,c:'nr',t:`A2 thoả (NR-RSRP dưới ${S.a2} dBm): giải phóng gNB${s}, UE chỉ còn LTE`});s=0;t0=null;}}
      else t0=null;
    }
    nr[k]=s;
    if(ns){
      const Q=LL(x),o=best(Q,ls);
      if(Q[o-1]-S.hys>Q[ls-1]+S.a3Off){if(lt0===null||ltk!==o){lt0=x;ltk=o;}if(x-lt0>=dT){ev.push({x,c:'lte',t:L4?`A3 thoả từ ${f0(lt0)} m: eNB${o} là lân cận mạnh nhất, hết TTT thì handover từ eNB${ls} sang eNB${o} qua X2`:`A3 trên LTE: eNB${o} là lân cận mạnh nhất, handover neo từ eNB${ls} sang eNB${o}`});ls=o;lt0=null;}}
      else lt0=null;
      lte[k]=ls;
    }
  }
  ev.sort((a,b)=>a.x-b.x);
  return{step,n,nr,lte,ev,L};
}
function rsrpClass(r){return r>=-80?['#2F6FDE','Rất tốt']:r>=-95?['#22A06B','Tốt']:r>=-105?['#D4A100','Trung bình']:r>=-115?['#E0782A','Yếu']:['#D03A2B','Rất yếu'];}
