const CMP=[['Lõi','5GC (AMF, SMF, UPF)','EPC (MME, S-GW)'],['Neo điều khiển','NR','LTE'],['Trạm nối lõi qua','NG (N2, N3)','S1'],['Giữa các trạm','Xn','X2'],['Thêm NR bằng','Truy nhập thẳng vào NR','Sự kiện B1 trên LTE'],['RRC_INACTIVE, slicing','Có','Không'],['Tốc độ đường xuống','NR (cộng CA nếu có)','LTE + NR']];
/* ---------- Tên tiếng Anh đầy đủ của từ viết tắt trong tiêu đề giải thích khối ---------- */
var _ACRO=null,_ACRE=null;
function acroInit(){
  if(_ACRO)return;
  _ACRO={
   'UE':'User Equipment','RU':'Radio Unit','AAU':'Active Antenna Unit','RRU':'Remote Radio Unit','DU':'Distributed Unit','CU':'Central Unit',
   'CU-CP':'Central Unit, Control Plane','CU-UP':'Central Unit, User Plane',
   'gNB':'next-generation NodeB','gNB-DU':'next-generation NodeB Distributed Unit','gNB-CU-CP':'next-generation NodeB Central Unit, Control Plane','gNB-CU-UP':'next-generation NodeB Central Unit, User Plane',
   'en-gNB':'E-UTRA-NR Dual Connectivity gNB','eNB':'evolved NodeB','MeNB':'Master eNB','SgNB':'Secondary gNB',
   'AMF':'Access and Mobility Management Function','SMF':'Session Management Function','UPF':'User Plane Function','PCF':'Policy Control Function',
   'UDM':'Unified Data Management','UDR':'Unified Data Repository','AUSF':'Authentication Server Function','NSSF':'Network Slice Selection Function',
   'NRF':'Network Repository Function','CHF':'Charging Function','SMSF':'Short Message Service Function','SMSC':'Short Message Service Centre',
   'OCS':'Online Charging System','SCP':'Service Control Point','CDF':'Charging Data Function',
   'IMS':'IP Multimedia Subsystem','HSS':'Home Subscriber Server','PCRF':'Policy and Charging Rules Function','MME':'Mobility Management Entity',
   'S-GW':'Serving Gateway','P-GW':'Packet Data Network Gateway','SGW':'Serving Gateway','PGW':'Packet Data Network Gateway',
   'MSC':'Mobile Switching Centre','VLR':'Visitor Location Register','HLR':'Home Location Register','AuC':'Authentication Centre','EIR':'Equipment Identity Register',
   'SGSN':'Serving GPRS Support Node','GGSN':'Gateway GPRS Support Node','GMSC':'Gateway Mobile Switching Centre','MGW':'Media Gateway','RNC':'Radio Network Controller','SIM':'Subscriber Identity Module',
   'P-CSCF':'Proxy Call Session Control Function','I-CSCF':'Interrogating Call Session Control Function','S-CSCF':'Serving Call Session Control Function',
   'TAS':'Telephony Application Server','SCC AS':'Service Centralization and Continuity Application Server','IP-SM-GW':'IP Short Message Gateway',
   'MRF':'Media Resource Function','IBCF':'Interconnection Border Control Function','BGCF':'Breakout Gateway Control Function','MGCF':'Media Gateway Control Function',
   'IM-MGW':'IP Multimedia Media Gateway','ATCF':'Access Transfer Control Function','ATGW':'Access Transfer Gateway','TrGW':'Transition Gateway','IMS-AGW':'IMS Access Gateway',
   'ENUM':'E.164 Number Mapping','DNS':'Domain Name System','E-CSCF':'Emergency Call Session Control Function','LRF':'Location Retrieval Function','SBC':'Session Border Controller','DEA':'Diameter Edge Agent','SEPP':'Security Edge Protection Proxy','STP':'Signal Transfer Point',
   'CPRI':'Common Public Radio Interface','SBI':'Service-Based Interface','MAP':'Mobile Application Part','CAP':'CAMEL Application Part','CAMEL':'Customised Applications for Mobile network Enhanced Logic',
   'ISUP':'ISDN User Part','ISC':'IMS Service Control','SIP':'Session Initiation Protocol','Iu-CS':'Iu Circuit-Switched','Iu-PS':'Iu Packet-Switched',
   'NG-C':'NG Control plane','NG-U':'NG User plane','F1-C':'F1 Control plane','F1-U':'F1 User plane',
   'S1-MME':'S1 control plane to the MME','S1-U':'S1 User plane',
   'NAS':'Non-Access Stratum','RRC':'Radio Resource Control','SDAP':'Service Data Adaptation Protocol','PDCP':'Packet Data Convergence Protocol','RLC':'Radio Link Control',
   'MAC':'Medium Access Control','PHY':'Physical layer','RF':'Radio Frequency','IP':'Internet Protocol'
  };
  var ks=Object.keys(_ACRO).sort(function(a,b){return b.length-a.length;}).map(function(k){return k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}),K='(?:'+ks.join('|')+')';
  _ACRE=new RegExp(K+'(?:/'+K+')*(?:\\s?[0-9]+)?(?![A-Za-z0-9])(?!-[A-Za-z0-9])','g');
}
/* Thêm tên tiếng Anh đầy đủ trong ngoặc đơn sau mỗi từ viết tắt trong tiêu đề khối. Nếu ngay sau là ngoặc chú thích tiếng Việt thì gộp vào cùng một ngoặc. */
function acrT(s){
  s=String(s==null?'':s);acroInit();
  var seen={};
  var o=s.replace(_ACRE,function(m,off){
    var p=off>0?s.charAt(off-1):'';if(/[A-Za-z0-9\-]/.test(p))return m;
    var sfx=(m.match(/\s?[0-9]+$/)||[''])[0],base=sfx?m.slice(0,m.length-sfx.length):m,parts=base.split('/'),fl=[],i;
    for(i=0;i<parts.length;i++){if(!seen[parts[i]]){seen[parts[i]]=1;fl.push(_ACRO[parts[i]]);}else fl.push(null);}
    if(fl.every(function(x){return x===null;}))return m;
    var depth=0,j;for(j=0;j<off;j++){var c=s.charAt(j);if(c==='(')depth++;else if(c===')')depth--;}
    if(depth>0){return parts.map(function(t,k){return fl[k]?t+': '+fl[k]:t;}).join('/')+sfx;}
    var full=fl.filter(function(x){return x;}).join(' / ');
    return m+' ('+full+'\u0001)';
  });
  return o.replace(/\u0001\) \(/g,', ').replace(/\u0001/g,'');
}
function renderArch(){
  $('#archLead').textContent=lte()?'Mạng 4G LTE: eNB tự làm mọi việc của tầng vô tuyến và nối thẳng vào lõi EPC. Lõi tách phần điều khiển (MME) khỏi phần dữ liệu (S-GW, P-GW). Mọi dịch vụ đều chạy trên IP; thoại là VoLTE qua IMS, hoặc rơi xuống 3G bằng CSFB ở vùng chưa có VoLTE.':nsa()?'NSA (Non-Standalone, còn gọi EN-DC): UE giữ kết nối điều khiển trên LTE với lõi 4G, còn NR được thêm làm sóng mang phụ để tăng tốc dữ liệu. Cách này triển khai nhanh trên mạng 4G có sẵn.':'SA (Standalone, option 2): gNB nối thẳng vào lõi 5G. Cả báo hiệu lẫn dữ liệu đều chạy trên NR, nên dùng được trọn các tính năng 5G như network slicing, RRC_INACTIVE và độ trễ thấp.';
  $('#arch').innerHTML=lte()?archLTE():nsa()?archNSA():archSA();
  const i=infoOf(S.sel),col=lte()?3:nsa()?2:1,C4=['EPC (MME, S-GW, P-GW)','LTE','S1','X2','Không có NR','Không','LTE (cộng CA nếu có)'];
  let h=`<h2>${acrT(i.t)}</h2><p>${i.d}</p>`;
  if(i.v&&S.vendor!=='3gpp')h+=`<p><b>${VN[S.vendor].n}:</b> ${VNOTE[i.v][S.vendor]}</p>`;
  h+=kbHtml(S.sel);
  h+=`<h3 style="margin-top:16px">SA, NSA và 4G khác nhau ở đâu</h3><div class="scroll"><table><tr><th></th><th class="${col===1?'hl':''}">SA</th><th class="${col===2?'hl':''}">NSA</th><th class="${col===3?'hl':''}">4G</th></tr>`+CMP.map((r,k)=>`<tr><td>${r[0]}</td><td class="${col===1?'hl':''}">${r[1]}</td><td class="${col===2?'hl':''}">${r[2]}</td><td class="${col===3?'hl':''}">${C4[k]}</td></tr>`).join('')+'</table></div>';
  $('#archInfo').innerHTML=h;
}

/* ---------- Phủ sóng và di động ---------- */
let sigBase='',sigScene='',PATH=null,SC=null,CH=null,COV={sig:'',url:''};
const DESTN={g2:'gNB2',g3:'gNB3',g4:'gNB4',a45:'giữa gNB2 và gNB3',a75:'giữa gNB2 và gNB3',a315:'giữa gNB2 và gNB4',a165:'giữa gNB3 và gNB4',custom:'điểm tự chọn'};
const RATN={nr:'5G',lte:'4G',umts:'3G'};
function petal(cx,cy,dir,th,hw,L){
  const r=a=>a*Math.PI/180,p=(a,l)=>[(cx+dir*l*Math.cos(r(a))).toFixed(1),(cy-l*Math.sin(r(a))).toFixed(1)];
  const a=p(th-hw,L),b=p(th+hw,L),c=p(th,L*1.12);
  return `M${cx.toFixed(1)} ${cy.toFixed(1)}L${a[0]} ${a[1]}Q${c[0]} ${c[1]} ${b[0]} ${b[1]}Z`;
}
function renderObsRows(){
  const opt=v=>Object.entries(OBST).map(([k,o])=>`<option value="${k}"${k===v?' selected':''}>${o.t}</option>`).join('');
  $('#obsRows').innerHTML=S.obs.slice(0,S.nObs).map((o,i)=>`<div class="obrow"><b>Vật cản ${i+1}</b><select data-ob="${i}" data-f="type" aria-label="Loại vật cản ${i+1}">${opt(o.type)}</select>
   <label><span>Hấp thụ <output>${o.abs} dB</output></span><input type="range" data-ob="${i}" data-f="abs" min="0" max="45" step="1" value="${o.abs}"></label>
   <label><span>Tán xạ, nhiễu xạ <output>${o.sc} %</output></span><input type="range" data-ob="${i}" data-f="sc" min="0" max="100" step="5" value="${o.sc}"></label></div>`).join('')
   ||'<p class="note" style="margin:0">Không có vật cản. Tăng số vật cản để đặt nhà cao tầng hay công trình lên mặt bằng.</p>';
}
const hex2rgb=h=>{h=h.trim().replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');const n=parseInt(h,16);return[n>>16&255,n>>8&255,n&255];};
function ratLevels(rat,x,y,E){return[1,2,3,4].map(i=>rat==='nr'?nrRsrp(i,x,y,E).r:rat==='lte'?lteRsrp(i,x,y).r:umtsRx(i,x,y).r);}
/* ảnh lớp phủ: tính trên lưới rồi kéo giãn lên mặt bằng */
function covImage(E,W,H,k,m){
  if(S.cov==='none')return'';
  const cs=getComputedStyle(document.documentElement),kc=[1,2,3,4].map(i=>cs.getPropertyValue('--k'+i));
  const sig=JSON.stringify([S.cov,S.covRat,S.lBand,S.lteBw,S.lAnt,S.lPw,S.band,S.scs,S.bw,S.ant,S.pw,S.nBeam,S.scen,S.los,S.hbs,S.load,S.pen,S.sd2,S.sd3,S.sd4,S.sa2,S.sa3,S.sa4,S.nObs,S.obsScale,S.obs,DRAGREF,W,H,kc]);
  if(sig===COV.sig)return COV.url;
  const G=64,cv=document.createElement('canvas');cv.width=G;cv.height=G;const cx=cv.getContext('2d'),im=cx.createImageData(G,G),ref=refD(),rat=S.covRat;
  const rgb=kc.map(hex2rgb),RS=[[-80,'#2F6FDE'],[-95,'#22A06B'],[-105,'#D4A100'],[-115,'#E0782A'],[-999,'#D03A2B']].map(([v,c])=>[v,hex2rgb(c)]),SN=[[22,'#2F6FDE'],[15,'#22A06B'],[8,'#D4A100'],[0,'#E0782A'],[-999,'#D03A2B']].map(([v,c])=>[v,hex2rgb(c)]);
  const N0=rat==='nr'?-174+10*log10(S.scs*1e3)+7:rat==='lte'?-174+10*log10(15e3)+7:-101.2,off=rat==='umts'?10:0;
  for(let j=0;j<G;j++)for(let i=0;i<G;i++){
    const x=((i+0.5)/G*W-W/2)/k*ref,y=(m+1.2*k-(j+0.5)/G*H)/k*ref,L=ratLevels(rat,x,y,E);let b=0;for(let q=1;q<4;q++)if(L[q]>L[b])b=q;
    let c,al;const lv=L[b]-off;
    if(S.cov==='best'){c=rgb[b];al=clamp((lv+125)/50,0,1)*0.5+0.06;}
    else if(S.cov==='rsrp'){c=RS.find(r=>lv>=r[0])[1];al=0.5;}
    else{let I=10**(N0/10);for(let q=0;q<4;q++)if(q!==b)I+=10**(L[q]/10)*S.load/100;const sn=L[b]-10*log10(I);c=SN.find(r=>sn>=r[0])[1];al=0.5;}
    const o=(j*G+i)*4;im.data[o]=c[0];im.data[o+1]=c[1];im.data[o+2]=c[2];im.data[o+3]=al*255;
  }
  cx.putImageData(im,0,0);COV={sig,url:cv.toDataURL()};return COV.url;
}
function sceneStatic(E,W,H,px,py,k,m,sn,sec,bestBeam){
  const ST=sites(),ref=refD(),Ls=0.26*k,n=lte()?1:S.nBeam,[dx,dy]=destPt();let s='';
  const url=covImage(E,W,H,k,m);if(url)s+=`<image href="${url}" x="0" y="0" width="${W}" height="${H}" preserveAspectRatio="none"/>`;
  s+=`<line class="rt" x1="${px(0)}" y1="${py(0)}" x2="${px(dx)}" y2="${py(dy)}"/><circle class="rt-end" cx="${px(dx)}" cy="${py(dy)}" r="4.5"/>`;
  for(let i=1;i<=4;i++){
    const c=ST[i],cx=px(c.x),cy=py(c.y);s+=`<g style="--kc:var(--k${i})">`;
    c.az.forEach((a,j)=>{
      if(i===sn&&j===sec){
        if(n<=1)s+=`<path class="bm best" d="${petal(cx,cy,1,a,32.5,Ls*1.3)}"/>`;
        else{const w=120/n;for(let b=0;b<n;b++)s+=`<path class="bm ${b===bestBeam?'best':'sw'}" style="--sd:${(n*0.18).toFixed(2)}s;animation-delay:${(b*0.18).toFixed(2)}s" d="${petal(cx,cy,1,a-60+w*(b+0.5),w/2,Ls*1.3)}"/>`;}
      }else s+=`<path class="sec" d="${petal(cx,cy,1,a,36,Ls)}"/>`;
    });
    const lab=(lte()?`eNB${i}`:nsa()?`eNB${i}+gNB${i}`:`gNB${i}`)+(i>1?`, ${f0(S['sd'+i])} m`:'');
    s+=`<path class="sc-site" d="M${cx-7} ${cy+7}L${cx+7} ${cy+7}L${cx} ${cy-9}Z"/><text class="sc-t sc-halo" x="${clamp(cx,lab.length*3.2+2,W-lab.length*3.2-2)}" y="${cy+20}" text-anchor="middle" style="font-weight:700;fill:var(--ink)">${lab}</text>`;
    if(i>1)s+=`<circle class="drag-h site-h" data-site="${i}" cx="${cx}" cy="${cy}" r="17"/>`;
    s+='</g>';
  }
  for(let i=0;i<S.nObs;i++){const o=S.obs[i],w=o.w*S.obsScale/ref*k,h=o.h*S.obsScale/ref*k,x=px(o.x)-w/2,y=py(o.y)-h/2;
    s+=`<g class="obs drag-h" data-obs="${i}"><rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${w.toFixed(1)}" height="${h.toFixed(1)}" rx="2"/><rect class="obs-hit" x="${(x-8).toFixed(1)}" y="${(y-8).toFixed(1)}" width="${(w+16).toFixed(1)}" height="${(h+16).toFixed(1)}"/><text x="${px(o.x)}" y="${(py(o.y)+3.5).toFixed(1)}">${i+1}</text></g>`;}
  /* thước tỉ lệ */
  const nice=[50,100,200,250,500,1000,2000].find(v=>v/ref*k>=46)||2000,bw=nice/ref*k;
  s+=`<line class="scale" x1="10" y1="${H-9}" x2="${10+bw}" y2="${H-9}"/><line class="scale" x1="10" y1="${H-13}" x2="10" y2="${H-5}"/><line class="scale" x1="${10+bw}" y1="${H-13}" x2="${10+bw}" y2="${H-5}"/><text class="sc-t sc-halo" x="${14+bw}" y="${H-5}">${nice} m</text>`;
  return s;
}
function chartStatic(E,W){
  const P=PATH,ns=endc(),L4=lte(),H=250,ml=38,mr=10,mt=22,nstrip=ns?2:1,mb=26+nstrip*12,pw=W-ml-mr,ph=H-mt-mb,L=P.L,ID=[1,2,3,4];
  const N=120,ts=Array.from({length:N+1},(_,i)=>i*L/N),pts=ts.map(t=>uePos(t));
  const nrc=ID.map(i=>pts.map(([x,y])=>L4?lteRsrp(i,x,y).r:nrRsrp(i,x,y,E).r)),ltc=ns?ID.map(i=>pts.map(([x,y])=>lteRsrp(i,x,y).r)):[];
  const all=nrc.flat().concat(ltc.flat());let hi=Math.max(...all),lo=Math.max(Math.min(...all),hi-80);
  if(ns){lo=Math.min(lo,S.a2);hi=Math.max(hi,S.b1);}
  lo=Math.max(-170,Math.floor((lo-3)/10)*10);hi=Math.min(-20,Math.ceil((hi+3)/10)*10);
  const X=t=>ml+t/L*pw,Y=v=>mt+(hi-clamp(v,lo,hi))/(hi-lo)*ph;CH={X,mt,bot:mt+ph};
  let s='';const stp=hi-lo>70?20:10;
  for(let v=hi;v>=lo;v-=stp)s+=`<line class="ax" x1="${ml}" y1="${Y(v)}" x2="${ml+pw}" y2="${Y(v)}"/><text class="ax-t" x="${ml-5}" y="${Y(v)+3.5}" text-anchor="end">${v}</text>`;
  s+=`<text class="ax-t" x="4" y="10">RSRP (dBm)</text>`;
  if(ns)for(const [kk,lab] of [['b1','B1'],['a2','A2']])s+=`<line class="th" x1="${ml}" y1="${Y(S[kk])}" x2="${ml+pw}" y2="${Y(S[kk])}"/><text class="th-t" x="${ml+pw-2}" y="${Y(S[kk])-3}" text-anchor="end">${lab} ${S[kk]}</text>`;
  const line=(c,i,cls)=>`<polyline class="cv ${cls}" style="stroke:var(--k${i+1})" points="${c.map((v,j)=>X(ts[j]).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}"/>`;
  ltc.forEach((c,i)=>s+=line(c,i,'lt'));nrc.forEach((c,i)=>s+=line(c,i,''));
  let prev=-99;
  P.ev.forEach((e,i)=>{const x=X(e.x);let cx=x;if(cx-prev<17)cx=prev+17;prev=cx;
    s+=`<line class="evl" x1="${x}" y1="${mt}" x2="${x}" y2="${mt+ph}"/><circle class="evc" cx="${cx}" cy="${mt-9}" r="8"/><text class="evt" x="${cx}" y="${mt-5.5}">${String.fromCharCode(65+i)}</text>`;});
  const strip=(arr,row,lab)=>{const y0=mt+ph+6+row*12;let st=0,o=`<text class="ax-t" x="${ml-5}" y="${y0+8}" text-anchor="end">${lab}</text>`;
    for(let k=1;k<=P.n;k++)if(k===P.n||arr[k]!==arr[st]){o+=`<rect ${arr[st]?`style="fill:var(--k${arr[st]})"`:'class="st-0"'} x="${X(st*P.step).toFixed(1)}" y="${y0}" width="${Math.max(0.5,X(Math.min(L,k*P.step))-X(st*P.step)).toFixed(1)}" height="9"/>`;st=k;}
    return o;};
  if(ns)s+=strip(P.lte,0,'LTE');
  s+=L4?strip(P.lte,0,'LTE'):strip(P.nr,ns?1:0,'NR');
  s+=`<text class="ax-t" x="${ml}" y="${H-4}">0 m (${bsN()}1)</text><text class="ax-t" x="${ml+pw}" y="${H-4}" text-anchor="end">${f0(L)} m (${destName()})</text>`;
  const svg=$('#chartSvg');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('width',W);svg.setAttribute('height',H);
  $('#chS').innerHTML=s;
  $('#chLegend').innerHTML=ID.map(i=>`<span><i style="background:var(--k${i})"></i>${ns?'Trạm '+i:bsN()+i}</span>`).join('')+(ns?'<span>Nét liền: NR. Nét đứt mảnh: LTE của cùng trạm.</span>':'')+'<span>Dải màu dưới đồ thị: cell đang phục vụ tại từng điểm (xám là không có). Chỗ đường cong tụt đột ngột là nơi tia sóng bị vật cản che.</span>';
  $('#evList').innerHTML=P.ev.length?P.ev.map((e,i)=>`<li><b>${String.fromCharCode(65+i)}</b><span>Tại ${f0(e.x)} m: ${e.t}.</span></li>`).join(''):`<li><span>${ns?'Không có sự kiện di động nào trên đường đi này. Thử hạ ngưỡng B1, tăng ngưỡng A2, đổi hướng đi hoặc khoảng cách trạm.':'Chưa có handover trên đường đi này: chưa lân cận nào mạnh hơn cell phục vụ quá mức offset cộng hysteresis.'}</span></li>`;
}
const kv=(a,b)=>`<dt>${a}</dt><dd>${b}</dd>`;
