  let top=1;for(const i of ID)if(M[i].r>M[top].r)top=i;
  const cur=sn||top,sv=M[cur];let bn=0;for(const i of ID)if(i!==cur&&(!bn||M[i].r>M[bn].r))bn=i;
  const sg=base+'|'+sn+'|'+sv.sec+'|'+sv.beam,svg=$('#sceneSvg');
  if(sg!==sigScene){sigScene=sg;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('width',W);svg.setAttribute('height',H);$('#scS').innerHTML=sceneStatic(E,W,H,px,py,k,m,sn,sv.sec,sv.beam);}
  const ux=px(wx),uy=py(wy);let d='';
