     +kv('SINR đường xuống',f1(sinr)+' dB')+kv('CQI và điều chế',ad.cqi?`CQI ${ad.cqi}: ${CQI[ad.cqi-1][0]}, tỉ lệ mã ${(CQI[ad.cqi-1][1]/1024).toFixed(2)}`:'Quá yếu để truyền')+kv('Số lớp MIMO',ad.cqi?ad.rank:'—')
     +'<div class="sep"></div>'+kv('Tốc độ xuống ước lượng',`<span style="color:var(--up)">${mb(dlNR)}</span>`)+kv('Tốc độ lên ước lượng',`${mb(ul.rate)} (${ul.prb} PRB)`)
