/* ---------- Mạng lõi ---------- */
const CINFO={
 nssf:()=>({t:'NSSF',d:'Chọn lát cắt mạng (network slice) cho UE và chỉ ra nhóm AMF phục vụ lát cắt đó.'}),
 nrf:()=>({t:'NRF',d:'Danh bạ của lõi 5G. Mỗi chức năng mạng đăng ký dịch vụ của mình ở đây, và hỏi NRF khi cần tìm chức năng khác, ví dụ AMF tìm SMF phù hợp với DNN và lát cắt.'}),
 ausf:()=>({t:'AUSF',d:'Máy chủ xác thực. Chạy thủ tục 5G-AKA cùng UDM, rồi trả kết quả và khoá neo cho AMF.'}),
 udm:()=>({t:'UDM (cùng UDR)',d:'Giữ dữ liệu thuê bao: hồ sơ, lát cắt và DNN được phép, tốc độ tối đa. Sinh vector xác thực và giải mã định danh ẩn SUCI thành SUPI. Thay cho HSS của 4G; mạng liên thông thường gộp HSS và UDM làm một.'}),
 pcf:()=>({t:'PCF',d:'Quyết định chính sách và QoS cho từng phiên. Khi IMS báo có cuộc gọi qua N5/Rx, PCF ra luật để SMF thêm QoS flow thoại 5QI 1. Thay cho PCRF của 4G.'}),
 amf:()=>({t:'AMF',d:'Cửa ngõ điều khiển của lõi 5G. Là điểm cuối của N1 (báo hiệu NAS với UE) và N2 (với gNB). Lo đăng ký, xác thực, theo dõi vị trí, paging và chọn SMF. Nối với MME qua N26 để UE chuyển qua lại giữa 5G và 4G.'}),
 smf:()=>({t:'SMF',d:'Quản lý phiên PDU: cấp địa chỉ IP, chọn UPF, cài luật chuyển tiếp qua N4, gửi tham số QoS cho gNB thông qua AMF. Khi liên thông với 4G, SMF kiêm luôn vai trò điều khiển của P-GW.'}),
 upf:()=>({t:'UPF',d:'Nút duy nhất của lõi 5G mà gói dữ liệu người dùng đi qua. Chuyển tiếp giữa gNB (N3) và mạng ngoài (N6), áp QoS, đếm lưu lượng, đệm gói khi UE đang rảnh. Có thể đặt sát người dùng để giảm trễ.'}),
 dn:()=>({t:'Internet',d:'Mạng dữ liệu của phiên internet thông thường ('+(nsa()?'APN':'DNN')+' internet).'}),
 ims:()=>({t:'IMS',d:'Hệ thống thoại trên nền IP, dùng chung cho VoLTE và VoNR. P-CSCF là điểm SIP đầu tiên UE chạm tới; S-CSCF giữ đăng ký và định tuyến cuộc gọi; TAS cung cấp dịch vụ thoại (chờ cuộc gọi, chuyển hướng…). Đi kèm còn có các nút xử lý media và nối sang mạng khác.'}),
 cgnb:()=>({t:'gNB',d:'Trạm gốc 5G. Về phía lõi, gNB chỉ cần hai giao diện: N2 tới AMF cho báo hiệu và N3 tới UPF cho dữ liệu.'}),
 cue:()=>({t:'UE',d:lte()?'Máy đăng ký với lõi EPC qua MME. Báo hiệu NAS đi trong suốt qua eNB; dữ liệu đi qua eNB tới S-GW rồi P-GW.':nsa()?'Máy NSA đăng ký với lõi 4G như một máy LTE, có bật bit DCNR để báo hỗ trợ NR.':'Máy SA đăng ký với AMF. Báo hiệu NAS (giao diện N1) đi trong suốt qua gNB và N2.'}),
 mmeiw:()=>({t:'MME của lõi 4G',d:'Đầu kia của N26. Mạng có vùng phủ 5G chưa kín cần N26 để UE xuống 4G mà không rớt phiên: EPS fallback cho thoại, handover hoặc chuyển hướng cho dữ liệu.'}),
 sbi:()=>({t:'Giao diện dịch vụ (SBI)',d:'Các chức năng điều khiển của lõi 5G không nối điểm–điểm như 4G mà gọi dịch vụ của nhau qua HTTP/2, kiểu như các microservice. Ví dụ AMF gọi dịch vụ của AUSF để xác thực, gọi SMF để lập phiên.'}),
 n2:()=>({t:'N2',d:'Báo hiệu NGAP giữa gNB và AMF. Bản tin NAS giữa UE và AMF (N1) cũng đi nhờ trên đường này.'}),
 n3:()=>({t:'N3',d:'Đường hầm GTP-U mang dữ liệu người dùng giữa gNB và UPF.'}),
 n4:()=>({t:'N4',d:'SMF điều khiển UPF bằng PFCP: luật phát hiện gói, chuyển tiếp, QoS, đếm lưu lượng.'}),
 n6:()=>({t:'N6',d:'UPF nối ra mạng dữ liệu bằng IP thông thường.'}),
 n6i:()=>({t:'N6 tới IMS',d:'Phiên PDU với DNN ims đưa báo hiệu SIP và gói thoại RTP của UE tới IMS.'}),
 n5:()=>({t:nsa()?'Rx':'N5 / Rx',d:'P-CSCF của IMS báo cho '+(nsa()?'PCRF':'PCF')+' biết cuộc gọi cần kênh thoại băng thông bao nhiêu. Đây là mắt xích nối tầng dịch vụ thoại với QoS của mạng truy nhập.'}),
 n26:()=>({t:'N26',d:'Giao diện giữa AMF và MME. Chuyển ngữ cảnh di động, bảo mật và phiên khi UE đi giữa 5G và 4G, nhờ đó giữ nguyên địa chỉ IP.'}),
 cuu:()=>({t:'Giao diện vô tuyến',d:'Xem các thẻ Phủ sóng và Khung để biết phần vô tuyến hoạt động thế nào.'}),
 chf:()=>({t:'CHF (tính cước hội tụ)',d:'Chức năng tính cước của lõi 5G, gộp cả online (trả trước, kiểm soát hạn mức theo thời gian thực) và offline (ghi bản ghi cước CDR cho trả sau). SMF mở một phiên tính cước cho mỗi phiên PDU qua N40: xin hạn mức, báo lượng đã dùng, đóng phiên. IMS và SMSC tính cước cuộc gọi và tin nhắn qua Ro. PCF hỏi CHF trạng thái gói cước qua N28 để hạ tốc độ khi hết dung lượng. Phía sau CHF là hệ thống quản lý tài khoản và billing.'}),
 smsf:()=>({t:'SMSF',d:'Chức năng SMS của lõi 5G, phục vụ SMS over NAS. AMF chuyển tin nhắn nhận từ UE cho SMSF qua N20; SMSF kiểm tra thuê bao ở UDM rồi chuyển tiếp tới SMSC bằng MAP hoặc Diameter SGd.'}),
 smsc:()=>({t:'SMSC',d:'Trung tâm tin nhắn: nhận tin từ người gửi, lưu lại, hỏi '+(nsa()?'HSS':'UDM')+' vị trí người nhận, chuyển phát, và thử lại khi máy nhận tắt hoặc ngoài vùng phủ. Tính cước từng tin qua hệ thống tính cước online. Tin đi vào SMSC theo hai đường: qua NAS ('+(nsa()?'từ MME, qua MSC bằng SGs hoặc trực tiếp bằng SGd':'từ SMSF')+'), hoặc qua IMS (máy chủ IP-SM-GW).'}),
 ocs:()=>({t:'OCS (tính cước online)',d:'Hệ thống tính cước thời gian thực cho thuê bao trả trước và kiểm soát hạn mức. P-GW xin hạn mức dữ liệu qua Gy; IMS xin hạn mức thời gian gọi qua Ro; SMSC trừ cước từng tin. Hết tiền thì OCS từ chối hoặc ra chỉ thị chuyển hướng tới trang nạp tiền. PCRF hỏi OCS trạng thái gói cước qua Sy. Song song, cước trả sau được ghi thành CDR ở hệ thống offline (CGF) rồi đưa sang billing.'}),
 ro:()=>({t:'Ro',d:'IMS (máy chủ thoại TAS) xin hạn mức thời gian gọi và báo thời lượng đã dùng bằng Diameter Credit-Control: CCR Initial khi bắt đầu, Update định kỳ, Terminate khi gác máy.'}),
 gy:()=>({t:'Gy',d:'P-GW xin hạn mức dữ liệu theo từng nhóm cước và báo số byte đã dùng bằng Diameter Credit-Control. OCS có thể chủ động yêu cầu cấp phép lại (RAR) khi thuê bao nạp tiền.'}),
 smsl:()=>({t:'MAP / SGd',d:'SMSF chuyển tin tới SMSC (MO-ForwardSM) và nhận tin đến từ SMSC (MT-ForwardSM) bằng MAP hoặc Diameter SGd.'}),
 ipsm:()=>({t:'IP-SM-GW tới SMSC',d:'Với SMS over IP, máy chủ IP-SM-GW của IMS lấy tin nhắn ra khỏi bản tin SIP MESSAGE và trao đổi với SMSC bằng MAP hoặc Diameter.'}),
 sgs:()=>({t:'MAP giữa MSC và SMSC',d:'Chặng thứ hai của SMS over SGs: MME đưa tin nhắn cho MSC qua SGs, MSC chuyển tiếp tới SMSC bằng MAP. Mạng đã tắt MSC thì MME nối thẳng SMSC bằng Diameter SGd.'}),
 msc:()=>({t:'MSC/VLR (lõi chuyển mạch kênh 3G)',d:'Tổng đài của mạng 3G/2G, gồm phần điều khiển (MSC Server) và cổng media (MGW). Xử lý cuộc gọi chuyển mạch kênh cho các trường hợp thoại không chạy được trên IMS: CSFB khi vùng chưa có '+(nsa()?'VoLTE':'VoNR lẫn VoLTE')+', và SRVCC khi cuộc gọi IMS đang chạy thì ra khỏi vùng LTE. MSC nối với MME qua SGs (đăng ký vị trí, paging, SMS) và Sv (SRVCC), với RNC qua Iu-CS, với IMS bằng SIP để nhận chuyển phiên, và với hệ thống tính cước bằng CAMEL cho thuê bao trả trước.'}),
 rnc:()=>({t:'NodeB và RNC (vô tuyến 3G)',d:'Mạng truy nhập 3G (UTRAN). NodeB là trạm phát; RNC điều khiển tài nguyên vô tuyến, lập kênh mang thoại theo yêu cầu của MSC, và sau cuộc gọi CSFB thì đưa UE quay về LTE. Vùng phủ 3G còn giữ lại chủ yếu để làm lưới đỡ cho thoại.'}),
 sgsv:()=>({t:'SGs và Sv',d:'SGs: MME đăng ký hộ UE với MSC, chuyển paging cuộc gọi đến và chở SMS, phục vụ CSFB. Sv: MME nhờ MSC tiếp nhận phần thoại của cuộc gọi VoLTE đang chạy, phục vụ SRVCC.'}),
 iucs:()=>({t:'Iu-CS',d:'Giao diện giữa RNC và MSC. Báo hiệu RANAP lập kênh mang thoại và chuyển giao; kênh thoại nối về cổng media của MSC.'}),
 mscims:()=>({t:'SIP giữa MSC và IMS',d:'Dùng cho SRVCC: MSC gọi vào số chuyển phiên (STN-SR) để IMS đổi đầu media của cuộc gọi sang MSC. Cuộc gọi vẫn do IMS điều khiển và tính cước.'}),
 uu3g:()=>({t:'Giao diện vô tuyến 3G',d:'UE chuyển sang WCDMA khi CSFB hoặc SRVCC. Trong lúc gọi trên 3G, dữ liệu chỉ còn tốc độ 3G.'}),
 hss:()=>({t:'HSS',d:'Cơ sở dữ liệu thuê bao của 4G: hồ sơ, khoá xác thực, APN được phép. Với NSA, HSS còn giữ cờ cho phép hay cấm thuê bao dùng NR và mức tốc độ tối đa mở rộng.'}),
 pcrf:()=>({t:'PCRF',d:'Quyết định chính sách và tính cước của 4G. Khi IMS báo có cuộc gọi qua Rx, PCRF yêu cầu P-GW tạo bearer riêng QCI 1 qua Gx.'}),
 mme:()=>({t:'MME',d:'Nút điều khiển của lõi 4G: xác thực, theo dõi vị trí, paging, lập bearer. Với NSA, MME đọc bit DCNR của UE, kiểm tra quyền dùng NR, và xử lý E-RAB Modification khi đường dữ liệu chuyển giữa eNB và gNB.'}),
 sgwc:()=>({t:'S-GW',d:'Điểm neo dữ liệu khi UE di chuyển giữa các trạm. Giữ đầu đường hầm S1-U phía lõi và đệm gói khi UE đang rảnh. Với NSA, S-GW đổi đường hầm sang gNB khi gNB phụ được thêm.'}),
 pgw:()=>({t:'P-GW',d:'Cấp địa chỉ IP cho UE, nối ra internet và IMS qua SGi, áp chính sách QoS và tính cước. Tạo bearer riêng cho thoại khi PCRF yêu cầu.'}),
 cenb:()=>({t:'eNB',d:'Trạm gốc 4G, giữ giao diện điều khiển S1-MME với lõi. Ở NSA đây là nút chủ.'}),
 cgnbn:()=>({t:'en-gNB',d:'Trạm 5G ở vai trò nút phụ. Chỉ có giao diện dữ liệu S1-U với S-GW (option 3x, 3a), không có giao diện điều khiển với MME.'}),
 s6a:()=>({t:'S6a',d:'MME lấy dữ liệu thuê bao và vector xác thực từ HSS bằng giao thức Diameter.'}),
 s11:()=>({t:'S11',d:'MME điều khiển S-GW bằng GTPv2-C: tạo phiên, tạo và sửa bearer.'}),
 s5:()=>({t:'S5',d:'Nối S-GW với P-GW, gồm phần điều khiển (GTP-C) và đường hầm dữ liệu (GTP-U).'}),
 gx:()=>({t:'Gx',d:'PCRF đẩy luật QoS và tính cước xuống P-GW.'}),
 sgi:()=>({t:'SGi',d:'P-GW nối ra mạng dữ liệu bên ngoài.'}),
 sgii:()=>({t:'SGi tới IMS',d:'Kết nối PDN với APN ims đưa báo hiệu SIP và gói thoại của UE tới IMS.'}),
 s1m:()=>({t:'S1-MME',d:'Báo hiệu S1AP giữa eNB và MME; bản tin NAS cũng đi nhờ trên đường này.'}),
 s1u:()=>({t:'S1-U',d:'Đường hầm GTP-U mang dữ liệu người dùng giữa S-GW và trạm gốc.'}),
 cx2:()=>({t:'X2',d:'Giao diện giữa eNB và gNB để thêm, đổi, gỡ nút phụ và chia dữ liệu của bearer tách.'})
};
const CORE_V={huawei:'Lõi của Huawei thường gồm UNC (gộp AMF, SMF và MME), UDG (UPF cùng mặt phẳng người dùng của S-GW/P-GW), UDM và UPCF (PCF/PCRF); tính cước dùng CBS (Convergent Billing System).',nokia:'Lõi của Nokia thường gồm CMM (Cloud Mobility Manager: AMF và MME), CMG (Cloud Mobile Gateway: SMF, UPF, S-GW, P-GW) và bộ SDM cho UDM/HSS; tính cước dùng Nokia Converged Charging.',ericsson:'Lõi dual-mode của Ericsson thường gồm PCC (Packet Core Controller: AMF, SMF, MME), PCG (Packet Core Gateway: UPF, S-GW, P-GW), CCSM/CCDM cho UDM/HSS và CCPC cho PCF; tính cước dùng Ericsson Charging.'};
function cnd(id,x,y,w,h,t,sub){
  return `<g class="nd${S.csel===id?' sel':''}" data-c="${id}" tabindex="0" role="button" aria-label="${t}"><rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="6"/><text class="nt" x="${x}" y="${sub?y-3:y+4}">${t}</text>${sub?`<text class="ns" x="${x}" y="${y+11}">${sub}</text>`:''}</g>`;
}
function cln(id,pts,label,lx,ly,cls=''){
  return `<g class="ln ${cls}${S.csel===id?' sel':''}" data-c="${id}" tabindex="0" role="button" aria-label="Giao diện ${label}"><polyline points="${poly(pts)}"/><polyline points="${poly(pts)}" style="stroke:transparent;stroke-width:16"/>${label?`<text class="lt" x="${lx}" y="${ly}">${label}</text>`:''}</g>`;
}
function coreSA(){
  let s='';const top=[['nssf',38,'NSSF'],['nrf',109,'NRF'],['ausf',180,'AUSF'],['udm',251,'UDM'],['pcf',322,'PCF']],row=[['amf',48,'AMF'],['smf',134,'SMF'],['chf',220,'CHF'],['smsf',306,'SMSF']];
  for(const [,x] of top)s+=`<line class="sq-life" x1="${x}" y1="58" x2="${x}" y2="84"/>`;
  for(const [,x] of row)s+=`<line class="sq-life" x1="${x}" y1="84" x2="${x}" y2="110"/>`;
  s+=cln('sbi',[[12,84],[340,84]],'SBI (HTTP/2)',177,100)+cln('n4',[[134,146],[134,210]],'N4',147,182)+cln('n6i',[[170,246],[246,310]],'N6',204,268)
   +cln('n6',[[156,246],[262,392]],'N6',222,346)+cln('n5',[[352,58],[352,298]],'N5 / Rx',337,238)+cln('n3',[[134,246],[134,312]],'N3',120,284)
   +cln('n2',[[62,146],[62,330],[92,330]],'N2',75,240)+cln('n26',[[28,146],[28,392]],'N26',28,284)+cln('cuu',[[140,348],[154,393]],'',0,0,'air')
   +cln('ro',[[258,298],[226,146]],'Ro',234,226)+cln('smsl',[[306,146],[306,183]],'',0,0)+cln('ipsm',[[306,217],[306,298]],'MAP',292,266)
   +cln('sgsv',[[56,428],[58,464]],'SGs, Sv',84,450)+cln('iucs',[[108,482],[146,482]],'Iu-CS',127,474)+cln('uu3g',[[166,427],[186,464]],'',0,0,'air')
   +cln('mscims',[[60,500],[60,516],[348,516],[348,346]],'SIP (SRVCC)',270,512);
  s+=flow([[154,393],[140,348],[92,330],[62,330],[62,146]],'fl-cp',4,3)+flow([[12,84],[340,84]],'fl-cp',5,3)+flow([[262,392],[156,246],[140,246],[140,312],[146,348],[158,393]],'fl-up',4,4);
  for(const [id,x,t] of top)s+=cnd(id,x,40,62,36,t);
  for(const [id,x,t] of row)s+=cnd(id,x,128,76,36,t);
  s+=cnd('upf',134,228,84,36,'UPF')+cnd('smsc',306,200,76,34,'SMSC')+cnd('ims',300,322,108,48,'IMS','P-CSCF, S-CSCF, TAS')+cnd('cgnb',134,330,84,36,'gNB')
   +cnd('cue',160,410,64,34,'UE')+cnd('mmeiw',56,410,100,36,'MME (lõi 4G)')+cnd('dn',300,404,76,32,'Internet')
   +cnd('msc',60,482,96,36,'MSC/VLR','lõi thoại 3G')+cnd('rnc',196,482,100,36,'NodeB + RNC','vô tuyến 3G');
  return `<svg viewBox="0 0 360 526" role="img" aria-label="Sơ đồ lõi 5G có tính cước, SMS và đường lùi về thoại 3G">${s}</svg>`;
}
function coreNSA(){
  const o=S.nsaOpt,L4=lte();let s='';
  s+=cln('s6a',[[62,58],[62,112]],'S6a',80,88)+cln('s11',[[108,130],[148,130]],'S11',128,122)+cln('s5',[[232,130],[258,130]],'S5',245,122)
   +cln('gx',[[300,58],[300,112]],'Gx',288,90)+cln('sgi',[[280,112],[222,58]],'SGi',240,96)+cln('sgii',[[300,148],[300,218]],'SGi',312,190)
   +cln('n5',[[340,40],[353,40],[353,242],[347,242]],'Rx',344,166)+cln('s1m',[[62,148],[62,312]],'S1-MME',62,236)
   +(L4?'':cln('s1u',[[190,148],[190,312]],'S1-U',190,246,o==='3'?'off':''))+cln('s1u',[[170,148],[90,312]],'S1-U',126,262,!L4&&o==='3x'?'off':'')
   +(L4?'':cln('cx2',[[108,330],[144,330]],'X2',126,322))+cln('cuu',[[80,348],[112,379]],'',0,0,'air')+(L4?'':cln('cuu',[[176,348],[140,379]],'',0,0,'air'))
   +cln('gy',[[280,148],[254,169]],'Gy',256,156)+cln('ro',[[262,218],[250,199]],'Ro',244,213)+cln('ipsm',[[296,266],[296,319]],'MAP',296,296)
   +cln('sgsv',[[16,130],[8,130],[8,532],[220,532],[220,508]],'SGs, Sv',110,528)+cln('sgs',[[268,490],[296,490],[296,353]],'MAP',296,424)
   +cln('iucs',[[130,490],[172,490]],'Iu-CS',151,482)+cln('uu3g',[[112,413],[92,472]],'',0,0,'air')+cln('mscims',[[244,472],[244,266]],'SIP (SRVCC)',244,384);
  s+=flow([[112,379],[80,348],[62,312],[62,148],[62,58]],'fl-cp',4.5,3);
  s+=(L4||o==='3')?flow([[222,58],[280,112],[232,130],[170,148],[90,312],[80,348],[112,379]],'fl-up',4.5,4):flow([[222,58],[280,112],[232,130],[190,148],[190,312],[176,348],[140,379]],'fl-up',4.5,4);
  s+=cnd('hss',62,40,92,36,'HSS')+cnd('dn',190,40,80,36,'Internet')+cnd('pcrf',300,40,80,36,'PCRF')+cnd('mme',62,130,92,36,'MME')+cnd('sgwc',190,130,84,36,'S-GW')
   +cnd('pgw',300,130,84,36,'P-GW')+cnd('ocs',234,184,64,30,'OCS')+cnd('ims',292,242,110,48,'IMS','P-CSCF, S-CSCF, TAS')+cnd('smsc',296,336,76,34,'SMSC')
   +cnd('cenb',62,330,92,36,'eNB')+(L4?'':cnd('cgnbn',190,330,92,36,'en-gNB'))+cnd('cue',126,396,72,34,'UE')
   +cnd('rnc',80,490,100,36,'NodeB + RNC','vô tuyến 3G')+cnd('msc',220,490,96,36,'MSC/VLR','lõi thoại 3G');
  return `<svg viewBox="0 0 360 544" role="img" aria-label="Sơ đồ lõi 4G dùng cho NSA, có tính cước, SMS và đường lùi về thoại 3G">${s}</svg>`;
}
let renderCore=function(){
  const n=nsa();
  $('#coreLead').textContent=lte()?'Lõi 4G (EPC) tách nút điều khiển MME khỏi các cổng dữ liệu S-GW và P-GW. Các nút nối với nhau từng cặp qua giao diện riêng. Thoại chạy qua IMS bằng VoLTE; nơi chưa có VoLTE thì MME phối hợp với MSC của mạng 3G qua SGs để làm CSFB.':n?'NSA dùng lại lõi 4G (EPC), chỉ nâng cấp để chịu tốc độ cao hơn và hiểu được NR. Các nút nối với nhau từng cặp qua giao diện riêng. Thoại chạy qua IMS bằng VoLTE.':'Lõi 5G (5GC) tách hẳn phần điều khiển và phần dữ liệu. Các chức năng điều khiển gọi dịch vụ của nhau qua một giao diện chung (SBI); gói dữ liệu của người dùng chỉ đi qua UPF. Thoại chạy qua IMS bằng VoNR.';
  $('#core').innerHTML=n?coreNSA():coreSA();
  const i=(CINFO[S.csel]||CINFO.cue)();
  let h=`<h2>${acrT(i.t)}</h2><p>${i.d}</p>`;
  if(S.vendor!=='3gpp')h+=`<p class="note"><b>${VN[S.vendor].n}:</b> ${CORE_V[S.vendor]} Tên sản phẩm có thể đổi theo thế hệ.</p>`;
  h+=kbHtml(S.csel);
  $('#coreInfo').innerHTML=h;
  const rows=n?[['Internet','APN internet','QCI 9 (hoặc 6, 8)','Không bảo đảm tốc độ',lte()?'LTE':'Bearer tách LTE + NR'],['Báo hiệu SIP','APN ims','QCI 5','Ưu tiên cao nhất, không bảo đảm tốc độ','Chỉ LTE'],['Thoại VoLTE','APN ims, bearer riêng','QCI 1','Tốc độ bảo đảm, trễ dưới 100 ms','Chỉ LTE'],['Gọi video','APN ims, bearer riêng','QCI 2','Tốc độ bảo đảm, trễ dưới 150 ms','Chỉ LTE']]
   :[['Internet','DNN internet','5QI 9 (hoặc 6, 8)','Không bảo đảm tốc độ','NR'],['Báo hiệu SIP','DNN ims','5QI 5','Ưu tiên cao nhất, không bảo đảm tốc độ','NR'],['Thoại VoNR','DNN ims, QoS flow riêng','5QI 1','Tốc độ bảo đảm, trễ dưới 100 ms','NR; nếu cell chưa bật VoNR thì EPS fallback'],['Gọi video','DNN ims, QoS flow riêng','5QI 2','Tốc độ bảo đảm, trễ dưới 150 ms','NR']];
  const vr=n?[['Có VoLTE','VoLTE: SIP qua IMS, thoại trên bearer QCI 1 của LTE','Khoảng 2 đến 3 giây'],['Chưa có VoLTE (mạng hoặc máy)','CSFB: rơi xuống 3G, gọi qua MSC, gác máy thì quay về LTE','Thêm 3 đến 6 giây'],['Đang gọi VoLTE, ra khỏi vùng LTE','SRVCC: chuyển cuộc gọi sang 3G, IMS vẫn điều khiển','Ngắt dưới 0,3 giây'],['Không có cả 3G','Cuộc gọi không thực hiện được hoặc rớt','']]
   :[['Cell NR có VoNR','VoNR: SIP qua IMS, thoại trên QoS flow 5QI 1 của NR','Khoảng 1,5 đến 2,5 giây'],['Cell NR chưa bật VoNR, LTE có VoLTE','EPS fallback: gNB đẩy UE sang LTE, gọi bằng VoLTE, xong quay về NR','Thêm 1 đến 2 giây'],['Mạng không có thoại IMS cho máy này','Máy tự tắt 5G SA, về LTE; gọi bằng CSFB xuống 3G','Thêm 3 đến 6 giây'],['Đang gọi VoNR, ra khỏi vùng NR','Handover sang LTE qua N26, cuộc gọi thành VoLTE','Ngắt vài chục mili giây'],['Tiếp tục ra khỏi vùng LTE','SRVCC sang 3G (hoặc 5G-SRVCC thẳng từ NR, ít mạng có)','Ngắt dưới 0,3 giây']];
  $('#voiceTable').innerHTML='<tr><th>Tình huống tại chỗ UE</th><th>Cuộc gọi chạy bằng</th><th>Thời gian thiết lập / gián đoạn</th></tr>'+vr.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('');
  const cr=n?[['Dữ liệu','P-GW đếm byte theo nhóm cước','Gy tới OCS','Initial khi lập kết nối PDN, Update khi chạm ngưỡng, Terminate khi xoá'],['Thoại VoLTE','IMS (TAS) đếm giây','Ro tới OCS','Initial khi INVITE, Update định kỳ, Terminate khi BYE'],['SMS','SMSC','Ro tới OCS','Event: trừ một lần cho mỗi tin'],['Thoại 3G (CSFB)','MSC đếm giây','CAMEL (CAP) tới OCS','InitialDP khi SETUP, ApplyCharging theo từng khoảng thời gian'],['Hạ tốc độ khi hết gói','OCS báo PCRF','Sy, rồi Gx','PCRF giảm APN-AMBR'],['Trả sau','S-GW, P-GW, IMS ghi CDR','Gz / Rf tới CGF','Không chặn theo thời gian thực; CDR đưa sang billing']]
   :[['Dữ liệu','UPF đếm byte, SMF tổng hợp','N40 tới CHF','Initial khi lập phiên PDU, Update khi chạm ngưỡng, Termination khi xoá'],['Thoại VoNR','IMS (TAS) đếm giây','Ro tới CHF/OCS','Initial khi INVITE, Update định kỳ, Terminate khi BYE'],['SMS','SMSC','Ro tới CHF/OCS','Event: trừ một lần cho mỗi tin'],['Thoại 3G (CSFB)','MSC đếm giây','CAMEL (CAP) tới OCS','InitialDP khi SETUP, ApplyCharging theo từng khoảng thời gian'],['Hạ tốc độ khi hết gói','CHF báo PCF','N28, rồi N7','PCF giảm Session-AMBR'],['Trả sau','SMF, IMS gửi thông tin cước','N40 (offline), Rf','CHF xuất CDR, đưa sang billing']];
  $('#chgTable').innerHTML='<tr><th>Dịch vụ</th><th>Ai đo</th><th>Báo qua</th><th>Khi nào</th></tr>'+cr.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('');
  $('#qosTable').innerHTML=`<tr><th>Dịch vụ</th><th>${n?'Kết nối PDN':'Phiên PDU'}</th><th>${n?'QCI':'5QI'}</th><th>Đặc tính</th><th>Chạy trên</th></tr>`+rows.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('');
};

/* ---------- Các phần khác của mạng lõi: thuê bao và xác thực, IMS, 3G ---------- */
Object.assign(CINFO,{
 sim:()=>({t:'SIM và máy',d:'SIM (USIM) giữ số thuê bao IMSI và khoá bí mật K, cùng thuật toán xác thực. Khoá K không bao giờ được đọc ra ngoài; SIM chỉ nhận thử thách và trả đáp án. Bản thân máy có số IMEI riêng, không phụ thuộc SIM. Mạng xác thực thuê bao bằng SIM và kiểm tra thiết bị bằng IMEI, là hai việc tách biệt.'}),
 hlr:()=>({t:'HLR và AuC',d:'HLR là cơ sở dữ liệu thuê bao của mạng 2G/3G: số IMSI, số điện thoại, các dịch vụ được dùng, cài đặt chuyển hướng và chặn gọi, và thuê bao đang ở MSC/VLR hay SGSN nào. AuC là trung tâm xác thực đi kèm, giữ khoá K của từng SIM và sinh vector xác thực. Mọi cuộc gọi đến và tin nhắn đến đều phải hỏi HLR để biết đường đi.'}),
 hssd:()=>({t:'HSS',d:'Cơ sở dữ liệu thuê bao của 4G và IMS, kế thừa HLR và gộp luôn AuC. Giữ hồ sơ gói (APN, QoS, tốc độ tối đa, quyền dùng NR), hồ sơ IMS (số công khai, tiêu chí lọc dịch vụ, S-CSCF đang phục vụ), khoá K, và MME đang giữ thuê bao. Mạng thật thường gộp HLR, HSS và UDM trên cùng một kho dữ liệu để một thuê bao chỉ có một hồ sơ.'}),
 ausfd:()=>({t:'AUSF',d:'Máy chủ xác thực của 5G. Nhận yêu cầu từ AMF, lấy vector từ UDM, và tự kiểm tra đáp án của UE, nhờ đó mạng nhà kiểm soát được việc xác thực kể cả khi thuê bao đang chuyển vùng. Sau khi xác thực xong, AUSF cấp khoá neo cho AMF.'}),
 udmd:()=>({t:'UDM',d:'Quản lý dữ liệu thuê bao của 5G. Gồm ba việc chính: giải mã định danh ẩn SUCI thành SUPI (chức năng SIDF); sinh vector xác thực từ khoá K (chức năng ARPF, vai trò của AuC); và cấp hồ sơ thuê bao cho AMF, SMF, SMSF. UDM cũng ghi AMF và SMF nào đang phục vụ thuê bao.'}),
 udr:()=>({t:'UDR',d:'Kho lưu dữ liệu phía sau UDM và PCF: hồ sơ thuê bao, khoá K (đã mã hoá), dữ liệu chính sách. UDM chỉ là lớp xử lý; dữ liệu thật nằm ở UDR. Nhờ tách như vậy, nhiều UDM có thể dùng chung một kho.'}),
 eird:()=>({t:'EIR (kiểm tra IMEI)',d:'Sổ đăng ký thiết bị. Khi máy vào mạng, nút phục vụ gửi số IMEI cho EIR để tra ba danh sách: trắng (cho phép), xám (cho dùng nhưng theo dõi), đen (máy bị báo mất, bị cấm hoặc IMEI giả). Một EIR dùng chung cho cả ba thế hệ: MSC và SGSN hỏi qua MAP (giao diện F, Gf), MME hỏi qua S13, AMF hỏi qua N17. Nhà mạng có thể đồng bộ danh sách đen với cơ sở dữ liệu IMEI quốc tế.'}),
 s_msc:()=>({t:'MSC/VLR và SGSN (3G)',d:'Nút phục vụ của 3G: MSC/VLR cho miền chuyển mạch kênh, SGSN cho miền gói. VLR giữ bản sao tạm hồ sơ thuê bao tải từ HLR trong lúc thuê bao ở vùng của mình. Cả hai tự so đáp án xác thực với vector HLR/AuC cấp.'}),
 s_mme:()=>({t:'MME (4G)',d:'Nút phục vụ của 4G. Xin vector từ HSS qua S6a, tự so đáp án của UE, lấy IMEI và hỏi EIR qua S13, rồi tải hồ sơ thuê bao bằng Update Location.'}),
 s_amf:()=>({t:'AMF (5G)',d:'Nút phục vụ của 5G. Nhờ AUSF xác thực (N12), lấy IMEI và hỏi EIR (N17), rồi đăng ký với UDM và tải hồ sơ (N8). Phần giữ khoá trong AMF gọi là SEAF.'}),
 s_cscf:()=>({t:'S-CSCF (IMS)',d:'Nút phục vụ của IMS. Xin vector xác thực IMS-AKA từ HSS qua Cx, so đáp án trong bản tin REGISTER, rồi tải hồ sơ dịch vụ IMS.'}),
 l_map:()=>({t:'MAP (giao diện D, Gr)',d:'VLR và SGSN dùng MAP để xin vector xác thực (Send Authentication Info), cập nhật vị trí (Update Location) và nhận hồ sơ (Insert Subscriber Data) từ HLR.'}),
 l_s6a:()=>({t:'S6a',d:'MME dùng Diameter để xin vector (AIR/AIA), cập nhật vị trí và nhận hồ sơ (ULR/ULA) từ HSS. HSS dùng nó để huỷ đăng ký ở MME cũ (CLR).'}),
 l_cx:()=>({t:'Cx',d:'S-CSCF và I-CSCF dùng Diameter để hỏi quyền đăng ký (UAR), xin vector (MAR), ghi nhận đăng ký và tải hồ sơ dịch vụ (SAR) từ HSS.'}),
 l_n12:()=>({t:'N12',d:'AMF gọi dịch vụ xác thực của AUSF.'}),
 l_n13:()=>({t:'N13',d:'AUSF xin vector xác thực từ UDM và báo lại kết quả xác thực.'}),
 l_n8:()=>({t:'N8',d:'AMF đăng ký với UDM (UECM) và tải, theo dõi hồ sơ thuê bao (SDM).'}),
 l_n35:()=>({t:'N35',d:'UDM đọc và ghi dữ liệu thuê bao ở UDR.'}),
 l_n17:()=>({t:'N17',d:'AMF hỏi EIR trạng thái của số máy (PEI).'}),
 l_s13:()=>({t:'S13',d:'MME hỏi EIR trạng thái của số máy IMEI bằng Diameter.'}),
 l_f:()=>({t:'Giao diện F và Gf',d:'MSC (qua F) và SGSN (qua Gf) hỏi EIR trạng thái của số máy IMEI bằng MAP Check IMEI.'}),
 l_comb:()=>({t:'HLR, HSS, UDM dùng chung dữ liệu',d:'Một thuê bao dùng cả 3G, 4G, 5G và IMS chỉ có một SIM và một khoá K. Vì vậy các mạng thật triển khai HLR, HSS và UDM như các giao diện khác nhau trên cùng một kho dữ liệu thuê bao.'}),
 pcscf:()=>({t:'P-CSCF (kèm ATCF, ATGW)',d:'Điểm SIP đầu tiên mà UE chạm tới. Giữ kênh IPsec với UE, nén và kiểm tra bản tin, và báo PCF/PCRF qua Rx hoặc N5 để mạng truy nhập dành kênh thoại. Thường chạy trên thiết bị biên (SBC) cùng ATCF và ATGW, hai chức năng neo báo hiệu và media để SRVCC chuyển cuộc gọi sang 3G nhanh.'}),
 icscf:()=>({t:'I-CSCF',d:'Cửa vào của mạng nhà. Khi có REGISTER hoặc cuộc gọi đến, I-CSCF hỏi HSS xem S-CSCF nào phục vụ thuê bao rồi chuyển tiếp. Nó che cấu trúc bên trong IMS với mạng ngoài.'}),
 scscf:()=>({t:'S-CSCF',d:'Trung tâm điều khiển phiên. Xác thực và giữ đăng ký của thuê bao, áp tiêu chí lọc (iFC) để đưa bản tin qua đúng máy chủ ứng dụng, và định tuyến cuộc gọi: tra ENUM, gửi sang mạng IMS khác hoặc ra mạng chuyển mạch kênh.'}),
 tas:()=>({t:'TAS (máy chủ thoại)',d:'Máy chủ ứng dụng thoại (MMTel). Thực hiện các dịch vụ bổ sung: chuyển hướng, chặn, chờ và giữ cuộc gọi, hội nghị, hiển thị số. Là nơi tính cước cuộc gọi qua Ro. Tải cấu hình dịch vụ của thuê bao từ HSS qua Sh.'}),
 as2:()=>({t:'SCC AS và IP-SM-GW',d:'Hai máy chủ ứng dụng khác nối với S-CSCF qua ISC. SCC AS neo mọi cuộc gọi để khi cần thì chuyển phiên sang 3G (SRVCC) và quyết định cuộc gọi đến đi qua IMS hay chuyển mạch kênh. IP-SM-GW chuyển đổi giữa SIP MESSAGE và SMSC cho SMS over IP.'}),
 mrf:()=>({t:'MRF',d:'Máy chủ media. Phát thông báo (ví dụ số không liên lạc được, sắp hết tiền), nhạc chờ, trộn tiếng cho cuộc gọi hội nghị, chuyển mã giữa các codec.'}),
 ibcf:()=>({t:'IBCF và BGCF',d:'IBCF là cửa biên sang mạng IMS của nhà mạng khác, kèm cổng media TrGW. BGCF quyết định cuộc gọi tới số không thuộc IMS sẽ ra mạng chuyển mạch kênh qua MGCF nào.'}),
 mgcf:()=>({t:'MGCF và IM-MGW',d:'Cầu nối giữa IMS và mạng chuyển mạch kênh (3G, điện thoại cố định). MGCF đổi báo hiệu SIP sang ISUP; IM-MGW đổi gói thoại RTP sang kênh thoại truyền thống.'}),
 ipcf:()=>({t:'PCF / PCRF',d:'Nhận thông tin luồng thoại từ P-CSCF và ra lệnh cho mạng truy nhập lập kênh thoại bảo đảm tốc độ (5QI 1 hoặc QCI 1).'}),
 igw:()=>({t:'UPF / P-GW',d:'Cổng dữ liệu của mạng truy nhập. IMS nhìn UE như một địa chỉ IP phía sau cổng này, không quan tâm UE đang ở 4G hay 5G.'}),
 iocs:()=>({t:'OCS / CHF',d:'Hệ thống tính cước online. TAS xin hạn mức thời gian gọi và báo thời lượng qua Ro.'}),
 ifar:()=>({t:'Mạng khác',d:'IMS của nhà mạng khác, hoặc mạng chuyển mạch kênh, nơi người bị gọi đang đăng ký.'}),
 l_gm:()=>({t:'Gm (qua mạng truy nhập)',d:'SIP giữa UE và P-CSCF. Đi như dữ liệu thường trong phiên IMS, qua trạm gốc và cổng dữ liệu.'}),
 l_mw:()=>({t:'Mw',d:'SIP giữa các CSCF với nhau.'}),
 l_isc:()=>({t:'ISC',d:'SIP giữa S-CSCF và các máy chủ ứng dụng.'}),
 l_sh:()=>({t:'Sh',d:'Máy chủ ứng dụng đọc và ghi dữ liệu dịch vụ của thuê bao ở HSS.'}),
 l_mr:()=>({t:'Mr',d:'S-CSCF hoặc TAS điều khiển MRF để phát thông báo hay trộn hội nghị.'}),
 l_mx:()=>({t:'Mx, Mi',d:'S-CSCF gửi cuộc gọi ra IBCF (sang mạng IMS khác) hoặc BGCF (ra mạng chuyển mạch kênh).'}),
 l_mj:()=>({t:'Mj',d:'BGCF chuyển cuộc gọi cho MGCF để đổi sang ISUP.'}),
 nodeb:()=>({t:'NodeB',d:'Trạm phát 3G. Chỉ lo lớp vật lý WCDMA: trải phổ, điều chế, điều khiển công suất nhanh. Khác eNB và gNB, NodeB không tự quyết định về kết nối; mọi điều khiển nằm ở RNC. Với HSPA, bộ lập lịch gói được đưa xuống NodeB.'}),
 rnc3:()=>({t:'RNC',d:'Bộ điều khiển vô tuyến, quản lý hàng trăm NodeB. Lo kết nối RRC, cấp mã và công suất, kiểm soát nhận vào, chuyển giao mềm (UE nối cùng lúc nhiều NodeB), mã hoá và bảo vệ toàn vẹn. Nối miền chuyển mạch kênh qua Iu-CS và miền gói qua Iu-PS. Ở 4G và 5G, các chức năng này đã chuyển xuống trạm gốc.'}),
 mscs:()=>({t:'MSC Server kèm VLR',d:'Phần điều khiển của tổng đài: xử lý báo hiệu cuộc gọi, quản lý di động miền chuyển mạch kênh, điều khiển MGW. VLR đi kèm giữ bản sao tạm hồ sơ của các thuê bao đang ở trong vùng, và cấp định danh tạm TMSI. Với mạng 4G/5G, MSC còn có SGs (CSFB, SMS) và Sv (SRVCC) nối sang MME.'}),
 mgw:()=>({t:'MGW (cổng media)',d:'Phần chuyển mạch tiếng của tổng đài, do MSC Server điều khiển bằng H.248. Nối kênh thoại từ RNC sang mạng khác, chuyển mã (ví dụ AMR sang G.711), phát âm báo, khử tiếng vọng.'}),
 gmsc:()=>({t:'GMSC (tổng đài cổng)',d:'Nơi cuộc gọi từ mạng khác đi vào. GMSC hỏi HLR thuê bao đang ở đâu, nhận số định tuyến tạm MSRN, rồi chuyển cuộc gọi tới MSC đang phục vụ.'}),
 sgsn:()=>({t:'SGSN',d:'Nút phục vụ của miền gói 3G: xác thực, quản lý di động, lập PDP context, và chuyển tiếp dữ liệu giữa RNC và GGSN. Vai trò tương đương MME cộng S-GW của 4G. Nối sang MME để chuyển phiên khi UE đi giữa 3G và 4G.'}),
 ggsn:()=>({t:'GGSN',d:'Cổng ra internet của miền gói 3G: cấp địa chỉ IP, áp chính sách, đếm lưu lượng và tính cước. Tương đương P-GW của 4G và UPF của 5G; mạng thật thường dùng một nút kết hợp GGSN và P-GW để giữ nguyên IP khi đổi mạng.'}),
 smsc3:()=>({t:'SMSC',d:'Trung tâm tin nhắn, nối MSC bằng MAP. Xem phần lõi gói để biết các đường SMS của 4G và 5G.'}),
 ocs3:()=>({t:'OCS và SCP',d:'Tính cước online. Với thoại chuyển mạch kênh, MSC hỏi qua CAMEL (SCP là điểm điều khiển dịch vụ của mạng thông minh). Với dữ liệu, GGSN hỏi qua Gy.'}),
 far3:()=>({t:'Mạng khác',d:'Mạng di động khác, mạng cố định, hoặc IMS (qua MGCF).'}),
 mme3:()=>({t:'MME (4G)',d:'Nối với SGSN để chuyển phiên dữ liệu giữa 3G và 4G, và với MSC qua SGs, Sv cho CSFB và SRVCC.'}),
 l_iub:()=>({t:'Iub',d:'Nối NodeB với RNC, mang cả điều khiển lẫn dữ liệu của mọi UE trong cell.'}),
 l_iucs:()=>({t:'Iu-CS',d:'Nối RNC với miền chuyển mạch kênh: báo hiệu RANAP tới MSC Server, kênh thoại tới MGW.'}),
 l_iups:()=>({t:'Iu-PS',d:'Nối RNC với SGSN: báo hiệu RANAP và đường hầm GTP-U cho dữ liệu.'}),
 l_mc:()=>({t:'Mc',d:'MSC Server điều khiển MGW bằng H.248.'}),
 l_nc:()=>({t:'Nc, ISUP',d:'Báo hiệu cuộc gọi giữa các tổng đài (ISUP, BICC hoặc SIP-I).'}),
 l_c:()=>({t:'Giao diện C',d:'GMSC hỏi HLR đường tới thuê bao (Send Routing Information).'}),
 l_d:()=>({t:'Giao diện D',d:'VLR trao đổi với HLR: xác thực, cập nhật vị trí, hồ sơ, xin số định tuyến MSRN.'}),
 l_gr:()=>({t:'Gr',d:'SGSN trao đổi với HLR: xác thực, cập nhật vị trí miền gói, hồ sơ APN.'}),
 l_gn:()=>({t:'Gn',d:'GTP giữa SGSN và GGSN.'}),
 l_gi:()=>({t:'Gi',d:'GGSN nối ra internet.'}),
 l_cap:()=>({t:'CAP (CAMEL)',d:'MSC hỏi hệ thống tính cước để kiểm soát cuộc gọi của thuê bao trả trước.'}),
 l_e:()=>({t:'MAP tới SMSC',d:'MSC chuyển tin nhắn đi và nhận tin nhắn đến với SMSC.'}),
 l_s3:()=>({t:'Giữa SGSN và MME',d:'Chuyển ngữ cảnh và phiên dữ liệu khi UE di chuyển giữa 3G và 4G (giao diện S3 hoặc Gn).'})
});
