const renderCorePkt=renderCore;
renderCore=function(){
  const v=S.coreView;
  $('#pktPanels').style.display=v==='pkt'?'':'none';$('#xPanel').style.display=v==='pkt'?'none':'';
  if(v==='pkt'){renderCorePkt();return;}
  $('#coreLead').textContent=v==='sub'?'Mỗi thế hệ mạng có nút phục vụ riêng, nhưng đều dựa vào cùng một nhóm khối để biết thuê bao là ai, có phải thật không, và máy có được phép dùng không. Sơ đồ này gom các khối đó lại.'
   :v==='ims'?'IMS là hệ thống điều khiển thoại và tin nhắn trên nền IP, dùng chung cho VoLTE và VoNR. Nó gồm ba loại khối: các CSCF định tuyến báo hiệu SIP, các máy chủ ứng dụng thực hiện dịch vụ, và các cổng nối ra mạng khác.'
   :'Mạng 3G có hai miền lõi tách biệt: chuyển mạch kênh cho thoại (MSC, MGW) và chuyển mạch gói cho dữ liệu (SGSN, GGSN), dùng chung vô tuyến (NodeB, RNC) và dữ liệu thuê bao (HLR). Với mạng 4G/5G, 3G là lưới đỡ cho thoại khi chưa có VoLTE hoặc VoNR.';
  $('#core').innerHTML=v==='sub'?coreSub():v==='ims'?coreIMS():coreG3();
  const i=(CINFO[S.csel]||CINFO.sim)();
  let h=`<h2>${acrT(i.t)}</h2><p>${i.d}</p>`;
  if(S.vendor!=='3gpp')h+=`<p class="note"><b>${VN[S.vendor].n}:</b> ${CORE_VX[v][S.vendor]} Tên sản phẩm có thể đổi theo thế hệ.</p>`;
  h+=kbHtml(S.csel);
  $('#coreInfo').innerHTML=h;
  const [title,head,rows]=XT[v];
  $('#xTitle').textContent=title;
  $('#xTable').innerHTML='<tr>'+head.map(c=>`<th>${c}</th>`).join('')+'</tr>'+rows.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('');
};
