  const sccp=(ssnA,ssnB,co)=>({n:'Signalling Connection Control Part (SCCP)',s:co?'Data Form 1 (DT1), kết nối đã lập':'Unitdata (UDT)',f:co?[['Message Type','Data Form 1 (0x06)'],['Destination Local Reference','0x00a1b2'],['Segmenting/reassembling','No more data']]
    :[['Message Type','Unitdata (0x09)'],['Protocol Class','0 (không kết nối)'],DG('Called Party address',['Routing Indicator','Route on GT'],['SubSystem Number',ssnB],['Global Title (E.164)',DGT[b]||'84900000200']),DG('Calling Party address',['SubSystem Number',ssnA],['Global Title (E.164)',DGT[a]||'84900000100'])]});
  const tcap=(kind,op,opn)=>({n:'Transaction Capabilities Application Part (TCAP)',s:`${kind}, ${opn}`,f:[['Message',kind],['Transaction ID',rev?'otid 0x2f00a1b3 / dtid 0x00003c41':'otid 0x00003c41'],DG('Dialogue portion',['application-context-name',X.l==='CAP'?'CAP-v2-gsmSSF-to-gsmSCF-AC':'ngữ cảnh MAP phiên bản 3 của thao tác này']),DG('Component portion',['Component',rev?'returnResultLast':'invoke'],['invokeID','1'],['opCode',`localValue ${op} (${opn})`])]});
  const nasWrap=()=>{const up=X.ka==='ue';return X.sa?[{n:'NR RRC (bọc ngoài, chặng UE ↔ gNB)',s:up?'ULInformationTransfer':'DLInformationTransfer',f:[['Kênh logic','DCCH trên SRB2 (SRB1 nếu chưa có SRB2)'],['Bản tin',up?'ULInformationTransfer':'DLInformationTransfer'],['dedicatedNAS-Message','(bản tin NAS bên dưới)']]},
      {n:'NGAP (bọc ngoài, chặng gNB ↔ AMF)',s:up?'UplinkNASTransport':'DownlinkNASTransport',f:[['procedureCode',up?'id-UplinkNASTransport (46)':'id-DownlinkNASTransport (4)'],['AMF-UE-NGAP-ID','4101'],['RAN-UE-NGAP-ID','1'],['NAS-PDU','(bản tin NAS bên dưới)']]}]
     :[{n:'LTE RRC (bọc ngoài, chặng UE ↔ eNB)',s:up?'ULInformationTransfer':'DLInformationTransfer',f:[['Kênh logic','DCCH trên SRB2'],['dedicatedInfoNAS','(bản tin NAS bên dưới)']]},
      {n:'S1AP (bọc ngoài, chặng eNB ↔ MME)',s:up?'UplinkNASTransport':'DownlinkNASTransport',f:[['procedureCode',up?'id-uplinkNASTransport (13)':'id-downlinkNASTransport (11)'],['MME-UE-S1AP-ID','5201'],['eNB-UE-S1AP-ID','1'],['NAS-PDU','(bản tin NAS bên dưới)']]}];};
  const l2=()=>[{n:'MAC',s:'DL-SCH / UL-SCH',f:[['RNTI','C-RNTI 0x4a21'],['LCID','1 (SRB1)'],['Length','theo kích thước RLC PDU']]},{n:'RLC (chế độ có xác nhận, AM)',s:'Data PDU',f:[['D/C','Data PDU'],['Polling bit','1'],['Segmentation Info','Complete SDU'],['Sequence Number','7']]},{n:'PDCP',s:'SRB, có bảo vệ toàn vẹn',f:[['Sequence Number','7'],['MAC-I','0x9c41e2b7']]}];
