function decodeStep(p,st){
  const X=decCtx(p,st),probe=st.l+' '+st.m;let r=null;
  for(const [re,fn] of DRULES)if(re.test(probe)){r=fn(X);if(r)break;}
  if(!r)r=[['Bản tin',st.m],['Thuê bao',X.im],['Ghi chú','Bản tin này chưa có mẫu giải mã chi tiết; các lớp bên dưới vẫn đúng với giao thức đang dùng.']];
  let pn=typeof DPROTO[st.l]==='function'?DPROTO[st.l]():(DPROTO[st.l]||st.l);
  if(st.l==='RRC'&&(/3G|Radio Bearer|RRC Connection Release/.test(st.m)||TPK==='G3'))pn='UTRAN Radio Resource Control (RRC, TS 25.331)';
  const parts=r.two?r.two.map((t,i)=>({name:t[0],f:t[1],rev:i===1})):[{name:st.m,f:r.f||r,pre:r.pre,rev:false}];
  return parts.map(q=>({name:q.name,src:q.rev?X.bn:X.an,dst:q.rev?X.an:X.bn,proto:st.l==='—'?'nội bộ':st.l,layers:[...decLower(X,q.rev),...(q.pre||[]),{n:pn,s:q.name,f:q.f,open:1}]}));
}
function decFields(f){return f.map(x=>Array.isArray(x)?`<div class="fd"><span class="fk">${esc(String(x[0]))}:</span> ${esc(String(x[1]))}</div>`:`<details class="fg" open><summary>${esc(x.n)}</summary>${decFields(x.f)}</details>`).join('');}
function renderDecode(p,st){
  const tl=sigTimeline(p),i=p.steps.indexOf(st),pk=decodeStep(p,st);
  $('#sigDec').innerHTML=pk.map((q,k)=>`<div class="pk"><div class="pk-h">Frame ${i+1}${pk.length>1?'.'+(k+1):''}: ${esc(q.name)}</div>
   <div class="pk-s"><span><b>Thời điểm</b> ${fmtT(tl[i].t+(k?tl[i].dt/2:0))}</span><span><b>Nguồn</b> ${esc(q.src)}</span><span><b>Đích</b> ${esc(q.dst)}</span><span><b>Giao thức</b> ${esc(q.proto)}</span></div>
   ${q.layers.map(L=>`<details class="ly"${L.open?' open':''}><summary>${esc(L.n)}${L.s?`<span class="ly-s">, ${esc(L.s)}</span>`:''}</summary><div class="fl">${decFields(L.f)}</div></details>`).join('')}</div>`).join('')
   +'<p class="note" style="margin:8px 0 0">Chạm vào từng lớp để mở hoặc đóng, như ô chi tiết gói của máy phân tích giao thức. Tên trường theo chuẩn 3GPP; giá trị là số minh hoạ khớp với thuê bao và cấu hình đang mô phỏng, không phải bản ghi từ mạng thật.</p>';
}
