  $('#prbLteTitle').textContent=`PRB 4G ${dir} (${ch} của LTE): ${R.nL} PRB, cấp theo nhóm ${R.PL} PRB, mỗi cột là một khung con 1 ms`;
  prbGrid('#prbNr',R,'nr');prbGrid('#prbLte',R,'lte');
