  $('#prbNrLeg').innerHTML=leg+(E.tdd?`<span><i style="background:var(--g-gp)"></i>${ul?'Khe đường xuống và khe đặc biệt':'Khe đường lên'}</span>`:'');$('#prbLteLeg').innerHTML=leg;
  const usedN=ul?R.prbSlotsNU/Math.max(1,R.ulSlots*R.usN)*100:R.prbSlotsN/(R.dlSlots*R.nN)*100,usedL=ul?R.prbSlotsLU/(R.MS*R.usL)*100:R.prbSlotsL/(R.MS*R.nL)*100;
