   +(r.why?kv('Vì sao ở trạng thái này',r.why):'')
   +'<div class="sep"></div>'+kv('Khối số của khối vô tuyến',f0(r.parts.dig)+' W')+kv('Các nhánh thu phát',f0(r.parts.trx)+' W')+kv('Bộ khuếch đại lúc chờ',f0(r.parts.pa)+' W')+kv('Bộ khuếch đại khi phát',f0(r.parts.rf)+' W')+kv('Băng gốc, nguồn và phần khác',f0(r.parts.oth)+' W')
   +'<div class="sep"></div>'+kv('Số nhánh phát đang bật',`${r.n} trên ${esT()}`)+(r.n?kv('Phần ký hiệu có phát',pct(r.act)):'')+(r.exp>1.01?kv('Trải PRB và lùi công suất',`PRB dùng tăng ${f1(r.exp)} lần, thành ${pct(r.prb)}`):'')
   +kv('Dung lượng cell còn lại',r.cap?pct(r.cap):'0 (UE sang lớp phủ)')+kv('Tốc độ đỉnh người dùng',r.peak>=1?'Không đổi':'còn khoảng '+pct(r.peak))+kv('Độ lợi chùm dữ liệu',r.bf?`giảm khoảng ${r.bf} dB`:r.n?'Không đổi':'—')
   +kv('Trễ thêm do giữ gói',r.lat?`tối đa ${r.lat} ms`:'Không')+(r.n===0?kv('Tải PRB của lớp phủ',pct(Math.min(1.5,r.lteLoad))+(r.lteOver?', quá tải':'')):'')+kv('Thời gian đánh thức',r.wake||'Không cần')
   +(D1.aes&&c.mute?'<div class="sep"></div>'+kv('Ngưỡng PRB do Automated Energy Saver tự chỉnh',`tắt dưới ${D1.aes.dn} %, bật trên ${D1.aes.up} %`)+kv(`Tốc độ mà ${esPar(v,'aR')} % số UE đạt được`,r.n?`khoảng ${f0(D1.aes.rate(r.L,r.st==='mute'))} Mbit/s`:'—'):'');
  const overs=D1.hs.filter(x=>x.over).map(x=>x.h),lo=D1.hs.filter(x=>x.lteOver).map(x=>x.h);
  $('#esWarn').innerHTML=(overs.length?`<p class="warn">Lúc ${overs.join(', ')} giờ, tải vượt dung lượng còn lại sau khi tắt bớt nhánh nên cell bị nghẽn. Hạ ngưỡng tắt nhánh hoặc thu hẹp khung giờ.</p>`:'')
   +(lo.length?`<p class="warn">Lúc ${lo.join(', ')} giờ, lớp phủ không gánh nổi tải dồn sang trong khi cell này vẫn tắt.${v==='nokia'&&!c.coord?' Bật Coordinated 4G-5G power saving ở mức 2 để eNB gọi cell NR dậy.':v==='huawei'&&c.deep?' Ngủ sâu theo lịch không tự thoát theo tải; thu hẹp khung giờ.':''}</p>`:'')
   +(!overs.length&&!lo.length&&r.n===0?`<p class="note" style="margin:10px 0 0">Cell này đang tắt nên toàn bộ ${pct(r.L)} tải được lớp phủ gánh; phần điện tăng thêm ở lớp phủ đã được tính vào con số trên.</p>`:'');
