   +kv(`Mỗi năm cho ${S.esSites} cell`,`${f0(yr*S.esSites/1000)} MWh, khoảng ${vnd(yr*S.esSites*S.esPrice)}`)
   +'<div class="sep"></div>'+kv('Số giờ cell bị tắt hẳn',D1.hs.filter(x=>x.n===0).length+' giờ')+kv('Số giờ chạy thiếu nhánh phát',D1.hs.filter(x=>x.st==='mute').length+' giờ')+kv('Số giờ bị nghẽn',(overs.length+lo.length)+' giờ')+kv('Trễ thêm lớn nhất',Math.max(...D1.hs.map(x=>x.lat))?Math.max(...D1.hs.map(x=>x.lat))+' ms':'Không');
  /* so với tài liệu */
  $('#esCmp').innerHTML='<tr><th>Tính năng</th><th>Mô hình, bật riêng</th><th>Kết quả trong tài liệu</th></tr>'+F.filter(f=>f.eff!=='coord').map(f=>{const o=E.one[f.id];return `<tr><td>${f.t}</td><td>${f1(o.sv/D0.e*100)} %${o.dep?`<br><span class="note">${V.stack?'thêm vào các tính năng phía trên':'thêm vào tính năng nền'}</span>`:''}</td><td>${f.trial||'Không có: đây là bộ tính năng tổng quát.'}</td></tr>`;}).join('')
   +(V.combo?V.combo.map(t=>`<tr><td>Kết hợp</td><td>${f1(sav/D0.e*100)} %<br><span class="note">với các tính năng đang bật</span></td><td>${t}</td></tr>`).join(''):'');
  $('#esCmpNote').textContent=v==='3gpp'?'':'Cột mô hình tính cho một cell với loại anten, công suất và đường tải đang đặt; cột tài liệu là số đo trên mạng thật, có loại thiết bị và mức tải khác, nên hai cột chỉ để so xu hướng. Thử đổi mức tải sang Thấp để gần với mạng 5G mới triển khai.'+(v==='nokia'?' Tài liệu Nokia thử lần lượt, tính năng sau chạy trên nền các tính năng trước, nên cột mô hình cũng tính cộng dồn theo thứ tự đó.':'')+(v==='huawei'?' Trong tài liệu, hai tính năng đầu được thử trên LTE và hai tính năng sau trên NR.':'');
