/* ---------- Trình chạy chung cho mọi thẻ: tự động hoặc từng bước ---------- */
/* mỗi thẻ khai: n() số bước, idx() bước hiện tại suy từ trạng thái, set(i, chiều) đặt trạng thái cho bước i, cap() mô tả bước, hold thời gian giữ mỗi bước (ms) */
const ARCHSEQ={SA:['ue','uu','ru','fh','du','f1c','cucp','ngc','amf','n11','smf','n4','upf','ngu','cuup','e1','f1u','n6','dn','xn','gnb2'],
 NSA:['ue','lteuu','lteru','cpri','enb','s1mme','mme','s11','sgw','sgi','dn','x2','gnb','s1ug','s1ue','fh','nrru','nruu']};
const CORESEQ={SA:['cue','cuu','cgnb','n2','amf','sbi','nrf','ausf','udm','nssf','pcf','smf','chf','n4','upf','n3','n6','dn','n6i','ims','n5','ro','smsf','smsl','smsc','ipsm','n26','mmeiw','sgsv','msc','iucs','rnc','uu3g','mscims'],
 NSA:['cue','cuu','cenb','s1m','mme','s6a','hss','s11','sgwc','s1u','cgnbn','cx2','s5','pgw','gx','pcrf','gy','ocs','sgi','dn','sgii','ims','n5','ro','ipsm','smsc','sgs','msc','sgsv','iucs','rnc','uu3g','mscims']};
ARCHSEQ.LTE=['ue','lteuu','lteru','cpri','enb','s1mme','mme','s6a','hss','s11','sgw','s5','pgw','gx','pcrf','sgi','dn','s1ue','x2','enb2'];CORESEQ.LTE=CORESEQ.NSA;
const STACKSEQ=['ip','nas','rrc','sdap','pdcp','rlc','mac','hphy','lphy'];
const VSEQ=['3gpp','huawei','nokia','ericsson'];
function stackSeq(){const dom=[...new Set($$('#stack [data-layer]').map(e=>e.dataset.layer))];const q=STACKSEQ.filter(k=>dom.includes(k));return q.length?q:STACKSEQ;}
function coreSeq(){
  const dom=[...new Set($$('#core .nd').map(e=>e.dataset.c).concat($$('#core .ln').map(e=>e.dataset.c)))];
  if(S.coreView!=='pkt')return dom;
  const cur=CORESEQ[S.mode].filter(k=>dom.includes(k));return cur.concat(dom.filter(k=>!cur.includes(k)));
}
const frameN=()=>lte()?10:isTDD()?(S.tdd.length<=5?S.tdd.length*2:S.tdd.length):10;
const prbCols=()=>PRB?(S.psel.rat==='nr'?(S.pdir==='ul'?PRB.gridNU:PRB.gridN):(S.pdir==='ul'?PRB.gridLU:PRB.gridL)):[];
const beamPos=()=>{const n=Math.max(2,Math.min(bCfg().ssb,16)),w=120/n;return Array.from({length:n},(_,i)=>Math.round(-60+w*(i+0.5)));};
const first=s=>{const i=s.indexOf('. ');return i>0?s.slice(0,i+1):s;};
const TOUR={
 arch:{hold:2400,n:()=>ARCHSEQ[S.mode].length,idx:()=>Math.max(0,ARCHSEQ[S.mode].indexOf(S.sel)),set:i=>{S.sel=ARCHSEQ[S.mode][i];},
  cap:()=>{const q=ARCHSEQ[S.mode],i=q.indexOf(S.sel),t=infoOf(S.sel);return (i<0?'':'Đi theo đường của một kết nối, từ máy lên lõi rồi ra mạng dữ liệu. ')+`Đang xem: ${t.t}. ${first(t.d)}`+(i>=0&&i<q.length-1?` Kế tiếp: ${infoOf(q[i+1]).t}.`:'');}},
 core:{hold:2400,n:()=>coreSeq().length,idx:()=>Math.max(0,coreSeq().indexOf(S.csel)),set:i=>{S.csel=coreSeq()[i];},
  cap:()=>{const q=coreSeq(),i=q.indexOf(S.csel),t=(CINFO[S.csel]||CINFO.cue)();return `Đang xem: ${t.t}. ${first(t.d)}`+(i>=0&&i<q.length-1?` Kế tiếp: ${(CINFO[q[i+1]]||CINFO.cue)().t}.`:'');}},
 radio:{hold:190,light:()=>{renderRadio();syncUx();},n:()=>61,idx:()=>Math.round(S.ux/routeLen()*60),set:i=>{S.ux=i/60*routeLen();},
  cap:()=>{if(!PATH)return'';const P=PATH,k=clamp(Math.round(S.ux/P.step),0,P.n-1),L4=lte(),sn=L4?P.lte[k]:P.nr[k],E=env(),[x,y]=uePos(),pass=P.ev.filter(e=>e.x<=S.ux),nx=P.ev.find(e=>e.x>S.ux);
   const r=sn?f0((L4?lteRsrp(sn,x,y):nrRsrp(sn,x,y,E)).r)+' dBm':'';
   return `UE đã đi ${f0(S.ux)} m trên ${f0(P.L)} m từ ${bsN()}1 về phía ${destName()}. `+(sn?`Đang được ${bsN()}${sn} phục vụ, ${r}. `:'Chưa có NR, chỉ chạy LTE. ')+(pass.length?`Vừa xảy ra tại ${f0(pass[pass.length-1].x)} m: ${first(pass[pass.length-1].t+'. ')}`:'Chưa có sự kiện di động nào. ')+(nx?` Sự kiện kế tiếp ở ${f0(nx.x)} m.`:'');}},
 frame:{hold:1300,n:frameN,idx:()=>clamp(S.slot,0,frameN()-1),set:i=>{S.slot=i;},
  cap:()=>{if(lte())return `Khung con ${S.slot}: vùng điều khiển ${S.pdcch} ký hiệu đầu, tín hiệu tham chiếu CRS rải khắp băng, phần còn lại là PDSCH.`+(S.slot===0?' Khung con này có PSS, SSS và PBCH (mang MIB) ở 6 PRB giữa băng.':S.slot===5?' Khung con này có PSS và SSS lần thứ hai trong khung.':' Không có tín hiệu đồng bộ.');
   const t=slotType(S.slot),[d,g,u]=SSFS[S.ssf],ss=ssbPlan().used.filter(p=>p.slot===S.slot).map(p=>p.idx);
   return `Khe ${S.slot}, `+(t==='D'?'khe đường xuống: PDCCH ở đầu khe báo cấp phát, phần còn lại là PDSCH mang dữ liệu, xen DMRS để ước lượng kênh.':t==='U'?'khe đường lên: UE phát PUSCH, hai mép băng là PUCCH.':`khe đặc biệt: ${d} ký hiệu xuống, ${g} ký hiệu bảo vệ để trạm chuyển từ phát sang thu, ${u} ký hiệu lên.`)+(ss.length?` Khe này có khối SSB số ${ss.join(' và ')}, mỗi khối phát trên một chùm.`:' Khe này không có SSB.');}},
 prb:{hold:1000,n:()=>prbCols().length||1,idx:()=>clamp(S.psel.slot,0,Math.max(0,prbCols().length-1)),
  set:(i,dir)=>{const g=prbCols();while(g[i]&&!g[i].own&&g[i+(dir||1)])i+=dir||1;S.psel={rat:S.psel.rat,slot:clamp(i,0,g.length-1)};},
  cap:()=>{const g=prbCols(),r=g[clamp(S.psel.slot,0,g.length-1)];if(!r)return'';const nr=S.psel.rat==='nr',ks=Object.keys(r.per);
   return `${nr?'Khe NR':'Khung con LTE'} số ${S.psel.slot}, ${S.pdir==='ul'?'đường lên':'đường xuống'}: `+(!r.own?'không có cấp phát theo chiều này.':ks.length?ks.map(k=>`UE${+k+1} được ${r.per[k].prb} PRB`).join(', ')+'. Bộ lập lịch chia lại ở mỗi khe theo kênh và dữ liệu chờ của từng UE.':'không UE nào có dữ liệu chờ.')+' Chạm một cột ở lưới 4G để chạy trên lưới đó.';}},
 ca:{hold:520,n:()=>31,idx:()=>Math.round((S.caD-50)/(S.caDmax-50)*30),set:i=>{S.caD=Math.round((50+i*(S.caDmax-50)/30)/10)*10;},
  cap:()=>{const s=caState(S.caD),on=s.cc.filter(e=>e.on);return `UE cách trạm ${f0(S.caD)} m. `+(s.alive?`Đang ghép ${on.map(e=>e.c.band).join(' + ')} (${s.bwOn} MHz), tốc độ xuống ${f0(s.dl)} Mbit/s.`:'PCell đã mất phủ nên không còn kết nối.')+(s.cc.some(e=>!e.on)&&s.alive?` Đã rơi: ${s.cc.filter(e=>!e.on).map(e=>e.c.band).join(', ')} vì RSRP dưới ${S.caThr} dBm.`:'');}},
 beam:{hold:1500,light:()=>{renderScene();},n:()=>16,idx:()=>clamp(S.bSlot,0,15),set:i=>{S.bSlot=i;},
  cap:()=>($('#antCap')?$('#antCap').textContent:'')+' Mỗi bước là một lượt lập lịch; các UE đi bộ nên chùm bám theo.'},
 es:{hold:950,light:()=>{renderEs(true);},n:()=>24,idx:()=>S.esHour,set:i=>{S.esHour=i;},
  cap:()=>{const E=esCalc(),r=E.D1.hs[S.esHour],r0=E.D0.hs[S.esHour];return `${S.esHour} giờ: tải ${f0(r.L*100)} %, ${r.state.toLowerCase()}, tiêu thụ ${f0(r.P)} W so với ${f0(r0.P)} W khi không tiết kiệm.`+(r.why?` Lý do: ${r.why}.`:'')+(r.over||r.lteOver?' Giờ này bị nghẽn.':r.wake?` Muốn bật lại cần ${r.wake}.`:'');}},
 stack:{hold:2400,n:()=>stackSeq().length,idx:()=>Math.max(0,stackSeq().indexOf(S.layer)),set:i=>{S.layer=stackSeq()[i];},
  cap:()=>{const q=stackSeq(),L=layOf(S.layer),i=q.indexOf(S.layer);return `Đi từ lớp trên cùng xuống tới anten. Đang xem: ${L.t}. ${first(L.d())}`+(i>=0&&i<q.length-1?` Kế tiếp: ${layOf(q[i+1]).t}.`:'');}},
 vendor:{hold:2600,n:()=>VSEQ.length,idx:()=>Math.max(0,VSEQ.indexOf(S.vendor)),set:i=>{S.vendor=VSEQ[i];},
  cap:()=>S.vendor==='3gpp'?'Đang xem cấu hình theo tên chuẩn 3GPP. Chạy tiếp để xem cùng cấu hình đó viết theo cú pháp của Huawei, Nokia, Ericsson.':`Đang xem cấu hình mẫu và tên tham số theo ${VN[S.vendor].n}; cột của vendor này được tô đậm trong các bảng.`}
};
const TP={on:false,timer:null};
function tourStop(){if(TP.timer){clearTimeout(TP.timer);TP.timer=null;}const was=TP.on;TP.on=false;return was;}
function tourGo(i,dir){
  const t=TOUR[S.tab];if(!t)return;i=clamp(i,0,t.n()-1);t.set(i,dir);
  if(t.light){t.light();tourUi();}else renderAll();
}
function tourSchedule(){
  const t=TOUR[S.tab];TP.timer=setTimeout(()=>{if(!TP.on||!TOUR[S.tab])return;const i=t.idx();if(i>=t.n()-1){tourStop();tourUi();return;}tourGo(i+1,1);if(t.idx()>=t.n()-1){tourStop();tourUi();}else tourSchedule();},t.hold/S.sgSpeed);
}
function tourAct(a){
  const t=TOUR[S.tab];if(!t)return;
  if(a==='play'){if(TP.on){tourStop();tourUi();return;}if(t.idx()>=t.n()-1)tourGo(0,1);TP.on=true;tourUi();tourSchedule();return;}
  tourStop();tourGo(a==='first'?0:t.idx()+(a==='next'?1:-1),a==='prev'?-1:1);
}
function tourUi(){
  const t=TOUR[S.tab],box=$(`[data-player="${S.tab}"]`);if(!t||!box)return;
  const n=t.n(),i=clamp(t.idx(),0,n-1);
  box.querySelector('[data-tour="play"]').textContent=TP.on?'Tạm dừng':i>=n-1?'Chạy lại từ đầu':'Chạy tự động';
  box.querySelector('[data-tour="prev"]').disabled=i<=0;box.querySelector('[data-tour="first"]').disabled=i<=0;box.querySelector('[data-tour="next"]').disabled=i>=n-1;
  box.querySelector('.pbar').style.width=((i+1)/n*100).toFixed(1)+'%';
  box.querySelector('.pcap').innerHTML=`<span class="note">Bước ${i+1} trên ${n}.</span> ${t.cap()}`;
  const sp=box.querySelector('select');if(sp)sp.value=String(S.sgSpeed);
}
function tourInit(){
  for(const tab in TOUR){const sec=$('#t-'+tab),lead=sec&&sec.querySelector('.lead');if(!sec)continue;
    const d=document.createElement('div');d.className='panel player';d.dataset.player=tab;
    d.innerHTML=`<div class="row" style="margin-top:0"><button class="btn pri" type="button" data-tour="play">Chạy tự động</button><button class="btn" type="button" data-tour="next">Tiến một bước</button><button class="btn" type="button" data-tour="prev">Lùi một bước</button><button class="btn" type="button" data-tour="first">Về đầu</button><label class="pspd">Tốc độ <select data-k="sgSpeed" aria-label="Tốc độ chạy tự động"><option value="0.5">Chậm</option><option value="1">Vừa</option><option value="2">Nhanh</option></select></label></div><div class="prog"><div class="pbar"></div></div><p class="pcap" aria-live="polite"></p>`;
    if(lead)lead.after(d);else sec.prepend(d);}
}
