const SSBC={A4:['Case A, 15 kHz, đến 3 GHz',15,[2,8],[0,1]],A8:['Case A, 15 kHz, 3 đến 6 GHz',15,[2,8],[0,1,2,3]],B4:['Case B, 30 kHz, đến 3 GHz',30,[4,8,16,20],[0]],B8:['Case B, 30 kHz, 3 đến 6 GHz',30,[4,8,16,20],[0,1]],C4:['Case C, 30 kHz, đến 3 GHz',30,[2,8],[0,1]],C8:['Case C, 30 kHz, 3 đến 6 GHz',30,[2,8],[0,1,2,3]],D:['Case D, 120 kHz, FR2',120,[4,8,16,20],[0,1,2,3,5,6,7,8,10,11,12,13,15,16,17,18]],E:['Case E, 240 kHz, FR2',240,[8,12,16,20,32,36,40,44],[0,1,2,3,5,6,7,8]]};
Object.assign(C,{bSsbPci:{l:'PCI của cell',r:[0,1007,1],f:v=>`${v} = 3 × ${Math.floor(v/3)} + ${v%3}`},bSsbCase:{l:'Mẫu vị trí SSB',o:()=>Object.entries(SSBC).map(([k,v])=>[k,v[0]])}});
function pssSeq(n2){const x=[0,1,1,0,1,1,1];for(let i=0;i<120;i++)x.push((x[i+4]+x[i])%2);return Array.from({length:127},(_,n)=>1-2*x[(n+43*n2)%127]);}
function sssSeq(n1,n2){const x0=[1,0,0,0,0,0,0],x1=[1,0,0,0,0,0,0];for(let i=0;i<120;i++){x0.push((x0[i+4]+x0[i])%2);x1.push((x1[i+1]+x1[i])%2);}const m0=15*Math.floor(n1/112)+5*n2,m1=n1%112;return Array.from({length:127},(_,n)=>(1-2*x0[(n+m0)%127])*(1-2*x1[(n+m1)%127]));}
BK.ssb={t:'Khối SSB: quét búp, PSS, SSS, PBCH và sắp xếp phần tử tài nguyên',ch:'Chương 11 và 12',ctl:['bSsbPci','bSsbCase'],n:()=>5,r(i){
  const pci=S.bSsbPci,n1=Math.floor(pci/3),n2=pci%3,v=pci%4,cs=SSBC[S.bSsbCase],scs=cs[1];let s='',out='';
  const st=['Trạm phát một loạt SSB trong nửa khung 5 ms, mỗi khối trên một chùm khác hướng. UE quét tần số theo mành đồng bộ.','UE tương quan tín hiệu thu với ba chuỗi PSS: tìm được mốc thời gian của ký hiệu và N_ID(2).','Biết vị trí PSS, UE đọc SSS cách đó hai ký hiệu và dò trong 336 chuỗi: ra N_ID(1), tức ra PCI.','PCI cho biết vị trí DMRS của PBCH (dịch PCI chia 4 dư mấy). Chuỗi DMRS mang 3 bit thấp của chỉ số SSB, nên UE biết đang nghe chùm nào.','UE giải mã PBCH: MIB cho số khung, khoảng cách sóng mang con, k_SSB, và cấu hình CORESET 0 để đọc tiếp SIB1.'];
  if(i===0){
    const pos=[];for(const n of cs[3])for(const a of cs[2])pos.push(a+(scs===15||(scs===30&&cs[2].length===2)?14:scs===240?56:28)*n);const tsym=1/(14*scs/15),X=t=>20+t/5*320,cols=[V_('u1'),V_('u2'),V_('u3'),V_('u4'),V_('u5'),V_('u6'),V_('lte'),V_('cp')];
    s+=bx(20,60,320,40,'',{f:V_('panel2'),c:V_('line')});for(let m=0;m<=5;m++)s+=li([[X(m),100],[X(m),106]])+tx(X(m),118,m+' ms',{fs:9});
    pos.forEach((p,k)=>{s+=`<rect x="${X(p*tsym)}" y="62" width="${Math.max(1.6,X(4*tsym)-X(0))}" height="36" style="fill:${cols[k%8]}"/>`;});
    const L=pos.length,W=8;for(let k=0;k<Math.min(L,8);k++){const a=(-52+k*104/(Math.min(L,8)-1||1))*Math.PI/180;s+=`<path d="M180 220 L${180+70*Math.sin(a-0.09)} ${220-70*Math.cos(a-0.09)} Q${180+82*Math.sin(a)} ${220-82*Math.cos(a)} ${180+70*Math.sin(a+0.09)} ${220-70*Math.cos(a+0.09)}Z" style="fill:${cols[k%8]};opacity:.8"/>`;}
    s+=tx(180,50,`${L} vị trí SSB trong nửa khung 5 ms`,{b:1,c:V_('ink')})+tx(180,236,L>8?`Mỗi SSB một chùm; hình vẽ 8 trong ${L} chùm`:'Mỗi SSB một chùm, cùng màu với khối ở trên',{fs:9.5});
    out=kv('Mẫu',cs[0])+kv('Số SSB tối đa trong một loạt (L)',L)+kv('Ký hiệu bắt đầu của các SSB',pos.slice(0,8).join(', ')+(L>8?', …':''))+kv('Độ dài một SSB',`4 ký hiệu = ${(4*tsym*1000).toFixed(0)} µs`)+kv('Cả loạt kéo dài',`${((pos[L-1]+4)*tsym).toFixed(2)} ms`)+kv('Chu kỳ lặp lại loạt SSB','5 đến 160 ms; UE mới bật máy giả định 20 ms');
  }else if(i===1||i===2){
    const sq=i===1?pssSeq(n2):sssSeq(n1,n2),w=320/127;sq.forEach((d,k)=>{s+=`<rect x="${20+k*w}" y="${d>0?40:70}" width="${w-0.4}" height="30" style="fill:${i===1?V_('g-ssb'):V_('g-srs')}"/>`;});
    s+=li([[20,70],[340,70]],{c:V_('ink')})+tx(180,30,`${i===1?'PSS':'SSS'}: 127 phần tử, mỗi phần tử là +1 hoặc −1`,{b:1,c:V_('ink')});
    if(i===1){const me=pssSeq(n2);[0,1,2].forEach(c=>{const r=pssSeq(c).reduce((a,d,k)=>a+d*me[k],0),h=Math.abs(r)/127*70;s+=`<rect x="${70+c*90}" y="${210-h}" width="46" height="${Math.max(2,h)}" style="fill:${c===n2?V_('nr'):V_('muted')}"/>`+tx(93+c*90,224,`chuỗi ${c}`,{fs:9.5})+tx(93+c*90,206-h,r,{b:1,c:V_('ink')});});s+=tx(180,128,'Tương quan với ba chuỗi PSS ứng viên',{fs:10});}
    else{const me=sssSeq(n1,n2),cand=[n1,(n1+1)%336,(n1+57)%336,(n1+200)%336];cand.forEach((c,q)=>{const r=sssSeq(c,n2).reduce((a,d,k)=>a+d*me[k],0),h=Math.abs(r)/127*70;s+=`<rect x="${40+q*76}" y="${210-h}" width="46" height="${Math.max(2,h)}" style="fill:${q===0?V_('nr'):V_('muted')}"/>`+tx(63+q*76,224,`N1 = ${c}`,{fs:9.5})+tx(63+q*76,206-h,r,{b:1,c:V_('ink')});});s+=tx(180,128,'Tương quan với chuỗi đúng và ba chuỗi SSS khác',{fs:10});}
    out=i===1?kv('N_ID(2) tìm được',n2)+kv('Cách tạo chuỗi','chuỗi m dài 127, dịch vòng 43 × N_ID(2)')+kv('Vị trí','ký hiệu 0 của SSB, sóng mang con 56 đến 182')+kv('Số chuỗi phải thử','3'):kv('N_ID(1) tìm được',n1)+kv('PCI',`3 × ${n1} + ${n2} = ${pci}`)+kv('Cách tạo chuỗi','tích hai chuỗi m, dịch theo N_ID(1) và N_ID(2)')+kv('Vị trí','ký hiệu 2 của SSB, sóng mang con 56 đến 182')+kv('Số chuỗi phải thử','336');
  }else{
    const col={pss:V_('g-ssb'),sss:V_('g-srs'),pbch:V_('g-pucch'),dm:V_('ink'),no:V_('panel2')},ty=(sy,k)=>sy===0?(k>=56&&k<=182?'pss':'no'):sy===2?(k>=56&&k<=182?'sss':k<=47||k>=192?(k%4===v?'dm':'pbch'):'no'):(k%4===v?'dm':'pbch');
    for(let sy=0;sy<4;sy++){s+=tx(60+sy*44,14,'ký hiệu '+sy,{fs:9});let a=0,p=ty(sy,0);for(let k=1;k<=240;k++){const t=k<240?ty(sy,k):null;if(t!==p){s+=`<rect x="${40+sy*44}" y="${20+(240-k)*0.8}" width="40" height="${(k-a)*0.8}" style="fill:${col[p]}"/>`;a=k;p=t;}}}
    s+=tx(30,24,'239',{a:'end',fs:8})+tx(30,212,'0',{a:'end',fs:8})+tx(14,116,'240 sóng mang con = 20 PRB',{fs:8.5}).replace('<text ','<text transform="rotate(-90 14 116)" ');
    s+=tx(290,30,'Một PRB của PBCH',{fs:9,b:1});for(let k=0;k<12;k++)s+=`<rect x="262" y="${40+(11-k)*13}" width="56" height="12" style="fill:${k%4===v?col.dm:col.pbch}"/>`+tx(254,50+(11-k)*13,k,{a:'end',fs:8.5});
    s+=tx(290,206,`DMRS ở sóng mang con ${[0,1,2].map(q=>v+4*q).join(', ')}`,{fs:9});
    s+=[['pss','PSS'],['sss','SSS'],['pbch','PBCH'],['dm','DMRS']].map((q,k)=>`<rect x="${20+k*84}" y="228" width="10" height="10" style="fill:${col[q[0]]}"/>`+tx(34+k*84,237,q[1],{a:'start',fs:9.5})).join('');
    out=i===3?kv('Dịch vị trí DMRS (PCI chia 4 dư)',v)+kv('Số phần tử DMRS','144, cứ 4 sóng mang con có 1')+kv('DMRS mang thêm','3 bit thấp của chỉ số SSB (và bit nửa khung khi L = 4)')+kv('Số chuỗi DMRS UE phải thử','8')
     :kv('Số phần tử tài nguyên của PBCH','432 (576 trừ 144 DMRS)')+kv('Tải tin','32 bit: MIB 24 bit (kể cả bit loại bản tin) và 8 bit thời gian')+kv('Mã hoá','thêm CRC 24 bit, mã Polar ra 864 bit, điều chế QPSK')+kv('8 bit thời gian','4 bit thấp của số khung, bit nửa khung, 3 bit cao của chỉ số SSB hoặc k_SSB')+kv('Chu kỳ nội dung MIB','80 ms; phát lại ở mọi SSB');
  }
  return{fig:svgw(360,244,s,'Khối SSB'),cap:st[i],out,info:`<h3>Năm bước tìm cell</h3>${stepsHtml(st,i)}<p>Khối SSB chiếm 4 ký hiệu và 240 sóng mang con (20 PRB). Ba thành phần nằm cố định: PSS ở ký hiệu 0, SSS ở ký hiệu 2 (đều ở 127 sóng mang con giữa), PBCH phủ ký hiệu 1 và 3, cộng 48 sóng mang con mỗi bên của ký hiệu 2. Kéo thanh PCI để thấy chuỗi và vị trí DMRS thay đổi.</p>`,
   tblT:i===0?'Các mẫu vị trí SSB':'',tbl:i===0?tbl(['Mẫu','SCS','Ký hiệu đầu (trong mỗi cụm)','Số SSB tối đa'],Object.values(SSBC).map(c=>[c[0],c[1]+' kHz',c[2].join(', '),c[2].length*c[3].length]),Object.keys(SSBC).indexOf(S.bSsbCase)):''};
}};
/* ===== Chương 13: truy nhập ngẫu nhiên ===== */
const RAF={'0':['839','1.25 kHz','1 ms','14.5 km'],'1':['839','1.25 kHz','3 ms','100 km'],'2':['839','1.25 kHz','3.5 ms','22 km'],'3':['839','5 kHz','1 ms','14.5 km'],A1:['139','theo SCS','2 ký hiệu','0.9 km'],A2:['139','theo SCS','4 ký hiệu','2.1 km'],A3:['139','theo SCS','6 ký hiệu','3.5 km'],B1:['139','theo SCS','2 ký hiệu','0.5 km'],B4:['139','theo SCS','12 ký hiệu','3.9 km'],C0:['139','theo SCS','1 ký hiệu','5.3 km'],C2:['139','theo SCS','4 ký hiệu','9.2 km']};
Object.assign(C,{bRaType:{l:'Kiểu truy nhập ngẫu nhiên',o:()=>[['cb','4 bước, có tranh chấp (CBRA)'],['cf','Không tranh chấp (CFRA), dùng khi chuyển giao'],['s2','2 bước (MsgA, MsgB)']]},bRaFmt:{l:'Định dạng tiền tố',o:()=>Object.keys(RAF).map(k=>[k,`Định dạng ${k}: dài ${RAF[k][0]}, bán kính tối đa ${RAF[k][3]}`])},bRaD:{l:'Khoảng cách UE tới trạm',r:[50,5000,50],f:v=>v+' m'},bRaTgt:{l:'preambleReceivedTargetPower',r:[-120,-90,2],f:v=>v+' dBm'},bRaStep:{l:'powerRampingStep',num:1,o:()=>[0,2,4,6].map(v=>[v,v+' dB'])},bRaMax:{l:'preambleTransMax',num:1,o:()=>[3,4,5,6,7,8,10,20].map(v=>[v,v+' lần'])},bRaX:{l:'Suy hao thêm mà UE không lường được',r:[0,24,1],f:v=>v+' dB'},bRaN:{l:'Số UE cùng truy nhập trong một cơ hội RACH',r:[1,40,1],f:v=>v+' UE'}});
BK.rach={t:'Truy nhập ngẫu nhiên: các kiểu, tiền tố, tài nguyên RACH và tăng bậc công suất',ch:'Chương 13',ctl:['bRaType','bRaFmt','bRaD','bRaTgt','bRaStep','bRaMax','bRaX','bRaN'],n:()=>S.bRaType==='cb'?5:3,r(i){
  const E=env(),ty=S.bRaType,pl=pathloss(S.scen,S.los,E.fG,S.bRaD,S.hbs,1.5),pmax=S.uePw,att=[];let ok=0;
  for(let k=1;k<=S.bRaMax;k++){const want=S.bRaTgt+pl+(k-1)*S.bRaStep,tx_=Math.min(pmax,want),rx=tx_-pl-S.bRaX;att.push({k,tx:tx_,rx,cap:want>pmax,hit:rx>=S.bRaTgt});if(rx>=S.bRaTgt){ok=k;break;}}
  const M={cb:[['Chọn SSB mạnh nhất và cơ hội RACH gắn với nó',0],['Msg1: tiền tố trên PRACH',1],['Msg2: Random Access Response (RAR)',-1],['Msg3: bản tin đầu trên PUSCH, kèm định danh UE',1],['Msg4: giải quyết tranh chấp',-1]],cf:[['Gán tiền tố: gNB gán sẵn tiền tố riêng trong lệnh chuyển giao',-1],['Msg1: tiền tố riêng trên PRACH',1],['Msg2: RAR, xong',-1]],s2:[['Chọn SSB và cơ hội RACH',0],['MsgA: tiền tố và dữ liệu PUSCH gửi cùng lúc',1],['MsgB: RAR và giải quyết tranh chấp gộp lại',-1]]}[ty];
  let s=bx(10,14,54,24,'UE')+bx(100,14,54,24,'gNB')+li([[37,38],[37,196]])+li([[127,38],[127,196]]);
  M.forEach((m,k)=>{const y=56+k*32,on=k<=i,c=k===i?V_('warn'):on?V_('cp'):V_('line');if(m[1]===0)s+=bx(14,y-10,46,20,'',{c,w:k===i?2.4:1,f:'none'});else s+=li(m[1]>0?[[37,y],[127,y]]:[[127,y],[37,y]],{c,w:k===i?2.6:1.6})+`<path d="M${m[1]>0?127:37} ${y} l${m[1]>0?-7:7} -4 v8z" style="fill:${c}"/>`;s+=tx(82,y-5,m[1]===0?'':m[0].split(':')[0],{fs:8.5,c:k===i?V_('ink'):V_('muted'),b:k===i})+(m[1]===0?tx(37,y+3,'chọn',{fs:8}):'');});
  /* đồ thị tăng bậc công suất */
  const x0=176,W=174,lo=Math.min(S.bRaTgt-S.bRaX-6,-130),hi=pmax+4,Y=v=>24+(hi-v)/(hi-lo)*150,bw=Math.min(18,W/att.length-2);
  s+=li([[x0,Y(pmax)],[x0+W,Y(pmax)]],{c:V_('muted'),d:'4 3'})+tx(x0+W,Y(pmax)-3,`công suất tối đa ${pmax} dBm`,{a:'end',fs:8.5})+li([[x0,Y(S.bRaTgt)],[x0+W,Y(S.bRaTgt)]],{c:V_('nr'),d:'4 3'})+tx(x0+W,Y(S.bRaTgt)-3,`gNB cần ${S.bRaTgt} dBm`,{a:'end',fs:8.5,c:V_('nr')});
  att.forEach((a,k)=>{const x=x0+4+k*(W/att.length);s+=`<rect x="${x}" y="${Y(a.tx)}" width="${bw/2}" height="${Y(lo)-Y(a.tx)}" style="fill:${V_('up')};opacity:.8"/><rect x="${x+bw/2}" y="${Y(a.rx)}" width="${bw/2}" height="${Y(lo)-Y(a.rx)}" style="fill:${a.hit?V_('nr'):V_('warn')}"/>`+tx(x+bw/2,188,a.k,{fs:8.5});});
  s+=tx(x0+W/2-6,202,'Từng lần phát: UE phát và gNB thu',{fs:8.5});
  const pc=1-(63/64)**(S.bRaN-1),f=RAF[S.bRaFmt],L=+f[0],dfra=L===839?(S.bRaFmt==='3'?5000:1250):S.scs*1000,ncs=Math.ceil((2*Math.max(S.bRaD,300)/3e8+3e-6)*L*dfra),per=Math.max(1,Math.floor(L/Math.max(ncs,1))),roots=Math.ceil(64/per);
  const txt=ok?`Lần ${ok} thì gNB nghe thấy: UE đã tăng ${(ok-1)*S.bRaStep} dB, phát ${f1(att[ok-1].tx)} dBm.`:`Sau ${S.bRaMax} lần vẫn không tới: ${att[att.length-1].cap?'UE đã phát hết công suất, tức là ngoài vùng phủ đường lên':'bước tăng quá nhỏ so với suy hao thêm'}. UE báo lỗi truy nhập ngẫu nhiên.`;
  return{fig:svgw(360,210,s,'Truy nhập ngẫu nhiên'),cap:`${M[i][0]}. ${M[i][1]===1&&i<=1?txt:''}`,
   out:kv('Suy hao đường truyền UE ước lượng',f1(pl)+' dB')+kv('Công suất lần phát đầu',f1(att[0].tx)+' dBm'+(att[0].cap?' (đã chạm trần)':''))+kv('Kết quả',txt)+kv('Thời gian truy nhập ước tính',ok?`${(ok-1)*20+(ty==='cb'?40:ty==='s2'?15:20)} ms`:'thất bại')
    +'<div class="sep"></div>'+kv('Xác suất đụng tiền tố với UE khác',ty==='cf'?'0 (tiền tố được gán riêng)':f1(pc*100)+' %')+kv('Định dạng tiền tố',`${S.bRaFmt}: chuỗi Zadoff-Chu dài ${f[0]}, kéo dài ${f[2]}`)+kv('Bán kính cell tối đa của định dạng',f[3]+(L===139?' (ở 15 kHz; SCS gấp đôi thì giảm một nửa)':''))+kv('Dịch vòng N_CS cần cho khoảng cách này',`${ncs}: mỗi chuỗi gốc cho ${per} tiền tố, cần ${roots} chuỗi gốc để đủ 64`),
   info:`<h3>${{cb:'Bốn bước, có tranh chấp',cf:'Không tranh chấp',s2:'Hai bước'}[ty]}</h3>${stepsHtml(M.map(m=>m[0]),i)}<p><b>Tăng bậc công suất:</b> công suất phát tiền tố = min(công suất tối đa, mức đích ở gNB + suy hao ước lượng + (số lần − 1) × bước tăng). UE ước lượng suy hao từ RSRP của SSB, nhưng không biết hết (cơ thể che, nhiễu đường lên), nên lần đầu có thể không tới. Mỗi lần không nhận được RAR trong cửa sổ chờ, UE tăng thêm một bước và thử lại, tối đa preambleTransMax lần.</p><p><b>Tiền tố</b> là chuỗi Zadoff-Chu; 64 tiền tố của một cell được tạo bằng cách dịch vòng một chuỗi gốc, hết thì lấy chuỗi gốc kế tiếp. Cell càng rộng thì bước dịch N_CS càng phải lớn, nên càng tốn chuỗi gốc. <b>Tài nguyên RACH:</b> mỗi SSB được gắn với một hoặc vài cơ hội RACH (RO); UE chọn RO theo chùm nó nghe rõ nhất, nhờ đó gNB biết phải trả lời trên chùm nào.</p><p class="note">Bán kính tối đa của từng định dạng là giá trị gần đúng. Thủ tục đầy đủ với các bản tin trước và sau có ở thẻ Báo hiệu.</p>`,
   tblT:'Các định dạng tiền tố',tbl:tbl(['Định dạng','Độ dài chuỗi','SCS của PRACH','Thời lượng','Bán kính tối đa'],Object.entries(RAF).map(([k,v])=>[k,...v]),Object.keys(RAF).indexOf(S.bRaFmt))};
}};
/* ===== Chương 14: PDCCH ===== */
Object.assign(C,{bCoRb:{l:'Bề rộng CORESET',num:1,o:()=>[24,48,96].map(v=>[v,v+' PRB'])},bCoSym:{l:'Số ký hiệu của CORESET',r:[1,3,1],f:v=>v+' ký hiệu'},bAl:{l:'Mức tổ hợp (aggregation level)',num:1,o:()=>[1,2,4,8,16].map(v=>[v,`AL ${v}: ${v} CCE`])}});
BK.pdcch={t:'PDCCH: CORESET, CCE, không gian tìm kiếm và DCI',ch:'Chương 14',ctl:['bCoRb','bCoSym','bAl'],n:()=>10,r(i){
  const ncce=Math.floor(S.bCoRb*S.bCoSym/6),L=S.bAl,Mc={1:6,2:6,4:4,8:2,16:1},M=Math.min(Mc[L],Math.floor(ncce/L));let Y=0x4A21;for(let k=0;k<=i;k++)Y=(39827*Y)%65537;
  const cand=[];for(let m=0;m<M;m++)cand.push(L*((Y+Math.floor(m*ncce/(L*M)))%Math.floor(ncce/L)));
  const per=16,cw=20,chh=16;let s='';const used=cand[i%Math.max(M,1)];
  for(let c=0;c<ncce;c++){const x=18+(c%per)*cw,y=24+Math.floor(c/per)*(chh+3),ci=cand.findIndex(a=>c>=a&&c<a+L),u=M&&c>=used&&c<used+L;s+=`<rect x="${x}" y="${y}" width="${cw-2}" height="${chh}" rx="2" style="fill:${u?V_('g-pdcch'):ci>=0?V_('cp'):V_('panel2')};opacity:${u?1:ci>=0?0.45:1};stroke:${V_('line')}"/>`+(c%4===0?tx(x+cw/2-1,y+11,c,{fs:7.5,c:u?V_('panel'):V_('muted')}):'');}
  const hgt=24+Math.ceil(ncce/per)*(chh+3)+26;s+=tx(180,14,`CORESET: ${S.bCoRb} PRB × ${S.bCoSym} ký hiệu = ${ncce} CCE`,{b:1,c:V_('ink')})+tx(180,hgt-6,'Mờ: các ứng viên UE phải thử. Đậm: ứng viên gNB chọn để gửi DCI.',{fs:9});
  const bits=84,rate=bits/(L*108),req=10*log10(2**(2*rate/0.6)-1),sinr=+simCtx().sinr,best=[1,2,4,8,16].find(a=>10*log10(2**(2*bits/(a*108)/0.6)-1)<=sinr-1)||16;
  return{fig:svgw(360,hgt,s,'Lưới CCE của CORESET'),cap:`Khe ${i}: UE thử ${M} ứng viên AL ${L}, bắt đầu ở CCE ${cand.join(', ')}; vị trí đổi theo từng khe vì phụ thuộc RNTI và số khe.`,
   out:kv('REG (1 PRB × 1 ký hiệu)',S.bCoRb*S.bCoSym)+kv('CCE (6 REG)',ncce)+kv('Phần tử tài nguyên của một CCE','72: 54 cho DCI, 18 cho DMRS')+kv(`Số ứng viên ở AL ${L}`,M)+kv('Số UE lập lịch được trong một khe ở AL này',Math.floor(ncce/L))
    +'<div class="sep"></div>'+kv('Tỉ lệ mã của DCI khoảng 60 bit kèm CRC',rate.toFixed(2)+(rate>0.9?' (quá cao, không giải được)':''))+kv('SINR cần',f1(req)+' dB')+kv('SINR của UE ở thẻ Phủ sóng',f1(sinr)+' dB')+kv('Mức tổ hợp nên dùng cho UE này','AL '+best),
   info:`<p><b>CORESET</b> là vùng thời gian và tần số dành cho PDCCH: rộng bội số của 6 PRB, dài 1 đến 3 ký hiệu, và khác LTE ở chỗ không cần trải hết băng. Nó được chia thành <b>REG</b> (1 PRB trong 1 ký hiệu), 6 REG thành 1 <b>CCE</b>. Một PDCCH dùng 1, 2, 4, 8 hoặc 16 CCE: UE ở xa cần mức tổ hợp cao để tỉ lệ mã thấp.</p><p><b>Không gian tìm kiếm</b> là tập ứng viên mà UE phải giải thử (giải mù) ở mỗi khe. Không gian chung (cho SIB, tìm gọi, RAR) dùng AL 4, 8, 16; không gian riêng của UE có vị trí băm theo C-RNTI để các UE ít đụng nhau. Số lần giải mù tối đa mỗi khe là 44, 36, 22, 20 ứng với SCS 15, 30, 60, 120 kHz. UE nhận ra DCI của mình nhờ CRC được trộn với RNTI.</p>`,
   tblT:'Các định dạng DCI',tbl:tbl(['Định dạng','Dùng để'],[['0_0','Cấp phát PUSCH, dạng rút gọn (dự phòng)'],['0_1','Cấp phát PUSCH đầy đủ: MIMO, BWP, CSI'],['1_0','Cấp phát PDSCH rút gọn: SIB, tìm gọi, RAR, dự phòng'],['1_1','Cấp phát PDSCH đầy đủ'],['2_0','Báo định dạng khe (SFI) cho nhóm UE'],['2_1','Báo vùng bị chiếm trước (pre-emption)'],['2_2','Lệnh điều khiển công suất cho PUCCH, PUSCH'],['2_3','Lệnh điều khiển công suất cho SRS']])};
}};
/* ===== Chương 15: ấn định tài nguyên miền thời gian, lập lịch động, định thời ACK ===== */
Object.assign(C,{bTdMap:{l:'Kiểu sắp xếp PDSCH',o:()=>[['A','Kiểu A: theo khe, DMRS ở ký hiệu 2 hoặc 3'],['B','Kiểu B: khe ngắn, DMRS ở ký hiệu đầu của cấp phát']]},bTdS:{l:'Ký hiệu bắt đầu S',r:[0,12,1],f:v=>String(v)},bTdL:{l:'Số ký hiệu L',r:[2,14,1],f:v=>String(v)},bTdK0:{l:'K0: từ DCI tới PDSCH',r:[0,3,1],f:v=>v+' khe'},bTdK1:{l:'K1: từ PDSCH tới ACK/NACK trên PUCCH',r:[0,8,1],f:v=>v+' khe'},bTdK2:{l:'K2: từ DCI tới PUSCH',r:[0,8,1],f:v=>v+' khe'}});
BK.tdra={t:'Ấn định tài nguyên PDSCH, PUSCH; lập lịch động và định thời ACK/NACK',ch:'Chương 15',ctl:['bTdMap','bTdS','bTdL','bTdK0','bTdK1','bTdK2'],n:()=>4,r(i){
  const A=S.bTdMap==='A',Sx=S.bTdS,L=Math.min(S.bTdL,14-Sx),okA=Sx<=3&&L>=3,okB=[2,4,7].includes(L),valid=A?okA:okB,sliv=L-1<=7?14*(L-1)+Sx:14*(14-L+1)+(13-Sx);
  const n=12,sw=320/n,ns=0,sP=ns+S.bTdK0,sA=sP+S.bTdK1,sU=ns+S.bTdK2,tA=slotType(sA),tU=slotType(sU),tP=slotType(sP),ackOk=tA==='U'||(tA==='S'&&SSFS[S.ssf][2]>0),puOk=tU==='U',pdOk=tP!=='U';let s='';
  for(let k=0;k<n;k++){const t=slotType(k),x=20+k*sw;s+=`<rect x="${x}" y="30" width="${sw-2}" height="26" style="fill:${t==='D'?V_('g-pdsch'):t==='U'?V_('g-pusch'):V_('g-gp')}"/>`+tx(x+sw/2-1,47,t,{c:V_('ink'),b:1})+tx(x+sw/2-1,68,k,{fs:9});}
  const mk=(sl,lab,c,y,on)=>sl<n?li([[20+sl*sw+sw/2-1,y],[20+sl*sw+sw/2-1,30]],{c,w:on?2.8:1.6})+tx(20+sl*sw+sw/2-1,y-4,lab,{c,b:1,fs:9.5}):'';
  s+=mk(ns,'DCI',V_('g-pdcch'),12,i===0)+mk(sP,'PDSCH',V_('up'),24,i===1)+mk(sA,'ACK',ackOk?V_('nr'):V_('warn'),sA===sP?12:24,i===2)+li([[20+sU*sw+sw/2-1,56],[20+sU*sw+sw/2-1,82]],{c:puOk?V_('lte'):V_('warn'),w:i===3?2.8:1.6})+tx(Math.min(330,20+sU*sw+sw/2-1),94,'PUSCH',{c:puOk?V_('lte'):V_('warn'),b:1,fs:9.5});
  /* một khe: 14 ký hiệu */
  const dm=A?dmrsSyms(Sx+L,S.dmrs,2).filter(x=>x>=Sx&&x<Sx+L):[Sx].concat(L>=7&&S.dmrs?[Sx+4]:[]),cw=320/14;
  for(let sy=0;sy<14;sy++){const t=dm.includes(sy)?'dm':sy>=Sx&&sy<Sx+L?'pd':sy<S.pdcch&&(A||Sx>=S.pdcch)?'pc':'no';s+=`<rect x="${20+sy*cw}" y="120" width="${cw-2}" height="46" style="fill:${{dm:V_('ink'),pd:V_('g-pdsch'),pc:V_('g-pdcch'),no:V_('panel2')}[t]};stroke:${V_('line')}"/>`+tx(20+sy*cw+cw/2-1,180,sy,{fs:9});}
  s+=tx(20,112,`Khe ${sP}: PDSCH từ ký hiệu ${Sx}, dài ${L}`,{a:'start',b:1,c:V_('ink')})+[['g-pdcch','PDCCH'],['g-pdsch','PDSCH'],['ink','DMRS']].map((q,k)=>`<rect x="${20+k*90}" y="190" width="10" height="10" style="fill:${V_(q[0])}"/>`+tx(34+k*90,199,q[1],{a:'start',fs:9.5})).join('');
  const slot=1/2**mu(),N1=[8,10,17,20][mu()]||20,gap=S.bTdK1*14-(Sx+L)+(tA==='S'?SSFS[S.ssf][0]+SSFS[S.ssf][1]:12),st=['gNB gửi DCI 1_1 trên PDCCH ở khe 0. Trường Time domain resource assignment chỉ một hàng trong bảng cấu hình sẵn, cho K0, kiểu sắp xếp, S và L.',`PDSCH nằm ở khe 0 + K0 = ${sP}${pdOk?'':' (không hợp lệ: đây là khe đường lên)'}, chiếm ký hiệu ${Sx} đến ${Sx+L-1}.`,`UE trả ACK/NACK trên PUCCH ở khe ${sP} + K1 = ${sA}${ackOk?'':' (không hợp lệ: khe này không có ký hiệu đường lên)'}.`,`Với đường lên: DCI 0_1 ở khe 0 cấp PUSCH ở khe 0 + K2 = ${sU}${puOk?'':' (không hợp lệ: không phải khe đường lên)'}.`];
  return{fig:svgw(360,206,s,'Định thời lập lịch'),cap:st[i],
   out:kv('Kiểu sắp xếp',A?'A':'B')+kv('S, L',`${Sx}, ${L}: ${valid?'hợp lệ':'không hợp lệ với kiểu '+S.bTdMap}`)+kv('SLIV (giá trị mã hoá S và L)',sliv)+kv('Ký hiệu DMRS',dm.join(', '))+kv('Phần tử tài nguyên cho dữ liệu trong một PRB',(L-dm.length)*12+dm.length*(S.layers>2?0:6))
    +'<div class="sep"></div>'+kv('PDSCH ở khe',`${sP} (${tP})`)+kv('ACK/NACK ở khe',`${sA} (${tA}): ${ackOk?'được':'không được'}`)+kv('Khoảng hở cho UE xử lý',`${gap} ký hiệu, cần ít nhất N1 = ${N1}: ${gap>=N1?'đủ':'không đủ'}`)+kv('Vòng HARQ nhanh nhất',`${((S.bTdK0+S.bTdK1+2)*slot).toFixed(1)} ms`)+kv('PUSCH ở khe',`${sU} (${tU}): ${puOk?'được':'không được'}`),
   info:`<h3>Lập lịch động theo từng khe</h3>${stepsHtml(st,i)}<p><b>Kiểu A</b> là lập lịch theo khe: PDSCH bắt đầu ở ký hiệu 0 đến 3, DMRS đầu tiên cố định ở ký hiệu 2 hoặc 3. <b>Kiểu B</b> là khe ngắn (mini-slot): bắt đầu ở bất kỳ đâu, dài 2, 4 hoặc 7 ký hiệu, DMRS ở ngay ký hiệu đầu; dùng cho URLLC và cho phổ không cấp phép. S và L được gộp thành một số <b>SLIV</b>. Với PUSCH, kiểu A bắt đầu ở ký hiệu 0 và dài 4 đến 14; kiểu B bắt đầu ở bất kỳ đâu.</p><p><b>K0, K1, K2</b> đếm bằng khe. Ở TDD, K1 và K2 phải rơi đúng khe có đường lên; mẫu khe đang đặt là ${isTDD()?S.tdd:'FDD'}. UE cần thời gian xử lý tối thiểu N1 ký hiệu giữa cuối PDSCH và đầu PUCCH. Trong miền tần số, cấp phát kiểu 0 dùng bitmap theo nhóm PRB, kiểu 1 dùng một đoạn liên tiếp mã hoá thành RIV; xem thẻ Cấp phát PRB.</p>`,
   tblT:'Giới hạn S và L',tbl:tbl(['','Kiểu A','Kiểu B'],[['PDSCH: S','0 đến 3','0 đến 12'],['PDSCH: L','3 đến 14','2, 4, 7'],['PUSCH: S','0','0 đến 13'],['PUSCH: L','4 đến 14','1 đến 14'],['DMRS đầu tiên','Ký hiệu 2 hoặc 3 của khe','Ký hiệu đầu của cấp phát']])};
}};
/* ===== Chương 14 và 15: DMRS theo cửa anten, các tín hiệu tham chuẩn, PUCCH ===== */
const RSV={dm1:'DMRS kiểu cấu hình 1',dm2:'DMRS kiểu cấu hình 2',ptrs:'PTRS: bám pha',csirs:'CSI-RS: đo kênh',trs:'TRS: bám thời gian và tần số',srs:'SRS: thăm dò đường lên',pucch:'PUCCH: năm định dạng'};
Object.assign(C,{bRsV:{l:'Tín hiệu',o:()=>Object.entries(RSV)},bDmLen:{l:'DMRS đầu dài',num:1,o:()=>[[1,'1 ký hiệu'],[2,'2 ký hiệu']],show:()=>S.bRsV.startsWith('dm')},bDmPorts:{l:'Số cửa anten (số lớp cho các UE)',r:[1,12,1],f:v=>v+' cửa',show:()=>S.bRsV.startsWith('dm')}});
BK.rs={t:'DMRS theo cửa anten, các tín hiệu tham chuẩn và PUCCH',ch:'Chương 14 và 15',ctl:['bRsV','bDmLen','bDmPorts'],n:()=>Object.keys(RSV).length,r(i){
  const keys=Object.keys(RSV),v=keys[i];if(S.bRsV!==v)S.bRsV=v;const gc=[V_('u1'),V_('u2'),V_('u3')],cw=20,ch=13,gx=50,gy=18;let s='',out='',info='',tb='',tt='';const cell=(sy,k,c,o)=>`<rect x="${gx+sy*cw}" y="${gy+(11-k)*ch}" width="${cw-1}" height="${ch-1}" style="fill:${c}${o?';opacity:'+o:''}"/>`;
  const grid=f=>{for(let sy=0;sy<14;sy++){s+=tx(gx+sy*cw+cw/2,gy+12*ch+11,sy,{fs:8.5});for(let k=0;k<12;k++)s+=f(sy,k);}for(let k=0;k<12;k++)s+=tx(gx-5,gy+(11-k)*ch+10,k,{a:'end',fs:8.5});s+=tx(190,gy+12*ch+24,'Một PRB (12 sóng mang con) trong một khe (14 ký hiệu)',{fs:9});};
  if(v==='dm1'||v==='dm2'){
    const t1=v==='dm1',len=S.bDmLen,maxP=t1?4*len:6*len,np=Math.min(S.bDmPorts,maxP),ngrp=t1?(np>2*len?2:1):Math.ceil(np/(2*len)),grpOf=k=>t1?k%2:Math.floor((k%6)/2),syms=[2].concat(len===2?[3]:[]),add=dmrsSyms(14,S.dmrs,2).slice(1);
    grid((sy,k)=>{const d=syms.includes(sy)||add.includes(sy)||(len===2&&add.includes(sy-1));if(sy<S.pdcch)return cell(sy,k,V_('g-pdcch'),0.5);if(d){const g=grpOf(k);return cell(sy,k,g<ngrp?gc[g]:V_('panel2'));}return cell(sy,k,V_('g-pdsch'),0.45);});
    const ports=Array.from({length:np},(_,p)=>{const g=t1?Math.floor(p/2)%2:Math.floor(p/2)%3,f=p%2?'+ −':'+ +',td=p>=(t1?4:6)?'+ −':'+ +';return[1000+p,g,f,len===2?td:'—'];});
    const nsym=syms.length*(1+add.length),re=nsym*(t1?6:4)*ngrp,ohd=nsym*12;
    out=kv('Kiểu cấu hình',t1?'1: răng lược, cách một sóng mang con':'2: từng cặp sóng mang con liền nhau')+kv('Số cửa tối đa',`${maxP} (${t1?'4 với một ký hiệu, 8 với hai':'6 với một ký hiệu, 12 với hai'})`)+kv('Số cửa đang dùng',np)+kv('Số nhóm CDM đang dùng',ngrp)+kv('Phần tử DMRS trong một PRB',re)+kv('Ký hiệu DMRS',syms.concat(add).join(', '))+kv('Overhead nếu không ghép dữ liệu vào ký hiệu DMRS',f1(ohd/168*100)+' %');
    info=`<p>DMRS là tín hiệu tham chuẩn đi kèm PDSCH và PUSCH, được tiền mã hoá giống hệt dữ liệu, nên UE ước lượng luôn kênh đã qua tạo chùm. Mỗi lớp MIMO cần một <b>cửa anten</b> DMRS riêng. Các cửa được tách nhau bằng ba cách ghép lại: khác nhóm sóng mang con (<b>nhóm CDM</b>, mỗi màu một nhóm), khác mã trực giao theo tần số trong cùng nhóm, và khi DMRS dài hai ký hiệu thì thêm mã trực giao theo thời gian.</p><p><b>Kiểu 1</b> dày hơn theo tần số nên ước lượng kênh tốt hơn, tối đa 8 cửa. <b>Kiểu 2</b> thưa hơn, tối đa 12 cửa, hợp với MU-MIMO nhiều UE. Vị trí theo thời gian: DMRS đầu ở ký hiệu 2 hoặc 3 (kiểu sắp xếp A) hoặc ký hiệu đầu của cấp phát (kiểu B); UE đi nhanh thì thêm tới 3 vị trí bổ sung. Số DMRS bổ sung đang lấy theo ô DMRS bổ sung ở thẻ Khung (${S.dmrs}).</p>`;
    tt='Các cửa anten đang dùng';tb=tbl(['Cửa','Nhóm CDM','Mã theo tần số','Mã theo thời gian'],ports);
  }else if(v==='pucch'){
    const F=[['0','1 đến 2','tối đa 2 bit','1','chọn chuỗi; ghép nhiều UE trên cùng PRB'],['1','4 đến 14','tối đa 2 bit','1','BPSK/QPSK với mã trực giao theo thời gian; ghép nhiều UE'],['2','1 đến 2','trên 2 bit','1 đến 16','OFDM, không ghép UE; dùng cho CSI ngắn'],['3','4 đến 14','trên 2 bit','1 đến 16','DFT-s-OFDM, tải lớn, không ghép UE'],['4','4 đến 14','trên 2 bit','1','DFT-s-OFDM có mã trực giao; ghép được vài UE']];
    grid((sy,k)=>sy>=12&&k===11?cell(sy,k,V_('g-pucch')):sy>=4&&k===0?cell(sy,k,(sy-4)%2===0?V_('ink'):V_('g-srs')):cell(sy,k,V_('g-pusch'),0.35));
    out=kv('Trên hình, hàng trên cùng','PUCCH ngắn (định dạng 0 hoặc 2) ở 2 ký hiệu cuối')+kv('Hàng dưới cùng','PUCCH dài định dạng 1: ký hiệu DMRS xen kẽ ký hiệu mang tin')+kv('PUCCH mang','ACK/NACK của HARQ, yêu cầu cấp phát (SR), báo cáo CSI');
    info=`<p>PUCCH mang thông tin điều khiển đường lên (UCI) khi UE không có PUSCH. NR có năm định dạng, chia theo hai trục: <b>ngắn</b> (1 đến 2 ký hiệu, phản hồi nhanh, hợp với khe đặc biệt của TDD) hay <b>dài</b> (4 đến 14 ký hiệu, phủ xa hơn); và tải <b>nhỏ</b> (tối đa 2 bit: ACK/NACK, SR) hay <b>lớn</b> (CSI, nhiều ACK). Khi UE có PUSCH cùng lúc, UCI được ghép luôn vào PUSCH.</p>`;
    tt='Năm định dạng PUCCH';tb=tbl(['Định dạng','Số ký hiệu','Tải tin','Số PRB','Đặc điểm'],F);
  }else{
    const P={ptrs:[(sy,k)=>sy===2?cell(sy,k,V_('ink')):sy>2&&sy%2===1&&k===0?cell(sy,k,V_('warn')):sy<2?cell(sy,k,V_('g-pdcch'),0.5):cell(sy,k,V_('g-pdsch'),0.4),'PTRS (đỏ) giúp UE bám sai pha do bộ dao động gây ra, vấn đề chính ở FR2. Nó dày theo thời gian (mỗi 1, 2 hoặc 4 ký hiệu, MCS càng cao càng dày) nhưng thưa theo tần số (một sóng mang con trên mỗi 2 hoặc 4 PRB). Ở FR1 thường không cần.',kv('Mật độ thời gian','mỗi 1, 2 hoặc 4 ký hiệu, theo MCS')+kv('Mật độ tần số','1 sóng mang con mỗi 2 hoặc 4 PRB, theo số PRB được cấp')+kv('Gắn với','một cửa DMRS')],
     csirs:[(sy,k)=>(sy===5||sy===6)&&(k>=2&&k<=5)?cell(sy,k,gc[Math.floor((k-2)/2)]):cell(sy,k,V_('g-pdsch'),0.3),'CSI-RS là tín hiệu để UE đo kênh và báo CQI, PMI, RI; không đi kèm dữ liệu và không được tiền mã hoá theo UE. Hỗ trợ 1 đến 32 cửa; hình vẽ ví dụ 8 cửa ghép bằng CDM4 (2 sóng mang con × 2 ký hiệu). Có thể phát định kỳ, bán cố định hoặc theo yêu cầu. CSI-RS công suất không (ZP) dùng để chừa chỗ đo nhiễu.',kv('Số cửa','1, 2, 4, 8, 12, 16, 24, 32')+kv('Chu kỳ','4 đến 640 khe')+kv('Dùng cho','báo cáo CSI, quản lý chùm, đo di động')],
     trs:[(sy,k)=>(sy===4||sy===8)&&k%4===0?cell(sy,k,V_('u3')):cell(sy,k,V_('g-pdsch'),0.3),'NR không có CRS phát liên tục như LTE, nên UE cần TRS để bám thời gian và tần số. TRS là một cấu hình CSI-RS đặc biệt: một cửa, 3 phần tử trên mỗi PRB, hai ký hiệu cách nhau 4 ký hiệu trong khe, phát ở hai khe liền nhau, lặp lại sau 10 đến 80 ms.',kv('Mật độ','3 phần tử mỗi PRB')+kv('Trong khe','2 ký hiệu cách nhau 4')+kv('Chu kỳ','10, 20, 40, 80 ms')],
     srs:[(sy,k)=>sy>=12&&k%2===0?cell(sy,k,V_('g-srs')):sy>=12?cell(sy,k,V_('panel2')):cell(sy,k,V_('g-pusch'),0.35),'SRS do UE phát để gNB đo kênh đường lên. Ở TDD, kênh hai chiều giống nhau nên gNB dùng SRS để tính luôn trọng số tạo chùm đường xuống cho Massive MIMO. SRS nằm ở các ký hiệu cuối khe, dạng răng lược 2 hoặc 4 để nhiều UE phát xen kẽ; UE có ít nhánh phát hơn nhánh thu thì phát luân phiên qua các anten.',kv('Số ký hiệu','1, 2 hoặc 4 (về sau tới 14)')+kv('Răng lược','2 hoặc 4')+kv('Số cửa','1, 2, 4')]}[v];
    grid(P[0]);info=`<p>${P[1]}</p>`;out=P[2];
    tt='Các tín hiệu tham chuẩn của NR';tb=tbl(['Tín hiệu','Chiều','Dùng để'],[['DMRS','Cả hai','Giải điều chế PDSCH, PUSCH, PDCCH, PUCCH, PBCH'],['PTRS','Cả hai','Bám pha, chủ yếu ở FR2'],['CSI-RS','Xuống','Đo kênh, quản lý chùm, đo di động'],['TRS','Xuống','Bám thời gian và tần số'],['SRS','Lên','Đo kênh đường lên, tính trọng số tạo chùm'],['PSS, SSS','Xuống','Đồng bộ và nhận dạng cell']],keys.indexOf(v)-1);
  }
  return{fig:svgw(360,gy+12*ch+30,s,RSV[v]),cap:RSV[v]+'.',out,info,tbl:tb,tblT:tt};
}};
/* ===== Chương 16: lộ trình lên 6G ===== */
const G6=[['Tốc độ đỉnh','20 Gbit/s','50 đến 200 Gbit/s',20,200],['Tốc độ người dùng trải nghiệm','100 Mbit/s','300 đến 500 Mbit/s',100,500],['Hiệu suất phổ','mốc 1','gấp 1.5 đến 3 lần',1,3],['Dung lượng theo diện tích','10 Mbit/s/m²','30 đến 50 Mbit/s/m²',10,50],['Mật độ kết nối','10⁶ thiết bị/km²','10⁶ đến 10⁸ thiết bị/km²',1,100],['Tốc độ di chuyển','500 km/h','500 đến 1000 km/h',500,1000],['Trễ vô tuyến','1 ms','0.1 đến 1 ms',1,10],['Độ tin cậy','lỗi 10⁻⁵','lỗi 10⁻⁵ đến 10⁻⁷',1,100],['Định vị','chưa đặt mục tiêu','1 đến 10 cm',1,100]];
const G6S=['Truyền thông nhập vai (immersive): mở rộng từ eMBB, cho thực tế mở rộng, hiện diện từ xa.','Truyền thông siêu tin cậy, trễ thấp: mở rộng từ URLLC, cho tự động hoá toàn diện.','Truyền thông số lượng cực lớn: mở rộng từ mMTC, cho thành phố và hạ tầng thông minh.','Kết nối khắp nơi: phủ vùng xa bằng cả mặt đất lẫn vệ tinh. Mới.','Trí tuệ nhân tạo kết hợp truyền thông: mạng vừa dùng AI vừa phục vụ AI. Mới.','Cảm biến kết hợp truyền thông: dùng sóng vô tuyến để dò vật thể, đo khoảng cách. Mới.'];
BK.g6={t:'Lộ trình phát triển lên 6G (IMT-2030)',ch:'Chương 16',ctl:[],n:()=>G6.length,r(i){
  let s='';G6.forEach((r,k)=>{const y=14+k*24,a=Math.log10(r[4]/r[3]+1)/Math.log10(101)*150+40;s+=tx(4,y+12,r[0],{a:'start',fs:9,c:k===i?V_('ink'):V_('muted'),b:k===i})+`<rect x="150" y="${y}" width="40" height="8" style="fill:${V_('lte')};opacity:${k===i?1:0.5}"/><rect x="150" y="${y+9}" width="${a}" height="8" style="fill:${V_('nr')};opacity:${k===i?1:0.5}"/><rect x="2" y="${y-3}" width="356" height="23" data-bks="${k}" tabindex="0" role="button" style="fill:transparent;cursor:pointer"/>`;});
  s+=`<rect x="150" y="234" width="10" height="8" style="fill:${V_('lte')}"/>`+tx(164,242,'5G (IMT-2020)',{a:'start',fs:9.5})+`<rect x="250" y="234" width="10" height="8" style="fill:${V_('nr')}"/>`+tx(264,242,'6G (IMT-2030)',{a:'start',fs:9.5});
  const r=G6[i];
  return{fig:svgw(360,250,s,'So sánh năng lực 5G và 6G'),cap:`${r[0]}. 5G: ${r[1]}. 6G: ${r[2]}.`,
   out:kv('Năng lực',r[0])+kv('5G (IMT-2020)',r[1])+kv('6G (IMT-2030), khoảng mục tiêu nghiên cứu',r[2]),
   info:`<h3>Sáu kịch bản sử dụng của IMT-2030</h3><ol class="bks">${G6S.map(t=>`<li>${t}</li>`).join('')}</ol><p>Bốn nguyên tắc bao trùm: bền vững, bảo mật và tin cậy, kết nối cho mọi người, trí tuệ ở khắp nơi.</p><h3>Các mốc chính</h3><ul class="bk"><li><p class="bk-f"><b>2023:</b> ITU-R thông qua khuyến nghị khung cho IMT-2030 (M.2160), nêu kịch bản sử dụng và các năng lực ở trên.</p></li><li><p class="bk-f"><b>Các bản 3GPP Release 18, 19:</b> 5G-Advanced, đồng thời bắt đầu nghiên cứu cho 6G.</p></li><li><p class="bk-f"><b>Release 20:</b> giai đoạn nghiên cứu 6G. <b>Release 21:</b> dự kiến là bộ tiêu chuẩn 6G đầu tiên.</p></li><li><p class="bk-f"><b>Khoảng 2030:</b> ITU-R hoàn tất đánh giá và công nhận công nghệ IMT-2030; thương mại hoá đầu tiên.</p></li></ul><h3>Các hướng công nghệ đang được nghiên cứu</h3><p>Phổ mới ở dải 7 đến 15 GHz và dưới terahertz; anten cực lớn và bề mặt phản xạ thông minh (RIS); giao diện vô tuyến có AI bên trong; kết hợp cảm biến với truyền thông; mạng không gian và mặt đất hợp nhất; tiết kiệm năng lượng ngay từ thiết kế.</p><p class="note">Các con số của 6G là khoảng mục tiêu để nghiên cứu trong khuyến nghị khung của ITU-R, chưa phải yêu cầu chốt. Các mốc của 3GPP là kế hoạch và có thể thay đổi.</p>`,
   tblT:'Năng lực của 5G và 6G',tbl:tbl(['Năng lực','5G (IMT-2020)','6G (IMT-2030)'],G6.map(x=>x.slice(0,3)),i)};
}};
