   +li([[8+3.44*S.xRrDed,py-4],[8+3.44*S.xRrDed,py+24]],{c:V_('ink'),w:1.6})+li([[8+3.44*mn,py-4],[8+3.44*mn,py+24]],{c:V_('ink'),w:1.6,d:'3 2'})+li([[8+3.44*mx,py-4],[8+3.44*mx,py+24]],{c:V_('warn'),w:1.6})
   +tx(8,py+36,`Lát cắt này ${f0(g)} %`,{a:'start',c:V_('cp'),b:1})+tx(180,py+36,`các lát cắt khác ${f0(oth)} %`,{c:V_('up'),b:1})+tx(352,py+36,`trống ${f0(idle)} %`,{a:'end'})+tx(180,py+50,'Vạch liền: dành riêng. Vạch đứt: mức bảo đảm. Vạch đỏ: trần.',{fs:8.5});
