BKMAP.push(['Mở rộng: dịch vụ và mô hình triển khai',['#npn','#slice2','#urllc','#iot','#mec','#pos','#more']],['Mở rộng: vô tuyến nâng cao',['#ho2','#dss','#bm','#loop','#tddsync','#oran','#iabu']],['Mở rộng: lõi và bảo mật',['#sec','#sba','#nwdaf','#resil']],['Mở rộng: vận hành và truyền dẫn',['#kpi','#cap','#xhaul','#son']]);
/* ---------- Thẻ Di động và điều hướng lưu lượng ---------- */
/* Nội dung Ericsson theo tài liệu 5G Mobility and Traffic Management Guideline; phần 3GPP theo TS 38.331, 38.304, 37.340; tên của Huawei và Nokia ghi theo hiểu biết chung */
Object.assign(S,{mbV:'route',mbPos:0,mbDir:'out',mbUe:'ca',mbA2:-110,mbCrit:-120,mbA5:-108,mbB2:-112,mbB1:-108,mbBw:50,mbMlc:1,mbBwt:1,mbUl:-108,mbBuf:0,mbPrF2:7,mbPrF1:6,mbPrL:5,mbXHigh:-108,mbSLow:-114,mbXLow:-112,mb5g:30,mbsIdle:1,mbsHo:0,mbsCov:0,mbsLb:0,mbEps:1,mbVonr:1,mbLteCov:1});
