const mbD=i=>100+100*i,mbRs=(l,d)=>MBL[l].p-MBL[l].sl*log10(d/100),mbSe=r=>Math.min(7.4,Math.log2(1+10**(clamp(r+118,-8,28)/10)))*0.62,mbRate=(l,d)=>MBL[l].bw*mbSe(mbRs(l,d))*MBL[l].duty;
