 mbA5:{l:'A5: ngưỡng tần số NR ứng viên',r:[-120,-90,1],f:dbm,show:()=>'route,steer'.includes(S.mbV)},mbB2:{l:'B2: ngưỡng LTE ứng viên',r:[-124,-95,1],f:dbm,show:()=>'route,steer'.includes(S.mbV)&&!endc()},
 mbB1:{l:'B1: ngưỡng NR để LTE đưa UE sang NR',r:[-120,-95,1],f:dbm,show:()=>S.mbV==='route'},
 mbMlc:{l:'Điều hướng lên tần số băng rộng hơn',num:1,o:()=>[[1,'Bật'],[0,'Tắt']],show:()=>'route,steer'.includes(S.mbV)&&!endc()},mbBwt:{l:'Chuyển về LTE khi băng thông NR thấp',num:1,o:()=>[[1,'Bật'],[0,'Tắt']],show:()=>'route,steer'.includes(S.mbV)&&!endc()},
 mbBw:{l:'Ngưỡng tổng băng thông NR',r:[20,120,10],f:v=>v+' MHz',show:()=>'route,steer'.includes(S.mbV)&&!endc()&&S.mbBwt},
 mbUl:{l:'Ngưỡng NR để dùng đường lên NR',r:[-120,-95,1],f:dbm,show:()=>S.mbV==='route'&&endc()},mbBuf:{l:'Lượng dữ liệu xuống',num:1,o:()=>[[0,'Ít: một đường là đủ'],[1,'Nhiều: bộ đệm PDCP đầy']],show:()=>S.mbV==='route'&&endc()},
 mbPrF2:{l:'Độ ưu tiên của NR 3500',r:[0,7,1],f:v=>String(v),show:()=>S.mbV==='idle'},mbPrF1:{l:'Độ ưu tiên của NR 700',r:[0,7,1],f:v=>String(v),show:()=>S.mbV==='idle'},mbPrL:{l:'Độ ưu tiên của LTE',r:[0,7,1],f:v=>String(v),show:()=>S.mbV==='idle'},
 mbXHigh:{l:'Ngưỡng để lên tần số ưu tiên cao hơn',r:[-122,-95,1],f:dbm,show:()=>S.mbV==='idle'},mbSLow:{l:'Ngưỡng thấp của cell đang cắm trại',r:[-126,-100,1],f:dbm,show:()=>S.mbV==='idle'},mbXLow:{l:'Ngưỡng để xuống tần số ưu tiên thấp hơn',r:[-124,-98,1],f:dbm,show:()=>S.mbV==='idle'},
