/* Theo báo cáo RAN Sharing 4G/5G (MORAN và MOCN) của người dùng, 3GPP TS 23.251, 23.501 mục 5.18, 38.300, 38.331, 36.331, 38.413, 36.413, 28.541, 32.130; tên của vendor ghi theo hiểu biết chung */
Object.assign(S,{rsV:'arch',rsStep:0,rsModel:'mocn',rsCellId:'same',rsUe:'A',rsRes:0,rsPol:'dyn',rsAlpha:50,rsDemA:70,rsDemB:70});
const RSO={A:['Nhà mạng A','452-01','up','1001'],B:['Nhà mạng B','452-02','cp','2002']};
const RSM={site:['Chỉ chung hạ tầng thụ động','Hai nhà mạng chỉ dùng chung cột, nhà trạm, nguồn điện, đôi khi cả truyền dẫn. Mỗi bên có thiết bị vô tuyến, tần số và lõi riêng.'],
 moran:['MORAN: chung thiết bị, riêng tần số','Dùng chung anten, khối vô tuyến và băng gốc, nhưng mỗi nhà mạng có sóng mang riêng, phát PLMN riêng, bộ lập lịch và tham số vô tuyến riêng.'],
 mocn:['MOCN: chung cả thiết bị lẫn tần số','Một sóng mang chung phát đồng thời PLMN của các nhà mạng; một bộ lập lịch chia PRB giữa họ. Mỗi nhà mạng vẫn có lõi riêng.'],
 gwcn:['GWCN: chung cả nút điều khiển của lõi','Như MOCN nhưng dùng chung luôn MME (ở 4G). Hệ thống 5G chỉ chuẩn hoá MOCN, không có GWCN.']};
const RSHV={arch:'Kiến trúc: cái gì dùng chung, cái gì riêng',sib:'Quảng bá SIB1 và chọn mạng',sig:'Báo hiệu truy nhập và định tuyến về đúng lõi',sched:'Chia PRB giữa hai nhà mạng trong 24 giờ',ops:'Vận hành, cấu hình và ba vendor'};
Object.assign(C,{
 rsV:{l:'Xem phần nào',o:()=>Object.entries(RSHV)},
 rsModel:{l:'Mô hình chia sẻ',o:()=>Object.entries(RSM).filter(([k])=>S.rsV==='arch'||k==='moran'||k==='mocn').map(([k,v])=>[k,v[0]]),show:()=>S.rsV!=='ops'},
 rsCellId:{l:'Định danh cell trong SIB1',o:()=>[['same','Một định danh cell chung cho mọi PLMN'],['multi','Mỗi nhà mạng một định danh cell và TAC riêng']],show:()=>'sib,sig'.includes(S.rsV)&&S.rsModel==='mocn'&&!nsa()},
 rsUe:{l:'Máy đang xét',o:()=>[['A','Thuê bao của nhà mạng A (452-01)'],['B','Thuê bao của nhà mạng B (452-02)'],['C','Khách chuyển vùng quốc tế, có thoả thuận với B']],show:()=>'sib,sig'.includes(S.rsV)},
 rsRes:{l:'cellReservedForOperatorUse của nhà mạng B',num:1,o:()=>[[0,'notReserved: máy nào của B cũng vào được'],[1,'reserved: chỉ máy thử nghiệm của B (lớp truy nhập 11, 15)']],show:()=>S.rsV==='sib'},
 rsPol:{l:'Chính sách chia dung lượng',o:()=>[['static','Tĩnh: mỗi bên đúng phần của mình, không mượn'],['dyn','Động: bảo đảm phần tối thiểu, phần thừa cho bên kia mượn'],['pool','Gộp hoàn toàn: không hạn mức, ai có dữ liệu thì dùng']],show:()=>S.rsV==='sched'&&S.rsModel==='mocn'},
 rsAlpha:{l:'Phần của nhà mạng A (α)',r:[10,90,5],f:v=>`A ${v} %, B ${100-v} %`,show:()=>S.rsV==='sched'},
 rsDemA:{l:'Lưu lượng đỉnh của A so với dung lượng cả cell',r:[10,150,5],f:v=>v+' %',show:()=>S.rsV==='sched'},rsDemB:{l:'Lưu lượng đỉnh của B so với dung lượng cả cell',r:[10,150,5],f:v=>v+' %',show:()=>S.rsV==='sched'}});
const rsNode=()=>lte()?'eNB':nsa()?'eNB và en-gNB':'gNB',rsCn=()=>nsa()?'MME':'AMF',rsGw=()=>nsa()?'S-GW':'UPF',rsCore=()=>nsa()?'EPC':'5GC';
const rsDem=h=>{const g=(c,w)=>Math.exp(-(((Math.min(Math.abs(h-c),24-Math.abs(h-c)))/w)**2));return[S.rsDemA*(0.12+0.88*g(13,3.6)),S.rsDemB*(0.12+0.88*g(21,3.2))];};
function rsShare(h){
  const [dA,dB]=rsDem(h),a=S.rsAlpha,b=100-a;let sA,sB;
  if(S.rsModel==='moran'||S.rsPol==='static'){sA=Math.min(dA,a);sB=Math.min(dB,b);}
  else if(S.rsPol==='dyn'){if(dA+dB<=100){sA=dA;sB=dB;}else{sA=Math.min(dA,Math.max(a,100-dB));sB=Math.min(dB,100-sA);}}
  else{const k=Math.min(1,100/(dA+dB));sA=dA*k;sB=dB*k;}
  return{dA,dB,sA,sB,free:100-sA-sB,pkA:S.rsModel==='moran'||S.rsPol==='static'?a:100-sB,pkB:S.rsModel==='moran'||S.rsPol==='static'?b:100-sA};
}
const rsPre=lines=>`<pre class="dec" style="white-space:pre-wrap;font:11px/1.5 ui-monospace,Menlo,Consolas,monospace;overflow-x:auto;margin:0">${lines.map(l=>esc(l)).join('\n')}</pre>`;
/* các bước báo hiệu: [từ, tới, tên bản tin, giao thức, giải thích, các trường tin] ; nút: ue, ran, cn (lõi của máy), ot (lõi còn lại), cả hai = 'both' */
function rsSig(){
  const u=S.rsUe==='A'?'A':'B',o=RSO[u],mocn=S.rsModel==='mocn',multi=mocn&&S.rsCellId==='multi'&&!nsa(),sa=!nsa(),idx=u==='A'?1:2,cid=multi?(u==='A'?'gNB 1001, cell 1':'gNB 2002, cell 1'):'gNB 5001, cell 1',tac=mocn&&!multi&&nsa()?'1001 (chung)':o[3],L=[];
  const cellTxt=mocn?'cell dùng chung':`cell trên sóng mang riêng của ${o[0]}`;
  L.push(['ran','both',sa?'NG Setup Request / Response':'S1 Setup Request / Response',sa?'NGAP':'S1AP',`Khi khởi động, trạm dùng chung lập kết nối tới ${rsCn()} của từng nhà mạng và khai báo mình phát những PLMN nào ở vùng theo dõi nào. Mỗi lõi trả lời nó phục vụ PLMN nào.`,
   sa?[['GlobalRANNodeID',multi?'mỗi nhà mạng một gNB logic: 452-01 gNB 1001; 452-02 gNB 2002':'PLMN của bên chủ trì + gNB ID 5001'],['SupportedTAList',mocn?'{TAC 1001: [452-01]}, {TAC 2002: [452-02]}; mỗi PLMN kèm danh sách S-NSSAI':'theo từng cell: sóng mang F1 phát 452-01, F2 phát 452-02'],['Trả lời: ServedGUAMIList, PLMNSupportList','AMF A: 452-01; AMF B: 452-02'],['RelativeAMFCapacity','trọng số chia tải trong nhóm AMF của cùng một nhà mạng']]
     :[['Global eNB ID','PLMN của bên chủ trì + eNB ID'],['Supported TAs',mocn?'{TAC 1001: Broadcast PLMNs [452-01, 452-02]}':'TAC theo từng cell, mỗi cell một PLMN'],['Trả lời: Served GUMMEIs','MME A: 452-01; MME B: 452-02'],['Relative MME Capacity','trọng số chia tải (S1-flex)']]]);
  L.push(['ran','ue',sa?'MIB, SIB1':'MIB, SystemInformationBlockType1','RRC',mocn?`Cell dùng chung phát một SIB1 chứa cả hai PLMN. Máy của ${o[0]} thấy PLMN ${o[1]} ở vị trí thứ ${idx} trong danh sách.`:`Mỗi sóng mang là một cell riêng, SIB1 chỉ có một PLMN. Máy của ${o[0]} chỉ cắm trại trên sóng mang của mạng mình.`,
   mocn?[[sa?'plmn-IdentityInfoList':'plmn-IdentityList','[1] 452-01, [2] 452-02'],['trackingAreaCode',sa?'1001 cho 452-01; 2002 cho 452-02':'1001, chung cho mọi PLMN (LTE chỉ có một TAC mỗi cell)'],['cellIdentity',multi?'riêng cho từng nhà mạng':'chung'],['cellReservedForOperatorUse','khai riêng từng PLMN']]:[['plmn-Identity',o[1]],['trackingAreaCode',o[3]],['Tần số',u==='A'?'F1':'F2']]]);
  L.push(['ue','ran',sa?'RRCSetupRequest, RRCSetup':'RRCConnectionRequest, RRCConnectionSetup','RRC','Truy nhập ngẫu nhiên và lập SRB1. Tới đây trạm chưa biết máy thuộc nhà mạng nào.',[['ue-Identity','số ngẫu nhiên hoặc phần S-TMSI'],['establishmentCause','mo-Signalling']]]);
  L.push(['ue','ran',sa?'RRCSetupComplete':'RRCConnectionSetupComplete','RRC',mocn?`Bản tin then chốt của MOCN: máy báo đã chọn PLMN nào bằng chỉ số trong danh sách SIB1. Máy của ${o[0]} gửi chỉ số ${idx}.`:'Máy vẫn gửi selectedPLMN-Identity, nhưng cell chỉ có một PLMN nên luôn bằng 1.',
   [['selectedPLMN-Identity',mocn?`${idx} (tức ${o[1]})`:'1'],[sa?'registeredAMF, guami-Type':'registeredMME','có nếu máy đã đăng ký trước đó: giúp trạm tìm đúng nút cũ'],sa?['s-NSSAI-List','lát cắt máy muốn dùng']:['gummei-Type','native'],['dedicatedNAS-Message',sa?'Registration Request (SUCI)':'Attach Request']]]);
  L.push(['ran','ran',`Chọn ${rsCn()}`,'nội bộ',mocn?`Trạm chọn lõi theo PLMN máy vừa báo: chỉ xét các ${rsCn()} đã khai phục vụ ${o[1]}, rồi mới xét ${sa?'GUAMI và lát cắt':'GUMMEI'} và trọng số tải. Đây là chức năng chọn nút NAS (NNSF).`:`Trạm chọn lõi theo cell: cell trên sóng mang của ${o[0]} chỉ nối về lõi của ${o[0]}.`,
   [['Tiêu chí 1',mocn?'PLMN đã chọn':'cell đang phục vụ'],['Tiêu chí 2',sa?'GUAMI đã đăng ký, rồi S-NSSAI':'GUMMEI đã đăng ký'],['Tiêu chí 3','trọng số dung lượng tương đối'],['Kết quả',`${rsCn()} của ${o[0]}`]]]);
  L.push(['ran','cn','Initial UE Message',sa?'NGAP':'S1AP',`Bản tin NAS đầu tiên được chuyển tới ${rsCn()} của ${o[0]}. Vị trí của máy được ghi bằng PLMN đã chọn, nên lõi của ${o[0]} thấy như máy đang ở trong mạng mình.`,
   sa?[['RAN-UE-NGAP-ID','1'],['NAS-PDU','Registration Request'],['UserLocationInformation: TAI',`${o[1]}, TAC ${tac}`],['UserLocationInformation: NR-CGI',`${o[1]}, ${cid}`],['RRCEstablishmentCause','mo-Signalling']]
     :[['eNB-UE-S1AP-ID','1'],['NAS-PDU','Attach Request'],['TAI',`${o[1]}, TAC ${tac}`],['E-UTRAN-CGI',`${o[1]}, eNB 5001, cell 1`],['GUMMEI-Type','native']]]);
  L.push(['cn','ue','Xác thực và bảo mật NAS','NAS',`${sa?'AUSF và UDM':'HSS'} của ${S.rsUe==='C'?'mạng nhà của khách (qua chuyển vùng với B)':o[0]} xác thực máy. Trạm dùng chung chỉ chuyển tiếp, không thấy nội dung.`,[['Bên xác thực',S.rsUe==='C'?'mạng nhà của khách':o[0]],['Tên mạng phục vụ trong khoá',sa?`5G:mnc0${o[1].slice(4)}.mcc452.3gppnetwork.org`:o[1]]]]);
  L.push(['cn','ran','Initial Context Setup Request',sa?'NGAP':'S1AP',`Lõi giao ngữ cảnh cho trạm, kèm danh sách hạn chế di động: máy này thuộc PLMN nào và được coi PLMN nào là tương đương. Từ đây trạm biết phải tính PRB của máy vào hạn mức của ${o[0]} và chỉ chuyển giao máy tới cell có PLMN được phép.`,
   [[sa?'MobilityRestrictionList: servingPLMN':'HandoverRestrictionList: servingPLMN',o[1]],['equivalentPLMNs',S.rsUe==='C'?'không có':'các PLMN mà nhà mạng coi là tương đương, nếu có'],[sa?'AllowedNSSAI':'SPID (chỉ số RFSP)',sa?`lát cắt của ${o[0]}`:'chính sách tần số theo thuê bao'],['UESecurityCapabilities, SecurityKey','để bật bảo mật AS'],sa?['PDUSessionResourceSetupListCxtReq','phiên dữ liệu kèm địa chỉ đường hầm N3 của UPF']:['E-RABToBeSetupList','bearer kèm địa chỉ đường hầm S1-U của S-GW']]]);
  if(endc())L.push(['ran','ran','SgNB Addition Request / Acknowledge','X2AP',`eNB dùng chung kiểm tra PLMN của máy có được phép dùng EN-DC trên cell này không, rồi mới thêm en-gNB. Đường dữ liệu từ en-gNB đi thẳng về S-GW của ${o[0]}.`,[['Điều kiện','PLMN của máy nằm trong danh sách PLMN được phép EN-DC của cell LTE'],['E-RABs To Be Added','bearer tách do nút phụ kết cuối'],['S1-U của nút phụ',`về S-GW của ${o[0]}`]]]);
  L.push(['ran','cn',sa?'Dữ liệu trên N3':'Dữ liệu trên S1-U','GTP-U',`Gói của máy đi trong đường hầm GTP-U tới ${rsGw()} của ${o[0]}. Trên truyền dẫn, lưu lượng của hai nhà mạng tách bằng VLAN hoặc VRF riêng, thường có IPsec riêng từng bên.`,[['Đường hầm',`trạm ↔ ${rsGw()} của ${o[0]}`],['Tách trên truyền dẫn','VLAN, địa chỉ IP và IPsec riêng cho từng nhà mạng'],['Tính cước','lõi của từng nhà mạng tự tính cho thuê bao của mình']]]);
  L.push(['ran','ran','Chuyển giao trong vùng chia sẻ',sa?'XnAP hoặc NGAP':'X2AP hoặc S1AP','Khi máy di chuyển, trạm chỉ chọn cell đích có phát PLMN đang phục vụ hoặc PLMN tương đương của máy. Ra khỏi vùng chia sẻ thì máy được chuyển về mạng riêng của nhà mạng mình.',[['Kiểm tra cell đích','PLMN phục vụ hoặc tương đương có trong danh sách PLMN của cell đích'],['Bản tin Handover Request','mang theo danh sách hạn chế di động sang trạm đích'],['Ra khỏi vùng chia sẻ',`về tần số riêng của ${o[0]} theo ưu tiên tần số của thuê bao`]]]);
  return L;
}
let RSCAP='';
function rsN(){return {arch:4,sib:1,sig:rsSig().length,sched:24,ops:1}[S.rsV];}
function renderRsh(){
  if(S.rsV!=='arch'&&S.rsModel!=='moran'&&S.rsModel!=='mocn')S.rsModel='mocn';
  const v=S.rsV,i=clamp(S.rsStep,0,rsN()-1),M=S.rsModel,cA=V_('up'),cB=V_('cp'),cS=V_('nr'),g4=nsa(),lteM=lte();let fig='',out='',info='',tb='',tt='';
  $('#rsLead').textContent=`Hai nhà mạng A (PLMN 452-01) và B (PLMN 452-02) dùng chung một trạm ${lteM?'4G':nsa()?'5G NSA':'5G SA'}. MORAN chung thiết bị nhưng riêng tần số; MOCN chung cả tần số, một cell phát nhiều PLMN và một bộ lập lịch chia PRB. Đổi chế độ 5G SA, 5G NSA, 4G ở trên để thấy tên nút, giao diện và bản tin đổi theo.`;
  if(v==='arch'){
    const ks=Object.keys(RSM),m=ks[i],sh=m!=='site',sp=m==='mocn'||m==='gwcn',gw=m==='gwcn';let s='';
    const two=(y,h,ta,tb2,sub)=>bx(20,y,150,h,ta,{c:cA,w:2,fs:10,sub})+bx(190,y,150,h,tb2,{c:cB,w:2,fs:10,sub});
    const one=(y,h,t,sub)=>bx(20,y,320,h,t,{c:cS,w:2.4,fs:10.5,sub});
    s+=gw&&!lteM&&!g4?one(8,34,'Không áp dụng cho 5G','5G chỉ chuẩn hoá MOCN'):gw?bx(20,8,320,34,'MME dùng chung',{c:cS,w:2.4,sub:'S-GW, P-GW, HSS vẫn riêng'}):two(8,34,`Lõi ${rsCore()} của A`,`Lõi ${rsCore()} của B`,`${rsCn()}, ${rsGw()}`);
    s+=tx(180,56,sh?`${g4?'S1':'N2, N3'}: tách VLAN và IPsec theo nhà mạng`:'truyền dẫn riêng hoặc thuê chung',{fs:9});
    s+=sp?one(64,36,'Một bộ lập lịch MAC','chia PRB giữa A và B theo hạn mức'):two(64,36,'Bộ lập lịch của A','Bộ lập lịch của B','tham số vô tuyến riêng');
    s+=sp?`<rect x="20" y="108" width="160" height="34" style="fill:${cA};opacity:.8"/><rect x="180" y="108" width="160" height="34" style="fill:${cB};opacity:.8"/>`+tx(180,122,'Một sóng mang chung F',{c:V_('panel'),b:1,fs:10.5})+tx(180,135,'phát cả 452-01 và 452-02',{c:V_('panel'),fs:9}):two(108,34,'Sóng mang F1 · 452-01','Sóng mang F2 · 452-02','');
    s+=sh?one(150,34,`Băng gốc và khối vô tuyến (${rsNode()})`,'phần cứng dùng chung'):two(150,34,'Thiết bị vô tuyến của A','Thiết bị vô tuyến của B','');
    s+=one(192,30,'Cột, nhà trạm, nguồn điện','hạ tầng thụ động');
    s+=`<rect x="20" y="230" width="10" height="10" style="fill:none;stroke:${cA};stroke-width:2"/>`+tx(34,239,'của A',{a:'start',fs:9})+`<rect x="90" y="230" width="10" height="10" style="fill:none;stroke:${cB};stroke-width:2"/>`+tx(104,239,'của B',{a:'start',fs:9})+`<rect x="160" y="230" width="10" height="10" style="fill:none;stroke:${cS};stroke-width:2"/>`+tx(174,239,'dùng chung',{a:'start',fs:9});
    fig=svgw(360,246,s,'Các tầng dùng chung và riêng');RSCAP=`${RSM[m][0]}. ${RSM[m][1]}`;
    const R=[['Cột, nhà trạm, nguồn','Chung','Chung','Chung','Chung'],['Anten, khối vô tuyến, băng gốc','Riêng','Chung','Chung','Chung'],['Tần số (sóng mang)','Riêng','Riêng','Chung','Chung'],['PLMN phát trên một cell','1','1','Nhiều (4G tối đa 6, 5G tối đa 12)','Nhiều'],['Bộ lập lịch và tham số vô tuyến','Riêng','Riêng theo sóng mang','Chung, chia PRB theo hạn mức','Chung'],['Nút điều khiển của lõi','Riêng','Riêng','Riêng','Chung (chỉ 4G)'],['Cổng dữ liệu, cơ sở dữ liệu thuê bao','Riêng','Riêng','Riêng','Riêng']];
    out=kv('Mô hình',RSM[m][0])+R.map(r=>kv(r[0],r[1+i])).join('')+kv('Ưu điểm',['Độc lập hoàn toàn; chỉ tiết kiệm chi phí xây dựng','Độc lập về chất lượng và tham số, không nghẽn chéo; tiết kiệm thiết bị','Hiệu quả phổ cao nhất nhờ gộp băng thông: tốc độ đỉnh cao hơn, lúc bên này vắng bên kia dùng được','Tiết kiệm thêm phần lõi'][i])+kv('Nhược điểm',['Tiết kiệm ít nhất','Phổ của bên vắng khách bị bỏ trống; khối vô tuyến phải đủ rộng băng và công suất cho cả hai','Phải thoả thuận hạn mức, tham số chung, lộ trình nâng cấp; khó tách chất lượng từng bên','Phụ thuộc nhau nhiều nhất; không có ở 5G'][i]);
    info=`<p>${RSM[m][1]}</p><p>3GPP gọi bên vận hành trạm là <b>nhà mạng chủ trì</b> (master operator) và các bên còn lại là <b>nhà mạng tham gia</b> (participating operator). Về mặt chuẩn, <b>MOCN</b> và <b>GWCN</b> được định nghĩa trong TS 23.251 cho 2G đến 4G; với 5G, TS 23.501 mục 5.18 chỉ định nghĩa <b>5G MOCN</b>. <b>MORAN</b> không phải khái niệm của 3GPP: với UE và lõi, đó chỉ là hai cell bình thường của hai mạng khác nhau, việc dùng chung phần cứng là chuyện triển khai của vendor. Ở 5G NSA, cả eNB lẫn en-gNB đều có thể chia sẻ, và hai nhà mạng nối về hai EPC.</p><p>Chạy từng bước để đi qua bốn mức chia sẻ, từ ít tới nhiều.</p>${rsNote}`;
    tt='Bốn mức chia sẻ';tb=tbl(['','Chỉ hạ tầng','MORAN','MOCN','GWCN'],R);
  }else if(v==='sib'){
    const mocn=M==='mocn',multi=mocn&&S.rsCellId==='multi'&&!g4,ue=S.rsUe,pick=ue==='A'?'A':'B',o=RSO[pick],res=S.rsRes&&pick==='B',L=[];
    if(g4){L.push('SystemInformationBlockType1','  cellAccessRelatedInfo','    plmn-IdentityList  (tối đa 6)');
      if(mocn){L.push('      [1] plmn-Identity: mcc 452, mnc 01','          cellReservedForOperatorUse: notReserved','      [2] plmn-Identity: mcc 452, mnc 02',`          cellReservedForOperatorUse: ${S.rsRes?'reserved':'notReserved'}`,'    trackingAreaCode: 1001   (chung)','    cellIdentity: eNB 5001, cell 1   (chung)');}
      else L.push(`      [1] plmn-Identity: mcc 452, mnc ${o[1].slice(4)}`,`          cellReservedForOperatorUse: ${res?'reserved':'notReserved'}`,`    trackingAreaCode: ${o[3]}`,`    cellIdentity: eNB 5001, cell ${pick==='A'?1:2}`,`  freqBandIndicator, tần số ${pick==='A'?'F1':'F2'}`);
    }else{L.push('SIB1','  cellAccessRelatedInfo','    plmn-IdentityInfoList  (tối đa 12 PLMN)');
      if(mocn){L.push('      PLMN-IdentityInfo [1]','        plmn-IdentityList: [ mcc 452, mnc 01 ]','        trackingAreaCode: 1001',`        cellIdentity: ${multi?'gNB 1001, cell 1':'gNB 5001, cell 1'}`,'        cellReservedForOperatorUse: notReserved','      PLMN-IdentityInfo [2]','        plmn-IdentityList: [ mcc 452, mnc 02 ]','        trackingAreaCode: 2002',`        cellIdentity: ${multi?'gNB 2002, cell 1':'gNB 5001, cell 1'}`,`        cellReservedForOperatorUse: ${S.rsRes?'reserved':'notReserved'}`,'  uac-BarringInfo','    uac-BarringPerPLMN-List: riêng từng PLMN');}
      else L.push('      PLMN-IdentityInfo [1]',`        plmn-IdentityList: [ mcc 452, mnc ${o[1].slice(4)} ]`,`        trackingAreaCode: ${o[3]}`,`        cellIdentity: gNB 5001, cell ${pick==='A'?1:2}`,`        cellReservedForOperatorUse: ${res?'reserved':'notReserved'}`,`  tần số SSB ${pick==='A'?'F1':'F2'}`);}
    fig=`<p class="hint" style="margin:0 0 6px">${mocn?'Nội dung SIB1 của cell dùng chung':`Nội dung SIB1 của cell trên sóng mang ${pick==='A'?'F1 (của A)':'F2 (của B)'}`}</p>`+rsPre(L);
    const why=ue==='C'?'Máy không thấy mạng nhà. Lớp NAS chọn theo danh sách mạng ưu tiên trong SIM: mạng nhà của khách có thoả thuận với B nên chọn 452-02.':`Lớp AS đọc SIB1 và báo lên NAS mọi PLMN tìm thấy. NAS thấy mạng nhà ${o[1]} nên chọn ngay.`;
    RSCAP=res?`Máy ${ue==='C'?'khách':'của '+o[0]} chọn ${o[1]} nhưng cell đang dành riêng cho nhà mạng B thử nghiệm: máy thường coi cell như bị cấm.`:`${why} Máy sẽ báo chỉ số ${mocn?(pick==='A'?1:2):1} trong bản tin ${g4?'RRCConnectionSetupComplete':'RRCSetupComplete'}.`;
    out=kv('Máy',C.rsUe.o().find(q=>q[0]===ue)[1])+kv('PLMN được chọn',o[1]+' ('+o[0]+')')+kv('Vì sao',why)+kv('selectedPLMN-Identity sẽ gửi',mocn?(pick==='A'?'1':'2'):'1')+kv('Vùng theo dõi của máy',`${o[1]}, TAC ${mocn&&g4?'1001':o[3]}`)+kv('Cắm trại được không',res?'Không: cell dành riêng cho nhà mạng dùng, chỉ lớp truy nhập 11 và 15 của mạng nhà vào được':'Được')+kv('Tên mạng hiện trên máy',`của ${o[0]}: người dùng không biết trạm là dùng chung`);
    info=`<p>Ở <b>MOCN</b>, một cell phát danh sách PLMN trong SIB1. <b>4G:</b> tối đa 6 PLMN, và cả cell chỉ có một TAC, một định danh cell. <b>5G:</b> tối đa 12 PLMN, chia thành các nhóm PLMN-IdentityInfo; mỗi nhóm có TAC, RANAC, định danh cell và cờ dành riêng của nó. Nhờ vậy 5G có hai kiểu: <b>cùng định danh cell</b> cho mọi nhà mạng, hoặc <b>nhiều định danh cell</b>, khi đó mỗi nhà mạng thấy trạm như một gNB logic của riêng mình với gNB ID riêng. Mọi cell trong cùng một vùng theo dõi phải phát cùng tập nhà mạng.</p><p>Ở <b>MORAN</b>, mỗi sóng mang là một cell độc lập với một PLMN; UE không biết có chia sẻ.</p><p>Mọi UE 4G và 5G đều hiểu danh sách nhiều PLMN (khác với 3G, nơi máy đời cũ chỉ đọc PLMN chung). Chặn truy nhập (UAC ở 5G, ACB ở 4G) cũng đặt được riêng từng PLMN, nên một nhà mạng quá tải không kéo theo bên kia. Mạng riêng cũng chia sẻ được theo cùng cách: SIB1 có thêm danh sách NPN với NID hoặc CAG.</p>${rsNote}`;
  }else if(v==='sig'){
    const L=rsSig(),st=L[i],pick=S.rsUe==='A'?'A':'B',X={ue:36,ran:140,A:248,B:326},cx=n=>n==='cn'?X[pick]:n==='ot'?X[pick==='A'?'B':'A']:X[n];let s='';
    s+=bx(8,6,56,24,'UE',{c:V_(RSO[pick][2]),w:2})+bx(96,6,88,24,rsNode(),{sub:'',c:V_('nr'),w:2,fs:10})+bx(214,6,68,24,`${rsCn()} A`,{c:cA,w:pick==='A'?2.4:1,fs:10})+bx(292,6,68,24,`${rsCn()} B`,{c:cB,w:pick==='B'?2.4:1,fs:10});
    for(const k in X)s+=li([[X[k],30],[X[k],40+L.length*19]],{c:V_('line')});
    L.forEach((m,k)=>{const y=46+k*19,on=k<=i,c=k===i?V_('warn'):on?V_('muted'):V_('line'),w=k===i?2.6:1.3,arrow=(a,b)=>li([[a,y],[b,y]],{c,w})+`<path d="M${b} ${y} l${b>a?-6:6} -3.5 v7z" style="fill:${c}"/>`;
      if(m[0]===m[1])s+=`<rect x="${cx(m[0])-62}" y="${y-7}" width="124" height="13" rx="4" style="fill:${V_('panel')};stroke:${c};stroke-width:${w}"/>`+tx(cx(m[0]),y+3,m[2].slice(0,30),{fs:7.5,b:k===i,c:on?V_('ink'):V_('muted')});
      else if(m[1]==='both')s+=arrow(X.ran,X.A)+arrow(X.ran,X.B)+tx((X.ran+X.A)/2,y-3,m[2].split(' /')[0],{fs:7.5,b:k===i,c:on?V_('ink'):V_('muted')});
      else{const a=cx(m[0]),b=cx(m[1]);s+=arrow(a,b)+tx((a+b)/2,y-3,m[2].length>30?m[2].slice(0,29)+'…':m[2],{fs:7.5,b:k===i,c:on?V_('ink'):V_('muted')});}
      s+=`<rect x="0" y="${y-9}" width="360" height="18" data-rss="${k}" style="fill:transparent;cursor:pointer"/>`;});
    fig=svgw(360,48+L.length*19,s,'Luồng báo hiệu truy nhập trong RAN dùng chung');RSCAP=`${st[2]} (${st[3]}): ${st[4]}`;
    out=kv('Bước',`${i+1} trên ${L.length}`)+kv('Bản tin',st[2])+kv('Giao thức',st[3])+kv('Ý nghĩa',st[4]);
    info=`<h3>Giải mã các trường liên quan tới chia sẻ</h3><div class="scroll"><table>${tbl(['Trường tin','Giá trị trong ví dụ'],st[5])}</table></div><p style="margin-top:10px">Điểm khác của MOCN so với mạng thường chỉ nằm ở ba chỗ: <b>SIB1</b> phát nhiều PLMN; UE báo <b>selectedPLMN-Identity</b> khi hoàn tất lập kết nối RRC; và trạm <b>chọn lõi theo PLMN đó</b> rồi ghi PLMN ấy vào vị trí của máy gửi lên lõi. Sau đó mọi thứ giống hệt mạng riêng: lõi của mỗi nhà mạng không cần biết trạm đang phục vụ cả nhà mạng khác. Ở MORAN thì trạm khỏi phải chọn: cell nào về lõi nấy.</p><p class="note">Chạm vào một dòng trên hình để xem bản tin đó. Giá trị các trường là ví dụ. Thủ tục đăng ký đầy đủ với mọi bản tin nằm ở thẻ Báo hiệu.</p>${rsNote}`;
  }else if(v==='sched'){
    const E=env(),r=rsShare(i),mor=M==='moran',N=E.nrb,nA=Math.floor(S.rsAlpha/100*N),nB=Math.floor((100-S.rsAlpha)/100*N),X=h=>26+h*13.6,Y=p=>14+(100-p)*1.3;let s='',tS=0,tD=0,tM=0;
    for(let h=0;h<24;h++){const q=rsShare(h),keepM=S.rsModel,keepP=S.rsPol;S.rsModel='moran';const m0=rsShare(h);S.rsModel=keepM;S.rsPol=keepP;tS+=q.sA+q.sB;tD+=q.dA+q.dB;tM+=m0.sA+m0.sB;
      s+=`<rect x="${X(h)}" y="${Y(q.sA)}" width="12" height="${q.sA*1.3}" style="fill:${cA};opacity:${h===i?1:0.6}"/><rect x="${X(h)}" y="${Y(q.sA+q.sB)}" width="12" height="${q.sB*1.3}" style="fill:${cB};opacity:${h===i?1:0.6}"/>`
       +(q.dA+q.dB>q.sA+q.sB+0.5?`<rect x="${X(h)}" y="6" width="12" height="5" style="fill:${V_('warn')}"/>`:'')+`<rect x="${X(h)}" y="6" width="13.6" height="140" data-rss="${h}" style="fill:transparent;cursor:pointer"/>`+(h%3===0?tx(X(h)+6,158,h+'h',{fs:8.5}):'');}
    s+=li([[26,Y(100)],[352,Y(100)]],{c:V_('ink')})+li([[26,Y(0)],[352,Y(0)]],{c:V_('ink')})+(mor||S.rsPol!=='pool'?li([[26,Y(S.rsAlpha)],[352,Y(S.rsAlpha)]],{c:V_('muted'),d:'4 3'})+tx(352,Y(S.rsAlpha)-2,mor?'ranh giới hai sóng mang':'hạn mức của A',{a:'end',fs:8}):'')+tx(22,Y(100)+3,'100',{a:'end',fs:8})+tx(22,Y(0)+3,'0',{a:'end',fs:8})+li([[X(i)+6,4],[X(i)+6,150]],{c:V_('ink'),w:1.4})
     +`<rect x="26" y="166" width="10" height="8" style="fill:${cA}"/>`+tx(40,174,'A dùng',{a:'start',fs:9})+`<rect x="100" y="166" width="10" height="8" style="fill:${cB}"/>`+tx(114,174,'B dùng',{a:'start',fs:9})+`<rect x="176" y="166" width="10" height="8" style="fill:${V_('warn')}"/>`+tx(190,174,'giờ có lưu lượng bị nghẽn',{a:'start',fs:9});
    fig=svgw(360,180,s,'PRB hai nhà mạng dùng theo giờ');
    RSCAP=`${i} giờ: A cần ${f0(r.dA)} %, được ${f0(r.sA)} %; B cần ${f0(r.dB)} %, được ${f0(r.sB)} %; còn trống ${f0(r.free)} %.`;
    out=kv('Lúc',i+' giờ')+kv('Nhà mạng A',`cần ${f0(r.dA)} %, được ${f0(r.sA)} % (${f0(r.sA/100*N)} PRB)${r.sA<r.dA-0.5?', nghẽn':''}`)+kv('Nhà mạng B',`cần ${f0(r.dB)} %, được ${f0(r.sB)} % (${f0(r.sB/100*N)} PRB)${r.sB<r.dB-0.5?', nghẽn':''}`)+kv('PRB bỏ trống',f0(r.free)+' %')+kv('Tốc độ đỉnh một máy của A, của B',`${f0(E.peakDL*r.pkA/100)} và ${f0(E.peakDL*r.pkB/100)} Mbit/s`)
     +'<div class="sep"></div>'+kv(mor?'Hai sóng mang':'Hạn mức tĩnh theo công thức',`A: ⌊${S.rsAlpha/100} × ${N}⌋ = ${nA} PRB; B: ${nB} PRB`)+kv('Cả ngày: lưu lượng được phục vụ',f0(tS/tD*100)+' % nhu cầu')+kv('So với MORAN cùng tỉ lệ chia',mor?'—':`phục vụ thêm ${f1((tS-tM)/Math.max(tM,1)*100)} % lưu lượng`);
    info=`<p>Hai nhà mạng thường đông khách vào giờ khác nhau: ở đây A đông buổi trưa (khu văn phòng), B đông buổi tối (khu dân cư). ${mor?'<b>MORAN</b> chia cứng theo tần số: PRB của sóng mang bên này bỏ trống thì bên kia cũng không dùng được, và tốc độ đỉnh của mỗi máy bị giới hạn bởi băng thông sóng mang của mạng mình.':'<b>MOCN</b> cho một bộ lập lịch chia PRB của sóng mang chung. Ba chính sách: <b>tĩnh</b> giống MORAN về dung lượng; <b>động</b> bảo đảm cho mỗi bên phần tối thiểu khi cả hai cùng đông và cho mượn phần thừa khi một bên vắng; <b>gộp hoàn toàn</b> thì không bảo vệ bên nào khi nghẽn.'}</p><p>Phần lợi của việc gộp gọi là <b>lợi ích trung kế</b>: cùng số PRB nhưng phục vụ được nhiều lưu lượng hơn và tốc độ đỉnh cao hơn. Đổi sang MORAN rồi về MOCN động để so.</p><p><b>Theo 3GPP:</b> 4G không chuẩn hoá cách chia. 5G có mô hình quản lý trong TS 28.541: mỗi chính sách RRM gắn với một danh sách thành viên gồm PLMN và S-NSSAI, kèm ba tỉ lệ <b>dành riêng</b>, <b>tối thiểu</b> và <b>tối đa</b>; chia theo nhà mạng chính là chia theo PLMN trong danh sách đó. Bộ đếm hiệu năng cũng được tách theo PLMN để đối soát hợp đồng.</p><p class="note">Băng thông và số PRB lấy từ ô Cấu hình cell. Ở MORAN, mô hình coi tổng băng thông đó được chia thành hai sóng mang theo tỉ lệ α. Hai đường nhu cầu theo giờ là giả định.</p>${rsNote}`;
  }else{
    RSCAP='Các vấn đề vận hành của RAN dùng chung và cách ba vendor cấu hình.';
    const V=S.vendor,sa=!nsa(),cfg={
     huawei:lteM||g4?['// LTE: khai nhà mạng và chế độ chia sẻ (tên lệnh ghi theo hiểu biết chung)','MOD ENODEBSHARINGMODE: ENodeBSharingMode='+(M==='moran'?'SEPARATED_FREQ':'SHARED_FREQ')+';','ADD CNOPERATOR: CnOperatorId=0, CnOperatorName="A", CnOperatorType=CNOPERATOR_PRIMARY, Mcc="452", Mnc="01";','ADD CNOPERATOR: CnOperatorId=1, CnOperatorName="B", CnOperatorType=CNOPERATOR_SECONDARY, Mcc="452", Mnc="02";','ADD CNOPERATORTA: TrackingAreaId=0, CnOperatorId=0, Tac=1001;','ADD CNOPERATORTA: TrackingAreaId=1, CnOperatorId=1, Tac=1001;',M==='moran'?'ADD CELLOP: LocalCellId=1, TrackingAreaId=0;   // cell F1 của A\nADD CELLOP: LocalCellId=2, TrackingAreaId=1;   // cell F2 của B':`ADD CELLOP: LocalCellId=1, TrackingAreaId=0, OpDlRbUsedRatio=${S.rsAlpha}, OpUlRbUsedRatio=${S.rsAlpha};\nADD CELLOP: LocalCellId=1, TrackingAreaId=1, OpDlRbUsedRatio=${100-S.rsAlpha}, OpUlRbUsedRatio=${100-S.rsAlpha};`,'// mỗi nhà mạng một liên kết S1 riêng, gắn theo CnOperatorId']
       :['// NR: khai nhà mạng và chế độ chia sẻ (tên lệnh ghi theo hiểu biết chung)','MOD GNBSHARINGMODE: gNBMultiOpSharingMode='+(M==='moran'?'SEPARATED_FREQ':'SHARED_FREQ')+';','ADD GNBOPERATOR: OperatorId=0, OperatorName="A", Mcc="452", Mnc="01", OperatorType=PRIMARY_OPERATOR;','ADD GNBOPERATOR: OperatorId=1, OperatorName="B", Mcc="452", Mnc="02", OperatorType=SECONDARY_OPERATOR;','ADD GNBTRACKINGAREA: TrackingAreaId=0, Tac=1001;','ADD GNBTRACKINGAREA: TrackingAreaId=1, Tac=2002;','// gắn nhà mạng vào cell CU và DU, kèm tỉ lệ PRB của từng nhà mạng (đối tượng dạng NRDUCellOp)','// mỗi nhà mạng một liên kết NG riêng, gắn theo OperatorId'],
     nokia:lteM||g4?['// LTE (tên tham số ghi theo hiểu biết chung)','LNBTS: bật tính năng chia sẻ RAN (tên công tắc theo release)','LNCEL: mcc=452, mnc=01                 // PLMN chính',M==='moran'?'LNCEL (cell F2): mcc=452, mnc=02          // cell riêng của B':'LNCEL: furtherPlmnIdL = [ {452, 02} ]    // PLMN phát thêm','LNMME: mỗi MME khai PLMN mà nó phục vụ (S1-flex)',M==='moran'?'':'Hồ sơ chia dung lượng theo PLMN: tỉ lệ A '+S.rsAlpha+' %, B '+(100-S.rsAlpha)+' %']
       :['// NR (tên tham số ghi theo hiểu biết chung)','NRBTS: mcc=452, mnc=01                  // PLMN chính của gNB',M==='moran'?'NRCELL (cell F2): danh sách PLMN = [ {452, 02} ]':'NRCELL: danh sách PLMN phát thêm = [ {452, 02} ], kèm TAC riêng','NRBTS: mỗi liên kết NG gắn với PLMN của AMF tương ứng',M==='moran'?'':'Nhóm chính sách RRM theo PLMN: tỉ lệ A '+S.rsAlpha+' %, B '+(100-S.rsAlpha)+' %'],
     ericsson:lteM||g4?['// LTE (tên thuộc tính ghi theo hiểu biết chung, trừ endcAllowedPlmnList có trong tài liệu Ericsson đã đọc)','ENodeBFunction: eNodeBPlmnId = {mcc 452, mnc 01}',M==='moran'?'EUtranCellFDD=F1: activePlmnList = [452-01]\nEUtranCellFDD=F2: activePlmnList = [452-02]':'EUtranCellFDD=1: additionalPlmnList = [452-02], activePlmnList = [452-01, 452-02]','TermPointToMme: mỗi MME một điểm kết cuối; MME báo PLMN nó phục vụ',endc()?'EUtranCellFDD=1: endcAllowedPlmnList = [452-01, 452-02]   // PLMN nào được dùng EN-DC':'',M==='moran'?'':'Chia tài nguyên theo PLMN: phần của A '+S.rsAlpha+' %, của B '+(100-S.rsAlpha)+' %']
       :['// NR (tên thuộc tính ghi theo hiểu biết chung)','GNBCUCPFunction: pLMNId = {mcc 452, mnc 01}',M==='moran'?'NRCellCU=F1: pLMNIdList = [452-01]\nNRCellCU=F2: pLMNIdList = [452-02]':'NRCellCU=1: pLMNIdList = [452-01]; AdditionalPLMNInfo: pLMNIdList = [452-02], nRTAC = 2002','TermPointToAmf: mỗi AMF một điểm kết cuối',M==='moran'?'':'NR Radio Resource Partitioning (FAJ 121 5337): phân vùng theo PLMN, A '+S.rsAlpha+' %, B '+(100-S.rsAlpha)+' %'],
     '3gpp':lteM||g4?['// 4G: 3GPP chuẩn hoá phần báo hiệu (TS 23.251, 36.331, 36.413), không chuẩn hoá cách chia dung lượng',M==='moran'?'SIB1 của cell F1: plmn-IdentityList = [452-01]; của cell F2: [452-02]':'SIB1: plmn-IdentityList = [452-01, 452-02], một TAC chung','S1 Setup: Supported TAs kèm Broadcast PLMNs; mỗi MME trả Served GUMMEIs','Chia PRB giữa các nhà mạng: do vendor cài đặt']:['// TS 28.541: mô hình quản lý của NR','NRCellDU: pLMNInfoList = [ {452-01, S-NSSAI}, {452-02, S-NSSAI} ]',M==='moran'?'// MORAN: hai NRCellDU trên hai tần số, mỗi cell một PLMN':`RRMPolicyRatio (A): rRMPolicyMemberList = [452-01], rRMPolicyMinRatio = ${S.rsAlpha}, rRMPolicyMaxRatio = 100`,M==='moran'?'':`RRMPolicyRatio (B): rRMPolicyMemberList = [452-02], rRMPolicyMinRatio = ${100-S.rsAlpha}, rRMPolicyMaxRatio = 100`,'EP_NgC, EP_NgU: mỗi nhà mạng một điểm cuối riêng tới lõi của mình']}[V];
    const ISS=[['Chất lượng từng bên','Bộ đếm và KPI tách theo PLMN; đối soát hạn mức theo hợp đồng'],['Chặn truy nhập khi quá tải','Chặn riêng từng PLMN trong SIB1 (UAC ở 5G, ACB ở 4G)'],['Di động và lân cận','Chỉ chuyển giao tới cell có PLMN phục vụ hoặc tương đương; khai lân cận về mạng riêng của từng bên; ưu tiên tần số theo thuê bao (SPID, RFSP)'],['Truyền dẫn','VLAN, địa chỉ IP, IPsec và QoS riêng cho từng nhà mạng'],['Cắt lát mạng (5G SA)','Mỗi PLMN khai danh sách S-NSSAI riêng; chính sách RRM gắn với cặp PLMN và S-NSSAI'],['Thoại và dịch vụ khẩn cấp','Mỗi bên dùng IMS riêng; cuộc gọi khẩn cấp đi theo PLMN đã chọn'],['Tiết kiệm điện','Tắt sóng mang hay nhánh phát ảnh hưởng cả hai bên: phải thống nhất ngưỡng; ở MORAN tắt riêng được từng sóng mang'],['Nâng cấp và tính năng','Phần mềm, giấy phép tính năng và tham số chung phải thoả thuận; bên chủ trì vận hành, bên tham gia xem được số liệu của mình'],['Cảnh báo và cấu hình','Bên chủ trì quản lý trạm; mở cho bên tham gia quyền xem cảnh báo và hiệu năng phần của họ']];
    info=`<h3>Cấu hình mẫu theo ${VN[V].n}: ${M==='moran'?'MORAN':'MOCN'}, ${lteM?'4G':g4?'5G NSA (phía LTE)':'5G SA'}</h3>${rsPre(cfg.filter(Boolean))}<p class="note">Sinh theo mô hình, chế độ và tỉ lệ α đang chọn. Đổi vendor ở thanh trên để xem cú pháp khác.</p><h3 style="margin-top:14px">Những việc phải thống nhất khi vận hành</h3>${tbl0(['Vấn đề','Cách xử lý'],ISS)}<h3 style="margin-top:14px">Ba vendor</h3>${tbl0(['','Huawei','Nokia','Ericsson'],[['Tên tính năng cho MOCN','RAN Sharing with Common Carrier (LTE); Multi-Operator Sharing (NR)','Multi-Operator Core Network (MOCN) cho LTE và 5G','Shared LTE RAN, Shared NR RAN (Multi-Operator Core Network)'],['Tên tính năng cho MORAN','RAN Sharing with Dedicated Carrier; Hybrid RAN Sharing (lai cả hai)','Multi-Operator RAN (MORAN)','Multi-Operator RAN'],['Chia dung lượng','Tỉ lệ PRB theo nhà mạng trên từng cell','Hồ sơ chia dung lượng theo PLMN','Phân vùng tài nguyên vô tuyến theo PLMN'],['Triển khai đã công bố','—','MOCN từ 2G đến 5G với Telenor và Telia ở Đan Mạch','MORAN 5G với KDDI và SoftBank ở Nhật; MOCN 5G với APT ở Đài Loan']])}${rsNote}`;
  }
  $('#rsFig').innerHTML=fig;$('#rsFig').parentElement.style.display=fig?'':'none';$('#rsFigT').textContent=RSHV[v];$('#rsOut').innerHTML=out;$('#rsOut').parentElement.style.display=out?'':'none';$('#rsInfo').innerHTML=info;$('#rsTbl').innerHTML=tb;$('#rsTbl').closest('.panel').style.display=tb?'':'none';$('#rsTblT').textContent=tt;
}
const rsNote='<p class="note">Nội dung theo báo cáo RAN Sharing 4G/5G bạn cung cấp và các chuẩn 3GPP TS 23.251, 23.501, 38.300, 38.331, 36.331, 28.541. Tên tính năng, lệnh và tham số của Huawei, Nokia, Ericsson ghi theo hiểu biết chung, chưa đối chiếu tài liệu chính hãng.</p>';
TOUR.rsh={hold:2600,n:rsN,idx:()=>clamp(S.rsStep,0,rsN()-1),set:i=>{S.rsStep=i;if(S.rsV==='arch'){S.rsModel=Object.keys(RSM)[i];if(S.share!=='none'&&(S.rsModel==='moran'||S.rsModel==='mocn'))S.share=S.rsModel;}},cap:()=>RSCAP};
/* ---------- MORAN và MOCN là chế độ ngang cấp với 5G SA, 5G NSA, 4G: mỗi thẻ có thêm phần riêng cho mạng dùng chung ---------- */
S.share='none';
const SHN={moran:'MORAN',mocn:'MOCN'};
/* mượn hình và bảng đã dựng ở thẻ Chia sẻ RAN */
function shGrab(view,step,sel){const k=[S.rsV,S.rsStep];S.rsV=view;S.rsStep=step;renderRsh();const el=$(sel),h=el?(sel==='#rsFig'?el.innerHTML:el.outerHTML):'';S.rsV=k[0];S.rsStep=k[1];renderRsh();return h;}
const shUl=a=>`<ul class="bk">${a.filter(Boolean).map(t=>`<li><p class="bk-f">${t}</p></li>`).join('')}</ul>`;
function shareHtml(tab){
  const m=S.share,mo=m==='mocn',E=env(),g4=nsa(),lteM=lte(),nd=rsNode(),cn=rsCn(),gw=rsGw(),ifc=g4?'S1':'NG (N2, N3)',a=S.rsAlpha,nA=Math.floor(a/100*E.nrb),nB=Math.floor((100-a)/100*E.nrb),bwA=f0(S.bw*a/100),bwB=f0(S.bw*(100-a)/100);
  const hd=`${SHN[m]} trên ${lteM?'4G':g4?'5G NSA':'5G SA'}`;
  switch(tab){
   case 'arch':return{t:`${hd}: kiến trúc`,fig:shGrab('arch',mo?2:1,'#rsFig'),txt:shUl([`Sơ đồ bên dưới là bên trong của trạm ${nd} dùng chung: mọi khối CU, DU, RU${lteM?' (BBU, RRU)':''} đều phục vụ cả hai nhà mạng.`,mo?'Một cell phát cả PLMN 452-01 và 452-02; một bộ lập lịch chia PRB theo hạn mức.':'Mỗi nhà mạng một sóng mang, tức một cell riêng với PLMN riêng; hai cell chạy trên cùng băng gốc và cùng khối vô tuyến.',`Trạm có hai bộ giao diện ${ifc}, mỗi bộ về lõi ${rsCore()} của một nhà mạng.`,!g4&&mo?'Nếu phát nhiều định danh cell, mỗi nhà mạng thấy trạm như một gNB logic riêng; F1 giữa CU và DU có thể dùng chung hoặc riêng đường truyền báo hiệu.':'',endc()?'Ở NSA cả eNB lẫn en-gNB đều có thể dùng chung; X2 giữa chúng là nội bộ, còn S1-U của nút phụ đi về S-GW của đúng nhà mạng.':''])};
   case 'core':{const nodes=[['ua',8,150,60,24,'Máy của A','',V_('up'),9.5],['ub',8,186,60,24,'Máy của B','',V_('cp'),9.5],['ran',96,164,72,34,nd,'dùng chung',V_('nr'),10],['ca',204,60,64,28,cn+' A','',V_('up')],['ga',204,104,64,26,gw+' A','',V_('up')],['ha',284,60,68,28,g4?'HSS A':'UDM A','',V_('up')],['cb',204,170,64,28,cn+' B','',V_('cp')],['gb',204,214,64,26,gw+' B','',V_('cp')],['hb',284,170,68,28,g4?'HSS B':'UDM B','',V_('cp')]];
      const links=[['ua','ran','',V_('up')],['ub','ran','',V_('cp')],['ran','ca',g4?'S1-MME':'N2',V_('up')],['ran','ga',g4?'S1-U':'N3',V_('up')],['ran','cb',g4?'S1-MME':'N2',V_('cp')],['ran','gb',g4?'S1-U':'N3',V_('cp')],['ca','ha','',V_('up')],['cb','hb','',V_('cp')]];
      return{t:`${hd}: hai mạng lõi sau một trạm`,fig:flowFig(360,248,nodes,links,['ran'],['ua-ran','ub-ran','ran-ca','ran-ga','ran-cb','ran-gb','ca-ha','cb-hb'],'Hai lõi sau trạm dùng chung'),txt:shUl([`Sơ đồ lõi chi tiết bên dưới là lõi của <b>một</b> nhà mạng; lõi của bên kia có cấu trúc y hệt và hoàn toàn tách biệt.`,mo?`Trạm chọn ${cn} theo PLMN mà máy báo trong bản tin hoàn tất lập kết nối RRC (selectedPLMN-Identity), rồi mới xét ${g4?'GUMMEI':'GUAMI và lát cắt'} và trọng số tải.`:`Trạm không phải chọn: cell trên sóng mang của nhà mạng nào thì nối về ${cn} của nhà mạng đó.`,'Lõi không cần sửa gì: nó thấy máy ở trong vùng theo dõi mang PLMN của chính nó. Xác thực, tính cước, IMS, chính sách đều của riêng từng nhà mạng.',g4?'Riêng 4G còn kiểu GWCN: dùng chung luôn MME, chỉ S-GW, P-GW và HSS là riêng.':'5G chỉ chuẩn hoá MOCN; không có kiểu dùng chung AMF giữa hai nhà mạng.','Trên truyền dẫn, lưu lượng hai bên tách bằng VLAN, địa chỉ IP và IPsec riêng.'])};}
   case 'radio':return{t:`${hd}: vùng phủ và quảng bá`,fig:shGrab('sib',0,'#rsFig'),txt:shUl([mo?`Hai nhà mạng có vùng phủ giống hệt nhau vì cùng một cell: cùng mức thu, cùng nhiễu, cùng tham số chuyển giao.`:`Hai sóng mang phát từ cùng anten nên vùng phủ gần như nhau, nhưng mỗi bên tự đặt công suất, độ nghiêng điện (nếu anten cho phép) và tham số chuyển giao.`,mo?`Cả ${S.bw} MHz và toàn bộ công suất ${f1(E.pTot)} dBm dồn cho một sóng mang.`:`Nếu dùng chung một khối vô tuyến, công suất ${f1(E.pTot)} dBm phải chia cho hai sóng mang: mỗi sóng mang khoảng ${f1(E.pTot-3)} dBm, mức thu thấp hơn chừng 3 dB so với khi một mình dùng cả khối.`,'Quan hệ lân cận phải khai theo PLMN: máy của A chỉ được chuyển giao tới cell có phát PLMN của A hoặc PLMN tương đương; ra khỏi vùng chia sẻ thì về mạng riêng của A.','Chặn truy nhập khi quá tải đặt riêng từng PLMN ngay trong SIB1.'])};
   case 'frame':return{t:`${hd}: khung và lưới tài nguyên`,txt:shUl([mo?`Chỉ có một lưới tài nguyên ${S.bw} MHz, ${E.nrb} PRB. SSB, SIB1, PDCCH chung, tín hiệu tham chuẩn chỉ tốn một lần cho cả hai nhà mạng.`:`Hai lưới tài nguyên độc lập: sóng mang của A khoảng ${bwA} MHz, của B khoảng ${bwB} MHz (tính theo tỉ lệ α ở thẻ Chia sẻ RAN). Mỗi lưới có SSB, SIB1 và kênh điều khiển riêng, nên phần overhead tốn hai lần.`,mo?`SIB1 dài hơn một chút vì mang danh sách PLMN${g4?' (tối đa 6)':' (tối đa 12), mỗi PLMN có TAC và định danh cell riêng'}.`:'Mỗi SIB1 chỉ có một PLMN.',isTDD()?'Hai sóng mang TDD cùng băng trên một khối vô tuyến buộc phải cùng mẫu khe và cùng đồng bộ; hai nhà mạng phải thống nhất tỉ lệ đường lên và đường xuống.':'Với FDD, mỗi sóng mang có cặp tần số riêng.',mo?'Numerology, mẫu khe, cấu hình SSB là tham số chung: đổi là ảnh hưởng cả hai bên.':''])};
   case 'prb':return{t:`${hd}: chia PRB giữa hai nhà mạng`,fig:shGrab('sched',13,'#rsFig'),txt:shUl([mo?`Bộ lập lịch ở thẻ này là một, phục vụ máy của cả hai nhà mạng. Trước khi cấp PRB cho một máy, nó xem máy thuộc PLMN nào (biết từ lúc lập ngữ cảnh) và trừ vào hạn mức của nhà mạng đó: A ${nA} PRB, B ${nB} PRB khi cả hai cùng đông.`:`Mỗi sóng mang có bộ lập lịch riêng như ở thẻ này: của A trên ${nA} PRB, của B trên ${nB} PRB. Không bên nào dùng được PRB trống của bên kia.`,mo?'Bên trong hạn mức của mỗi nhà mạng, thuật toán vẫn là PF, luân phiên hoặc Max C/I như thường; lát cắt của từng nhà mạng lại chia tiếp trong phần của họ.':'Thuật toán lập lịch và tham số QoS do từng nhà mạng tự chọn.','Hình trên là mức dùng PRB theo giờ; đổi chính sách và tỉ lệ ở thẻ Chia sẻ RAN.'])};
   case 'ca':return{t:`${hd}: ghép sóng mang`,txt:shUl([mo?'Sóng mang dùng chung có thể làm PCell hoặc SCell cho máy của cả hai nhà mạng. Kiểu lai cũng phổ biến: một sóng mang dùng chung (MOCN) ghép với sóng mang riêng của từng nhà mạng.':'Mỗi nhà mạng chỉ ghép được các sóng mang của chính mình. Sóng mang của bên kia không nằm trong danh sách SCell.',mo?`Tốc độ đỉnh của một máy tính trên cả ${S.bw} MHz khi bên kia vắng: đây là lợi ích chính của MOCN.`:`Tốc độ đỉnh của máy A chỉ tính trên phần ${bwA} MHz của A.`,'SCell được chọn theo PLMN của máy: cell không phát PLMN phục vụ thì không được thêm.'])};
   case 'beam':return{t:`${hd}: anten và tạo chùm`,txt:shUl([mo?'Chùm SSB và mẫu quét là chung. Khi ghép MU-MIMO, bộ lập lịch có thể ghép máy của A với máy của B trên cùng PRB, miễn là hai chùm tách đủ xa.':'Cùng một khối AAU phát hai sóng mang. Điều kiện: dải thông tức thời của AAU phải phủ được cả hai sóng mang, và tổng công suất chia cho hai bên.',mo?'Trọng số tạo chùm cho dữ liệu vẫn tính riêng từng máy, không phụ thuộc máy thuộc nhà mạng nào.':'Mỗi sóng mang có thể đặt mẫu chùm SSB riêng, nhưng góc nghiêng cơ khí và hướng anten là chung.','Hình khối anten ở thẻ này không đổi: chia sẻ chỉ thay đổi phần băng gốc và tần số.'])};
   case 'es':return{t:`${hd}: tiết kiệm điện`,txt:shUl([mo?'Mọi tính năng tắt theo cell (tắt sóng mang, tắt nhánh phát, ngủ sâu) đều ảnh hưởng cả hai nhà mạng: ngưỡng tải phải tính trên tổng lưu lượng của A và B, và hai bên phải thống nhất khung giờ.':'Có thể tắt riêng sóng mang của nhà mạng đang vắng khách trong khi sóng mang kia vẫn chạy. Ngủ sâu cả khối vô tuyến thì vẫn phải chờ cả hai cùng vắng.','Tắt theo ký hiệu (micro sleep) hiệu quả hơn ở MOCN vì lưu lượng hai bên được gom vào một sóng mang, khối khuếch đại không phải thức cho hai bộ tín hiệu quảng bá.','Tiền điện thường chia theo tỉ lệ PRB hoặc lưu lượng của từng PLMN; cần bộ đếm tách theo nhà mạng.'])};
   case 'sig':return{t:`${hd}: báo hiệu truy nhập`,fig:shGrab('sig',S.rsStep,'#rsFig')+shGrab('sig',S.rsStep,'#rsInfo table'),txt:`<p class="hint">Chạm vào một bản tin để xem các trường tin của nó. Các thủ tục ở dưới (đăng ký, phiên dữ liệu, thoại, chuyển giao) diễn ra y như mạng riêng, với lõi của nhà mạng mà máy đã chọn.</p>`};
   case 'stack':return{t:`${hd}: giao thức và truyền dẫn`,txt:shUl([`Chồng giao thức vô tuyến không đổi. Khác biệt nằm ở phía mạng: trạm có hai bộ ${ifc}, mỗi bộ một VLAN, một dải địa chỉ IP và thường một đường hầm IPsec riêng tới lõi của từng nhà mạng.`,`Đường hầm GTP-U của mỗi máy kết cuối ở ${gw} của nhà mạng mà máy thuộc về; QoS trên truyền dẫn (DSCP) cũng đặt riêng.`,'Fronthaul giữa băng gốc và khối vô tuyến là chung: '+(mo?'một luồng IQ cho một sóng mang.':'hai luồng IQ, băng thông fronthaul bằng tổng của hai sóng mang.'),'Đồng bộ thời gian là chung cho cả trạm.'])};
   case 'vendor':return{t:`${hd}: cấu hình theo ${VN[S.vendor].n}`,fig:shGrab('ops',0,'#rsInfo pre'),txt:'<p class="hint">Cấu hình mẫu sinh theo vendor, chế độ và tỉ lệ α đang chọn. Tên lệnh và tham số ghi theo hiểu biết chung.</p>'};
   case 'mob':return{t:`${hd}: di động`,txt:shUl(['Khi lập ngữ cảnh, lõi gửi cho trạm danh sách hạn chế di động: PLMN đang phục vụ và các PLMN tương đương. Trạm chỉ chọn cell đích có phát một trong các PLMN đó.',mo?'Các ngưỡng A2, A5, B1, B2 là của cell nên chung cho cả hai nhà mạng, trừ khi vendor cho đặt theo PLMN hoặc theo nhóm thuê bao.':'Mỗi sóng mang có bộ ngưỡng riêng, nên hai nhà mạng tự đặt chiến lược di động của mình.','Ra khỏi vùng chia sẻ, máy được đưa về tần số riêng của nhà mạng mình bằng ưu tiên tần số theo thuê bao (SPID hoặc RFSP) và lân cận khai theo PLMN.',endc()?'Ở NSA, eNB còn kiểm tra PLMN của máy có nằm trong danh sách được phép EN-DC của cell không rồi mới thêm nút phụ.':''])};
   case 'ims':return imShare(hd);
   case 'book':return{t:`${hd}: các chuyên đề liên quan`,txt:shUl(['Cắt lát mạng: mỗi PLMN khai danh sách S-NSSAI riêng; chính sách chia PRB gắn với cặp PLMN và S-NSSAI.','Mạng riêng: SNPN dùng chung RAN với mạng công cộng cũng là một dạng chia sẻ, SIB1 có thêm NID hoặc CAG.','KPI: bộ đếm phải tách theo PLMN để từng nhà mạng theo dõi chất lượng của mình.'])};
  }
  return null;
}
function shareFill(){
  const box=$('#shareBox'),o=S.share!=='none'&&S.tab!=='rsh'?shareHtml(S.tab):null;box.hidden=!o;if(!o)return;
  box.innerHTML=`<h3>${o.t}</h3>${o.fig||''}${o.txt||''}<p class="note" style="margin-bottom:0">Hai nhà mạng trong ví dụ: A (452-01) và B (452-02). <button type="button" class="lnk" data-tab="rsh">Xem và chỉnh chi tiết ở thẻ Chia sẻ RAN</button></p>`;
}
/* ---------- Chế độ 4G: mạng LTE từ eNB tới lõi EPC ---------- */
const LBANDS={
 b28:{name:'Băng 28 (700 MHz, FDD)',f:780,ear:9430,num:28},b8:{name:'Băng 8 (900 MHz, FDD)',f:945,ear:3650,num:8},
 b3:{name:'Băng 3 (1800 MHz, FDD)',f:1850,ear:1650,num:3},b1:{name:'Băng 1 (2100 MHz, FDD)',f:2140,ear:300,num:1},b7:{name:'Băng 7 (2600 MHz, FDD)',f:2655,ear:3100,num:7}};
const LANT={'2T':{name:'2T2R (RRU hai cổng)',trx:2,g:17.5,lay:2},'4T':{name:'4T4R (RRU bốn cổng)',trx:4,g:18,lay:4},'8T':{name:'8T8R (tám cổng)',trx:8,g:19.5,lay:4}};
const lteOh=()=>(S.pdcch*12+(LANT[S.lAnt].trx>=4?(S.pdcch>=2?16:20):12))/168+0.012;
const lteLay=()=>Math.min(LANT[S.lAnt].lay,S.layers);
const ltePeak=()=>lteLay()*(S.mod===256?8:6)*(948/1024)*LTE.nrb*12*14000*(1-lteOh())/1e6;
const bsN=()=>lte()?'eNB':'gNB';
const destName=()=>DESTN[S.dest].replace(/gNB/g,bsN());

/* giải thích khối ở sơ đồ kiến trúc 4G */
const INFO_L={
 ue:()=>({t:'UE (thiết bị đầu cuối)',d:'Dò tín hiệu đồng bộ PSS/SSS để tìm cell, đọc MIB và SIB, truy nhập ngẫu nhiên rồi lập kết nối RRC với eNB. Sau đó attach vào lõi EPC và nhận một bearer mặc định cùng địa chỉ IP. Khi kết nối, máy đo RSRP và RSRQ của cell đang phục vụ và các cell lân cận rồi báo cho eNB.'}),
 lteuu:()=>({t:'LTE Uu (giao diện vô tuyến)',d:'Đường xuống dùng OFDMA, đường lên dùng SC-FDMA, khoảng cách sóng mang con cố định 15 kHz. Mỗi khung con dài 1 ms; bộ lập lịch của eNB cấp PRB cho từng UE ở mỗi khung con.'}),
 lteru:()=>({t:'RRU và anten',d:'Khối vô tuyến đặt gần anten: chuyển đổi số và tương tự, khuếch đại công suất, lọc. Mỗi cổng anten một bộ khuếch đại (2T2R, 4T4R). Khác 5G, RRU của LTE không xử lý lớp vật lý; toàn bộ băng gốc nằm ở BBU.'}),
 cpri:()=>({t:'CPRI (fronthaul)',d:'Sợi quang nối BBU với RRU, chở mẫu IQ miền thời gian của từng cổng anten. Một cell 20 MHz 2T2R cần khoảng 2,5 Gbit/s.'}),
 enb:()=>({t:'eNB (trạm gốc 4G)',d:'Gồm BBU và các RRU. Khác 3G, LTE không có bộ điều khiển trung gian: eNB tự chạy RRC, PDCP, RLC, MAC và lớp vật lý, tự quyết định handover và lập lịch. Nối MME bằng S1-MME, S-GW bằng S1-U, và các eNB khác bằng X2.'}),
 enb2:()=>({t:'eNB lân cận',d:'Hai eNB nói chuyện trực tiếp qua X2 để chuẩn bị handover, chuyển tiếp dữ liệu còn tồn, trao đổi thông tin tải và phối hợp nhiễu (ICIC).'}),
 x2:()=>({t:'X2',d:'Giao diện giữa hai eNB. X2-C mang báo hiệu X2AP (Handover Request, SN Status Transfer, Load Information). X2-U chở dữ liệu chuyển tiếp trong lúc handover. Thiếu X2 thì handover phải đi vòng qua MME bằng S1.'}),
 s1mme:()=>({t:'S1-MME',d:'Giao diện điều khiển giữa eNB và MME, chạy S1AP trên SCTP. Mang bản tin NAS của UE, lệnh lập và xoá ngữ cảnh UE, lập E-RAB, paging và handover S1.'}),
 s1ue:()=>({t:'S1-U',d:'Giao diện dữ liệu giữa eNB và S-GW. Mỗi bearer của mỗi UE là một đường hầm GTP-U, phân biệt bằng mã TEID.'}),
 mme:()=>({t:'MME',d:'Nút điều khiển của lõi 4G: xác thực thuê bao, quản lý di động (attach, cập nhật vùng theo dõi, paging), chọn S-GW và P-GW, lập và xoá bearer. MME không chạm vào dữ liệu người dùng. Nối MSC qua SGs để phục vụ CSFB.'}),
 s6a:()=>({t:'S6a',d:'Giao diện Diameter giữa MME và HSS: lấy vector xác thực, đăng ký MME đang phục vụ thuê bao, tải hồ sơ thuê bao.'}),
 hss:()=>({t:'HSS',d:'Cơ sở dữ liệu thuê bao: IMSI, khoá K (trong AuC), số máy, các APN được dùng, QoS mặc định, tốc độ tối đa. Cũng giữ hồ sơ IMS cho VoLTE.'}),
 s11:()=>({t:'S11',d:'Giao diện GTP-C giữa MME và S-GW: Create Session, Modify Bearer, Release Access Bearers, Downlink Data Notification.'}),
 sgw:()=>({t:'S-GW',d:'Cổng phục vụ: điểm neo dữ liệu khi UE chuyển giữa các eNB. Khi UE rảnh, S-GW giữ gói đường xuống và báo MME để paging.'}),
 s5:()=>({t:'S5 / S8',d:'Giao diện giữa S-GW và P-GW, mang cả GTP-C và GTP-U. Gọi là S8 khi thuê bao chuyển vùng quốc tế và P-GW nằm ở mạng nhà.'}),
 pgw:()=>({t:'P-GW',d:'Cổng ra mạng dữ liệu: cấp địa chỉ IP cho UE, thi hành chính sách và QoS theo từng bearer, đếm lưu lượng để tính cước (Gy với OCS), lọc gói vào đúng bearer.'}),
 gx:()=>({t:'Gx',d:'Giao diện Diameter giữa P-GW và PCRF. PCRF đẩy luật chính sách và tính cước xuống P-GW, ví dụ yêu cầu tạo bearer riêng QCI 1 khi có cuộc gọi VoLTE.'}),
 pcrf:()=>({t:'PCRF',d:'Quyết định chính sách: QoS của từng dịch vụ, giới hạn tốc độ theo gói cước, và yêu cầu tạo bearer riêng khi IMS báo có cuộc gọi (qua Rx).'}),
 sgi:()=>({t:'SGi',d:'Giao diện IP giữa P-GW và mạng ngoài: internet, IMS của nhà mạng, hoặc mạng riêng của doanh nghiệp. Mỗi APN ứng với một mạng đích.'}),
 dn:()=>({t:'Mạng dữ liệu',d:'Internet, IMS hoặc mạng riêng mà kết nối PDN của UE nối tới.'})
};
const LAY_L={
 sdap:{t:'Không có SDAP',d:()=>'Lõi EPC quản lý QoS theo từng bearer, và mỗi bearer ứng thẳng với một DRB, nên không cần lớp ánh xạ. SDAP chỉ xuất hiện ở 5G với lõi 5GC.'},
 mac:{t:'MAC và bộ lập lịch',d:()=>'Mỗi khung con 1 ms, bộ lập lịch của eNB chọn UE, số PRB, điều chế và số lớp MIMO theo CQI, rồi báo bằng DCI trên PDCCH. MAC ghép các kênh logic, điều khiển HARQ (8 tiến trình, phát lại sau 8 ms), truy nhập ngẫu nhiên và DRX.'},
 hphy:{t:'PHY: lớp vật lý',d:()=>'Mã hoá Turbo cho dữ liệu, điều chế tới 256QAM, ánh xạ lớp MIMO và tiền mã hoá, chèn tín hiệu tham chiếu CRS, rồi biến đổi IFFT thành tín hiệu OFDM. Đường lên dùng SC-FDMA để giảm tỉ số công suất đỉnh trên trung bình, tiết kiệm pin cho máy. Ở LTE toàn bộ lớp này nằm trong BBU.'},
 lphy:{t:'Vô tuyến (RRU)',d:()=>'RRU nhận mẫu IQ số từ BBU qua CPRI, chuyển thành tín hiệu tương tự, đưa lên tần số sóng mang, khuếch đại công suất và lọc trước khi ra anten. Chiều thu làm ngược lại. RRU không xử lý bit nào.'}
};
const layOf=id=>(lte()&&LAY_L[id])||LAY[id]||LAY.pdcp;
const infoOf=id=>((lte()&&INFO_L[id])||INFO[id]||INFO.ue)();
