/* dùng lại các thủ tục chung với NSA; bản nào có nhắc tới NR thì sao chép rồi sửa câu */
(function(){
  const N=s=>{const p=PROCS.NSA.find(x=>x.name.includes(s));if(!p)throw new Error('Thiếu thủ tục: '+s);return p;};
  const cp=(s,name,fix)=>{const p=JSON.parse(JSON.stringify(N(s)));delete p._tl;p.name=name;for(const st of p.steps){for(const [a,b] of fix)st.d=st.d.replace(a,b);if(st.p)st.p=st.p.map(x=>x==='gnb'?'enb':x).filter((x,i,q)=>x!==q[i-1]);}return p;};
  const V=(p)=>({...p,need:'volte'}),C=(p)=>({...p,need:'csfb'});
  const volteMo=cp('Thoại VoLTE trên NSA','Thoại VoLTE: gọi đi từ đầu đến cuối, có tính cước',[[' Ở NSA, thoại luôn là VoLTE vì lõi là EPC; gNB không tham gia.',''],[' Bearer thoại chỉ chạy trên LTE, không tách sang NR. Tuỳ cấu hình, eNB có thể giữ gNB phụ cho dữ liệu hoặc gỡ ra trong lúc gọi để UE dồn công suất phát cho LTE.',''],[' Dữ liệu internet vẫn chạy song song trên bearer tách LTE + NR nếu gNB phụ còn đó.',' Dữ liệu internet vẫn chạy song song trên bearer mặc định.']]);
  const csfbMo=cp('gọi đi bằng CSFB','Thoại: không có VoLTE, gọi đi bằng CSFB xuống 3G',[[', và được thêm NR lại nếu vùng đó có 5G NSA',''],['Phiên dữ liệu chạy lại trên 4G.','Phiên dữ liệu chạy lại trên 4G.']]);
  const csfbMt=cp('nhận cuộc gọi đến bằng CSFB','Thoại: không có VoLTE, nhận cuộc gọi đến bằng CSFB',[]);
  const chg=cp('Tính cước online','Tính cước online: cấp hạn mức, hết gói, hết tiền',[[' Dữ liệu đi qua eNB hay gNB thì P-GW cũng đếm như nhau.','']]);
  const auth=cp('Thuê bao: xác thực','Thuê bao: xác thực EPS-AKA, kiểm tra IMEI, tải hồ sơ',[[', có được dùng NR làm sóng mang phụ không','']]);
  const det=cp('detach khỏi mạng 4G','Ngắt: tắt máy, detach khỏi mạng 4G',[[' Nếu đang có gNB phụ, eNB gỡ nó ra bằng SgNB Release trước.','']]);
  window.LTE_ALL=[
   V(N('Đầu cuối: cuộc gọi')),E2E_CSFB,V(N('Đầu cuối: SMS từ UE1 đến UE2 qua IMS')),N('Đầu cuối: dữ liệu'),
   lteAttach(true),lteAttach(false),LTE_PAGING,
   V(volteMo),V(N('Thoại VoLTE: nhận cuộc gọi')),V(N('ra khỏi vùng LTE')),C(csfbMo),C(csfbMt),
   V(N('SMS: gửi và nhận qua IMS')),C(N('SMS over SGs')),chg,
   LTE_X2,LTE_S1,LTE_TAU,LTE_TO3G,LTE_CA,auth,
   V(N('IMS: đăng ký')),V(N('IMS: một cuộc gọi')),
   N('Mạng 3G: đăng ký'),N('Mạng 3G: cuộc gọi đến'),N('Mạng 3G: dữ liệu gói'),N('Mạng 3G: gọi đi'),
   det,N('Ngắt: tắt máy trên mạng 3G'),LTE_ES];
})();
function lteProcs(){const want=S.volte==='yes'?'volte':'csfb';PROCS.LTE=LTE_ALL.filter(p=>!p.need||p.need===want);}
PROCS.LTE=LTE_ALL.filter(p=>p.need!=='csfb');
