  $('#intTable').innerHTML='<tr><th></th><th>4G LTE</th><th>3G WCDMA</th></tr>'
   +`<tr><td>Trạm phục vụ</td><td>${dot(`var(--k${sl})`)}eNB${sl}</td><td>${dot(`var(--k${ut})`)}NodeB${ut}<br><span class="note">dùng khi CSFB, SRVCC</span></td></tr>`
   +`<tr><td>Mức thu</td><td>${cell(ls.r,'dBm','RSRP')}</td><td>${cell(us.r,'dBm','RSCP')}</td></tr>`
