  const chk={f:3,t:3,s:'So RES với XRES',m:'S-CSCF kiểm tra kết quả xác thực',p:'nội bộ S-CSCF',k:'loc',d:'S-CSCF tính lại giá trị mong đợi từ XRES và so với response UE gửi. Khớp thì thuê bao được xác thực; không khớp thì trả 403 Forbidden.',fl:[['Khớp','tiếp tục gán S-CSCF và tải hồ sơ'],['Không khớp','403 Forbidden']]};
  const sar=(type)=>({f:3,t:4,s:'SAR / SAA',m:'Server-Assignment-Request / Answer',p:'Diameter trên '+cx,k:'dia',d:type===1?'S-CSCF báo HSS rằng nó nhận phục vụ thuê bao này và xin hồ sơ. HSS ghi tên S-CSCF và trả hồ sơ dịch vụ: các định danh công khai đi kèm nhau và các tiêu chí lọc iFC.':type===2?'S-CSCF báo HSS thuê bao vừa đăng ký lại; không cần tải lại hồ sơ nếu đã có.':'S-CSCF báo HSS thuê bao đã huỷ đăng ký. HSS xoá tên S-CSCF, trừ khi thuê bao có dịch vụ chạy cả lúc chưa đăng ký (ví dụ chuyển cuộc gọi về hộp thư).',
   fl:[['Server-Assignment-Type',type===1?'REGISTRATION (1)':type===2?'RE_REGISTRATION (2)':'USER_DEREGISTRATION (5)'],['User-Data-Already-Available',type===1?'USER_DATA_NOT_AVAILABLE (0)':'USER_DATA_ALREADY_AVAILABLE (1)'],['Trả lời: User-Data',type===1?'XML hồ sơ IMS: IMPU sip và tel, iFC theo thứ tự ưu tiên':'không cần'],['Trả lời: Charging-Information','địa chỉ CDF và OCS']]});
