  const rxsig={f:1,t:1,s:`Theo dõi bearer báo hiệu (${imSa()?'N5':'Rx'})`,m:'P-CSCF đăng ký theo dõi đường báo hiệu',p:imRx(),k:'dia',d:`P-CSCF mở một phiên ${imRx()} với ${imPc()} cho đường báo hiệu, để được báo khi ${imSigB()} bị mất, khi UE đổi mạng truy nhập hoặc đổi PLMN.`,
   fl:[['Specific-Action','INDICATION_OF_LOSS_OF_BEARER, IP-CAN_CHANGE, PLMN_CHANGE, ACCESS_NETWORK_INFO_REPORT'],['AF-Signalling','đánh dấu đây là luồng báo hiệu']]};
