 imExp:{l:'Thời hạn đăng ký mạng cấp',num:1,o:()=>[[600000,'600 000 giây (mặc định của 3GPP)'],[86400,'86 400 giây (một ngày)'],[7200,'7 200 giây'],[3600,'3 600 giây'],[600,'600 giây']],show:()=>S.imV==='reg'},
