Object.assign(S,{voAI:1,voBI:1,voPg:1280,voPre:1,voCb:0,voHop:8,voSil:'ok'});
/* ----- thời gian lập cuộc gọi: ước lượng theo từng chặng ----- */
function voSetupParts(){const p=[],A=(n,ms,c,on)=>{if(on)p.push([n,ms,c]);};
 A('A rảnh: RACH, RRC, Service Request, Initial Context Setup',130,V_('k4'),S.voAI);
 A('INVITE từ A tới P-CSCF qua vô tuyến',35,V_('sip'),1);
 A('Xử lý IMS hai phía: P-CSCF, S-CSCF, TAS, ENUM, LIR, T-ADS',S.voHop*10+60,V_('u5'),1);
 A('Tìm gọi B: chờ trung bình nửa chu kỳ DRX, cộng RRC và Service Request',S.voPg/2+150,V_('warn'),S.voBI);
 A('INVITE tới B và B trả 183',90,V_('sip'),1);
 A('Lập bearer QCI 1 (Rx, Gx, GTP, S1AP, RRC) nằm trên đường găng',S.voPre?160:0,V_('cp'),1);
 A('PRACK và UPDATE precondition: hai vòng đầu cuối',S.voPre?2*(70+S.voHop*6):0,V_('u2'),1);
 A('Nhạc chờ: TAS mở nhánh tới máy chủ nhạc chờ, UPDATE tới A',S.voCb?220:0,V_('u4'),1);
 A('180 hoặc 183 kèm P-Early-Media về tới A',70+S.voHop*4,V_('nr'),1);
 return p.filter(x=>x[1]>0);}
function voSetupFig(){const P=voSetupParts(),T=P.reduce((a,b)=>a+b[1],0),mx=Math.max(4000,T*1.1),sc=320/mx;let s='',x=20;
 P.forEach((q,j)=>{const w=q[1]*sc;s+=`<rect x="${x.toFixed(1)}" y="30" width="${Math.max(1,w).toFixed(1)}" height="26" style="fill:${q[2]};fill-opacity:.55;stroke:${q[2]}"/>`+(w>16?tx(x+w/2,47,String(j+1),{fs:9,b:1,c:V_('ink')}):'');x+=w;});
 [[2000,'2 s'],[4000,'4 s']].forEach(([v,l])=>{if(v<=mx){const X=20+v*sc;s+=li([[X,22],[X,64]],{c:V_('muted'),d:'3 3'})+tx(X,18,l,{fs:8.5,c:V_('muted')});}});
 s+=tx(20,82,`Tổng ước lượng: ${(T/1000).toFixed(2).replace('.',',')} s (từ INVITE ở A tới khi A nghe chuông hoặc nhạc chờ)`,{a:'start',fs:9.5,b:1,c:V_('ink')});
 P.forEach((q,j)=>{const y=102+j*15;s+=`<rect x="20" y="${y-8}" width="9" height="9" style="fill:${q[2]};fill-opacity:.55;stroke:${q[2]}"/>`+tx(34,y,`${j+1}. ${q[0]}: ${f0(q[1])} ms`,{a:'start',fs:8.3,c:V_('ink')});});
 return svgw(360,104+P.length*15,s,'Thời gian lập cuộc gọi');}
