const VOFAULT={
 reg:{n:'Đăng ký IMS thất bại',pts:[['Hiện tượng','Máy không lên biểu tượng VoLTE, gọi rơi về CSFB hoặc không gọi được.'],['Dấu hiệu','REGISTER nhận 403, 408, 500, 503, 504; hoặc không có 401; Cx UAA, MAA, SAA có mã lỗi (5001, 5002, 5003).'],['Nguyên nhân thường gặp','Thuê bao chưa khai IMS; IMPI/IMPU sai dạng; HSS hoặc DNS chậm; P-CSCF không tới được; IPsec lỗi.'],['Kiểm tra','Lọc Cx theo Result-Code; xem 504 có phần thân XML restoration không; xem PCO có địa chỉ P-CSCF không.'],['Xử lý theo 3GPP','TS 24.229: 504 có thân restoration thì UE đăng ký lại từ đầu; khai đúng hồ sơ trong HSS (TS 29.228).']]},
 bearer:{n:'Không lập được bearer QCI 1',pts:[['Hiện tượng','Cuộc gọi lỗi trước khi đổ chuông, tập trung ở cell tải cao.'],['Dấu hiệu','E-RAB Setup Response có danh sách thất bại (radio-resources-not-available, invalid-qos-combination); Create Bearer Response cause 73; Rx AAA lỗi; SIP 580 hoặc 503.'],['Nguyên nhân thường gặp','Nhận vào GBR từ chối; ARP thấp không được chiếm; máy từ chối; tham số QoS không hợp lệ.'],['Kiểm tra','Tỉ lệ thêm E-RAB QCI 1 theo cell; nguyên nhân từ chối; ARP trong Gx RAR.'],['Xử lý theo 3GPP','Ưu tiên ARP cho thoại; cấu hình QCI 1 đúng (TS 23.203).']],ven:['Huawei: theo dõi Dedicated Bearer Context Activation Success Rate (SmartCare); tính năng nhận vào và chiếm tài nguyên theo ARP (tên tra theo phiên bản).','Nokia: LTE534 ARP-based Admission Control; LTE2430 qci1ProtectionTimer; KPI LTE_5204b/c.','Ericsson: Differentiated Admission Control, Dynamic GBR Admission Control (paArpOverride, firstPreEmptionSpidSet); Dynamic QoS Modification bắt buộc.']},
 slow:{n:'Lập cuộc gọi chậm',pts:[['Hiện tượng','Bấm gọi lâu mới nghe chuông.'],['Dấu hiệu','Khoảng INVITE tới 180 dài; tách ra thấy chặng tìm gọi, chặng AS, chặng bearer.'],['Nguyên nhân thường gặp','Chu kỳ DRX tìm gọi dài; nhiều AS nối chuỗi; precondition chờ bearer; mất gói truyền dẫn làm phát lại; EPS fallback ở 5G SA.'],['Kiểm tra','Dùng thẻ VoLTE, phần Thời gian lập cuộc gọi để ước lượng; đo từng chặng trong log.'],['Xử lý','Rút ngắn chu kỳ tìm gọi cho thoại, tối ưu chuỗi AS, sửa truyền dẫn.']]},
 codec:{n:'488 hoặc 415: không khớp bộ mã, SDP',pts:[['Hiện tượng','Gọi tới một hướng (mạng khác, một dòng máy) luôn lỗi ngay.'],['Dấu hiệu','488 Not Acceptable Here, 415, 606; SDP lời mời và trả lời không có bộ mã chung.'],['Kiểm tra','So SDP ở biên; cấu hình chuyển mã ở SBC, IBCF.'],['Xử lý','Bật chuyển mã; thống nhất danh sách bộ mã (GSMA IR.92: AMR, AMR-WB; EVS khuyến nghị).']]},
 hold:{n:'B nhấc máy nhưng A không thông (giữ 200 OK)',pts:[['Hiện tượng','A nghe chuông hoặc nhạc chờ, B nhấc máy nhưng không ai nghe ai, rồi rớt sau vài giây.'],['Dấu hiệu','200 OK (INVITE) của B đi tới TAS rồi dừng; TAS gửi UPDATE hoặc re-INVITE tới A; A không trả lời; 408; 200 OK phía B phát lại vì không có ACK.'],['Nguyên nhân thường gặp','Sóng của A kém đúng lúc đàm phán lại; kết nối TCP tới A; bộ đếm các nút không đồng bộ; SDP đàm phán lại khác nhiều.'],['Kiểm tra','Bộ phân tích log ở cuối thẻ này nhận diện được kiểu lỗi này.'],['Xử lý','Xem phần Silent call, tình huống nhạc chờ.']]},
 rlf:{n:'Rớt do mất sóng, chuyển giao',pts:[['Hiện tượng','Đang nói thì mất.'],['Dấu hiệu','UE Context Release Request (radio-connection-with-ue-lost), E-RAB Release Indication; Rx ASR Abort-Cause 0; BYE có Reason do mạng gửi.'],['Kiểm tra','Vị trí, mức thu lúc rớt; chuyển giao thất bại; tái lập RRC.'],['Xử lý theo 3GPP','Tối ưu ngưỡng chuyển giao, MRO (TS 36.300 mục 22.4.2); bộ đếm T310/N310.']],ven:['Huawei: SmartCare tách tỉ lệ rớt do E-RAB Release, do UE Context Release, do X2 handover, do SRVCC.','Nokia: LTE1569 (t310Qci1, n310Qci1; thử T310 500 ms giảm rớt QCI 1 trong một mạng), nCqiDtx, a2RedirectQci1 nên tắt.','Ericsson: Multi-Target RRC Connection Re-establishment; với CA dùng VoLTE Optimized Carrier Aggregation vì Dynamic SCell Selection có thể làm tăng rớt.']},
 rtp:{n:'Rớt do hết thời gian chờ RTP',pts:[['Hiện tượng','Im lặng một lúc rồi rớt.'],['Dấu hiệu','BYE từ SBC kèm Reason về RTP timeout; khoảng lặng trên eNB.'],['Kiểm tra','Phía nào ngừng gửi trước; vùng phủ đường lên; truyền dẫn.'],['Xử lý','Đặt bộ đếm RTP của IMS phù hợp; Ericsson đặt rtpTimeout của eNB bằng giá trị của IMS để đo khoảng lặng.']]},
 srvcc:{n:'SRVCC thất bại hoặc rớt khi đang đổ chuông',pts:[['Hiện tượng','Rớt ở mép vùng LTE.'],['Dấu hiệu','HO Required kiểu SRVCC không có HO Command; PS to CS Response lỗi; chuyển giao khi chưa trả lời mà lõi không hỗ trợ aSRVCC, bSRVCC.'],['Kiểm tra','STN-SR, C-MSISDN trong HSS; MSC hỗ trợ; ngưỡng B2.'],['Xử lý','Tách ngưỡng A2 và B2 để chuyển giao trong LTE trước; bật aSRVCC, bSRVCC ở lõi (TS 23.216, 23.237).']],ven:['Huawei: SmartCare đo SRVCC HO Success Rate, Preparation, Implement, bSRVCC, aSRVCC, eSRVCC.','Nokia: LTE872 (WCDMA), LTE873 (GSM), b2Threshold1UtraQci1, LTE2112; kích SRVCC sớm hơn chuyển giao PS 2 đến 3 dB; tS1RelPrepU 2000 ms.','Ericsson: SRVCC chỉ khi có QCI 1 và UE, MME hỗ trợ; Robust SRVCC Handover at Call Setup; voicePrio; giữ ngưỡng QCI 1, QCI 5, QCI 9 gần nhau.']},
 oneway:{n:'Mất tiếng một chiều',pts:[['Hiện tượng','Một bên nghe, bên kia không.'],['Kiểm tra','Xem phần Silent call ở thẻ này để khoanh đoạn: SBC, UPF, eNB, truyền dẫn, liên mạng, máy.']]},
 mos:{n:'Chất lượng thoại kém (MOS thấp)',pts:[['Dấu hiệu','RTCP báo mất gói, jitter cao; chuyển mã nhiều lần.'],['Nguyên nhân','Vùng phủ, nhiễu, tải cao, DRX đặt sai, chuyển giao nhiều, chuyển mã.'],['Xử lý','Lập lịch theo trễ, ưu tiên QCI 1 trên QCI 5, DRX cho thoại, giảm chuyển giao không cần thiết.']]},
 ocs:{n:'Rớt hoặc không gọi được do tính cước (OCS)',pts:[['Dấu hiệu','Ro CCA mã 4012 DIAMETER_CREDIT_LIMIT_REACHED, 4010 END_USER_SERVICE_DENIED, 5030 USER_UNKNOWN; TAS gửi BYE hoặc 402/403.'],['Kiểm tra','Số dư, gói cước, cấu hình chặn khi roaming.'],['Xử lý','Theo chính sách cước; xem thẻ Roaming và tính cước.']]},
 mt:{n:'Gọi đến không đổ chuông trên VoLTE',pts:[['Dấu hiệu','T-ADS chọn CS; INVITE tới UE không đến; 480.'],['Nguyên nhân','Máy không còn đăng ký IMS; Sh trả IMS-Voice-Over-PS = không hỗ trợ; tìm gọi lỗi.'],['Xử lý','Kiểm tra đăng ký, dữ liệu T-ADS trong HSS, cấu hình SCC AS.']]}};
/* ----- vô tuyến và tham số ----- */
const VOPAR={
 qos:{n:'Hồ sơ QoS cho QCI 1, QCI 5',d:'Bearer thoại QCI 1 là GBR, dùng RLC UM và ROHC; bearer SIP QCI 5 dùng RLC AM. Ericsson đặt ưu tiên QCI 1 cao hơn QCI 5 để tải SIP, RCS không làm hỏng tiếng nói.',tb:()=>['Hồ sơ QoS',['Mục','3GPP TS 23.203','Ericsson (QciProfilePredefined)','Nokia (qciTabX)','Huawei'],[['QCI 1: loại, trễ, tỉ lệ lỗi','GBR, 100 ms, 10⁻²','pdb 80 ms, pdbOffset 50 ms','delay target 80 ms','Cấu hình theo QCI (đối tượng QCI chuẩn)'],['QCI 1: mức ưu tiên','2','priority 1','scheduling priority 5 (theo tài liệu đào tạo)','—'],['QCI 1: RLC, ROHC','UM (khuyến nghị IR.92)','rlcMode UM, rohcEnabled TRUE','RLC UM, RLC/PDCP profile 101, actPdcpRohc','ROHC cho QCI 1'],['QCI 1: lập lịch','—','schedulingAlgorithm DELAY_BASED, serviceType VOIP','LTE10: trọng số theo trễ, gộp gói','Lập lịch nhận biết thoại (tên tra theo phiên bản)'],['QCI 1: DRX','—','drxProfile 1, drxPriority 98','qci1DrxOnThreshold 9, qci1DrxOffThreshold 7 (CQI)','DRX riêng cho thoại'],['QCI 1: PDCP SN','7 bit theo IR.92','pdcpSNLength 12','—','—'],['QCI 5','Không GBR, ưu tiên 1, 100 ms, 10⁻⁶','priority 2, pdb 100, AM, RESOURCE_FAIR, HIGH_PRIO_OVERRIDE','tDiscard vô hạn khi sóng rất kém','—'],['DSCP truyền dẫn','—','—','DSCP 46 cho QCI 1','—']],0]},
 drx:{n:'DRX khi đang gọi',d:'Một gói mỗi 20 ms nên chu kỳ DRX 40 ms gom được hai khung trong ngân sách trễ 80 ms, tiết kiệm pin. Khi sóng kém nên tắt DRX để giữ chất lượng.',ven:['DRX riêng cho thoại theo QCI; tên tham số tra theo phiên bản.','LTE42, LTE473, LTE585 Smart DRX; qci1DrxOnThreshold 9 và qci1DrxOffThreshold 7 bật, tắt DRX theo CQI; white paper: DRX gom hai gói, giảm khoảng 80 % điện năng VoLTE.','Service Specific DRX bắt buộc; DrxProfile 1 cho FDD: onDurationTimer PSF4, drxInactivityTimer PSF4, drxRetransmissionTimer PSF2, longDrxCycle SF40, không dùng chu kỳ ngắn; TDD: PSF10, PSF8.']},
 rohc:{n:'Nén tiêu đề ROHC',d:'Tiêu đề IPv6/UDP/RTP 60 byte nén còn vài byte (TS 36.323, RFC 5795). Chỉ dùng cho QCI mang RTP thoại.',ven:['ROHC cho QCI 1.','LTE11: actPdcpRohc, rohcMaxCid 1..16 (mặc định 4); tiết kiệm khoảng 91,5 % tiêu đề với AMR 12,2.','Robust Header Compression bắt buộc theo IR.92; rohcEnabled TRUE chỉ ở QCI 1.']},
 ttib:{n:'TTI bundling và tăng vùng phủ đường lên',d:'Mỗi gói đường lên gửi lặp 4 TTI liên tiếp (TS 36.321), lợi khoảng 4 dB vùng phủ, chỉ dùng ở mép cell.',ven:['TTI bundling (tên công tắc tra theo phiên bản).','LTE907: actTtiBundling, ttibOperMode, ttibSinrThresholdIn/Out, harqMaxTrULTtiBundling, enforceTtiBundling theo QCI; một thử nghiệm: BLER đường lên giảm từ 73 % xuống 9 %.','TTI Bundling (chỉ FDD): ttiBundlingSwitchThres, ttiBundlingSwitchThresHyst, tReorderingUl; ngưỡng quá thấp thì rớt trước khi bật, quá cao thì phí tài nguyên; kèm VoLTE Frequency Hopping.']},
 sched:{n:'Lập lịch: SPS hay theo trễ',d:'SPS (TS 36.321) cấp sẵn tài nguyên định kỳ 20 ms, giảm tải PDCCH; lập lịch động theo trễ thì linh hoạt hơn.',ven:['Lập lịch bán cố định cho VoIP (tên tra theo phiên bản).','Chỉ thấy LTE1929 UL Semi-persistent Scheduling trong tài liệu TD-LTE; LTE10 có trọng số theo trễ và gộp gói.','Không dùng SPS trong hướng dẫn; dùng Delay-Based Scheduling and Grant Estimation; pdcchCfiMode = 5 (CFI_AUTO_MAXIMUM_3), Enhanced PDCCH Link Adaptation, PDCCH Power Boost (pdcchPowerBoostMax 0 dB).']},
 ac:{n:'Nhận vào, ARP, chiếm tài nguyên',d:'ARP do HSS/PCRF cấp; eNB chỉ dùng chênh lệch ARP để nhận vào và chiếm tài nguyên.',ven:['Nhận vào theo ARP (tên tra theo phiên bản).','LTE534 ARP-based Admission Control, LTE497 Smart Admission Control, maxNumQci1Drb.','Admission Control, Differentiated Admission Control, Dynamic GBR Admission Control, paArpOverride, firstPreEmptionSpidSet.']},
 tmr:{n:'Bộ đếm không hoạt động, RLF riêng cho thoại',d:'Giữ máy gọi ở RRC_CONNECTED khi B chậm trả lời; bộ đếm RLF riêng cho QCI 1.',ven:['—','LTE1569: t310Qci1, n310Qci1; LTE2430 qci1ProtectionTimer 30 s.','Service Specific Inactivity Timer: inactivityTimerOffset 20 s cộng vào Rcs.tInactivityTimer; VoLTE Inactivity Timer Extension sau cuộc gọi (không nên bật lâu dài).']},
 obs:{n:'Bộ đếm theo dõi',d:'Bộ đếm phía RAN chỉ là chỉ báo phần đóng góp của RAN; chất lượng đầu cuối phải đo ở máy hoặc IMS.',ven:['SmartCare KQI: kết nối, trễ, rớt (ASR), MOS, mất gói, SRVCC (xem phần KPI).','M8006C188, C206, C197, C215 (QCI 1 initial, added); LTE_5204b, LTE_5572b, LTE_1263h, LTE_5571f, LTE_5563a.','counterActiveMode TRUE cho QCI 1; pmErabRelDlInactGapQci, pmErabRelUlInactGapQci, pmPdcpInactSecDlVolteDistr, pmPdcpInactSecUlVolteDistr; rtpTimeout.']}};
