  if(M.length&&D.length){const byKey={};D.forEach(d=>{const k=Math.round(d.t)+'|'+d.name.replace(/\s+/g,'');(byKey[k]=byKey[k]||[]).push(d);});
   M.forEach(m=>{const k=Math.round(m.t)+'|'+m.name.replace(/\s+/g,'');const q=byKey[k];if(q&&q.length){const d=q.shift();m.f=d.f;if(!m.sip&&d.sip)m.sip=d.sip;}});}
