function vaInit(){const inp=$('#vaFile'),drop=$('#vaDrop');if(!inp)return;
 inp.addEventListener('change',()=>{if(inp.files.length)vaLoad([...inp.files]);inp.value='';});
 ['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('on');}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('on');}));
 drop.addEventListener('drop',e=>{const f=[...(e.dataTransfer&&e.dataTransfer.files||[])];if(f.length)vaLoad(f);});
 $('#vaDemo1').addEventListener('click',()=>vaDemo(false));$('#vaDemo2').addEventListener('click',()=>vaDemo(true));
 $('#vaOut').addEventListener('click',e=>{const b=e.target.closest('[data-vam]');if(!b)return;VA.sel=+b.dataset.vam;vaRender();const d=$('#vaDec');if(d)d.scrollIntoView({block:'nearest',behavior:'smooth'});});}

