const HXFAIL={
 prep:{n:'Chuẩn bị chuyển giao thất bại',pts:[['Dấu hiệu','X2: Handover Preparation Failure; S1: Handover Preparation Failure từ MME (sau Handover Failure của eNB đích).'],['Nguyên nhân hay gặp','no-radio-resources-available-in-target-cell, ho-target-not-allowed, unknown-targetID (lân cận khai sai), transport resource unavailable, cell-not-available (cell đích tắt).'],['Kiểm tra','Tải và nhận vào ở cell đích; khai báo lân cận (ECGI, PCI); trạng thái X2; tiết kiệm điện ở cell đích.'],['Xử lý','Sửa lân cận, cân bằng tải, mở rộng; với cell tắt để tiết kiệm điện, eNB Configuration Update phải báo Deactivation Indication.']]},
 late:{n:'Chuyển giao quá muộn',pts:[['Dấu hiệu','RLF ở cell nguồn, rồi UE tái lập RRC ở cell khác; trạm của cell đó gửi RLF Indication qua X2 về trạm nguồn (TS 36.423 mục 8.3.9).'],['Nguyên nhân','A3 offset hoặc TTT quá lớn; UE đi nhanh; vùng chồng lấn hẹp.'],['Xử lý','MRO giảm offset, TTT cho cặp cell này (Cell Individual Offset); TS 36.300 mục 22.4.2.']]},
 early:{n:'Chuyển giao quá sớm',pts:[['Dấu hiệu','Chuyển giao xong thì RLF ngay ở cell đích rồi tái lập ở cell nguồn; trạm đích gửi Handover Report (Handover Too Early).'],['Xử lý','MRO tăng offset hoặc TTT.']]},
 wrong:{n:'Chuyển giao sai cell',pts:[['Dấu hiệu','Chuyển giao xong RLF rồi tái lập ở cell thứ ba (Handover To Wrong Cell).'],['Xử lý','Điều chỉnh CIO giữa các cell, kiểm tra chồng lấn và anten.']]},
 ping:{n:'Chuyển giao qua lại (ping-pong)',pts:[['Dấu hiệu','UE chuyển A sang B rồi về A trong vài giây.'],['Xử lý','Tăng hysteresis, TTT; kiểm tra vùng phủ hai cell gần bằng nhau; với VoLTE, mỗi lần chuyển giao là một khoảng mất tiếng nhỏ.']]},
 x2down:{n:'Mất liên kết X2 hoặc Xn',pts:[['Dấu hiệu','Cảnh báo SCTP X2 down; chuyển giao chuyển sang S1 (chậm hơn) hoặc không chuyển giao được nếu không cho phép S1.'],['Kiểm tra','Định tuyến IP, IPsec, tường lửa giữa hai trạm; cổng SCTP 36422 (X2), 38422 (Xn).'],['Xử lý','Khôi phục truyền dẫn; ANR có thể tự lập lại X2.']]},
 pci:{n:'Nhầm PCI (confusion, collision)',pts:[['Dấu hiệu','Hai lân cận cùng PCI: eNB không biết chuyển tới cell nào; tỉ lệ chuyển giao thấp ở một hướng.'],['Xử lý','Quy hoạch lại PCI (tự động bằng SON); xem chuyên đề PCI ở thẻ Chuyên đề.']]}};
gxDef('hx',{label:'Trạm lân cận và chuyển giao',
 lead:()=>'Trước khi chuyển giao được, hai trạm phải biết nhau (ANR, X2 Setup, Xn Setup), trao đổi tải để cân bằng (Resource Status), rồi phối hợp từng bước khi UE đi qua: chuẩn bị, thực hiện, chuyển tiếp dữ liệu, đổi đường ở lõi. Thẻ này đi sâu vào phần trao đổi giữa các trạm và các ca lỗi.',note:HXNOTE,
 views:{
  setup:{n:'Thiết lập giao diện giữa các trạm',items:{x2:{n:'ANR và X2 Setup (4G)',spec:'TS 36.300 mục 22.3.2a, 22.3.6; TS 36.423 mục 8.3.3',kind:'ladder',l:hxX2,ven:['Quan hệ lân cận: đối tượng ô ngoài (external cell) và quan hệ lân cận cùng tần, khác tần; liên kết X2 khai thủ công hoặc tự lập bằng ANR (tên đối tượng tra theo phiên bản).','LNADJ (eNB lân cận, địa chỉ X2), LNADJL (cell lân cận), LNREL (quan hệ lân cận); ANR tự tạo các đối tượng này.','ExternalENodeBFunction, ExternalEUtranCellFDD/TDD, EUtranFreqRelation, EUtranCellRelation, TermPointToENB; ANR tự thêm quan hệ và X2.']},
   xn:{n:'Xn Setup (5G) và EN-DC X2 Setup (NSA)',spec:'TS 38.423 mục 8.4.1; TS 36.423 mục 8.7.4',kind:'ladder',l:hxXn}}},
  load:{n:'Trao đổi tải và cân bằng tải',items:{rs:{n:'Resource Status và Mobility Settings Change',spec:'TS 36.423 mục 8.3.6, 8.3.7, 8.3.8; TS 36.300 mục 22.4.1',kind:'ladder',l:hxLoad}}},
  ho:{n:'Chuyển giao từng bước',items:{
   x2:{n:'Chuyển giao X2',spec:'TS 36.300 mục 10.1.2.1',kind:'ladder',l:voX2},
   s1:{n:'Chuyển giao S1 (không có X2)',spec:'TS 23.401 mục 5.5.1.2, TS 36.413',kind:'ladder',l:hxS1},
   n26:{n:'Chuyển giao 5G SA xuống 4G qua N26',spec:'TS 23.502 mục 4.11.1.2.1',kind:'ladder',l:hxN26}}},
  fail:{n:'Ca lỗi chuyển giao',il:'Ca lỗi',items:Object.fromEntries(Object.entries(HXFAIL).map(([k,v])=>[k,{n:v.n,kind:'text',pts:v.pts,spec:'TS 36.300 mục 22.4.2 (MRO); TS 36.423'}]))}}});
/* ---------- Thẻ: Liên mạng, UE tới UE khác nhà mạng, UE tới OTT ---------- */
const ITNOTE='<p class="note">Theo 3GPP TS 23.228 (IBCF, TrGW), 29.165 (Ici, Izi), 29.163 (liên mạng CS), 23.040 (SMS), 29.281 (GTP-U), 23.203, 29.212 (ADC), 23.503, 24.526 (URSP), 32.299; IETF RFC 4694 (tham số chuyển mạng giữ số), RFC 8446 (TLS 1.3), RFC 9000 (QUIC). Cách đánh số định tuyến khi chuyển mạng giữ số tuỳ quy định từng nước.</p>';
const itNni=()=>({nodes:[['np',4,8,64,30,'ENUM, NP'],['ca',4,78,64,30,'S-CSCF A'],['ia',100,78,60,30,'IBCF A','TrGW A'],['ib',210,78,60,30,'IBCF B','TrGW B'],['ic',294,78,62,30,'I/S-CSCF B'],['sa',4,148,64,30,'SBC A'],['sb',294,148,62,30,'SBC B'],['ua',4,218,64,30,'UE A','mạng A'],['ub',294,218,62,30,'UE B','mạng B']],
 links:[['ua','sa','Gm'],['sa','ca','Mw'],['ca','np','DNS'],['ca','ia','Mx'],['ia','ib','Ici, Izi'],['ib','ic','Mx'],['ic','sb','Mw'],['sb','ub','Gm']],
 steps:[[['ua','sa','ca'],['ua-sa','sa-ca'],'A gọi số của mạng khác','INVITE từ A tới S-CSCF A như mọi cuộc gọi.'],
  [['ca','np'],['ca-np'],'Tra chuyển mạng giữ số và ENUM','S-CSCF (hoặc TAS) tra cơ sở dữ liệu chuyển mạng giữ số để biết số đã chuyển sang mạng nào; kết quả gắn vào Request-URI (tham số rn, npdi theo RFC 4694) hoặc vào tiền tố định tuyến tuỳ quy định quốc gia. ENUM liên mạng (nếu có) trả SIP URI của mạng đích.',[['Request-URI','tel:+849xxxxxxx;npdi;rn=<mã mạng đích>'],['Không có thông tin','định tuyến theo dải số gốc']]],
  [['ca','ia','ib'],['ca-ia','ia-ib'],'Qua biên giới IMS','IBCF ẩn cấu trúc mạng (topology hiding), lọc tiêu đề; TrGW neo media, chuyển đổi IPv4/IPv6, chuyển mã nếu hai mạng khác bộ mã. Giao diện Ici (báo hiệu) và Izi (media) theo TS 29.165, thường đi qua IPX hoặc kết nối trực tiếp.',[['Ici','SIP, thường có TLS hoặc IPsec'],['Izi','RTP qua TrGW']]],
  [['ib','ic','sb','ub'],['ib-ic','ic-sb','sb-ub'],'Mạng B định tuyến tới máy','I-CSCF B hỏi HSS B, chuyển tới S-CSCF B và SBC B; như cuộc gọi đến bình thường.'],
  [['ua','ub','ia','ib'],['ia-ib'],'Lỗi hay gặp ở liên mạng','488 do không có bộ mã chung và biên không chuyển mã; 404, 604 do tra chuyển mạng giữ số sai; một chiều do định tuyến media ở TrGW; trễ lập tăng do nhiều chặng.']]});
