/* ---------- Thẻ Giao thức: tiêu đề, thủ tục, lỗi, ứng dụng, chuẩn và Wireshark, tính toán ---------- */
/* mỗi giao thức P(view,id,{n,spec,hdr,proc,flt,app,std,wf,calc,ven,more}); sáu khía cạnh chọn bằng điều khiển prF.
   hdr: {f:[[tên,bit,ý nghĩa,tên ngắn?]],row?,note?} (bit=0: độ dài thay đổi) hoặc {t:'text',f:[[dòng,ý nghĩa]]}
   proc: {cols:[...],st:[[từ,tới,bản tin,giải thích,{k,fl,chk,dash,bad,p}]],d?}
   flt: [{n,sym,cause:[],chk:[],kpi,keep,add:[bước]}]   app: [[giao diện,vai trò,'SNL',liên kết]]
   calc: {t,ctl:[khoá],run()->{fig,out,info,tb?,tt?}} */
const PRV={tcpip:{n:'TCP/IP, bảo mật, NAT',items:{}},ims:{n:'IMS và media',items:{}},core:{n:'Lõi 3GPP và báo hiệu',items:{}},rt:{n:'Định tuyến và truyền tải',items:{}},sm:{n:'Đồng bộ và quản lý',items:{}}};
const PRFL={hdr:'Cấu trúc tiêu đề',proc:'Thủ tục từng bước',flt:'Giả lập lỗi',app:'Ứng dụng trong mạng di động',std:'Chuẩn và bộ lọc Wireshark',calc:'Tính toán tương tác'};
const PRNOTE='<p class="note">Cấu trúc tiêu đề và thủ tục theo RFC, 3GPP, IEEE, ITU-T; các bản tin, địa chỉ, tên máy trong ví dụ đều tự tạo, không lấy từ mạng thật. Mô hình tính toán là mô hình đơn giản để hiểu quy luật, không thay cho phép đo. Tên tính năng, tham số, lệnh của Huawei, Nokia, Ericsson ghi theo hiểu biết chung, kiểm tra theo phiên bản phần mềm. Số mã (mã thủ tục, mã lệnh, kiểu bản tin) nên đối chiếu với bản đặc tả đúng phiên bản trước khi dùng trong tài liệu chính thức.</p>';
const PRVEN={
 tcpip:['Trạm và lõi dùng IP/Ethernet qua cổng và VLAN riêng cho báo hiệu, người dùng, quản lý; IPsec thường do cổng bảo mật (SeGW) trong thiết bị hoặc router riêng đảm nhận. Tên tham số tra theo phiên bản.','Trạm AirScale/AirFlex dùng IP backhaul với VLAN, IPsec và QoS theo cấu hình của khối truyền tải; tên đối tượng cấu hình tra theo tài liệu từng bản phát hành.','Trạm Radio Processing / Baseband dùng IP/VLAN, IPsec và QoS theo cấu hình truyền tải; phần định tuyến hay do Router 6000 trong mạng Ericsson đảm nhận. Tra tài liệu đúng bản phát hành.'],
 ims:['Lõi IMS Huawei (CSCF, TAS, SBC) dùng SIP/SDP/RTP và Diameter chuẩn; các bộ đếm SmartCare cho tỷ lệ thiết lập, rớt, silent call. Tên mô-đun tra theo phiên bản.','IMS Nokia (CSCF, TAS, SBC/IBCF) dùng SIP/SDP chuẩn; cấu hình timer, mã hoá theo nền tảng từng bản. Tên tra theo tài liệu.','IMS Ericsson (CSCF, MTAS, SBG) dùng SIP/SDP chuẩn; tài liệu VoLTE Guidelines nêu cấu hình timer và bearer. Tên tra theo bản phát hành.'],
 core:['Lõi gói và 5GC của Huawei dùng Diameter, GTP, PFCP, SBI theo chuẩn; khác biệt nằm ở cấu hình, bộ đếm và công cụ giám sát. Tên mô-đun tra theo phiên bản.','Lõi Nokia (MME, SGW/PGW, AMF/SMF/UPF) dùng các giao thức chuẩn; bộ đếm và log khác nhau theo sản phẩm. Tra tài liệu đúng bản phát hành.','Lõi Ericsson (EPG, SGSN-MME, 5GC) dùng giao thức chuẩn; log, bộ đếm theo từng sản phẩm. Tra tài liệu đúng bản phát hành.'],
 rt:['Router, switch truyền tải của Huawei chạy VRP; lệnh hiển thị thường bắt đầu bằng display. Cú pháp và tên tính năng kiểm tra theo phiên bản.','Router Nokia chạy SR OS; lệnh hiển thị thường bắt đầu bằng show. Cú pháp và tên tính năng kiểm tra theo phiên bản.','Router Ericsson (dòng Router 6000/Redback) có giao diện dòng lệnh kiểu show; cú pháp và tên tính năng kiểm tra theo phiên bản.'],
 sm:['Đồng bộ và quản lý của Huawei: trạm lấy đồng bộ từ PTP/SyncE/GNSS; mạng quản lý dùng SNMP, NETCONF, Syslog. Tên tham số tra theo phiên bản.','Đồng bộ Nokia: GNSS, PTP, SyncE tuỳ trạm; quản lý qua SNMP/NETCONF theo nền tảng. Tên tham số tra theo phiên bản.','Đồng bộ Ericsson: GNSS, PTP, SyncE tuỳ trạm; quản lý qua SNMP/NETCONF theo nền tảng. Tên tham số tra theo phiên bản.']};
Object.assign(S,{prF:'hdr',prFt:0});
const prCur=()=>gxItem('pr').P;
const prFacets=P=>['hdr','proc','flt','app','std','calc'].filter(f=>f==='app'||f==='std'||P[f]);
const prFac=()=>{const a=prFacets(prCur());if(!a.includes(S.prF))S.prF=a[0];return S.prF;};
C.prF={l:'Khía cạnh',o:()=>{prFac();return prFacets(prCur()).map(f=>[f,PRFL[f]]);}};
C.prFt={l:'Tình huống lỗi',num:1,o:()=>(prCur().flt||[]).map((f,j)=>[j,f.n]),show:()=>prFac()==='flt'};
/* điều khiển cho phần tính toán: spec là [min,max,bước] hoặc danh sách [[giá trị,nhãn]] */
function prC(k,l,spec,def,f){S[k]=def;C[k]=Array.isArray(spec[0])?{l,num:typeof def==='number'?1:0,o:()=>spec}:{l,r:spec,f:f||(v=>String(v))};}
const prSt=(f,t,m,d,o)=>Object.assign({f,t,s:m,m,d},o||{});
const prKv=a=>a.map(r=>kv(r[0],r[1])).join('');
const prF1=(v,n)=>Number(v).toFixed(n===undefined?1:n);
const prFmt=v=>Math.abs(v)>=1e6?prF1(v/1e6,2)+' triệu':Math.abs(v)>=1e4?Math.round(v).toLocaleString('vi-VN'):String(Math.round(v*100)/100);
/* biểu đồ đường: o={xr,yr,series:[{p:[[x,y]],c,l,d}],mk:[[x,y,nhãn]],hz:[[y,nhãn]],xl,yl,xf,yf} */
function prChart(o){
  const W=372,H=214,l=42,r=10,t=12,b=34,pw=W-l-r,ph=H-t-b,X=x=>l+(x-o.xr[0])/(o.xr[1]-o.xr[0])*pw,Y=y=>t+ph-(y-o.yr[0])/(o.yr[1]-o.yr[0])*ph,xf=o.xf||(v=>prFmt(v)),yf=o.yf||(v=>prFmt(v));let s='';
  for(let k=0;k<=4;k++){const yv=o.yr[0]+(o.yr[1]-o.yr[0])*k/4,xv=o.xr[0]+(o.xr[1]-o.xr[0])*k/4;
    s+=li([[l,Y(yv)],[W-r,Y(yv)]],{c:V_('line'),w:.8})+tx(l-4,Y(yv)+3,yf(yv),{a:'end',fs:8})+tx(X(xv),H-b+12,xf(xv),{fs:8});}
  s+=li([[l,t],[l,t+ph],[W-r,t+ph]],{c:V_('ink'),w:1.2});
  (o.hz||[]).forEach(h=>{if(h[0]>=o.yr[0]&&h[0]<=o.yr[1])s+=li([[l,Y(h[0])],[W-r,Y(h[0])]],{c:V_('warn'),w:1,d:'5 3'})+tx(W-r-2,Y(h[0])-3,h[1],{a:'end',fs:8,c:V_('warn')});});
  const cs=[V_('up'),V_('k4'),V_('k1'),V_('cp')];
  (o.series||[]).forEach((se,j)=>{const c=se.c||cs[j%4],pts=se.p.map(p=>[X(clamp(p[0],o.xr[0],o.xr[1])).toFixed(1),Y(clamp(p[1],o.yr[0],o.yr[1])).toFixed(1)]);s+=li(pts,{c,w:2,d:se.d});});
  (o.mk||[]).forEach(m=>{s+=`<circle cx="${X(m[0]).toFixed(1)}" cy="${Y(m[1]).toFixed(1)}" r="4.2" style="fill:${V_('warn')};stroke:${V_('panel')};stroke-width:1.5"/>`+(m[2]?tx(clamp(X(m[0]),50,W-60),Y(m[1])-8,m[2],{fs:8.5,b:1,c:V_('ink')}):'');});
  s+=tx(l+pw/2,H-3,o.xl||'',{fs:8.5})+`<text transform="translate(9 ${t+ph/2}) rotate(-90)" text-anchor="middle" style="fill:${V_('muted')};font-size:8.5px">${o.yl||''}</text>`;
  const lg=(o.series||[]).filter(q=>q.l);lg.forEach((se,j)=>{const c=se.c||cs[j%4],x=l+6+j*108;s+=li([[x,t+6],[x+14,t+6]],{c,w:2.4})+tx(x+18,t+9,se.l,{a:'start',fs:8,c:V_('ink')});});
  return svgw(W,H,s,o.lab||'Biểu đồ');
}
/* thanh ngang: items [[nhãn,giá trị,màu?]], max */
function prBars(items,max,unit,lab){
  const W=372,rh=21,H=items.length*rh+8;let s='';const lw=92,pw=W-lw-64;
  items.forEach((it,j)=>{const y=4+j*rh,w=Math.max(1,it[1]/max*pw);s+=tx(lw-4,y+13,it[0],{a:'end',fs:8.5,c:V_('ink')})+`<rect x="${lw}" y="${y+2}" width="${w.toFixed(1)}" height="14" rx="3" style="fill:${it[2]||V_('up')}"/>`+tx(lw+w+4,y+13,prFmt(it[1])+(unit||''),{a:'start',fs:8.5,c:V_('ink')});});
  return svgw(W,H,s,lab||'Biểu đồ cột');
}
/* sơ đồ tiêu đề theo bit */
function prBits(F,i,rowBits){
  const rb=rowBits||32,W=372,x0=6,bw=(W-12)/rb,rh=32,y0=16;let s='',row=0,cur=0;const pos=[];
  F.forEach(f=>{const b=f[1];let n=1,x,w,h,y;
    if(b===0){if(cur>0){row++;cur=0;}x=0;w=rb;h=24;pos.push({x,y:row,w,h:24,v:1});row+=0.78;cur=0;return;}
    if(b>rb){n=Math.ceil(b/rb);if(cur>0){row++;cur=0;}pos.push({x:0,y:row,w:rb,h:Math.min(n,2)*rh/rh});row+=Math.min(n,2);cur=0;return;}
    if(cur+b>rb){row++;cur=0;}pos.push({x:cur,y:row,w:b,h:1});cur+=b;if(cur>=rb){row++;cur=0;}});
  const rows=row+(cur>0?1:0);const H=y0+rows*rh+8;
  for(let q=0;q<4;q++){const bb=q*rb/4;s+=tx(x0+bb*bw+2,10,bb,{a:'start',fs:7});}s+=tx(W-x0,10,rb-1,{a:'end',fs:7});
  pos.forEach((p,j)=>{const f=F[j],cur_=j===i,x=x0+p.x*bw,y=y0+p.y*rh,w=p.w*bw,h=p.v?p.h:p.h*rh-2,c=cur_?V_('warn'):V_('ink');
    s+=`<g data-gxs="pr:${j}" tabindex="0" role="button" style="cursor:pointer"><rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${w.toFixed(1)}" height="${(h).toFixed(1)}" rx="3" style="fill:${cur_?'color-mix(in srgb,'+V_('warn')+' 18%,'+V_('panel')+')':V_('panel2')};stroke:${c};stroke-width:${cur_?2.4:1.1}${p.v?';stroke-dasharray:4 3':''}"/>`;
    let fs=8.6,t=f[0];while(fs>5.6&&t.length*fs*0.56>w-4)fs-=0.4;if(t.length*fs*0.56>w-4)t=f[3]||t.slice(0,Math.max(1,Math.floor((w-4)/(fs*0.56))));
    const ty=y+(h>24?h/2-1:h/2-(w>40?2:-3));
    s+=tx(x+w/2,ty+1,t,{fs,b:1,c:V_('ink')});
    if(w>=34)s+=tx(x+w/2,ty+11,f[1]===0?'(độ dài thay đổi)':f[1]+' bit',{fs:6.8,c:V_('muted')});
    s+='</g>';});
  return svgw(W,H,s,'Cấu trúc tiêu đề theo bit');
}
function prHdrTbl(F){let off=0,fix=true;const rows=F.map(f=>{const b=f[1];let o,ln;
  if(b===0){o=fix?String(Math.floor(off/8)):'—';ln='thay đổi';fix=false;}else{o=fix?(off%8?Math.floor(off/8)+' (bit '+off%8+')':String(off/8)):'—';ln=b%8?b+' bit':b/8+' byte';if(fix)off+=b;}
  return[o,ln,'<b>'+esc(f[0])+'</b>',f[2]];});return{rows,fixed:fix?off/8:Math.floor(off/8),var:!fix};}
/* bản đồ giao diện của mạng di động; hl là danh sách mã liên kết */
function prMap(hl){
  const sa=S.mode==='SA',en=S.mode==='NSA';
  const N={ue:[4,100,40,'UE'],ran:[76,100,52,sa?'gNB':'eNB'],ran2:[76,30,52,sa?'gNB 2':'eNB 2'],amf:[164,30,66,sa?'AMF':'MME'],smf:[164,100,66,sa?'SMF':'S/PGW-C'],upf:[164,170,66,sa?'UPF':'S/PGW-U'],hss:[270,30,70,sa?'UDM, AUSF':'HSS'],pcf:[270,100,70,sa?'PCF':'PCRF'],dn:[270,170,70,'Internet, IMS']};
  const Lk={uu:['ue','ran',sa?'NR-Uu':'LTE-Uu'],xn:['ran','ran2',sa?'Xn':en?'X2, EN-DC':'X2'],ng:['ran','amf',sa?'N2':'S1-MME'],gu:['ran','upf',sa?'N3':'S1-U'],n11:['amf','smf',sa?'N11':'S11'],n4:['smf','upf',sa?'N4':'Sx'],n8:['amf','hss',sa?'N8':'S6a'],n7:['smf','pcf',sa?'N7':'Gx'],n6:['upf','dn',sa?'N6':'SGi']};
  let s='',lb='',nd='';const hn=new Set();
  const cn=k=>[N[k][0]+N[k][2]/2,N[k][1]+14];
  Object.keys(Lk).forEach(k=>{const [a,b,l]=Lk[k],on=hl.includes(k),A=cn(a),B=cn(b);if(on){hn.add(a);hn.add(b);}
    s+=li([A,B],{c:on?V_('warn'):V_('line'),w:on?3:1.3});
    const mx=(A[0]+B[0])/2,my=(A[1]+B[1])/2,w=l.length*4.5+6;
    lb+=`<rect x="${(mx-w/2).toFixed(1)}" y="${(my-6.5).toFixed(1)}" width="${w.toFixed(1)}" height="12" rx="3" style="fill:${V_('panel')}"/>`+tx(mx,my+3,l,{fs:8.5,b:on,c:on?V_('ink'):V_('muted')});});
  Object.keys(N).forEach(k=>{const n=N[k],on=hn.has(k);nd+=bx(n[0],n[1],n[2]+(n[2]<50?0:0),28,n[3],{w:on?2.8:1.2,c:on?V_('warn'):V_('ink'),fs:n[3].length>9?8.5:10});});
  return svgw(372,208,s+nd+lb,'Vị trí giao thức trong mạng di động');
}
const prModes=m=>[['S','5G SA'],['N','5G NSA'],['L','4G']].filter(x=>m.includes(x[0])).map(x=>x[1]).join(', ');
const prModeCh=()=>({SA:'S',NSA:'N',LTE:'L'}[S.mode]);
function prFaultSt(P,fl){return fl.st?fl.st:P.proc.st.slice(0,fl.keep===undefined?0:fl.keep).concat(fl.add||[]);}
function prCnt(P){const f=prFac();
  if(f==='hdr')return P.hdr.f.length;if(f==='proc')return P.proc.st.length;
  if(f==='flt'){const j=clamp(+S.prFt||0,0,P.flt.length-1);return Math.max(1,prFaultSt(P,P.flt[j]).length);}
  if(f==='app')return P.app.length;if(f==='std')return Math.max(1,P.wf.length);return 1;}
function prStepInfo(st,cols){return`<h3>${esc(st.m)}</h3><p>${st.d}</p>${st.fl?'<h3>Trường tin chính</h3>'+gxFl(st.fl):''}${st.chk?'<h3>Điểm cần kiểm tra</h3>'+gxUl(st.chk):''}`;}
function prR(P,i){
  const f=prFac(),fn=PRFL[f];let R={};
  if(f==='hdr'){const H=P.hdr;
    if(H.t==='text'){const L=H.f,cur=L[i]||L[0];
      R.fig=`<div style="font:11px/1.55 var(--mono);overflow-x:auto;background:var(--panel2);border:1px solid var(--line);border-radius:8px;padding:8px 6px">${L.map((r,j)=>`<div data-gxs="pr:${j}" tabindex="0" role="button" style="cursor:pointer;white-space:pre;padding:0 4px;border-radius:4px;${j===i?'background:color-mix(in srgb,var(--warn) 18%,var(--panel));outline:2px solid var(--warn);font-weight:700':''}">${esc(r[0])||'&nbsp;'}</div>`).join('')}</div>`;
      R.hint='Chạm vào một dòng để xem ý nghĩa.';R.cap=`${first(String(cur[1]).replace(/<[^>]+>/g,''))}`;
      R.out=kv('Dòng',`${i+1} trên ${L.length}`);R.info=`<h3>${esc(cur[0].trim()||'(dòng trống)')}</h3><p>${cur[1]}</p>`+(H.note?`<p class="note">${H.note}</p>`:'');
      R.tt='Các dòng của bản tin';R.tb=tbl(['Dòng','Ý nghĩa'],L.map(r=>['<code>'+esc(r[0].trim())+'</code>',r[1]]),i);}
    else{const cur=H.f[i]||H.f[0],T=prHdrTbl(H.f);
      R.fig=prBits(H.f,i,H.row);R.hint=`Mỗi hàng ${H.row||32} bit; trường dài hơn một hàng vẽ chiếm 1 đến 2 hàng, không theo đúng tỷ lệ. Chạm vào một trường để xem ý nghĩa.`;
      R.out=kv('Trường',`${i+1} trên ${H.f.length}`)+kv('Độ dài trường',cur[1]===0?'thay đổi':cur[1]+' bit')+kv('Tiêu đề',T.var?`${T.fixed} byte cố định, rồi phần thay đổi`:T.fixed+' byte');
      R.info=`<h3>${esc(cur[0])}</h3><p>${cur[2]}</p>`+(H.note?`<p class="note">${H.note}</p>`:'');R.tt='Các trường theo thứ tự trong gói';R.tb=tbl(['Byte','Độ dài','Trường','Ý nghĩa'],T.rows,i);R.cap=`${cur[0]}: ${first(String(cur[2]).replace(/<[^>]+>/g,''))}`;}}
  else if(f==='proc'||f==='flt'){
    const fl=f==='flt'?P.flt[clamp(+S.prFt||0,0,P.flt.length-1)]:null,steps=f==='flt'?prFaultSt(P,fl):P.proc.st,cols=(fl&&fl.cols)||P.proc.cols;
    const sp=steps.map(a=>Array.isArray(a)?prSt(a[0],a[1],a[2],a[3],a[4]):a),st=sp[clamp(i,0,sp.length-1)];
    R.fig=gxLadder(cols,sp,i,'pr');R.hint='Chạm vào một dòng để xem giải thích; chữ đỏ cam là bản tin hoặc sự kiện lỗi.';
    R.cap=`${st.m}: ${first(String(st.d).replace(/<[^>]+>/g,''))}`;
    R.out=kv('Bước',`${i+1} trên ${sp.length}`)+kv('Bản tin, sự kiện',esc(st.m))+(st.p?kv('Giao diện',st.p):'')+(st.f===st.t?'':kv('Từ, tới',`${cols[st.f]} → ${cols[st.t]}`))+(fl?kv('Tình huống',esc(fl.n)):'');
    R.info=prStepInfo(st,cols)+(f==='proc'&&P.proc.d?`<h3>Về thủ tục này</h3><p>${P.proc.d}</p>`:'');
    if(fl){R.info+=`<h3>Triệu chứng</h3><p>${fl.sym}</p><h3>Nguyên nhân thường gặp</h3>${gxUl(fl.cause)}<h3>Cách kiểm tra</h3>${gxUl(fl.chk)}<h3>Ảnh hưởng tới KPI</h3><p>${fl.kpi}</p>`;}}
  else if(f==='app'){const A=P.app,cur=A[clamp(i,0,A.length-1)],m=prModeCh();
    R.fig=prMap((cur[3]||'').split(',').filter(Boolean));R.hint='Đường màu cam là giao diện đang xem; tên giao diện đổi theo chế độ 5G SA, 5G NSA, 4G đang chọn.';
    R.out=kv('Giao diện, vị trí',cur[0])+kv('Dùng ở chế độ',prModes(cur[2]))+kv('Chế độ đang chọn',cur[2].includes(m)?'có dùng':'không dùng trong chế độ này');R.cap=`${cur[0]}: ${first(String(cur[1]))}`;
    R.info=`<h3>${cur[0]}</h3><p>${cur[1]}</p>`+(P.appn?gxUl(P.appn):'');R.tt='Nơi giao thức xuất hiện trong mạng di động';
    R.tb=tbl(['Giao diện, vị trí','Vai trò','Chế độ'],A.map(r=>[r[0],r[1],r[2].includes(m)?prModes(r[2]):'<span style="opacity:.55">'+prModes(r[2])+'</span>']),i);}
  else if(f==='std'){const W=P.wf,cur=W[clamp(i,0,W.length-1)];
    R.fig=`<div style="background:var(--panel2);border:1px solid var(--line);border-radius:8px;padding:10px"><div style="font:11px var(--mono);color:var(--muted);margin-bottom:6px">Ô lọc hiển thị (display filter) của Wireshark</div><div style="font:13px/1.4 var(--mono);background:var(--panel);border:2px solid var(--up);border-radius:6px;padding:7px 9px;overflow-x:auto;white-space:pre-wrap;word-break:break-all">${esc(cur[0])}</div></div>`;
    R.hint='Chạm vào một dòng trong danh sách để xem bộ lọc.';R.cap=`${cur[0]}: ${cur[1]}`;R.out=kv('Bộ lọc',`${clamp(i,0,W.length-1)+1} trên ${W.length}`)+kv('Ý nghĩa',cur[1]);
    R.info=`<h3>Bộ lọc Wireshark</h3>${gxOl('pr',W.map(r=>`<code>${esc(r[0])}</code> — ${r[1]}`),i)}`+(P.wfn?`<p class="note">${P.wfn}</p>`:'')+'<p class="note">Tên trường lọc ghi theo trí nhớ; nếu Wireshark báo trường không tồn tại thì bấm vào gói bất kỳ, chuột phải vào trường cần lọc, chọn "Apply as Filter" để lấy đúng tên theo phiên bản.</p>';
    R.tt='Tài liệu chuẩn tham chiếu';R.tb=tbl(['Tài liệu','Nội dung'],P.std);}
  else{const c=P.calc.run();R.fig=c.fig;R.out=c.out;R.info=`<h3>${P.calc.t}</h3>`+c.info;R.tb=c.tb||'';R.tt=c.tt||'';R.hint='Kéo thanh trượt hoặc đổi lựa chọn ở khung bên phải; kết quả và hình đổi theo.';R.cap=P.calc.t;}
  R.out=kv('Khía cạnh',fn)+(R.out||'');return R;
}
function P(view,id,d){
  const it={n:d.n,spec:d.spec,kind:'custom',P:d,cnt:()=>prCnt(d),r:i=>prR(d,i),ctl:()=>['prF','prFt'].concat(prFac()==='calc'?d.calc.ctl:[]),
    onCtl:k=>{if(k==='prF'||k==='prFt')S.prS=0;if(d.onc)d.onc(k);},
    idx:()=>[d.n,d.spec,d.hdr.f.map(r=>r[0]+' '+r[2]).join('; '),d.proc?d.proc.st.map(r=>(r[2]||'')+' '+(r[3]||'')).join('; '):'',(d.flt||[]).map(x=>x.n+' '+x.sym).join('; '),d.app.map(r=>r.slice(0,2).join(' ')).join('; '),d.std.map(r=>r.join(' ')).join('; '),d.wf.map(r=>r.join(' ')).join('; '),d.calc?d.calc.t:'',(d.ven||[]).join(' ')].join(' '),
    get ven(){return prFac()==='app'?(d.ven||PRVEN[view]):undefined;},get venH(){return d.ven?'Góc nhìn vendor:':'Góc nhìn vendor (chung cho nhóm):';}};
  PRV[view].items[id]=it;return it;
}

