 hdr:{f:[['Loại phần cứng',16,'1 = Ethernet.','HTYPE'],['Loại giao thức',16,'0x0800 = IPv4.','PTYPE'],['Dài MAC',8,'6 byte.','HLEN'],['Dài IP',8,'4 byte.','PLEN'],['Thao tác',16,'1 = yêu cầu (request), 2 = trả lời (reply); GARP dùng một trong hai với IP gửi bằng IP đích.','OPER'],['MAC bên gửi',48,'Địa chỉ phần cứng của máy gửi (SHA).','SHA'],['IP bên gửi',32,'Địa chỉ IPv4 của máy gửi (SPA).','SPA'],['MAC bên nhận',48,'Trong yêu cầu để 00:00:00:00:00:00 (chưa biết); trong trả lời là MAC của máy được hỏi (THA).','THA'],['IP bên nhận',32,'Địa chỉ IPv4 cần phân giải (TPA).','TPA']]},
 proc:{cols:['Máy A','Switch','Máy B','Router'],d:'ARP phân giải IPv4 thành MAC trong cùng một mạng lớp 2. Yêu cầu được quảng bá, trả lời là unicast.',st:[
  [0,0,'Tra bảng ARP','A cần gửi tới 10.1.1.2 nhưng chưa có MAC trong bảng ARP (cache).'],
  [0,1,'Request quảng bá','A gửi khung quảng bá: "ai có 10.1.1.2? trả lời cho 10.1.1.1".',{fl:[['MAC đích Ethernet','ff:ff:ff:ff:ff:ff'],['Thao tác','1 (request)'],['THA','00:00:00:00:00:00']]}],
  [1,2,'Switch tràn','Switch tràn quảng bá ra mọi cổng cùng VLAN.'],
  [2,0,'Reply unicast','B nhận ra IP mình, ghi A vào bảng và trả lời unicast kèm MAC của B.',{fl:[['Thao tác','2 (reply)'],['SHA','MAC của B']]}],
  [0,0,'Ghi bảng ARP','A lưu IP↔MAC của B, thời gian sống thường vài phút, rồi gửi gói IP đang chờ.'],
  [2,3,'ARP gratuitous','Khi đổi chủ/chuyển dự phòng (ví dụ VRRP chuyển Master), thiết bị mới gửi GARP để cập nhật bảng ARP của các máy.',{chk:['GARP có thể bị chặn bởi tính năng bảo mật (DAI)']}]]},
 flt:[{n:'ARP không trả lời (khác VLAN hoặc mask sai)',sym:'Ping báo "Destination Host Unreachable"; bảng ARP có mục "incomplete".',cause:['Hai máy khác VLAN nhưng cùng dải','Mask sai khiến máy nghĩ đích ngoài mạng hoặc trong mạng','Cổng switch đóng hoặc VLAN không cho phép'],chk:['Xem bảng ARP có mục chưa hoàn tất','Bắt gói: có request mà không có reply?','Đối chiếu VLAN, mask hai phía'],kpi:'Mất kết nối tới gateway của trạm/lõi; phiên dữ liệu qua PGW/UPF tới mạng ngoài không thông.',keep:3,add:[[0,1,'Request lặp lại','A gửi lại request nhiều lần không có hồi âm.',{bad:1}],[0,0,'Incomplete','Mục ARP ở trạng thái incomplete; gói IP chờ bị loại.',{bad:1}]]},
  {n:'Trùng địa chỉ IP',sym:'Kết nối chập chờn: lúc thông lúc không; log báo MAC của IP thay đổi.',cause:['Hai thiết bị cấu hình cùng IP','Thiết bị dự phòng lên Active hai bên (split-brain)'],chk:['Bắt gói: hai MAC khác nhau trả lời cho cùng một IP','Bật phát hiện xung đột (ARP probe theo RFC 5227)'],kpi:'Phiên lập chập chờn, lỗi ngẫu nhiên khó tái hiện; có thể rớt cuộc gọi nếu IP của P-CSCF/UPF bị trùng.',keep:3,add:[[2,0,'Reply từ B','Máy B trả lời với MAC của B.'],[3,0,'Reply từ thiết bị trùng IP','Thiết bị thứ hai cũng trả lời cho cùng IP với MAC khác.',{bad:1}],[0,0,'Bảng ARP nhảy','Bảng ARP của A đổi qua lại giữa hai MAC.',{bad:1}]]}],
 app:[['Gateway của trạm','Trạm hỏi ARP để tìm MAC của gateway (router truyền tải) trong VLAN của từng giao diện.','SNL','ng,gu'],['Cổng SGi / N6','PGW hoặc UPF hỏi ARP để tìm MAC của firewall/router kế tiếp khi cùng mạng lớp 2.','SNL','n6'],['VRRP/HSRP chuyển đổi','GARP sau khi chuyển Master giúp các máy học lại MAC ảo/mới ngay.','SNL','gu'],['IPv6','IPv6 không dùng ARP mà dùng ND (xem mục kế tiếp).','SNL','']],
