prC('prMtu','MTU liên kết truyền tải',[[1500,'1500 (Ethernet thường)'],[9000,'9000 (jumbo)'],[1400,'1400 (đường bị bọc thêm)'],[1280,'1280 (IPv6 tối thiểu)']],1500);
prC('prMo','IP của mạng truyền tải',[[4,'IPv4 (20 byte)'],[6,'IPv6 (40 byte)']],4);
prC('prMg','Bọc GTP-U',[[0,'Không'],[1,'4G: GTP-U 8 byte'],[2,'5G N3: GTP-U + container phiên (khoảng 16 byte)']],1);
prC('prMs','Bọc IPsec',[[0,'Không'],[1,'ESP tunnel, AES-GCM-128'],[2,'ESP tunnel, AES-CBC-128 + HMAC-SHA1-96']],0);
prC('prMu','IP của UE',[[4,'IPv4'],[6,'IPv6']],4);
prC('prMk','Gói UE gửi đi',[500,1500,10],1500,v=>v+' byte');
function prMtu(pk,g,sec,ov,L){const ip=ov===6?40:20,gh=g===0?0:g===1?8:16;let tot=pk;if(g)tot+=gh+8+ip;let pad=0,esp=0;
  if(sec){const gcm=sec===1,iv=gcm?8:16,icv=gcm?16:12,blk=gcm?4:16;pad=(blk-((tot+2)%blk))%blk;esp=ip+8+iv+pad+2+icv;tot+=esp;}return{tot,ip,gh,pad,esp};}
P('tcpip','ip',{n:'IPv4, IPv6 và tính MTU khi bọc GTP, IPsec',spec:'RFC 791, 8200, 1191, 8201; TS 29.281 (GTP-U); TS 23.060 Phụ lục C',
 hdr:{f:[['Phiên bản',4,'4 cho IPv4.','Ver'],['IHL',4,'Độ dài tiêu đề tính theo từ 32 bit (tối thiểu 5 = 20 byte).'],['DSCP',6,'Differentiated Services: phân loại QoS ở truyền tải; ánh xạ từ 5QI/QCI (ví dụ EF=46 cho thoại).'],['ECN',2,'Báo tắc nghẽn tường minh.'],['Tổng độ dài',16,'Tiêu đề + dữ liệu, tối đa 65535 byte.','Total Len'],['Nhận dạng',16,'ID chung cho các mảnh của cùng một gói.','ID'],['Cờ',3,'Bit DF (không phân mảnh) và MF (còn mảnh sau).'],['Độ lệch mảnh',13,'Vị trí mảnh theo đơn vị 8 byte.','Frag Off'],['TTL',8,'Số chặng còn lại; giảm 1 mỗi router.'],['Giao thức',8,'6 TCP, 17 UDP, 1 ICMP, 132 SCTP, 50 ESP, 47 GRE.','Proto'],['Checksum tiêu đề',16,'Chỉ bảo vệ tiêu đề IP.','Sum'],['IP nguồn',32,'Địa chỉ nguồn.'],['IP đích',32,'Địa chỉ đích.'],['Tuỳ chọn',0,'Ít dùng; làm gói bị xử lý chậm ở router.']],note:'IPv6 có tiêu đề cố định 40 byte: Version 4, Traffic Class 8, Flow Label 20, Payload Length 16, Next Header 8, Hop Limit 8, rồi IP nguồn 128 và IP đích 128 bit; không có checksum và router không phân mảnh (chỉ máy gửi, qua Fragment Header).'},
 proc:{cols:['UE','Trạm','Router','PGW, UPF'],d:'Gói của UE đi qua nhiều lớp bọc: GTP-U/UDP/IP của mạng truyền tải, và nếu bật thì IPsec. Mỗi lớp thêm byte; tổng vượt MTU thì bị phân mảnh hoặc loại.',st:[
  [0,1,'Gói IP của UE','UE gửi gói IP (ví dụ 1400 byte) qua bearer.',{p:'Uu'}],
  [1,1,'Bọc GTP-U','Trạm thêm GTP-U (8 byte, 5G có thêm container phiên), UDP 2152 (8 byte) và IP ngoài của truyền tải (20 hoặc 40 byte).',{p:'S1-U, N3'}],
  [1,1,'Bọc IPsec (nếu có)','Nếu truyền tải không tin cậy, ESP tunnel thêm IP ngoài mới, ESP, IV, đệm và ICV.'],
  [1,2,'Qua router','Router so tổng kích thước với MTU từng chặng. Vượt MTU và DF=0: phân mảnh IPv4; DF=1: loại và gửi ICMP.',{chk:['Kiểm tra MTU mọi chặng, kể cả cổng ảo']}],
  [2,3,'Tới PGW/UPF','Phía thu ghép các mảnh (nếu có), gỡ IPsec và GTP-U, lấy gói gốc ra mạng ngoài qua SGi/N6.'],
  [3,1,'Chiều xuống tương tự','Gói xuống được bọc ngược lại; lỗi MTU thường chỉ lộ ở một chiều khi đường đi không đối xứng.']]},
 flt:[{n:'Gói lớn bị mất, gói nhỏ bình thường',sym:'Ping nhỏ được, tải trang hoặc tệp lớn treo; một số ứng dụng chỉ chậm ở bước TLS/ảnh.',cause:['MTU truyền tải không đủ sau khi bọc GTP-U/IPsec','ICMP "cần phân mảnh" bị firewall chặn (PMTUD hố đen)','UE dùng MTU/MSS mặc định 1500 trong khi mạng chỉ cho 1358-1400'],chk:['Ping với DF và kích thước tăng dần tới khi mất','Xem MSS trong SYN/SYN-ACK có bị kẹp (MSS clamping) không','Dùng phần tính toán bên phải để tìm kích thước tối đa'],kpi:'Tốc độ tải thực tế thấp, ứng dụng web/video chập chờn dù RSRP, SINR tốt; không thấy trong KPI vô tuyến.',keep:2,add:[[1,1,'Gói vượt MTU','Gói đã bọc dài hơn MTU của chặng kế.',{bad:1}],[1,2,'DF=1 bị loại','Router loại gói; nếu ICMP bị chặn, máy gửi không hề biết.',{bad:1}],[0,0,'TCP treo','Dữ liệu lớn không tới; chỉ thấy phát lại mà không tiến triển.',{bad:1}]]},
  {n:'Phân mảnh quá nhiều làm nghẽn',sym:'Nhiều mảnh IP trên đường truyền; CPU thiết bị cao; thông lượng giảm.',cause:['Đặt DF=0 trên GTP-U nên mọi gói lớn bị phân mảnh','Lưu lượng UDP lớn (video, QUIC) đi qua đường MTU thấp'],chk:['Lọc ip.flags.mf==1 để đếm mảnh','Hạ MSS hoặc nâng MTU toàn tuyến'],kpi:'Độ trễ và jitter tăng, thông lượng giảm; nếu mất một mảnh thì mất cả gói.',keep:3,add:[[2,2,'Phân mảnh','Router cắt gói thành nhiều mảnh theo MTU.',{bad:1}],[2,3,'Nhiều mảnh','Mất một mảnh là mất cả gói gốc.',{bad:1}]]}],
 app:[['S1-U, N3 (người dùng)','Gói IP của UE nằm trong GTP-U; IP của truyền tải là IPv4 hoặc IPv6 tuỳ mạng.','SNL','gu'],['S1-MME, N2 (báo hiệu)','Báo hiệu SCTP trên IP; có thể bảo vệ bằng IPsec.','SNL','ng'],['X2, Xn','IP giữa các trạm, qua router truyền tải.','SNL','xn'],['SGi, N6','Gói IP của UE đi ra mạng ngoài; CGNAT/NAT64 xử lý ở biên này.','SNL','n6'],['IPv6 và IPv4v6','Mạng và UE có thể IPv4, IPv6 hoặc song song; mạng di động ngày càng ưu tiên IPv6.','SNL','uu,gu,n6']],
 appn:['Giá trị như 1358 byte hay 1400 byte cho MTU của UE thường được đặt qua PCO/ePCO để tránh phân mảnh; con số cụ thể tuỳ nhà mạng, xem TS 23.060 Phụ lục C và TS 23.501.'],
 std:[['RFC 791','IPv4'],['RFC 8200','IPv6'],['RFC 1191, 8201','Khám phá MTU đường đi (IPv4, IPv6)'],['RFC 4821','PMTUD ở lớp packetization (không phụ thuộc ICMP)'],['TS 29.281','GTP-U: kích thước tiêu đề'],['RFC 4303','ESP: tính phần thêm']],
 wf:[['ip.addr == 10.0.0.1','Gói có IP nguồn hoặc đích bằng 10.0.0.1 (IP ví dụ)'],['ip.flags.mf == 1 || ip.frag_offset > 0','Các mảnh IPv4'],['ip.flags.df == 1','Gói đặt DF'],['ip.dsfield.dscp == 46','Gói DSCP EF (thoại)'],['ipv6.fraghdr','Gói IPv6 có Fragment Header'],['frame.len > 1400','Khung dài hơn 1400 byte'],['ip.ttl < 5','Gói sắp hết TTL']],
 calc:{t:'MTU của UE khi bọc GTP-U và IPsec',ctl:['prMtu','prMo','prMg','prMs','prMu','prMk'],run(){
   const L=S.prMtu,ov=S.prMo,g=S.prMg,sec=S.prMs;let U=0;for(let u=L;u>=1;u--){if(prMtu(u,g,sec,ov,L).tot<=L){U=u;break;}}
   const cur=prMtu(S.prMk,g,sec,ov,L),m=prMtu(U,g,sec,ov,L),inner=S.prMu===6?60:40,mss=U-inner,ipH=ov===6?40:20;
   let fate;if(cur.tot<=L)fate=`Gói UE ${S.prMk} byte sau khi bọc dài ${cur.tot} byte, vừa MTU ${L}, đi bình thường.`;
   else if(ov===6)fate=`Gói ngoài ${cur.tot} byte vượt ${L}: router IPv6 không được phân mảnh, gói bị loại và gửi ICMPv6 Packet Too Big.`;
   else{const per=Math.floor((L-ipH)/8)*8,nf=Math.ceil((cur.tot-ipH)/per);fate=`Gói ngoài ${cur.tot} byte vượt ${L}: nếu DF=0 bị cắt thành ${nf} mảnh (mất một mảnh là mất cả gói); nếu DF=1 bị loại và gửi ICMP loại 3 mã 4.`;}
   const items=[['Gói của UE',U,V_('up')],['GTP-U',m.gh,V_('k1')],['UDP',g?8:0,V_('k4')],['IP ngoài (GTP)',g?m.ip:0,V_('cp')],['IPsec (IP+ESP+IV+đệm+ICV)',m.esp,V_('warn')]];
   return{fig:prBars(items,Math.max(U,60),' byte','Thành phần của gói lớn nhất vừa MTU'),
    out:prKv([['MTU tối đa cho UE',U+' byte'],['Phần thêm của đường truyền',(m.tot-U)+' byte'],['MSS TCP gợi ý',mss+' byte (MTU của UE trừ '+inner+' byte IP và TCP)'],['Đệm ESP',sec?m.pad+' byte':'không có'],['Số phận gói đang thử',fate]]),
    info:`<p>Thứ tự bọc: gói của UE → GTP-U → UDP 2152 → IP ngoài → (nếu có) ESP tunnel với IP ngoài mới. MTU lớn nhất cho UE là giá trị lớn nhất sao cho gói sau khi bọc không vượt MTU liên kết.</p><p>Giá trị GTP-U 5G (khoảng 16 byte) là ước lượng: 8 byte bắt buộc, 4 byte trường tuỳ chọn và một tiêu đề mở rộng PDU Session Container; tuỳ bản và tình huống. Đệm ESP lấy theo khối 4 byte (GCM) hoặc 16 byte (CBC). Mô hình không tính thẻ VLAN vì MTU IP đã không tính tiêu đề Ethernet.</p>`};}}});

