P('tcpip','quic',{n:'QUIC và HTTP/3',spec:'RFC 9000 (QUIC), 9001 (TLS trong QUIC), 9002 (phát lại), RFC 9114 (HTTP/3)',
 hdr:{f:[['Header Form',1,'1 = long header (lúc bắt tay), 0 = short header (sau khi xong).','HF'],['Fixed Bit',1,'Luôn bằng 1.','FB'],['Long Packet Type',2,'0 Initial, 1 0-RTT, 2 Handshake, 3 Retry.','LPT'],['Bit riêng loại',4,'Dự trữ và độ dài số gói (được bảo vệ bằng header protection).','Rsv'],['Version',32,'Phiên bản QUIC (0x00000001 cho QUIC v1).'],['DCID Len',8,'Độ dài Destination Connection ID.','DCIDL'],['Destination CID',0,'Định danh kết nối của bên nhận (tối đa 20 byte); giúp kết nối sống khi đổi IP.'],['SCID Len',8,'Độ dài Source Connection ID.','SCIDL'],['Source CID',0,'Định danh kết nối của bên gửi.'],['Token, Length, Packet Number, Payload',0,'Token (Initial), độ dài, số gói (mã hoá) và các khung (STREAM, ACK, CRYPTO...). Toàn bộ phần sau tiêu đề được mã hoá bằng AEAD.']],note:'QUIC chạy trên UDP, mã hoá gần như toàn bộ; mạng chỉ thấy cờ và CID. Số gói và ACK nằm trong phần đã mã hoá nên không thể phân tích phát lại như TCP.'},
 proc:{cols:['Máy khách','Máy chủ'],d:'QUIC gộp bắt tay vận chuyển và TLS 1.3: 1 RTT cho kết nối mới, 0 RTT khi tiếp tục phiên; ghép nhiều luồng không chặn nhau.',st:[
  [0,1,'Initial (CRYPTO)','Khách gửi Initial chứa ClientHello TLS 1.3, tối thiểu 1200 byte để chống khuếch đại.',{p:'UDP/443'}],
  [1,0,'Initial + Handshake','Chủ trả ServerHello, chứng chỉ, Finished; mã hoá từ khung Handshake.'],
  [0,1,'Handshake (Finished)','Khách hoàn tất; từ đây dữ liệu ứng dụng 1-RTT mã hoá.'],
  [0,1,'1-RTT (HTTP/3)','Khách gửi yêu cầu HTTP/3 trên luồng; mỗi luồng độc lập, mất gói một luồng không chặn luồng khác.'],
  [1,0,'ACK + dữ liệu','Chủ trả dữ liệu; ACK và điều khiển tắc nghẽn trong QUIC (CUBIC/BBR).'],
  [0,1,'0-RTT (phiên cũ)','Lần sau khách dùng khoá lưu để gửi dữ liệu ngay trong gói đầu (có rủi ro phát lại nên chỉ cho thao tác an toàn).'],
  [0,1,'Đổi mạng (migration)','Chuyển từ Wi-Fi sang di động: giữ nguyên CID, kết nối không đứt.']]},
 flt:[{n:'UDP/443 bị chặn hoặc giới hạn',sym:'Trang tải chậm một lúc rồi mới chạy; trình duyệt quay về HTTP/2 qua TCP.',cause:['Firewall chặn UDP 443','Giới hạn tốc độ UDP ở biên','NAT hết hạn ánh xạ UDP quá nhanh'],chk:['Xem Initial gửi đi có hồi âm không','Đo thời gian quay về TCP (fallback)'],kpi:'Thời gian tải trang tăng vài trăm ms; có thể thấy lưu lượng TCP/443 tăng cùng lúc.',keep:1,add:[[1,1,'Không trả lời','Không có gói Initial từ chủ (bị chặn).',{bad:1}],[0,0,'Hết hạn, về TCP','Sau một thời gian, trình duyệt thử lại bằng TCP+TLS.',{bad:1}]]},
  {n:'MTU thấp làm Initial không đi',sym:'Kết nối QUIC không lập được dù cổng mở.',cause:['Đường có MTU dưới 1252 (khuyến nghị tối thiểu cho QUIC)','Gói Initial 1200+ byte bị phân mảnh hoặc loại'],chk:['Xem kích thước UDP lớn nhất đi qua','Áp dụng phần tính MTU ở thẻ IPv4'],kpi:'Tỷ lệ HTTP/3 thấp bất thường ở một vùng.',keep:1,add:[[1,1,'Initial bị loại','Gói Initial (1200 byte) vượt MTU thực của đường.',{bad:1}],[0,0,'Phát lại PTO','Khách phát lại theo PTO nhưng không tiến triển.',{bad:1}]]}],
 app:[['Lưu lượng người dùng','Ứng dụng video, mạng xã hội, tìm kiếm dùng HTTP/3 trên QUIC; mạng chỉ thấy UDP/443, khó đo TCP RTT như trước.','SNL','uu,gu,n6'],['Đo chất lượng','Do mã hoá, chỉ số như thời gian tới byte đầu cần thu từ thiết bị/ứng dụng thay vì phân tích TCP.','SNL','gu'],['NAT và CGNAT','Thời gian giữ ánh xạ UDP ngắn làm kết nối QUIC rớt; cần keep-alive.','SNL','n6']],
 std:[['RFC 9000','QUIC: truyền tải đa luồng, mã hoá'],['RFC 9001','Dùng TLS 1.3 cho QUIC'],['RFC 9002','Phát hiện mất gói và điều khiển tắc nghẽn'],['RFC 9114','HTTP/3'],['RFC 9204','QPACK']],
 wf:[['quic','Mọi gói QUIC'],['quic.long.packet_type == 0','Gói Initial'],['quic.header_form == 1','Long header'],['udp.port == 443','UDP 443'],['tls.handshake.type == 1','ClientHello (đã giải mã trong Initial nếu có khoá)'],['http3','Khung HTTP/3 (cần khoá giải mã)']],
 calc:{t:'Thời gian tới byte đầu: TCP+TLS so với QUIC',ctl:['prQr','prQd'],run(){
   const r=S.prQr,d=S.prQd?r:0,items=[['TCP + TLS 1.2',d+4*r,V_('warn')],['TCP + TLS 1.3',d+3*r,V_('k4')],['QUIC 1-RTT',d+2*r,V_('up')],['QUIC 0-RTT',d+1*r,V_('k1')]];
   return{fig:prBars(items,items[0][1],' ms','Thời gian tới byte đầu của phản hồi'),out:prKv([['TCP + TLS 1.2',items[0][1]+' ms (4 RTT)'],['TCP + TLS 1.3',items[1][1]+' ms (3 RTT)'],['QUIC 1-RTT',items[2][1]+' ms (2 RTT)'],['QUIC 0-RTT',items[3][1]+' ms (1 RTT)']]),
    info:`<p>Đếm số RTT trước khi nhận byte đầu của phản hồi (bỏ qua xử lý máy chủ). TCP mất 1 RTT bắt tay, TLS 1.2 thêm 2 RTT, TLS 1.3 thêm 1 RTT, sau đó 1 RTT yêu cầu và phản hồi. QUIC gộp bắt tay vận chuyển và TLS nên chỉ 1 RTT bắt tay (kết nối mới) hoặc 0 (tiếp tục phiên).</p><p>Trên di động RTT 50 đến 100 ms thì chênh lệch lên tới vài trăm ms mỗi lần mở kết nối. Mô hình lý thuyết, bỏ qua mất gói và TCP Fast Open.</p>`};}}});

/* --- TLS 1.3 --- */
P('tcpip','tls',{n:'TLS 1.3',spec:'RFC 8446 (TLS 1.3), RFC 5246 (TLS 1.2), RFC 6066 (SNI)',
 hdr:{f:[['Content Type',8,'20 ChangeCipherSpec (giữ tương thích), 21 Alert, 22 Handshake, 23 Application Data.','Type'],['Legacy Version',16,'Luôn 0x0303 (TLS 1.2) để tránh thiết bị trung gian chặn; phiên bản thật nằm trong extension supported_versions.','Ver'],['Length',16,'Độ dài bản ghi (tối đa 2^14 + 256 byte).'],['Handshake Type',8,'1 ClientHello, 2 ServerHello, 8 EncryptedExtensions, 11 Certificate, 15 CertificateVerify, 20 Finished.','HsType'],['Handshake Length',24,'Độ dài bản tin bắt tay.','HsLen'],['Legacy Version (Hello)',16,'0x0303.','LegV'],['Random',256,'32 byte ngẫu nhiên; trong ServerHello có giá trị đặc biệt khi hạ cấp.'],['Session ID, Cipher Suites, Extensions',0,'Danh sách bộ mã (TLS_AES_128_GCM_SHA256...), và các extension: supported_versions, key_share (X25519), server_name (SNI), ALPN, signature_algorithms.']],note:'Từ ServerHello trở đi mọi bản tin bắt tay đều được mã hoá, chỉ thấy Content Type 23 bên ngoài.'},
 proc:{cols:['Máy khách','Máy chủ'],d:'TLS 1.3 xong bắt tay sau 1 RTT: khách đoán trước nhóm khoá và gửi key_share ngay trong ClientHello.',st:[
  [0,1,'ClientHello','Gửi phiên bản hỗ trợ, bộ mã, key_share (X25519), SNI, ALPN.',{k:'tls',fl:[['supported_versions','TLS 1.3'],['key_share','X25519'],['server_name','tên dịch vụ (SNI)'],['ALPN','h2, http/1.1']]}],
  [1,0,'ServerHello','Chọn bộ mã và nhóm khoá; từ đây hai bên suy ra khoá bắt tay.',{k:'tls'}],
  [1,0,'EncryptedExtensions, Certificate','Chứng chỉ máy chủ được gửi đã mã hoá.',{k:'tls'}],
  [1,0,'CertificateVerify, Finished','Chủ ký xác nhận và báo hoàn tất.',{k:'tls'}],
  [0,1,'Finished','Khách kiểm tra chứng chỉ (chuỗi tin cậy, tên, hạn dùng) rồi gửi Finished; dữ liệu ứng dụng bắt đầu.',{k:'tls'}],
  [0,1,'Application Data','Dữ liệu được mã hoá bằng AEAD (AES-GCM hoặc ChaCha20-Poly1305).',{k:'tls'}],
  [1,0,'NewSessionTicket','Chủ gửi vé phiên để lần sau tiếp tục nhanh (PSK, 0-RTT).',{k:'tls'}]]},
 flt:[{n:'Chứng chỉ hết hạn hoặc không tin cậy',sym:'Kết nối đóng ngay sau Certificate; trình duyệt báo lỗi chứng chỉ; ứng dụng không mở được.',cause:['Chứng chỉ hết hạn','Thiếu chứng chỉ trung gian trong chuỗi','Đồng hồ thiết bị lệch','Tên (SAN) không khớp SNI'],chk:['Xem Alert gửi đi (certificate_expired, unknown_ca, bad_certificate)','So ngày hiệu lực chứng chỉ với giờ hệ thống','Kiểm tra chuỗi chứng chỉ đầy đủ'],kpi:'Với SBI 5GC dùng TLS giữa NF: lỗi này làm NF không gọi được nhau; thiết lập phiên PDU thất bại hàng loạt.',keep:4,add:[[0,1,'Alert: bad_certificate','Khách đóng kết nối với Alert phù hợp.',{bad:1,k:'tls'}],[1,0,'Đóng','Kết nối bị đóng, không có dữ liệu.',{bad:1}]]},
  {n:'Không có phiên bản hoặc bộ mã chung',sym:'Lỗi handshake_failure hoặc protocol_version ngay sau ClientHello.',cause:['Máy chủ chỉ cho TLS 1.2 mà khách chỉ TLS 1.3 (hoặc ngược lại)','Bộ mã bị tắt theo chính sách bảo mật'],chk:['Xem Alert (protocol_version 70, handshake_failure 40)','So danh sách cipher suites hai phía'],kpi:'Kết nối giữa NF hoặc với ứng dụng thất bại ngay, tỷ lệ thành công = 0 cho cặp đó.',keep:1,add:[[1,0,'Alert: handshake_failure','Chủ không chọn được tham số chung.',{bad:1,k:'tls'}]]}],
 app:[['SBI giữa các NF của 5GC','Các NF gọi nhau bằng HTTP/2 trên TLS (khuyến nghị bắt buộc), có xác thực hai chiều (mTLS).','S','n11,n8,n7'],['IMS và tầng ứng dụng','SIP qua TLS (cổng 5061), RCS, XCAP dùng TLS.','SNL','uu,gu,n6'],['Quản lý','NETCONF/SSH, RESTCONF, gNMI dùng TLS/SSH; web OAM dùng HTTPS.','SNL',''],['Dữ liệu người dùng','HTTPS chiếm đa số lưu lượng; mạng không thấy nội dung, chỉ thấy SNI/IP.','SNL','uu,gu,n6']],
 std:[['RFC 8446','TLS 1.3'],['RFC 5246','TLS 1.2'],['RFC 6066','Các extension (SNI)'],['TS 33.501 mục 13','Bảo mật miền dịch vụ: TLS, OAuth2 trong 5GC'],['TS 33.210','Bảo mật miền mạng (IPsec, TLS)']],
 wf:[['tls','Mọi gói TLS'],['tls.handshake.type == 1','ClientHello'],['tls.handshake.extensions_server_name','Tên trong SNI'],['tls.alert_message','Bản tin Alert'],['tls.record.version == 0x0304','Bản ghi TLS 1.3 (hiếm; thường 0x0303 ngoài)'],['tls.handshake.type == 11','Certificate (chưa mã hoá trong TLS 1.2)']]});

