prC('prRc','Bộ mã (tham số E-model minh hoạ)',[['g711','G.711'],['amr','AMR-NB 12,2'],['amrwb','AMR-WB 12,65'],['evs','EVS 13,2']],'amrwb');
prC('prRd','Trễ mạng một chiều',[20,400,10],60,v=>v+' ms');
prC('prRj','Độ lệch jitter σ',[0,100,2],10,v=>v+' ms');
prC('prRb','Độ sâu bộ đệm jitter',[0,300,10],60,v=>v+' ms');
prC('prRn','Mất gói mạng',[0,10,0.5],0.5,v=>v+' %');
const PRIE={g711:[0,25.1],amr:[5,10],amrwb:[3,13],evs:[2,15]};
function prMos(c,dn,sg,jb,ln){const late=sg>0?Math.exp(-jb/sg):(jb>=0?0:1),ppl=100*(1-(1-ln/100)*(1-late)),Ta=dn+jb+40,Id=0.024*Ta+(Ta>177.3?0.11*(Ta-177.3):0),ie=PRIE[c][0],bpl=PRIE[c][1],ieE=ie+(95-ie)*ppl/(ppl+bpl),R=Math.max(0,Math.min(100,93.2-Id-ieE)),mos=R<=0?1:R>=100?4.5:1+0.035*R+R*(R-60)*(100-R)*7e-6;return{late:late*100,ppl,Ta,Id,ieE,R,mos};}
P('ims','rtp',{n:'RTP: jitter buffer và chất lượng thoại (E-model)',spec:'RFC 3550 (RTP, RTCP), RFC 3551; ITU-T G.107 (E-model), G.113, G.114; TS 26.114 (bộ đệm jitter)',
 hdr:{f:[['Version',2,'Luôn 2.','V'],['Padding',1,'Có byte đệm cuối gói.','P'],['Extension',1,'Có phần mở rộng tiêu đề.','X'],['CSRC Count',4,'Số nguồn đóng góp (CSRC) theo sau; 0 ở cuộc gọi hai bên.','CC'],['Marker',1,'Đánh dấu: đầu đợt nói (talkspurt) hoặc khung quan trọng.','M'],['Payload Type',7,'Loại tải: tĩnh (0 PCMU, 8 PCMA) hoặc động 96 đến 127 gán bởi SDP (AMR-WB thường 96 đến 110).','PT'],['Sequence Number',16,'Tăng 1 mỗi gói: bên nhận phát hiện mất và sai thứ tự.','Seq'],['Timestamp',32,'Mốc lấy mẫu của khung đầu tiên (đơn vị theo tốc độ lấy mẫu: 8000 hoặc 16000 Hz); dùng tính jitter.'],['SSRC',32,'Định danh nguồn đồng bộ: mỗi hướng một giá trị; thay đổi giữa cuộc gọi là dấu hiệu lỗi.'],['Tải trọng',0,'Khung mã hoá, có CMR và ToC với AMR.']]},
 proc:{cols:['Bên gửi','Mạng','Bộ đệm jitter','Bộ giải mã'],d:'Mạng làm gói đến không đều (jitter). Bộ đệm jitter giữ gói thêm một khoảng rồi phát đều; gói đến quá muộn bị coi là mất.',st:[
  [0,1,'Gói RTP mỗi 20 ms','Bên gửi phát gói đều đặn, Seq và Timestamp tăng đều.',{k:'med'}],
  [1,2,'Gói đến không đều','Mạng làm trễ khác nhau: có gói tới dồn, có gói tới muộn.',{k:'med'}],
  [2,2,'Giữ trong bộ đệm','Mỗi gói được giữ tới thời điểm phát = (thời điểm phát gói đầu) + (Timestamp) + độ sâu bộ đệm.'],
  [2,3,'Phát đều','Gói đến kịp được trao cho bộ giải mã đúng nhịp 20 ms.',{k:'med'}],
  [2,2,'Gói muộn bị loại','Gói đến sau thời điểm phát bị bỏ; bộ giải mã dùng ẩn mất gói (PLC).',{bad:1}],
  [2,2,'Bộ đệm thích nghi','Bộ đệm thích nghi tăng độ sâu khi jitter tăng và giảm khi ổn định (TS 26.114 có quy định tối thiểu).']]},
 flt:[{n:'Jitter cao: tiếng đứt quãng',sym:'Nghe lạo xạo, rơi từ, nhất là khi di chuyển hoặc tải cao.',cause:['Hàng đợi vô tuyến hoặc truyền tải tăng trễ','Bộ đệm jitter quá nhỏ','Chuyển giao làm gián đoạn vài chục ms'],chk:['Xem jitter trong RTCP RR hoặc phân tích RTP của Wireshark','Dùng phần tính toán để xem MOS theo độ sâu bộ đệm'],kpi:'MOS ước tính giảm, tỷ lệ mất gói hiệu dụng tăng dù mất gói mạng thấp; chất lượng thoại VoLTE xấu.',keep:3,add:[[1,2,'Gói đến muộn','Một gói đến sau thời điểm phát.',{bad:1,k:'med'}],[2,3,'Ẩn mất gói','Bộ giải mã chèn khung giả; nghe méo.',{bad:1}]]},
  {n:'Một chiều (không có RTP một hướng)',sym:'Một bên không nghe thấy bên kia.',cause:['SSRC/cổng sai ở một hướng','Firewall chặn UDP hướng đó','Bearer QCI 1 chưa lập cho một bên'],chk:['Bắt gói hai đầu: có RTP theo hướng đó không','Kiểm tra SDP (IP, cổng) và bearer QCI 1','Áp quy tắc silent call: RTCP mất trên 80 % trong một cửa sổ'],kpi:'Tỷ lệ silent call, mất tiếng một chiều tăng.',keep:1,add:[[1,2,'Không có gói','Không gói RTP nào tới bên nhận.',{bad:1,k:'med'}],[2,2,'Bộ đệm rỗng','Bộ giải mã chỉ chèn khung im lặng.',{bad:1}]]}],
 app:[['UE ↔ UE qua bearer QCI 1','Tiếng nói đi trong RTP qua bearer QCI 1/5QI 1, bảo đảm tốc độ, qua trạm, lõi và biên IMS.','SNL','uu,gu,n6'],['Bộ đệm jitter của UE','Nằm trong UE; mạng chỉ gián tiếp ảnh hưởng qua jitter.','SNL','uu'],['TrGW, SBC','Neo và chuyển mã media ở biên IMS.','SNL','n6'],['Đo chất lượng','Probe lấy RTP/RTCP để tính MOS, mất gói, jitter, silent call.','SNL','gu']],
 std:[['RFC 3550','RTP và RTCP'],['RFC 3551','Hồ sơ RTP cho hội nghị âm thanh'],['RFC 4867','Payload AMR/AMR-WB'],['ITU-T G.107','E-model: tính R và MOS'],['ITU-T G.113','Giá trị suy giảm thiết bị Ie, Bpl'],['ITU-T G.114','Khuyến nghị trễ một chiều'],['TS 26.114','Bộ đệm jitter, yêu cầu hiệu năng']],
 wf:[['rtp','Mọi gói RTP'],['rtp.ssrc == 0x12345678','Một luồng theo SSRC (ví dụ)'],['rtp.p_type == 96','Loại tải động 96 (thường AMR-WB)'],['rtp.marker == 1','Gói có marker (đầu đợt nói)'],['rtp.seq','Số thứ tự'],['rtpevent','DTMF theo RFC 4733'],['rtp.padding','Gói có đệm']],
 wfn:'Wireshark có thể phân tích luồng RTP (menu Telephony → RTP → Stream Analysis) để cho mất gói, jitter, trễ.',
 calc:{t:'MOS theo trễ, jitter, bộ đệm và mất gói (E-model G.107 rút gọn)',ctl:['prRc','prRd','prRj','prRb','prRn'],run(){
   const c=S.prRc,dn=S.prRd,sg=S.prRj,jb=S.prRb,ln=S.prRn,m=prMos(c,dn,sg,jb,ln),pts=[];for(let b=0;b<=300;b+=5)pts.push([b,prMos(c,dn,sg,b,ln).mos]);
   return{fig:prChart({xr:[0,300],yr:[1,4.6],series:[{p:pts,l:'MOS'}],mk:[[jb,m.mos,prF1(m.mos,2)]],hz:[[4,'MOS 4']],xl:'Độ sâu bộ đệm jitter (ms)',yl:'MOS',xf:v=>Math.round(v),yf:v=>prF1(v,1),lab:'MOS theo độ sâu bộ đệm jitter'}),
    out:prKv([['MOS ước tính',prF1(m.mos,2)],['Hệ số R',prF1(m.R,1)],['Trễ một chiều Ta',prF1(m.Ta,0)+' ms (mạng + bộ đệm + 40 ms mã hoá, giải mã, gói hoá)'],['Gói muộn bị loại',prF1(m.late,1)+' %'],['Mất gói hiệu dụng',prF1(m.ppl,1)+' %'],['Suy giảm do trễ Id, do mất gói Ie,eff',prF1(m.Id,1)+', '+prF1(m.ieE,1)]]),
    info:`<p>Hai lực kéo ngược nhau: bộ đệm sâu thì ít gói muộn nhưng tăng trễ; bộ đệm nông thì ít trễ nhưng mất nhiều gói. Đường cong có đỉnh: đó là độ sâu tối ưu cho jitter σ đã chọn. Mô hình: gói muộn = e^(−độ sâu/σ) (jitter phân bố mũ); R = 93,2 − Id − Ie,eff; Id theo xấp xỉ Cole–Rosenbluth; Ie,eff = Ie + (95 − Ie) × Ppl / (Ppl + Bpl) với mất gói ngẫu nhiên; MOS suy từ R theo G.107.</p><p>Giá trị Ie và Bpl trong bảng là con số minh hoạ gần G.113, không phải số chuẩn của từng bộ mã, đặc biệt AMR-WB và EVS (dùng thang băng rộng riêng). Dùng để hiểu xu hướng, không dùng làm kết luận SLA.</p>`};}}});

