function prBgpBest(){const p=[1,2].map(n=>({n,lp:S['prGl'+(n===1?'p':'q')],as:S['prGa'+n],og:S['prGo'+n],med:S['prGm'+n],ib:S['prGe'+n],igp:S['prGi'+n]}));
 const [a,b]=p;const steps=[['Weight (Cisco, cục bộ)',0,0,'không dùng ở ví dụ'],['Local-Pref cao hơn',a.lp,b.lp,-1],['AS-Path ngắn hơn',a.as,b.as,1],['Origin thấp hơn (IGP < EGP < Incomplete)',a.og,b.og,1],['MED thấp hơn (cùng AS láng giềng)',a.med,b.med,1],['eBGP hơn iBGP',a.ib,b.ib,1],['IGP metric tới next hop thấp hơn',a.igp,b.igp,1]];
 for(let i=1;i<steps.length;i++){const s=steps[i],x=s[1],y=s[2];if(x!==y){const w=(s[3]===-1?(x>y):(x<y))?1:2;return{win:w,step:i,name:s[0],a,b,steps};}}return{win:0,step:-1,name:'Hết các bước so sánh: dùng Router ID thấp hơn',a,b,steps};}
