P('sm','syslog',{n:'Syslog',spec:'RFC 5424 (Syslog), RFC 3164 (BSD, cũ), RFC 5425 (TLS), RFC 5426 (UDP); UDP 514, TCP/TLS 6514',
 hdr:{t:'text',f:[['<PRI>','PRI = Facility × 8 + Severity; ví dụ <165> = local4.notice.'],['VERSION','1 cho RFC 5424.'],['TIMESTAMP','Thời gian RFC 3339, ví dụ 2026-01-01T00:00:00+07:00.'],['HOSTNAME APP-NAME PROCID MSGID','Tên máy, ứng dụng, tiến trình, loại bản tin.'],['STRUCTURED-DATA','Cặp khoá-giá trị có cấu trúc [id k="v"] hoặc "-".'],['MSG','Nội dung tự do.'],['Mức nghiêm trọng (severity)','0 Emergency, 1 Alert, 2 Critical, 3 Error, 4 Warning, 5 Notice, 6 Informational, 7 Debug.']],note:'Ví dụ tự tạo: <165>1 2026-01-01T00:00:00+07:00 gnb-test-01 ran 1234 LINK - Interface eth0 down. Không chứa dữ liệu thật.'},
 proc:{cols:['Thiết bị','Máy chủ syslog'],d:'Thiết bị gửi bản tin một chiều; UDP không bảo đảm, TCP/TLS tin cậy hơn.',st:[
  [0,1,'Bản tin syslog (UDP 514)','Gửi và quên: không xác nhận.',{k:'mgmt',p:'UDP 514'}],
  [0,1,'Bản tin qua TCP/TLS 6514','Có kết nối, có thứ tự, có mã hoá.',{k:'mgmt'}],
  [1,1,'Lọc theo severity','Máy chủ lưu, cảnh báo ở mức Error trở lên.'],
  [0,1,'Log storm','Thiết bị gửi hàng loạt khi sự cố; UDP dễ mất.',{k:'mgmt'}]]},
 flt:[{n:'Mất log do UDP',sym:'Sự cố xảy ra nhưng không có log tương ứng.',cause:['Hàng đợi/CPU quá tải','Mạng quản lý tắc nghẽn'],chk:['Đối chiếu số thứ tự (sequence)','Chuyển sang TCP/TLS hoặc tách mạng quản lý'],kpi:'Mất bằng chứng điều tra; khó xác định nguyên nhân.',keep:3,add:[[0,1,'Log storm','Nhiều bản tin trong thời gian ngắn.',{bad:1,k:'mgmt'}],[1,1,'Mất bản tin','Bộ đệm nhận đầy, loại.',{bad:1}]]}],
 app:[['Nhật ký thiết bị mạng','Tập trung nhật ký của router, trạm, lõi.','SNL','n8'],['Tương quan sự cố','Dùng mốc thời gian (NTP) để ghép log nhiều nút.','SNL','n8'],['Bảo mật','Log truy cập, thay đổi cấu hình phục vụ kiểm toán.','SNL','n8']],
 std:[['RFC 5424','Giao thức Syslog'],['RFC 5425','Syslog trên TLS'],['RFC 5426','Syslog trên UDP']],
 wf:[['syslog','Mọi bản tin syslog'],['syslog.level <= 3','Mức Error trở lên'],['syslog.facility == 20','local4'],['syslog.msg contains "down"','Nội dung chứa "down"']],
 calc:{t:'Tải log bình thường và khi sự cố',ctl:['prLn','prLr','prLb','prLs'],run(){
   const n=S.prLn,r=S.prLr,b=S.prLb,s=S.prLs,nm=n*r,st=nm*b,bm=nm*s*8/1e6,bs=st*s*8/1e6;
   return{fig:prBars([['Bình thường',nm,V_('up')],['Khi sự cố',st,V_('warn')]],Math.max(st,1),' dòng/s','Dòng log mỗi giây'),out:prKv([['Bình thường',prFmt(nm)+' dòng/s, '+prF1(bm,1)+' Mbit/s'],['Khi sự cố',prFmt(st)+' dòng/s, '+prF1(bs,1)+' Mbit/s'],['Dung lượng lưu 1 ngày (bình thường)',prF1(nm*s*86400/1e9,1)+' GB']]),
    info:`<p>Thiết kế cho đỉnh sự cố chứ không cho tải trung bình: khi hỏng một liên kết, nhiều thiết bị cùng ghi log. Hệ số ×20 là giả định minh hoạ.</p>`};}}});

/* --- TWAMP / Y.1731 --- */
prC('prWp','Số gói thử',[10,1000,10],100,v=>String(v));
prC('prWd','Trễ một chiều trung bình',[1,50,1],5,v=>v+' ms');
prC('prWj','Độ lệch chuẩn của trễ',[0,20,1],2,v=>v+' ms');
prC('prWl','Mất gói thực',[0,10,0.5],1,v=>v+' %');
P('sm','twamp',{n:'TWAMP và đo hiệu năng (ITU-T Y.1731)',spec:'RFC 5357 (TWAMP), RFC 4656 (OWAMP), RFC 8762 (STAMP), ITU-T Y.1731 (OAM Ethernet)',
 hdr:{f:[['Sequence Number',32,'Số thứ tự gói thử.','Seq'],['Timestamp',64,'Thời điểm gửi (NTP format).'],['Error Estimate',16,'Ước lượng sai số đồng hồ.','Err Est'],['MBZ',16,'Phải bằng 0.'],['Receive Timestamp',64,'(Gói phản hồi) thời điểm bên reflector nhận.','Rx TS'],['Sender Sequence Number',32,'(Phản hồi) số thứ tự gốc.','Snd Seq'],['Sender Timestamp',64,'(Phản hồi) thời điểm gửi gốc.','Snd TS'],['Sender TTL',8,'(Phản hồi) TTL gói gốc.','TTL'],['Packet Padding',0,'Đệm để đạt kích thước thử mong muốn.']],note:'TWAMP-Test chạy trên UDP; TWAMP-Control (TCP 862) thiết lập phiên. STAMP (RFC 8762) đơn giản hoá, không cần điều khiển phức tạp. Y.1731 thực hiện đo trễ, mất gói, jitter ở lớp Ethernet (DMM, LMM).'},
 proc:{cols:['Sender','Reflector'],d:'Sender gửi gói thử có số thứ tự và thời điểm; reflector phản hồi; từ đó tính trễ, jitter, mất gói.',st:[
  [0,1,'TWAMP-Control: Request-TW-Session','Thoả thuận cổng và tham số (qua TCP).',{k:'mgmt',p:'TCP 862'}],
  [1,0,'Accept-Session','Chấp nhận, trả cổng UDP.',{k:'mgmt'}],
  [0,1,'Start-Sessions','Bắt đầu đo.',{k:'mgmt'}],
  [0,1,'Test packet (Seq, T1)','Gói thử UDP.',{k:'mgmt'}],
  [1,0,'Reflected packet (T2, T3)','Phản hồi mang T2 (nhận) và T3 (gửi).',{k:'mgmt'}],
  [0,0,'Tính RTT, jitter, mất gói','RTT = (T4−T1)−(T3−T2).']]},
 flt:[{n:'Mất gói giả do ưu tiên QoS thấp',sym:'Đo TWAMP báo mất gói trong khi dịch vụ thật bình thường.',cause:['Gói thử bị xếp lớp ưu tiên thấp','Reflector bị giới hạn tốc độ'],chk:['Đặt DSCP của gói thử giống dịch vụ cần đo','Kiểm tra giới hạn trên reflector'],kpi:'Đo sai chất lượng; cảnh báo SLA sai.',keep:3,add:[[0,1,'Test packet','Gói thử dùng DSCP 0.',{bad:1,k:'mgmt'}],[0,0,'Mất gói','Hàng đợi ưu tiên thấp bị loại.',{bad:1}]]}],
 app:[['Đo SLA truyền tải','Độ trễ một chiều, jitter cho đường thoại và dữ liệu URLLC.','SNL','n3'],['Y.1731 trên Ethernet','Đo trễ, mất khung trên đường Ethernet backhaul.','SNL','n3'],['Đồng bộ hoá giờ','Đo một chiều cần đồng hồ đồng bộ (PTP/GNSS).','SNL','n3']],
 std:[['RFC 5357','TWAMP'],['RFC 8762','STAMP'],['ITU-T Y.1731','Hiệu năng OAM Ethernet'],['RFC 7679','Trễ một chiều (IPPM)']],
 wf:[['twamp','Mọi gói TWAMP'],['twamp.test','Gói thử'],['udp.dstport == 862','Cổng điều khiển TWAMP (TCP 862 là điều khiển)']],
 calc:{t:'Độ tin cậy của phép đo với số gói thử',ctl:['prWp','prWd','prWj','prWl'],run(){
   const n=S.prWp,d=S.prWd,sd=S.prWj,p=S.prWl/100,se=sd/Math.sqrt(n),ci=1.96*se,pse=Math.sqrt(Math.max(p*(1-p),1e-9)/n)*100;
   const pts=[];[10,30,100,300,1000].forEach(x=>pts.push([x,1.96*sd/Math.sqrt(x)]));
   return{fig:prChart({xr:[10,1000],yr:[0,Math.max(...pts.map(q=>q[1]))*1.15||1],series:[{p:pts,l:'Khoảng tin cậy 95 %'}],mk:[[n,ci,'±'+prF1(ci,2)+' ms']],xl:'Số gói thử',yl:'± ms',xf:v=>Math.round(v),yf:v=>prF1(v,1),lab:'Độ chính xác của trễ trung bình'}),
    out:prKv([['Trễ trung bình đo được',prF1(d,1)+' ± '+prF1(ci,2)+' ms (95 %)'],['Mất gói đo được',prF1(p*100,1)+' ± '+prF1(1.96*pse,2)+' điểm phần trăm (xấp xỉ)'],['Muốn sai số trễ ≤ 0,5 ms',sd?Math.ceil(Math.pow(1.96*sd/0.5,2))+' gói':'1 gói']]),
    info:`<p>Khoảng tin cậy của trung bình tỷ lệ với độ lệch chuẩn chia căn bậc hai của số mẫu: muốn chính xác gấp đôi cần gấp bốn số gói. Tỷ lệ mất gói thấp cần nhiều gói hơn để thấy (xấp xỉ chuẩn, kém khi p rất nhỏ). Giả định các mẫu độc lập, thực tế trễ thường tương quan theo thời gian nên khoảng thật rộng hơn.</p>`};}}});

gxDef('pr',{label:'Giao thức',il:'Giao thức',hold:3000,
 lead:()=>'Mỗi giao thức được xem theo sáu khía cạnh: cấu trúc tiêu đề (trường, byte), thủ tục từng bước, giả lập lỗi, ứng dụng trong mạng di động (giao diện nào), chuẩn tham chiếu kèm bộ lọc Wireshark, và tính toán tương tác khi có. Chọn nhóm, giao thức rồi khía cạnh ở khung bên phải; nút trên thanh trên cùng đổi chế độ 5G SA, 5G NSA, 4G và vendor.',
 note:PRNOTE,
 views:Object.fromEntries(Object.entries(PRV).filter(([k,v])=>Object.keys(v.items).length).map(([k,v])=>[k,{n:v.n,items:v.items}]))});

/* ================= Đợt 2: thẻ Truyền dẫn (tx) và Tường lửa (fw) ================= */
const TXNOTE='<p class="note">Theo ITU-T G.8271, G.8272, G.8273.2, G.8275.1, G.8032, G.709, G.694.1, ITU-R P.530, P.837, P.838, IEEE 802.1Q, 802.3, IETF RFC 4364, 4271, 2328, 5880, 8402 (SR), 9256 (SR-MPLS), 7432, MEF 6.2, 10.4, O-RAN WG9, eCPRI. Các phép tính là mô hình đơn giản để hiểu quy luật, không thay cho khảo sát tuyến, đo OTDR, đo OSNR hay thiết kế chính thức. Dòng sản phẩm, tên tính năng và lệnh của Cisco, Juniper, Huawei, Nokia ghi theo trí nhớ, là lệnh cơ bản phổ biến: kiểm tra theo phiên bản phần mềm, riêng PTP và QoS thay đổi nhiều theo nền tảng. Địa chỉ, số AS (64496, dải tài liệu), VLAN, nhãn trong ví dụ đều tự đặt.</p>';
const TXVD=[['std','Chuẩn (IETF, ITU-T, IEEE, MEF)'],['cisco','Cisco (IOS-XR, IOS-XE)'],['juniper','Juniper (Junos)'],['huawei','Huawei (VRP)'],['nokia','Nokia SR OS']];
const TXVDN={std:'Chuẩn',cisco:'Cisco',juniper:'Juniper',huawei:'Huawei',nokia:'Nokia SR OS'};
Object.assign(S,{txVd:'std'});
C.txVd={l:'Góc nhìn vendor truyền dẫn',o:()=>TXVD};
const txBox=h=>(h&&h[S.txVd])?`<h3 style="margin-top:12px">Góc nhìn: ${TXVDN[S.txVd]}</h3><div style="font-size:13.5px">${h[S.txVd]}</div>`:'';
const TXH={
 arch:{std:'Khung chuẩn: ITU-T G.8271, G.8272, G.8273 (đồng bộ), G.8032 (ERPS), IEEE 802.1Q, MEF 6.x và 10.x (dịch vụ E-Line, E-LAN), RFC 4364 và 7432 (VPN), O-RAN WG9 (truyền tải), eCPRI.',cisco:'Dòng thường gặp (theo hiểu biết chung): NCS 540 hoặc ASR 920 làm router cell site, NCS 5500 và ASR 9000 làm tập hợp và biên; chạy IOS-XR hoặc IOS-XE, hỗ trợ SR-MPLS, EVPN, PTP, SyncE.',juniper:'Dòng thường gặp: ACX làm cell site và tập hợp, MX và PTX làm biên và lõi; chạy Junos, hỗ trợ SR, EVPN, PTP, SyncE.',huawei:'Dòng thường gặp: ATN làm cell site, NE40E, NE8000 hoặc CX600 làm tập hợp và lõi; chạy VRP, hỗ trợ SR, EVPN, FlexE, PTP.',nokia:'Dòng thường gặp: 7705 SAR làm cell site, 7250 IXR làm tập hợp, 7750 SR làm biên và lõi; chạy SR OS, hỗ trợ SR, EVPN, FlexE, PTP.'},
 link:{std:'Vi ba: ITU-R P.530 (tính tuyến), P.838 (suy hao mưa), P.837 (cường độ mưa), ETSI EN 302 217 (thiết bị). Quang: ITU-T G.652 (sợi), G.694.1 (lưới DWDM), G.709 (OTN), IEEE 802.3 (cổng quang).',cisco:'Router thường dùng module quang cắm được (SFP, QSFP) và có thể dùng module coherent cắm trực tiếp cho tuyến ngắn. Thiết bị vi ba là thiết bị riêng của hãng vi ba, nối vào router bằng cổng Ethernet; router chỉ thấy cổng Ethernet.',juniper:'Giống Cisco: module quang cắm được, đọc DDM bằng lệnh show interfaces diagnostics optics. Vi ba nối vào bằng Ethernet.',huawei:'Huawei có cả dòng vi ba, dòng truyền tải quang (WDM, OTN) và router; việc tích hợp quản lý thường nằm ở hệ thống quản lý chung. Router đọc thông tin module quang bằng lệnh display transceiver.',nokia:'Nokia có dòng DWDM/OTN (1830 PSS) và router; SR OS đọc DDM bằng lệnh show port … optical. Vi ba nối vào router bằng Ethernet.'},
 ip:{std:'MPLS: RFC 3031, LDP RFC 5036, RSVP-TE RFC 3209; SR: RFC 8402, 8660 (SR-MPLS); L3VPN RFC 4364; EVPN RFC 7432; DiffServ RFC 2474, 4594; H-QoS không có chuẩn riêng; FlexE: OIF FlexE IA 2.x.',cisco:'XR dùng MQC (class-map, policy-map, service-policy) cho QoS; SR-TE dùng policy với color và endpoint, có PCE (PCEP) bên ngoài.',juniper:'Junos dùng class-of-service (classifier, forwarding-class, scheduler-map) và hierarchical-scheduler cho H-QoS; SR-TE qua segment-routing traffic-engineering.',huawei:'VRP dùng traffic classifier, behavior, policy và hàng đợi theo cổng; FlexE có trên dòng NE; SR-TE Policy tương tự khái niệm chuẩn.',nokia:'SR OS tách QoS ở SAP (sap-ingress, sap-egress), scheduler-policy phân cấp; SR-TE LSP/policy có thể tạo bằng PCC/PCE.'},
 cfg:null,
 flt:{std:'Cảnh báo giao diện: ITU-T G.806 và G.707 (LOS, LOF), IEEE 802.3 (link fault), RFC 5880 (BFD), ITU-T Y.1731 và IEEE 802.1ag (CFM) để dò lỗi Ethernet đầu cuối.',cisco:'Dùng show interfaces, show controllers (đọc DDM), show logging; lỗi liên kết thấy ở log; counters CRC, input errors tăng khi BER cao.',juniper:'Dùng show interfaces extensive (counters lỗi), show interfaces diagnostics optics; alarm hệ thống ở show chassis alarms.',huawei:'Dùng display interface (lỗi CRC), display transceiver verbose (DDM), display alarm active; log ở display logbuffer.',nokia:'Dùng show port detail (lỗi, trạng thái), show port … optical (DDM), show log log-id; alarm ở show system alarms hoặc log events.'}};
const TXVEN={ /* góc nhìn trạm vô tuyến, theo nút Huawei / Nokia / Ericsson trên thanh trên cùng */
 seg:['Trạm Huawei nối backhaul bằng cổng Ethernet/quang, có thể dùng IPsec, VLAN, BFD và định tuyến tĩnh hoặc OSPF tới router cell site; đồng bộ qua PTP, SyncE, GNSS. Tên tham số tra theo phiên bản.','Trạm Nokia (AirScale) nối backhaul tương tự, cấu hình VLAN, IP, IPsec, QoS ở khối truyền tải; dùng GNSS hoặc PTP, SyncE. Tên đối tượng tra theo tài liệu từng bản phát hành.','Trạm Ericsson (Radio Processing/Baseband) nối backhaul bằng Ethernet; phần định tuyến hay do Router 6000 phía ngoài đảm nhận; đồng bộ qua GNSS, PTP, SyncE. Tra tài liệu đúng bản phát hành.']};
const txFlt=a=>a;
/* ---- tiện ích tạo điều khiển ---- */
const txSel=(k,l,opts,def)=>prC(k,l,opts,def);
const txSl=(k,l,mn,mx,st,def,f)=>prC(k,l,[mn,mx,st],def,f);
const txP=(v,n)=>String(prF1(v,n===undefined?1:n)).replace('.',',');
const txMinPerYear=u=>u*525600;
const txFmtT=s=>s<1?txP(s*1000,0)+' ms':s<120?txP(s,0)+' giây':s<7200?txP(s/60,0)+' phút':txP(s/3600,1)+' giờ';

/* ====== Kiến trúc và yêu cầu ====== */
const txSeg=()=>({nodes:[['ru',4,8,64,30,'RU','ăng-ten'],['du',100,8,64,30,'DU','F1'],['cu',196,8,64,30,'CU','gNB-CU'],['up',292,8,64,30,'UPF, AMF','lõi'],
 ['gb',4,78,64,30,'gNB','D-RAN'],['csr',100,78,64,30,'CSR','cell site'],['ag',196,78,64,30,'AGG','tập hợp'],['co',292,78,64,30,'IP lõi','P, PE'],
 ['gm',196,148,64,30,'PRTC','GM PTP'],['os',292,148,64,30,'OSS','quản lý']],
 links:[['ru','du','FH'],['du','cu','F1'],['cu','up','NG'],['cu','ag','Backhaul'],['gb','csr','S1/NG'],['csr','ag','MPLS'],['ag','co','MPLS'],['co','up','N3'],['gm','ag','PTP'],['os','co','OAM']],
 steps:[[['ru','du'],['ru-du'],'Fronthaul (RU tới DU)','Đoạn nối cụm vô tuyến với xử lý băng gốc. Dùng CPRI (option 7, 8 cũ) hoặc eCPRI với tách chức năng 7.2x (O-RAN), chạy trên Ethernet 10/25 Gb/s. Đòi hỏi trễ một chiều rất thấp (cỡ 100 µs, ước lượng) và đồng bộ chặt, nên dây ngắn, ít chặng, thường quang trực tiếp hoặc WDM thụ động.',[['Giao diện','CPRI, eCPRI (O-RAN 7.2x)'],['Cự ly điển hình','vài km đến vài chục km'],['Đòi hỏi','trễ cỡ 100 µs, băng thông lớn (xem phần Yêu cầu)']]],
  [['du','cu'],['du-cu'],'Midhaul (DU tới CU), giao diện F1','F1-C (SCTP) và F1-U (GTP-U) chạy trên IP, tách CU và DU theo 3GPP TS 38.470. Băng thông gần bằng backhaul, trễ nới hơn fronthaul (cỡ ms, ước lượng); thường đi qua mạng IP/MPLS.',[['Giao diện','F1-C trên SCTP, F1-U trên GTP-U'],['Chuẩn','3GPP TS 38.470, 38.473']]],
  [['cu','ag','co','up'],['cu-ag','ag-co','co-up'],'Backhaul (CU hoặc gNB tới lõi)','NG-C (SCTP) và NG-U (GTP-U), ở 4G là S1-MME và S1-U, đi qua mạng truyền tải IP/MPLS tới AMF và UPF. Mỗi loại lưu lượng nên nằm trong VRF/VLAN riêng; QoS phân lớp theo DSCP.',[['Giao diện','N2/N3 (5G SA), S1 (4G, 5G NSA)'],['Trễ một chiều','vài ms tới vài chục ms tuỳ điểm đặt UPF']]],
  [['gb','csr','ag'],['gb-csr','csr-ag'],'Mô hình D-RAN (trạm đặt trọn bộ tại site)','Không có fronthaul dài: gNB nằm ngay tại site, chỉ cần backhaul. Router cell site (CSR) gom S1/NG, X2/Xn, OAM thành các VLAN rồi đẩy lên tập hợp.'],
  [['csr','ag','co'],['csr-ag','ag-co'],'Ba tầng: truy nhập, tập hợp, lõi','Truy nhập (cell site tới nút tập hợp): ring hoặc sao, 1 đến 10 Gb/s, có thể là vi ba. Tập hợp: ring/mesh 10 đến 100 Gb/s. Lõi IP: mesh 100 đến 400 Gb/s. Ring dễ có đường dự phòng bằng ERPS (G.8032) hoặc IGP/TI-LFA; sao đơn giản nhưng mỗi site một điểm hỏng.'],
  [['gm','ag','csr','gb'],['gm-ag','ag-csr','csr-gb'],'Đồng bộ phân phối từ trên xuống','Đồng hồ chủ (PRTC, GNSS) ở lõi hoặc tập hợp, phân phối PTP/SyncE xuống từng cell site qua các boundary clock. TDD cần pha chuẩn, sai số mạng cỡ ±1,5 µs (G.8271.1). Không nên dựa riêng GNSS tại từng site vì dễ bị nhiễu và cần sẵn sàng khi mất tín hiệu.',[['Chuẩn','ITU-T G.8271.1, G.8275.1'],['Yêu cầu pha (TDD)','±1,5 µs đầu cuối'],['Yêu cầu tần số','±50 ppb ở giao diện vô tuyến']]],
  [['os','co'],['os-co'],'Quản lý (OAM)','Mạng quản lý riêng (VRF OAM) cho SSH, SNMP, NETCONF, syslog, tải phần mềm. Không trộn với lưu lượng người dùng; chặn bằng ACL hoặc tường lửa.']]});
const txTopo=()=>{
  const N=S.txN,A=+S.txLa,u=1-A,h2=Math.ceil(N/2),pw=(x,n)=>Math.pow(x,n),lg=Math.max(2,Math.ceil(Math.log2(N)));
  const T=[['Chuỗi (daisy chain), site cuối',N,N,pw(A,N)],['Sao đơn tuyến',N,1,A],['Sao hai hướng (dual-homed)',2*N,1,1-pw(u,2)],['Vòng (ring), site xa nhất',N,h2,1-(1-pw(A,h2))*(1-pw(A,N-h2))],['Lưới một phần (mỗi nút 3 liên kết)',Math.ceil(1.5*N),lg,1-pw(1-pw(A,lg),2)]];
  return T.map(r=>({n:r[0],links:r[1],hops:r[2],av:r[3],nines:Math.min(9,-log10(Math.max(1-r[3],1e-9))),min:txMinPerYear(1-r[3])}));};
const txBwSel=[['20','20 MHz, SCS 30 kHz (51 PRB)'],['40','40 MHz, SCS 30 kHz (106 PRB)'],['60','60 MHz, SCS 30 kHz (162 PRB)'],['80','80 MHz, SCS 30 kHz (217 PRB)'],['100','100 MHz, SCS 30 kHz (273 PRB)'],['f100','FR2 100 MHz, SCS 120 kHz (66 PRB)'],['f200','FR2 200 MHz, SCS 120 kHz (132 PRB)'],['f400','FR2 400 MHz, SCS 120 kHz (264 PRB)']];
const TXBW={'20':[51,1,1024],'40':[106,1,2048],'60':[162,1,2048],'80':[217,1,4096],'100':[273,1,4096],'f100':[66,3,1024],'f200':[132,3,2048],'f400':[264,3,4096]};
Object.assign(S,{txBwK:'100',txLy:4,txQm:8,txSc:3,txAv:20,txIps:'no',txIq:9,txAnt:64,txN:12,txLa:'0.9999',txKm:10,txHp:3,txHd:10});
txSel('txBwK','Băng thông sóng mang',txBwSel,'100');
