txSel('txMd','Điều chế mục tiêu',TXMOD.map((m,j)=>[j,m[0]]),3);
txSel('txXp','XPIC (hai phân cực)',[['no','Không'],['yes','Có, dung lượng gấp đôi']],'no');
txSel('txBr','Suy hao ống dẫn sóng, bộ phân nhánh',[['0.5','ODU gắn trực tiếp (0,5 dB)'],['3','Có bộ phân nhánh 1+1 (3 dB)']],'0.5');
txSel('txCl','Hệ số khí hậu đa đường (Vigants)',[['0.25','Núi, khô (0,25)'],['1','Trung bình (1)'],['4','Ẩm, đồng bằng, qua mặt nước (4)']],'4');
function txMwCalc(){
  const f=+S.txF,d=+S.txD,k=TXB[S.txF],G=17.8+20*log10(f)+20*log10(+S.txDia),fs=92.45+20*log10(f)+20*log10(d),gas=k[2]*d,br=+S.txBr,pr=+S.txPt+2*G-fs-br-gas;
  const R=+S.txR,gam=k[0]*Math.pow(R,k[1]),d0=35*Math.exp(-0.015*Math.min(R,100)),deff=d/(1+d/d0),a001=gam*deff,Ap=p=>a001*0.12*Math.pow(p,-(0.546+0.043*log10(p)));
  const bw=+S.txBwc,xp=S.txXp==='yes',thr=m=>TXMOD[m][2]+10*log10(bw/28)+(xp?1.5:0);
  const pRain=fm=>{if(fm<=Ap(1))return 1;if(fm>=Ap(0.001))return 0.001;let lo=-3,hi=0;for(let i=0;i<40;i++){const mid=(lo+hi)/2;if(Ap(Math.pow(10,mid))>fm)lo=mid;else hi=mid;}return Math.pow(10,(lo+hi)/2);};
  const un=fm=>{const pr_=pRain(fm)/100,pm=Math.min(1,2.5e-6*(+S.txCl)*f*Math.pow(d,3)*Math.pow(10,-fm/10));return{rain:pr_,multi:pm,tot:Math.min(1,pr_+pm)};};
  const cap=m=>bw*TXMOD[m][1]*0.77*(xp?2:1);
  return{f,d,G,fs,gas,pr,gam,deff,a001,Ap,thr,pRain,un,cap,xp};}
const txMw=()=>{const c=txMwCalc(),m=+S.txMd,fm=c.pr-c.thr(m),u=c.un(fm),pr_=c.pRain(fm),nn=-log10(pr_/100);
  const pts=[];for(let n=2;n<=5.001;n+=0.25)pts.push([n,c.Ap(100*Math.pow(10,-n))]);
  const rows=TXMOD.map((md,j)=>{const f_=c.pr-c.thr(j),uu=c.un(f_);return[md[0],txP(c.thr(j),0)+' dBm',txP(f_,1)+' dB',txP(c.cap(j),0)+' Mb/s',f_<=0?'<span style="color:var(--warn)">không đạt</span>':txP((1-uu.tot)*100,4)+' %'];});
  return{fig:prChart({xr:[2,5],yr:[0,Math.max(c.Ap(0.001),fm)*1.15||1],series:[{p:pts,l:'Suy hao mưa'}],hz:[[fm,'Dự trữ fading '+txP(fm,1)+' dB']],mk:fm>0&&nn>=2&&nn<=5?[[nn,fm,txP(100-pr_,3)+' %']]:[],xl:'Số chữ số 9 của độ khả dụng do mưa (2 = 99 %)',yl:'dB',xf:v=>String(Math.round(v*100)/100),yf:v=>txP(v,0),lab:'Suy hao do mưa theo thời gian vượt'}),
   hint:'Điểm cam là nơi dự trữ fading (đường đứt) cắt đường suy hao mưa: thời gian vượt đó là xác suất tuyến mất khi dùng điều chế đã chọn.',
   out:prKv([['Mức thu (RSL)',txP(c.pr,1)+' dBm'],['Ngưỡng '+TXMOD[m][0]+' ở '+S.txBwc+' MHz',txP(c.thr(m),0)+' dBm'],['Dự trữ fading',txP(fm,1)+' dB'],['Suy hao mưa 0,01 %',txP(c.a001,1)+' dB (đường hiệu dụng '+txP(c.deff,1)+' km)'],['Độ khả dụng ước lượng',fm<=0?'tuyến không thông':txP((1-u.tot)*100,4)+' % (mưa '+txP(u.rain*1e5,1)+' + đa đường '+txP(u.multi*1e5,1)+', đơn vị 10⁻⁵)'],['Gián đoạn mỗi năm',fm<=0?'—':txP(txMinPerYear(u.tot),0)+' phút'],['Dung lượng',txP(c.cap(m),0)+' Mb/s'+(c.xp?' (XPIC)':'')]]),
   tt:'Điều chế thích ứng (ACM): dung lượng và độ khả dụng theo từng mức',tb:tbl(['Điều chế','Ngưỡng thu','Dự trữ fading','Dung lượng','Khả dụng ước lượng'],rows,m),
   info:`<p><b>Quỹ đường truyền.</b> RSL = công suất phát + hai lần độ lợi ăng-ten (17,8 + 20·log f(GHz) + 20·log D(m) dBi, hiệu suất 55 %) − suy hao không gian tự do (92,45 + 20·log f + 20·log d) − suy hao ống dẫn − hấp thụ khí. Dự trữ fading = RSL − ngưỡng thu của điều chế.</p><p><b>Mưa</b> theo ITU-R P.838 (γ = k·R^α, phân cực ngang cho an toàn) và P.530: chiều dài hiệu dụng d/(1 + d/d₀) với d₀ = 35·e^(−0,015·R), A(p) = A₀,₀₁ · 0,12 · p^−(0,546 + 0,043·log p). <b>Đa đường</b> (quan trọng dưới 10 GHz và tuyến dài) dùng công thức Vigants cũ: 2,5·10⁻⁶ · c · f · d³ · 10^(−FM/10), chỉ để so sánh tương đối.</p><p><b>ACM</b>: khi mưa mạnh thiết bị tự hạ điều chế, dung lượng giảm nhưng tuyến còn thông; lưu lượng ưu tiên (thoại, đồng bộ, báo hiệu) phải được QoS bảo vệ khi dung lượng tụt. Hệ số k, α, thế khí, ngưỡng thu và dung lượng theo kênh ETSI trong bảng là xấp xỉ, lấy số thật từ datasheet và phần mềm quy hoạch tuyến; vùng mưa lấy theo ITU-R P.837 đúng toạ độ.</p>`};};
const txMwt=()=>({
 pts:[['Dải tần và cự ly điển hình','6 đến 8 GHz: tuyến dài 30 đến 100 km, ít bị mưa, nhiều đa đường. 11 đến 15 GHz: 10 đến 40 km. 18 đến 23 GHz: 5 đến 20 km (vùng mưa nhiệt đới thường chỉ 8 đến 12 km cho 99,99 %). 26 đến 38 GHz: 2 đến 10 km. E-band (71 đến 76 và 81 đến 86 GHz): 1 đến 3 km, dung lượng nhiều Gb/s, chịu mưa kém nên hay ghép với một tuyến băng thấp (multi-band).'],
  ['Điều chế thích ứng (ACM)','Tự nâng hạ điều chế (QPSK … 4096QAM) theo chất lượng tín hiệu; thay đổi không gây mất khung (hitless) với thiết bị tốt. Dung lượng đỉnh dùng khi trời quang, dung lượng thấp nhất giữ cho lưu lượng ưu tiên khi mưa.'],
  ['XPIC và ghép kênh','XPIC dùng hai phân cực trực giao trên cùng kênh để nhân đôi dung lượng, bộ khử nhiễu chéo xử lý rò giữa hai phân cực. Có thể gộp nhiều sóng mang (link aggregation hoặc gộp lớp vật lý) để tăng dung lượng.'],
  ['Bảo vệ tuyến','1+0 không bảo vệ; 1+1 HSB (thiết bị dự phòng, cùng tần số); 1+1 FD (hai tần số) hoặc SD (hai ăng-ten) chống fading đa đường; 2+0 để tăng dung lượng.'],
  ['Giao diện và OAM','Nối router bằng Ethernet, có thể mang cả đồng bộ (SyncE, PTP) nên cần boundary clock hoặc thiết bị hỗ trợ; đo bằng Y.1731, CFM. Cần cẩn thận bất đối xứng khi ACM, vì đường lên và xuống có thể khác điều chế.'],
  ['Chuẩn','ETSI EN 302 217 (thiết bị, ăng-ten), ITU-R P.530 (tính tuyến), F.746 và F.2006 (băng tần, E-band), ITU-T G.826 (chỉ tiêu lỗi).']],
 tb:()=>['Cự ly điển hình theo dải tần (ước lượng, nhiệt đới)',['Dải tần','Cự ly 99,99 %','Dung lượng điển hình','Ghi chú'],[['6 đến 8 GHz','30 đến 80 km','đến vài trăm Mb/s','nhạy đa đường; cần diversity'],['11 đến 15 GHz','10 đến 30 km','đến 1 Gb/s','cân bằng cự ly và dung lượng'],['18 đến 23 GHz','5 đến 12 km','đến vài Gb/s (XPIC, kênh rộng)','phổ biến cho backhaul'],['26 đến 38 GHz','2 đến 6 km','vài Gb/s','dễ bị mưa'],['E-band','1 đến 3 km','đến 10 Gb/s','cần tầm nhìn thẳng, ăng-ten nhỏ']]]});
