Object.assign(S,{txSfp:'lr',txTx:-8.2,txRx:-14.4,txOv:0.5,txKmF:10,txWl:'1310',txCn:4,txMg:3});
txSel('txSfp','Loại module quang (đặt sẵn tham số)',Object.entries(TXSFP).map(([k,v])=>[k,v[0]]),'lr');
txSl('txTx','Công suất phát tối thiểu',-12,6,0.5,-8.2,v=>txP(v,1)+' dBm');
