txSl('txMg','Dự trữ lão hoá, sửa chữa',0,6,0.5,3,v=>txP(v,1)+' dB');
function txFibCalc(km){const a=S.txWl==='1550'?0.25:0.4,loss=a*km+S.txCn*0.5+Math.floor(km/2)*0.1;return{loss,rx:S.txTx-loss,a};}
const txFib=()=>{const km=S.txKmF,c=txFibCalc(km),need=S.txRx+S.txMg,mg=c.rx-need,over=c.rx>S.txOv,reach=Math.max(0,(S.txTx-need-S.txCn*0.5)/(c.a+0.05)),pts=[];for(let x=0;x<=90;x+=10)pts.push([x,txFibCalc(x).rx]);
  return{fig:prChart({xr:[0,90],yr:[-30,6],series:[{p:pts,l:'Mức thu'}],hz:[[need,'Nhạy + dự trữ'],[S.txOv,'Quá tải']],mk:[[km,clamp(c.rx,-30,6),txP(c.rx,1)+' dBm']],xl:'Chiều dài sợi (km)',yl:'dBm',xf:v=>Math.round(v),yf:v=>Math.round(v),lab:'Mức thu theo chiều dài sợi'}),
   hint:'Đường đứt dưới là mức thu tối thiểu (độ nhạy cộng dự trữ); đường đứt trên là ngưỡng quá tải của bộ thu, cần gắn suy hao nếu mức thu vượt.',
   out:prKv([['Tổng suy hao tuyến',txP(c.loss,1)+' dB (sợi '+txP(c.a*km,1)+', đầu nối '+txP(S.txCn*0.5,1)+', mối hàn '+txP(Math.floor(km/2)*0.1,1)+')'],['Mức thu',txP(c.rx,1)+' dBm'],['Dự trữ quỹ công suất',mg>=0?txP(mg,1)+' dB':'<b>thiếu '+txP(-mg,1)+' dB</b>'],['Kết luận',mg<0?'không đạt, cần module công suất cao hơn hoặc rút ngắn tuyến':over?'đạt nhưng mức thu vượt ngưỡng quá tải: gắn suy hao '+txP(c.rx-S.txOv+1,0)+' dB':'đạt'],['Cự ly tối đa ước lượng',txP(reach,0)+' km']]),
   info:`<p>Quỹ công suất: mức thu = công suất phát − (suy hao sợi + đầu nối + mối hàn). Tuyến đạt khi mức thu ≥ độ nhạy + dự trữ và ≤ ngưỡng quá tải. Suy hao thiết kế: sợi G.652 cỡ 0,35 đến 0,4 dB/km ở 1310 nm, 0,22 đến 0,25 dB/km ở 1550 nm; đầu nối ≈ 0,5 dB (thiết kế, thực tế 0,2 đến 0,3); mối hàn ≈ 0,1 dB cứ 2 km. Giá trị công suất và độ nhạy của module lấy từ chuẩn IEEE 802.3 hoặc datasheet, có sai khác theo hãng.</p><p>Kiểm tra thực tế bằng máy đo công suất (power meter), OTDR và đọc DDM (Rx power, Tx power, nhiệt độ) từ module bằng lệnh của router. Đầu nối bẩn là nguyên nhân hàng đầu của BER cao và flap.</p>`};};
txSl('txSpn','Số chặng khuếch đại (span)',1,20,1,6,v=>String(v));
txSl('txSl','Suy hao một chặng',10,35,1,22,v=>v+' dB');
txSl('txNf','Hệ số nhiễu bộ khuếch đại (NF)',4,7,0.5,5.5,v=>txP(v,1)+' dB');
txSl('txPc','Công suất mỗi kênh vào sợi',-3,5,0.5,0,v=>txP(v,1)+' dBm');
txSel('txRt','Tốc độ, điều chế kênh',[[11,'10G OOK/NRZ (cần ≈ 11 dB)'],[12,'100G DP-QPSK coherent (≈ 12 dB)'],[19,'200G DP-16QAM (≈ 19 dB)'],[23,'400G DP-16QAM (≈ 23 dB)']],12);
const txOsnr=()=>{const N=S.txSpn,req=+S.txRt,mg=3,f=n=>58+S.txPc-S.txSl-S.txNf-10*log10(n),o=f(N),maxN=Math.floor(Math.pow(10,(58+S.txPc-S.txSl-S.txNf-req-mg)/10)),pts=[];for(let n=1;n<=20;n++)pts.push([n,f(n)]);
  return{fig:prChart({xr:[1,20],yr:[5,Math.max(40,f(1))],series:[{p:pts,l:'OSNR (0,1 nm)'}],hz:[[req+mg,'Cần + 3 dB']],mk:[[N,o,txP(o,1)+' dB']],xl:'Số chặng',yl:'dB',xf:v=>Math.round(v),yf:v=>Math.round(v),lab:'OSNR theo số chặng khuếch đại'}),
   hint:'OSNR giảm 3 dB mỗi khi số chặng gấp đôi; tuyến đạt khi đường cong còn trên đường đứt.',
   out:prKv([['OSNR cuối tuyến',txP(o,1)+' dB (băng tham chiếu 0,1 nm)'],['Yêu cầu của kênh',req+' dB, cộng dự trữ 3 dB'],['Dư',o-req-mg>=0?txP(o-req-mg,1)+' dB':'<b>thiếu '+txP(req+mg-o,1)+' dB</b>'],['Số chặng tối đa',String(Math.max(0,maxN))]]),
   info:`<p>OSNR ≈ 58 + P<sub>kênh</sub> − L<sub>chặng</sub> − NF − 10·log(N) (dB, băng tham chiếu 0,1 nm, tại 1550 nm; hằng 58 dB suy từ năng lượng photon). Giá trị OSNR yêu cầu là xấp xỉ điển hình cho từng điều chế và mã sửa lỗi; lấy số thật theo datasheet module/transponder. Bỏ qua phi tuyến sợi, ảnh hưởng ROADM/bộ lọc, tán sắc và PMD.</p>`};};
const txOtn=()=>({
 pts:[['Lưới DWDM và CWDM','DWDM theo ITU-T G.694.1: lưới 100 GHz (khoảng 48 đến 40 kênh C-band) hoặc 50 GHz (96 kênh) và lưới linh hoạt (flex-grid); CWDM theo G.694.2: 18 bước sóng cách nhau 20 nm (1271 đến 1611 nm). Dùng WDM thụ động (CWDM/DWDM mux) để chở nhiều kênh fronthaul trên một đôi sợi.'],
  ['OTN (G.709)','Đóng gói dịch vụ vào ODU (ODU0, 1, 2, 2e, 3, 4, flex), thêm FEC, giám sát (TCM) và bảo vệ. Cho phép chuyển mạch ở lớp ODU, giám sát chất lượng đầu cuối, và chở nhiều dịch vụ Ethernet qua một bước sóng.'],
  ['Fronthaul trên WDM','Hai cách: bước sóng màu cắm trực tiếp vào RU/DU (passive WDM), hoặc transponder bộ chuyển đổi. Cần kiểm soát trễ và bất đối xứng (hai chiều cùng sợi hoặc khác sợi), vì ảnh hưởng PTP.'],
  ['Bảo vệ','1+1 OSNCP/SNCP, bảo vệ ring (OMS), hoặc phục hồi ở lớp IP/MPLS (TI-LFA, FRR). Thời gian chuyển mạch bảo vệ lớp quang/OTN cỡ dưới 50 ms.']],
 tb:()=>['Các container OTN thường gặp (G.709)',['Container','Tốc độ danh định','Chở (ví dụ)'],[['ODU0','1,244 Gb/s','GbE'],['ODU1','2,499 Gb/s','STM-16'],['ODU2','10,037 Gb/s','STM-64, 10G'],['ODU2e','10,399 Gb/s','10GbE LAN'],['ODU3','40,319 Gb/s','40G'],['ODU4','104,794 Gb/s','100GbE'],['ODUflex','n × 1,244 Gb/s','dịch vụ tốc độ bất kỳ'],['ODUCn','n × 100 Gb/s','200G, 400G, trên 100G']]]});

