const txVrf=()=>({nodes:[['rr',4,8,64,30,'RR','VPNv4'],['gb',4,78,64,30,'gNB','S1-U, N3'],['csr',100,78,64,30,'CSR','PE site'],['ag',196,78,64,30,'AGG','P'],['pe',292,78,64,30,'PE lõi','VRF MBH-U'],['up',292,8,64,30,'UPF','SGW-U'],['os',292,148,64,30,'OSS','VRF OAM'],['g2',4,148,64,30,'gNB 2','site khác']],
 links:[['gb','csr','VLAN 101'],['csr','ag','MPLS'],['ag','pe','MPLS'],['pe','up','N3'],['rr','csr','BGP'],['pe','os','OAM'],['g2','csr','VLAN 200']],
 steps:[[['gb','csr'],['gb-csr'],'gNB gửi gói GTP-U vào VLAN riêng','gNB đóng gói dữ liệu người dùng bằng GTP-U (UDP 2152), đánh DSCP (ví dụ EF cho thoại), gắn thẻ VLAN 101 và gửi tới cổng của CSR. Mỗi loại lưu lượng một VLAN: người dùng, điều khiển, X2/Xn, OAM.',[['Khung','Ethernet, 802.1Q VID 101, PCP 5'],['IP','nguồn gNB, đích UPF; DSCP 46'],['Tải','UDP 2152, GTP-U, TEID']]],
  [['rr','csr'],['rr-csr'],'Mặt phẳng điều khiển: BGP gán nhãn VPN','Các PE trao đổi route VPN-IPv4 qua Route Reflector (MP-BGP, RFC 4364). Mỗi route của VRF đi kèm RD, route target và nhãn VPN. CSR nhập các route có RT 64496:100 (của lõi) vào VRF MBH-U.',[['RD','64496:101'],['RT xuất','64496:101'],['RT nhập','64496:100 (lõi)']]],
  [['csr','ag'],['csr-ag'],'CSR đẩy hai nhãn','Cổng thuộc VRF MBH-U: CSR tra bảng VRF, thấy đích UPF qua PE lõi, đẩy nhãn VPN (trong) và nhãn vận chuyển (ngoài, LDP hoặc SR-MPLS). Trường TC của nhãn sao chép từ DSCP theo chính sách.',[['Nhãn vận chuyển','16005 (SR, ví dụ) hoặc nhãn LDP'],['Nhãn VPN','24011 (ví dụ)'],['TC (EXP)','5, ánh xạ từ DSCP 46']]],
  [['ag'],[],'Nút tập hợp (P) chỉ đổi nhãn ngoài','AGG không biết gì về VRF hay IP khách; nó đổi (swap) nhãn vận chuyển, cân bằng tải ECMP theo băm, giữ nguyên TC. Nút cuối cùng trước PE gỡ nhãn ngoài (PHP).'],
  [['ag','pe'],['ag-pe'],'PE lõi gỡ nhãn VPN','PE lõi nhận gói chỉ còn nhãn VPN, gỡ nhãn, tra VRF MBH-U tại đích UPF rồi chuyển ra cổng N3.',[['Hành động','pop VPN label, lookup trong VRF']]],
  [['pe','up'],['pe-up'],'Gói tới UPF','Gói GTP-U tới UPF/SGW-U. Chiều về đi đối xứng theo nhãn do CSR quảng bá cho dải địa chỉ gNB.'],
  [['g2','csr','os'],['g2-csr','pe-os'],'X2/Xn và OAM đi VRF riêng','Lưu lượng X2/Xn giữa hai site lân cận nằm trong VRF mesh (MBH-X) nên không phải đi về lõi; OAM nằm VRF riêng hub-spoke về hệ thống quản lý. Đồng bộ PTP không đi qua VRF vì PTP G.8275.1 chạy trên Ethernet từng chặng.']]});
