function txQosCalc(){
  const R=+S.txLk,dem=[Math.min(20,R*0.002),+S.txLv,+S.txLsg,+S.txLg,+S.txLb],srv=[0,0,0,0,0];
  srv[0]=dem[0];srv[1]=Math.min(dem[1],R*0.2,R-srv[0]);let rest=R-srv[0]-srv[1];
  const w=[0,0,20,50,30],act=[2,3,4];let left=act.slice();
  while(rest>1e-9&&left.length){const sw=left.reduce((s,i)=>s+w[i],0),done=[];let used=0;
    left.forEach(i=>{const share=rest*w[i]/sw,need=dem[i]-srv[i];if(need<=share){srv[i]+=need;used+=need;done.push(i);}});
    if(!done.length){left.forEach(i=>{srv[i]+=rest*w[i]/sw;});rest=0;break;}
    rest-=used;left=left.filter(i=>!done.includes(i));}
  return{dem,srv};}
const txQos=()=>{const c=txQosCalc(),sel=+S.txQs,nm=['Đồng bộ, điều khiển','Thoại, URLLC','Báo hiệu','Video, ưu tiên','Dữ liệu thường'],pc=c.dem.map((d,i)=>d>0?c.srv[i]/d*100:100);
  return{fig:prBars(nm.map((n,i)=>[n,pc[i],pc[i]<99.5?V_('warn'):V_('k1')]),100,' %','Tỷ lệ lưu lượng được phục vụ theo lớp'),hint:'Cột đầy (100 %) là lớp không mất gói; cột cam là lớp bị loại gói do nghẽn.',
   out:prKv([['Dịch vụ đang xem',esc(TXQC[sel][0])],['DSCP → TC (EXP) → PCP',TXQC[sel][1]+' → '+TXQC[sel][2]+' → '+TXQC[sel][3]],['Loại hàng đợi',TXQC[sel][4]],['5QI/QCI thường ánh xạ',TXQC[sel][5]],['Tổng tải / tốc độ',txP((c.dem.reduce((a,b)=>a+b,0))/(+S.txLk)*100,0)+' %']]),
   tt:'Ánh xạ lớp dịch vụ và kết quả phục vụ',tb:tbl(['Lớp','DSCP','TC (EXP)','PCP','Hàng đợi','Tải','Được phục vụ','Mất'],TXSIM.map((q,i)=>[q[0],q[1],q[2],q[3],q[4],txP(c.dem[i],0)+' Mb/s',txP(c.srv[i],0)+' Mb/s',pc[i]>=99.5?'0 %':txP(100-pc[i],1)+' %']),[0,1,2,3,3,4][sel]),
   info:`<p>Chuỗi ánh xạ từ lõi xuống truyền tải: 5QI/QCI → DSCP do UPF hoặc gNB đánh → trên mạng MPLS, TC (trước gọi EXP) sao chép từ DSCP ở router biên → trên Ethernet, PCP 802.1p. Bảng là gợi ý minh hoạ; nhà mạng tự quy hoạch theo RFC 4594 và chính sách riêng. Đồng bộ (PTP) và điều khiển mạng phải có lớp riêng ưu tiên cao nhất.</p><p>Mô phỏng: lớp đồng bộ và thoại đi ưu tiên tuyệt đối (thoại bị police ở 20 % tốc độ để không chiếm hết); phần còn lại chia theo trọng số 20 : 50 : 30 cho báo hiệu, video/ưu tiên và dữ liệu thường, lớp nào dùng ít hơn phần mình thì nhường cho lớp khác. Khi tổng tải vượt tốc độ, lớp dữ liệu thường mất gói trước. Mô hình bỏ qua bộ đệm và microburst.</p>`};};
const txHq=()=>({nodes:[['in',4,78,64,30,'Gói vào','DSCP, TC'],['cl',100,78,64,30,'Phân loại','lớp FC'],['q',196,8,64,30,'Hàng đợi','PQ, WFQ'],['sh',196,78,64,30,'Shaper','VLAN, site'],['sb',196,148,64,30,'Nhà mạng B','sub-if'],['pt',292,78,64,30,'Cổng','shaper'],['ex',292,148,64,30,'Dư băng','chia sẻ']],
 links:[['in','cl',''],['cl','q','FC'],['q','sh','cấp 3'],['sh','pt','cấp 2'],['cl','sb','FC'],['sb','pt','cấp 2'],['pt','ex','dư']],
 steps:[[['in','cl'],['in-cl'],'Phân loại','Gói vào được xếp vào lớp dịch vụ (forwarding class) theo DSCP, TC hoặc PCP của gói, hoặc theo ACL. Đây là chỗ ánh xạ 5QI → hàng đợi.'],
  [['cl','q'],['cl-q'],'Police và hàng đợi lớp (cấp 3)','Lớp ưu tiên (đồng bộ, thoại, URLLC) vào hàng đợi ưu tiên tuyệt đối, có police để không chiếm hết băng thông; các lớp còn lại vào hàng đợi chia theo trọng số (WFQ/DWRR) hoặc tốc độ tối thiểu bảo đảm (CIR).'],
  [['q','sh'],['q-sh'],'Shaper cấp 2: theo VLAN, site hoặc lát cắt','Mỗi VLAN, sub-interface hoặc lát cắt có shaper riêng đặt tốc độ cam kết (CIR) và tối đa (PIR). Ví dụ trong chia sẻ RAN (MORAN, MOCN), mỗi nhà mạng một sub-interface với băng thông thuê riêng; hoặc mỗi site một VLAN để không site nào lấn site khác.'],
  [['cl','sb','pt'],['cl-sb','sb-pt'],'Nhà mạng hoặc lát cắt thứ hai','Cùng cấu trúc nhưng độc lập: hàng đợi lớp của nhà mạng B nằm dưới shaper của B, nên B nghẽn không làm A mất gói.'],
  [['sh','pt'],['sh-pt'],'Shaper cấp 1: cổng hoặc đường thuê','Tổng các shaper cấp 2 bị giới hạn bởi tốc độ cổng, hoặc tốc độ đường thuê nếu nhỏ hơn cổng (ví dụ cổng 10G nhưng chỉ thuê 3 Gb/s). Shaper phải đặt thấp hơn tốc độ thật để hàng đợi nằm ở router của mình thay vì ở thiết bị thuê.'],
  [['pt','ex'],['pt-ex'],'Chia sẻ băng thông dư','Khi một VLAN không dùng hết CIR, phần dư có thể chia cho VLAN khác theo trọng số (excess bandwidth sharing) cho tới PIR.']]});
