const txSlice=()=>{const tot=S.txFp*S.txFg,dm=[S.txS1,S.txS2,S.txS3,S.txS4],nm=['eMBB','URLLC','mMTC, OAM','Nhà mạng thuê'],col=[V_('up'),V_('warn'),V_('k1'),V_('k4')],sl=dm.map(d=>Math.ceil(d/5)),used=sl.reduce((a,b)=>a+b,0),over=used>tot;
  let k=0,s='';const cw=17,ch=18,W=372,per=20,rows=Math.ceil(tot/per),H=rows*(ch+3)+8;
  for(let r=0;r<rows;r++)for(let c=0;c<per&&k<tot;c++,k++){let ow=-1,acc=0;for(let q=0;q<4;q++){acc+=sl[q];if(k<acc){ow=q;break;}}s+=`<rect x="${4+c*cw}" y="${4+r*(ch+3)}" width="${cw-2}" height="${ch}" rx="2" style="fill:${ow>=0?col[ow]:V_('panel2')};stroke:${V_('line')};stroke-width:.8"/>`+tx(4+c*cw+(cw-2)/2,4+r*(ch+3)+12,k+1,{fs:6,c:ow>=0?V_('panel'):V_('muted')});}
  return{fig:svgw(W,H,s,'Lịch khe FlexE'),hint:'Mỗi ô là một khe 5 Gb/s của lịch (calendar) FlexE; màu theo lát cắt, ô xám là khe trống.',
   out:prKv([['Tổng khe',tot+' ('+tot*5+' Gb/s)'],['Khe đã cấp',used+(over?' <b>(vượt '+(used-tot)+' khe)</b>':'')],['Khe trống',over?'0':String(tot-used)]].concat(dm.map((d,i)=>[nm[i],sl[i]+' khe = '+sl[i]*5+' Gb/s cho nhu cầu '+d+' Gb/s (dư '+(sl[i]*5-d)+')']))),
   info:`<p>FlexE (OIF Flexible Ethernet) chia lịch của một nhóm cổng thành các khe 5 Gb/s (20 khe cho 100G, 40 cho 200G, 80 cho 400G) và gán mỗi khe cho một client. Mỗi lát cắt thành một kênh lớp 1 cứng, không chia sẻ hàng đợi với lát cắt khác, nên trễ ổn định và cách ly tuyệt đối; đổi lại không thống kê ghép kênh được, phần khe không dùng bị lãng phí và băng thông cấp theo bội của 5 Gb/s. Dùng cho lát cắt URLLC, thuê kênh cho nhà mạng khác hoặc fronthaul cần cách ly. Có thể ghép nhiều cổng vào một nhóm (bonding) để có kênh lớn hơn một cổng và chuyển mạch con (sub-rate) ở lớp FlexE.</p>`};};
const txSrte=()=>({nodes:[['rr',4,8,64,30,'RR','VPNv4'],['pc',196,8,64,30,'PCE','tính đường'],['pe1',4,78,64,30,'PE site','head-end'],['p1',100,78,64,30,'P1','16002'],['p3',196,78,64,30,'P3','16004'],['pe2',292,78,64,30,'PE lõi','16005'],['p2',100,148,64,30,'P2','16003'],['p4',196,148,64,30,'P4','16006']],
 links:[['rr','pe1','BGP'],['pc','pe1','PCEP'],['pe1','p1',''],['p1','p3',''],['p3','pe2',''],['pe1','p2',''],['p2','p4',''],['p4','pe2','']],
 steps:[[['rr','pe1'],['rr-pe1'],'Route VPN đến kèm màu','PE lõi quảng bá route VPN của UPF kèm community màu (Color Extended Community, ví dụ 100 = trễ thấp) và nexthop 16005. Màu là cách khách hàng, dịch vụ hoặc lát cắt chọn kiểu đường đi.',[['Color','100 (ví dụ: trễ thấp)'],['Endpoint','PE lõi, SID 16005']]],
  [['pe1'],[],'On-demand nexthop (ODN) tạo chính sách','Head-end thấy route có màu 100 và nexthop 16005, tự tạo SR Policy (color 100, endpoint PE lõi) theo mẫu cấu hình sẵn, không cần cấu hình từng tuyến thủ công.'],
  [['pc','pe1'],['pc-pe1'],'Tính đường theo ràng buộc','Head-end tự tính (hoặc hỏi PCE bằng PCEP) đường thoả ràng buộc: cực tiểu trễ, tránh liên kết nhất định, hay dùng Flex-Algo (thuật toán IGP riêng, ví dụ 128 theo chỉ số trễ).'],
  [['pe1','p2','p4','pe2'],['pe1-p2','p2-p4','p4-pe2'],'Danh sách đoạn (segment list)','Đường được biểu diễn thành danh sách SID; head-end đẩy chuỗi nhãn tương ứng. Core chỉ cần đọc nhãn trên cùng, không giữ trạng thái từng tuyến (khác RSVP-TE).',[['SRGB','16000 đến 23999 (mặc định thường gặp)'],['Danh sách','[16003, 16006, 16005] hoặc dùng Adjacency-SID'],['Nhãn ở đầu','đẩy các nhãn tương ứng, thêm nhãn VPN dưới cùng']]],
  [['p2','p4'],['p2-p4'],'Chuyển tiếp và bảo vệ TI-LFA','Mỗi nút ra quyết định theo nhãn trên cùng. TI-LFA tính trước đường dự phòng cho từng liên kết/nút, chuyển sang trong cỡ 50 ms khi mất liên kết, cũng bằng nhãn SR.'],
  [['pe2'],[],'Tách lát cắt bằng màu','Mỗi màu (và Flex-Algo) tương ứng một lát cắt truyền tải có đường đi, ràng buộc riêng; kết hợp VRF/nhãn VPN theo dịch vụ và FlexE cho cách ly lớp 1.']]});
