const CCBASE=[['192.168.10.0/24','192.168.10.0/24'],['10.10.0.0/22','10.10.0.0/22'],['172.16.0.0/20','172.16.0.0/20'],['192.0.2.0/24','192.0.2.0/24']];
const ccBase=s=>{const [a,b]=s.split('/');return{ip:ccIp(a),p:+b};};
