  const blocks=P.sorted.map((r,j)=>({off:r.off,size:r.size,label:r.n.length>6?r.h:r.n,col:cols[j%cols.length],ok:r.fit})).filter((b,j)=>P.sorted[j].fit&&j<(c===0?0:Math.min(c,n)));
