ccReg('vlan',{n:'VLAN: khung đi qua hai switch',spec:'IEEE 802.1Q; IEEE 802.1D (học MAC); Cisco IOS: vlan, switchport',dom:2,
 vars:[['main','Khung, bảng MAC và flood'],['cli','Kịch bản CLI: tạo VLAN, gán cổng, trunk']],
 par:v=>v==='main'?[{l:'Máy gửi',o:[['A','PC-A (SW1, VLAN 10)'],['B','PC-B (SW1, VLAN 20)'],['C','PC-C (SW1, VLAN 10)'],['D','PC-D (SW2, VLAN 10)'],['E','PC-E (SW2, VLAN 20)']],def:'A'},{l:'Máy nhận',o:[['A','PC-A'],['B','PC-B'],['C','PC-C'],['D','PC-D'],['E','PC-E']],def:'D'},{l:'Bảng MAC lúc bắt đầu',o:[['empty','Trống (khung đầu tiên)'],['known','Đã học đủ']],def:'empty'},{l:'Sự cố thêm vào',o:[['none','Không có'],['wrong','Cổng máy nhận gán nhầm VLAN'],['allowed','Trunk chỉ cho phép VLAN 20'],['novlan','SW2 chưa tạo VLAN 10']],def:'none'}]:[],
 steps:v=>v==='main'?ccVlanRun().ev.length:CCCLI_VLAN.length,
 sim:i=>S.ccV==='main'?ccVlanMain(i):ccCli(CCCLI_VLAN,i,'Tạo VLAN, gán cổng, cấu hình trunk'),
 idx:'VLAN access trunk 802.1Q bảng MAC flood unknown unicast native VLAN allowed vlan switchport mode access show vlan brief'});
/* ---------- Trunk: thẻ 802.1Q, Router-on-a-stick, DTP ---------- */
function ccTagFig(vid,pcp,dei,hl){const bits=(0x8100<<16|((pcp<<13)|(dei<<12)|vid))>>>0,cw=10.4,x0=8,y=58;let s='';
  const grp=[[0,16,'TPID 0x8100',V_('k2'),1],[16,3,'PCP',V_('k4'),2],[19,1,'D',V_('cp'),3],[20,12,'VID '+vid,V_('k1'),4]];
  grp.forEach(g=>{const on=hl===0||hl===g[4];for(let b=g[0];b<g[0]+g[1];b++){const x=x0+b*cw+(b>=16?6:0)+(b>=19?0:0);s+=`<rect x="${x.toFixed(1)}" y="${y}" width="${cw}" height="20" style="fill:color-mix(in srgb,${g[3]} ${on?36:14}%,${V_('panel')});stroke:${on?g[3]:V_('line')};stroke-width:1"/>`+tx((x+cw/2).toFixed(1),y+14,(bits>>>(31-b))&1,{fs:9,c:V_('ink')});}
    const xa=x0+g[0]*cw+(g[0]>=16?6:0),xb=x0+(g[0]+g[1])*cw+(g[0]>=16?6:0);s+=li([[xa,y+25],[xb,y+25]],{c:g[3],w:2.2})+tx((xa+xb)/2,y+37,g[2],{fs:g[1]<3?7:8.2,b:1,c:V_('ink')});});
  const fr=[['DA',6,V_('muted'),44],['SA',6,V_('muted'),44],['802.1Q',4,V_('k2'),56],['Type',2,V_('muted'),34],['Payload 46–1500',0,V_('up'),120],['FCS',4,V_('k3'),38]];let x=8;
  fr.forEach((f,j)=>{const on=hl===0||(hl===9&&j===2)||(hl===8&&j===5);s+=`<rect x="${x}" y="8" width="${f[3]}" height="26" rx="3" style="fill:color-mix(in srgb,${f[2]} ${on?34:14}%,${V_('panel')});stroke:${on?V_('warn'):f[2]};stroke-width:${on?2.2:1}"/>`+tx(x+f[3]/2,19,f[0],{fs:j===4?7.2:7.8,b:1,c:V_('ink')})+(f[1]?tx(x+f[3]/2,29,f[1]+' B',{fs:7,c:V_('muted')}):tx(x+f[3]/2,29,'',{fs:7}));x+=f[3];});
  s+=li([[8+44*2+0,34],[8+88,40],[x0,y-4]],{c:V_('k2'),w:1,d:'3 3'}) ;
  return svgw(372,112,s,'Thẻ 802.1Q');}
function ccTrunkTag(i){const vid=+S.ccP1,pcp=+S.ccP2,dei=+S.ccP3,nat=+S.ccP4,tci=(pcp<<13)|(dei<<12)|vid,hex=n=>n.toString(16).toUpperCase().padStart(4,'0'),untag=vid===nat;
  const cls=vid===1?'VLAN mặc định, không xoá được':vid<=1001?'Dải thường (2 đến 1001)':vid<=1005?'Dành riêng cho FDDI, Token Ring cũ':'Dải mở rộng (1006 đến 4094), cần VTPv3 hoặc chế độ transparent';
  const T=[
   ['Khung gốc từ máy tính',`Máy tính gửi khung Ethernet thường (DA, SA, EtherType, tải trọng, FCS), tối đa 1518 byte. Máy không biết VLAN. Cổng access của switch gán khung vào VLAN ${vid} theo cấu hình cổng.`],
   [untag?'Khung thuộc native VLAN: gửi không thẻ':'Thêm thẻ 802.1Q vào khung',untag?`VLAN ${vid} trùng native VLAN (${nat}) của trunk nên khung được gửi KHÔNG thẻ. Đầu bên kia coi mọi khung không thẻ là thuộc native VLAN của nó, nên nếu hai đầu đặt native VLAN khác nhau thì khung nhảy sang VLAN khác (VLAN hopping/ lỗi cấu hình, CDP báo native VLAN mismatch).`:`Switch chèn 4 byte thẻ ngay sau MAC nguồn: TPID 0x8100 (16 bit) báo "khung có thẻ", TCI 16 bit gồm PCP 3 bit (ưu tiên CoS 0 đến 7), DEI 1 bit (có thể loại khi tắc nghẽn), VID 12 bit (${vid}). TCI hiện tại = 0x${hex(tci)}. Lớp cũ ISL của Cisco bọc 26 byte tiêu đề + 4 byte FCS, nay hầu như không dùng.`],
   ['Tính lại FCS và kích thước khung',`Vì khung thay đổi, FCS phải tính lại. Khung có thẻ dài thêm 4 byte: tối đa 1522 byte (802.3ac), tối thiểu vẫn 64 byte. Thiết bị trên đường truyền phải chấp nhận khung 1522 byte; nếu cổng chỉ cho 1518, khung bị coi là quá khổ (giant) khi đi qua. Nếu MTU lớp 3 vẫn 1500 thì không cần chỉnh.`],
   ['Switch đầu kia bỏ thẻ',untag?`Switch bên kia nhận khung không thẻ trên trunk, gán vào native VLAN của nó (${nat}), rồi chuyển tiếp. Không có gì để bỏ.`:`Switch bên kia đọc VID ${vid}, chỉ chuyển tiếp trong VLAN ${vid} (nếu VLAN này được phép và tồn tại), bỏ thẻ khi ra cổng access, tính lại FCS. Máy đích nhận khung Ethernet thường như ban đầu.`],
   ['Native VLAN: nguyên tắc cấu hình',`Native VLAN mặc định là 1. Khuyến nghị bảo mật: đổi sang một VLAN không dùng (ví dụ 99), và cấu hình giống hệt hai đầu. Lệnh: switchport trunk native vlan ${nat}. CDP và STP (PVST+) cảnh báo khi hai đầu lệch. Không nên dùng VLAN 1 cho người dùng hay quản trị.`]];
  const c=clamp(i,0,4),hl=[0,c===1?4:0,8,9,0][c];
  return{fig:ccTagFig(vid,pcp,dei,[0,untag?0:9,8,9,0][c]),hint:'Kéo VID, PCP, DEI hoặc đổi native VLAN: 32 bit của thẻ và các giá trị bên dưới đổi theo.',
    out:prKv([['TPID','0x8100'],['TCI (PCP|DEI|VID)','0x'+hex(tci)+'  =  '+tci.toString(2).padStart(16,'0')],['PCP (CoS)',pcp+(pcp===5?' (thường dùng cho thoại)':'')],['DEI',dei],['VID',vid+' · '+cls],['Native VLAN',nat],['Trên trunk',untag?'Không thẻ (native VLAN)':'Có thẻ 802.1Q']]),
    info:ccInfo(T[c][0],T[c][1],T.map((q,j)=>`${q[0]}`),c,c===1?[['TPID','0x8100'],['PCP / DEI / VID',`${pcp} / ${dei} / ${vid}`],['Thêm vào khung','4 byte']]:null,['Hai đầu trunk cùng native VLAN','Chỉ cho phép đúng các VLAN cần dùng: switchport trunk allowed vlan','Kiểm tra: show interfaces trunk']),
    tt:'Khung Ethernet có thẻ và không thẻ',tb:tbl(['Loại khung','Byte tối thiểu','Byte tối đa','Ghi chú'],[['Ethernet II thường',64,1518,'Không thẻ'],['Có thẻ 802.1Q',64,1522,'Thêm 4 byte thẻ'],['Q-in-Q (802.1ad)',64,1526,'Hai thẻ, dùng ở nhà mạng']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
function ccIvrBuild(){const meth=S.ccP1,f=S.ccP2,roas=meth==='roas';let st;
  if(roas){const cols=['PC-A','SW1','R1','PC-B'];
    st=[{f:0,t:2,s:'ARP Request: ai là 192.168.10.1 ?',m:'ARP Request (gateway)',p:'VLAN 10',k:'nas',d:'PC-A (192.168.10.10/24, VLAN 10) muốn ping 192.168.20.20. Địa chỉ đích khác mạng nên PC-A gửi tới default gateway 192.168.10.1. Chưa biết MAC của gateway nên phát ARP broadcast trong VLAN 10. Switch gắn thẻ VLAN 10 rồi đẩy lên trunk tới R1.',fl:[['MAC đích','ffff.ffff.ffff'],['Thẻ trên trunk','802.1Q VID 10'],['Target IP','192.168.10.1']]},
      {f:2,t:0,s:'ARP Reply: 192.168.10.1 ở MAC của R1',m:'ARP Reply',p:'Gi0/0.10',k:'nas',d:'Sub-interface Gi0/0.10 của R1 (encapsulation dot1Q 10, IP 192.168.10.1) trả lời unicast bằng MAC của cổng vật lý Gi0/0. Mọi sub-interface của một cổng dùng chung MAC.',fl:[['MAC nguồn','MAC Gi0/0 của R1'],['Thẻ','VID 10']]},
      {f:0,t:2,s:'ICMP Echo 192.168.10.10 → 192.168.20.20',m:'Echo Request tới R1',p:'VLAN 10',k:'rt',d:'PC-A gửi gói IP: IP đích 192.168.20.20 (PC-B) nhưng MAC đích là MAC của R1. Switch thêm thẻ VLAN 10, trunk chuyển sang R1.',fl:[['IP nguồn → đích','192.168.10.10 → 192.168.20.20'],['MAC đích','MAC R1 Gi0/0'],['Thẻ','VID 10']]},
      {f:2,t:2,s:'Gi0/0.10 nhận, tra route 192.168.20.0/24 qua Gi0/0.20',m:'R1 định tuyến',p:'L3',k:'rt',d:'R1 nhận khung có thẻ VID 10 trên sub-interface .10, bỏ khung L2, tra bảng định tuyến: 192.168.20.0/24 là mạng kết nối trực tiếp qua Gi0/0.20. Giảm TTL (128 → 127 với Windows).',fl:[['Route','C 192.168.20.0/24 is directly connected, Gi0/0.20'],['TTL','giảm 1']]},
      {f:2,t:3,s:'ARP Request 192.168.20.20 (thẻ VLAN 20)',m:'ARP Request (đích)',p:'VLAN 20',k:'nas',d:'R1 chưa biết MAC của PC-B nên phát ARP trên sub-interface .20 (thẻ VID 20). Switch chỉ đưa ARP tới các cổng VLAN 20; PC-B trả lời.',fl:[['Thẻ','802.1Q VID 20']]}];
    if(f==='encap')st.push({f:2,t:2,s:'Sai: encapsulation dot1Q 200 (gõ nhầm)',m:'Sub-interface .20 gắn sai VLAN',p:'lỗi',k:'rt',bad:1,d:'Trên Gi0/0.20 đã gõ nhầm encapsulation dot1Q 200 thay vì 20. R1 gắn thẻ VID 200 vào ARP/khung: switch không có VLAN 200 trên trunk (allowed 10,20) nên bỏ khung, PC-B không bao giờ nhận. Ping từ PC-A báo Request timed out. Kiểm tra show running-config interface g0/0.20 và show vlans.',chk:['show ip interface brief: sub-interface up/up nhưng không thông','Đối chiếu VID encapsulation với VLAN của cổng access PC-B']});
    else if(f==='gw')st=[{f:0,t:1,s:'ARP Request: 192.168.10.254 ?',m:'ARP Request (gateway sai)',p:'VLAN 10',k:'nas',bad:1,d:'PC-A được cấu hình default gateway 192.168.10.254, nhưng sub-interface của R1 là 192.168.10.1. Không ai trả lời ARP. PC-A không gửi được gói ra ngoài mạng, ping báo Destination host unreachable (từ chính PC-A) hoặc timeout. Sửa gateway trên PC hay trên router cho khớp.',chk:['ipconfig / show ip interface brief','Gateway phải cùng mạng với IP của PC và trùng IP sub-interface']}];
    else if(f==='trunk'){st=st.slice(0,4);st.push({f:2,t:1,s:'Khung VID 20 bị trunk loại',m:'Trunk không cho VLAN 20',p:'lỗi',k:'rt',bad:1,d:'Trunk Gi0/1 giữa SW1 và R1 chỉ cho phép VLAN 10 (switchport trunk allowed vlan 10). Khung VID 20 từ R1 bị loại ở SW1. Hiện tượng: PC cùng VLAN ping nhau được, ping qua VLAN thất bại. Sửa bằng switchport trunk allowed vlan add 20.',chk:['show interfaces trunk','Cột Vlans allowed and active in management domain']});}
    else{st.push({f:3,t:2,s:'ARP Reply từ PC-B',m:'ARP Reply',p:'VLAN 20',k:'nas',d:'PC-B (192.168.20.20) trả lời unicast cho R1, kèm MAC của PC-B.'},
      {f:2,t:3,s:'Echo Request 192.168.10.10 → 192.168.20.20 (VLAN 20)',m:'Khung mới ra Gi0/0.20',p:'VLAN 20',k:'rt',d:'R1 đóng khung L2 mới: MAC nguồn là MAC Gi0/0 của R1, MAC đích là MAC PC-B, thẻ VID 20. IP nguồn và đích giữ nguyên, chỉ TTL giảm. Khung quay lại đúng cổng vật lý Gi0/0 mà nó vừa vào (đường "hairpin"), nên băng thông một cổng trunk bị dùng hai chiều cho mỗi gói.',fl:[['MAC nguồn','MAC R1 Gi0/0'],['MAC đích','MAC PC-B'],['Thẻ','VID 20'],['TTL','127']]},
      {f:3,t:3,s:'PC-B nhận (switch bỏ thẻ)',m:'Tới PC-B',p:'cổng access VLAN 20',k:'med',d:'SW1 bỏ thẻ và đẩy ra cổng access VLAN 20 nối PC-B. Echo Reply đi theo chiều ngược lại.'});}
    return{cols,st};}
  const cols=['PC-A','Switch L3','PC-B'];
  st=[{f:0,t:1,s:'ARP Request: ai là 192.168.10.1 ?',m:'ARP Request (SVI 10)',p:'VLAN 10',k:'nas',d:'PC-A hỏi MAC của gateway 192.168.10.1, là địa chỉ của SVI (interface vlan 10) của switch lớp 3. Gói chỉ cần ở trong switch, không đi qua trunk.'},
   {f:1,t:0,s:'ARP Reply từ SVI 10',m:'ARP Reply',p:'SVI',k:'nas',d:'SVI trả lời bằng MAC của VLAN 10 (thường là MAC của switch).'},
   {f:0,t:1,s:'Echo Request tới SVI (MAC đích = MAC SVI)',m:'Echo Request',p:'VLAN 10',k:'rt',d:'Khung vào switch qua cổng access VLAN 10, đích MAC là SVI, đích IP là 192.168.20.20.'}];
  if(f==='gw')st=[st[0],{f:1,t:1,s:'Gateway sai: không ai trả lời ARP',m:'Gateway cấu hình sai',p:'lỗi',k:'rt',bad:1,d:'PC-A đặt gateway sai nên ARP không có trả lời; ping qua mạng khác thất bại dù SVI đúng.'}];
  else if(f==='encap'||f==='trunk'){st.push({f:1,t:1,s:'ip routing chưa bật: SVI không chuyển tiếp',m:'Thiếu ip routing',p:'lỗi',k:'rt',bad:1,d:'Switch lớp 3 mặc định có thể chưa bật định tuyến. Thiếu lệnh ip routing nên switch có SVI cho từng VLAN nhưng không chuyển gói giữa các VLAN. Sau khi gõ ip routing, route kết nối trực tiếp của các SVI vào bảng định tuyến và ping thông.',chk:['show ip route phải có hai mạng C','show ip interface brief: interface vlan 10, 20 phải up/up (cần ít nhất một cổng up trong VLAN)']});}
  else st.push({f:1,t:1,s:'Định tuyến nội bộ: SVI 10 → SVI 20',m:'Switch định tuyến',p:'ASIC',k:'rt',d:'Switch tra bảng route (C 192.168.20.0/24 is directly connected, Vlan20) và chuyển tiếp bằng phần cứng (CEF/ASIC) ở tốc độ đường truyền. Không có đường hairpin qua trunk nên nhanh hơn router-on-a-stick.'},{f:1,t:2,s:'Khung mới VLAN 20 ra cổng PC-B',m:'Khung mới',p:'VLAN 20',k:'rt',d:'Switch ARP cho 192.168.20.20 trong VLAN 20, đóng khung mới (MAC nguồn là SVI 20, MAC đích là PC-B, TTL giảm 1) và gửi ra cổng access.'},{f:2,t:2,s:'PC-B nhận',m:'Tới PC-B',p:'VLAN 20',k:'med',d:'PC-B nhận gói. Echo Reply đi ngược lại tương tự.'});
  return{cols,st};}
function ccTrunkIvr(i){const B=ccIvrBuild(),c=clamp(i,0,B.st.length-1),s=B.st[c],roas=S.ccP1==='roas',bad=B.st.some(x=>x.bad);
  return{fig:gxLadder(B.cols,B.st,c,'tx'),hint:'Chạm vào một dòng để xem chi tiết. Đổi kiểu thiết bị hoặc chọn một sự cố ở khung bên cạnh.',
    out:prKv([['Phương pháp',roas?'Router-on-a-stick (một trunk, nhiều sub-interface)':'Switch lớp 3 với SVI'],['Cặp đang ping','PC-A (VLAN 10) → PC-B (VLAN 20)'],['Bước',`${c+1} trên ${B.st.length}`],['Kết quả cuối',bad?'Ping thất bại':'Ping thành công']]),
    info:ccInfo(s.m,s.d,B.st.map((q,j)=>`${q.m}`),c,s.fl,s.chk)+'<h3>Cấu hình tương ứng</h3>'+ccPre(roas?'interface g0/0\n no shutdown\ninterface g0/0.10\n encapsulation dot1Q 10\n ip address 192.168.10.1 255.255.255.0\ninterface g0/0.20\n encapsulation dot1Q 20\n ip address 192.168.20.1 255.255.255.0':'ip routing\ninterface vlan 10\n ip address 192.168.10.1 255.255.255.0\n no shutdown\ninterface vlan 20\n ip address 192.168.20.1 255.255.255.0\n no shutdown'),
    tt:'So sánh hai cách',tb:tbl(['Tiêu chí','Router-on-a-stick','SVI trên switch L3'],[['Thiết bị','Router + switch L2','Switch lớp 3'],['Đường đi gói giữa VLAN','Vào và ra cùng cổng trunk (hairpin)','Trong ASIC của switch'],['Băng thông','Giới hạn bởi một cổng trunk','Tốc độ chuyển mạch của switch'],['Cấu hình','Sub-interface + encapsulation dot1Q','interface vlan + ip routing'],['Dùng khi','Mạng nhỏ, lab, chi nhánh','Mạng campus']]),cap:`${s.m}: ${first(s.d)}`};}
const CCDM=['access','dynamic auto','dynamic desirable','trunk','trunk nonegotiate'];
function ccDtp(a,b){const na=a==='nonegotiate',nb=b==='nonegotiate',mt=m=>m==='trunk'||m==='nonegotiate',dyn=m=>m==='auto'||m==='desirable';
  if(a==='access'&&b==='access')return['access','Hai đầu cùng access: cổng thuộc VLAN truy cập, không trunk.'];
  if(a==='access'||b==='access'){if(mt(a)||mt(b))return['Lỗi (trunk/access lệch)','Một đầu trunk một đầu access: không thể thông; thường sinh cảnh báo native VLAN, khung bị loại hoặc nhảy VLAN. Đây là cấu hình sai điển hình.'];return['access','Phía kia là dynamic nhưng đầu access không gửi DTP: dynamic trở thành access.'];}
  if(mt(a)&&mt(b))return['trunk','Cả hai đầu ép trunk: trunk lên bình thường (nonegotiate chỉ tắt DTP).'];
  if(mt(a)||mt(b)){const o=mt(a)?b:a,t=mt(a)?a:b;if(t==='nonegotiate')return['Lỗi (trunk/access lệch)','Đầu nonegotiate không gửi DTP nên đầu dynamic không biết phải trunk: một đầu trunk, một đầu access, lệch.'];return['trunk',`Đầu trunk gửi DTP mời; đầu ${o} chấp nhận nên cả hai thành trunk.`];}
  if(a==='auto'&&b==='auto')return['access','Auto chỉ chờ được mời, không ai mời nên cả hai ở access.'];
  return['trunk','Có ít nhất một đầu desirable chủ động mời, đầu kia đồng ý (desirable hoặc auto): trunk.'];}
function ccTrunkDtp(i){const A=S.ccP1,B=S.ccP2,m=x=>x==='dynamic auto'?'auto':x==='dynamic desirable'?'desirable':x==='trunk nonegotiate'?'nonegotiate':x,R=ccDtp(m(A),m(B)),c=clamp(i,0,2);
  const send=x=>x==='access'||x==='trunk nonegotiate'?'không gửi DTP':x==='trunk'?'gửi DTP (báo: tôi là trunk)':x==='dynamic desirable'?'chủ động gửi DTP (mời làm trunk)':'chỉ trả lời khi nhận được DTP';
  const T=[[`Phía A: ${A}`,`Chế độ ${A} ${send(A)}. DTP (Dynamic Trunking Protocol) là giao thức của Cisco chạy trên Ethernet (dùng địa chỉ multicast của Cisco, qua LLC/SNAP).`],[`Phía B: ${B}`,`Chế độ ${B} ${send(B)}.`],['Kết luận',R[1]+' Khuyến nghị: tắt DTP, cấu hình cứng cả hai đầu bằng switchport mode trunk và switchport nonegotiate, cổng người dùng switchport mode access.']];
  const rows=[];CCDM.forEach(x=>CCDM.map(m).forEach((y,yi)=>{}));
  const tb=CCDM.map(x=>[x].concat(CCDM.map(y=>ccDtp(m(x),m(y))[0].replace('Lỗi (trunk/access lệch)','lệch'))));
  return{fig:`<div style="font-size:15px;text-align:center;padding:14px 4px"><div style="display:flex;justify-content:space-around;align-items:center;gap:6px;flex-wrap:wrap"><div class="cc-sw">SW-A<br><small>${A}</small></div><div style="flex:1;min-width:90px;border-top:4px solid ${R[0]==='trunk'?'var(--k1)':R[0]==='access'?'var(--up)':'var(--warn)'};padding-top:4px;font-size:12.5px;font-weight:700">${R[0]}</div><div class="cc-sw">SW-B<br><small>${B}</small></div></div></div>`,
    hint:'Chọn chế độ ở hai đầu để xem DTP đàm phán ra trunk hay access. Bảng bên dưới là toàn bộ 25 cặp.',
    out:prKv([['Đầu A',A],['Đầu B',B],['Kết quả',R[0]]]),info:ccInfo(T[c][0],T[c][1],T.map((q,j)=>`${q[0]}`),c)+gxUl(['dynamic auto: chờ được mời','dynamic desirable: chủ động mời','trunk: luôn trunk và vẫn gửi DTP','switchport nonegotiate: ngừng gửi DTP (chỉ dùng với trunk hoặc access)']),
    tt:'Kết quả đàm phán theo cặp (hàng là đầu A, cột là đầu B)',tb:tbl(['A \\ B'].concat(CCDM),tb),cap:`${A} với ${B}: ${R[0]}`};}
