const CCLOGS=[['Emergency',0,'%SYS-0-... (ví dụ minh họa) hệ thống không dùng được'],['Alert',1,'%SYS-1-... (ví dụ minh họa) cần xử lý ngay'],['Critical',2,'%SYS-2-MALLOCFAIL: Memory allocation of 65536 bytes failed'],['Error',3,'%LINK-3-UPDOWN: Interface GigabitEthernet0/1, changed state to down'],['Warning',4,'%PM-4-ERR_DISABLE: psecure-violation error detected on Fa0/1, putting Fa0/1 in err-disable state'],['Notice',5,'%OSPF-5-ADJCHG: Process 1, Nbr 2.2.2.2 on GigabitEthernet0/0 from FULL to DOWN, Neighbor Down: Dead timer expired'],['Notice',5,'%SYS-5-CONFIG_I: Configured from console by admin on vty0 (192.168.10.25)'],['Informational',6,'%SEC-6-IPACCESSLOGP: list ACL-IN denied tcp 192.168.10.25(40000) -> 10.0.0.5(23), 1 packet'],['Debugging',7,'ICMP: echo reply rcvd, src 10.0.0.5, dst 192.168.10.1 (debug ip icmp)']];
