function ccMgmtSyslog(i){const dest=S.ccP1,lv=+S.ccP2,c=clamp(i,0,CCLOGS.length-1),fac=23;
  const rows=CCLOGS.map((m,j)=>{const pass=m[1]<=lv;return`<tr${j===c?' class="hlr"':''}><td>${j+1}</td><td>${m[0]} (${m[1]})</td><td style="font:11px var(--mono);overflow-wrap:anywhere">${esc(m[2])}</td><td>${pass?'<b style="color:var(--k1)">Gửi</b>':'<span style="color:var(--muted)">Bỏ</span>'}</td></tr>`;}).join('');
  const m=CCLOGS[c],pass=m[1]<=lv,pri=fac*8+m[1],dn={trap:'máy chủ syslog (logging host)',console:'console',buffered:'bộ nhớ đệm (logging buffered)',monitor:'phiên Telnet/SSH (terminal monitor)'}[dest];
  const dd=dest==='trap'?'logging trap':'logging '+dest;
  const T=[`Thông điệp ${c+1}: ${m[0]}`,`Mức nghiêm trọng ${m[1]} (${CCSEV[m[1]]}). Cấu hình ${dd} ${CCSEV[lv].toLowerCase()} (mức ${lv}) nghĩa là gửi các thông điệp từ mức 0 đến ${lv} (số nhỏ hơn hoặc bằng ${lv}) tới ${dn}. Thông điệp này mức ${m[1]} ${pass?'≤':'>'} ${lv} nên ${pass?'ĐƯỢC gửi':'BỊ bỏ'}.`+(dest==='trap'?` Gửi tới máy chủ qua UDP 514; PRI = facility × 8 + severity = ${fac} × 8 + ${m[1]} = ${pri} (facility local7 mặc định của IOS).`:'')];
  return{fig:`<div class="scroll"><table>${'<tr><th>#</th><th>Mức</th><th>Thông điệp (ví dụ)</th><th>Kết quả</th></tr>'+rows}</table></div>`,hint:'Mức càng nhỏ càng nghiêm trọng; đặt mức N nghĩa là nhận các mức từ 0 đến N. Ghi nhớ: Emergency, Alert, Critical, Error, Warning, Notice, Informational, Debugging.',
    out:prKv([['Đích nhật ký',dn],['Mức đã đặt',`${lv} (${CCSEV[lv]})`],['Số thông điệp được gửi',CCLOGS.filter(x=>x[1]<=lv).length+' trên '+CCLOGS.length],['PRI (facility 23 × 8 + mức)',pri]]),
    info:ccInfo(T[0],T[1],CCLOGS.map((q,j)=>`<b>${q[0]} (${q[1]})</b>`),c)+'<h3>Định dạng thông điệp IOS</h3>'+ccPre('%FACILITY-SEVERITY-MNEMONIC: nội dung\nví dụ: %LINK-3-UPDOWN: Interface Gi0/1, changed state to down')+'<p class="note">Các thông điệp ở đây là ví dụ tự soạn theo dạng IOS thường gặp, một số mức 0 và 1 chỉ minh họa. Bật dấu thời gian bằng service timestamps log datetime msec.</p>',
    tt:'Bảng mức nghiêm trọng syslog',tb:tbl(['Mức','Tên','Từ khoá IOS','Ví dụ'],CCSEV.map((n,k)=>[k,n,n.toLowerCase().replace('emergency','emergencies').replace('alert','alerts').replace('critical','critical').replace('error','errors').replace('warning','warnings').replace('notice','notifications').replace('informational','informational').replace('debugging','debugging'),['hệ thống sập','cần can thiệp ngay','lỗi nghiêm trọng','lỗi (link down)','cảnh báo','bình thường nhưng đáng chú ý','thông tin','debug'][k]]),c),cap:`${T[0]}: ${first(T[1])}`};}
