/* ---------- Multicast: PIM-SM, RPF, ánh xạ MAC ---------- */
const MCG=[['224.1.1.1','Quản trị nội bộ (224.0.1.0/24 và các dải toàn cầu)'],['239.1.1.1','Dải admin-scoped 239/8 (RFC 2365)'],['239.129.1.1','Cùng MAC với 239.1.1.1 (va chạm 32:1)'],['225.1.1.1','Dải toàn cầu ASM'],['232.1.1.1','Dải SSM 232/8 (RFC 4607)'],['224.0.0.5','Link-local: OSPF (không chuyển tiếp)']];
function mcMacR(i){const g=String(S.ccP1),o=g.split('.').map(Number),c=clamp(i,0,2);
  const low=((o[1]&0x7f)<<16)|(o[2]<<8)|o[3];const h=b=>b.toString(16).padStart(2,'0');const mac=`01:00:5e:${h(o[1]&0x7f)}:${h(o[2])}:${h(o[3])}`;
  const same=[];for(let a=224;a<=239;a++)for(let b=0;b<2;b++){const o2=(o[1]&0x7f)|(b<<7);if(a!==o[0]||o2!==o[1])same.push(`${a}.${o2}.${o[2]}.${o[3]}`);}
  const fig=`<div class="scroll"><table>${tbl(['Bước','Giá trị'],[['Địa chỉ nhóm',`${g}`],['Nhị phân (4 byte)',o.map(x=>x.toString(2).padStart(8,'0')).join('.')],['Lấy 23 bit thấp',(low).toString(2).padStart(23,'0')+` (0x${low.toString(16)})`],['Ghép sau tiền tố 01:00:5E',mac]])}</table></div>`;
  const T=[['Quy tắc ánh xạ',`Địa chỉ IPv4 multicast (224.0.0.0/4) ánh xạ vào MAC multicast bằng cách lấy tiền tố cố định 01:00:5E, đặt bit thứ 24 bằng 0 và chép 23 bit thấp của địa chỉ IP vào 23 bit sau. Nhóm ${g} thành ${mac}.`],
   ['Va chạm 32:1',`Địa chỉ IPv4 multicast có 28 bit thay đổi nhưng MAC chỉ giữ 23 bit, nên 5 bit bị bỏ: 32 địa chỉ nhóm khác nhau chia sẻ cùng một MAC. Ví dụ cùng MAC ${mac}: ${same.slice(0,3).join(', ')}... (tổng 32 nhóm). Hệ quả: switch có thể gửi lưu lượng nhóm khác cho cổng đã tham gia nhóm trùng MAC, và CPU máy thu phải lọc lại ở lớp IP. Nên chọn địa chỉ nhóm tránh trùng và dùng IGMP snooping.`],
   ['IPv6 và các dải đặc biệt',`IPv6 multicast ánh xạ sang 33:33 + 32 bit thấp của địa chỉ. Dải IPv4 cần nhớ: 224.0.0.0/24 link-local (không bao giờ chuyển tiếp; 224.0.0.5/6 OSPF, .9 RIPv2, .10 EIGRP, .13 PIM, .18 VRRP), 224.0.1.0/24 internetwork control, 232.0.0.0/8 SSM, 233.0.0.0/8 GLOP, 239.0.0.0/8 admin-scoped (tương đương dải riêng).`]];
  return{fig,hint:'Chọn nhóm và xem địa chỉ MAC. Chọn 239.1.1.1 rồi 239.129.1.1 để thấy hai nhóm trùng MAC.',out:prKv([['Nhóm',g],['Loại',(MCG.find(x=>x[0]===g)||['',''])[1]],['MAC multicast',mac],['Số nhóm chung MAC','32']]),
    info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),tt:'Dải địa chỉ multicast IPv4',tb:tbl(['Dải','Dùng cho'],[['224.0.0.0/24','Link-local, không chuyển tiếp'],['224.0.1.0/24','Internetwork control'],['224.0.2.0 đến 238.255.255.255','Toàn cầu ASM'],['232.0.0.0/8','SSM'],['233.0.0.0/8','GLOP'],['239.0.0.0/8','Admin-scoped (nội bộ tổ chức)']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
function mcRpfR(i){const uni=S.ccP1,arr=S.ccP2,mr=S.ccP3==='yes',c=clamp(i,0,2);
  const rpfIf=mr?'Gi0/2':uni;const pass=rpfIf===arr;
  const N=[['s',40,40,'Nguồn','10.9.9.10'],['r',180,100,'R1','nhận gói'],['a',330,40,'Gi0/0','',{c:V_('k4')}],['b',330,100,'Gi0/1','',{c:V_('k2')}],['d',330,160,'Gi0/2','',{c:V_('u3')}],['rc',40,160,'Máy thu']];
  const L=[['s','r','',{c:V_('line')}],['r','rc','OIL',{on:pass&&c>=2}]];
  const uniN=uni==='Gi0/0'?'a':'b',arrN=arr==='Gi0/0'?'a':arr==='Gi0/1'?'b':'d';
  L.push(['r',uniN,'unicast về nguồn',{c:V_('warn'),w:1}]);L.push(['r',arrN,'gói tới',{on:c>=2&&pass,off:c>=2&&!pass}]);
  const fig=npTopo(N.filter(n=>n[0]!=='d'||arr==='Gi0/2'||mr),L.filter(l=>true),{h:196,w:60,cap:pass||c<2?'Cổng RPF = cổng theo bảng định tuyến về nguồn':'Gói tới sai cổng: RPF fail, bị loại'});
  const T=[['Gói multicast tới',`Gói (S,G) = (10.9.9.10, 239.1.1.1) tới R1 trên cổng ${arr}. Với multicast, định tuyến theo hướng NGƯỢC: không hỏi “đích ở đâu” mà hỏi “gói này có đến từ hướng của nguồn không”.`],
   ['Kiểm tra RPF (Reverse Path Forwarding)',`R1 tra bảng định tuyến unicast (hoặc bảng mroute tĩnh/MRIB) cho địa chỉ NGUỒN 10.9.9.10: ${mr?'có lệnh ip mroute chỉ ra cổng RPF riêng là Gi0/2 (ghi đè unicast, dùng khi đường multicast khác đường unicast)':`đường unicast về nguồn đi qua ${uni}`}. Cổng RPF = ${rpfIf}.`],
   ['Quyết định',pass?`Gói tới trên cổng ${arr} trùng cổng RPF ${rpfIf}: đạt, R1 nhân bản gói ra danh sách cổng ra (OIL) của (S,G).`:`Gói tới ${arr} khác cổng RPF ${rpfIf}: RPF thất bại, gói bị LOẠI. Đây là cơ chế chống vòng lặp chủ yếu của multicast; nếu đường unicast bất đối xứng, multicast mất dù ping bình thường. Sửa bằng cách đồng nhất định tuyến, ip mroute, hoặc dùng PIM trên đúng cổng.`]];
  return{fig,hint:'Chọn cổng mà bảng định tuyến unicast dùng để về nguồn, cổng gói thực sự tới, và có hay không ip mroute. RPF chỉ đạt khi hai cổng trùng nhau.',
    out:prKv([['Cổng unicast về nguồn',uni],['Cổng RPF (sau mroute)',rpfIf],['Gói tới',arr],['Kết quả',pass?'Đạt, chuyển tiếp':'RPF fail, loại gói']]),info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),
    tt:'Mục (S,G) tương ứng trong bảng mroute',tb:tbl(['Trường','Giá trị'],[['(S,G)','(10.9.9.10, 239.1.1.1)'],['Incoming interface (RPF)',rpfIf],['RPF neighbor','láng giềng PIM về nguồn'],['Outgoing interface list','Gi0/3 (cổng tới máy thu)'],['Cờ','T (SPT), J (đã chuyển SPT) khi chạy PIM-SM']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
function mcSm(){const sp=S.ccP1,f=S.ccP2,st=[];
  st.push({f:0,t:1,s:'IGMP Report (239.1.1.1)',m:'Máy thu tham gia nhóm',p:'IGMP v2/v3',k:'ctl',d:'Máy thu báo cho router cuối (last-hop router, DR) rằng nó muốn nhận nhóm 239.1.1.1. IGMPv2: Membership Report gửi tới chính địa chỉ nhóm; IGMPv3 gửi tới 224.0.0.22 và có thể chỉ rõ nguồn (SSM). Router truy vấn mỗi 125 giây (General Query).',fl:[['Loại','Membership Report'],['Nhóm','239.1.1.1'],['Query interval','125 giây mặc định']]});
  if(f==='norp'){st.push({f:1,t:1,s:'Không có RP cho nhóm này',m:'Không tìm thấy RP',p:'lỗi cấu hình',k:'rt',bad:1,d:'Router cuối không có ánh xạ RP cho nhóm 239.1.1.1 (chưa cấu hình ip pim rp-address, Auto-RP hoặc BSR). Không thể gửi (*,G) Join, nên máy thu không nhận được gì. Kiểm tra show ip pim rp mapping.',chk:['show ip pim rp mapping','show ip mroute 239.1.1.1: không có (*,G) hợp lệ']});return{st};}
  st.push({f:1,t:2,s:'PIM (*,G) Join → RP',m:'(*,G) Join theo hướng RP',p:'PIM v2 · 224.0.0.13',k:'ctl',d:'Router cuối gửi PIM Join (*,239.1.1.1) về phía RP theo định tuyến unicast, từng chặng một. Mỗi router dọc đường tạo mục (*,G) và cổng RPF hướng RP. Đây là cây chung (shared tree) gốc tại RP. Join được gửi lại định kỳ mỗi 60 giây.',fl:[['Địa chỉ','224.0.0.13 (ALL-PIM-ROUTERS)'],['Mục tạo','(*, 239.1.1.1), incoming = hướng RP']]});
  if(f==='nopim'){st.push({f:2,t:2,s:'Chặng giữa chưa bật PIM',m:'Join bị chặn giữa đường',p:'lỗi cấu hình',k:'rt',bad:1,d:'Một cổng trên đường tới RP chưa có ip pim sparse-mode nên không có láng giềng PIM và Join không được chuyển tiếp. show ip pim neighbor thiếu láng giềng; show ip mroute chỉ có (*,G) với outgoing interface rỗng ở phía RP.',chk:['show ip pim interface','show ip pim neighbor']});return{st};}
  st.push({f:4,t:3,s:'Nguồn bắt đầu phát',m:'Nguồn phát luồng multicast',p:'UDP/RTP tới 239.1.1.1',k:'med',d:'Nguồn gửi gói multicast. Router đầu tiên (first-hop router, DR phía nguồn) nhận gói nhưng chưa biết RP có cần không.'});
  st.push({f:3,t:2,s:'PIM Register (đóng gói unicast)',m:'PIM Register',p:'PIM, unicast tới RP',k:'ctl',d:'DR phía nguồn đóng gói chính gói dữ liệu đầu tiên vào PIM Register gửi unicast tới RP, để RP biết nguồn S đang hoạt động cho nhóm G.',fl:[['Loại','PIM Register (đóng gói dữ liệu)'],['Đích','Địa chỉ RP (unicast)']]});
  st.push({f:2,t:3,s:'PIM (S,G) Join → nguồn',m:'RP kéo cây nguồn',p:'PIM',k:'ctl',d:'RP gửi (S,G) Join về phía nguồn để nhận dữ liệu qua đường native thay vì đóng gói. Mỗi chặng tạo (S,G).'});
  st.push({f:2,t:3,s:'Register-Stop',m:'Register-Stop',p:'PIM, unicast',k:'ctl',d:'Khi dữ liệu native đã đến RP, RP gửi Register-Stop để DR ngừng đóng gói. Từ đây không còn hiện tượng encap/decap tốn CPU.'});
  st.push({f:2,t:1,s:'Dữ liệu qua cây chung (*,G)',m:'Dữ liệu theo cây chung',p:'RP → DR thu',k:'med',d:'RP chuyển dữ liệu xuống theo (*,G) tới router cuối và máy thu. Lúc này đường đi qua RP có thể vòng và dài hơn đường ngắn nhất.'});
  if(sp==='inf'){st.push({f:1,t:1,s:'spt-threshold infinity: ở lại cây chung',m:'Giữ nguyên cây chung',p:'cấu hình',k:'sync',d:'Đã cấu hình ip pim spt-threshold infinity nên router cuối không bao giờ chuyển sang cây ngắn nhất. Lưu lượng luôn qua RP: tiết kiệm trạng thái (S,G) ở router nhưng RP chịu tải và đường dài hơn.'});return{st};}
  st.push({f:1,t:3,s:'PIM (S,G) Join theo đường ngắn nhất',m:'Chuyển sang cây nguồn (SPT)',p:'PIM',k:'ctl',d:'Theo mặc định (spt-threshold 0 kb/s) router cuối chuyển sang cây đường ngắn nhất ngay khi nhận gói đầu tiên: gửi (S,G) Join thẳng về phía nguồn theo cổng RPF về S (không qua RP).'});
  st.push({f:1,t:2,s:'PIM (S,G,rpt) Prune → RP',m:'Cắt nhánh khỏi cây chung',p:'PIM',k:'ctl',d:'Khi dữ liệu SPT đã tới, router cuối gửi (S,G,rpt) Prune về RP để RP ngừng chuyển nguồn S xuống theo cây chung, tránh gói trùng.'});
  st.push({f:3,t:1,s:'Dữ liệu theo SPT',m:'Dữ liệu theo đường ngắn nhất',p:'nguồn → router cuối',k:'sync',d:'Dữ liệu đi theo đường ngắn nhất từ nguồn tới router cuối, RP chỉ còn vai trò kết nối ban đầu. Trong show ip mroute, cờ T (SPT-bit) được đặt.'});
  return{st};}
function mcSmR(i){const B=mcSm(),bad=B.st.some(x=>x.bad);
  return npLad(B,i,['Máy thu','Router cuối (DR thu)','RP','Router đầu (DR nguồn)','Nguồn'],{rows:(c,s)=>[['spt-threshold',S.ccP1==='inf'?'infinity (ở cây chung)':'0 (mặc định)'],['Lỗi giả lập',{none:'không',norp:'Không có RP',nopim:'Thiếu PIM giữa đường'}[S.ccP2]],['Bước',`${c+1} trên ${B.st.length}`],['Kết quả cuối',bad?'Máy thu không nhận luồng':'Máy thu nhận luồng']],
    tt:'Các bản tin PIM-SM',tb:tbl(['Bản tin','Hướng','Mục đích'],[['(*,G) Join','Thu → RP','Dựng cây chung'],['Register','DR nguồn → RP (unicast)','Báo nguồn mới'],['Register-Stop','RP → DR nguồn','Dừng đóng gói'],['(S,G) Join','Thu hoặc RP → nguồn','Dựng cây nguồn'],['(S,G,rpt) Prune','Thu → RP','Cắt nguồn khỏi cây chung'],['Hello','Mọi láng giềng','Phát hiện láng giềng, bầu DR']])});}
