/* ---------- Ảo hoá và overlay: VXLAN, LISP ---------- */
function vrtVx(){const hp=+S.ccP1,v6=S.ccP2==='v6',um=+S.ccP3,evpn=S.ccP4==='evpn';
  const oip=v6?40:20,inner=hp+14,under=oip+8+8+inner;return{hp,v6,um,evpn,oip,inner,under,fit:under<=um,need:under,ovh:under-hp};}
function vrtVxR(i){const D=vrtVx(),c=clamp(i,0,2);let s='';const seg=[['Eth ngoài',14,'muted'],['IP ngoài',D.oip,'k4'],['UDP',8,'k2'],['VXLAN',8,'warn'],['Eth trong',14,'u3'],['IP của máy',D.hp,'up']];
  const tot=seg.reduce((a,x)=>a+x[1],0),sc=336/Math.max(tot,D.um+14);let x=18;
  seg.forEach(g=>{const w=g[1]*sc,col=V_(g[2]);s+=`<rect x="${x.toFixed(1)}" y="30" width="${w.toFixed(1)}" height="34" style="fill:color-mix(in srgb,${col} 28%,${V_('panel')});stroke:${col}"/>`+(w>=16?tx(x+w/2,43,g[0],{fs:w<32?6:7.2,c:V_('ink')})+tx(x+w/2,56,String(g[1]),{fs:7.2,b:1,c:V_('ink')}):'');x+=w;});
  const xm=18+(D.um+14)*sc;s+=li([[xm,22],[xm,72]],{c:D.fit?V_('k1'):V_('cp'),w:2,d:'4 3'})+tx(xm,18,'MTU underlay '+D.um,{fs:7.6,b:1,c:D.fit?V_('k1'):V_('cp')});
  s+=tx(186,90,`Gói IP trên underlay = ${D.under} byte (cần MTU underlay ≥ ${D.under}); phụ thêm ${D.ovh} byte so với gói IP của máy`,{fs:8.2,b:1,c:V_('ink')});
  s+=tx(186,106,D.fit?'Vừa MTU underlay: không phân mảnh':`Thiếu ${D.under-D.um} byte: gói bị phân mảnh hoặc loại (VXLAN đặt DF=1 theo thực tế)`,{fs:8.2,c:D.fit?V_('k1'):V_('cp')});
  const T=[['Đóng gói VXLAN',`VXLAN bọc toàn bộ khung Ethernet của máy ảo vào UDP đích 4789: tiêu đề VXLAN 8 byte mang VNI 24 bit (hơn 16 triệu mạng logic, so với 4094 VLAN). Cổng nguồn UDP là băm từ khung gốc để underlay cân bằng tải ECMP. Hai đầu đường hầm là VTEP (VXLAN Tunnel Endpoint), thường là leaf switch hoặc vSwitch. Cần ${D.oip===20?50:70} byte phụ thêm (không tính FCS): IP ${D.oip} + UDP 8 + VXLAN 8 + Ethernet trong 14, cộng Ethernet ngoài 14.`],
   ['MTU của underlay',`Máy gửi gói IP ${D.hp} byte nên khung trong là ${D.inner} byte và gói IP trên underlay là ${D.under} byte. Underlay ${D.um} ${D.fit?'đủ':'KHÔNG đủ'}. Cách làm chuẩn: đặt underlay jumbo (9000 hoặc 9216) để máy 1500 chạy trọn vẹn, vì VXLAN thường đặt cờ DF và không phân mảnh.`],
   ['Mặt phẳng điều khiển',D.evpn?'BGP EVPN (RFC 7432, 8365) làm mặt phẳng điều khiển: leaf học MAC và IP cục bộ rồi quảng bá bằng route type 2 (MAC/IP), type 3 (inclusive multicast, danh sách VTEP cho BUM), type 5 (tiền tố IP) trong MP-BGP. Có ARP suppression, anycast gateway và symmetric IRB (L3 VNI) nên định tuyến phân tán, không flood.':'Flood-and-learn: VTEP học MAC bằng cách nhìn gói đến, và gói BUM (broadcast, unknown unicast, multicast) được phát tán bằng multicast underlay (mỗi VNI ánh xạ một nhóm) hoặc ingress replication. Đơn giản nhưng flood nhiều và mở rộng kém; EVPN là cách hiện đại thay thế.']];
  return{fig:svgw(372,114,s,'Cấu trúc gói VXLAN'),hint:'Đổi kích thước gói của máy, IPv4 hay IPv6 underlay và MTU underlay để thấy khi nào VXLAN bị phân mảnh.',
    out:prKv([['Gói IP của máy',D.hp+' byte'],['Phụ thêm VXLAN',D.ovh+' byte'],['Gói trên underlay',D.under+' byte'],['MTU underlay',D.um],['Kết quả',D.fit?'Vừa':'Không đủ MTU'],['Mặt phẳng điều khiển',D.evpn?'BGP EVPN':'Flood-and-learn']]),
    info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),tt:'So sánh VLAN và VXLAN',tb:tbl(['Tiêu chí','VLAN (802.1Q)','VXLAN'],[['Số mạng','4094','16.777.216 (VNI 24 bit)'],['Phạm vi','Lớp 2, STP','Overlay trên underlay IP, ECMP'],['Đóng gói','Thẻ 4 byte','50 byte (IPv4)'],['Điều khiển','MAC learning, STP','EVPN hoặc flood-and-learn'],['Cổng UDP','—','4789']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
function vrtLisp(){const reg=S.ccP1==='yes',st=[];
  st.push({f:3,t:2,s:'Map-Register EID 10.2.0.0/24',m:'ETR đăng ký EID-prefix',p:'LISP · UDP 4342',k:'ctl',d:reg?'ETR gửi Map-Register tới Map-Server (MS) khai: EID-prefix 10.2.0.0/24 đặt sau RLOC 198.51.100.2. Có xác thực bằng khoá; lặp lại định kỳ (60 giây). LISP tách “ai” (EID, định danh) khỏi “ở đâu” (RLOC, định vị) để giữ nguyên địa chỉ khi di chuyển.':'ETR của site B chưa đăng ký (hoặc đăng ký lỗi vì khoá sai): MS không có bản ghi cho 10.2.0.0/24.',fl:[['EID-prefix','10.2.0.0/24'],['RLOC','198.51.100.2'],['Giao thức','UDP 4342 (control)']]});
  st.push({f:0,t:1,s:'Gói tới 10.2.0.5',m:'Máy A gửi tới EID đích',p:'IP gốc',k:'med',d:'Máy A gửi gói IP thường tới 10.2.0.5. ITR (Ingress Tunnel Router) nhận gói và tra map-cache (bộ nhớ ánh xạ EID→RLOC).'});
  st.push({f:1,t:1,s:'map-cache miss',m:'Chưa có ánh xạ trong map-cache',p:'ITR',k:'sync',d:'Không có mục cho 10.2.0.5 nên ITR bắt đầu quá trình phân giải (gói đầu có thể bị bỏ hoặc gửi qua Proxy-ITR tuỳ cấu hình).'});
  st.push({f:1,t:2,s:'Map-Request (EID 10.2.0.5)',m:'Map-Request',p:'LISP · UDP 4342',k:'ctl',d:'ITR gửi Map-Request tới Map-Resolver (MR) hỏi RLOC của EID 10.2.0.5, kèm địa chỉ RLOC của chính nó để nhận trả lời. Map-Resolver và Map-Server thường là một thiết bị (MS/MR).',fl:[['EID','10.2.0.5'],['ITR-RLOC','198.51.100.1']]});
  if(!reg){st.push({f:2,t:1,s:'Negative Map-Reply',m:'Negative Map-Reply',p:'LISP',k:'rt',bad:1,d:'MS không có đăng ký nào bao 10.2.0.5 nên trả Negative Map-Reply (action native-forward): đích nằm ngoài vùng LISP. ITR gửi gói theo định tuyến thường (hoặc qua Proxy-ETR). Nếu thực ra site B đáng lẽ ở LISP, nguyên nhân là ETR chưa đăng ký: kiểm tra khoá Map-Register, địa chỉ MS, kết nối UDP 4342.',chk:['show lisp site (trên MS)','show ip lisp map-cache (trên ITR)']});return{st};}
  st.push({f:2,t:3,s:'Map-Request chuyển tới ETR',m:'MS chuyển yêu cầu',p:'LISP',k:'ctl',d:'MS tra bản ghi đã đăng ký và chuyển Map-Request tới ETR sở hữu EID (hoặc tự trả lời nếu ETR bật proxy-reply).'});
  st.push({f:3,t:1,s:'Map-Reply: RLOC 198.51.100.2 (pri 1, wt 100)',m:'Map-Reply trực tiếp',p:'LISP · UDP 4342',k:'ctl',d:'ETR trả lời THẲNG cho ITR bằng Map-Reply: EID-prefix 10.2.0.0/24, danh sách RLOC kèm priority (nhỏ hơn ưu tiên hơn) và weight (chia tải khi priority bằng nhau), TTL bản ghi (mặc định 24 giờ). ITR lưu vào map-cache.',fl:[['EID-prefix','10.2.0.0/24'],['RLOC','198.51.100.2, priority 1, weight 100'],['TTL','1440 phút (mặc định)']]});
  st.push({f:1,t:3,s:'Gói LISP: IP(RLOC) UDP 4341 LISP IP(EID)',m:'ITR đóng gói và gửi',p:'LISP data · UDP 4341',k:'tcp',d:'ITR bọc gói gốc: IP ngoài (nguồn RLOC ITR, đích RLOC ETR), UDP đích 4341, tiêu đề LISP (có Instance ID 24 bit để phân tách VRF/VN), rồi gói gốc. Phụ thêm khoảng 36 byte với IPv4 (20 + 8 + 8). Cổng nguồn UDP băm từ luồng để cân bằng tải.',fl:[['IP ngoài','198.51.100.1 → 198.51.100.2'],['UDP','đích 4341'],['LISP','Instance ID, cờ'],['Phụ thêm','khoảng 36 byte (IPv4)']]});
  st.push({f:3,t:4,s:'Giải đóng gói, gửi tới 10.2.0.5',m:'ETR giải đóng gói',p:'IP gốc',k:'sync',d:'ETR bỏ tiêu đề ngoài và chuyển gói gốc vào mạng nội bộ site B. Nhờ tách EID khỏi RLOC, máy B có thể di chuyển giữa các site mà vẫn giữ địa chỉ 10.2.0.5; chỉ cần ETR mới đăng ký lại. SD-Access dùng LISP làm mặt phẳng điều khiển của fabric (dữ liệu là VXLAN-GPO).'});
  return{st};}
function vrtLispR(i){const B=vrtLisp(),bad=B.st.some(x=>x.bad);
  return npLad(B,i,['Máy A','ITR','MS/MR','ETR','Máy B'],{rows:(c,s)=>[['ETR đã đăng ký EID',S.ccP1==='yes'?'Có':'Không'],['Bước',`${c+1} trên ${B.st.length}`],['Bản tin',s.m],['Kết quả',bad?'Không có ánh xạ: định tuyến native':'Đường hầm LISP hoạt động']],
    tt:'Thành phần LISP',tb:tbl(['Thành phần','Vai trò'],[['EID','Định danh của máy (địa chỉ nội bộ site)'],['RLOC','Định vị: địa chỉ của router biên (ETR)'],['ITR / ETR','Đóng gói / giải đóng gói (xTR là cả hai)'],['Map-Server (MS)','Nhận đăng ký EID từ ETR'],['Map-Resolver (MR)','Nhận Map-Request từ ITR'],['PITR / PETR','Proxy cho mạng không dùng LISP']])});}
const VRT_PTS=[
 ['Máy ảo, container và hạ tầng ảo hoá','Hypervisor loại 1 (chạy trên phần cứng: ví dụ ESXi, KVM) và loại 2 (chạy trên hệ điều hành). Máy ảo có hệ điều hành riêng, container chia sẻ nhân của máy chủ nên nhẹ và khởi động nhanh. Mạng ảo: vSwitch hoặc Open vSwitch nối máy ảo ra mạng vật lý; SR-IOV và PCIe passthrough cho NIC hiệu năng cao; DPDK/VPP xử lý gói ở không gian người dùng. Router ảo như Catalyst 8000V chạy trên hypervisor cho đám mây và NFV.'],
 ['VRF và VRF-lite','VRF cho nhiều bảng định tuyến độc lập trên cùng một router, địa chỉ chồng lấn không xung đột. VRF-lite là VRF không dùng MPLS: mỗi VRF cần một giao diện con hoặc VLAN riêng nối giữa các router và giao thức định tuyến riêng cho từng VRF (address-family ipv4 vrf trong BGP/OSPF). Dùng để phân tách khách, dịch vụ, quản lý. Rò rỉ tuyến giữa VRF dùng route-target (khi có MP-BGP) hoặc route-map hoặc VRF-aware.'],
 ['SD-Access (fabric)','Fabric dựa trên LISP (điều khiển), VXLAN-GPO (dữ liệu) và Cisco TrustSec. Vai trò: edge node (nối người dùng), border node (nối ngoài fabric), control plane node (Map-Server/Resolver). Anycast gateway: mọi edge dùng chung địa chỉ cổng. Chính sách theo nhóm bảo mật (SGT) mang trong tiêu đề VXLAN, thực thi bằng SGACL. Điều phối qua Catalyst Center (trước đây DNA Center) và ISE cho danh tính.'],
 ['SD-WAN (Catalyst SD-WAN, trước đây Viptela)','Bốn thành phần: Manager (trước là vManage, quản lý và giám sát), Controller (vSmart, mặt phẳng điều khiển với giao thức OMP), Validator (vBond, xác thực và điều phối kết nối đầu tiên) và WAN Edge (router dữ liệu). Các edge dựng đường hầm IPsec/GRE (TLOC = transport locator, mỗi TLOC có màu như mpls, biz-internet), dùng BFD đo chất lượng. Chính sách tập trung (AAR chọn đường theo SLA, QoS, bảo mật). Mô hình VPN (segment) ánh xạ gần với VRF.'],
 ['So sánh các công nghệ overlay','VXLAN (RFC 7348) chủ yếu cho trung tâm dữ liệu; LISP tách định danh và định vị, dùng trong SD-Access; GRE/mGRE bọc mọi giao thức, DMVPN thêm NHRP; MPLS L3VPN là overlay của nhà mạng; GENEVE (RFC 8926) linh hoạt tuỳ chọn. Mọi overlay đều thêm byte tiêu đề nên phải tính MTU underlay.']];
