/* ---------- L3VPN ---------- */
function l3Cp(){const f=S.ccP1,rtm=S.ccP2,st=[];
  const stop=(m,d,chk)=>{st.push({f:3,t:0,s:m,m,p:'MP-BGP',k:'rt',bad:1,d,chk});return{st};};
  st.push({f:0,t:1,s:'CE1 → PE1: tiền tố 192.0.2.0/24',m:'CE1 quảng bá tiền tố cho PE1',p:'eBGP hoặc IGP trong VRF',k:'ctl',d:'CE1 báo tiền tố của khách cho PE1 qua giao thức PE–CE (eBGP, OSPF, EIGRP, tĩnh...). PE1 học tiền tố vào bảng định tuyến RIÊNG của VRF khách A (không vào bảng toàn cục). Mỗi VRF có RD và các route-target.',fl:[['VRF','CUST-A'],['RD','65000:100 (8 byte, làm tiền tố duy nhất)']]});
  st.push({f:1,t:2,s:'VPNv4 UPDATE: RD:192.0.2.0/24, RT 65000:100, nhãn VPN 30011',m:'PE1 quảng bá VPNv4 qua MP-BGP',p:'MP-BGP · AFI 1 / SAFI 128',k:'ctl',d:'PE1 đóng gói tiền tố thành VPNv4: 12 byte = RD (8 byte) + IPv4 (4 byte), kèm các extended community Route-Target (RT) xuất, một NHÃN VPN (cục bộ do PE1 cấp, ở đây 30011), và next-hop là loopback của PE1. RD chỉ làm cho tiền tố duy nhất (cho phép hai khách dùng cùng 192.0.2.0/24); RT mới quyết định ai được nhập.',fl:[['NLRI','RD 65000:100 + 192.0.2.0/24 (nhãn 30011)'],['Ext community','RT export 65000:100'],['Next-hop','10.0.0.1 (loopback PE1)']]});
  if(f==='nolabel')return stop('Không có đường tới next-hop','PE2 nhận được VPNv4 nhưng next-hop 10.0.0.1 KHÔNG có đường nhãn (LSP) trong lõi (LDP/SR chưa chạy, hoặc loopback bị tổng hợp): tiền tố được học nhưng không cài vào VRF vì next-hop không hợp lệ. Dấu hiệu: show bgp vpnv4 unicast hiện “inaccessible”.',['Kiểm tra LSP: show mpls forwarding-table 10.0.0.1','Quảng bá loopback PE vào IGP và LDP']);
  st.push({f:2,t:3,s:'RR phản chiếu (không đổi RT, nhãn)',m:'Route reflector chuyển tiếp VPNv4',p:'MP-BGP',k:'sync',d:'Trong mạng lớn, PE không nối full-mesh iBGP mà nối tới route reflector; RR phản chiếu VPNv4 mà không đổi next-hop. RR không cần VRF; để không giữ mọi tiền tố, RR dùng rt-filter (RT constrain, RFC 4684) hoặc chỉ giữ cái cần. Cần address-family vpnv4 và send-community extended.'});
  if(f==='rt'){st.push({f:3,t:3,s:'RT 65000:100 không khớp import',m:'PE2 bỏ tiền tố: RT không khớp',p:'MP-BGP',k:'rt',bad:1,d:'PE2 nhập (import) khi có ÍT NHẤT MỘT RT của tiền tố trùng với RT import của VRF. VRF CUST-A trên PE2 import 65000:200 (sai), nên tiền tố bị bỏ qua (vẫn nằm trong bảng BGP VPNv4 nhưng không vào VRF). Lỗi RT là nguyên nhân hàng đầu của “VPN không thông”.',chk:['show bgp vpnv4 unicast all (có tiền tố)','show ip route vrf CUST-A (không có)','Sửa route-target import cho khớp']});return{st};}
  st.push({f:3,t:3,s:'Nhập vào VRF (RT khớp)',m:'PE2 nhập tiền tố vào VRF',p:'MP-BGP',k:'sync',d:'RT khớp: PE2 cài tiền tố vào bảng VRF CUST-A, với next-hop đệ quy qua LSP tới 10.0.0.1 và nhãn VPN 30011. Cách đặt RT quyết định mô hình: full mesh (mọi VRF import/export cùng RT), hub-and-spoke (RT riêng cho hub và spoke), extranet (thêm RT chung).',fl:[['Import','65000:100 khớp'],['Next-hop','10.0.0.1 qua LSP']]});
  st.push({f:3,t:4,s:'PE2 → CE2: tiền tố 192.0.2.0/24',m:'PE2 báo cho CE2',p:'eBGP hoặc IGP trong VRF',k:'ctl',d:'PE2 quảng bá tiền tố cho CE2 qua giao thức PE–CE. Với eBGP cần chú ý AS-path: hai site cùng AS khách sẽ bị loop-prevention chặn (cần allowas-in hoặc as-override trên PE).',fl:[['Lưu ý','Cùng AS khách ở hai site → as-override hoặc allowas-in']]});
  return{st};}
function l3CpR(i){const B=l3Cp(),bad=B.st.some(x=>x.bad);
  return npLad(B,i,['CE1','PE1','RR','PE2','CE2'],{rows:(c,s)=>[['Lỗi giả lập',{none:'Không',nolabel:'Next-hop không có LSP',rt:'RT import sai'}[S.ccP1]],['Bước',`${c+1} trên ${B.st.length}`],['Kết quả',bad?'Tiền tố không vào VRF PE2':'Site B thấy tiền tố của site A']],
    tt:'RD và RT khác nhau thế nào',tb:tbl(['Mục','RD','RT'],[['Tác dụng','Làm tiền tố duy nhất (cho phép địa chỉ trùng)','Quyết định tiền tố nào vào VRF nào'],['Kích thước','8 byte','Extended community 8 byte'],['Số lượng','Một cho mỗi VRF (thường)','Nhiều export, nhiều import'],['Mang theo','Trong NLRI','Trong thuộc tính']])});}
function l3Dp(){const hops=+S.ccP1,sr=S.ccP2==='sr',st=[];
  const nodes=['CE1','PE1'];for(let k=0;k<hops;k++)nodes.push('P'+(k+1));nodes.push('PE2','CE2');
  st.push({f:0,t:1,s:'IP 192.0.2.10 → 198.51.100.7',m:'Gói IP vào VRF',p:'IP',k:'tcp',d:'Gói vào PE1 trên giao diện thuộc VRF CUST-A. PE1 tra bảng của VRF đó (không phải bảng toàn cục), tìm ra tiền tố đích qua PE2: nhãn VPN 30022 (do PE2 cấp) và next-hop 10.0.0.2.'});
  st.push({f:1,t:2,s:'Đẩy HAI nhãn: ngoài '+(sr?'16004 (SID nút PE2)':'24005 (LDP)')+', trong 30022 (VPN)',m:'PE1 đẩy hai nhãn',p:'MPLS · ngăn xếp 2 nhãn',k:'ctl',d:`PE1 đẩy nhãn VPN 30022 (đáy, S=1) trước, rồi nhãn vận chuyển ${sr?'16004 là SID nút của PE2 trong SR':'24005 do LDP cấp cho loopback PE2'} lên trên. Nhãn ngoài đưa gói tới PE2; nhãn trong cho PE2 biết VRF/giao diện đích. Lõi chỉ nhìn nhãn ngoài.`,fl:[['Nhãn ngoài','vận chuyển → PE2'],['Nhãn trong','VPN 30022, S=1'],['Thêm vào gói','8 byte']]});
  for(let k=1;k<=hops;k++){const last=k===hops;
    st.push({f:k+1,t:k+2,s:last?'P'+k+': pop nhãn ngoài (PHP)':'P'+k+': swap nhãn ngoài',m:'P'+k+(last?': PHP':': swap'),p:'MPLS',k:'ctl',d:last?'Chặng áp chót gỡ nhãn ngoài; PE2 chỉ nhận nhãn VPN (một nhãn). Lõi KHÔNG biết VPN hay địa chỉ của khách: có thể trùng địa chỉ giữa các khách mà không xung đột.':'P hoán đổi nhãn ngoài, không đụng nhãn VPN bên trong và không xem IP.'});}
  st.push({f:hops+1,t:hops+2,s:'PE2: pop nhãn VPN, tra VRF',m:'PE2 gỡ nhãn VPN',p:'MPLS',k:'sync',d:'PE2 đọc nhãn VPN 30022, biết cần tra bảng VRF CUST-A (hoặc gửi thẳng ra giao diện, tuỳ chế độ cấp nhãn: per-prefix, per-VRF, per-CE) rồi gửi gói IP thuần tới CE2.'});
  return{st,nodes};}
function l3DpR(i){const B=l3Dp();
  return npLad(B,i,B.nodes,{rows:(c,s)=>[['Số router P',+S.ccP1],['Nhãn vận chuyển',S.ccP2==='sr'?'SR-MPLS':'LDP'],['Bước',`${c+1} trên ${B.st.length}`],['Số nhãn khi qua lõi','2']],
    tt:'Các kiểu cấp nhãn VPN',tb:tbl(['Kiểu','Một nhãn cho','Đánh đổi'],[['Per-prefix','Mỗi tiền tố','Nhiều nhãn, tra IP không cần ở egress'],['Per-VRF','Cả VRF','Ít nhãn, PE2 phải tra IP trong VRF'],['Per-CE','Mỗi CE','Cân bằng, gửi thẳng tới CE']])});}
function l3Rt(){const m=S.ccP1,N=m==='hub'?4:m==='ext'?3:3,c=[];
  return m;}
function l3RtR(i){const m=S.ccP1,c=clamp(i,0,2);
  const X={full:{v:[['A','100:1','100:1'],['B','100:1','100:1'],['C','100:1','100:1']],ex:'Mọi VRF export RT 100:1 và import RT 100:1: mọi site thấy nhau.'},
   hub:{v:[['Hub','100:1 và 100:9 (xuất 100:1)','nhập 100:2'],['Spoke 1','xuất 100:2','nhập 100:1'],['Spoke 2','xuất 100:2','nhập 100:1']],ex:'Spoke chỉ import RT của hub, hub import RT của spoke: spoke KHÔNG thấy nhau trực tiếp, lưu lượng đi vòng qua hub (cho kiểm soát tập trung bằng tường lửa).'},
   ext:{v:[['Khách A','xuất 100:1, 100:50','nhập 100:1, 100:50'],['Khách B','xuất 100:2, 100:50','nhập 100:2, 100:50'],['Dịch vụ chung','xuất 100:50','nhập 100:1, 100:2']],ex:'RT chung 100:50 chỉ để A và B tới được dịch vụ chung (extranet); A và B không thấy nhau vì không import RT của nhau.'}}[m];
  const nodes=X.v.map((q,k)=>[k,60+k*125,60,q[0]]);let s='';
  if(m==='hub'){s+=li([[185,40],[60,100]],{c:V_('k1'),w:2})+li([[185,40],[310,100]],{c:V_('k1'),w:2});s+=bx(160,22,50,24,'Hub',{fs:9});s+=bx(36,90,50,24,'Spoke 1',{fs:9})+bx(286,90,50,24,'Spoke 2',{fs:9});s+=li([[86,102],[286,102]],{c:V_('cp'),w:1.4,d:'4 3'})+tx(186,96,'không thấy nhau',{fs:7.6,c:V_('cp')});}
  else if(m==='full'){s+=li([[60,100],[310,100]],{c:V_('k1'),w:2})+li([[60,100],[185,40]],{c:V_('k1'),w:2})+li([[185,40],[310,100]],{c:V_('k1'),w:2});s+=bx(160,22,50,24,'Site C',{fs:9})+bx(36,90,50,24,'Site A',{fs:9})+bx(286,90,50,24,'Site B',{fs:9});}
  else{s+=li([[60,90],[185,40]],{c:V_('k1'),w:2})+li([[310,90],[185,40]],{c:V_('k1'),w:2})+li([[60,100],[310,100]],{c:V_('cp'),w:1.4,d:'4 3'})+tx(186,114,'A và B không thấy nhau',{fs:7.6,c:V_('cp')});s+=bx(150,22,70,24,'Dịch vụ chung',{fs:8.6})+bx(36,90,50,24,'Khách A',{fs:9})+bx(286,90,50,24,'Khách B',{fs:9});}
  const T=[['Mô hình RT','Route-target quyết định ai thấy ai. '+X.ex],['Bảng RT của từng VRF','<br>'+X.v.map(q=>`${q[0]}: ${q[1]}; ${q[2]}`).join('<br>')],['Thiết kế','RT là chính sách; đặt tên theo quy ước (ASN:số) và ghi tài liệu. Với số VRF lớn dùng RT constrain để RR chỉ gửi tiền tố cần. Hub-and-spoke hay dùng khi mọi lưu lượng giữa chi nhánh phải qua trung tâm (tường lửa).']];
  return{fig:svgw(372,130,s,'Mô hình Route-Target'),hint:'Chọn mô hình để xem RT của từng VRF và ai thấy ai.',out:prKv(X.v.map(q=>[q[0],q[1]+' | '+q[2]])),info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),tt:'Ví dụ cấu hình RT',tb:tbl(['Mô hình','Quy tắc'],[['Full mesh','Cùng RT xuất và nhập'],['Hub-and-spoke','Hub nhập RT spoke, spoke nhập RT hub'],['Extranet','Thêm RT chung giữa hai nhóm']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
const L3_PTS=[
 ['Thành phần L3VPN (RFC 4364)','VRF (bảng định tuyến riêng cho mỗi khách trên PE), RD (làm tiền tố VPNv4 duy nhất), RT (chính sách nhập xuất), MP-BGP VPNv4/VPNv6 giữa các PE, hai nhãn (vận chuyển và VPN), PE–CE chạy giao thức định tuyến riêng của khách. Lõi (P) không có thông tin VRF.'],
 ['Giao thức PE–CE','eBGP (phổ biến, nhà mạng kiểm soát tốt), OSPF (cần sham-link nếu có đường dự phòng backdoor, DN-bit chống vòng lặp), EIGRP (SoO chống vòng lặp), RIP, tĩnh. Sự cố hay gặp: cùng AS ở hai site eBGP bị chặn bởi AS-path, dùng as-override hoặc allowas-in.'],
 ['Internet access và dịch vụ chung','Truy cập Internet từ VRF: định tuyến tĩnh có từ khóa global, import/export qua RT chung, hoặc dùng VRF Internet riêng. Dịch vụ chung (DNS, giám sát) qua extranet với RT chung. Cẩn thận rò rỉ định tuyến ngoài ý muốn.'],
 ['Inter-AS option A, B, C','Option A: ASBR coi nhau như CE, một giao diện/VRF mỗi VPN (đơn giản, kém mở rộng). Option B: ASBR trao đổi VPNv4 qua eBGP, có nhãn VPN trao đổi. Option C: RR hai miền trao đổi VPNv4 đa chặng, ASBR chỉ trao đổi nhãn tới loopback PE (mở rộng tốt nhưng phức tạp).'],
 ['Xử lý sự cố nhanh','1) show ip route vrf X: đường có không? 2) show bgp vpnv4 unicast all: có bản tin VPNv4 không (RT?). 3) ping vrf X. 4) show mpls forwarding-table: LSP tới next-hop? 5) show ip cef vrf X detail: nhãn đẩy đúng không. Kiểm tra theo thứ tự: PE–CE, MP-BGP, RT, LSP, nhãn VPN.']];
