/* ---------- QoS nhà mạng ---------- */
function qsTun(){const mode=S.ccP1,d=S.ccP2,rm=S.ccP3==='yes';
  const dscp={ef:46,af31:26,af11:10,be:0}[d],tc0={ef:5,af31:3,af11:1,be:0}[d];
  const tc=rm?2:tc0;/* SP đặt lại TC theo lớp dịch vụ khách mua (giả sử lớp 2) */
  const q=t=>['BE','AF1x','Dữ liệu ưu tiên','AF3x','Video','Thoại','Điều khiển','Mạng'][t];
  const dq=ds=>ds>=46?'Thoại (LLQ)':ds>=32?'Video':ds>=24?'Dữ liệu ưu tiên':ds>=8?'Dữ liệu thường':'Best effort';
  const core=q(tc);
  let egressQ,out;if(mode==='uni'){const nd=rm?{0:0,1:10,2:18,3:26,4:34,5:46}[tc]||0:dscp;out=nd;egressQ=dq(nd);}
  else if(mode==='short'){out=dscp;egressQ=dq(dscp);}
  else{out=dscp;egressQ=dq({0:0,1:10,2:18,3:26,4:34,5:46}[tc]||0);}
  return{mode,dscp,tc,tc0,rm,core,egressQ,out};}
function qsTunR(i){const D=qsTun(),c=clamp(i,0,2);const nm={uni:'Uniform',short:'Short-pipe',pipe:'Pipe'}[D.mode];
  let s='';const bxs=[['CE vào',`DSCP ${D.dscp}`],['PE1 vào',`TC ${D.tc}`+(D.rm?' (SP đặt lại)':'')],['Lõi',`TC ${D.tc} → ${D.core}`],['PE2 ra',D.egressQ],['Ra CE',`DSCP ${D.out}`]];
  bxs.forEach((b,k)=>{const x=6+k*72;s+=bx(x,40,66,34,b[0],{sub:b[1],fs:8.4});if(k)s+=li([[x-6,57],[x,57]],{c:V_('ink'),w:1.6});});
  s+=tx(186,100,`Mô hình ${nm}: lõi xếp hàng theo TC ${D.tc} (${D.core}); PE ra xếp hàng theo ${D.egressQ}`,{fs:8.2,b:1,c:V_('ink')});
  const T=[['Ba mô hình đường hầm DiffServ',`RFC 3270 định nghĩa: Uniform (nhà mạng và khách cùng một miền DiffServ; TC sao chép ngược về DSCP ở egress, nên nhà mạng có thể đổi DSCP của khách). Short-pipe (khách giữ nguyên DSCP, PE ra xếp hàng theo DSCP gốc của khách). Pipe (khách giữ DSCP, PE ra xếp hàng theo TC của nhà mạng). Mô hình đang chọn: ${nm}.`],
   ['Kết quả với tham số này',`DSCP vào ${D.dscp} (${D.tc0 ? 'ánh xạ thường gặp sang TC '+D.tc0 : 'TC 0'}). ${D.rm?`Nhà mạng đặt lại TC thành ${D.tc} theo lớp dịch vụ khách mua.`:`TC được suy ra từ DSCP: ${D.tc}.`} Trong lõi chỉ nhìn TC, lớp ${D.core}. Ở PE ra: xếp hàng "${D.egressQ}"; DSCP trả về khách là ${D.out}${D.mode==='uni'&&D.rm?' (bị đổi vì Uniform)':''}.`],
   ['Chọn mô hình nào',`Short-pipe phổ biến với dịch vụ VPN doanh nghiệp: nhà mạng không đụng DSCP của khách, nhưng ở egress vẫn tôn trọng chính sách của khách. Pipe cho nhà mạng kiểm soát hàng đợi tới tận PE ra, hữu ích khi phải thực thi SLA ở chặng cuối. Uniform khi khách và nhà mạng cùng tổ chức. Ánh xạ DSCP–TC trong bài là ví dụ phổ biến, không phải chuẩn bắt buộc (kiểm tra thiết kế của bạn).`]];
  return{fig:svgw(372,112,s,'DiffServ qua MPLS'),hint:'Đổi mô hình đường hầm, DSCP của khách và việc nhà mạng đặt lại TC.',out:prKv([['Mô hình',nm],['DSCP khách',D.dscp],['TC trong lõi',D.tc+' ('+D.core+')'],['Xếp hàng ở PE ra',D.egressQ],['DSCP trả về khách',D.out]]),info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),tt:'So sánh ba mô hình',tb:tbl(['Mô hình','TC ở egress','DSCP khách','Xếp hàng ở PE ra'],[['Uniform','Sao chép về DSCP','Có thể bị đổi','Theo TC/DSCP mới'],['Short-pipe','Bỏ qua','Giữ nguyên','Theo DSCP gốc của khách'],['Pipe','Dùng để xếp hàng','Giữ nguyên','Theo TC của nhà mạng']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
/* HQoS: nước chảy (water-filling) */
function qsHq(){const par=+S.ccP1,pri=+S.ccP2,v=+S.ccP3,d=+S.ccP4,b=+S.ccP5;/* tải đưa vào theo Mb/s */
  const cls=[{n:'Thoại (ưu tiên)',pri:1,off:pri},{n:'Video',w:35,off:v},{n:'Dữ liệu doanh nghiệp',w:45,off:d},{n:'Best effort',w:20,off:b}];
  let rem=par;const al={};cls[0].al=Math.min(cls[0].off,par*0.25);rem-=cls[0].al;
  let act=cls.slice(1);act.forEach(x=>x.al=0);let loop=0;
  while(rem>1e-6&&act.length&&loop++<10){const tw=act.reduce((a,x)=>a+x.w,0);let used=0;const next=[];act.forEach(x=>{const sh=rem*x.w/tw,need=x.off-x.al,g=Math.min(sh,need);x.al+=g;used+=g;if(x.off-x.al>1e-6)next.push(x);});rem-=used;act=next;if(used<1e-9)break;}
  return{par,cls,rem:Math.max(0,rem)};}
function qsHqR(i){const D=qsHq(),c=clamp(i,0,2);const fm=x=>prF1(x,1)+' Mb/s';
  let s='';const mx=Math.max(D.par,...D.cls.map(x=>x.off),1);
  D.cls.forEach((x,j)=>{const y=8+j*26,wo=x.off/mx*220,wa=x.al/mx*220;s+=tx(4,y+11,x.n,{a:'start',fs:7.8,c:V_('ink')})+`<rect x="116" y="${y}" width="${wo.toFixed(1)}" height="16" style="fill:none;stroke:${V_('line')}"/><rect x="116" y="${y}" width="${wa.toFixed(1)}" height="16" style="fill:${x.al+1e-6>=x.off?V_('k1'):V_('cp')}"/>`+tx(120+Math.max(wo,wa),y+12,fm(x.al)+(x.off-x.al>0.05?' / '+fm(x.off):''),{a:'start',fs:7.6,c:V_('ink')});});
  s+=tx(186,118,`Bộ định hình cha ${fm(D.par)}; còn dư ${fm(D.rem)}`,{fs:8.6,b:1,c:V_('ink')});
  const dr=D.cls.filter(x=>x.off-x.al>0.05);
  const T=[['Chính sách phân cấp',`HQoS (Hierarchical QoS): chính sách cha định hình (shape) cả liên kết khách ở ${fm(D.par)} (tốc độ thuê, thường thấp hơn tốc độ cổng), chính sách con chia theo lớp: thoại dùng hàng đợi ưu tiên (LLQ) có ngưỡng policing, các lớp còn lại chia theo trọng số CBWFQ (35/45/20). Cổng vật lý có thể 10 Gb/s nhưng khách chỉ mua ${fm(D.par)}: bộ định hình cha khớp tốc độ bán.`],
   ['Kết quả phân bổ',`Thoại được ${fm(D.cls[0].al)} (chặn ở ngưỡng 25 % tốc độ cha, tránh đói các lớp khác). Phần còn lại chia theo trọng số: lớp nào dùng ít hơn phần mình thì phần dư chia cho lớp khác theo trọng số (water-filling). ${dr.length?'Lớp bị thiếu: '+dr.map(x=>x.n).join(', ')+' (tắc nghẽn, gói bị rớt hoặc trễ hàng đợi).':'Không lớp nào bị rớt.'}`],
   ['Điều chỉnh thực tế',`Mô hình này lý tưởng hoá (không có độ trễ hàng đợi, burst, kích thước gói). Thiết kế thật: đặt WRED trong lớp dữ liệu để tránh đồng bộ TCP, giới hạn thoại 20 đến 33 % tốc độ liên kết (khuyến nghị thường gặp để thoại không lấn át), dùng buffer đủ cho shaper (Bc, Be). Các số trong bài là ví dụ, không phải cấu hình khuyến nghị.`]];
  return{fig:svgw(372,128,s,'Phân bổ băng thông HQoS'),hint:'Đổi tốc độ thuê và tải từng lớp (Mb/s) để xem ai bị thiếu.',out:prKv(D.cls.map(x=>[x.n,fm(x.al)+' (tải '+fm(x.off)+')']).concat([['Tổng',fm(D.cls.reduce((a,x)=>a+x.al,0))+' / '+fm(D.par)]])),info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),tt:'Policing và shaping',tb:tbl(['Mục','Policing','Shaping'],[['Hành động quá mức','Rớt hoặc đánh dấu lại','Đệm rồi gửi dần'],['Độ trễ','Không thêm','Thêm trễ hàng đợi'],['Thường dùng','Hướng vào (ingress)','Hướng ra (egress), khớp tốc độ thuê'],['Ảnh hưởng TCP','Rớt gây giảm cửa sổ','Mượt hơn']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
const QS_PTS=[
 ['Các lớp dịch vụ nhà mạng','Thường 4 đến 6 lớp: thoại/thời gian thực (EF), video (AF4x), dữ liệu quan trọng (AF3x, AF2x), điều khiển mạng (CS6), best effort. Nhà mạng bán theo lớp và tốc độ cam kết (CIR); phải ghi rõ SLA: độ trễ, jitter, mất gói theo lớp (số thực tế do nhà mạng định, các ví dụ khuyến nghị phổ biến là thoại một chiều dưới 150 ms theo ITU-T G.114, jitter dưới 30 ms, mất gói dưới 1 %).'],
 ['Thực thi ở biên và lõi','Biên (PE vào): phân loại (theo DSCP, ACL, VLAN CoS), đánh dấu TC, policing theo CIR. Lõi: chỉ xếp hàng theo TC, không phân loại lại; ít trạng thái. Biên ra: shaping và hàng đợi theo cam kết (HQoS). Giữ nhất quán ánh xạ TC ↔ lớp trong toàn mạng.'],
 ['LLQ, CBWFQ, WRED','LLQ: hàng đợi ưu tiên nghiêm ngặt cho thoại, có policer chống đói. CBWFQ: chia băng thông theo tỷ lệ cho lớp còn lại. WRED: rớt ngẫu nhiên sớm theo ngưỡng của từng DSCP, tránh đồng bộ hoá TCP. Tail drop khi hàng đợi đầy là cơ chế mặc định.'],
 ['MPLS-TE và QoS','Kỹ thuật lưu lượng và QoS bổ trợ nhau: DS-TE (RFC 4124) cho dự trữ băng thông theo lớp. Với SR, bộ điều khiển phân bổ lưu lượng lên đường có độ trễ thấp bằng chính sách theo màu; QoS vẫn thực thi ở hàng đợi từng chặng.'],
 ['Quan sát','Kiểm tra bằng show policy-map interface (số gói khớp, rớt, hàng đợi), show mpls forwarding để đảm bảo nhãn; đo chủ động bằng IP SLA/TWAMP (RFC 5357) hoặc STAMP (RFC 8762) để so với SLA theo lớp.']];
