/* ---------- Tự động hoá và giám sát nhà mạng ---------- */
function saBfd(){const tx_=+S.ccP1,rx=+S.ccP2,m=+S.ccP3,n=+S.ccP4;/* tx: DesiredMinTx cục bộ; rx: RequiredMinRx từ xa */
  const act=Math.max(tx_,rx),det=m*act;const pps=n*1000/act;return{tx_,rx,m,n,act,det,pps};}
function saBfdR(i){const D=saBfd(),c=clamp(i,0,2);
  const cmp=[['BFD',D.det],['Hello IGP nhanh (1 s × 3)',3000],['Hello IGP mặc định (OSPF 10 s × 4)',40000],['Hold-time BGP mặc định (180 s)',180000]];
  const mx=Math.log10(Math.max(...cmp.map(x=>x[1]))+1);let s='';
  cmp.forEach((x,j)=>{const y=10+j*28,w=Math.max(3,Math.log10(x[1]+1)/mx*210),fm=x[1]>=1000?prF1(x[1]/1000,x[1]>=10000?0:1)+' s':x[1]+' ms';s+=tx(4,y+12,x[0],{a:'start',fs:7.8,c:V_('ink')})+`<rect x="150" y="${y}" width="${w.toFixed(1)}" height="16" rx="3" style="fill:${j===0?V_('k1'):V_('muted')}"/>`+tx(154+w,y+12,fm,{a:'start',fs:8,c:V_('ink')});});
  s+=tx(186,126,'Thang logarit: thời gian phát hiện lỗi liên kết',{fs:7.2,c:V_('muted')});
  const T=[['BFD thương lượng thời gian',`BFD (RFC 5880) gửi gói điều khiển rất nhẹ qua UDP 3784 (một chặng, RFC 5881), 4784 (nhiều chặng, RFC 5883) hoặc 3785 (chế độ echo). Mỗi đầu công bố DesiredMinTxInterval và RequiredMinRxInterval; khoảng gửi thực tế là MAX của (Tx của mình, Rx yêu cầu của đầu kia) = max(${D.tx_}, ${D.rx}) = ${D.act} ms. Thời gian phát hiện = hệ số nhân × khoảng nhận = ${D.m} × ${D.act} = ${D.det} ms.`],
   ['Chi phí',`Với ${D.n} phiên BFD ở ${D.act} ms, router phải xử lý khoảng ${prF1(D.pps,0)} gói mỗi giây (chỉ tính một chiều). Phần cứng hiện đại chuyển BFD xuống card (offload) để chịu hàng nghìn phiên; phần mềm cũ chịu rất ít. Đặt khoảng quá nhỏ làm cờ chập chờn (flap) khi CPU bận. Giá trị phổ biến: 50 ms × 3 (phát hiện 150 ms) cho liên kết lõi; 300 ms × 3 cho liên kết kém ổn định; echo mode giảm tải cho đầu kia.`],
   ['Dùng BFD với giao thức nào',`BFD không tự tính đường: nó báo “liên kết chết” cho các giao thức (IS-IS, OSPF, BGP, static route, MPLS-TE, PW) để chúng hội tụ ngay thay vì chờ hello và hold-time. BFD cho LAG/bundle (BoB, RFC 7130) phát hiện lỗi từng thành viên. Kết hợp TI-LFA để chuyển trong mili giây. Số liệu trên là ước tính; thực tế còn cộng thời gian xử lý của giao thức.`]];
  return{fig:svgw(372,134,s,'Thời gian phát hiện lỗi (thang logarit)'),hint:'Đổi khoảng gửi, khoảng nhận yêu cầu của đầu kia, hệ số nhân và số phiên.',out:prKv([['Khoảng thực tế',D.act+' ms'],['Hệ số nhân',D.m],['Thời gian phát hiện',D.det+' ms'],['Tải gói/giây',prF1(D.pps,0)]]),info:ccInfo(T[c][0],T[c][1],T.map(q=>q[0]),c),tt:'Cổng và RFC',tb:tbl(['Chế độ','UDP đích','RFC'],[['Một chặng','3784','5881'],['Nhiều chặng','4784','5883'],['Echo','3785','5880'],['BFD cho LAG (micro-BFD)','6784','7130']]),cap:`${T[c][0]}: ${first(T[c][1])}`};}
function saOam(){const f=S.ccP1,mode=S.ccP2,st=[];const nodes=['PE1','P1','P2','PE2'];
  st.push({f:0,t:1,s:'Echo Request: nhãn LSP + FEC stack',m:'PE1 gửi MPLS Echo Request',p:'UDP 3503 · đích 127.0.0.1 · Router Alert',k:'ctl',d:'LSP ping (RFC 8029) gửi gói UDP (cổng 3503) tới địa chỉ 127.x.x.x, có Router Alert, đẩy NHÃN của LSP cần thử, nên đi chính xác như dữ liệu. TLV Target FEC Stack mô tả FEC mà người gửi tin LSP này phục vụ (ví dụ LDP IPv4 prefix 10.0.0.4/32 hoặc SR Node-SID).',fl:[['UDP','3503'],['IP đích','127.0.0.1 (loopback)'],['TLV','Target FEC Stack, Downstream Mapping']]});
  if(mode==='tr'){
    st.push({f:0,t:1,s:'TTL = 1',m:'Traceroute: TTL = 1',p:'MPLS',k:'ctl',d:'Với traceroute LSP, TTL nhãn đặt lần lượt 1, 2, 3... Router tại chặng TTL hết hạn trả lời Echo Reply với return code và thông tin downstream (nhãn ra, giao diện) để PE1 kiểm tra từng chặng có khớp FEC không.'});
    st.push({f:1,t:0,s:'Echo Reply: mã 8 (swapped at stack-depth) + DS map',m:'P1 trả lời (chặng 1)',p:'UDP 3503',k:'ctl',d:'Return code 8: “Label switched at stack-depth”: P1 chuyển tiếp theo nhãn và trả thông tin nhãn ra / giao diện / địa chỉ chặng sau. PE1 so với kỳ vọng.'});
    st.push({f:0,t:2,s:'TTL = 2',m:'Traceroute: TTL = 2',p:'MPLS',k:'ctl',d:'Tiếp tục với TTL 2 để chạm P2.'});
    if(f==='nolabel')return{st:st.concat([{f:2,t:0,s:'Echo Reply: mã 11 (no label entry)',m:'P2 không có nhãn',p:'UDP 3503',k:'rt',bad:1,d:'P2 trả return code 11 “No label entry”: P2 KHÔNG có mục LFIB cho nhãn mà P1 đã gửi (LSP bị đứt tại P2). Đây đúng là vị trí lỗi cần tìm. Nguyên nhân thường gặp: LDP/SR chưa quảng bá, ACL chặn phiên LDP, hoặc LSP đã thay đổi sau hội tụ.',chk:['show mpls forwarding-table tại P2','show mpls ldp bindings','Kiểm tra IGP và phiên LDP']}])};
    if(f==='fec')return{st:st.concat([{f:2,t:0,s:'Echo Reply: mã 10 (FEC mismatch)',m:'P2 báo FEC không khớp',p:'UDP 3503',k:'rt',bad:1,d:'Return code 10 “Mapping for this FEC is not the given label at stack-depth”: nhãn nhận được tại P2 không ứng với FEC mà PE1 khai báo (nhãn bị lệch, thường do cấu hình SRGB khác nhau hoặc nhãn cũ chưa cập nhật).',chk:['So sánh SRGB hai bên','show mpls forwarding để đối chiếu nhãn–FEC']}])};
    st.push({f:2,t:0,s:'Echo Reply: mã 8 + DS map',m:'P2 trả lời (chặng 2)',p:'UDP 3503',k:'ctl',d:'P2 chuyển tiếp bình thường.'});
    st.push({f:0,t:3,s:'TTL = 3',m:'Traceroute: TTL = 3',p:'MPLS',k:'ctl',d:'Chạm PE2, đích của LSP.'});
    st.push({f:3,t:0,s:'Echo Reply: mã 3 (egress for FEC)',m:'PE2 là egress',p:'UDP 3503',k:'sync',d:'Return code 3: “Replying router is an egress for the FEC at stack-depth”. LSP thông suốt và hợp lệ từ đầu đến cuối. Có thể đo RTT từng chặng.'});
    return{st};}
  if(f==='nolabel')return{st:st.concat([{f:2,t:0,s:'Echo Reply: mã 11 (no label entry)',m:'P2 không có nhãn',p:'UDP 3503',k:'rt',bad:1,d:'Gói LSP ping bị rớt hoặc P2 trả return code 11: không có mục nhãn. Ping không nói đứt ở đâu; muốn xác định chặng lỗi phải dùng traceroute LSP.',chk:['Chạy traceroute mpls để định vị','Kiểm tra bảng nhãn từng chặng']}])};
  if(f==='fec')return{st:st.concat([{f:3,t:0,s:'Echo Reply: mã 10 (FEC mismatch)',m:'PE2: FEC không khớp',p:'UDP 3503',k:'rt',bad:1,d:'PE2 nhận Echo Request nhưng FEC trong gói không ứng với nhãn nhận được: mã 10. Cấu hình hoặc nhãn lệch giữa các nút.',chk:['Đối chiếu bảng nhãn đầu–cuối']}])};
  st.push({f:1,t:2,s:'P1, P2 chuyển tiếp theo nhãn',m:'Chuyển tiếp trong lõi',p:'MPLS',k:'ctl',d:'Gói đi theo đúng đường dữ liệu qua các LSR. Không LSR nào kiểm tra nội dung nếu TTL chưa hết.'});
  st.push({f:3,t:0,s:'Echo Reply: mã 3 (egress), qua IP',m:'PE2 trả lời',p:'UDP 3503',k:'sync',d:'PE2 xác nhận là egress của FEC (mã 3) và gửi Echo Reply bằng IP thường (hoặc LSP ngược tuỳ cấu hình reply mode). PE1 nhận Reply: LSP hoạt động ở mặt phẳng dữ liệu, không chỉ ở mặt phẳng điều khiển.',fl:[['Return code','3: replying router is an egress'],['Reply mode','2: reply via an IPv4 UDP packet (mặc định)']]});
  return{st};}
function saOamR(i){const B=saOam();
  return npLad(B,i,B.nodes||['PE1','P1','P2','PE2'],{rows:(c,s)=>[['Công cụ',S.ccP2==='tr'?'LSP traceroute':'LSP ping'],['Lỗi giả lập',{none:'Không',nolabel:'Thiếu nhãn ở P2',fec:'FEC không khớp'}[S.ccP1]],['Bước',`${c+1} trên ${B.st.length}`]],
    tt:'Mã trả về chính (RFC 8029)',tb:tbl(['Mã','Ý nghĩa'],[[3,'Router trả lời là egress của FEC'],[8,'Chuyển nhãn tại độ sâu ngăn xếp đã nêu'],[10,'Ánh xạ FEC không khớp nhãn'],[11,'Không có mục nhãn'],[2,'Có router không hiểu TLV/ yêu cầu']])});}
const SA_PTS=[
 ['Mô hình điều khiển nhà mạng','Bộ điều khiển SDN hoặc điều phối (orchestrator) giữ trạng thái dịch vụ, thiết bị giữ trạng thái chuyển tiếp. Mô hình dịch vụ (service model) YANG biểu diễn ý định (ví dụ L3VPN) và NSO (Network Services Orchestrator) hoặc tương đương dịch thành cấu hình thiết bị cho mọi hãng; giao dịch hai pha, rollback cả dịch vụ nếu một thiết bị lỗi. NETCONF/YANG và gNMI/gRPC là giao diện chính.'],
 ['Mô hình YANG','Ba lớp: mô hình dịch vụ (L3SM RFC 8299, L2SM RFC 8466), mô hình mạng (RFC 8345 topo), mô hình thiết bị (IETF, OpenConfig, riêng của hãng). OpenConfig do nhà vận hành định nghĩa, trung lập hãng; thiết bị có thể hỗ trợ một phần. Kiểm tra bằng pyang hoặc yanglint, duyệt cây bằng pyang -f tree.'],
 ['Telemetry và đo hiệu năng','Telemetry hướng mô hình (gRPC/gNMI) thay SNMP; BMP cho BGP; IPFIX cho luồng. Đo chủ động: TWAMP (RFC 5357) và STAMP (RFC 8762) cho trễ, jitter, mất gói; SR Performance Measurement tự đo độ trễ liên kết gắn vào IGP để Flex-Algo chọn đường. Alert dựa trên SLA từng lớp dịch vụ.'],
 ['Mô hình cam kết (commit) của IOS-XR','IOS-XR dùng cấu hình hai giai đoạn: gõ lệnh vào “target configuration” (candidate), kiểm tra bằng show configuration, rồi commit; show configuration commit changes xem thay đổi đã áp dụng; rollback configuration last 1 hoàn tác; commit confirmed trong khoảng thời gian tự quay lại nếu không xác nhận. Giúp thay đổi an toàn hơn so với IOS-XE kiểu áp dụng ngay (kiểm tra theo phiên bản).'],
 ['Chuỗi công cụ tự động hoá','Python (ncclient, netmiko), Ansible (module cho từng hãng), Terraform, CI/CD cho cấu hình (lưu Git, kiểm thử bằng mô phỏng như CML hay Containerlab, rồi triển khai theo giai đoạn). Quy tắc vàng: có môi trường thử, có rollback, thay đổi nhỏ, ghi nhật ký, và phân quyền.']];
