/* ====================== Trắc nghiệm và phiếu lệnh: chuyển mạch, VPN, bảo mật, không dây ====================== */
CCT.fhrp.quiz=[
 ['Mặc định, độ ưu tiên HSRP và việc chiếm quyền (preempt) như thế nào?','Ưu tiên 100; preempt TẮT','Ưu tiên 100; preempt BẬT','Ưu tiên 255; preempt BẬT','Ưu tiên 0; preempt TẮT','HSRP: priority 100 mặc định, preempt không bật nên router ưu tiên cao hơn vào sau không tự chiếm active. VRRP thì preempt bật mặc định.'],
 ['Hello và hold time mặc định của HSRP là bao nhiêu?','3 giây và 10 giây','5 giây và 15 giây','1 giây và 3 giây','10 giây và 40 giây','HSRP hello 3 s, hold 10 s. VRRP quảng bá mỗi 1 giây.'],
 ['Địa chỉ MAC ảo của nhóm HSRP version 1 có dạng nào?','0000.0C07.ACxx (xx là số nhóm)','0000.5E00.01xx','0007.B400.xxyy','AAAA.BBBB.xxxx','0000.0C07.ACxx cho HSRPv1; HSRPv2 dùng 0000.0C9F.Fxxx. VRRP dùng 0000.5E00.01xx; GLBP dùng 0007.B400.xxyy.'],
 ['Điểm khác biệt chính của GLBP so với HSRP là gì?','Cho phép nhiều router cùng chuyển tiếp lưu lượng (cân bằng tải) qua nhiều MAC ảo','Dùng IP giao thức 112','Không có bầu chọn','Chỉ chạy IPv6','GLBP có AVG trả lời ARP bằng các MAC ảo khác nhau của các AVF, nên các máy khách chia tải giữa nhiều gateway.'],
 ['BPDU Guard làm gì khi nhận BPDU trên cổng PortFast?','Đưa cổng vào trạng thái err-disable','Chuyển cổng sang root','Bỏ qua BPDU','Tăng chi phí cổng','BPDU Guard bảo vệ cổng biên: bất kỳ BPDU nào đến sẽ đặt cổng vào err-disable để tránh vòng lặp hoặc switch lạ.'],
 ['Root Guard khác Loop Guard thế nào?','Root Guard ngăn cổng nhận BPDU tốt hơn, giữ vai trò root; Loop Guard ngăn cổng chuyển sang forwarding khi mất BPDU','Hai tính năng giống nhau','Root Guard chạy trên cổng biên, Loop Guard chạy trên cổng access','Loop Guard ngăn mọi BPDU','Root Guard đặt cổng vào trạng thái root-inconsistent khi nhận BPDU cao hơn; Loop Guard tránh cổng không nhận BPDU (do liên kết một chiều) chuyển nhầm sang forwarding.'],
 ['EtherChannel LACP dùng chuẩn nào và chế độ nào chủ động đàm phán?','IEEE 802.3ad; chế độ active','Cisco độc quyền; chế độ desirable','IEEE 802.1Q; chế độ auto','IEEE 802.1X; chế độ on','LACP (802.3ad/802.1AX) có active (chủ động) và passive. PAgP là giao thức riêng của Cisco, có desirable và auto.']];
CCT.fhrp.cheat=[
 {g:'HSRP, STP bảo vệ',d:'Lệnh IOS-XE.',rows:[
  ['HSRP','interface vlan 10\n standby version 2\n standby 10 ip 10.1.10.1\n standby 10 priority 110\n standby 10 preempt','Cặp gateway dự phòng'],
  ['Kiểm tra HSRP','show standby brief','Active, Standby, địa chỉ ảo'],
  ['VRRP','vrrp 10 ip 10.1.10.1\nvrrp 10 priority 110','Chuẩn mở RFC 5798'],
  ['PortFast + BPDU Guard','spanning-tree portfast\nspanning-tree bpduguard enable','Trên cổng access đầu cuối'],
  ['Root Guard','spanning-tree guard root','Trên cổng hướng xuống switch không được làm root'],
  ['Loop Guard','spanning-tree guard loop','Trên cổng không định danh (cổng root, alternate)'],
  ['Kiểm tra STP','show spanning-tree vlan 10','Root, vai trò và trạng thái cổng'],
  ['LACP','channel-group 1 mode active','Đặt trên các cổng thành viên']]}];
CCT.qos.quiz=[
 ['Giá trị DSCP của lớp EF thường dùng cho thoại là bao nhiêu?','46','34','26','10','EF = 46 (nhị phân 101110). AF41 = 34, AF31 = 26, AF11 = 10. CS6 = 48.'],
 ['Trong ký hiệu AFxy, y chỉ điều gì?','Mức ưu tiên rớt gói (drop precedence)','Lớp dịch vụ','Vòng đời gói','Hệ số cân bằng tải','AFxy: x (1–4) là lớp, y (1–3) là mức ưu tiên rớt; DSCP = 8x + 2y.'],
 ['Điểm khác nhau chính giữa policing và shaping là gì?','Policing loại bỏ hoặc đánh dấu lại phần vượt; shaping đệm lại và gửi dần','Shaping loại bỏ phần vượt, policing đệm','Cả hai đều đệm','Cả hai chỉ dùng trên ingress','Policing không thêm trễ nhưng gây rớt; shaping làm mượt luồng bằng bộ đệm, thêm trễ.'],
 ['LLQ (Low Latency Queueing) kết hợp những gì?','Hàng đợi ưu tiên nghiêm ngặt cho thoại cộng CBWFQ cho các lớp khác','Hai hàng đợi FIFO','WRED và policing','Chỉ shaping','LLQ thêm hàng đợi ưu tiên (priority) vào CBWFQ; có policer ngầm để tránh đói các lớp khác.'],
 ['Công thức nào cho khoảng thời gian Tc của bộ định hình?','Tc = Bc / CIR','Tc = CIR / Bc','Tc = Be × CIR','Tc = Bc × CIR','Bc (bit mỗi khoảng) chia cho CIR (bit mỗi giây) cho thời lượng khoảng Tc. Ví dụ Bc 8000 bit, CIR 64.000 b/s thì Tc = 125 ms.'],
 ['WRED giúp ích như thế nào trong hàng đợi dữ liệu?','Rớt ngẫu nhiên sớm theo ngưỡng, tránh đồng bộ hoá TCP','Đảm bảo độ trễ cố định','Mã hoá lưu lượng','Tăng MTU','Khi hàng đợi bắt đầu đầy, WRED rớt ngẫu nhiên có xác suất tăng dần theo DSCP, làm các luồng TCP giảm tốc không đồng loạt.'],
 ['Ranh giới tin cậy (trust boundary) nên đặt ở đâu?','Càng gần thiết bị cuối đáng tin cậy càng tốt, thường ở switch truy cập','Ở lõi mạng','Ở ISP','Ở máy chủ DNS','Đánh dấu ở gần nguồn, rồi mọi thiết bị phía sau tin nhãn đó. Máy khách tuỳ tiện không nên được tin nhãn QoS.']];
