/* ====================== Ghép vào thẻ Truyền dẫn ====================== */
CCORD.forEach(k=>{if(k==='subx')CCT.subx.cheat=CCT.sub.cheat;});
(function(){const mk=(arr,n)=>{const it={};arr.forEach(k=>{it['c_'+k]=ccItem(k);});return{n,items:it};};
  const V=GX.tx.views;
  V.ccO=mk(['over','mock'],'CCNA: tổng quan và đề thi thử');
  V.ccO.items.c_mock.cnt=()=>{ccSync();return Math.max(1,ccMockList().length);};
  V.ccF=mk(['osi','sub','subx'],'CCNA: nền tảng mạng và địa chỉ IP');
  V.ccL=mk(['vlan','trunk','stp','ech'],'CCNA: chuyển mạch lớp 2');
  V.ccI=mk(['route','ospf','nat','dhcp','mgmt'],'CCNA: định tuyến và dịch vụ IP');
  V.ccS=mk(['acl','psec','wlan','auto'],'CCNA: bảo mật, không dây, tự động hoá');
  GX.tx.note=()=>String(S.txI).startsWith('c_')?CCNOTE:TXNOTE;
  const L=GX.tx.lead;GX.tx.lead=()=>L()+' Có thêm phần CCNA (Cisco 200-301): OSI/TCP-IP, chia subnet có bài tập chấm điểm, VLAN, trunk, STP, EtherChannel, định tuyến tĩnh và OSPF, NAT, DHCP, NTP, SNMP, Syslog, ACL, port security, Wi-Fi, REST/JSON/Ansible; mỗi chủ đề có mô phỏng, câu hỏi trắc nghiệm và phiếu lệnh.';
})();

/* ====================== CCNP: tổng quan, đề thi thử, ghép vào thẻ Truyền dẫn ====================== */
const NPO=NPALL.filter(k=>CCT[k]);
Object.assign(S,{ccNk:{seed:0}});
Object.assign(CCV,NPVIEW);
const NPEX=[['encor','ENCOR'],['enarsi','ENARSI'],['spcor','SPCOR']];
const npHas=(T,e)=>(T.np||[]).some(p=>p[0]===e);
function npOver(){
  const rows=NPO.map(k=>{const T=CCT[k],sc=ccScore(ccQuizList(T)),nc=T.cheat?T.cheat.reduce((a,g)=>a+g.rows.length,0):0;
    return[`<b>${esc(T.n)}</b>`,NPEX.filter(e=>npHas(T,e[0])).map(e=>e[1]).join(', '),sc.a?`${sc.c} đúng / ${sc.a} đã làm / ${sc.n}`:`0 / ${sc.n}`,nc,ccGo(k,'sim','Mô phỏng')+' '+ccGo(k,'quiz','Trắc nghiệm')+' '+ccGo(k,'cheat','Phiếu lệnh')];});
  const tot=NPO.reduce((a,k)=>{const s=ccScore(ccQuizList(CCT[k]));return[a[0]+s.a,a[1]+s.c,a[2]+s.n];},[0,0,0]);
  const dom=[];NPEX.forEach(e=>{Object.entries(NPD[e[0]][1]).forEach(([d,x])=>{const ts=NPO.filter(k=>(CCT[k].np||[]).some(p=>p[0]===e[0]&&p[1]==+d));dom.push([`<b>${NPD[e[0]][0]}</b>`,esc(x[0]),x[1]?'~'+x[1]+' %':'không ghi',ts.map(k=>esc(CCT[k].n.split(':')[0])).join('; ')||'—']);});});
  return{fig:`<div class="scroll"><table>${tbl(['Chủ đề','Kỳ thi','Trắc nghiệm','Số lệnh','Mở'],rows)}</table></div>`,hint:'Bấm Mô phỏng, Trắc nghiệm hoặc Phiếu lệnh ở từng hàng để vào chủ đề.',
    out:prKv([['Số chủ đề CCNP',NPO.length],['Câu đã làm',tot[0]+' trên '+tot[2]],['Trả lời đúng',tot[1]],['Kỳ thi liên quan','ENCOR, ENARSI, SPCOR']]),
    info:`<h3>Phần CCNP: Enterprise và Service Provider</h3><p>Mỗi chủ đề có ba chế độ giống phần CCNA: <b>Mô phỏng</b> (có tham số để đổi), <b>Trắc nghiệm</b> và <b>Phiếu lệnh</b>. Kết quả trắc nghiệm lưu trong trình duyệt của bạn. Theo mô hình chứng chỉ CCNP của Cisco (ghi theo trí nhớ, hãy đối chiếu trang chính thức): CCNP Enterprise gồm kỳ thi lõi ENCOR 350-401 cộng một kỳ thi chuyên sâu (ENARSI 300-410 là một lựa chọn về định tuyến và dịch vụ); CCNP Service Provider gồm kỳ thi lõi SPCOR 350-501 cộng một kỳ thi chuyên sâu. Trang này tập trung vào ENCOR, ENARSI và SPCOR. Mô phỏng không phải trình giả lập router: đầu ra là kịch bản minh họa tự soạn.</p>`,
    tt:'Các miền kiến thức của ba kỳ thi (tên và tỷ trọng ghi theo trí nhớ, hãy đối chiếu trang chính thức của Cisco)',tb:tbl(['Kỳ thi','Miền','Tỷ trọng','Chủ đề trong trang này'],dom),cap:`Tổng quan CCNP: ${NPO.length} chủ đề cho ENCOR, ENARSI, SPCOR; mỗi chủ đề có mô phỏng, trắc nghiệm và phiếu lệnh.`};}
ccReg('npover',{n:'Tổng quan CCNP và tiến độ',spec:'Cisco ENCOR 350-401, ENARSI 300-410, SPCOR 350-501 (ghi theo trí nhớ)',solo:true,steps:()=>1,sim:()=>npOver(),idx:'CCNP tổng quan Enterprise Service Provider ENCOR ENARSI SPCOR blueprint tiến độ Cisco Certified Network Professional'});
function npMockList(){const seed=S.ccNk.seed,ex=String(S.ccP2||'all'),pool=[];
  NPO.forEach(k=>{const T=CCT[k];if(ex!=='all'&&!npHas(T,ex))return;(T.quiz||[]).forEach((q,j)=>pool.push({q,t:k,src:k+'#'+j}));});
  const r=ccRng(ccH('npmock'+seed+'|'+ex)),a=pool.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}
  const n=Math.min(Math.max(+S.ccP1||20,1),a.length);return a.slice(0,n).map(x=>({q:x.q,t:x.t,key:'n'+seed+'.'+x.src}));}
function npMockR(i){const list=npMockList(),by={};if(!list.length)return{fig:'<p class="note">Chưa có câu hỏi nào trong phạm vi đã chọn.</p>',out:'',info:'',hint:'',cap:'Đề thi thử CCNP'};list.forEach(x=>{const b=by[x.t]||(by[x.t]={n:0,a:0,c:0});b.n++;const v=S.ccA[x.key];if(v!==undefined){b.a++;if(v===0)b.c++;}});
  const rows=Object.keys(by).map(t=>[esc(CCT[t].n.split(':')[0]),by[t].n,by[t].a,by[t].a?Math.round(by[t].c/by[t].a*100)+' %':'—']);
  const sc=ccScore(list),done=sc.a===list.length;
  return ccQuizView(list,i,{title:'Đề thi thử CCNP số '+(S.ccNk.seed+1),reset:'npmock',resetLabel:'Làm lại đề này',extra:' '+ccBtn('data-ccx="npmock"','Đề mới',1),tag:cur=>esc(CCT[cur.t].n.split(':')[0]),
    more:`<h3>Kết quả theo chủ đề</h3><div class="scroll"><table>${tbl(['Chủ đề','Số câu','Đã làm','Tỷ lệ đúng'],rows)}</table></div><p class="note">${done?'Đã hết đề. Chủ đề có tỷ lệ thấp nhất là chỗ cần ôn trước. ':''}Đây là bộ câu tự soạn để luyện, không phải đề thi thật; điểm đạt của kỳ thi Cisco do Cisco quy định.</p>`});}
ccReg('npmock',{n:'Đề thi thử CCNP: trộn câu hỏi các chủ đề',spec:'Câu hỏi tự soạn theo blueprint ENCOR, ENARSI, SPCOR',solo:true,steps:()=>1,sim:i=>npMockR(i),
 par:()=>[{l:'Số câu',r:[5,40,5],f:x=>x+' câu',def:20},{l:'Kỳ thi',o:[['all','Tất cả'],['encor','ENCOR'],['enarsi','ENARSI'],['spcor','SPCOR']],def:'all'}],
 idx:'đề thi thử mock exam CCNP ENCOR ENARSI SPCOR trộn câu hỏi luyện thi'});
(function(){const mk=(arr,n)=>{const it={};arr.filter(k=>CCT[k]).forEach(k=>{it['c_'+k]=ccItem(k);});return{n,items:it};};
  const V=GX.tx.views;
  V.npO=mk(['npover','npmock'],'CCNP: tổng quan và đề thi thử');
  V.npO.items.c_npmock.cnt=()=>{ccSync();return Math.max(1,npMockList().length);};
  const grp={npR:['CCNP ENCOR, ENARSI: định tuyến IP',['eig','ospx','bgp','rdis','ipv6','pbr','bgpa','tsh']],npS:['CCNP ENCOR: chuyển mạch, QoS, multicast',['fhrp','qos','mc']],npV:['CCNP ENCOR, ENARSI: VPN, ảo hoá, bảo mật',['vpn','vrt','sec']],npA:['CCNP ENCOR: giám sát, tự động hoá, không dây',['ass','wl']],npP:['CCNP SPCOR: IS-IS, MPLS, Segment Routing',['isis','mpls','l3v','sr']],npQ:['CCNP SPCOR: dịch vụ nhà mạng',['l2v','spq','spb','sps','spa']]};
  Object.keys(grp).forEach(g=>{V[g]=mk(grp[g][1],grp[g][0]);if(!Object.keys(V[g].items).length)delete V[g];});
  const N0=GX.tx.note;GX.tx.note=()=>{const k=String(S.txI);return k.startsWith('c_')&&CCT[k.slice(2)]&&CCT[k.slice(2)].np?CCPNOTE:N0();};
  const L=GX.tx.lead;GX.tx.lead=()=>L()+' Phần CCNP (Cisco ENCOR, ENARSI, SPCOR): EIGRP, OSPF nhiều vùng, BGP, redistribution, IPv6, PBR, HSRP, QoS, multicast, IPsec và DMVPN, VXLAN, LISP, bảo mật truy cập, IP SLA, NETCONF; và phía nhà mạng: IS-IS, MPLS, L3VPN, Segment Routing, EVPN, QoS nhà mạng, route reflector, CGNAT; mỗi chủ đề có mô phỏng, câu hỏi trắc nghiệm và phiếu lệnh.';
})();

