/* danh sách các bước dọc, mỗi bước có trạng thái: ok, fail, cur, idle */
function fwPipe(items,lab){
  const W=372,rh=34,H=items.length*rh+6;let s='';
  items.forEach((it,j)=>{const y=4+j*rh,st=it.st||'idle',col=st==='fail'?V_('warn'):st==='ok'?V_('k1'):st==='cur'?V_('warn'):V_('line'),fillc=st==='cur'?`color-mix(in srgb,${V_('warn')} 14%,${V_('panel')})`:st==='fail'?`color-mix(in srgb,${V_('warn')} 10%,${V_('panel')})`:V_('panel2');
    s+=`<g data-gxs="${it.k}:${j}" tabindex="0" role="button" style="cursor:pointer"><rect x="6" y="${y}" width="${W-12}" height="${rh-6}" rx="5" style="fill:${fillc};stroke:${col};stroke-width:${st==='cur'?2.6:1.3}"/>`+tx(16,y+13,(st==='ok'?'✓ ':st==='fail'?'✗ ':'')+it.n,{a:'start',fs:9.2,b:1,c:V_('ink')})+(it.sub?tx(16,y+24,it.sub,{a:'start',fs:7.6,c:V_('muted')}):'')+`</g>`;
    if(j<items.length-1)s+=li([[W/2,y+rh-6],[W/2,y+rh]],{c:V_('line'),w:1.2});});
  return svgw(W,H,s,lab||'Các bước xử lý');}
