const fwCpArch=()=>({nodes:[['sc',4,78,64,30,'SmartConsole','quản trị'],['sm',100,78,64,30,'SMS','Mgmt Server'],['ca',100,148,64,30,'ICA','chứng chỉ SIC'],['gw',196,78,64,30,'Gateway','Gaia'],['lg',196,8,64,30,'Log, Event','SmartEvent'],['cl',292,78,64,30,'Cluster','ClusterXL'],['nt',292,148,64,30,'Mạng','vùng bảo vệ']],
 links:[['sc','sm','19009'],['sm','ca','SIC'],['sm','gw','Install'],['gw','lg','Log'],['gw','cl','Sync'],['gw','nt','Gói']],
 steps:[[['sc','sm'],['sc-sm'],'Quản trị viên sửa chính sách','SmartConsole kết nối tới Security Management Server (SMS) qua giao diện quản lý (HTTPS, thường TCP 19009 từ R80). Chỉnh sửa diễn ra trong một phiên (session); nhiều quản trị viên làm cùng lúc, chỉ khi bấm Publish thay đổi mới ghi vào CSDL dùng chung.',[['Cổng SmartConsole→SMS','TCP 19009 (R80 trở lên)'],['Hành động','Publish rồi Install Policy']]],
  [['sm','ca'],['sm-ca'],'SMS và ICA: tin cậy bằng chứng chỉ (SIC)','Mỗi gateway cần được SMS tin cậy qua SIC (Secure Internal Communication): gateway nhận chứng chỉ từ Internal CA của SMS sau khi quản trị nhập mật khẩu một lần (one-time password). Sau đó mọi trao đổi giữa SMS và gateway được xác thực và mã hoá.',[['SIC','chứng chỉ do ICA cấp, mật khẩu dùng một lần'],['Cổng thường gặp','CPMI 18190, CPD 18191 (kiểm tra theo phiên bản)']]],
  [['sm','gw'],['sm-gw'],'Install Policy','SMS xác minh (verify) chính sách rồi biên dịch và đẩy xuống gateway; gateway nạp vào nhân (kernel) mà không cần khởi động lại. Lệnh trên gateway: fw stat cho biết chính sách hiện hành và thời điểm nạp.',[['Kiểm tra trước','Verify; cảnh báo luật bóng (shadowed), đối tượng chưa dùng'],['Trên gateway','fw stat']]],
  [['gw','nt'],['gw-nt'],'Gateway xử lý gói: SecureXL, CoreXL','Gói đi qua đường nhanh SecureXL (đã khớp phiên, được tăng tốc) hoặc đường chậm hơn qua nhân Firewall khi cần kiểm tra (phiên mới, IPS, nội dung). CoreXL chia tải ra nhiều lõi CPU. Tên đường xử lý và số liệu xem bằng fwaccel stat, fw ctl multik stat.',[['Đường nhanh','SecureXL (accelerated path)'],['Đường giữa/chậm','PSL, F2F (kiểm tra sâu)'],['Chia lõi','CoreXL']]],
  [['gw','lg'],['gw-lg'],'Nhật ký và sự kiện','Gateway gửi log tới log server (thường TCP 257); SmartLog/SmartEvent gom, tương quan để phát hiện sự cố và đe doạ. Ghi log theo luật (cột Track); luật cho phép không ghi log sẽ khó điều tra.',[['Log','TCP 257 (kiểm tra theo phiên bản)'],['Công cụ','SmartLog, SmartEvent']]],
  [['gw','cl'],['gw-cl'],'Cụm gateway đồng bộ trạng thái','Hai (hoặc nhiều) gateway ClusterXL đồng bộ bảng kết nối để khi chuyển đổi, phiên đang có không bị đứt. Xem mục ClusterXL.']]});
const fwCpLayers=()=>({
 pts:[['Mô hình lớp chính sách (R80 trở lên)','Chính sách gồm các “lớp” (layer). Access Control: Firewall (L3/L4), Application Control và URL Filtering, Content Awareness (loại dữ liệu), NAT. Threat Prevention: IPS, Anti-Bot, Anti-Virus, Threat Emulation, Threat Extraction. Mỗi lớp có thể bật tắt, đặt thứ tự, gắn quyền riêng cho từng nhóm quản trị.'],
  ['Luật khớp từ trên xuống, khớp đầu tiên thắng','Gói được so với từng luật theo thứ tự No.; luật đầu tiên khớp (nguồn, đích, dịch vụ/ứng dụng, thời gian…) quyết định hành động. Luật Cleanup cuối cùng (Drop tất cả, có log) là thói quen tốt. Luật bóng (shadowed rule) bị luật phía trên che nên không bao giờ khớp.'],
  ['Lớp thứ tự (ordered layer) và lớp nội tuyến (inline layer)','Ordered layer: gói phải được chấp nhận ở mọi lớp nối tiếp; một lớp Drop là mất. Inline layer: một luật cha mở ra một nhóm luật con (ví dụ luật “UE ra Internet” có lớp con kiểm tra ứng dụng), giữ bộ luật gọn.'],
  ['Luật ngầm (implied rules)','Gateway có luật ngầm cho các dịch vụ nội bộ (SIC, log, ClusterXL…) nằm ngoài bảng luật. Cần biết khi điều tra “vì sao gói này được cho phép”.'],
  ['Đối tượng','Network, Host, Group, Address Range, Service, Application/Site, Data Type, Access Role (người dùng, máy), Time, Updatable Objects (danh sách địa chỉ cập nhật tự động). Đặt tên rõ nghĩa, tránh luật dùng địa chỉ trực tiếp.'],
  ['Thực hành tốt','Mỗi luật có Name và Comment; chỉ mở đúng dịch vụ cần; đặt Track là Log cho luật quan trọng; kiểm tra luật không dùng bằng Hit Count; làm theo nguyên tắc “từ chối mặc định”.']],
 tb:()=>['Ví dụ bảng luật của biên mạng di động (minh hoạ, địa chỉ tự đặt)',['No.','Tên','Nguồn','Đích','Dịch vụ','Hành động','Track'],[['1','Quản trị cổng','OAM','Gateway','ssh, https, snmp','Accept','Log'],['2','Stealth','Any','Gateway','Any','Drop','Log'],['3','Chặn Telnet, SMB','Any','Any','telnet, smb','Drop','Log'],['4','OAM quản lý thiết bị','OAM','RAN, Core, IMS, DMZ','ssh, https, snmp','Accept','Log'],['5','RAN và lõi','RAN, Core','Core, RAN','gtp-u, sctp','Accept','Log'],['6','Roaming vào lõi','Roaming','Core','gtp-c, diameter','Accept','Log'],['7','IMS','Core, Roaming','IMS','sip','Accept','Log'],['8','UE ra Internet','Dải UE','Internet','https, dns, icmp','Accept (Hide NAT)','Log'],['9','Internet vào DMZ','Internet','DMZ','https, dns','Accept (Static NAT)','Log'],['10','Cleanup','Any','Any','Any','Drop','Log']]]});
const fwCpNat=()=>({nodes:[['pi',4,8,64,30,'i','vào'],['vi',100,8,64,30,'VM vào','luật, anti-spoof'],['pI',196,8,64,30,'I','sau luật'],['rt',292,8,64,30,'Định tuyến','route'],['po',292,78,64,30,'o','trước ra'],['vo',196,78,64,30,'VM ra','NAT nguồn'],['pO',100,78,64,30,'O','ra']],
 links:[['pi','vi',''],['vi','pI',''],['pI','rt',''],['rt','po','route'],['po','vo',''],['vo','pO','']],
 steps:[[['pi'],[],'Gói vào giao diện (điểm i)','Điểm i của fw monitor: gói vừa tới, chưa qua kiểm tra của nhân firewall; địa chỉ vẫn là địa chỉ gốc.',[['fw monitor','điểm i (pre-inbound)']]],
  [['pi','vi'],['pi-vi'],'Chống giả mạo (anti-spoofing)','Kiểm tra địa chỉ nguồn có phù hợp giao diện vào theo topology khai báo. Gói giả mạo bị loại ở đây.'],
  [['vi'],[],'Tra bảng kết nối, rồi bộ luật','Gói thuộc kết nối đã có thì đi thẳng; gói mở kết nối mới được so với bảng luật theo địa chỉ gốc (chưa NAT).'],
  [['vi','pI'],['vi-pI'],'NAT đích phía máy khách (client side)','Điểm I (post-inbound): NAT đích (Static NAT, chuyển cổng) thực hiện sau khi luật cho phép và trước định tuyến, vì thế định tuyến thấy địa chỉ đã dịch. Cần gateway trả lời ARP cho địa chỉ công cộng (proxy ARP).'],
  [['pI','rt'],['pI-rt'],'Định tuyến','Gateway tra bảng định tuyến để chọn giao diện ra, theo địa chỉ đích đã dịch (nếu có NAT đích).'],
  [['po','vo'],['po-vo'],'Tới bộ xử lý ra','Điểm o (pre-outbound); gói qua phần kiểm tra chiều ra (ví dụ một số kiểm tra nội dung, NAT nguồn).'],
  [['vo','pO'],['vo-pO'],'NAT nguồn (Hide hoặc Static) rồi ra','NAT nguồn dịch địa chỉ gói trước khi rời gateway (điểm O). Hide NAT gộp nhiều địa chỉ nguồn vào một địa chỉ công cộng, phân biệt bằng cổng nguồn; bảng NAT phải đủ cổng cho số phiên.',[['Hide NAT','nhiều → một (dịch cả cổng)'],['Static NAT','một ↔ một (không dịch cổng)']]]]});
const fwCpHa=()=>({nodes:[['sw',4,78,64,30,'Switch','phía ngoài'],['a',100,8,64,30,'GW A','Active'],['b',100,148,64,30,'GW B','Standby'],['sy',196,78,64,30,'Sync','đồng bộ'],['sw2',292,78,64,30,'Switch','phía trong']],
 links:[['sw','a',''],['sw','b',''],['a','sy','CCP'],['b','sy','CCP'],['a','sw2',''],['b','sw2','']],
 steps:[[['sw','a','sw2'],['sw-a','a-sw2'],'Trạng thái bình thường (HA)','Gateway A là Active, B là Standby; cả hai có địa chỉ ảo (VIP) và MAC ảo chung, nên thiết bị xung quanh chỉ thấy một địa chỉ. Chỉ Active xử lý lưu lượng (chế độ High Availability). Xem bằng lệnh cphaprob stat.',[['Lệnh','cphaprob stat'],['Chế độ','High Availability (Active/Standby)']]],
  [['a','sy','b'],['a-sy','b-sy'],'Đồng bộ trạng thái và nhịp CCP','Hai gateway trao đổi bản tin Cluster Control Protocol (CCP, UDP 8116) qua các giao diện cụm, kể cả mạng đồng bộ riêng; đồng thời đồng bộ bảng kết nối để phiên không đứt khi chuyển. Mất nhịp CCP quá thời hạn là dấu hiệu sự cố.',[['CCP','UDP 8116 (kiểm tra theo phiên bản)'],['Đồng bộ','bảng kết nối, NAT, VPN']]],
  [['a'],[],'Sự cố kích hoạt chuyển đổi','Giám sát các “thiết bị tới hạn” (pnote): giao diện đứt, tiến trình fwd, cphad, routed không phản hồi, ... Thiết bị nào hỏng thì gateway tự hạ ưu tiên. Xem bằng cphaprob list.',[['Lệnh','cphaprob list, cphaprob -a if']]],
  [['b','sw'],['sw-b'],'Gateway B lên Active','B nhận VIP, gửi ARP miễn phí (gratuitous ARP) để cập nhật bảng ARP của các thiết bị; các phiên đã đồng bộ tiếp tục, phiên chưa kịp đồng bộ phải thiết lập lại. Thời gian chuyển điển hình vài giây (ước lượng, tuỳ cấu hình).'],
  [['a','b'],['a-sy','b-sy'],'Quay lại (failback)','Tuỳ cài đặt: giữ gateway hiện tại làm Active (Maintain current active) để tránh chuyển đổi lần hai, hay quay về gateway có ưu tiên cao hơn (Switch to higher priority).'],
  [['sw','a','b','sw2'],['sw-a','sw-b','a-sw2','b-sw2'],'Chế độ chia tải (Load Sharing)','Cả hai gateway cùng xử lý, lưu lượng chia theo băm (unicast hoặc multicast). Phù hợp lưu lượng lớn nhưng cần chú ý định tuyến bất đối xứng và đồng bộ trạng thái đầy đủ.']]});
const fwCpIps=()=>({
 pts:[['Hồ sơ (profile) và hai chế độ','IPS chạy theo hồ sơ (ví dụ Basic, Optimized, Strict hoặc hồ sơ do quản trị tạo). Mỗi bảo vệ (protection) có chế độ Prevent (chặn và ghi log) hoặc Detect (chỉ ghi log). Khi triển khai mới nên để Detect một thời gian, xem log, rồi chuyển Prevent.'],
  ['Tiêu chí chọn bảo vệ','Mỗi bảo vệ có mức độ nghiêm trọng (severity), độ tin cậy (confidence) và tác động hiệu năng (performance impact). Hồ sơ chọn tập bảo vệ theo ngưỡng của ba tiêu chí này; hồ sơ chặt chẽ hơn thì bật nhiều bảo vệ hơn nhưng tốn CPU và dễ cảnh báo giả.'],
  ['Các thành phần Threat Prevention','IPS (chữ ký lỗ hổng), Anti-Bot (phát hiện máy nhiễm kết nối C&C), Anti-Virus (tệp độc hại), Threat Emulation (chạy tệp lạ trong môi trường cô lập, thương hiệu SandBlast), Threat Extraction (làm sạch tệp: loại bỏ phần chủ động). Cập nhật chữ ký qua ThreatCloud.'],
  ['Kiểm tra lưu lượng mã hoá (HTTPS Inspection)','Hầu hết lưu lượng là TLS, IPS không thấy nội dung nếu không giải mã. Giải mã (HTTPS Inspection) cần chứng chỉ CA nội bộ phát cho máy khách, chính sách loại trừ (ngân hàng, y tế) và đánh giá pháp lý, hiệu năng.'],
  ['Áp dụng trong mạng di động','Gateway biên cần xử lý khối lượng lớn: dùng hồ sơ riêng cho lưu lượng báo hiệu và lõi, tránh bật chữ ký nặng ở đường người dùng lưu lượng cao. Có tính năng kiểm tra GTP (GTP Security) cho nhà mạng, chi tiết ở mục Bảo mật mạng di động.'],
  ['Điều chỉnh vòng đời','Chu trình: bật ở Detect, xem log, đặt ngoại lệ cho dương tính giả, chuyển sang Prevent, giám sát hiệu năng (CPU, kết nối/giây), rà soát hằng tháng khi có chữ ký mới.']],
 tb:()=>['Tuning hồ sơ IPS (minh hoạ)',['Tình huống','Hành động gợi ý'],[['Dương tính giả với ứng dụng nội bộ','Đặt ngoại lệ cho bảo vệ đó với nguồn, đích cụ thể; không tắt toàn cục'],['CPU gateway cao','Giảm tập bảo vệ có tác động hiệu năng cao ở đường lưu lượng lớn; kiểm tra có bật quét tệp không cần thiết'],['Gateway phải quét cả lưu lượng nội bộ tin cậy','Chỉ áp IPS ở ranh giới vùng, không áp cho mọi luật'],['Bản cập nhật chữ ký mới','Chạy Detect trước khi Prevent với bảo vệ mới nếu hệ thống quan trọng']]]});
const fwCpVpn=()=>({
 pts:[['Site-to-Site IPsec: cộng đồng VPN (VPN Community)','Cấu hình theo cộng đồng: Meshed (mọi gateway thông nhau) hoặc Star (vệ tinh chỉ nói với trung tâm). Gateway trao đổi qua IKE (IKEv1, IKEv2 tuỳ phiên bản) để lập SA, ESP bảo vệ dữ liệu. Chọn mã hoá, băm, nhóm DH, thời hạn khoá cho cộng đồng.'],
  ['Miền mã hoá (encryption domain)','Mỗi gateway khai báo những mạng nào nằm sau nó cần mã hoá. Hai đầu phải khớp: lệch miền (mismatch subnet) là lỗi VPN phổ biến nhất (lập IKE được nhưng gói không đi). Có thể đổi sang VPN theo định tuyến (VTI), khi đó route quyết định gói nào vào tunnel.'],
  ['Giữ tunnel và phát hiện chết','Tunnel thường dựng khi có lưu lượng; có thể đặt tunnel thường trực (permanent) kèm DPD (dead peer detection). Chọn giao diện ra theo Link Selection khi gateway nhiều đường Internet.'],
  ['Truy cập từ xa','Người dùng dùng client VPN (Remote Access) hoặc cổng SSL; xác thực bằng chứng chỉ, tên người dùng/mật khẩu và hai yếu tố. Tách vùng cho nhà thầu, giới hạn quyền theo Access Role.'],
  ['Vai trò trong mạng di động','Gateway bảo mật SeGW giữa trạm và lõi dùng IPsec (3GPP TS 33.210, 33.310; ở 5G TS 33.501): IKEv2, chứng chỉ X.509, ESP, thường nhiều nghìn tunnel. Một số nhà mạng dùng thiết bị chuyên dụng cho SeGW; tường lửa dùng cho IPsec của đối tác, nhà cung cấp, VPN văn phòng.'],
  ['MTU và MSS','ESP thêm khoảng 50 đến 70 byte; nên kẹp MSS (MSS clamping) và cho phép ICMP để PMTUD hoạt động. Lỗi “ping được, web treo” qua VPN là dấu hiệu MTU.']],
 tb:()=>['Tham số IPsec minh hoạ (nên đối chiếu 3GPP TS 33.210 và chính sách của bạn)',['Tham số','Giá trị gợi ý','Ghi chú'],[['IKE','IKEv2','khuyến nghị cho thiết bị mới'],['Mã hoá IKE','AES-256-GCM hoặc AES-256-CBC','tránh 3DES, DES'],['Băm (PRF)','SHA-256 trở lên','SHA-1 chỉ khi bắt buộc'],['Nhóm DH','14 (2048 bit) hoặc 19, 20 (đường cong elliptic)','nhóm lớn hơn tốn CPU'],['ESP','AES-256-GCM (mã hoá có xác thực)','hoặc AES-CBC + HMAC-SHA-256'],['PFS','Bật','khoá phiên không suy ra từ khoá cũ'],['Thời hạn SA','IKE 8 đến 24 giờ, IPsec 1 giờ','ước lượng thường gặp']]]});
const fwCpCli=()=>({
 pts:[['Gaia: clish và expert','Gaia là hệ điều hành của gateway. clish là vỏ lệnh có cú pháp thống nhất, kiểm tra tham số và lưu cấu hình bằng save config. Chế độ expert là vỏ Linux đầy đủ, dùng cho các công cụ như fw, cp*, và cần cẩn thận vì sửa trực tiếp có thể làm hỏng hệ thống. Cả hai đều cần tài khoản có quyền thích hợp.'],
  ['Cấu hình giao diện cơ bản (clish)','set interface eth1 ipv4-address 192.0.2.1 mask-length 24; set interface eth1 state on; set static-route default nexthop gateway address 192.0.2.254 on; save config. Kiểm tra bằng show interfaces all, show route.'],
  ['Chẩn đoán gói bị chặn','fw ctl zdebug drop xem các gói đang bị loại và lý do (chạy ngắn, vì nặng CPU); fw monitor bắt gói ở bốn điểm i, I, o, O của nhân; kết hợp bộ lọc theo host để không quá tải; log trong SmartConsole cho biết luật nào khớp.'],
  ['Hiệu năng','cpview xem CPU, kết nối, băng thông theo thời gian thực; fwaccel stat xem SecureXL có bật không; fw ctl multik stat xem CoreXL chia lõi; fw tab -t connections -s đếm kết nối.'],
  ['Cụm','cphaprob stat trạng thái cụm; cphaprob list thiết bị tới hạn; cphaprob -a if giao diện cụm; clusterXL_admin down/up để thử chuyển đổi có kiểm soát.']],
 tb:()=>['Bảng tra lệnh hay dùng (cơ bản, kiểm tra theo phiên bản)',['Lệnh','Công dụng'],[['show interfaces all','Liệt kê giao diện và địa chỉ (clish)'],['show route','Bảng định tuyến (clish)'],['fw stat','Chính sách hiện hành và thời điểm nạp'],['fwaccel stat','Trạng thái tăng tốc SecureXL'],['fw ctl pstat','Thống kê bộ nhớ, kết nối của nhân'],['fw tab -t connections -s','Số mục trong bảng kết nối'],['fw ctl zdebug drop','Xem các gói bị loại và lý do (dùng ngắn)'],['fw monitor -e "accept host(192.0.2.10);"','Bắt gói theo bộ lọc, ở các điểm i I o O'],['cphaprob stat','Trạng thái ClusterXL'],['cpview','Bảng theo dõi hiệu năng tương tác'],['cpstat fw','Thống kê firewall tóm tắt']]]});
/* ====== So sánh hãng ====== */
const FWCOMP=[ /* [tiêu chí, cp, pa, ft, asa, srx, usg] */
 ['Quản lý tập trung','SmartConsole kết nối Security Management Server (SMS); nhiều miền với Multi-Domain.','Panorama.','FortiManager (kèm FortiAnalyzer cho log).','FMC cho FTD; ASDM, CSM cho ASA.','Junos Space Security Director hoặc CLI từng thiết bị.','Hệ thống quản lý riêng của Huawei (ví dụ eSight, iMaster).'],
 ['Mô hình chính sách','Các lớp (layer) Access Control và Threat Prevention; luật từ trên xuống, khớp đầu tiên.','Luật theo zone và App-ID, từ trên xuống.','Chính sách theo giao diện hoặc zone; hỗ trợ VDOM để chia ảo.','ASA: ACL theo giao diện và mức an toàn; FTD: Access Control Policy.','Chính sách theo cặp from-zone, to-zone.','Chính sách bảo mật theo zone (security-policy), mặc định chặn giữa các zone.'],
 ['Nhận diện ứng dụng','Application Control, URL Filtering.','App-ID, trọng tâm của kiến trúc.','Application Control (FortiGuard).','AVC (trên FTD).','AppSecure, AppID.','Nhận dạng ứng dụng (cơ sở chữ ký riêng).'],
 ['Chống đe doạ','IPS, Anti-Bot, Anti-Virus, Threat Emulation (SandBlast), Threat Extraction.','Threat Prevention, WildFire (sandbox).','IPS, AV, sandbox (FortiSandbox).','IPS dựa Snort (Talos), AMP.','IDP, ATP Cloud.','IPS, AV, sandbox của hãng.'],
 ['Kiến trúc xử lý','Gaia, CoreXL chia lõi, SecureXL tăng tốc.','Xử lý một lượt song song (Single-Pass), PAN-OS.','FortiOS trên ASIC chuyên dụng (NP, CP) cho nhiều dòng.','ASA/FTD: tiến trình Lina và Snort.','Junos, mô hình dựa luồng (flow-based) trên SRX.','Dòng USG với bộ xử lý mạng riêng.'],
 ['VPN','Site-to-Site, Remote Access, Mobile Access.','IPsec và GlobalProtect.','IPsec, SSL VPN, FortiClient.','IPsec, AnyConnect.','IPsec (hỗ trợ theo định tuyến), Juniper Secure Connect.','IPsec, SSL VPN.'],
 ['Dự phòng (HA)','ClusterXL (Active/Standby, Load Sharing), VRRP.','HA Active/Passive, Active/Active.','FGCP.','Failover Active/Standby, Clustering.','Chassis Cluster.','HRP (Huawei Redundancy Protocol).'],
 ['Cấu hình và tự động hoá','SmartConsole, mgmt_cli, Management API.','CLI dạng set và commit, API REST.','CLI dạng config/edit/next, API REST.','CLI kiểu IOS, FMC API.','CLI Junos dạng set, NETCONF.','CLI kiểu VRP, NETCONF.'],
 ['Tính năng cho nhà mạng','Biên Gi/SGi, SeGW; có tính năng bảo mật GTP cho nhà mạng.','Bảo mật GTP, SCTP và 5G (PFCP, SBI) trên một số bản PAN-OS.','Bản “Carrier” với GTP, SCTP, CGNAT.','Inspect GTP trên ASA (theo giấy phép).','GTP firewall, SCTP, CGNAT trên dòng SRX và thẻ dịch vụ.','Dòng cho nhà mạng, CGNAT và kiểm tra GTP.']];
const fwCompTbl=(a,b)=>tbl(['Tiêu chí',FWVDN[a],FWVDN[b]],FWCOMP.map(r=>[`<b>${r[0]}</b>`,r[1+FWVD.findIndex(x=>x[0]===a)],r[1+FWVD.findIndex(x=>x[0]===b)]]));
const fwCfgRows=[ /* [mục đích, giải thích, cp, pa, ft, asa, srx, usg] */
 ['Vùng và đối tượng mạng','Khai báo vùng (zone/giao diện) bên trong, bên ngoài và đối tượng mạng LAN dùng trong luật.',
  `# SmartConsole: New → Network "Net-LAN"\nmgmt_cli add network name "Net-LAN" subnet "192.0.2.0" mask-length 24`,
  `set zone trust network layer3 ethernet1/1\nset zone untrust network layer3 ethernet1/2\nset address Net-LAN ip-netmask 192.0.2.0/24`,
  `config firewall address\n  edit "Net-LAN"\n    set subnet 192.0.2.0 255.255.255.0\n  next\nend`,
  `interface GigabitEthernet0/0\n nameif inside\n security-level 100\n ip address 192.0.2.1 255.255.255.0\ninterface GigabitEthernet0/1\n nameif outside\n security-level 0\nobject network Net-LAN\n subnet 192.0.2.0 255.255.255.0`,
  `set security zones security-zone trust interfaces ge-0/0/1.0\nset security zones security-zone untrust interfaces ge-0/0/2.0\nset security address-book global address Net-LAN 192.0.2.0/24`,
  `firewall zone trust\n add interface GigabitEthernet 0/0/1\nfirewall zone untrust\n add interface GigabitEthernet 0/0/2\nip address-set Net-LAN type object\n address 0 192.0.2.0 mask 24`],
 ['Luật cho phép HTTPS từ trong ra ngoài','Cho phép mạng LAN truy cập HTTPS ra Internet, ghi log.',
  `mgmt_cli add access-rule layer "Network" position top name "Allow-Web" source "Net-LAN" destination "Any" service "https" action "Accept" track.type "Log"`,
  `set rulebase security rules Allow-Web from trust to untrust source Net-LAN destination any application ssl service application-default action allow log-end yes`,
  `config firewall policy\n  edit 1\n    set name "Allow-Web"\n    set srcintf "port1"\n    set dstintf "port2"\n    set srcaddr "Net-LAN"\n    set dstaddr "all"\n    set action accept\n    set schedule "always"\n    set service "HTTPS"\n    set logtraffic all\n  next\nend`,
  `access-list INSIDE_IN extended permit tcp object Net-LAN any eq https\naccess-group INSIDE_IN in interface inside`,
  `set security policies from-zone trust to-zone untrust policy Allow-Web match source-address Net-LAN destination-address any application junos-https\nset security policies from-zone trust to-zone untrust policy Allow-Web then permit\nset security policies from-zone trust to-zone untrust policy Allow-Web then log session-close`,
  `security-policy\n rule name Allow-Web\n  source-zone trust\n  destination-zone untrust\n  source-address address-set Net-LAN\n  service protocol tcp destination-port 443\n  action permit`],
 ['NAT nguồn ra Internet (Hide NAT)','Dịch địa chỉ riêng sang địa chỉ giao diện ngoài.',
  `mgmt_cli set network name "Net-LAN" nat-settings.auto-rule true nat-settings.method "hide" nat-settings.hide-behind "gateway" nat-settings.install-on "All"`,
  `set rulebase nat rules Hide-LAN from trust to untrust source Net-LAN destination any service any source-translation dynamic-ip-and-port interface-address interface ethernet1/2`,
  `config firewall policy\n  edit 1\n    set nat enable\n  next\nend`,
  `object network Net-LAN\n nat (inside,outside) dynamic interface`,
  `set security nat source rule-set LAN-OUT from zone trust\nset security nat source rule-set LAN-OUT to zone untrust\nset security nat source rule-set LAN-OUT rule R1 match source-address 192.0.2.0/24\nset security nat source rule-set LAN-OUT rule R1 then source-nat interface`,
  `nat-policy\n rule name Hide-LAN\n  source-zone trust\n  destination-zone untrust\n  source-address address-set Net-LAN\n  action source-nat easy-ip`],
 ['Áp dụng cấu hình','Cách làm cho chính sách có hiệu lực và lưu lại.',
  `# SmartConsole: Publish rồi Install Policy; hoặc\nmgmt_cli publish\nmgmt_cli install-policy policy-package "Standard" access true threat-prevention false targets.1 "GW1"`,
  `commit`,
  `# lệnh có hiệu lực ngay sau next/end; cấu hình lưu tự động vào flash`,
  `write memory`,
  `commit check\ncommit`,
  `# lệnh có hiệu lực ngay; lưu cấu hình bằng: save`]];
const fwCfgItem=()=>({n:'Cùng tác vụ trên sáu hãng: cho phép HTTPS ra ngoài có NAT',spec:'—',kind:'custom',ctl:['fwVd'],onCtl:()=>{},cnt:()=>fwCfgRows.length,idx:'cấu hình tường lửa cùng tác vụ Check Point Palo Alto Fortinet Cisco ASA Juniper SRX Huawei USG zone luật NAT',
 r:i=>{const vi=2+FWVD.findIndex(x=>x[0]===S.fwVd),cur=fwCfgRows[clamp(i,0,fwCfgRows.length-1)];
  const fig=`<div style="font:11px/1.55 var(--mono);overflow-x:auto;background:var(--panel2);border:1px solid var(--line);border-radius:8px;padding:6px">`+fwCfgRows.map((r,j)=>`<div data-gxs="fw:${j}" tabindex="0" role="button" style="cursor:pointer;padding:3px 6px;border-radius:5px;margin:2px 0;${j===i?'background:color-mix(in srgb,var(--warn) 16%,var(--panel));outline:2px solid var(--warn)':''}"><div style="font:600 10px/1.3 system-ui,sans-serif;color:var(--muted)">${j+1}. ${esc(r[0])}</div><div style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(r[vi])}</div></div>`).join('')+`</div>`;
  return{fig,hint:'Chạm vào một khối để xem so sánh sáu hãng cho khối đó; chọn hãng ở ô “Hãng xem cấu hình”.',out:prKv([['Hãng',FWVDN[S.fwVd]],['Bước',`${i+1} trên ${fwCfgRows.length}`]]),cap:`${cur[0]}: ${first(cur[1])}`,
   info:`<h3>${esc(cur[0])}</h3><p>${cur[1]}</p><div class="scroll"><table>${tbl(['Hãng','Cùng tác vụ'],FWVD.map((v,q)=>[`<b>${v[1]}</b>`,`<pre style="margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11.5px">${esc(cur[q+2])}</pre>`]))}</table></div><p class="note">Cú pháp ghi theo trí nhớ, lệnh cơ bản phổ biến, kiểm tra theo phiên bản. Với Check Point thường dùng giao diện SmartConsole; mgmt_cli chỉ minh hoạ khả năng tự động hoá. Cisco FTD thường cấu hình qua FMC thay vì CLI.</p>`,
   tt:'Cả tác vụ, sáu hãng',tb:tbl(['Mục đích'].concat(FWVD.map(v=>v[1])),fwCfgRows.map(r=>[esc(r[0])].concat([2,3,4,5,6,7].map(q=>`<pre style="margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(r[q])}</pre>`))),i)};}});
const fwCmp=()=>({n:'So sánh hai hãng theo từng tiêu chí',spec:'—',kind:'custom',ctl:['fwA','fwB'],cnt:()=>1,idx:'so sánh tường lửa Check Point Palo Alto Fortinet Cisco ASA FTD Juniper SRX Huawei USG quản lý chính sách VPN HA',
 r:()=>({fig:'',out:prKv([['Hãng thứ nhất',FWVDN[S.fwA]],['Hãng thứ hai',FWVDN[S.fwB]]]),tt:'So sánh theo tiêu chí',tb:fwCompTbl(S.fwA,S.fwB),
  info:`<p>Chọn hai hãng ở khung bên phải để so sánh theo tiêu chí. Không có hãng nào “tốt nhất” tuyệt đối: lựa chọn phụ thuộc hệ sinh thái đang có, kỹ năng đội vận hành, yêu cầu hiệu năng (băng thông và số phiên mới mỗi giây thật sự), tính năng mạng di động cần dùng (GTP, SCTP, CGNAT, 5G), giá và hỗ trợ tại chỗ.</p><p>Quy tắc thực tế: yêu cầu nhà cung cấp chứng minh bằng bài kiểm thử với bộ tính năng thật bạn sẽ bật (IPS, giải mã TLS, ghi log) chứ không chỉ con số “băng thông tường lửa” trong datasheet, vì khi bật đủ tính năng hiệu năng thấp đi nhiều.</p>`})});
const fwAll=()=>({n:'Bảng tổng hợp sáu hãng',spec:'—',kind:'text',pts:[['Bảng tổng hợp','Xem bảng bên dưới: mỗi hàng là một tiêu chí, mỗi cột một hãng. Thông tin ghi theo hiểu biết chung, cần kiểm tra datasheet và tài liệu đúng phiên bản.']],tb:()=>['Sáu hãng theo từng tiêu chí',['Tiêu chí'].concat(FWVD.map(v=>v[1])),FWCOMP.map(r=>[`<b>${r[0]}</b>`].concat(r.slice(1)))]});
gxDef('fw',{label:'Tường lửa',il:'Nội dung',hold:3000,
 lead:()=>'Check Point là hãng trọng tâm: kiến trúc quản lý, lớp chính sách, NAT, ClusterXL, IPS và VPN. Sau đó so sánh với Palo Alto, Fortinet, Cisco ASA/FTD, Juniper SRX, Huawei USG, mô phỏng gói đi qua bộ luật từng bước (chống giả mạo, bảng kết nối, luật, NAT, chống đe doạ), và phần bảo mật riêng của mạng di động: tường lửa Gi/SGi, GTP, SIP, SS7 và Diameter, SEPP, DDoS.',
 note:FWNOTE,
 views:{
  cp:{n:'Check Point',items:{
   arch:{n:'Kiến trúc: SmartConsole, SMS, SIC, gateway',spec:'Tài liệu Check Point (R81.x, R82 theo phiên bản)',kind:'flow',g:fwCpArch},
   layers:{n:'Lớp chính sách và bảng luật',spec:'Check Point Access Control, Threat Prevention',kind:'text',pts:fwCpLayers().pts,tb:fwCpLayers().tb},
   nat:{n:'NAT và thứ tự xử lý trong nhân (i, I, o, O)',spec:'Check Point NAT; công cụ fw monitor',kind:'flow',g:fwCpNat},
   ha:{n:'ClusterXL: dự phòng và chia tải',spec:'Check Point ClusterXL',kind:'flow',g:fwCpHa},
   ips:{n:'IPS và Threat Prevention',spec:'Check Point IPS, Anti-Bot, SandBlast',kind:'text',pts:fwCpIps().pts,tb:fwCpIps().tb},
   vpn:{n:'VPN IPsec site-to-site và truy cập từ xa',spec:'RFC 7296 (IKEv2), RFC 4303 (ESP); 3GPP TS 33.210',kind:'text',pts:fwCpVpn().pts,tb:fwCpVpn().tb},
   cli:{n:'Gaia và lệnh chẩn đoán',spec:'Tài liệu Gaia',kind:'text',pts:fwCpCli().pts,tb:fwCpCli().tb}}},
  cmp:{n:'So sánh các hãng',items:{
   two:fwCmp(),
   all:fwAll(),
   cfg:fwCfgItem()}},
  sim:{n:'Mô phỏng gói đi qua bộ luật',items:{}},
  mob:{n:'Bảo mật riêng mạng di động',items:{}}}});

/* ====== Mô phỏng gói đi qua bộ luật ====== */
const FWZ=[['internet','Internet'],['ue','Dải UE (người dùng di động)'],['ran','RAN (gNB, eNB)'],['core','Lõi (MME, AMF, SMF, UPF)'],['oam','Quản lý OAM, NMS'],['roam','Đối tác roaming (IPX)'],['dmz','DMZ (web, DNS công cộng)'],['ims','IMS (P-CSCF, SBC)'],['gw','Chính cổng tường lửa']];
const FWS=[['https','HTTPS (TCP 443)'],['ssh','SSH (TCP 22)'],['snmp','SNMP (UDP 161)'],['gtpu','GTP-U (UDP 2152)'],['gtpc','GTP-C (UDP 2123)'],['sctp','SCTP S1AP, NGAP (36412, 38412)'],['dia','Diameter (TCP, SCTP 3868)'],['sip','SIP (5060, 5061)'],['dns','DNS (UDP 53)'],['icmp','ICMP'],['telnet','Telnet (TCP 23)'],['smb','SMB (TCP 445)']];
const FWR=[
 {n:'Quản trị cổng',src:['oam'],dst:['gw'],svc:['ssh','https','snmp'],act:'Accept'},
 {n:'Stealth (bảo vệ chính cổng)',src:null,dst:['gw'],svc:null,act:'Drop'},
 {n:'Chặn Telnet, SMB',src:null,dst:null,svc:['telnet','smb'],act:'Drop'},
 {n:'OAM quản lý thiết bị',src:['oam'],dst:['ran','core','ims','dmz'],svc:['ssh','https','snmp'],act:'Accept'},
 {n:'RAN và lõi',src:['ran','core'],dst:['core','ran'],pair:[['ran','core'],['core','ran']],svc:['gtpu','sctp'],act:'Accept',tp:1},
 {n:'Roaming vào lõi',src:['roam'],dst:['core'],svc:['gtpc','dia'],act:'Accept',tp:1,note:'qua tường lửa GTP, Diameter'},
 {n:'IMS',src:['core','roam'],dst:['ims'],svc:['sip'],act:'Accept',tp:1},
 {n:'UE ra Internet',src:['ue'],dst:['internet'],svc:['https','dns','icmp'],act:'Accept',tp:1,nat:'hide'},
 {n:'Internet vào DMZ',src:['internet'],dst:['dmz'],svc:['https','dns'],act:'Accept',tp:1,nat:'static'},
 {n:'Cleanup',src:null,dst:null,svc:null,act:'Drop'}];
const FWPRE=[['cus','Tuỳ chỉnh (chọn nguồn, đích, dịch vụ)'],['ue','UE duyệt web HTTPS ra Internet','ue','internet','https'],['ssh-in','Internet quét SSH vào cổng tường lửa','internet','gw','ssh'],['gtpu','gNB gửi GTP-U tới UPF','ran','core','gtpu'],['roam-ok','Đối tác roaming gửi GTP-C vào lõi','roam','core','gtpc'],['roam-ssh','Đối tác roaming thử SSH vào lõi','roam','core','ssh'],['nms','NMS SSH vào gNB','oam','ran','ssh'],['telnet','NMS dùng Telnet tới gNB','oam','ran','telnet'],['dmz','Internet truy cập HTTPS vào DMZ','internet','dmz','https'],['smb','UE truy cập SMB vào lõi','ue','core','smb']];
Object.assign(S,{fwPre:'ue',fwSrc:'ue',fwDst:'internet',fwSvc:'https',fwSt:'new',fwSp:'no',fwIp:'no'});
C.fwPre={l:'Tình huống mẫu',o:()=>FWPRE.map(x=>[x[0],x[1]])};
C.fwSrc={l:'Nguồn của gói',o:()=>FWZ.filter(x=>x[0]!=='gw')};
C.fwDst={l:'Đích của gói',o:()=>FWZ};
C.fwSvc={l:'Dịch vụ',o:()=>FWS};
C.fwSt={l:'Trạng thái kết nối',o:()=>[['new','Kết nối mới (gói đầu)'],['est','Kết nối đã có trong bảng']]};
C.fwSp={l:'Địa chỉ nguồn',o:()=>[['no','Đúng với giao diện vào'],['yes','Giả mạo (không khớp topology)']]};
C.fwIp={l:'Gói có chữ ký tấn công (IPS)',o:()=>[['no','Không'],['yes','Có (khớp chữ ký)']]};
const fwZn=k=>(FWZ.find(x=>x[0]===k)||[0,k])[1],fwSn=k=>(FWS.find(x=>x[0]===k)||[0,k])[1];
const fwIn=(a,x)=>!a||a.includes(x);
function fwMatch(r,p){const f=[];if(!fwIn(r.src,p.src))f.push('nguồn');if(!fwIn(r.dst,p.dst))f.push('đích');if(!fwIn(r.svc,p.svc))f.push('dịch vụ');if(!f.length&&r.pair&&!r.pair.some(q=>q[0]===p.src&&q[1]===p.dst))f.push('cặp nguồn–đích');return f;}
function fwTrace(){
  const p={src:S.fwSrc,dst:S.fwDst,svc:S.fwSvc,est:S.fwSt==='est',spoof:S.fwSp==='yes',ips:S.fwIp==='yes'},T=[];let rule=-1,verdict='Accept',why='';
  if(p.spoof){T.push({stage:'spoof',ok:false,t:'Chống giả mạo: loại gói',d:`Gói tự nhận nguồn “${fwZn(p.src)}” nhưng đến từ giao diện không thuộc vùng đó theo topology đã khai báo. Gateway loại gói và ghi log “Address spoofing”, không cần xét đến luật. Đây là lớp bảo vệ đầu tiên, trước cả bộ luật.`});return{T,verdict:'Drop',why:'giả mạo địa chỉ nguồn',rule};}
  T.push({stage:'spoof',ok:true,t:'Chống giả mạo: đạt',d:`Địa chỉ nguồn phù hợp với giao diện vào (vùng “${fwZn(p.src)}”). Gói tiếp tục.`});
  if(p.est){T.push({stage:'conn',ok:true,t:'Bảng kết nối: kết nối đã có',d:'Gói thuộc một kết nối đã được cho phép nên được chuyển nhanh, không so lại bộ luật (đây là phần “stateful”). Thay đổi luật không ảnh hưởng kết nối đang sống cho tới khi hết hạn hoặc bị xoá.'});
    T.push({stage:'nat',ok:true,t:'NAT: dùng bản dịch đã có',d:'Nếu kết nối có NAT thì bản dịch đã lập lúc đầu được áp dụng cho gói này.'});}
  else{T.push({stage:'conn',ok:true,t:'Bảng kết nối: kết nối mới',d:'Không có mục nào khớp trong bảng kết nối, nên gói được coi là mở kết nối mới và phải qua bộ luật.'});
    for(let i=0;i<FWR.length;i++){const r=FWR[i],f=fwMatch(r,p);
      if(f.length){T.push({stage:'rule',rule:i,ok:null,t:`Luật ${i+1} “${r.n}”: không khớp`,d:`Không khớp ở ${f.join(', ')}. Chuyển sang luật kế tiếp.`});continue;}
      rule=i;verdict=r.act;T.push({stage:'rule',rule:i,ok:r.act==='Accept',t:`Luật ${i+1} “${r.n}”: khớp, ${r.act}`,d:`Nguồn, đích và dịch vụ đều khớp: luật đầu tiên khớp quyết định, các luật phía dưới không được xét.${r.act==='Drop'?' Hành động Drop: gói bị loại và ghi log.':''}`});break;}
    if(verdict==='Drop'){why=`luật ${rule+1} “${FWR[rule].n}”`;T.push({stage:'out',ok:false,t:'Kết quả: Drop',d:`Gói bị loại do ${why}. Ghi log với số luật để điều tra.`});return{T,verdict,why,rule};}
    const r=FWR[rule];
    T.push({stage:'nat',ok:true,t:r.nat?(r.nat==='hide'?'NAT nguồn kiểu Hide':'NAT đích kiểu Static'):'NAT: không áp dụng',d:r.nat==='hide'?'Nhiều địa chỉ UE (dải riêng hoặc CGNAT) được dịch sang một địa chỉ công cộng, phân biệt bằng cổng nguồn. Ví dụ nguồn 100.64.12.5:40001 → 203.0.113.10:33021. Bảng NAT cần đủ cổng cho số phiên.':r.nat==='static'?'Đích công cộng 203.0.113.20:443 được dịch sang máy chủ DMZ 192.0.2.20:443. Luật được so với địa chỉ gốc, nên ở luật ghi địa chỉ công cộng; gateway cần trả lời ARP cho địa chỉ công cộng.':'Không có luật NAT cho luồng này, địa chỉ giữ nguyên.'});}
  const hasTp=p.est||(rule>=0&&FWR[rule].tp);
  if(p.ips){if(hasTp){T.push({stage:'tp',ok:false,t:'Threat Prevention: chặn (chữ ký IPS khớp)',d:'Nội dung gói khớp chữ ký tấn công trong hồ sơ IPS ở chế độ Prevent: gói/kết nối bị loại và ghi log, dù luật đã cho phép. Cho thấy IPS là lớp độc lập sau luật.'});return{T,verdict:'Drop',why:'IPS (Threat Prevention)',rule};}
    T.push({stage:'tp',ok:true,t:'Threat Prevention: không áp dụng cho luật này',d:'Luật đã khớp không gắn hồ sơ Threat Prevention, nên gói có chữ ký tấn công vẫn đi qua. Đây là lỗi cấu hình thường gặp: cần gắn hồ sơ IPS cho mọi luật cho phép cần bảo vệ.'});}
  else T.push({stage:'tp',ok:true,t:hasTp?'Threat Prevention: không phát hiện đe doạ':'Threat Prevention: không có hồ sơ cho luật này',d:hasTp?'Hồ sơ IPS kiểm tra nội dung, không khớp chữ ký nào. Gói đi tiếp.':'Luật này không gắn hồ sơ Threat Prevention (ví dụ luật quản trị); gói không bị kiểm tra chữ ký.'});
  T.push({stage:'out',ok:true,t:'Kết quả: Accept',d:`Gói được chuyển tiếp${p.est?' theo kết nối có sẵn':' theo luật '+(rule+1)+' “'+FWR[rule].n+'”'}. Ghi log theo cột Track.`});
  return{T,verdict:'Accept',why:'',rule};}
const FWST=[['spoof','Chống giả mạo','anti-spoofing theo topology giao diện'],['conn','Bảng kết nối','kết nối mới hay đã có'],['rule','Bộ luật','từ trên xuống, khớp đầu tiên'],['nat','NAT','dịch địa chỉ'],['tp','Threat Prevention','IPS và chống đe doạ'],['out','Kết quả','Accept hay Drop, ghi log']];
const fwSim=()=>{const R=fwTrace(),T=R.T,i=clamp(S.fwS,0,T.length-1),cur=T[i];
  const items=FWST.map((s,j)=>{const past=T.slice(0,i).filter(e=>e.stage===s[0]);let st='idle';if(cur.stage===s[0])st=cur.ok===false?'fail':'cur';else if(past.length){const l=past.slice().reverse().find(e=>e.ok!==null);st=l?(l.ok?'ok':'fail'):'ok';}return{n:s[1],sub:s[2],st,k:'fw'};});
  const stepOfStage=st=>T.findIndex(e=>e.stage===st);
  const figs=fwPipe(items.map((it,j)=>Object.assign(it,{k:'fwx'})),'Các giai đoạn xử lý gói trong gateway');
  const hl=cur.stage==='rule'?cur.rule:R.rule;
  return{fig:figs.replace(/data-gxs="fwx:(\d+)"/g,(m,a)=>{const idx=stepOfStage(FWST[+a][0]);return idx>=0?`data-gxs="fw:${idx}"`:'';}),
   hint:'Mỗi hộp là một giai đoạn; hộp cam là giai đoạn đang xem, xanh lá đã đạt, đỏ cam là nơi gói bị loại. Chạm hộp để nhảy tới giai đoạn đó.',
   out:prKv([['Gói',`${esc(fwZn(S.fwSrc))} → ${esc(fwZn(S.fwDst))}, ${esc(fwSn(S.fwSvc))}`],['Kết nối',S.fwSt==='est'?'đã có':'mới'],['Bước',`${i+1} trên ${T.length}`],['Kết quả cuối',R.verdict==='Accept'?'<b>Accept</b>':`<b>Drop</b> (${R.why})`]]),
   cap:`${cur.t}. ${first(cur.d)}`,
   info:`<h3>${esc(cur.t)}</h3><p>${cur.d}</p>${gxOl('fw',T.map(e=>`${e.ok===false?'✗ ':e.ok?'✓ ':'· '}${esc(e.t)}`),i)}<p class="note">Mô hình giản lược. Với gateway thật còn có đường nhanh (SecureXL), NAT đa tầng, luật ngầm, kiểm tra ứng dụng nhiều lớp (inline layer) và nhiều hồ sơ Threat Prevention; thứ tự chi tiết xem mục NAT ở phần Check Point.</p>`,
   tt:'Bộ luật mẫu của biên mạng di động (luật đang xét được tô)',tb:tbl(['No.','Tên','Nguồn','Đích','Dịch vụ','Hành động','Ghi chú'],FWR.map((r,j)=>[j+1,esc(r.n),r.src?r.src.map(fwZn).join(', '):'Any',r.dst?r.dst.map(fwZn).join(', '):'Any',r.svc?r.svc.map(x=>x).join(', '):'Any',`<span style="white-space:nowrap">${r.act}</span>`,[r.nat==='hide'?'Hide NAT':r.nat==='static'?'Static NAT':'',r.tp?'IPS':'',r.note||''].filter(Boolean).join('; ')]),hl)};};
/* ====== Bảo mật riêng mạng di động ====== */
const fwMap=()=>{const sa=S.mode==='SA';return{nodes:[['ims',100,8,64,30,'IMS','SBC, P-CSCF'],['dd',196,8,64,30,'DDoS','scrubbing'],['net',292,8,64,30,'Internet','SGi, N6'],['ran',4,78,64,30,sa?'gNB':'eNB','RAN'],['sg',100,78,64,30,'SeGW','IPsec'],['co',196,78,64,30,sa?'5GC':'EPC','lõi'],['gi',292,78,64,30,'Gi FW','CGNAT'],['rp',4,148,64,30,'IPX','đối tác'],['bf',100,148,64,30,'Biên','GTP, DEA']],
 links:[['ran','sg','IPsec'],['sg','co',''],['co','gi',sa?'N6':'SGi'],['gi','net',''],['dd','net','sạch'],['ims','co','SIP'],['rp','bf',sa?'N32':'S8'],['bf','co','']],
 steps:[[['ran','sg'],['ran-sg'],'Bảo vệ đường truy nhập: IPsec và SeGW','Đường backhaul đi qua mạng không tin cậy (đường thuê, vi ba dùng chung) nên báo hiệu và dữ liệu giữa trạm và lõi được bọc IPsec ESP tới cổng bảo mật SeGW (3GPP TS 33.210, TS 33.310 cho chứng chỉ; ở 5G TS 33.501). SeGW chấm dứt tunnel, kiểm tra chứng chỉ trạm (X.509) trước khi cho vào mạng lõi.',[['Giao thức','IKEv2, ESP'],['Xác thực','chứng chỉ X.509 của trạm'],['Chuẩn','TS 33.210, 33.310, 33.501']]],
  [['sg','co'],['sg-co'],'Phân vùng bên trong lõi','Sau SeGW là vùng RAN, vùng lõi, vùng quản lý, vùng IMS; giữa các vùng đặt tường lửa với luật tối thiểu (xem mô phỏng gói đi qua bộ luật). Quản lý (OAM) tách hẳn mạng người dùng.'],
  [['co','gi','net'],['co-gi','gi-net'],`Tường lửa ${sa?'N6':'SGi'} (Gi): người dùng ra Internet`,'Tường lửa ở ranh giới tới Internet: lọc theo trạng thái, CGNAT (RFC 6888) cho dải UE, giới hạn tốc độ kết nối, chặn lưu lượng giả mạo nguồn (BCP 38). Phải chịu số phiên rất lớn, nên dùng thiết bị hiệu năng cao hoặc chạy ảo hoá; ghi log CGNAT để truy vết theo luật.',[['Chức năng','stateful, CGNAT, DDoS cơ bản, lọc ứng dụng'],['Lưu ý','số phiên mới mỗi giây và dung lượng bảng NAT quyết định, không chỉ Gb/s']]],
  [['ims','co'],['ims-co'],'IMS: SBC và SIP ALG','Biên IMS thường đặt Session Border Controller (SBC) che cấu trúc mạng, kiểm soát SIP và media. SIP ALG trên tường lửa thông thường hay làm hỏng SIP (viết lại SDP sai, ép NAT); khi có SBC nên tắt SIP ALG trên tường lửa.'],
  [['rp','bf','co'],['rp-bf','bf-co'],sa?'Roaming 5G: SEPP tại biên N32':'Roaming 4G: GTP và Diameter tại biên S8, S6a','Nơi hai nhà mạng nối nhau, kẻ xấu có thể gửi bản tin báo hiệu giả. Biên cần tường lửa GTP (kiểm tra GTP-C và GTP-U), tường lửa Diameter/DEA (và SS7 nếu còn 2G/3G), và ở 5G là SEPP thay cho DEA (xem mục SEPP).',[['Khuyến nghị','GSMA FS.11 (SS7), FS.19 (Diameter), FS.20 (GTP), FS.21 (5G interconnect)'],['Chuẩn','3GPP TS 33.501 mục 13']]],
  [['dd','net'],['dd-net'],'Chống DDoS','Tấn công làm nghẽn băng thông (Gb/s) hoặc tài nguyên (kết nối/giây, gói/giây). Lớp phòng thủ: lọc ở nhà cung cấp (scrubbing, BGP FlowSpec, RTBH), giới hạn tốc độ ở tường lửa Gi, bảo vệ dịch vụ DNS, SIP, GTP. Xem mô phỏng DDoS.']]};};
const FWGM=[['Create Session Request hợp lệ từ đối tác roaming',-1,'Qua cả bảy kiểm tra nên bản tin được chuyển tiếp.'],['Create Session Request có IMSI/PLMN ngoài thoả thuận',4,'IMSI hoặc PLMN không nằm trong danh sách thoả thuận roaming: bản tin bị chặn ở kiểm tra danh tính.'],['G-PDU chứa GTP lồng (GTP-in-GTP) gửi từ phía người dùng',6,'Tải bên trong là một gói GTP khác: kỹ thuật để lọt qua lọc; tường lửa kiểm tra tải bên trong và chặn.'],['Echo Request tràn ngập từ một đối tác',5,'Vượt ngưỡng tốc độ cho phép theo đối tác nên bị giới hạn, tránh làm cạn tài nguyên.'],['Delete Session Request với TEID không có trong bảng',3,'TEID và số thứ tự không thuộc phiên nào: bản tin không có trạng thái khớp nên bị loại (chống xoá phiên người khác).'],['Bản tin GTP phiên bản 0 (cũ)',1,'Phiên bản cũ không an toàn và không còn dùng: bị chặn theo chính sách.'],['Bản tin dài bất thường hoặc IE sai',2,'Độ dài hoặc IE bắt buộc không hợp lệ: loại để tránh khai thác lỗi bộ phân tích.'],['G-PDU có địa chỉ nguồn UE không khớp phiên',6,'Địa chỉ nguồn trong gói người dùng khác địa chỉ được cấp cho phiên: giả mạo, bị chặn.']];
const FWGC=[['Đối tác trong danh sách cho phép','địa chỉ IP nguồn thuộc đối tác roaming đã ký'],['Phiên bản và kiểu bản tin hợp lệ','chỉ phiên bản và kiểu bản tin theo thoả thuận'],['Độ dài và các IE hợp lệ','kiểm tra độ dài, IE bắt buộc, giá trị hợp lệ'],['Trạng thái: TEID và số thứ tự khớp','bản tin trả lời hay xoá phải thuộc một phiên có thật'],['Danh tính: IMSI, PLMN, APN theo thoả thuận','chặn PLMN lạ, APN không cho phép'],['Giới hạn tốc độ theo đối tác','Echo, Create Session mỗi giây'],['Kiểm tra tải bên trong','GTP lồng GTP, địa chỉ nguồn UE đúng phiên']];
Object.assign(S,{fwGm:0,fwSg:0,fwSs:'hp',fwAt:'syn',fwAg:50,fwTr:100,fwFw:100,fwPp:20,fwSc:'no',fwBl:20});
C.fwGm={l:'Bản tin GTP cần kiểm tra',num:1,o:()=>FWGM.map((m,j)=>[j,m[0]])};
const fwGtp=()=>{const j=S.fwGm,m=FWGM[j],fail=m[1],i=clamp(S.fwS,0,FWGC.length-1);
  const items=FWGC.map((c,q)=>{let st='idle';if(fail<0||q<fail)st=q<=i?'ok':'idle';else if(q===fail)st=i>=q?'fail':'idle';if(q===i&&st!=='fail')st='cur';return{n:c[0],sub:c[1],st,k:'fw'};});
  return{fig:fwPipe(items,'Các kiểm tra của tường lửa GTP'),hint:'Mỗi hộp là một kiểm tra theo thứ tự; bản tin dừng ở kiểm tra đầu tiên không đạt.',
   out:prKv([['Bản tin',esc(m[0])],['Kết quả',fail<0?'<b>Chuyển tiếp</b>':`<b>Chặn</b> ở kiểm tra ${fail+1}: ${esc(FWGC[fail][0])}`],['Bước',`${i+1} trên ${FWGC.length}`]]),cap:m[2],
   info:`<h3>${esc(FWGC[i][0])}</h3><p>${FWGC[i][1]}.</p><p>${i<fail||fail<0?'Bản tin này đạt kiểm tra này.':i===fail?'<b>Bản tin này không đạt kiểm tra này nên bị chặn.</b>':'Bản tin đã bị chặn ở kiểm tra trước, kiểm tra này không còn được xét.'}</p><p>${m[2]}</p><p>Tường lửa GTP duy trì trạng thái theo từng phiên (TEID, địa chỉ, số thứ tự) để kiểm tra bản tin trả lời và xoá, vì thế phải cùng đường đi (không bất đối xứng) và có dung lượng bảng phiên đủ lớn. Khuyến nghị cấu hình theo GSMA FS.20. Bản tin được dùng để minh hoạ, không phải danh mục đầy đủ.</p>`,
   tt:'Các bản tin mẫu và kiểm tra chặn chúng',tb:tbl(['Bản tin mẫu','Kết quả','Chặn ở'],FWGM.map(x=>[esc(x[0]),x[1]<0?'chuyển tiếp':'chặn',x[1]<0?'—':FWGC[x[1]][0]]),j)};};
const FWSM=[['MAP AnyTimeInterrogation (ATI)',1,'Hỏi vị trí và trạng thái thuê bao, chỉ nên dùng nội bộ; từ ngoài gửi vào là dấu hiệu theo dõi thuê bao.'],['MAP ProvideSubscriberInfo (PSI)',1,'Lấy thông tin vị trí chi tiết thuê bao, thuộc nhóm chỉ nội bộ.'],['MAP UpdateLocation (UL)',2,'Hợp lệ khi tới từ mạng khách nơi thuê bao thực sự đang đăng ký; giả mạo để chuyển hướng cuộc gọi, SMS.'],['MAP SendRoutingInfoForSM (SRI-SM)',2,'Dùng để định tuyến SMS; hợp lệ trong ngữ cảnh nhưng hay bị lạm dụng để lấy IMSI và nơi đăng ký thuê bao.'],['Diameter Update-Location-Request (ULR, S6a)',2,'Tương đương UL ở 4G: hợp lệ khi thuê bao đúng ở mạng khách gửi tới.'],['Diameter Cancel-Location-Request (CLR)',1,'Chỉ HSS nhà gửi tới MME đang phục vụ; từ ngoài tới MME của mình là giả mạo để cắt dịch vụ thuê bao.'],['Diameter Authentication-Information-Request (AIR) tốc độ cao','F','Đối tác thật có thể gửi, nhưng tốc độ bất thường là dấu hiệu quét hoặc lấy vector xác thực hàng loạt.'],['Diameter Insert-Subscriber-Data (IDR) từ nút lạ',1,'Chỉ HSS nhà ghi dữ liệu thuê bao vào MME; từ nút lạ là giả mạo thay đổi hồ sơ.']];
const FWSS=[['hp','Đối tác có thoả thuận, thuê bao đang ở đó'],['hn','Đối tác có thoả thuận, thuê bao không ở đó'],['un','Nút lạ, không có thoả thuận'],['sp','Địa chỉ giả như nút của mạng nhà']];
C.fwSg={l:'Bản tin báo hiệu',num:1,o:()=>FWSM.map((m,j)=>[j,m[0]])};
C.fwSs={l:'Nguồn bản tin',o:()=>FWSS};
const FWSC=[['Nguồn thuộc danh sách đối tác','địa chỉ SS7 (GT) hoặc Origin-Host/Realm có trong danh sách thoả thuận, không giả địa chỉ mạng nhà'],['Hướng và loại bản tin hợp lệ','loại 1 (chỉ nội bộ) không được tới từ ngoài; loại 2/3 theo ngữ cảnh'],['Ngữ cảnh và trạng thái','thuê bao có thật đang ở mạng của nguồn không (khớp dữ liệu vị trí đã biết)'],['Hành vi: tốc độ, tần suất','số bản tin mỗi giây, mỗi thuê bao; phát hiện quét hàng loạt'],['Kết luận','cho qua, chặn, hoặc cho qua nhưng cảnh báo']];
const fwSig=()=>{const m=FWSM[S.fwSg],src=S.fwSs,i=clamp(S.fwS,0,FWSC.length-1);let fail=-1;
  if(src==='un'||src==='sp')fail=0;else if(m[1]===1)fail=1;else if(m[1]===2&&src==='hn')fail=2;else if(m[1]==='F')fail=3;
  const items=FWSC.map((c,q)=>{let st='idle';const last=q===FWSC.length-1;if(last){st=i>=q?(fail>=0?'fail':'ok'):'idle';}else if(fail<0||q<fail)st=q<=i?'ok':'idle';else if(q===fail)st=i>=q?'fail':'idle';if(q===i&&st!=='fail')st='cur';return{n:c[0],sub:c[1].slice(0,66)+(c[1].length>66?'…':''),st,k:'fw'};});
  const why=fail<0?'Cho qua: nguồn hợp lệ, bản tin đúng ngữ cảnh, tốc độ bình thường.':fail===0?'Chặn: nguồn không thuộc danh sách đối tác hoặc giả địa chỉ mạng nhà.':fail===1?'Chặn: bản tin loại 1 chỉ dùng nội bộ, không được tới từ ngoài.':fail===2?'Chặn: bản tin cần ngữ cảnh, nhưng thuê bao không đang ở mạng của nguồn.':'Giới hạn hoặc chặn: tốc độ bất thường.';
  return{fig:fwPipe(items,'Các kiểm tra của tường lửa SS7 và Diameter'),hint:'Bản tin dừng ở kiểm tra đầu tiên không đạt; mục cuối là kết luận.',
   out:prKv([['Bản tin',esc(m[0])],['Loại (ví dụ)',m[1]===1?'loại 1, chỉ nội bộ':m[1]===2?'loại 2, theo ngữ cảnh':'cần giới hạn tốc độ'],['Nguồn',esc(FWSS.find(x=>x[0]===src)[1])],['Kết luận',`<b>${why}</b>`]]),cap:why,
   info:`<h3>${esc(FWSC[i][0])}</h3><p>${FWSC[i][1]}.</p><p>${m[2]}</p><p class="note">Phân loại mang tinh thần GSMA FS.11 (SS7) và FS.19 (Diameter) nhưng chỉ là ví dụ minh hoạ, danh mục thật dài hơn và cần đối chiếu tài liệu. Tường lửa báo hiệu cần dữ liệu vị trí thuê bao (từ HLR/HSS) để kiểm tra ngữ cảnh, và phải bao quát cả SMS home routing.</p>`,
   tt:'Bản tin mẫu và phân loại',tb:tbl(['Bản tin','Loại (ví dụ)','Ghi chú'],FWSM.map(x=>[esc(x[0]),x[1]===1?'loại 1':x[1]===2?'loại 2':'tốc độ',x[2]]),S.fwSg)};};
const fwSip=()=>({pts:[['SIP ALG trên tường lửa thường gây lỗi','SIP ALG (Application Layer Gateway) đọc và viết lại địa chỉ trong SIP và SDP để NAT hoạt động. Khi viết sai hoặc không hiểu phần mở rộng IMS (Path, Service-Route, Record-Route, P-Asserted-Identity) thì cuộc gọi bị hỏng: tiếng một chiều, đăng ký rớt, INVITE không tới. Trong mạng IMS thật nên tắt SIP ALG và dùng SBC.'],
  ['SBC làm gì','SBC (Session Border Controller) che cấu trúc mạng (topology hiding), chuẩn hoá SIP, kiểm soát phiên (số phiên, tốc độ), xử lý NAT traversal, chuyển mã media, và chặn tấn công SIP (quét, INVITE flood, giả mạo). Là phần tử bắt buộc ở biên liên mạng IMS (IBCF).'],
  ['Bảo vệ SIP','TLS cho báo hiệu, SRTP cho media; giới hạn số INVITE và REGISTER mỗi giây theo nguồn; chặn User-Agent bất thường; xác thực Digest hoặc IMS AKA; xác thực P-Asserted-Identity chống giả số gọi (STIR/SHAKEN ở Bắc Mỹ).'],
  ['Cuộc gọi khẩn cấp','Không được chặn nhầm: tường lửa và SBC phải để lưu lượng cuộc gọi khẩn cấp đi qua kể cả khi bị giới hạn tốc độ.']],
 tb:()=>['Dấu hiệu lỗi do SIP ALG và cách kiểm tra',['Triệu chứng','Nguyên nhân thường gặp','Cách kiểm tra'],[['Gọi được nhưng một chiều không nghe','SDP bị viết lại sai địa chỉ media','Bắt gói hai phía, so sánh dòng c= và m= trong SDP'],['Đăng ký IMS rớt định kỳ','ALG viết sai Contact hoặc hết hạn mục NAT','So sánh Contact trước và sau tường lửa; kiểm tra thời hạn mục NAT'],['INVITE bị 4xx hoặc không có phản hồi','ALG làm hỏng tiêu đề mở rộng','Tắt ALG thử; xem tiêu đề Via và Record-Route']]]});
const fwSepp=()=>({nodes:[['vn',4,78,64,30,'V-AMF','vPLMN'],['vs',100,78,64,30,'vSEPP','vPLMN'],['ip',196,78,64,30,'IPX','trung gian'],['hs',292,78,64,30,'hSEPP','hPLMN'],['hn',292,8,64,30,'AUSF, UDM','hPLMN'],['pl',100,8,64,30,'Chính sách','lọc, ẩn topo']],
 links:[['vn','vs','SBI'],['vs','ip','N32'],['ip','hs','N32'],['hs','hn','SBI'],['pl','vs','']],
 steps:[[['vs','hs'],[],'N32-c: bắt tay hai SEPP','Hai SEPP lập kênh điều khiển N32-c bằng TLS: xác thực lẫn nhau bằng chứng chỉ, thoả thuận khả năng bảo mật (dùng TLS hay PRINS cho bản tin ứng dụng) và các chính sách.',[['Kênh','N32-c, HTTP/2 trên TLS'],['Chuẩn','3GPP TS 33.501 mục 13, TS 29.573']]],
  [['vn','vs'],['vn-vs'],'Bản tin SBI từ V-AMF','Bản tin dịch vụ (ví dụ Nausf_UEAuthentication) từ mạng khách tới SEPP khách. SEPP kiểm tra bản tin, áp chính sách rồi chuyển qua N32-f.'],
  [['vs','ip','hs'],['vs-ip','ip-hs'],'N32-f: chuyển tiếp bản tin ứng dụng','Hai chế độ: nếu hai SEPP nối trực tiếp thì TLS đầu cuối; nếu có IPX ở giữa cần sửa tiêu đề thì dùng PRINS: bảo vệ ở tầng ứng dụng bằng JWS (ký) và JWE (mã hoá từng phần), cho phép IPX sửa một số trường có kiểm soát và ký sửa đổi.',[['TLS','bảo vệ từng chặng, IPX nhìn thấy nội dung'],['PRINS','JWS + JWE, bảo vệ cả khi qua IPX']]],
  [['hs','hn'],['hs-hn'],'hSEPP kiểm tra và chuyển vào mạng nhà','hSEPP xác minh chữ ký/giải mã, áp chính sách (danh sách PLMN được phép, giới hạn tốc độ, lọc theo loại bản tin), ẩn cấu trúc mạng nhà rồi chuyển tới AUSF/UDM.'],
  [['pl','vs'],['pl-vs'],'Chính sách và nhật ký','SEPP là điểm duy nhất để áp chính sách interconnect 5G: danh sách bản tin cho phép, giới hạn theo đối tác, chống giả mạo, ghi log để điều tra. Thay thế vai trò DEA ở 4G.']]});
txSel('fwAt','Kiểu tấn công',[['syn','SYN flood (TCP, gói nhỏ)'],['dns','Khuếch đại DNS (UDP, gói lớn)'],['gtp','GTP-C Echo flood (gói nhỏ)'],['sip','SIP INVITE flood (gói vừa)']],'syn');
txSel('fwAg','Lưu lượng tấn công',[[1,'1 Gb/s'],[5,'5 Gb/s'],[20,'20 Gb/s'],[50,'50 Gb/s'],[100,'100 Gb/s'],[200,'200 Gb/s'],[400,'400 Gb/s']],50);
txSel('fwTr','Đường thuê Internet',[[10,'10 Gb/s'],[40,'40 Gb/s'],[100,'100 Gb/s'],[400,'400 Gb/s']],100);
txSel('fwFw','Băng thông xử lý tường lửa Gi',[[10,'10 Gb/s'],[40,'40 Gb/s'],[100,'100 Gb/s'],[200,'200 Gb/s']],100);
txSel('fwPp','Giới hạn gói/giây của tường lửa',[[5,'5 triệu pps'],[20,'20 triệu pps'],[50,'50 triệu pps'],[150,'150 triệu pps']],20);
txSel('fwSc','Lọc DDoS ở nhà cung cấp (scrubbing, giả định 200 Gb/s)',[['no','Không'],['yes','Có']],'no');
txSl('fwBl','Lưu lượng hợp lệ thường ngày',1,80,1,20,v=>v+' Gb/s');
const fwDdos=()=>{const A=+S.fwAg,T=+S.fwTr,F=+S.fwFw,P=+S.fwPp,L=S.fwBl,sc=S.fwSc==='yes',size={syn:64,dns:1200,gtp:100,sip:700}[S.fwAt],name={syn:'SYN flood',dns:'khuếch đại DNS',gtp:'GTP-C Echo flood',sip:'SIP INVITE flood'}[S.fwAt];
  const A2=sc?(A<=200?A*0.05:A-190):A,pps=A2*1e9/(8*size)/1e6,tl=(A2+L)/T*100,fl=(A2+L)/F*100,pl=pps/P*100;
  const items=[['Lọc nhà cung cấp',sc?(A<=200?5:Math.min(100,A2/A*100)):100,sc?V_('k1'):V_('muted')],['Đường thuê',Math.min(tl,100),tl>100?V_('warn'):V_('up')],['Băng thông tường lửa',Math.min(fl,100),fl>100?V_('warn'):V_('up')],['Gói/giây tường lửa',Math.min(pl,100),pl>100?V_('warn'):V_('up')]];
  const bad=[tl>100&&'đường thuê',fl>100&&'băng thông tường lửa',pl>100&&'giới hạn gói/giây'].filter(Boolean);
  const fix={syn:'SYN cookies hoặc SYN proxy trên tường lửa, giới hạn kết nối bán mở, lọc ở nhà cung cấp.',dns:'Lọc cổng UDP nguồn 53 vào, chặn truy vấn đệ quy từ ngoài, Response Rate Limiting trên DNS, scrubbing.',gtp:'Giới hạn tốc độ GTP-C mỗi đối tác trên tường lửa GTP, chỉ cho phép địa chỉ đối tác đã ký.',sip:'SBC giới hạn INVITE mỗi giây theo nguồn, xác thực, chặn nguồn lạ.'}[S.fwAt];
  return{fig:prBars(items.map(x=>[x[0],x[1],x[2]]),100,' %','Mức dùng từng tầng phòng thủ khi bị tấn công'),hint:'Cột đầy (100 %) và màu cam là tầng bị quá tải; các cột đã tính sau khi lọc ở nhà cung cấp nếu bật.',
   out:prKv([['Tấn công',`${name}, ${A} Gb/s (~${txP(A*1e9/(8*size)/1e6,1)} triệu pps thô)`],['Còn lại sau lọc nhà cung cấp',txP(A2,1)+' Gb/s ('+txP(pps,1)+' triệu pps)'],['Đường thuê',txP(tl,0)+' %'],['Băng thông tường lửa',txP(fl,0)+' %'],['Gói/giây tường lửa',txP(pl,0)+' %'],['Kết luận',bad.length?`<b>Quá tải:</b> ${bad.join(', ')}`:'<b>Chịu được</b>']]),
   info:`<p>Gói nhỏ (SYN, Echo) làm nghẽn <b>gói/giây</b> trước khi nghẽn băng thông; gói lớn (khuếch đại DNS) làm nghẽn <b>băng thông</b> trước. Tầng bị quá tải đầu tiên cũng chặn luôn lưu lượng hợp lệ (${L} Gb/s). Biện pháp cho ${name}: ${fix}</p><p>Hạ tầng nên có kế hoạch ứng phó: ngưỡng cảnh báo, quy trình báo nhà cung cấp, BGP FlowSpec và RTBH (chặn theo đích) cho trường hợp cực đoan (chấp nhận hy sinh một địa chỉ để cứu hệ thống). Mô hình giản lược, không tính kết nối mới mỗi giây hay CPU của tường lửa, và giả định lọc nhà cung cấp loại 95 % tấn công khi trong ngưỡng.</p>`};};
Object.assign(GX.fw.views.sim.items,{
 run:{n:'Một gói đi qua gateway: từng giai đoạn và từng luật',spec:'Check Point Access Control; RFC 6888 (CGNAT); RFC 3704 (BCP 84, chống giả mạo nguồn)',kind:'custom',ctl:['fwPre','fwSrc','fwDst','fwSvc','fwSt','fwSp','fwIp'],cnt:()=>fwTrace().T.length,idx:'mô phỏng gói bộ luật tường lửa chống giả mạo bảng kết nối luật NAT Threat Prevention IPS Accept Drop cleanup stealth',r:fwSim,
  onCtl:k=>{if(k==='fwPre'){const p=FWPRE.find(x=>x[0]===S.fwPre);if(p&&p[2]){S.fwSrc=p[2];S.fwDst=p[3];S.fwSvc=p[4];S.fwSt='new';S.fwSp='no';S.fwIp='no';}}else if(['fwSrc','fwDst','fwSvc'].includes(k))S.fwPre='cus';S.fwS=0;}}});
Object.assign(GX.fw.views.mob.items,{
 map:{n:'Điểm đặt bảo vệ trong mạng di động',spec:'3GPP TS 33.210, 33.310, 33.501; GSMA FS.11, FS.19, FS.20, FS.21',kind:'flow',g:fwMap},
 gtp:{n:'Tường lửa GTP: từng kiểm tra',spec:'GSMA FS.20; 3GPP TS 29.060, 29.274, 29.281',kind:'custom',ctl:['fwGm'],cnt:()=>FWGC.length,idx:'tường lửa GTP GTP-C GTP-U TEID IMSI PLMN GTP-in-GTP Echo flood roaming S8 FS.20',r:fwGtp,onCtl:()=>{S.fwS=0;}},
 sig:{n:'Tường lửa SS7 và Diameter',spec:'GSMA FS.11, FS.19; 3GPP TS 29.002, 29.272',kind:'custom',ctl:['fwSg','fwSs'],cnt:()=>FWSC.length,idx:'tường lửa SS7 Diameter MAP ATI PSI UL SRI-SM ULR CLR AIR IDR loại 1 loại 2 FS.11 FS.19',r:fwSig,onCtl:()=>{S.fwS=0;}},
 sip:{n:'SIP ALG và SBC',spec:'RFC 3261; 3GPP TS 23.228, 24.229; RFC 4787 (NAT UDP)',kind:'text',pts:fwSip().pts,tb:fwSip().tb},
 sepp:{n:'SEPP và N32 cho roaming 5G',spec:'3GPP TS 33.501 mục 13; TS 29.573; GSMA FS.21',kind:'flow',g:fwSepp},
 ddos:{n:'DDoS: tầng nào quá tải trước',spec:'RFC 4732, 4987 (SYN), 5575 (FlowSpec), 3882 (RTBH); GSMA FS.21',kind:'custom',ctl:['fwAt','fwAg','fwTr','fwFw','fwPp','fwSc','fwBl'],cnt:()=>1,idx:'DDoS SYN flood khuếch đại DNS GTP-C Echo flood SIP INVITE flood scrubbing FlowSpec RTBH gói trên giây băng thông',r:fwDdos}});
GX.fw.views.cmp.items.cfg.onCtl=()=>{};

/* ===== THẺ MACHINE LEARNING (đợt ML-1) ===== */
/* =====================================================================
   THẺ ML — ĐỢT ML-1 · LÕI: RNG, dữ liệu tổng hợp, đại số nhỏ, chỉ số, vẽ
   Mọi dữ liệu trong thẻ này là dữ liệu tổng hợp do mã tự sinh (có seed).
   ===================================================================== */
const ML={sims:{},v:{},pt:'th',quiz:{},run:null,addMode:'off',fail:{},sweep:{}};
const mlClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const mlSum=a=>{let s=0;for(let i=0;i<a.length;i++)s+=a[i];return s;};
const mlMean=a=>a.length?mlSum(a)/a.length:0;
const mlVar=a=>{const m=mlMean(a);let s=0;for(const v of a)s+=(v-m)*(v-m);return a.length?s/a.length:0;};
const mlStd=a=>Math.sqrt(mlVar(a));
const mlFin=v=>typeof v==='number'&&isFinite(v);
