   for(let j=0;j<show;j++){const f=F[j],y=22+j*rh,vs=new Set(f.va),ts=new Set(f.tr);for(let t=0;t<v.n;t++){const i=ord[t];g.fillStyle=vs.has(i)?C.cls[2]:ts.has(i)?C.cls[0]:C.line;g.globalAlpha=vs.has(i)||ts.has(i)?0.9:0.4;g.fillRect(L+t*W/v.n,y,Math.max(1,W/v.n-0.6),rh-3);}g.globalAlpha=1;
     g.fillStyle=C.ink;g.textAlign='right';g.textBaseline='middle';mlFont(g,10);g.fillText((j+1)+': '+mlF(cur[j],3),L-5,y+rh/2-1);}
   if(F.length>show){g.fillStyle=C.muted;g.textAlign='left';g.fillText('… và '+(F.length-show)+' lần nữa',L,22+show*rh+8);}
