  s.kv=()=>[['Số lần huấn luyện',F.length],['RMSE CV ở bậc '+v.deg,mlF(mlMean(cur),4)+' ± '+mlF(mlStd(cur),4)],['Bậc tốt nhất theo CV',best],['Bậc tốt nhất theo hold-out 1 lần',1+hold.indexOf(Math.min(...hold))],['-'],['Hold-out 1 lần ở bậc '+v.deg,mlF(hold[v.deg-1],4)],['Chênh lệch hold-out so với CV',mlF(hold[v.deg-1]-mlMean(cur),4)]];
