mlItem('mcls',{z:'found',fam:'Đánh giá',n:'Chỉ số phân loại: confusion matrix, precision/recall/F1, ROC, PR',short:'ROC, PR, F1',nc:3,nostep:true,hs:[190,190,190],
 sweep:{title:'ngưỡng quyết định',k:'thr',label:'Ngưỡng',vals:[-1,0,0.5,1,1.5,2,3],cols:[['Precision',s=>mlF(s.pr,3)],['Recall',s=>mlF(s.rc,3)],['F1',s=>mlF(s.f1,3)],['Accuracy',s=>mlPct(s.acc)]]},
 P:[mlR('sep','Độ tách hai lớp (d′)',0,4,0.1,2),mlL('prev','Tỷ lệ lớp dương',0.005,0.5,0.1),mlR('n','Số mẫu',200,5000,100,1500),mlR('thr','Ngưỡng quyết định',-3,6,0.05,1,{live:true}),mlR('beta','β của Fβ',0.25,4,0.25,1,{live:true}),mlPSEED()],
 mk(v){const r=mlRng(v.seed*31+9),sc=[],y=[];for(let i=0;i<v.n;i++){const pos=r.u()<v.prev;y.push(pos?1:0);sc.push(r.n()+(pos?v.sep:0));}
  const roc=mlRoc(sc,y),P=y.filter(a=>a===1).length,s=mlStatic({thr:v.thr,beta:v.beta});
  const met=()=>{const p=sc.map(q=>q>=s.thr?1:0),c=mlConf(y,p,1),m=mlPRF(c),b2=s.beta*s.beta,fb=(1+b2)*m.pr*m.rc/Math.max(1e-12,b2*m.pr+m.rc),den=Math.sqrt((c.tp+c.fp)*(c.tp+c.fn)*(c.tn+c.fp)*(c.tn+c.fn)),mcc=den?(c.tp*c.tn-c.fp*c.fn)/den:0;return{c,m,fb,mcc,bal:(m.rc+m.spec)/2};};
  s.set=(k,val)=>{s[k]=val;};
  s.draw=cv=>{const C=mlCols(),lo=-4,hi=v.sep+4,nb=44,bw=(hi-lo)/nb,h0=new Array(nb).fill(0),h1=new Array(nb).fill(0);sc.forEach((q,i)=>{const b=mlClamp(Math.floor((q-lo)/bw),0,nb-1);(y[i]?h1:h0)[b]++;});
   const pl=mlPlot(cv[0],[lo,hi,0,Math.max(...h0,...h1)*1.12]);pl.frame();const g=pl.g;for(let b=0;b<nb;b++){const x0=lo+b*bw,mid=x0+bw/2;[[h0,0],[h1,1]].forEach(([h,k])=>{g.globalAlpha=mid>=s.thr?0.85:0.35;g.fillStyle=C.cls[k];g.fillRect(pl.px(x0)+1,pl.py(h[b]),pl.px(x0+bw)-pl.px(x0)-1,pl.py(0)-pl.py(h[b]));});}g.globalAlpha=1;
   pl.line([s.thr,0],[s.thr,pl.B[3]],C.ink,2);pl.label(pl.pad.l+6,pl.pad.t+9,'Điểm số mô hình · xanh dương = lớp âm, hồng = lớp dương; phần sáng đậm = bị dự đoán là dương',C.muted,'left',10);
   const r1=mlPlot(cv[1],[0,1,0,1]);r1.frame();r1.line([0,0],[1,1],C.muted,1,[4,3]);r1.poly(roc.fpr.map((f,i)=>[f,roc.tpr[i]]),C.cls[0],2.2);const M=met();r1.pts([[1-M.m.spec,M.m.rc]],null,{col:()=>C.cls[1],r:5.5});r1.label(r1.pad.l+6,r1.pad.t+9,'ROC · AUC = '+mlF(roc.auc,3)+' · trục ngang: FPR, dọc: TPR',C.muted,'left',10);
   const r2=mlPlot(cv[2],[0,1,0,1.02]);r2.frame();r2.line([0,v.prev],[1,v.prev],C.muted,1,[4,3]);const pr=[];for(let i=0;i<roc.rc.length;i++)pr.push([roc.rc[i],roc.pr[i]]);r2.poly(pr,C.cls[2],2.2);r2.pts([[M.m.rc,M.m.pr]],null,{col:()=>C.cls[1],r:5.5});r2.label(r2.pad.l+6,r2.pad.t+9,'PR · AP = '+mlF(roc.ap,3)+' · đường đứt: mức ngẫu nhiên = tỷ lệ dương · ngang: recall, dọc: precision',C.muted,'left',10);};
  s.note=()=>{const M=met(),c=M.c;return`<div class="scroll"><table class="mlcm"><tr><th></th><th>Dự đoán dương</th><th>Dự đoán âm</th></tr><tr><th>Thật dương (${P})</th><td class="ok">TP = ${c.tp}</td><td class="bad">FN = ${c.fn}</td></tr><tr><th>Thật âm (${v.n-P})</th><td class="bad">FP = ${c.fp}</td><td class="ok">TN = ${c.tn}</td></tr></table></div>`;};
  s.kv=()=>{const M=met();return[['Accuracy',mlPct(M.m.acc)],['Precision',mlF(M.m.pr,3)],['Recall (TPR)',mlF(M.m.rc,3)],['Specificity (TNR)',mlF(M.m.spec,3)],['F1',mlF(M.m.f1,3)],['F'+mlF(s.beta,2)+' (β = '+mlF(s.beta,2)+')',mlF(M.fb,3)],['Balanced accuracy',mlF(M.bal,3)],['MCC',mlF(M.mcc,3)],['-'],['ROC-AUC',mlF(roc.auc,3)],['PR-AUC (AP)',mlF(roc.ap,3)],['Số mẫu dương / tổng',P+' / '+v.n]];};
  s.diag=()=>{const M=met();if(v.prev<0.1&&M.m.acc>0.9&&M.m.rc<0.5)return['warn','<b>Accuracy đẹp nhưng vô dụng.</b> Accuracy '+mlPct(M.m.acc)+' chủ yếu do đoán “âm” cho tất cả; recall chỉ '+mlF(M.m.rc,2)+'. Với lớp hiếm hãy nhìn PR và F1.'];if(roc.auc>0.95&&roc.ap<0.5)return['warn','<b>ROC-AUC lạc quan.</b> AUC '+mlF(roc.auc,2)+' nhưng AP chỉ '+mlF(roc.ap,2)+': khi lớp dương hiếm, nhiều báo giả vẫn làm precision thấp.'];return null;};
  s.sum=()=>{const M=met();return{pr:M.m.pr,rc:M.m.rc,f1:M.m.f1,acc:M.m.acc};};return s;}});
