  const lay=nd=>{if(nd.leaf){pos[nd.id]=[leaf++,nd.depth];return;}lay(nodes[nd.l]);lay(nodes[nd.r]);pos[nd.id]=[(pos[nd.l][0]+pos[nd.r][0])/2,nd.depth];};lay(T.root);
  const W=c.w-16,rh=Math.min(46,(c.h-24)/(depth+1)),bw=Math.min(54,W/Math.max(nl,1)-2),X=i=>8+(i+0.5)*W/Math.max(nl,1),Y=d=>16+d*rh;
  g.strokeStyle=C.muted;g.lineWidth=1.2;nodes.forEach(nd=>{if(nd.leaf)return;[nd.l,nd.r].forEach((q,k)=>{g.beginPath();g.moveTo(X(pos[nd.id][0]),Y(nd.depth)+6);g.lineTo(X(pos[q][0]),Y(nodes[q].depth)-6);g.stroke();});});
  nodes.forEach(nd=>{const x=X(pos[nd.id][0]),y=Y(nd.depth),maj=mlArgmax(nd.cnt),hl=hi===nd.id;if(nd.leaf){const w=Math.max(6,Math.min(bw,28)),tot=mlSum(nd.cnt)||1;let xx=x-w/2;nd.cnt.forEach((q,k)=>{const ww=w*q/tot;g.fillStyle=C.cls[k%6];g.fillRect(xx,y-6,ww,12);xx+=ww;});g.strokeStyle=hl?C.warn:C.ink;g.lineWidth=hl?2.4:1;g.setLineDash(hl?[3,2]:[]);g.strokeRect(x-w/2,y-6,w,12);g.setLineDash([]);if(nl<=14){g.fillStyle=C.muted;mlFont(g,9);g.textAlign='center';g.textBaseline='top';g.fillText(String(nd.n),x,y+8);}}
    else{g.fillStyle=C.panel2;g.strokeStyle=C.ink;g.lineWidth=1.2;const w=Math.min(60,Math.max(34,bw+10));g.beginPath();g.roundRect(x-w/2,y-7,w,14,4);g.fill();g.stroke();g.fillStyle=C.ink;mlFont(g,nl>16?8:9.5,true);g.textAlign='center';g.textBaseline='middle';g.fillText((nd.sp.f===0?'x₁':nd.sp.f===1?'x₂':'z'+nd.sp.f)+'≤'+mlF(nd.sp.t,2),x,y);}});
  const nx=nodes.filter(n=>n.leaf&&n.sp).sort((a,b)=>b.sp.wg-a.sp.wg)[0];if(nx){const x=X(pos[nx.id][0]),y=Y(nx.depth);g.strokeStyle=C.warn;g.setLineDash([3,2]);g.lineWidth=2;g.strokeRect(x-14,y-9,28,18);g.setLineDash([]);}
