function mlEnsHeat(pl,s,rowf){const cell=(ML.cell||6)+2,gs=pl.gs(cell),gw=gs.gw,gh=gs.gh,K=s.K,T=s.eng.trees||s.eng.st.map(q=>q.tr);let c=s._hc;if(!c||c.gw!==gw||c.gh!==gh||c.eng!==s.eng||c.nT>T.length||s.eng.st){c=s._hc={gw,gh,eng:s.eng,nT:0,sum:new Float32Array(gw*gh*K)};}
  if(s.eng.st){let q=0;pl.heat((x,y)=>s.eng.p(rowf(x,y)),K,{cell});return;}
  for(;c.nT<T.length;c.nT++){const t=T[c.nT];let q=0;for(let j=0;j<gh;j++)for(let i=0;i<gw;i++){const x=-1.1+(i+0.5)/gw*2.2,y=1.1-(j+0.5)/gh*2.2,p=t.p(rowf(x,y));for(let k=0;k<K;k++)c.sum[q*K+k]+=p[k];q++;}}
  let q=0;pl.heat(()=>{const o=q++*K,a=[];for(let k=0;k<K;k++)a.push(c.sum[o+k]/Math.max(1,c.nT));return a;},K,{cell});}
