const NBV=['LOS','BER','quang','CRC','VSWR','RSRP','SINR','PRACH','RLF','handover','alarm','reset'],NBT=[[0.14,0.16,0.14,0.12,0.04,0.02,0.02,0.01,0.02,0.01,0.2,0.12],[0.01,0.02,0.01,0.02,0.1,0.18,0.17,0.12,0.12,0.1,0.1,0.05]].map(a=>{const s=mlSum(a);return a.map(x=>x/s);});
function mlNBmn(v){const r=mlRng(v.seed*17+5),cnt=[0,1].map(()=>new Array(12).fill(0)),nd=[v.nd,v.nd];
  for(let c=0;c<2;c++)for(let d=0;d<v.nd;d++)for(let t=0;t<v.len;t++){let u=r.u(),k=0;for(;k<11;k++){u-=NBT[c][k];if(u<=0)break;}cnt[c][k]++;}
  const th=cnt.map(a=>{const s=mlSum(a)+v.alpha*12;return a.map(q=>(q+v.alpha)/Math.max(s,1e-12));}),llr=th[1].map((q,k)=>Math.log(Math.max(q,1e-12))-Math.log(Math.max(th[0][k],1e-12))),s=mlStatic({msg:[0,0,0,0,0,2,2,0,0,0,0,0],th,llr});
  s.post=()=>{const lp=[0,1].map(c=>Math.log(0.5)+mlSum(s.msg.map((m,k)=>m*Math.log(Math.max(th[c][k],1e-12)))));return mlSoft(lp);};
  s.draw=cv=>{const C=mlCols();mlBars(cv[0],NBV,llr.map(q=>mlClamp(q,-6,6)),{title:'ln[P(từ | vô tuyến) / P(từ | truyền dẫn)] — chạm một cột để thêm từ vào tin nhắn',col:i=>llr[i]>=0?C.cls[1]:C.cls[0],rot:true,padL:30});
   const p=s.post();mlBars(cv[1],['Truyền dẫn','Vô tuyến'],p,{title:'Xác suất hậu nghiệm của tin nhắn đang soạn',max:1,min:0,col:i=>C.cls[i===0?0:1]});};
  s.click=(x,y,i)=>{if(i!==0)return false;const c=document.getElementById('mlC0'),w=(c._w||300)-44,k=Math.floor((x-36)/(w/12));if(k>=0&&k<12){s.msg[k]=(s.msg[k]+1)%6;return true;}return false;};
  s.note=()=>`<p><b>Tin nhắn:</b> ${s.msg.map((m,k)=>m?NBV[k]+'×'+m:'').filter(Boolean).join(', ')||'(trống)'} · <button type="button" class="btn sm" data-ml="clrmsg">Xoá tin nhắn</button></p><p class="note">Chạm cột để tăng số lần xuất hiện của từ (0 đến 5, rồi về 0).</p>`;
  s.kv=()=>{const p=s.post();return[['P(vô tuyến | tin nhắn)',mlF(p[1],4)],['P(truyền dẫn | tin nhắn)',mlF(p[0],4)],['Laplace α',v.alpha],['Số tài liệu mỗi lớp × độ dài',v.nd+' × '+v.len],['Từ có xác suất = 0 ở một lớp',th.reduce((a,t)=>a+t.filter(q=>q===0).length,0)]];};
  s.diag=()=>v.alpha===0&&th.some(t=>t.some(q=>q===0))?['bad','<b>Xác suất bằng 0.</b> Với α = 0, một từ chưa từng xuất hiện trong một lớp làm P = 0 và triệt tiêu toàn bộ tích. Dùng làm mượt Laplace (α > 0).']:null;
  s.sum=()=>({});return s;}
