const RS_P=(extra)=>[mlR('dens','Mật độ ma trận đã biết',0.1,0.8,0.05,0.45)].concat(extra).concat([mlR('u','Thuê bao xem chi tiết',0,23,1,0,{live:true}),mlR('N','Số dịch vụ gợi ý N',1,8,1,3),mlPSEED()]);
