 s.draw=cv=>{const C=mlCols();mlRsGrid(cv[0],D,P,s.u,C);s.top=mlRsUserBars(cv[1],D,P,s.u,v.N,C);if(cv[2]&&ex.chart)ex.chart(cv[2],s);};
