 s.diag=()=>{const m=mlRsEval(D,P,v.N),b=mlRsEval(D,D.R.map(()=>new Array(D.ni).fill(D.st.mu)),v.N).rmse;if(v.dens<0.2)return['warn','<b>Ma trận quá thưa ('+mlPct(v.dens)+').</b> Ít điểm để học nên sai số gần mức đoán trung bình; đây là vấn đề cốt lõi của hệ gợi ý.'];if(ex.diag){const d=ex.diag(s,m,b);if(d)return d;}return m.rmse>b?['warn','<b>Kém hơn đoán trung bình.</b> RMSE '+mlF(m.rmse,3)+' > '+mlF(b,3)+': mô hình đang quá khớp hoặc thiếu dữ liệu.']:null;};
