   const pl=mlPlot(cv[2],[-1.4,1.4,-1.4,1.4]);pl.frame();const xs=Pu.map(p=>p[0]||0),ys=Pu.map(p=>p[1]||0),sc=Math.max(1e-6,...xs.map(Math.abs),...ys.map(Math.abs));pl.pts(Pu.map((p,i)=>[(p[0]||0)/sc,(p[1]||0)/sc]),D.tp,{r:4});
