  s.kv=()=>[['Epoch',s.it],['RMSE huấn luyện',h.tr.length?mlF(mlLast(h.tr),3):'—'],['RMSE kiểm định',h.te.length?mlF(mlLast(h.te),3):'—'],['Số tham số / số điểm đã biết',k*(D.nu+D.ni)+' / '+D.obs.flat().reduce((a,b)=>a+b,0)],['Phương pháp',v.method==='als'?'ALS: mỗi bước giải hệ tuyến tính k×k':'SGD: cập nhật từng điểm']];
