const MLALLDS=['lin','xor','moons','circles','spiral','noisy','imb','blobs3','pin3','blobs5','aniso','uneq'];
mlItem('lab_gen',{z:'lab',fam:'Công cụ',n:'Bộ sinh dữ liệu tổng hợp',short:'Sinh dữ liệu',nc:2,nostep:true,hs:[300,140],
 P:[mlS('ds','Dạng dữ liệu',MLALLDS.map(k=>[k,ML_DS[k]]),'moons'),mlR('n','Số mẫu',40,1000,10,200),mlPNZ(0.15),mlR('ratio','Tỉ lệ mất cân bằng (lớp 0 : mỗi lớp còn lại)',1,30,1,1),mlR('lbl','Tỉ lệ nhãn bị gán sai (nhiễu nhãn)',0,0.3,0.01,0),mlPSEED()],
 act:{csv(arg,el,sim){const t=sim.csv||'';if(arg==='copy'){try{navigator.clipboard.writeText(t).then(()=>{sim.msg='Đã chép '+sim.n+' dòng vào clipboard.';mlOut();},()=>{sim.msg='Trình duyệt chặn clipboard: dùng nút tải xuống.';mlOut();});}catch(e){sim.msg='Trình duyệt chặn clipboard: dùng nút tải xuống.';}}
   else{try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download='du-lieu-tong-hop.csv';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},500);sim.msg='Đã tải xuống du-lieu-tong-hop.csv.';}catch(e){sim.msg='Không tải được: '+e.message;}}}},
 mk(v){let D=mlData(v.ds,v.n,v.nz,v.seed);const r=mlRng(v.seed*31+5);
  if(v.ratio>1&&D.K>=2){const keep=[];let c0=0;D.y.forEach(q=>{if(q===0)c0++;});const k=Math.max(2,Math.round(c0/v.ratio));let kk=0;D.X.forEach((p,i)=>{if(D.y[i]===0)keep.push(i);else if(kk<k*(D.K-1)||r.u()<0.0){keep.push(i);kk++;}});D={X:keep.map(i=>D.X[i]),y:keep.map(i=>D.y[i]),K:D.K,name:D.name,kind:D.kind};}
  const y=D.y.slice();if(v.lbl>0)for(let i=0;i<y.length;i++)if(r.u()<v.lbl)y[i]=(y[i]+1+r.int(Math.max(1,D.K-1)))%D.K;
  const s=mlStatic({n:D.X.length,msg:''});s.csv='x1,x2,nhan\n'+D.X.map((p,i)=>p[0].toFixed(4)+','+p[1].toFixed(4)+','+y[i]).join('\n');
  s.draw=cv=>{const pl=mlPlot(cv[0],[-1.1,1.1,-1.1,1.1]);pl.frame();pl.pts(D.X,y,{});pl.label(pl.pad.l+6,pl.pad.t+9,'Dữ liệu tổng hợp: '+ML_DS[v.ds],pl.C.muted,'left',10);const cnt=Array.from({length:D.K},(_,k)=>y.filter(q=>q===k).length);mlBars(cv[1],cnt.map((_,k)=>'lớp '+k),cnt,{title:'Số mẫu mỗi lớp',col:k=>pl.C.cls[k%6]});};
  const cnt=Array.from({length:D.K},(_,k)=>y.filter(q=>q===k).length);
  s.kv=()=>[['Số mẫu',D.X.length],['Số lớp',D.K],['Số mẫu mỗi lớp',cnt.join(' / ')],['Tỉ lệ lớp 0 trên lớp nhỏ nhất',mlF(cnt[0]/Math.max(1,Math.min(...cnt)),2)+' : 1'],['Nhãn bị đổi sai',v.lbl>0?mlPct(v.lbl):'không']];
  s.diag=()=>Math.min(...cnt)/D.X.length<0.1?['warn','<b>Mất cân bằng nặng.</b> Lớp nhỏ nhất chỉ chiếm '+mlPct(Math.min(...cnt)/D.X.length)+': accuracy sẽ gây hiểu lầm; dùng F1/PR-AUC.']:null;
  s.note=()=>`<p class="note">Bản xem trước ${Math.min(6,D.X.length)} dòng đầu của tệp CSV (x1, x2, nhan):</p><div class="scroll"><table>${tbl(['x1','x2','nhãn'],D.X.slice(0,6).map((p,i)=>[p[0].toFixed(3),p[1].toFixed(3),y[i]]))}</table></div><div class="row" style="margin:6px 0"><button type="button" class="btn sm" data-ml="csv:copy">Chép CSV</button><button type="button" class="btn sm" data-ml="csv:dl">Tải CSV</button></div><p class="note">${s.msg||'Dữ liệu hoàn toàn tổng hợp, sinh bằng bộ số ngẫu nhiên có seed nên tái lập được.'}</p>`;
  s.sum=()=>({});return s;}});
