/* --- ML-2: m01_core.js --- */

/* =====================================================================
   THẺ ML — ĐỢT ML-2 · LÕI: autograd tensor nhỏ, bộ tối ưu, mạng dày đặc
   Tất cả tự viết, không thư viện ngoài. Tensor 2 chiều (hàng × cột) lưu Float64Array.
   ===================================================================== */
const ml2={tape:null};
function ml2T(r,c,d){return{r,c,d:d||new Float64Array(r*c),g:null};}
const ml2G=t=>t.g||(t.g=new Float64Array(t.r*t.c));
const ml2K=(r,c,arr)=>ml2T(r,c,Float64Array.from(arr));
function ml2Rand(r,c,rng,sd){const t=ml2T(r,c);for(let i=0;i<t.d.length;i++)t.d[i]=rng.n()*sd;return t;}
function ml2Rows(X){const r=X.length,c=X[0].length,t=ml2T(r,c);for(let i=0;i<r;i++)for(let j=0;j<c;j++)t.d[i*c+j]=X[i][j];return t;}
function ml2Reg(out,back){if(ml2.tape)ml2.tape.push(back);return out;}
function ml2Begin(){ml2.tape=[];}
function ml2Back(loss){const T=ml2.tape;ml2.tape=null;ml2G(loss).fill(0);loss.g[0]=1;for(let i=T.length-1;i>=0;i--)T[i]();}
const ml2Op={
 mm(A,B){const n=A.r,k=A.c,m=B.c,o=ml2T(n,m),a=A.d,b=B.d,c=o.d;
  for(let i=0;i<n;i++)for(let p=0;p<k;p++){const v=a[i*k+p];if(v===0)continue;const bo=p*m,co=i*m;for(let j=0;j<m;j++)c[co+j]+=v*b[bo+j];}
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A),gB=ml2G(B),go=o.g;
   for(let i=0;i<n;i++)for(let p=0;p<k;p++){let s=0;const bo=p*m,go0=i*m;for(let j=0;j<m;j++)s+=go[go0+j]*b[bo+j];gA[i*k+p]+=s;const v=a[i*k+p];if(v!==0)for(let j=0;j<m;j++)gB[bo+j]+=v*go[go0+j];}});},
 mmT(A,B){const n=A.r,k=A.c,m=B.r,o=ml2T(n,m),a=A.d,b=B.d,c=o.d;
  for(let i=0;i<n;i++)for(let j=0;j<m;j++){let s=0;for(let p=0;p<k;p++)s+=a[i*k+p]*b[j*k+p];c[i*m+j]=s;}
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A),gB=ml2G(B),go=o.g;
   for(let i=0;i<n;i++)for(let j=0;j<m;j++){const q=go[i*m+j];if(q===0)continue;for(let p=0;p<k;p++){gA[i*k+p]+=q*b[j*k+p];gB[j*k+p]+=q*a[i*k+p];}}});},
 add(A,B){const o=ml2T(A.r,A.c),br=B.r===1&&A.r>1,N=A.d.length,c=A.c;for(let i=0;i<N;i++)o.d[i]=A.d[i]+B.d[br?i%c:i];
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A),gB=ml2G(B);for(let i=0;i<N;i++){gA[i]+=o.g[i];gB[br?i%c:i]+=o.g[i];}});},
 addCol(A,B){const o=ml2T(A.r,A.c),c=A.c,N=A.d.length;for(let i=0;i<N;i++)o.d[i]=A.d[i]+B.d[(i/c)|0];
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A),gB=ml2G(B);for(let i=0;i<N;i++){gA[i]+=o.g[i];gB[(i/c)|0]+=o.g[i];}});},
 sub(A,B){const o=ml2T(A.r,A.c),N=A.d.length;for(let i=0;i<N;i++)o.d[i]=A.d[i]-B.d[i];
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A),gB=ml2G(B);for(let i=0;i<N;i++){gA[i]+=o.g[i];gB[i]-=o.g[i];}});},
 mul(A,B){const o=ml2T(A.r,A.c),N=A.d.length;for(let i=0;i<N;i++)o.d[i]=A.d[i]*B.d[i];
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A),gB=ml2G(B);for(let i=0;i<N;i++){gA[i]+=o.g[i]*B.d[i];gB[i]+=o.g[i]*A.d[i];}});},
 sc(A,s){const o=ml2T(A.r,A.c),N=A.d.length;for(let i=0;i<N;i++)o.d[i]=A.d[i]*s;
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<N;i++)gA[i]+=o.g[i]*s;});},
 addS(A,s){const o=ml2T(A.r,A.c),N=A.d.length;for(let i=0;i<N;i++)o.d[i]=A.d[i]+s;
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<N;i++)gA[i]+=o.g[i];});},
 fn(A,f,df){const o=ml2T(A.r,A.c),N=A.d.length;for(let i=0;i<N;i++)o.d[i]=f(A.d[i]);
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<N;i++)gA[i]+=o.g[i]*df(A.d[i],o.d[i]);});},
 relu(A){return ml2Op.fn(A,z=>z>0?z:0,z=>z>0?1:0);},
 leaky(A){return ml2Op.fn(A,z=>z>0?z:0.05*z,z=>z>0?1:0.05);},
 tanh(A){return ml2Op.fn(A,Math.tanh,(z,a)=>1-a*a);},
 sig(A){return ml2Op.fn(A,mlSig,(z,a)=>a*(1-a));},
 exp(A){return ml2Op.fn(A,z=>Math.exp(Math.min(30,z)),(z,a)=>z>30?0:a);},
 sq(A){return ml2Op.fn(A,z=>z*z,z=>2*z);},
 gelu(A){return ml2Op.fn(A,z=>0.5*z*(1+Math.tanh(0.79788456*(z+0.044715*z*z*z))),z=>{const u=0.79788456*(z+0.044715*z*z*z),t=Math.tanh(u);return 0.5*(1+t)+0.5*z*(1-t*t)*0.79788456*(1+3*0.044715*z*z);});},
 softplus(A){return ml2Op.fn(A,z=>z>30?z:Math.log1p(Math.exp(z)),z=>mlSig(z));},
 act(A,k){return k==='tanh'?ml2Op.tanh(A):k==='sig'?ml2Op.sig(A):k==='leaky'?ml2Op.leaky(A):k==='gelu'?ml2Op.gelu(A):k==='lin'?A:ml2Op.relu(A);},
 smx(A){const n=A.r,c=A.c,o=ml2T(n,c);for(let i=0;i<n;i++){let m=-1e300;for(let j=0;j<c;j++)m=Math.max(m,A.d[i*c+j]);let s=0;for(let j=0;j<c;j++){const e=Math.exp(Math.min(50,A.d[i*c+j]-m));o.d[i*c+j]=e;s+=e;}for(let j=0;j<c;j++)o.d[i*c+j]/=s;}
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<n;i++){let dot=0;for(let j=0;j<c;j++)dot+=o.g[i*c+j]*o.d[i*c+j];for(let j=0;j<c;j++)gA[i*c+j]+=o.d[i*c+j]*(o.g[i*c+j]-dot);}});},
 rmean(A){const o=ml2T(A.r,1),c=A.c;for(let i=0;i<A.r;i++){let s=0;for(let j=0;j<c;j++)s+=A.d[i*c+j];o.d[i]=s/c;}
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<A.r;i++)for(let j=0;j<c;j++)gA[i*c+j]+=o.g[i]/c;});},
 sumAll(A){const o=ml2T(1,1);let s=0;for(let i=0;i<A.d.length;i++)s+=A.d[i];o.d[0]=s;
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<A.d.length;i++)gA[i]+=o.g[0];});},
 meanAll(A){return ml2Op.sc(ml2Op.sumAll(A),1/Math.max(1,A.d.length));},
 /* mất mát: entropy chéo trung bình theo hàng, nhãn nguyên */
 ce(Z,y,w){const n=Z.r,c=Z.c,P=new Float64Array(n*c),o=ml2T(1,1);let L=0,W=0;
  for(let i=0;i<n;i++){let m=-1e300;for(let j=0;j<c;j++)m=Math.max(m,Z.d[i*c+j]);let s=0;for(let j=0;j<c;j++){const e=Math.exp(Math.min(50,Z.d[i*c+j]-m));P[i*c+j]=e;s+=e;}for(let j=0;j<c;j++)P[i*c+j]/=s;
   const wi=w?w[i]:1;L-=wi*Math.log(Math.max(1e-12,P[i*c+y[i]]));W+=wi;}
  W=W||1;o.d[0]=L/W;
  return ml2Reg(o,()=>{if(!o.g)return;const gZ=ml2G(Z),q=o.g[0]/W;for(let i=0;i<n;i++){const wi=w?w[i]:1;for(let j=0;j<c;j++)gZ[i*c+j]+=q*wi*(P[i*c+j]-(y[i]===j?1:0));}});},
 /* entropy chéo nhị phân trên logit cột 1×; nhãn 0/1 hoặc xác suất mềm */
 bce(Z,y){const n=Z.d.length,o=ml2T(1,1);let L=0;for(let i=0;i<n;i++){const z=Z.d[i];L+=Math.max(z,0)-z*y[i]+Math.log1p(Math.exp(-Math.abs(z)));}o.d[0]=L/n;
  return ml2Reg(o,()=>{if(!o.g)return;const gZ=ml2G(Z);for(let i=0;i<n;i++)gZ[i]+=o.g[0]*(mlSig(Z.d[i])-y[i])/n;});},
 mse(A,Y){const n=A.d.length,o=ml2T(1,1);let L=0;for(let i=0;i<n;i++){const d=A.d[i]-Y[i];L+=d*d;}o.d[0]=L/n;
  return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<n;i++)gA[i]+=o.g[0]*2*(A.d[i]-Y[i])/n;});}};
/* ---------- bộ tối ưu dùng chung ---------- */
const ml2NSC=[3.4445,-4.7750,2.0315];
function ml2NS(G,r,c,steps){/* Newton–Schulz: xấp xỉ thừa số cực U Vᵀ của ma trận G (r×c) */
 let tr=r>c;const R=tr?c:r,C=tr?r:c;let X=new Float64Array(R*C);let nrm=0;for(let i=0;i<G.length;i++)nrm+=G[i]*G[i];nrm=Math.sqrt(nrm)+1e-7;
 for(let i=0;i<R;i++)for(let j=0;j<C;j++)X[i*C+j]=(tr?G[j*c+i]:G[i*c+j])/nrm;
 for(let s=0;s<steps;s++){const A=new Float64Array(R*R);for(let i=0;i<R;i++)for(let j=0;j<R;j++){let q=0;for(let k=0;k<C;k++)q+=X[i*C+k]*X[j*C+k];A[i*R+j]=q;}
  const B=new Float64Array(R*R);for(let i=0;i<R;i++)for(let j=0;j<R;j++){let q=0;for(let k=0;k<R;k++)q+=A[i*R+k]*A[k*R+j];B[i*R+j]=ml2NSC[1]*A[i*R+j]+ml2NSC[2]*q;}
  const Y=new Float64Array(R*C);for(let i=0;i<R;i++)for(let j=0;j<C;j++){let q=ml2NSC[0]*X[i*C+j];for(let k=0;k<R;k++)q+=B[i*R+k]*X[k*C+j];Y[i*C+j]=q;}X=Y;}
 const out=new Float64Array(r*c);for(let i=0;i<R;i++)for(let j=0;j<C;j++){if(tr)out[j*c+i]=X[i*C+j];else out[i*c+j]=X[i*C+j];}return out;}
/* o: {kind, lr, b1, b2, mom, wd, eps, clip}; kinds: sgd, mom, nag, rms, adagrad, adam, adamw, lion, muon, adafactor */
function ml2Opt(P,o){const st=P.map(t=>({m:new Float64Array(t.d.length),v:new Float64Array(t.d.length),vr:new Float64Array(t.r),vc:new Float64Array(t.c)})),k=o.kind||'adam';let t=0;
 const self={lr:o.lr,t:0,
  step(lrScale){t++;self.t=t;const lr=(o.lr)*(lrScale==null?1:lrScale),b1=o.b1==null?0.9:o.b1,b2=o.b2==null?0.999:o.b2,eps=o.eps||1e-8,wd=o.wd||0;let gnorm=0;
   if(o.clip>0){for(const p of P){if(!p.g)continue;for(let i=0;i<p.g.length;i++)gnorm+=p.g[i]*p.g[i];}gnorm=Math.sqrt(gnorm);}
   const cs=o.clip>0&&gnorm>o.clip?o.clip/gnorm:1;
   P.forEach((p,pi)=>{if(!p.g)return;const g=p.g,w=p.d,s=st[pi],N=w.length;if(cs!==1)for(let i=0;i<N;i++)g[i]*=cs;
    if(k==='sgd'){for(let i=0;i<N;i++){w[i]-=lr*(g[i]+wd*w[i]);}}
    else if(k==='mom'||k==='nag'){const mu=o.mom==null?0.9:o.mom;for(let i=0;i<N;i++){s.m[i]=mu*s.m[i]+g[i];w[i]-=lr*(k==='nag'?g[i]+mu*s.m[i]:s.m[i])+lr*wd*w[i];}}
    else if(k==='rms'){const rho=o.rho==null?0.99:o.rho;for(let i=0;i<N;i++){s.v[i]=rho*s.v[i]+(1-rho)*g[i]*g[i];w[i]-=lr*g[i]/(Math.sqrt(s.v[i])+eps);}}
    else if(k==='adagrad'){for(let i=0;i<N;i++){s.v[i]+=g[i]*g[i];w[i]-=lr*g[i]/(Math.sqrt(s.v[i])+eps);}}
    else if(k==='adam'||k==='adamw'){const c1=1-Math.pow(b1,t),c2=1-Math.pow(b2,t);for(let i=0;i<N;i++){s.m[i]=b1*s.m[i]+(1-b1)*g[i];s.v[i]=b2*s.v[i]+(1-b2)*g[i]*g[i];const u=(s.m[i]/c1)/(Math.sqrt(s.v[i]/c2)+eps);w[i]-=lr*(u+(k==='adamw'?wd*w[i]:0));if(k==='adam'&&wd)w[i]-=lr*wd*w[i]*0;}}
    else if(k==='lion'){const bb1=o.b1==null?0.9:o.b1,bb2=o.b2==null?0.99:o.b2;for(let i=0;i<N;i++){const u=Math.sign(bb1*s.m[i]+(1-bb1)*g[i]);w[i]-=lr*(u+wd*w[i]);s.m[i]=bb2*s.m[i]+(1-bb2)*g[i];}}
    else if(k==='muon'){const mu=o.mom==null?0.95:o.mom;for(let i=0;i<N;i++)s.m[i]=mu*s.m[i]+g[i];
     if(p.r>1&&p.c>1){const G2=new Float64Array(N);for(let i=0;i<N;i++)G2[i]=g[i]+mu*s.m[i];const U=ml2NS(G2,p.r,p.c,5),sc=0.2*Math.sqrt(Math.max(p.r,p.c));for(let i=0;i<N;i++)w[i]-=lr*(U[i]*sc+wd*w[i]);}
     else{const c1=1-Math.pow(0.9,t),c2=1-Math.pow(0.999,t);for(let i=0;i<N;i++){s.v[i]=0.999*s.v[i]+0.001*g[i]*g[i];w[i]-=lr*(s.m[i]*(1-mu)/(c1||1))/(Math.sqrt(s.v[i]/c2)+eps);}}}
    else if(k==='adafactor'){const r=p.r,c=p.c;if(r>1&&c>1){const rho=1-Math.pow(t,-0.8),rs=s.vr,cs2=s.vc;for(let i=0;i<r;i++){let q=0;for(let j=0;j<c;j++)q+=g[i*c+j]*g[i*c+j];rs[i]=rho*rs[i]+(1-rho)*q/c;}
      for(let j=0;j<c;j++){let q=0;for(let i=0;i<r;i++)q+=g[i*c+j]*g[i*c+j];cs2[j]=rho*cs2[j]+(1-rho)*q/r;}let mr=0;for(let i=0;i<r;i++)mr+=rs[i];mr=mr/r+1e-30;
      for(let i=0;i<r;i++)for(let j=0;j<c;j++){const vh=rs[i]*cs2[j]/mr;w[i*c+j]-=lr*g[i*c+j]/(Math.sqrt(vh)+eps)+lr*wd*w[i*c+j];}}
     else{const rho=1-Math.pow(t,-0.8);for(let i=0;i<N;i++){s.v[i]=rho*s.v[i]+(1-rho)*g[i]*g[i];w[i]-=lr*g[i]/(Math.sqrt(s.v[i])+eps);}}}
    g.fill(0);});return gnorm;},
  zero(){for(const p of P)if(p.g)p.g.fill(0);},
  memFloats(){let n=0;P.forEach(p=>{const N=p.d.length;n+=k==='sgd'?0:k==='mom'||k==='nag'||k==='lion'||k==='muon'?N:k==='rms'||k==='adagrad'?N:k==='adafactor'?(p.r>1&&p.c>1?p.r+p.c:N):2*N;});return n;}};
 return self;}
/* ---------- lịch tốc độ học: trả hệ số nhân tại bước t (0..T-1) ---------- */
function ml2Sched(kind,t,T,o={}){const wu=Math.max(0,Math.round((o.warm==null?0.05:o.warm)*T)),mn=o.min==null?0.02:o.min;let f=1;
 if(kind==='const')f=1;
 else if(kind==='step')f=Math.pow(0.3,Math.floor(t/Math.max(1,T/3)));
 else if(kind==='linear')f=Math.max(mn,1-t/T);
 else if(kind==='cos')f=mn+(1-mn)*0.5*(1+Math.cos(Math.PI*Math.min(1,t/T)));
 else if(kind==='cyc'){const cyc=Math.max(2,o.cycles||4),ph=((t/T)*cyc)%1;f=mn+(1-mn)*(ph<0.5?ph*2:2-2*ph);}
 else if(kind==='onecycle'){const up=0.3,x=t/T;f=x<up?0.1+0.9*(x/up):mn*0.1+(1-mn*0.1)*0.5*(1+Math.cos(Math.PI*(x-up)/(1-up)));}
 else if(kind==='invsqrt')f=1/Math.sqrt(1+10*t/T);
 if(kind!=='onecycle'&&kind!=='cyc'&&wu>0&&t<wu)f*=(t+1)/wu;return f;}
/* ---------- mạng dày đặc trên autograd ---------- */
function ml2Dense(sizes,act,rng,o={}){const P=[],Ws=[],Bs=[];
 for(let l=0;l<sizes.length-1;l++){const i=sizes[l],j=sizes[l+1],sd=o.init==='xavier'?Math.sqrt(2/(i+j)):Math.sqrt(2/i);const W=ml2Rand(i,j,rng,sd*(l===sizes.length-2&&o.lastScale!=null?o.lastScale:1)),B=ml2T(1,j);Ws.push(W);Bs.push(B);P.push(W,B);}
 const net={P,Ws,Bs,sizes,fwd(x){let h=x;for(let l=0;l<Ws.length;l++){h=ml2Op.add(ml2Op.mm(h,Ws[l]),Bs[l]);if(l<Ws.length-1)h=ml2Op.act(h,act);else if(o.outAct)h=ml2Op.act(h,o.outAct);}return h;},
  /* suy luận không ghi băng */
  run(x){const t=ml2.tape;ml2.tape=null;const y=net.fwd(x);ml2.tape=t;return y;},
  copyFrom(o2){for(let i=0;i<P.length;i++)P[i].d.set(o2.P[i].d);},
  count(){let n=0;for(const p of P)n+=p.d.length;return n;}};
 return net;}
const ml2Gnorm=P=>{let s=0;for(const p of P)if(p.g)for(let i=0;i<p.g.length;i++)s+=p.g[i]*p.g[i];return Math.sqrt(s);};
const ml2Finite=P=>{for(const p of P)for(let i=0;i<p.d.length;i++)if(!isFinite(p.d[i]))return false;return true;};
/* nhãn → one-hot không cần; trích hàng lô */
function ml2Batch(X,y,idx){const d=X[0].length,t=ml2T(idx.length,d),yy=new Array(idx.length);idx.forEach((i,q)=>{for(let j=0;j<d;j++)t.d[q*d+j]=X[i][j];yy[q]=y?y[i]:0;});return{x:t,y:yy};}
/* dự đoán lớp cho lưới điểm bằng mạng logit */
function ml2Prob(net,x,K){const r=net.run(ml2K(1,x.length,x)).d;if(K===1){const s=mlSig(r[0]);return[1-s,s];}return mlSoft(Array.from(r));}
/* tô nền bản đồ quyết định bằng một lần suy luận theo lô (nhanh hơn gọi từng điểm) */
function ml2HeatNet(pl,run,K,op){op=op||{};const gs=pl.gs(op.cell),gw=gs.gw,gh=gs.gh,B=pl.B,X=ml2T(gw*gh,2);
 for(let j=0;j<gh;j++)for(let i=0;i<gw;i++){X.d[(j*gw+i)*2]=B[0]+(i+0.5)/gw*(B[1]-B[0]);X.d[(j*gw+i)*2+1]=B[3]-(j+0.5)/gh*(B[3]-B[2]);}
 const P=run(X),c=P.c;pl.heat((x,y)=>{const i=Math.min(gw-1,Math.max(0,Math.floor((x-B[0])/(B[1]-B[0])*gw))),j=Math.min(gh-1,Math.max(0,Math.floor((B[3]-y)/(B[3]-B[2])*gh))),o=(j*gw+i)*c,r=new Array(c);for(let q=0;q<c;q++)r[q]=P.d[o+q];return r;},K,op);}
/* xác suất lớp theo lô từ logit của mạng: K = 1 (sigmoid) hoặc nhiều lớp (softmax) */
function ml2ProbT(net,K){return X=>{const Z=net.run(X),n=Z.r,o=ml2T(n,K===1?2:K);for(let i=0;i<n;i++){if(K===1){const s=mlSig(Z.d[i]);o.d[i*2]=1-s;o.d[i*2+1]=s;}else{const p=mlSoft(Array.from(Z.d.subarray(i*K,i*K+K)));for(let j=0;j<K;j++)o.d[i*K+j]=p[j];}}return o;};}
/* suy luận nhanh không qua đồ thị tính toán: X phẳng (n × din) → đầu ra phẳng */
function ml2Fast(net,act,outAct){const fa=k=>k==='tanh'?Math.tanh:k==='relu'?(z=>z>0?z:0):k==='leaky'?(z=>z>0?z:0.05*z):k==='sig'?mlSig:k==='gelu'?(z=>0.5*z*(1+Math.tanh(0.79788456*(z+0.044715*z*z*z)))):(z=>z),f=fa(act),fo=outAct?fa(outAct):null;
 return(X,n)=>{let h=X,d=net.sizes[0];const L=net.Ws.length;for(let l=0;l<L;l++){const W=net.Ws[l].d,B=net.Bs[l].d,j=net.sizes[l+1],o=new Float64Array(n*j);
  for(let i=0;i<n;i++){const oo=i*j;for(let q=0;q<j;q++)o[oo+q]=B[q];for(let p=0;p<d;p++){const v=h[i*d+p];if(v===0)continue;const wo=p*j;for(let q=0;q<j;q++)o[oo+q]+=v*W[wo+q];}}
  if(l<L-1){for(let i=0;i<o.length;i++)o[i]=f(o[i]);}else if(fo){for(let i=0;i<o.length;i++)o[i]=fo(o[i]);}h=o;d=j;}return h;};}
/* chuẩn hoá L2 theo hàng (cho học tương phản) */
ml2Op.l2n=function(A){const n=A.r,c=A.c,o=ml2T(n,c),nr=new Float64Array(n);for(let i=0;i<n;i++){let s=0;for(let j=0;j<c;j++)s+=A.d[i*c+j]**2;nr[i]=Math.sqrt(s)+1e-9;for(let j=0;j<c;j++)o.d[i*c+j]=A.d[i*c+j]/nr[i];}
 return ml2Reg(o,()=>{if(!o.g)return;const gA=ml2G(A);for(let i=0;i<n;i++){let dot=0;for(let j=0;j<c;j++)dot+=o.g[i*c+j]*o.d[i*c+j];for(let j=0;j<c;j++)gA[i*c+j]+=(o.g[i*c+j]-o.d[i*c+j]*dot)/nr[i];}});};

/* --- ML-2: m02_arch_a.js --- */

/* =====================================================================
   THẺ ML — ĐỢT ML-2 · KHU DEEP LEARNING · NHÓM KIẾN TRÚC (A): CNN, RNN/LSTM/GRU, TCN, AE/VAE, GAN
   ===================================================================== */
/* ---------- tiện ích vẽ chung của đợt ML-2 ---------- */
function ml2Grid(g,C,x0,y0,w,h,A,R,Cc,o={}){const cw=w/Cc,ch=h/R;let mx=o.max;if(mx==null){mx=1e-9;for(let i=0;i<R*Cc;i++)mx=Math.max(mx,Math.abs(A[i]));}
 g.save();for(let i=0;i<R;i++)for(let j=0;j<Cc;j++){const v=A[i*Cc+j],t=mlClamp(v/mx,-1,1),rg=t>=0?C.rgb[o.ci==null?0:o.ci]:C.rgb[1],a=o.sym===false?mlClamp((v-(o.lo||0))/((mx-(o.lo||0))||1),0,1):Math.abs(t);
  g.fillStyle='rgba('+rg[0]+','+rg[1]+','+rg[2]+','+(0.04+0.9*a).toFixed(3)+')';g.fillRect(x0+j*cw,y0+i*ch,Math.ceil(cw),Math.ceil(ch));
  if(o.num&&cw>26&&ch>14){g.fillStyle=C.ink;mlFont(g,Math.min(11,ch*0.55));g.textAlign='center';g.textBaseline='middle';g.fillText(mlF(v,1),x0+(j+0.5)*cw,y0+(i+0.5)*ch);}}
 g.strokeStyle=C.muted;g.lineWidth=1;g.strokeRect(x0+0.5,y0+0.5,w,h);g.restore();}
function ml2Title(g,C,x,y,t,al){g.fillStyle=C.ink;mlFont(g,11,true);g.textAlign=al||'left';g.textBaseline='top';g.fillText(t,x,y);}
function ml2Blank(c){const C=mlCols(),g=c.g;g.clearRect(0,0,c.w,c.h);g.fillStyle=C.panel;g.fillRect(0,0,c.w,c.h);return C;}
/* hàm mất mát giảm hay phân kỳ: dùng chung cho các mô phỏng huấn luyện */
const ml2Bad=a=>a.some(v=>!mlFin(v)||Math.abs(v)>1e8);
function ml2Smooth(a,k){k=k||5;return a.map((_,i)=>{let s=0,n=0;for(let j=Math.max(0,i-k+1);j<=i;j++){s+=a[j];n++;}return s/n;});}

/* =============================================================
   CNN · tích chập, stride, đệm, pooling, trường nhìn
   ============================================================= */
function ml2Img(kind,n,seed,noise){const r=mlRng(seed*17+3),A=new Float64Array(n*n),put=(i,j,v)=>{if(i>=0&&j>=0&&i<n&&j<n)A[i*n+j]=Math.max(A[i*n+j],v);};
 if(kind==='rsrp'){const L=[[0.3,0.3,0.14,1],[0.72,0.35,0.17,0.8],[0.5,0.78,0.15,0.9]];for(let i=0;i<n;i++)for(let j=0;j<n;j++){let v=0;for(const q of L){const d2=((j/n-q[0])**2+(i/n-q[1])**2)/(q[2]*q[2]);v+=q[3]*Math.exp(-d2);}A[i*n+j]=Math.min(1,v);}}
 else if(kind==='shapes'){for(let i=0;i<n;i++)for(let j=0;j<n;j++){const x=j/n,y=i/n;if(x>0.12&&x<0.45&&y>0.15&&y<0.5)A[i*n+j]=1;if((x-0.7)**2+(y-0.65)**2<0.035)A[i*n+j]=0.8;if(Math.abs(y-0.85)<0.03&&x>0.1&&x<0.9)A[i*n+j]=0.6;}}
 else if(kind==='stripes'){for(let i=0;i<n;i++)for(let j=0;j<n;j++)A[i*n+j]=0.5+0.5*Math.sin((j*0.9+i*0.35)*0.9);}
 else{/* chữ T và dấu gạch chéo */for(let i=0;i<n;i++)for(let j=0;j<n;j++){const x=j/n,y=i/n;if(y>0.15&&y<0.3&&x>0.15&&x<0.85)A[i*n+j]=1;if(x>0.42&&x<0.58&&y>0.15&&y<0.88)A[i*n+j]=1;if(Math.abs((x-0.15)-(y-0.55)*0.0)<0&&false)A[i*n+j]=1;}}
 for(let i=0;i<A.length;i++)A[i]+=r.n()*noise;return A;}
function ml2Kern(kind,k){const c=(k-1)/2,sg=Math.max(0.6,k/3.2),K=new Float64Array(k*k);
 if(k===3&&kind==='edgex')K.set([-1,0,1,-2,0,2,-1,0,1]);else if(k===3&&kind==='edgey')K.set([-1,-2,-1,0,0,0,1,2,1]);else if(k===3&&kind==='laplace')K.set([0,1,0,1,-4,1,0,1,0]);else if(k===3&&kind==='sharp')K.set([0,-1,0,-1,5,-1,0,-1,0]);
 else{let s=0;for(let i=0;i<k;i++)for(let j=0;j<k;j++){const e=Math.exp(-((i-c)**2+(j-c)**2)/(2*sg*sg));let v=e;
   if(kind==='edgex')v=(j-c)*e;else if(kind==='edgey')v=(i-c)*e;else if(kind==='laplace')v=(((i-c)**2+(j-c)**2)/(sg*sg)-2)*e*-1;else if(kind==='sharp')v=(i===c&&j===c?2:0)-e/1;else if(kind==='ident')v=(i===c&&j===c)?1:0;K[i*k+j]=v;s+=kind==='blur'?v:0;}
  if(kind==='blur')for(let i=0;i<K.length;i++)K[i]/=s;else if(kind==='sharp'){let q=0;for(let i=0;i<K.length;i++)q+=K[i];for(let i=0;i<K.length;i++)K[i]/=(Math.abs(q)<1e-6?1:Math.abs(q));}}
 if(kind==='blur'&&k===3)K.set([1,2,1,2,4,2,1,2,1].map(x=>x/16));if(kind==='ident'){K.fill(0);K[c*k+c]=1;}return K;}
function ml2Conv(A,n,K,k,s,pad){const m=Math.floor((n+2*pad-k)/s)+1,O=new Float64Array(Math.max(0,m*m));for(let i=0;i<m;i++)for(let j=0;j<m;j++){let q=0;for(let a=0;a<k;a++)for(let b=0;b<k;b++){const y=i*s+a-pad,x=j*s+b-pad;if(y>=0&&x>=0&&y<n&&x<n)q+=A[y*n+x]*K[a*k+b];}O[i*m+j]=q;}return{O,m};}
function ml2Pool(A,n,p,kind){if(p<=1)return{O:A,m:n};const m=Math.floor(n/p),O=new Float64Array(m*m);for(let i=0;i<m;i++)for(let j=0;j<m;j++){let mx=-1e9,sm=0;for(let a=0;a<p;a++)for(let b=0;b<p;b++){const q=A[(i*p+a)*n+j*p+b];mx=Math.max(mx,q);sm+=q;}O[i*m+j]=kind==='max'?mx:sm/(p*p);}return{O,m};}
const ML2KN={blur:'Làm mờ (Gauss)',edgex:'Biên dọc (Sobel x)',edgey:'Biên ngang (Sobel y)',laplace:'Laplace (biên mọi hướng)',sharp:'Làm nét',ident:'Đồng nhất'};
mlItem('cnn',{z:'dl',fam:'Kiến trúc',n:'Mạng tích chập (CNN)',short:'CNN',nc:2,nostep:true,hs:[250,170],
 sweep:{title:'bước nhảy (stride)',k:'stride',label:'stride',vals:[1,2,3,4],cols:[['Cỡ bản đồ đặc trưng',s=>s.m+'×'+s.m],['Số phép nhân–cộng',s=>s.macs],['Cỡ sau pooling',s=>s.pm+'×'+s.pm]],fv:x=>String(x),maxSteps:1},
 P:[mlS('img','Ảnh đầu vào',[['rsrp','Bản đồ RSRP (3 thùy)'],['shapes','Hình khối'],['stripes','Sọc chéo'],['T','Chữ T']],'rsrp'),mlR('n','Cỡ ảnh (n×n)',12,40,2,24),mlR('nz','Nhiễu ảnh',0,0.5,0.02,0.05),
  mlS('kern','Bộ lọc (kernel)',Object.entries(ML2KN),'edgex'),mlR('k','Cỡ kernel k',1,7,2,3),mlR('stride','Stride',1,4,1,1),mlS('pad','Đệm',[['same','giữ cỡ (same)'],['valid','không đệm (valid)']],'same'),
  mlS('pool','Pooling',[['none','không'],['max','max'],['avg','trung bình']],'max'),mlR('psz','Cỡ cửa sổ pooling',1,4,1,2),mlR('L','Số lớp xếp chồng (tính trường nhìn)',1,8,1,4),mlR('cin','Kênh vào',1,64,1,16),mlR('cout','Kênh ra',1,128,1,32),mlPSEED()],
 mk(v){const n=v.n,k=v.k%2?v.k:v.k+1,A=ml2Img(v.img,n,v.seed,v.nz),K=ml2Kern(v.kern,k),pad=v.pad==='same'?(k-1)/2:0,R=ml2Conv(A,n,K,k,v.stride,pad),F=Float64Array.from(R.O,x=>Math.max(0,x)),Pl=ml2Pool(F,R.m,v.pool==='none'?1:Math.max(1,Math.min(v.psz,R.m)),v.pool==='none'?'max':v.pool);
  const macs=R.m*R.m*k*k*v.cin*v.cout,params=k*k*v.cin*v.cout+v.cout,dense=n*n*v.cin*R.m*R.m*v.cout;
  const rf=[],jmp=[];let r0=1,j0=1;for(let l=1;l<=v.L;l++){r0+=(k-1)*j0;j0*=v.stride;rf.push(r0);}
  const rfPool=[];{let rr=1,jj=1;for(let l=1;l<=v.L;l++){rr+=(k-1)*jj;jj*=v.stride;rr+=(v.psz-1)*jj;jj*=v.psz;rfPool.push(rr);}}
  const rf1=[];{let rr=1;for(let l=1;l<=v.L;l++){rr+=2;rf1.push(rr);}}
  const s=mlStatic({m:R.m,pm:Pl.m,macs,params});
  s.draw=cv=>{const c=cv[0],C=ml2Blank(c),g=c.g,pw=(c.w-40)/3,ph=Math.min(c.h-52,pw);const px=[8,16+pw,24+2*pw];
   ml2Title(g,C,px[0],4,'Đầu vào '+n+'×'+n);ml2Grid(g,C,px[0],22,pw,ph,A,n,n,{sym:false,lo:0,max:1});
   ml2Title(g,C,px[1],4,'Conv + ReLU '+R.m+'×'+R.m);ml2Grid(g,C,px[1],22,pw,ph,F,R.m,R.m,{sym:false,lo:0});
   ml2Title(g,C,px[2],4,v.pool==='none'?'Không pooling':'Sau '+v.pool+'-pool '+Pl.m+'×'+Pl.m);ml2Grid(g,C,px[2],22,pw,ph,Pl.O,Pl.m,Pl.m,{sym:false,lo:0});
   const ks=Math.min(70,ph*0.5);ml2Title(g,C,px[0],26+ph,'Kernel '+k+'×'+k+' ('+ML2KN[v.kern]+')');ml2Grid(g,C,px[0]+0,44+ph,Math.min(ks,c.h-50-ph),Math.min(ks,c.h-50-ph),K,k,k,{num:true});};
  s.draw2=null;const oldDraw=s.draw;s.draw=cv=>{oldDraw(cv);const c=cv[1];mlChart(c,[{a:rf,c:0,n:'k, stride của bạn',dots:true},{a:rfPool,c:2,n:'+ pooling mỗi lớp',dots:true},{a:rf1,c:1,n:'3×3 stride 1',dots:true}],{title:'Trường nhìn (điểm ảnh) theo số lớp xếp chồng',xlab:'số lớp',ymin:0});};
  s.kv=()=>[['Cỡ bản đồ đặc trưng',R.m+'×'+R.m],['Tham số lớp tích chập',params.toLocaleString('vi-VN')],['Tham số nếu nối đầy đủ',(n*n*v.cin*R.m*R.m*v.cout).toExponential(2)],['Chia sẻ trọng số giảm tham số',mlF((n*n*v.cin*R.m*R.m*v.cout)/Math.max(1,params),0)+'×'],['Phép nhân–cộng',macs.toExponential(2)],['Trường nhìn sau '+v.L+' lớp',rf[rf.length-1]+' điểm ảnh'],['Đầu ra pooling',Pl.m+'×'+Pl.m]];
  s.diag=()=>{if(R.m<4)return['warn','<b>Bản đồ đặc trưng rất nhỏ</b> (cỡ '+R.m+'×'+R.m+'). Stride lớn hoặc không đệm làm mất thông tin; tăng đệm hoặc giảm stride.'];if(rf[rf.length-1]<n/2)return['warn','<b>Trường nhìn nhỏ</b> ('+rf[rf.length-1]+' < nửa ảnh): neuron cuối chưa “thấy” toàn cảnh. Thêm lớp, tăng stride/pooling hoặc kernel giãn.'];return null;};
  s.sum=()=>({m:R.m,pm:Pl.m,macs:macs.toExponential(1)});return s;}});
mlText('cnn',{
 th:mlP('<b>Tích chập</b> trượt một bộ lọc nhỏ k×k lên ảnh và lấy tổng có trọng số: cùng một bộ trọng số dùng cho mọi vị trí (<i>chia sẻ trọng số</i>) và mỗi neuron chỉ nhìn vùng cục bộ (<i>trường nhìn</i>). Nhờ đó số tham số không phụ thuộc cỡ ảnh và mạng bắt được mẫu hình lặp lại ở mọi vị trí (tịnh tiến bất biến một phần).','Mô phỏng cho thấy ba bước quen thuộc: conv → ReLU → pooling. Đổi bộ lọc để thấy biên dọc, biên ngang, làm mờ; đổi stride, đệm, cỡ kernel để thấy cỡ bản đồ đặc trưng và trường nhìn thay đổi. Biểu đồ dưới tính trường nhìn khi xếp chồng nhiều lớp.'),
 fm:['đầu ra (i,j) = Σₐ Σᵦ K[a,b] · A[i·s + a − p, j·s + b − p]','cỡ ra m = ⌊(n + 2p − k)/s⌋ + 1','trường nhìn: r_l = r_(l−1) + (k − 1)·j_(l−1);  bước nhảy j_l = j_(l−1)·s','tham số lớp = k²·C_vào·C_ra + C_ra'],
 assume:'Cấu trúc cục bộ và lặp lại theo không gian (hoặc thời gian) có ích; thông tin gần nhau liên quan chặt hơn thông tin xa.',cx:'Một lớp: O(m²·k²·C_vào·C_ra) phép nhân–cộng; tham số O(k²·C_vào·C_ra), không phụ thuộc cỡ ảnh.',
 src:'LeCun và cs. (1989, 1998) cho CNN; diễn giải lại. Bộ lọc ở đây được đặt tay để minh hoạ; mạng thật học bộ lọc bằng lan truyền ngược.',
 pros:'Ít tham số nhờ chia sẻ trọng số; khai thác cấu trúc không gian; song song hoá rất tốt trên GPU.',cons:'Trường nhìn cục bộ, muốn nhìn xa phải xếp chồng hoặc dùng kernel giãn; không bất biến xoay/tỉ lệ; cần nhiều dữ liệu hoặc tăng cường dữ liệu.',when:'Dữ liệu có lưới không gian hoặc chuỗi cục bộ: ảnh, bản đồ vùng phủ, phổ tín hiệu, ma trận kênh (anten × sóng mang).',not:'Dữ liệu bảng không có cấu trúc lân cận, đồ thị bất quy tắc (dùng GNN) hoặc khi cần quan hệ xa trực tiếp (dùng attention).',
 cvt:mlP('CNN hội tụ nhanh hơn nhiều so với mạng nối đầy đủ cùng khả năng vì ít tham số. Chi phí suy luận tỉ lệ với số phép nhân–cộng ở bảng bên (mô phỏng hiển thị cho một lớp). Giảm chi phí bằng stride, pooling, tích chập tách theo chiều sâu hoặc lượng tử hoá.','Bảng quét stride cho thấy cỡ bản đồ và số phép tính giảm gần như theo bình phương stride.'),
 fail:[{n:'Stride 4, không đệm',set:{stride:4,pad:'valid',k:7},why:'Bản đồ đặc trưng co lại còn vài điểm ảnh, mất chi tiết nhỏ và biên.',fix:'Dùng đệm “same”, stride 1–2 ở các lớp đầu; giảm kích thước dần bằng pooling hoặc stride ở lớp sau.'},{n:'Kernel 1×1, không nhìn lân cận',set:{k:1,L:8},why:'Kernel 1×1 chỉ trộn kênh, không lấy thông tin lân cận nên trường nhìn mãi bằng 1 dù xếp nhiều lớp.',fix:'Dùng kernel ≥ 3×3 hoặc kernel giãn để mở rộng trường nhìn.'},{n:'Ảnh nhiễu mạnh',set:{nz:0.5,kern:'edgex'},why:'Bộ lọc biên khuếch đại nhiễu tần số cao; bản đồ đặc trưng đầy hạt.',fix:'Làm mờ trước, hoặc dùng bộ lọc lớn hơn; mạng học sâu tự học kết hợp nhưng cần dữ liệu nhiễu khi huấn luyện.'}],
 app:mlP('Bản đồ RSRP/SINR theo lưới ô vuông: CNN dự đoán vùng phủ yếu, ước lượng vùng lỗ phủ từ số liệu drive-test thưa. Ma trận kênh (anten × sóng mang) có cấu trúc cục bộ nên CNN dùng trong nén phản hồi CSI (autoencoder tích chập) — hướng được 3GPP xem xét ở AI/ML air interface (TR 38.843, kiểm tra theo phiên bản). Phổ tín hiệu: nhận dạng điều chế và phát hiện nhiễu bằng CNN trên ảnh phổ thời gian–tần số.'),
 vn:MLVN_GEN,cmp:{vs:'MLP nối đầy đủ',rows:[['Số tham số','k²·C_vào·C_ra, không phụ thuộc cỡ ảnh','Tỉ lệ với (cỡ vào × cỡ ra)'],['Bất biến tịnh tiến','Một phần','Không'],['Khai thác lân cận','Có','Không']]},
 q:[['Chia sẻ trọng số nghĩa là?',['Cùng bộ lọc dùng cho mọi vị trí','Mỗi vị trí một bộ lọc','Chia batch','Bỏ trọng số'],0,'Đó là lý do CNN ít tham số.'],['Tăng stride từ 1 lên 2 thì cỡ bản đồ đặc trưng?',['Giảm xấp xỉ một nửa mỗi chiều','Tăng gấp đôi','Không đổi','Bằng 0'],0,'m ≈ n/s.'],['Muốn trường nhìn lớn mà ít lớp nên?',['Tăng stride/pooling hoặc kernel giãn','Giảm kênh','Bỏ ReLU','Tăng batch'],0,'Trường nhìn tăng theo bước nhảy tích luỹ.']]});

/* =============================================================
   RNN / LSTM / GRU · gradient biến mất và bùng nổ theo độ trễ
   ============================================================= */
function ml2Cell(kind,H,rng,rho,bias,ract){const sd=rho/Math.sqrt(H),M=()=>{const w=new Float64Array(H*H);for(let i=0;i<w.length;i++)w[i]=rng.n()*sd;return w;},V=()=>{const w=new Float64Array(H);for(let i=0;i<H;i++)w[i]=rng.n()*0.8;return w;};
 const mv=(W,x,off)=>{const o=new Float64Array(H);for(let i=0;i<H;i++){let s=0;for(let j=0;j<H;j++)s+=W[i*H+j]*x[off+j];o[i]=s;}return o;};
 if(kind==='rnn'){const W=M(),Ux=V();return{D:H,f(x,u){const a=mv(W,x,0),o=new Float64Array(H);for(let i=0;i<H;i++){const z=a[i]+Ux[i]*u;o[i]=ract==='lin'?z:ract==='relu'?Math.max(0,z):Math.tanh(z);}return o;}};}
 if(kind==='gru'){const Wz=M(),Wr=M(),Wn=M(),Uz=V(),Ur=V(),Un=V();return{D:H,f(x,u){const z=mv(Wz,x,0),r=mv(Wr,x,0),o=new Float64Array(H),rh=new Float64Array(H);for(let i=0;i<H;i++){const rr=mlSig(r[i]+Ur[i]*u);rh[i]=rr*x[i];}const n=mv(Wn,rh,0);
    for(let i=0;i<H;i++){const zz=mlSig(z[i]+Uz[i]*u+bias.z),nn=Math.tanh(n[i]+Un[i]*u);o[i]=(1-zz)*x[i]+zz*nn;}return o;}};}
 const Wi=M(),Wf=M(),Wo=M(),Wg=M(),Ui=V(),Uf=V(),Uo=V(),Ug=V();return{D:2*H,f(x,u){const i0=mv(Wi,x,0),f0=mv(Wf,x,0),o0=mv(Wo,x,0),g0=mv(Wg,x,0),o=new Float64Array(2*H);
  for(let i=0;i<H;i++){const ii=mlSig(i0[i]+Ui[i]*u),ff=mlSig(f0[i]+Uf[i]*u+bias.f),oo=mlSig(o0[i]+Uo[i]*u),gg=Math.tanh(g0[i]+Ug[i]*u),c=ff*x[H+i]+ii*gg;o[H+i]=c;o[i]=oo*Math.tanh(c);}return o;}};}
function ml2LagProfile(cell,T,inScale,rng){const D=cell.D,us=Array.from({length:T},()=>rng.n()*inScale);let x=new Float64Array(D);for(let i=0;i<D;i++)x[i]=rng.n()*0.3;
 const states=[x],Js=[];const eps=1e-5;
 for(let t=0;t<T;t++){const J=new Float64Array(D*D);for(let j=0;j<D;j++){const xp=Float64Array.from(x),xm=Float64Array.from(x);xp[j]+=eps;xm[j]-=eps;const fp=cell.f(xp,us[t]),fm=cell.f(xm,us[t]);for(let i=0;i<D;i++)J[i*D+j]=(fp[i]-fm[i])/(2*eps);}
  Js.push(J);x=cell.f(x,us[t]);states.push(x);}
 let M=new Float64Array(D*D);for(let i=0;i<D;i++)M[i*D+i]=1;const prof=[],fro=m=>{let s=0;for(let i=0;i<m.length;i++)s+=m[i]*m[i];return Math.sqrt(s/D);};
 prof.push(fro(M));for(let t=T-1;t>=0;t--){const J=Js[t],N=new Float64Array(D*D);for(let i=0;i<D;i++)for(let p=0;p<D;p++){const a=M[i*D+p];if(a===0)continue;for(let j=0;j<D;j++)N[i*D+j]+=a*J[p*D+j];}M=N;prof.push(fro(M));}
 return{prof,states};}
mlItem('rnn',{z:'dl',fam:'Kiến trúc',n:'RNN, LSTM và GRU: gradient theo độ trễ',short:'RNN/LSTM/GRU',nc:2,nostep:true,hs:[260,150],
 sweep:{title:'bán kính phổ ρ của ma trận hồi quy',k:'rho',label:'ρ',vals:[0.4,0.8,1,1.3,1.8],cols:[['‖∂s_T/∂s_(T−20)‖ RNN',s=>mlF(s.g20[0],3)],['… LSTM',s=>mlF(s.g20[1],3)],['… GRU',s=>mlF(s.g20[2],3)]],fv:x=>String(x),maxSteps:1,force:{T:30}},
 P:[mlR('T','Độ dài chuỗi T',10,60,2,30),mlR('H','Số đơn vị ẩn H',4,20,2,10),mlR('rho','Bán kính phổ ρ (độ lớn trọng số hồi quy)',0.2,2.2,0.05,0.9),mlR('fb','Độ lệch cổng quên của LSTM',-2,5,0.5,1),mlR('zb','Độ lệch cổng cập nhật của GRU (âm = nhớ lâu)',-4,2,0.5,-1),mlR('inp','Biên độ đầu vào',0,2,0.1,0.8),mlS('ract','Hàm kích hoạt của RNN thuần',[['tanh','tanh (bão hoà)'],['relu','ReLU'],['lin','tuyến tính (không bão hoà)']],'tanh'),mlPSEED()],
 mk(v){const mkc=(kind,off)=>ml2Cell(kind,v.H,mlRng(v.seed*31+off),v.rho,{f:v.fb,z:v.zb},v.ract),cells=[mkc('rnn',1),mkc('lstm',2),mkc('gru',3)],pr=cells.map((c,i)=>ml2LagProfile(c,v.T,v.inp,mlRng(v.seed*7+i)));
  const nm=['RNN '+(v.ract==='lin'?'tuyến tính':v.ract==='relu'?'ReLU':'tanh'),'LSTM','GRU'],log=a=>a.map(x=>x),lag=pr.map(p=>p.prof),g20=lag.map(p=>p[Math.min(20,p.length-1)]),eff=lag.map(p=>{const b=p[1]||1;for(let i=1;i<p.length;i++)if(p[i]<b*1e-3)return i;return null;});
  const s=mlStatic({g20});
  s.draw=cv=>{mlChart(cv[0],lag.map((p,i)=>({a:p.slice(1),c:[0,1,2][i],n:nm[i]})),{title:'‖∂s_T/∂s_(T−lag)‖ theo độ trễ (thang log)',ylog:true,xlab:'độ trễ (số bước lùi)'});
   const st=pr[0].states,c=cv[1],C=ml2Blank(c),g=c.g;ml2Title(g,C,8,3,'Trạng thái ẩn của RNN thuần: 6 đơn vị đầu theo thời gian');const w=c.w-20,h=c.h-30;g.strokeStyle=C.line;g.strokeRect(10.5,22.5,w,h);
   for(let q=0;q<Math.min(6,v.H);q++){g.beginPath();st.forEach((x,t)=>{const X=10+t/(st.length-1)*w,Y=22+h*(0.5-0.45*x[q]);t?g.lineTo(X,Y):g.moveTo(X,Y);});g.strokeStyle=C.cls[q%6];g.lineWidth=1.4;g.stroke();}
   let sat=0,tot=0;st.forEach(x=>{for(let q=0;q<v.H;q++){tot++;if(Math.abs(x[q])>0.95)sat++;}});g.fillStyle=C.muted;mlFont(g,10);g.textAlign='right';g.fillText('bão hoà |h|>0,95: '+mlPct(sat/tot),c.w-12,5);};
  s.kv=()=>[['Gradient sau 10 bước lùi (RNN / LSTM / GRU)',lag.map(p=>mlF(p[Math.min(10,p.length-1)],3)).join(' / ')],['Gradient sau 20 bước',g20.map(x=>mlF(x,3)).join(' / ')],['Gradient sau T bước',lag.map(p=>mlF(p[p.length-1],3)).join(' / ')],['Tầm nhớ hiệu dụng (giảm 1000×)',eff.map(e=>e==null?'> T':e).join(' / ')]];
  s.diag=()=>{const r=lag.map(p=>p[p.length-1]);if(r[0]>1e3)return['bad','<b>Gradient bùng nổ</b> ở RNN (ρ = '+mlF(v.rho,2)+'): chuẩn Jacobian tích luỹ vượt 1 qua '+v.T+' bước và đạt '+mlF(r[0],3)+'. Cắt gradient (clipping), khởi tạo trực giao hoặc giảm ρ.'];
   if(r[1]<1e-3&&r[2]<1e-3)return['warn','<b>Cả ba ô nhớ đều quên.</b> Gradient sau '+v.T+' bước chỉ còn '+r.map(x=>mlF(x,2)).join(' / ')+': cổng quên đang đóng hoặc ρ quá nhỏ.'];
   if(r[0]<1e-3&&Math.max(r[1],r[2])>r[0]*30)return['warn','<b>Gradient biến mất</b> ở RNN thuần ('+mlF(r[0],3)+' sau '+v.T+' bước) trong khi LSTM giữ được '+mlF(r[1],3)+': cổng quên gần 1 tạo đường đi gradient “gần như đồng nhất”.'];return null;};
  s.sum=()=>({g20});return s;}});
mlText('rnn',{
 th:mlP('<b>RNN</b> đọc chuỗi từng bước, giữ trạng thái ẩn s_t = f(s_(t−1), x_t). Lan truyền ngược qua thời gian nhân liên tiếp các ma trận Jacobian ∂s_t/∂s_(t−1); tích này co về 0 (<i>biến mất</i>) hoặc phình ra (<i>bùng nổ</i>) theo độ lớn trọng số hồi quy. <b>LSTM</b> và <b>GRU</b> thêm cổng để có đường “gần như đồng nhất” cho trạng thái ô nhớ, nên gradient đi xa hơn.','Mô phỏng tính <i>chính xác</i> (đạo hàm số trung tâm của từng bước) chuẩn của ∂s_T/∂s_(T−lag) với ba ô nhớ cùng bán kính phổ ρ. Không huấn luyện: đây là tính chất cấu trúc của ô nhớ ở khởi tạo.'),
 fm:['RNN: s_t = tanh(W s_(t−1) + U x_t)','LSTM: c_t = f ⊙ c_(t−1) + i ⊙ g;  h_t = o ⊙ tanh(c_t)','GRU: s_t = (1 − z) ⊙ s_(t−1) + z ⊙ tanh(W(r ⊙ s_(t−1)) + U x_t)','∂s_T/∂s_t = Π_(k=t+1..T) ∂s_k/∂s_(k−1)'],
 assume:'Chuỗi có phụ thuộc theo thứ tự; trạng thái ẩn đủ nén thông tin quá khứ cần thiết.',cx:'O(T·H²) mỗi chuỗi; tuần tự theo thời gian nên khó song song hơn Transformer.',
 src:'Hochreiter & Schmidhuber (1997) cho LSTM; Cho và cs. (2014) cho GRU; Pascanu và cs. (2013) về bùng nổ/biến mất gradient. Diễn giải lại.',
 pros:'Bộ nhớ trạng thái nén, suy luận tuyến tính theo độ dài chuỗi; hợp dữ liệu truyền theo luồng.',cons:'Khó nhớ xa dù có cổng; huấn luyện tuần tự chậm; nhạy khởi tạo và learning rate.',when:'Chuỗi KPI/nhật ký độ dài vừa, suy luận trực tuyến với bộ nhớ cố định.',not:'Chuỗi rất dài cần truy hồi chính xác (attention, SSM chọn lọc) hoặc khi cần huấn luyện song song quy mô lớn.',
 cvt:mlP('Quét ρ: với ρ < 1 gradient của RNN co theo hàm mũ; ρ > 1 phình ra. LSTM/GRU bớt nhạy với ρ nhờ cổng. Trong huấn luyện thực, kết hợp khởi tạo trực giao, độ lệch cổng quên dương và cắt gradient.'),
 fail:[{n:'ρ lớn, RNN tuyến tính: gradient bùng nổ',set:{rho:1.4,T:40,ract:'lin'},why:'Khi hàm kích hoạt không bão hoà, Jacobian chính là ma trận hồi quy; ρ > 1 làm tích tăng như ρ^lag, một bước cập nhật có thể làm loss nhảy vọt hoặc NaN. (Với tanh, bão hoà thường kìm nén hiện tượng này nhưng làm gradient biến mất theo hướng khác.)',fix:'Cắt gradient theo chuẩn, khởi tạo trực giao, giảm learning rate.'},{n:'ρ nhỏ: gradient biến mất',set:{rho:0.4,T:50},why:'RNN gần như quên mọi thứ sau vài bước; không học được phụ thuộc xa.',fix:'Dùng LSTM/GRU, tăng độ lệch cổng quên, hoặc dùng attention/SSM.'},{n:'Cổng quên bị đóng (bias âm)',set:{fb:-2,zb:2,T:40},why:'LSTM với cổng quên ≈ 0 và GRU với cổng cập nhật ≈ 1 xoá trạng thái mỗi bước nên cũng biến mất.',fix:'Khởi tạo bias cổng quên dương (ví dụ 1–2).'}],
 app:mlP('Dự báo lưu lượng cell theo giờ, dự đoán rớt cuộc gọi từ chuỗi KPI, phân tích chuỗi báo hiệu (mô hình tuần tự trên bản ghi sự kiện). Với độ dài lịch sử vài ngày (hàng trăm bước), LSTM/GRU thường được so sánh với GBM đặc trưng trễ và Transformer; hãy dùng walk-forward để chọn.'),
 vn:MLVN_GEN,cmp:{vs:'Transformer (self-attention)',rows:[['Truy cập quá khứ','Qua trạng thái nén','Trực tiếp mọi vị trí'],['Chi phí theo độ dài','O(T)','O(T²)'],['Song song huấn luyện','Kém','Tốt']]},
 q:[['Nguyên nhân gradient biến mất ở RNN?',['Nhân nhiều Jacobian có chuẩn < 1','Learning rate nhỏ','Thiếu dữ liệu','Batch nhỏ'],0,'Tích co theo hàm mũ.'],['LSTM giúp gradient đi xa nhờ?',['Đường ô nhớ gần như đồng nhất qua cổng quên ≈ 1','Nhiều tham số hơn','Dropout','ReLU'],0,'c_t = f·c_(t−1) + …'],['Khi gradient bùng nổ, cách xử lý phổ biến?',['Cắt gradient theo chuẩn','Tăng learning rate','Bỏ cổng','Thêm lớp'],0,'Giữ chuẩn bước cập nhật.']]});

