mlItem('tcn',{z:'dl',fam:'Kiến trúc',n:'Mạng tích chập thời gian (TCN)',short:'TCN',nc:2,nostep:true,hs:[250,150],
 sweep:{title:'số lớp',k:'L',label:'L',vals:[2,4,6,8,10],cols:[['Trường nhìn (dilation 2^l)',s=>s.rf],['Số tham số / kênh² ',s=>s.pc]],fv:x=>String(x),maxSteps:1},
 P:[mlR('L','Số lớp tích chập',1,10,1,5),mlR('k','Cỡ kernel k',2,6,1,3),mlS('base','Giãn nở theo lớp',[['1','không giãn (d = 1)'],['2','d = 2^l'],['3','d = 3^l']],'2'),mlR('Cc','Số kênh C',4,128,4,32),mlR('N','Số bước hiển thị',16,64,4,32)],
 mk(v){const d=l=>Math.pow(+v.base,l),rfOf=L=>{let r=1;for(let l=0;l<L;l++)r+=(v.k-1)*d(l);return r;},rf=rfOf(v.L),pc=v.L*v.k;
  const s=mlStatic({rf,pc});
  s.draw=cv=>{const c=cv[0],C=ml2Blank(c),g=c.g,N=v.N,L=v.L,x0=14,wd=c.w-28,y0=c.h-18,dy=(c.h-40)/(L),X=i=>x0+(i+0.5)*wd/N;
   ml2Title(g,C,8,3,'Nút cuối nhìn lại những bước nào (đỏ = trong trường nhìn)');
   const reach=Array.from({length:L+1},()=>new Set());reach[L].add(N-1);for(let l=L-1;l>=0;l--){for(const i of reach[l+1]){for(let q=0;q<v.k;q++){const j=i-q*d(l);if(j>=0)reach[l].add(j);}}}
   for(let l=L;l>=0;l--){const y=y0-l*dy;for(let i=0;i<N;i++){const on=reach[l].has(i);g.beginPath();g.arc(X(i),y,on?3.6:2.2,0,6.2832);g.fillStyle=on?C.cls[1]:C.line;g.fill();}
    if(l>0)for(const i of reach[l]){for(let q=0;q<v.k;q++){const j=i-q*d(l-1);if(j<0)continue;g.beginPath();g.moveTo(X(i),y);g.lineTo(X(j),y+dy);g.strokeStyle=C.cls[1];g.globalAlpha=0.35;g.lineWidth=1;g.stroke();g.globalAlpha=1;}}}
   g.fillStyle=C.muted;mlFont(g,10);g.textAlign='left';g.textBaseline='bottom';g.fillText('thời gian →',x0,c.h-3);
   const cov=[...reach[0]].length;g.textAlign='right';g.fillText('phủ '+cov+' / '+N+' bước',c.w-10,c.h-3);
   const Ls=Array.from({length:10},(_,i)=>i+1);mlChart(cv[1],[{a:Ls.map(rfOf),c:0,n:'trường nhìn TCN của bạn',dots:true},{a:Ls.map(L2=>1+(v.k-1)*L2),c:1,n:'không giãn',dots:true}],{title:'Trường nhìn theo số lớp (thang log)',ylog:true,xlab:'số lớp'});};
  s.kv=()=>[['Trường nhìn',rf+' bước'],['Số tham số (≈ L·k·C²)',(v.L*v.k*v.Cc*v.Cc).toLocaleString('vi-VN')],['Độ dài phụ thuộc tối đa',rf-1+' bước lùi'],['Song song theo thời gian','có (khác RNN)']];
  s.diag=()=>rf<v.N?['warn','<b>Trường nhìn ('+rf+') nhỏ hơn cửa sổ '+v.N+'.</b> Nút cuối không thấy hết đầu chuỗi: thêm lớp hoặc tăng giãn nở.']:null;
  s.sum=()=>({rf,pc});return s;}});
mlText('tcn',{
 th:mlP('<b>TCN</b> dùng tích chập <i>nhân quả</i> (không nhìn tương lai) và <i>giãn nở</i> theo cấp số nhân: lớp l lấy mẫu cách nhau d_l bước, nên trường nhìn tăng theo hàm mũ khi xếp chồng nhưng số tham số chỉ tăng tuyến tính. Khác RNN, mọi bước thời gian được tính song song khi huấn luyện.','Hình trên vẽ đồ thị phụ thuộc: bắt đầu từ nút ra cuối, lùi qua từng lớp theo kernel và giãn nở; đỏ là các bước đầu vào mà nút cuối thực sự “thấy”.'),
 fm:['trường nhìn = 1 + (k − 1)·Σ_l d_l','với d_l = b^l (l = 0..L−1): ≈ (k − 1)·(b^L − 1)/(b − 1)','tham số ≈ L·k·C²'],
 assume:'Phụ thuộc quan trọng nằm trong trường nhìn hữu hạn; cấu trúc tịnh tiến theo thời gian.',cx:'O(L·N·k·C²) cho chuỗi dài N; suy luận trực tuyến cần bộ đệm các trạng thái giãn.',
 src:'Bai, Kolter & Koltun (2018), “An Empirical Evaluation of Generic Convolutional and Recurrent Networks”; van den Oord và cs. (WaveNet, 2016). Diễn giải lại.',
 pros:'Huấn luyện song song; gradient ổn định; trường nhìn dài với ít lớp; độ trễ suy luận dự đoán được.',cons:'Trường nhìn cố định (không nhớ ngoài đó); bộ nhớ kích hoạt lớn khi chuỗi dài; ít linh hoạt hơn attention.',when:'Chuỗi KPI/tín hiệu có chu kỳ cố định cần dự báo nhanh, cần độ trễ thấp và song song hoá.',not:'Cần phụ thuộc vượt trường nhìn hoặc chọn lọc theo nội dung.',
 cvt:mlP('Số lớp cần thiết để phủ N bước giảm từ N xuống ~log_b N khi dùng giãn nở. Bảng quét cho thấy trường nhìn bứt tốc theo số lớp với d = 2^l.'),
 fail:[{n:'Không giãn nở',set:{base:'1',L:6,k:3},why:'Trường nhìn chỉ tăng tuyến tính (1 + 2L); mô hình “mù” với chu kỳ dài như 24 giờ.',fix:'Dùng giãn nở theo cấp số nhân hoặc thêm đặc trưng chu kỳ.'},{n:'Quá ít lớp',set:{L:2,k:2},why:'Trường nhìn quá hẹp so với cửa sổ chuỗi.',fix:'Tăng số lớp hoặc kernel; đối chiếu trường nhìn với chu kỳ cần bắt (ví dụ 168 giờ).'}],
 app:mlP('Dự báo lưu lượng/PRB theo giờ với độ trễ suy luận thấp; khử nhiễu chuỗi KPI; mô hình nhân quả trong dự đoán suy giảm chất lượng. Chu kỳ ngày–tuần của lưu lượng (24 và 168 giờ) quyết định trường nhìn cần thiết.'),
 vn:MLVN_GEN,cmp:{vs:'RNN/LSTM',rows:[['Song song huấn luyện','Có','Hạn chế'],['Nhớ xa','Trong trường nhìn hữu hạn','Lý thuyết không giới hạn, thực tế yếu'],['Độ ổn định gradient','Tốt','Cần cổng/cắt gradient']]},
 q:[['Tích chập nhân quả đảm bảo?',['Không nhìn dữ liệu tương lai','Nhìn mọi bước','Giảm tham số','Bỏ ReLU'],0,'Ngăn rò rỉ tương lai.'],['Với d = 2^l, trường nhìn tăng thế nào theo số lớp?',['Theo hàm mũ','Tuyến tính','Giảm','Không đổi'],0,'Tổng cấp số nhân.'],['Ưu thế chính của TCN so với RNN?',['Huấn luyện song song và gradient ổn định','Nhớ vô hạn','Ít tham số hơn mọi trường hợp','Không cần dữ liệu'],0,'Mọi bước tính đồng thời.']]});

