mlItem('t_fail',{z:ML3Z,fam:'Dữ liệu và dự báo',n:'3. Dự đoán suy giảm chất lượng, sự cố và giảm ticket',short:'3 · Dự đoán sự cố, ticket',nc:2,hs:[230,170],stepL:'Bước 3 epoch',stepN:3,
 sweep:{title:'ngưỡng quyết định',k:'th',label:'Ngưỡng',vals:[0.1,0.2,0.3,0.5,0.7],cols:[['Precision',s=>mlPct(s.pr)],['Recall',s=>mlPct(s.rc)],['Tiết kiệm chi phí (ước lượng)',s=>mlPct(s.save)]],maxSteps:150,note:'Chi phí = lượt xử lý phòng ngừa × c_p + sự cố bị bỏ sót × c_f, so với không làm gì; chi phí c_f/c_p đặt ở thanh trượt.'},
 P:[mlR('n','Số cell',400,3000,100,1200),mlR('prev','Tỉ lệ cell sắp lỗi (%)',2,30,1,8),mlR('nz','Nhiễu nhãn',0,2,0.1,0.6),mlR('cw','Trọng số lớp dương',1,20,1,1),mlR('th','Ngưỡng quyết định',0.05,0.95,0.05,0.3),mlL('lr','Learning rate',0.01,2,0.5),mlL('l2','Điều chuẩn L2',0.0001,1,0.001),mlR('cf','Chi phí sự cố / chi phí phòng ngừa (c_f/c_p)',2,50,1,10),mlPSEED()],
 mk(v){const r=mlRng(v.seed*29+5),n=v.n,Z=[],raw=[];const nm=['BLER trung bình','độ dốc RSRP','alarm 7 ngày','nhiệt độ','tuổi thiết bị','VSWR'];
  for(let i=0;i<n;i++){const z=Array.from({length:6},()=>r.n());Z.push(z);raw.push([3+1.2*z[0],-0.3*Math.exp(0.6*z[1])+0.1,Math.max(0,Math.round(1.5+1.3*z[2])),38+6*z[3],4+2*z[4],1.3+0.15*z[5]]);}
  const sc=Z.map(z=>0.8*z[0]+0.6*z[1]+0.7*z[2]+0.2*z[3]+0.35*z[4]+0.5*z[5]+v.nz*r.n()),srt=sc.slice().sort((a,b)=>b-a),q=srt[Math.max(0,Math.min(n-1,Math.round(n*v.prev/100)-1))],y=sc.map(s=>s>=q?1:0);
  const nt=Math.round(n*0.7),sca=ml3Scaler(raw.slice(0,nt)),Xs=raw.map(sca.f),Xtr=Xs.slice(0,nt),ytr=y.slice(0,nt),Xte=Xs.slice(nt),yte=y.slice(nt);
  const lg=ml3Logit(Xtr,ytr,{lr:v.lr,l2:v.l2,cw:v.cw}),rule=Xte.map(z=>(z[2]>0.8||z[5]>1.2)?1:0),m={spf:3,t:0,done:false,bad:false,loss:[]};
  const scores=()=>Xte.map(x=>lg.p(x));
  const at=(th)=>{const s=scores(),c=mlConf(yte,s.map(p=>p>=th?1:0));const P=yte.filter(a=>a===1).length;return{c,pr:c.tp+c.fp?c.tp/(c.tp+c.fp):0,rc:P?c.tp/P:0,cost:(c.tp+c.fp)*1+c.fn*v.cf+c.tp*0,base:P*v.cf};};
  m.step=()=>{if(m.done)return false;const l=lg.step();if(!isFinite(l)){m.bad=true;m.done=true;return false;}m.loss.push(l);m.t++;if(m.t>=150)m.done=true;return true;};
  m.sum=()=>{const a=at(v.th);return{pr:a.pr,rc:a.rc,save:a.base?1-a.cost/a.base:NaN};};
  m.draw=cv=>{const C=mlCols(),s=scores(),R=mlRoc(s,yte),rc=mlConf(yte,rule),rt=yte.filter(a=>a===1).length,rn=yte.length-rt;
   const info=mlChart(cv[0],[{a:R.tpr,x:R.fpr,c:0,n:'ROC (logistic) AUC '+mlF(R.auc,3),w:2},{a:[0,1],x:[0,1],c:C.muted,d:[3,3],w:1}],{title:'ROC trên tập kiểm tra',xmin:0,xmax:1,ymin:0,ymax:1,xlab:'tỉ lệ dương giả (FPR)'});
   if(info){const g=cv[0].g,pt=(fp,tp,col,t)=>{g.beginPath();g.arc(info.X(fp),info.Y(tp),5,0,6.2832);g.fillStyle=col;g.fill();g.fillStyle=C.ink;mlFont(g,10,true);g.textAlign='left';g.fillText(t,info.X(fp)+7,info.Y(tp)+10);};
    pt(rn?rc.fp/rn:0,rt?rc.tp/rt:0,C.cls[2],'luật cố định');const a=at(v.th);pt(rn?a.c.fp/rn:0,rt?a.c.tp/rt:0,C.cls[1],'ngưỡng '+v.th);}
   const ths=Array.from({length:19},(_,i)=>0.05+i*0.05),cs=ths.map(t=>{const a=at(t);return a.base?a.cost/a.base:1;});
   mlChart(cv[1],[{a:cs,x:ths,c:1,n:'Chi phí / chi phí không làm gì',w:2},{a:ths.map(()=>1),x:ths,c:C.muted,d:[3,3],w:1}],{title:'Chi phí theo ngưỡng (nhỏ hơn 1 = có lợi)',xmin:0.05,xmax:0.95,ymin:0,ymax:Math.max(1.3,...cs),vline:v.th,xlab:'ngưỡng quyết định'});};
  m.kv=()=>{const a=at(v.th),P=yte.filter(b=>b===1).length,rc=mlConf(yte,rule),rp=mlPRF(rc);return[['Cell huấn luyện / kiểm tra',Xtr.length+' / '+Xte.length],['Số cell sắp lỗi (kiểm tra)',P+' ('+mlPct(P/Xte.length)+')'],['Epoch',m.t+' / 150'],['-'],['Logistic · Precision / Recall','P '+mlPct(a.pr)+' · R '+mlPct(a.rc)],['Luật cố định · Precision / Recall','P '+mlPct(rp.pr)+' · R '+mlPct(rp.rc)],['Giảm chi phí so với không làm gì (ước lượng)',a.base?mlPct(1-a.cost/a.base):'—'],['Loss',m.loss.length?mlF(mlLast(m.loss),4):'—']];};
  m.diag=()=>{if(m.bad)return['bad','<b>Phân kỳ.</b> Giảm learning rate.'];if(m.t<20)return null;const a=at(v.th);
   if(v.prev<=4&&v.cw===1&&a.rc<0.3)return['warn','<b>Mất cân bằng lớp.</b> Chỉ '+v.prev+' % cell sắp lỗi và trọng số lớp = 1: mô hình dự đoán “không lỗi” gần như mọi lúc (Recall '+mlPct(a.rc)+'); tăng trọng số lớp dương hoặc hạ ngưỡng.'];
   if(v.th>=0.7&&a.rc<0.3)return['warn','<b>Ngưỡng quá cao.</b> Bỏ sót nhiều cell sắp lỗi (Recall '+mlPct(a.rc)+'); với c_f lớn hơn c_p nhiều, nên hạ ngưỡng.'];
   if(v.th<=0.1&&a.pr<0.2)return['warn','<b>Ngưỡng quá thấp.</b> Quá nhiều lượt xử lý phòng ngừa thừa (Precision '+mlPct(a.pr)+').'];
   if(v.nz>=1.6)return['warn','<b>Nhãn nhiễu.</b> Dấu hiệu yếu so với nhiễu nên AUC thấp; khả năng dự đoán bị giới hạn bởi dữ liệu, không phải mô hình.'];return null;};
  return m;}});
