 fail:[{n:'Cây quá sâu, ít dữ liệu',set:{leaves:40,n:100},why:'Cây tách đến từng điểm nhiễu: tốt trên huấn luyện, kém trên kiểm tra.',fix:'Cắt tỉa, đặt số mẫu tối thiểu mỗi lá, dùng rừng.'},{n:'Nhiễu KPI lớn',set:{nz:2},why:'Các nguyên nhân chồng lấn KPI.',fix:'Thêm KPI phân biệt (bản tin, log), không chỉ tăng độ phức tạp mô hình.'},{n:'Lan truyền sai',set:{pc:0,al:2,G:6},why:'Cell hàng xóm không chung nguyên nhân nhưng bị kéo theo.',fix:'Chỉ lan truyền trên cạnh có quan hệ phụ thuộc thật (cùng nút, cùng backhaul).'},{n:'KPI thiếu nhiều',set:{miss:0.6},why:'Thiếu KPI làm mô hình đoán theo giá trị điền.',fix:'Xử lý thiếu có chủ đích, ghi cờ thiếu như một đặc trưng.'}],
