/* ---------- 13. MOS thoại ---------- */
const ML3CODEC=[['AMR-NB-like',12,10],['AMR-WB-like',6,12],['EVS-like',3,14]];
function ml3Emodel(loss,delay,cod,burst){const [,Ie,Bpl]=ML3CODEC[cod],Ie_eff=Ie+(95-Ie)*loss/(loss/burst+Bpl),x=Math.log2(Math.max(1,delay)/100),Id=delay>100?25*(Math.pow(1+Math.pow(x,6),1/6)-3*Math.pow(1+Math.pow(x/3,6),1/6)+2):0,R=93.2-Id-Ie_eff;
  return R<0?1:R>100?4.5:1+0.035*R+7e-6*R*(R-60)*(100-R);}
mlItem('t_mos',{z:ML3Z,fam:'Dịch vụ và truyền dẫn',n:'13. Dự đoán MOS thoại/video: E-model so với ML',short:'13 · MOS thoại',nc:2,hs:[250,150],stepL:'Bước 4 epoch',stepN:4,
 sweep:{title:'số mẫu huấn luyện',k:'n',label:'Số mẫu',vals:[100,300,600,1200,2000],cols:[['RMSE E-model',s=>mlF(s.r.em,3)],['RMSE ridge',s=>mlF(s.r.rd,3)],['RMSE MLP',s=>mlF(s.r.mlp,3)]],maxSteps:80,note:'RMSE của MOS trên tập kiểm tra 300 mẫu (MOS thang 1–4,5).'},
 P:[mlS('sel','Biểu đồ phân tán cho',[['em','E-model (chỉ mất gói + trễ)'],['rd','Hồi quy ridge'],['mlp','MLP']],'mlp'),mlR('n','Số mẫu huấn luyện',100,2000,50,600),mlR('nz','Nhiễu cảm nhận (MOS)',0,0.6,0.05,0.12),mlR('jb','Bộ đệm jitter (ms)',20,100,5,40),mlC('sn','Cho mô hình dùng SINR vô tuyến',true),mlR('hid','Nơ-ron ẩn (MLP)',4,32,2,12),mlL('lr','Learning rate (MLP)',0.001,0.05,0.01),mlPSEED()],
 mk(v){const rng=mlRng(v.seed*167+13),gen=(n)=>{const X=[],y=[],raw=[];for(let i=0;i<n;i++){const sinr=-8+26*rng.u(),cod=rng.int(3),ho=rng.u()<0.1?1:0,loss0=0.1+8*mlSig((-3-sinr)/2.2),jit=Math.max(1,5+45*mlSig((2-sinr)/3)+4*rng.n()),delay=70+jit*0.8+8*rng.n()+(ho?30:0),late=Math.min(10,6*Math.pow(jit/v.jb,2)),burst=1+2.2*mlSig((-1-sinr)/3),effL=Math.min(40,loss0+late+(ho?1.5:0));
    const mos=mlClamp(ml3Emodel(effL,delay,cod,burst)+v.nz*rng.n(),1,4.5);raw.push({loss:loss0,jit,delay,sinr,cod,ho,burst});y.push(mos);}return{raw,y};};
  const feat=r=>{const f=[r.loss/5,r.jit/30,r.delay/100,r.cod===1?1:0,r.cod===2?1:0,r.ho];if(v.sn)f.push(r.sinr/10);return f;};
  const tr=gen(v.n),te=gen(300),Xr=tr.raw.map(feat),Xt=te.raw.map(feat),sc=ml3Scaler(Xr),Xs=Xr.map(sc.f),Xts=Xt.map(sc.f);
  const poly=x=>{const o=x.slice();for(let i=0;i<x.length;i++)for(let j=i;j<x.length;j++)o.push(x[i]*x[j]);return o;};const rd=ml3Ridge(Xs.map(poly),tr.y,0.003);
  const em=r=>ml3Emodel(r.loss,r.delay,r.cod,r.burst),rngN=mlRng(v.seed*5+1),net=ml3Mlp([Xs[0].length,v.hid,v.hid,1],rngN),Yt=tr.y.map(a=>[(a-3)/1.5]),m={spf:1,t:0,done:false,bad:false,L:[],T:[]};
  const pm=()=>Xts.map(x=>net.fwd(x)[0]*1.5+3),pr=()=>Xts.map(x=>rd(poly(x))),pe=te.raw.map(em);
  const rm=(p)=>mlRMSE(te.y,p),cor=(p)=>{const a=mlMean(p),b=mlMean(te.y);let sxy=0,sx=0,sy=0;for(let i=0;i<p.length;i++){sxy+=(p[i]-a)*(te.y[i]-b);sx+=(p[i]-a)**2;sy+=(te.y[i]-b)**2;}return sxy/Math.sqrt(sx*sy+1e-12);};
  m.step=()=>{if(m.done)return false;const idx=rngN.perm(Xs.length).slice(0,256);let Ls=0,c=0;for(let b=0;b<idx.length;b+=32){const l=net.train(Xs,Yt,idx.slice(b,b+32),v.lr,1e-5);if(!isFinite(l)){m.bad=true;m.done=true;return false;}Ls+=l;c++;}m.L.push(Ls/Math.max(1,c));m.t++;m.T.push(rm(pm()));if(m.t>=80)m.done=true;return true;};
  m.sum=()=>({r:{em:rm(pe),rd:rm(pr()),mlp:rm(pm())}});
  m.draw=cv=>{const C=mlCols(),pred={em:pe,rd:pr(),mlp:pm()}[v.sel],pl=mlPlot(cv[0],[1,4.6,1,4.6]);pl.frame();pl.line([1,1],[4.6,4.6],C.muted,1,[4,3]);pl.pts(pred.map((p,i)=>[te.y[i],p]),null,{col:()=>C.cls[{em:2,rd:1,mlp:0}[v.sel]],r:2.6});pl.label(pl.pad.l+6,pl.pad.t+10,'Trục ngang: MOS thật (có nhiễu cảm nhận) · trục dọc: dự đoán · đường đứt: y = x',C.muted,'left',10);
   const x=m.T.map((_,i)=>i+1),s=m.sum().r;mlChart(cv[1],[{a:m.T,x,c:0,n:'RMSE MLP (kiểm tra)',w:2},{a:x.map(()=>s.em),x,c:2,n:'E-model',d:[4,3]},{a:x.map(()=>s.rd),x,c:1,n:'Ridge',d:[4,3]}],{title:'RMSE MOS theo epoch',ymin:0,xlab:'epoch',empty:'Bấm Chạy để huấn luyện MLP'});};
  m.kv=()=>{const s=m.sum().r,ba=te.y.map(a=>a<3?1:0),R1=mlRoc(pe.map(a=>-a),ba).auc,R2=mlRoc(pm().map(a=>-a),ba).auc;return[['Mẫu huấn luyện / kiểm tra',v.n+' / 300'],['Epoch MLP',m.t+' / 80'],['-'],['E-model','RMSE '+mlF(s.em,3)+' · tương quan '+mlF(cor(pe),3)],['Ridge bậc 2','RMSE '+mlF(s.rd,3)+' · tương quan '+mlF(cor(pr()),3)],['MLP','RMSE '+mlF(s.mlp,3)+' · tương quan '+mlF(cor(pm()),3)],['-'],['AUC phát hiện cuộc gọi MOS < 3','E-model '+mlF(R1,3)+' · MLP '+mlF(R2,3)]];};
  m.diag=()=>{if(m.bad)return['bad','<b>Phân kỳ.</b>'];const s=m.sum().r;if(m.t<10)return null;if(v.n<=150&&s.mlp>s.rd+0.02)return['warn','<b>Quá ít mẫu.</b> MLP kém ridge ('+mlF(s.mlp,3)+' so với '+mlF(s.rd,3)+'); mẫu MOS có nhãn (nghe thật/đo POLQA) rất đắt.'];
   if(v.nz>=0.5)return['warn','<b>Nhiễu cảm nhận lớn.</b> RMSE bị chặn bởi nhiễu nhãn (~'+v.nz+'); không mô hình nào vượt qua.'];if(v.jb<=25&&s.em>s.mlp+0.05)return['ok','Bộ đệm jitter nhỏ làm gói trễ bị loại (mất gói hiệu dụng cao): E-model chỉ dùng mất gói + trễ nên lệch '+mlF(s.em,2)+', còn ML dùng jitter nên đúng hơn.'];
   if(!v.sn&&s.mlp>s.em)return['warn','<b>Bỏ SINR.</b> Mô hình thiếu đặc trưng vô tuyến nên khó vượt E-model.'];return null;};
  return m;}});
