mlItem('t_cong',{z:ML3Z,fam:'Dịch vụ và truyền dẫn',n:'15. Truyền dẫn: chọn đường (SD-WAN/SR) và tắc nghẽn bằng bandit',short:'15 · Chọn đường (SD-WAN/SR)',nc:2,hs:[250,160],stepL:'Thêm 1 khối',
 sweep:{title:'mức tải luồng',k:'F',label:'Tải luồng',vals:[0.1,0.2,0.3,0.4],cols:[['p95 tĩnh (ms)',s=>mlF(s.p.st,0)],['p95 ECMP (ms)',s=>mlF(s.p.ec,0)],['p95 bandit (ms)',s=>mlF(s.p.bd,0)],['Vi phạm SLA bandit',s=>mlPct(s.v.bd)]],maxSteps:30,note:'p95 trễ và tỉ lệ vượt SLA trung bình các khối cuối.'},
 P:[mlR('np','Số đường',2,6,1,4),mlR('F','Tải luồng điều khiển (phần dung lượng)',0.05,0.6,0.05,0.25),mlR('bu','Mức bùng nổ lưu lượng nền',0,1,0.1,0.5),mlR('sla','SLA trễ (ms)',40,200,5,90),mlR('c','Hệ số khám phá (bandit)',0,4,0.25,0.4),mlR('ne','Nhiễu đo (ms)',0,20,1,5),mlPSEED()],
 mk(v){const rng=mlRng(v.seed*181+11),np=v.np,base=Array.from({length:np},(_,i)=>20+14*i),bg=new Float64Array(np).fill(0.35),dr=new Float64Array(np);const pol=['st','ec','th','bd'],names={st:'Đường ngắn nhất (tĩnh)',ec:'ECMP',th:'Phản ứng ngưỡng',bd:'Bandit (UCB)'};
  const S={};for(const p of pol)S[p]={lat:[],vio:0,n:0,sw:0,share:new Float64Array(np),cur:0,bm:Array.from({length:np},()=>({n:1,mu:base[0]})),H:[]};
  for(const b of S.bd.bm)b.mu=60;
  const m={spf:1,t:0,done:false};
  const world=()=>{for(let i=0;i<np;i++){dr[i]=0.9*dr[i]+0.12*rng.n();bg[i]=mlClamp(0.35+0.25*Math.sin((m.t*100+i*37)/ (60+10*i))+0.2*dr[i]+(rng.u()<0.02*v.bu?0.35:0)*(i<np/2?1:0.3),0.05,0.92);}};
  m.step=()=>{if(m.done)return false;const lens=new Array(pol.length).fill(0);const blk={st:[],ec:[],th:[],bd:[]};
   for(let k=0;k<100;k++){world();const share={};for(const p of pol)share[p]=new Float64Array(np);
    const choice={st:0,ec:rng.int(np),th:S.th.cur,bd:0};
    let bi=0,bv=1e9;for(let i=0;i<np;i++){const b=S.bd.bm[i],val=b.mu-v.c*Math.sqrt(Math.log(S.bd.n+2)/b.n)*6;if(val<bv){bv=val;bi=i;}}choice.bd=bi;
    for(const p of pol){const i=choice[p],rho=mlClamp(bg[i]+v.F,0,0.97),lat=base[i]+25*rho/(1-rho)+v.ne*rng.n()*0.5,truth=Math.max(1,lat);S[p].lat.push(truth);blk[p].push(truth);S[p].n++;if(truth>v.sla)S[p].vio++;S[p].share[i]++;
     if(p==='th'){if(truth>v.sla*0.8){let b=0,bl=1e9;for(let j=0;j<np;j++){const rj=mlClamp(bg[j]+v.F,0,0.97),lj=base[j]+25*rj/(1-rj)+v.ne*rng.n()*0.5;if(lj<bl){bl=lj;b=j;}}S.th.pr=(S.th.pr||0)+1;if(b!==S.th.cur){S.th.sw++;S.th.cur=b;}}}
     if(p==='bd'){const bm=S.bd.bm[i];bm.n=Math.min(bm.n+1,40);bm.mu+=(truth-bm.mu)/Math.min(bm.n,15);S.bd.n++;}}}
   for(const p of pol)S[p].H.push([mlMean(blk[p]),(()=>{const s=blk[p].slice().sort((a,b)=>a-b);return s[Math.floor(s.length*0.95)];})()]);m.t++;if(m.t>=30)m.done=true;return true;};
  const last=(p,f)=>{const L=S[p].H.slice(-8);return L.length?mlMean(L.map(h=>h[f])):NaN;};
  m.sum=()=>({p:{st:last('st',1),ec:last('ec',1),bd:last('bd',1)},v:{st:S.st.n?S.st.vio/S.st.n:0,ec:S.ec.n?S.ec.vio/S.ec.n:0,bd:S.bd.n?S.bd.vio/S.bd.n:0}});
  m.draw=cv=>{const C=mlCols(),x=S.st.H.map((_,i)=>i+1),ci={st:2,ec:3,th:1,bd:0};mlChart(cv[0],pol.map(p=>({a:S[p].H.map(h=>h[1]),x,c:ci[p],n:names[p].split(' ')[0],w:p==='bd'?2.2:1.5})),{title:'Trễ p95 theo khối 100 luồng (ms)',ymin:0,hline:v.sla,xlab:'khối',empty:'Bấm Chạy để mô phỏng'});
   const g=cv[1].g,c=cv[1];g.clearRect(0,0,c.w,c.h);g.fillStyle=C.panel;g.fillRect(0,0,c.w,c.h);mlFont(g,11,true);g.fillStyle=C.ink;g.textAlign='left';g.fillText('Phần luồng đi qua từng đường',8,14);const rowH=(c.h-26)/pol.length;
   pol.forEach((p,r)=>{const tot=mlSum(Array.from(S[p].share))||1;g.fillStyle=C.muted;mlFont(g,10);g.textAlign='right';g.textBaseline='middle';g.fillText(names[p].split(' ')[0],86,24+r*rowH+rowH/2);let x0=92;for(let i=0;i<np;i++){const w=(c.w-100)*S[p].share[i]/tot;g.fillStyle=C.cls[i%6];g.globalAlpha=0.85;g.fillRect(x0,24+r*rowH+3,Math.max(0,w-1),rowH-6);g.globalAlpha=1;if(w>26){g.fillStyle='#fff';g.textAlign='center';g.fillText(Math.round(100*S[p].share[i]/tot)+'%',x0+w/2,24+r*rowH+rowH/2);}x0+=w;}});};
  m.kv=()=>{const r=[['Khối',m.t+' / 30 ('+m.t*100+' luồng)'],['Đường: RTT nền (ms)',base.map((b,i)=>'Đ'+(i+1)+': '+b).join(' · ')],['-']];for(const p of pol)r.push([names[p],'p95 '+mlF(last(p,1),0)+' ms · TB '+mlF(last(p,0),0)+' ms · vượt SLA '+mlPct(S[p].n?S[p].vio/S[p].n:0)+(p==='th'?' · '+S.th.sw+' lần đổi đường · '+(S.th.pr||0)+' lần thăm dò mọi đường (chi phí thêm)':'')]);return r;};
  m.diag=()=>{if(m.t<8)return null;const s=m.sum();if(v.c===0&&s.p.bd>s.p.ec)return['warn','<b>Không khám phá.</b> Bandit chỉ bám đường tốt nhất ban đầu nên không phát hiện khi đường khác tốt lên.'];
   if(v.F>=0.5&&s.v.bd>0.3)return['warn','<b>Quá tải toàn bộ đường.</b> Khi mọi đường gần đầy, chọn đường không cứu được; cần thêm dung lượng hoặc điều khiển tốc độ.'];if(v.ne>=18&&s.p.bd>s.p.st)return['warn','<b>Nhiễu đo lớn.</b> Bandit nhầm đo nhiễu thành thay đổi thật.'];
   if(s.p.bd<s.p.st*0.8)return['ok','Bandit giảm p95 trễ '+mlPct(1-s.p.bd/s.p.st)+' so với đường ngắn nhất tĩnh (mô phỏng).'];return null;};
  return m;}});
ml3Txt('t_cong',{
 prob:'Chọn đường truyền (SD-WAN, Segment Routing/SR-TE, ECMP) khi các đường có trễ và mức tắc nghẽn thay đổi theo thời gian; đường ngắn nhất theo IGP không phải lúc nào cũng tốt nhất.',
 data:'Trễ/jitter/mất gói đo bằng probe (IP SLA, TWAMP), tải liên kết (SNMP/telemetry), thông lượng luồng. Ở đây mô hình hàng đợi M/M/1 xấp xỉ: trễ = nền + 25·ρ/(1−ρ).',
 model:'Bandit UCB chọn đường theo trễ đo gần đây có cửa sổ trượt (không dừng); thay thế: Thompson sampling, RL có trạng thái, dự báo tắc nghẽn bằng LSTM/GBM rồi chọn đường.',
 alt:'Học tăng cường (xem rl_q, rl_dqn) với trạng thái tải liên kết; dự báo lưu lượng liên kết (mục 1) để chọn đường trước.',
 classic:'Đường ngắn nhất theo IGP, ECMP băm đều và chuyển đường khi trễ vượt ngưỡng.',
 fm:['UCB: i* = argmin_i [ μ_i − c·√(ln N / n_i) ]  (chọn đường có cận dưới trễ thấp nhất)','μ_i: trung bình trượt trễ đo; n_i: số lần chọn','trễ_i = nền_i + 25·ρ_i/(1 − ρ_i),  ρ_i = nền + tải luồng'],
 assume:'Trễ mỗi đường dừng chậm hơn tốc độ thăm dò; tải luồng tác động tới đường được chọn (phản hồi).',cx:'O(số đường) mỗi quyết định.',
 src:'Auer, Cesa-Bianchi & Fischer (2002); RFC 8402 (Segment Routing), RFC 7799/TWAMP cho đo; thực hành SD-WAN của vendor. Mô hình đồ chơi.',
 pros:'Thích nghi theo trạng thái thực; tận dụng đường kém ưu tiên khi cần.',cons:'Khám phá làm một số luồng đi đường xấu; dao động đường (flapping) nếu phản ứng quá nhanh; cần giữ thứ tự gói.',
 when:'Có nhiều đường, SLA trễ quan trọng, đường biến động.',not:'Chỉ một đường, hoặc luồng nhạy với đổi đường (reordering).',
 cvt:'Bandit hội tụ sau vài khối; khám phá lớn tốn kém ngay từ đầu nhưng thích nghi tốt khi điều kiện đổi.',
 fail:[{n:'Không khám phá',set:{c:0},why:'Không bao giờ thử đường khác.',fix:'c > 0, cửa sổ trượt.'},{n:'Quá tải mọi đường',set:{F:0.6,np:2},why:'Không có đường nhàn rỗi.',fix:'Thêm dung lượng, điều khiển tốc độ, ưu tiên QoS.'},{n:'Nhiễu đo lớn',set:{ne:20},why:'Bandit đuổi theo nhiễu.',fix:'Lọc, tăng cửa sổ.'},{n:'Bùng nổ nền mạnh',set:{bu:1},why:'Đường tốt đổi nhanh.',fix:'Thăm dò thường xuyên hơn, dự báo ngắn hạn.'}],
 use:'SD-WAN chọn đường theo SLA, SR-TE chọn policy theo dự báo tắc nghẽn; điều khiển tắc nghẽn backhaul/fronthaul 5G.',
 kpi:'Giảm p95 trễ và tỉ lệ vượt SLA (ước lượng mô phỏng); cân bằng tải liên kết.',
 links:[['tx','Truyền dẫn'],['pr','Giao thức'],['stack','Giao thức và fronthaul']],
 std:'RFC 8402 (SR), RFC 9256 (SR Policy), RFC 5357 (TWAMP), MEF 70/70.1 (SD-WAN); O-RAN WG9 (transport). Tra theo phiên bản.',
 cmp:{vs:'ECMP / đường ngắn nhất',rows:[['Thích nghi','Có','Không'],['Rủi ro','Khám phá, flapping','Không'],['Giữ thứ tự','Cần chính sách dính','Băm giữ thứ tự'],['Độ phức tạp','Cao hơn','Thấp']]},
 q:[['UCB cân bằng điều gì?',['Khai thác đường tốt và khám phá đường ít thử','Tốc độ và màu','Tần số','Điện áp'],0,'Cận trên độ tin cậy.'],['Flapping là gì?',['Đổi đường liên tục','Mất gói','Tăng băng thông','Tắt cổng'],0,'Phản ứng quá nhạy.'],['Vì sao ECMP không đủ?',['Không biết tắc nghẽn từng đường','Quá chậm','Không có băm','Luôn tốt nhất'],0,'Chia đều bất kể trạng thái.']]});

/* --- ML-3: ml3_03_a.js --- */
/* =====================================================================
   ĐỢT ML-3 · ỨNG DỤNG 16–18: gian lận/tấn công, churn + phân khúc + gói cước, quy hoạch mạng
   ===================================================================== */
/* ---------- 16. Gian lận và tấn công ---------- */
const ML3FR={simbox:{n:'SIM-box (chuyển cuộc gọi quốc tế thành nội mạng)',f:['Cuộc gọi đi/ngày','Thời lượng TB (giây)','Số đích khác nhau','Tỉ lệ gọi đêm','Tỉ lệ cuộc gọi đến/đi','Số cell khác nhau'],
  nm:[[30,180,14,0.15,0.9,4],[0.45,0.5,0.5,0.7,0.6,0.8]],at:[[220,28,150,0.4,0.05,1],[0.3,0.5,0.35,0.5,0.8,0.3]]},
 irsf:{n:'IRSF (bơm lưu lượng vào số quốc tế giá cao)',f:['Cuộc gọi quốc tế/ngày','Thời lượng TB (giây)','Tỉ lệ đích giá cao','Tỉ lệ gọi đêm','Tỉ lệ cuộc gọi đến/đi','Số đích khác nhau'],
  nm:[[1.5,150,0.02,0.15,0.9,8],[0.8,0.5,0.9,0.7,0.6,0.6]],at:[[40,620,0.8,0.5,0.1,3],[0.6,0.45,0.25,0.4,0.8,0.5]]},
 sig:{n:'Thăm dò báo hiệu SS7/Diameter hoặc DDoS đăng ký',f:['Bản tin/giờ','Số IMSI khác nhau','Tỉ lệ SRI/ULR lạ','Tỉ lệ lỗi','Gốc GT/Realm lạ','Chênh lệch giờ'],
  nm:[[60,6,0.01,0.03,0.05,1],[0.6,0.7,0.9,0.7,0.9,0.5]],at:[[900,300,0.55,0.25,0.8,1],[0.5,0.6,0.4,0.5,0.4,0.5]]}};
mlItem('t_fraud',{z:ML3Z,fam:'Bảo mật và khách hàng',n:'16. Phát hiện gian lận và tấn công: SIM-box, IRSF, báo hiệu SS7/Diameter',short:'16 · Gian lận/tấn công',nc:2,hs:[250,170],stepL:'Bước 5 epoch',stepN:5,
 sweep:{title:'tỉ lệ tấn công (%)',k:'prev',label:'%',vals:[0.5,1,2,5,10],cols:[['AUC logistic',s=>mlF(s.a.lg,3)],['AUC Mahalanobis (không nhãn)',s=>mlF(s.a.mh,3)],['PR-AUC logistic',s=>mlF(s.ap.lg,3)],['PR-AUC Mahalanobis',s=>mlF(s.ap.mh,3)]],maxSteps:150,note:'PR-AUC (độ chính xác trung bình) phản ánh tốt hơn AUC khi lớp dương hiếm.'},
 P:[mlS('kind','Kịch bản',Object.keys(ML3FR).map(k=>[k,ML3FR[k].n]),'simbox'),mlR('n','Số thuê bao / ngày quan sát',500,4000,100,1500),mlR('prev','Tỉ lệ tấn công (%)',0.2,15,0.2,3),mlR('ov','Mức khó (độ chồng lấn giữa tấn công và bình thường)',0,2,0.1,1.3),mlR('cw','Trọng số lớp dương (logistic)',1,40,1,5),mlR('th','Ngưỡng cảnh báo',0.02,0.98,0.02,0.4),mlR('cf','Thiệt hại bỏ sót / chi phí điều tra (c_f/c_i)',1,100,1,20),mlL('lr','Learning rate',0.01,2,0.5),mlPSEED()],
 mk(v){const K=ML3FR[v.kind],r=mlRng(v.seed*191+17),n=v.n,X=[],y=[];const gen=(cls)=>K.nm[0].map((mn,j)=>{const ln=Math.log(Math.max(1e-3,mn)),la=Math.log(Math.max(1e-3,K.at[0][j])),mean=cls?ln+(la-ln)*(1-v.ov/2.2):ln,sg=(cls?K.at[1][j]:K.nm[1][j])*(1+0.3*v.ov*cls);return mean+sg*r.n();});
  for(let i=0;i<n;i++){const c=r.u()<v.prev/100?1:0;X.push(gen(c));y.push(c);}if(mlSum(y)<4){for(let i=0;i<4;i++){y[i]=1;X[i]=gen(1);}}
  const nt=Math.round(n*0.6),sc=ml3Scaler(X.slice(0,nt)),Xs=X.map(sc.f),Xtr=Xs.slice(0,nt),ytr=y.slice(0,nt),Xte=Xs.slice(nt),yte=y.slice(nt);
  const lg=ml3Logit(Xtr,ytr,{lr:v.lr,l2:0.001,cw:v.cw}),nrm=Xtr.filter((_,i)=>ytr[i]===0),mu=Xtr[0].map((_,j)=>mlMean(Xtr.map(a=>a[j]))),C=mlCov(Xtr,mu);for(let i=0;i<C.length;i++)C[i][i]+=1e-3;
  const Ci=(()=>{const d=C.length,cols=[];for(let j=0;j<d;j++){const e=new Array(d).fill(0);e[j]=1;cols.push(mlSolve(C,e));}return cols;})(),maha=x=>{const dx=x.map((a,j)=>a-mu[j]);let s=0;for(let i=0;i<dx.length;i++)for(let j=0;j<dx.length;j++)s+=dx[i]*Ci[j][i]*dx[j];return s;};
  const rule=Xte.map(x=>(x[0]>2.2||x[2]>2.2)?1:0),m={spf:5,t:0,done:false,L:[]};
  m.step=()=>{if(m.done)return false;const l=lg.step();if(!isFinite(l)){m.done=true;return false;}m.L.push(l);m.t++;if(m.t>=150)m.done=true;return true;};
  const sl=()=>Xte.map(x=>lg.p(x)),sm=()=>Xte.map(maha);
  m.sum=()=>{const a=mlRoc(sl(),yte),b=mlRoc(sm(),yte);return{a:{lg:a.auc,mh:b.auc},ap:{lg:a.ap,mh:b.ap}};};
  m.draw=cv=>{const C=mlCols(),a=mlRoc(sl(),yte),b=mlRoc(sm(),yte),rc=mlConf(yte,rule),rp=mlPRF(rc),P=yte.filter(q=>q===1).length;
   const info=mlChart(cv[0],[{a:a.pr,x:a.rc,c:0,n:'Logistic (có nhãn) AP '+mlF(a.ap,2),w:2},{a:b.pr,x:b.rc,c:1,n:'Mahalanobis (không nhãn) AP '+mlF(b.ap,2),w:1.8}],{title:'Precision–Recall trên tập kiểm tra ('+P+' tấn công)',xmin:0,xmax:1,ymin:0,ymax:1,xlab:'recall'});
   if(info){const g=cv[0].g;g.fillStyle=C.cls[2];g.beginPath();g.arc(info.X(rp.rc),info.Y(rp.pr),5,0,6.2832);g.fill();mlFont(g,10,true);g.fillStyle=C.ink;g.textAlign='left';g.fillText('luật cố định',info.X(rp.rc)+7,info.Y(rp.pr));}
   const ths=Array.from({length:49},(_,i)=>0.02+i*0.02),s=sl(),cs=ths.map(t=>{const c=mlConf(yte,s.map(p=>p>=t?1:0));return(c.tp+c.fp)*1+c.fn*v.cf;});const base=P*v.cf||1;
   mlChart(cv[1],[{a:cs.map(q=>q/base),x:ths,c:1,n:'Chi phí / chi phí không làm gì',w:2},{a:ths.map(()=>1),x:ths,c:C.muted,d:[3,3]}],{title:'Chi phí theo ngưỡng (logistic)',xmin:0.02,xmax:0.98,ymin:0,vline:v.th,xlab:'ngưỡng'});};
  m.kv=()=>{const s=sl(),c=mlConf(yte,s.map(p=>p>=v.th?1:0)),q=mlPRF(c),P=yte.filter(a=>a===1).length,cost=(c.tp+c.fp)+c.fn*v.cf,rc=mlPRF(mlConf(yte,rule)),sm0=m.sum();return[['Kịch bản',K.n],['Đặc trưng',K.f.join(' · ')],['-'],['Mẫu huấn luyện / kiểm tra · tấn công',Xtr.length+' / '+Xte.length+' · '+P],['Logistic ở ngưỡng '+v.th,'P '+mlPct(q.pr)+' · R '+mlPct(q.rc)+' · F1 '+mlF(q.f1,2)],['Luật cố định','P '+mlPct(rc.pr)+' · R '+mlPct(rc.rc)],['AUC logistic / Mahalanobis',mlF(sm0.a.lg,3)+' / '+mlF(sm0.a.mh,3)],['Giảm chi phí so với không làm gì (ước lượng)',P?mlPct(1-cost/(P*v.cf)):'—']];};
  m.diag=()=>{if(m.t<20)return null;const s=m.sum();if(v.prev<=1&&v.cw===1)return['warn','<b>Lớp dương rất hiếm, trọng số = 1.</b> Logistic dễ đoán “bình thường”; tăng trọng số lớp hoặc dùng PR-AUC để đánh giá.'];
   if(v.ov>=1.5)return['warn','<b>Tấn công giống bình thường.</b> Đặc trưng chồng lấn mạnh: cả hai phương pháp gần ngẫu nhiên; cần đặc trưng mới (chuỗi hành vi, đồ thị).'];if(s.a.mh>s.a.lg&&v.prev>=8)return['warn','<b>Tỉ lệ tấn công cao làm nhiễm bẩn Mahalanobis.</b> Mô hình không nhãn coi tấn công là một phần “bình thường”.'];
   if(s.ap.lg>0.7)return['ok','PR-AUC logistic '+mlF(s.ap.lg,2)+': có thể vận hành với danh sách ưu tiên điều tra.'];return null;};
  return m;}});
ml3Txt('t_fraud',{
 prob:'Phát hiện thuê bao/luồng báo hiệu gian lận hoặc tấn công: SIM-box, IRSF, thăm dò SS7/Diameter (định vị, chặn), DDoS đăng ký, botnet. Lớp dương hiếm và đối thủ thích nghi.',
 data:'CDR (số cuộc gọi, thời lượng, đích, giờ), báo hiệu SS7/Diameter (IMSI khác nhau, GT lạ, tỉ lệ lỗi), log tường lửa. Ở đây dữ liệu tổng hợp theo 3 kịch bản; không dùng IMSI/IMEI thật.',
 model:'Hồi quy logistic có trọng số lớp (có nhãn) và khoảng cách Mahalanobis (không nhãn); thay thế: Isolation Forest, GBM, autoencoder, mô hình đồ thị/ chuỗi cho gian lận có tổ chức.',
 alt:'GBM/XGBoost (tiêu chuẩn cho gian lận bảng), Isolation Forest (mục anom_cmp), học bán giám sát, phát hiện cộng đồng trên đồ thị cuộc gọi.',
 classic:'Luật nghiệp vụ (số cuộc gọi, tỉ lệ đích giá cao, ngưỡng tốc độ báo hiệu) và danh sách chặn: nhanh, giải thích được, đối thủ dễ né.',
 fm:['logistic: p = σ(wᵀx + b),  loss có trọng số lớp','Mahalanobis: D² = (x − μ)ᵀ Σ⁻¹ (x − μ)','chi phí(ngưỡng) = (TP + FP)·c_i + FN·c_f'],
 assume:'Hành vi bình thường ổn định; đặc trưng log-chuẩn; nhãn tấn công đáng tin; đối thủ chưa tránh đặc trưng.',cx:'Rất nhẹ; có thể chấm điểm theo luồng.',
 src:'GSMA FS.11 (thông lệ bảo mật SS7), FS.19 (Diameter) — nhắc tên, kiểm tra theo phiên bản; CFCA báo cáo tổn thất gian lận; Chandola et al. (2009). Dữ liệu minh hoạ, không phản ánh phân phối thật.',
 pros:'Bắt được hành vi lạ mà luật không nghĩ tới; xếp hạng ưu tiên điều tra; kết hợp có nhãn và không nhãn.',cons:'Đối thủ thích nghi (concept drift); nhãn thường thiếu; báo động giả tốn công điều tra.',
 when:'Có CDR/báo hiệu khối lượng lớn và nhóm điều tra gian lận; cần danh sách ưu tiên.',not:'Khi cần chặn thời gian thực không chấp nhận báo động giả: dùng luật cứng cộng ML để xếp hạng.',
 cvt:'Logistic hội tụ trong vài chục epoch; chọn ngưỡng theo chi phí quan trọng hơn thêm epoch.',
 fail:[{n:'Lớp hiếm, không trọng số',set:{prev:0.6,cw:1,th:0.5},why:'Mô hình đoán “bình thường” để giảm loss.',fix:'Trọng số lớp, PR-AUC, ngưỡng theo chi phí.'},{n:'Tấn công chồng lấn',set:{ov:1.8},why:'Đặc trưng không phân biệt.',fix:'Thêm đặc trưng chuỗi/đồ thị.'},{n:'Ngưỡng cao',set:{th:0.9},why:'Bỏ sót.',fix:'Hạ ngưỡng theo c_f/c_i.'},{n:'Nhiễm bẩn không nhãn',set:{prev:15},why:'Tấn công làm lệch mô hình bình thường.',fix:'Lọc, dùng mô hình bền (MCD, trung vị).'}],
 use:'Danh sách điều tra SIM-box/IRSF hằng ngày; cảnh báo thăm dò SS7/Diameter cho tường lửa báo hiệu; phát hiện DDoS đăng ký trước khi quá tải AMF/MME.',
 kpi:'Giảm thiệt hại gian lận và thời gian phát hiện; tỉ lệ báo động giả (ước lượng mô phỏng, tuỳ nhà mạng).',
 links:[['fw','Tường lửa'],['rm','Roaming'],['core','Mạng lõi']],
 std:'GSMA FS.11 (SS7), FS.19 (Diameter), FS.31 (an ninh cơ bản), 3GPP TS 33.501 (an ninh 5G); O-RAN WG11 (bảo mật). Tra theo phiên bản.',
 cmp:{vs:'Luật nghiệp vụ',rows:[['Phát hiện kiểu mới','Có (không nhãn)','Không'],['Giải thích','Trung bình','Rất tốt'],['Báo động giả','Điều chỉnh bằng ngưỡng','Tuỳ luật'],['Bảo trì','Huấn luyện lại','Viết lại luật']]},
 q:[['Vì sao dùng PR-AUC cho gian lận?',['Lớp dương hiếm','Vì đẹp','Vì ROC sai','Vì ít dữ liệu'],0,'ROC lạc quan khi lớp âm quá nhiều.'],['Mahalanobis không nhãn giả định?',['Đa số dữ liệu là bình thường','Mọi mẫu đều là tấn công','Không có hiệp phương sai','Dữ liệu rời rạc'],0,'Học phân phối bình thường.'],['IRSF là?',['Bơm lưu lượng vào số quốc tế giá cao','Mã hoá SIM','Chuyển giao','Định tuyến'],0,'International Revenue Share Fraud.']]});

/* ---------- 17a. Churn + CLV ---------- */
mlItem('t_churn',{z:ML3Z,fam:'Bảo mật và khách hàng',n:'17a. Dự báo rời mạng (churn), CLV và chiến dịch giữ chân',short:'17a · Churn / CLV',nc:2,hs:[250,170],stepL:'Bước 5 epoch',stepN:5,
 sweep:{title:'chi phí ưu đãi giữ chân',k:'co',label:'Chi phí',vals:[5,15,30,60],cols:[['Lợi nhuận tối đa: p·CLV',s=>mlF(s.pf.clv,0)],['Lợi nhuận tối đa: chỉ p',s=>mlF(s.pf.p,0)],['Lợi nhuận: ngẫu nhiên',s=>mlF(s.pf.rnd,0)],['AUC',s=>mlF(s.auc,3)]],maxSteps:150,note:'Lợi nhuận kỳ vọng = Σ (p·s·CLV − chi phí ưu đãi) trên nhóm được chọn, đơn vị tiền tương đối.'},
 P:[mlR('n','Số khách hàng',500,4000,100,1500),mlR('ch','Tỉ lệ rời mạng (%)',3,40,1,15),mlR('nz','Nhiễu',0,2,0.1,0.8),mlR('co','Chi phí ưu đãi mỗi khách',2,100,1,6),mlR('sr','Xác suất ưu đãi giữ được khách (%)',5,80,5,40),mlR('mg','Biên lợi nhuận (%)',10,60,5,35),mlL('lr','Learning rate',0.01,2,0.5),mlPSEED()],
 mk(v){const r=mlRng(v.seed*197+23),n=v.n,raw=[],Z=[];for(let i=0;i<n;i++){const z=Array.from({length:6},()=>r.n());Z.push(z);raw.push([Math.max(1,24+18*z[0]),Math.max(3,20*Math.exp(0.4*z[1])),Math.max(0,3+2.5*z[2]),Math.max(0,Math.round(0.8+1.2*z[3])),Math.max(0,0.02+0.015*Math.exp(0.3*z[4])),z[5]>0.3?1:0]);}
  const sc0=Z.map((z,i)=>-0.7*z[0]+0.2*z[1]-0.1*z[2]+0.6*z[3]+0.5*z[4]+0.5*(z[5]>0.3?1:0)+v.nz*r.n()),srt=sc0.slice().sort((a,b)=>b-a),q=srt[Math.max(0,Math.round(n*v.ch/100)-1)],y=sc0.map(s=>s>=q?1:0);
  const nt=Math.round(n*0.6),sca=ml3Scaler(raw.slice(0,nt)),Xs=raw.map(sca.f),Xtr=Xs.slice(0,nt),ytr=y.slice(0,nt),Xte=Xs.slice(nt),yte=y.slice(nt),rte=raw.slice(nt),lg=ml3Logit(Xtr,ytr,{lr:v.lr,l2:0.001,cw:2}),m={spf:5,t:0,done:false,L:[]};
  const clv=(i)=>rte[i][1]*v.mg/100*18;
  m.step=()=>{if(m.done)return false;const l=lg.step();if(!isFinite(l)){m.done=true;return false;}m.L.push(l);m.t++;if(m.t>=150)m.done=true;return true;};
  const profit=(order)=>{let cum=0,best=-1e9,bk=0;const out=[0];for(let k=0;k<order.length;k++){const i=order[k];cum+=(yte[i]?v.sr/100*clv(i):0)-v.co;out.push(cum);if(cum>best){best=cum;bk=k+1;}}return{curve:out,best,bk};};
  const orders=()=>{const idx=Xte.map((_,i)=>i),p=Xte.map(x=>lg.p(x));const byP=idx.slice().sort((a,b)=>p[b]-p[a]),byC=idx.slice().sort((a,b)=>p[b]*clv(b)-p[a]*clv(a)),rnd=mlRng(v.seed+9).shuf(idx.slice()),rule=idx.slice().sort((a,b)=>(rte[b][3]+rte[b][5])-(rte[a][3]+rte[a][5]));return{byP,byC,rnd,rule};};
  m.sum=()=>{const o=orders(),p=Xte.map(x=>lg.p(x));return{pf:{clv:profit(o.byC).best,p:profit(o.byP).best,rnd:profit(o.rnd).best,rule:profit(o.rule).best},auc:mlRoc(p,yte).auc};};
  m.draw=cv=>{const C=mlCols(),o=orders(),N=Xte.length,xs=Array.from({length:N+1},(_,i)=>100*i/N),mk1=(ord)=>profit(ord);
   const pc=mk1(o.byC),pp=mk1(o.byP),pr=mk1(o.rnd),pu=mk1(o.rule);mlChart(cv[0],[{a:pc.curve,x:xs,c:0,n:'Xếp theo p·CLV',w:2.2},{a:pp.curve,x:xs,c:1,n:'Theo p',w:1.6},{a:pu.curve,x:xs,c:3,n:'Luật (khiếu nại)',w:1.4},{a:pr.curve,x:xs,c:2,n:'Ngẫu nhiên',w:1.4,d:[4,3]}],{title:'Lợi nhuận kỳ vọng theo % khách được ưu đãi',xmin:0,xmax:100,xlab:'% khách hàng được nhắm tới',hline:0});
   const p=Xte.map(x=>lg.p(x)),R=mlRoc(p,yte);mlChart(cv[1],[{a:R.tpr,x:R.fpr,c:0,n:'ROC AUC '+mlF(R.auc,3),w:2},{a:[0,1],x:[0,1],c:C.muted,d:[3,3]}],{title:'ROC dự báo rời mạng',xmin:0,xmax:1,ymin:0,ymax:1});};
  m.kv=()=>{const o=orders(),s=m.sum();return[['Khách huấn luyện / kiểm tra · rời mạng',Xtr.length+' / '+Xte.length+' · '+mlSum(yte)],['Epoch',m.t+' / 150'],['AUC',mlF(s.auc,3)],['-'],['Nhắm theo p·CLV','tối đa '+mlF(s.pf.clv,0)+' ở '+mlF(100*profit(o.byC).bk/Xte.length,0)+' % khách'],['Nhắm theo p',mlF(s.pf.p,0)],['Luật (khiếu nại + HO lỗi)',mlF(s.pf.rule,0)],['Ngẫu nhiên',mlF(s.pf.rnd,0)]];};
  m.diag=()=>{if(m.t<20)return null;const s=m.sum();if(v.co>=80&&s.pf.clv<=5)return['warn','<b>Ưu đãi quá đắt.</b> Chi phí ưu đãi gần bằng giá trị kỳ vọng giữ được nên chiến dịch không có lãi dù mô hình tốt.'];if(v.nz>=1.8)return['warn','<b>Nhiễu lớn.</b> AUC '+mlF(s.auc,2)+' thấp: hành vi rời mạng khó dự đoán từ dữ liệu này.'];
   if(v.sr<=10&&s.pf.clv<=3)return['warn','<b>Ưu đãi hiệu quả thấp.</b> Chỉ '+v.sr+' % khách được giữ nên không bù chi phí; cần uplift modelling (ai thực sự bị tác động).'];if(s.pf.clv>s.pf.p*1.1)return['ok','Nhắm theo p·CLV có lợi hơn chỉ theo p '+mlPct(s.pf.clv/s.pf.p-1)+': không phải ai sắp rời cũng đáng giữ.'];return null;};
  return m;}});
