/* ---------- 17b. Phân khúc + gợi ý gói ---------- */
const ML3PK=[['Gói Cơ bản',50,2,100,100],['Gói Dữ liệu',100,10,200,100],['Gói Tất cả',180,40,1000,500]]; /* [tên, giá/tháng, quota GB, quota phút, quota SMS]; giá trị minh hoạ */
function ml3Kmeans(X,K,rng,pp,maxIt){const n=X.length,d=X[0].length,C=[];if(pp){C.push(X[rng.int(n)].slice());while(C.length<K){const D=X.map(x=>Math.min(...C.map(c=>mlDist(x,c)**2))),s=mlSum(D);let t=rng.u()*s,i=0;for(;i<n-1;i++){t-=D[i];if(t<=0)break;}C.push(X[i].slice());}}else for(let k=0;k<K;k++)C.push(X[rng.int(n)].slice());
  let lab=new Array(n).fill(0),it=0,ch=true;for(;it<maxIt&&ch;it++){ch=false;for(let i=0;i<n;i++){let b=0,bd=1e18;for(let k=0;k<K;k++){const dd=mlDist(X[i],C[k])**2;if(dd<bd){bd=dd;b=k;}}if(lab[i]!==b){lab[i]=b;ch=true;}}
    for(let k=0;k<K;k++){const mem=[];for(let i=0;i<n;i++)if(lab[i]===k)mem.push(X[i]);if(mem.length)C[k]=C[k].map((_,j)=>mlMean(mem.map(a=>a[j])));}}
  let inertia=0;for(let i=0;i<n;i++)inertia+=mlDist(X[i],C[lab[i]])**2;return{C,lab,inertia,it};}
mlItem('t_seg',{z:ML3Z,fam:'Bảo mật và khách hàng',n:'17b. Phân cụm khách hàng và gợi ý gói cước',short:'17b · Phân khúc / gói cước',nc:2,hs:[250,170],nostep:true,
 sweep:{title:'số cụm K',k:'K',label:'K',vals:[2,3,4,5,6],cols:[['Silhouette',s=>mlF(s.sil,3)],['Tiết kiệm nhờ gói theo cụm (%)',s=>mlF(s.save,1)],['Tiết kiệm tối đa theo từng khách (%)',s=>mlF(s.orc,1)]],maxSteps:1,note:'Tiết kiệm = giảm hoá đơn trung bình so với một gói chung tốt nhất cho tất cả.'},
 P:[mlR('n','Số khách hàng',200,1500,50,600),mlR('tk','Số nhóm hành vi thật (ẩn)',2,5,1,3),mlR('sp','Độ trải của mỗi nhóm',0.3,1.6,0.1,0.6),mlR('K','Số cụm K',2,8,1,3),mlC('pp','Khởi tạo k-means++',true),mlR('rs','Số lần khởi tạo lại',1,10,1,3),mlPSEED()],
 mk(v){const r=mlRng(v.seed*199+31),n=v.n,cent=[[0.3,0.2,0.2],[1.1,0.8,0.4],[0.5,2.6,0.8],[2.4,1.4,0.7],[1.6,2.8,1.8]].slice(0,v.tk),raw=[];
  for(let i=0;i<n;i++){const c=cent[i%v.tk];raw.push(c.map(m=>Math.max(0.02,m*Math.exp(v.sp*0.35*r.n()))));} /* [giờ thoại/10, GB/10, SMS/100] */
  const usage=raw.map(a=>({gb:a[1]*10,min:a[0]*100,sms:a[2]*100})),Z=raw.map(a=>a.map(Math.log)),sc=ml3Scaler(Z),X=Z.map(sc.f);
  const bill=(u,p)=>p[1]+Math.max(0,u.gb-p[2])*10+Math.max(0,u.min-p[3])*0.3+Math.max(0,u.sms-p[4])*0.1;
  const run=(K)=>{let best=null;for(let t=0;t<v.rs;t++){const q=ml3Kmeans(X,K,r,v.pp,40);if(!best||q.inertia<best.inertia)best=q;}return best;};
  const el=[],sil=[];for(let K=2;K<=8;K++){const q=run(K);el.push(q.inertia);sil.push(mlSil(X,q.lab));}
  const res=run(v.K),totalBill=(sel)=>mlMean(usage.map((u,i)=>bill(u,ML3PK[sel(i)])));
  const bestSingle=[0,1,2].map(k=>totalBill(()=>k)),bs=Math.min(...bestSingle),bsk=bestSingle.indexOf(bs);
  const cp=res.C.map((_,k)=>{const idx=usage.map((_,i)=>i).filter(i=>res.lab[i]===k);let b=0,bv=1e18;for(let p=0;p<3;p++){const c=mlMean(idx.map(i=>bill(usage[i],ML3PK[p])));if(c<bv){bv=c;b=p;}}return b;});
  const bc=totalBill(i=>cp[res.lab[i]]),bo=mlMean(usage.map(u=>Math.min(...ML3PK.map(p=>bill(u,p)))));
  const m={spf:1,done:true,fixed:true};
  m.sum=()=>({sil:sil[v.K-2],save:100*(1-bc/bs),orc:100*(1-bo/bs)});
  m.draw=cv=>{const C=mlCols(),pl=mlPlot(cv[0],[Math.min(...Z.map(a=>a[0]))-0.3,Math.max(...Z.map(a=>a[0]))+0.3,Math.min(...Z.map(a=>a[1]))-0.3,Math.max(...Z.map(a=>a[1]))+0.3],{});pl.frame();pl.pts(Z.map(a=>[a[0],a[1]]),res.lab,{r:2.6});
   res.C.forEach((c,k)=>{const x=c[0]*sc.sd[0]+sc.mu[0],y=c[1]*sc.sd[1]+sc.mu[1];pl.pts([[x,y]],null,{col:()=>C.ink,r:6,hollow:true});pl.text(x+0.05,y+0.08,'→ '+ML3PK[cp[k]][0],C.ink,'left',10,true);});pl.label(pl.pad.l+6,pl.pad.t+10,'Trục ngang: ln(phút thoại) · trục dọc: ln(GB) · vòng: tâm cụm, nhãn: gói gợi ý',C.muted,'left',10);
   const x=el.map((_,i)=>i+2),sn=sil.map(a=>a);const mx=Math.max(...el);mlChart(cv[1],[{a:el.map(a=>a/mx),x,c:2,n:'Quán tính (chuẩn hoá)',w:1.8,dots:true},{a:sn,x,c:0,n:'Silhouette',w:1.8,dots:true}],{title:'Chọn K: khuỷu (elbow) và silhouette',xmin:2,xmax:8,xlab:'K',vline:v.K});};
  m.kv=()=>{const s=m.sum();return[['Khách · nhóm ẩn · K',v.n+' · '+v.tk+' · '+v.K],['Silhouette tại K',mlF(s.sil,3)],['Silhouette tốt nhất ở K',String(sil.indexOf(Math.max(...sil))+2)],['-'],['Hoá đơn TB nếu mọi người một gói tốt nhất ('+ML3PK[bsk][0]+')',mlF(bs,1)],['Hoá đơn TB khi gợi ý theo cụm',mlF(bc,1)+' (giảm '+mlF(s.save,1)+' %)'],['Hoá đơn TB nếu từng khách chọn gói rẻ nhất',mlF(bo,1)+' (giảm '+mlF(s.orc,1)+' %)'],['Gói gợi ý theo cụm',cp.map((p,k)=>'C'+(k+1)+': '+ML3PK[p][0]).join(' · ')]];};
  m.diag=()=>{if(v.K<v.tk-1)return['warn','<b>K nhỏ hơn số nhóm thật.</b> Gộp hai nhóm hành vi khác nhau vào một cụm nên gói gợi ý khó vừa cho mọi người.'];if(v.K>v.tk+3)return['warn','<b>K lớn hơn số nhóm thật.</b> Chia nhỏ một nhóm; silhouette giảm và gói gợi ý không đổi.'];if(v.sp>=1.4)return['warn','<b>Các nhóm chồng lấn.</b> Độ trải lớn nên cụm không tách rõ; gợi ý theo cụm kém hơn theo từng khách.'];if(!v.pp&&v.rs===1)return['warn','<b>Khởi tạo ngẫu nhiên, 1 lần.</b> k-means có thể kẹt ở cực tiểu cục bộ; dùng k-means++ hoặc nhiều lần khởi tạo.'];return null;};
  return m;}});
