KL.forEach(k=>{if(!KEN[k.id])throw new Error("Thiếu KEN: "+k.id);k.en=KEN[k.id];});
for(const id in KEN)if(!KL.some(k=>k.id===id))throw new Error("KEN id lạ: "+id);
function kpGlExtra(k,pb){const sc=KSC[k.sc];const where=k.nd.map(id=>sc&&sc.n[id]?sc.n[id][2]:id).join(", ");
 const ca=(pb.ca||[]).slice(0,3);const rel=KL.filter(x=>x!==k&&x.pb===k.pb).slice(0,4);
 return'<p>Trên sơ đồ, KPI được đo ở <b>'+kpE(where)+'</b>.'+(ca.length?' Khi KPI xấu đi, các nguyên nhân thường gặp gồm: '+kpE(ca.join("; "))+'.':'')+(rel.length?' Nên xem cùng: '+rel.map(x=>'<b>'+kpE(x.ab[0]||x.fn)+'</b>').join(", ")+'.':'')+'</p>';}
function kpRank(k,q){const a=k.ab.map(x=>x.toLowerCase());if(a[0]===q||a.includes(q))return 0;if(k.dn.toLowerCase().includes(q)||a.some(x=>x.includes(q)))return 1;return 2;}
function kpAbBadge(k){return k.ab&&k.ab[0]?'<b class="kpab">'+kpE(k.ab[0])+'</b> ':'';}

const KTECH=[["all","Tất cả"],["5G","5G"],["4G","4G"],["3G","3G"],["2G","2G"],["IMS","IMS / VoLTE"],["TX","Truyền dẫn"],["IT","CNTT"],["SEC","Bảo mật"]];
const KLY=[["all","Tất cả"],["ran","RAN"],["core","Lõi"],["ims","IMS, dịch vụ"],["tx","Truyền dẫn"],["it","CNTT"],["sec","Bảo mật"]];
const KCAT=[["all","Tất cả"],["acc","Truy cập"],["ret","Duy trì"],["mob","Di động"],["int","Toàn vẹn"],["avl","Sẵn sàng"],["utl","Sử dụng"],["ipq","Chất lượng IP"],["syn","Đồng bộ"],["opt","Quang, vi ba"],["sat","Bảo vệ"],["sdt","Phát hiện, ứng phó"],["sgv","Quản trị, tuân thủ"]];
const KCATN={acc:"Truy cập (Accessibility)",ret:"Duy trì kết nối (Retainability)",mob:"Di động (Mobility)",int:"Toàn vẹn (Integrity)",avl:"Sẵn sàng (Availability)",utl:"Sử dụng (Utilization)",ipq:"Chất lượng IP (Y.1540/1541)",syn:"Đồng bộ (G.8260 trở đi)",opt:"Quang và vi ba",sat:"Bảo vệ (NIST CSF: Protect)",sdt:"Phát hiện và ứng phó (NIST CSF: Detect, Respond)",sgv:"Quản trị và tuân thủ"};
const KLYN={ran:"RAN",core:"Lõi",ims:"IMS",tx:"Truyền dẫn",it:"CNTT",sec:"Bảo mật"};
const KP={tech:"all",ly:"all",cat:"all",q:"",sel:"rrc5",node:"",pf:5,spd:1,run:true};
const kpE=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
const kpById=id=>KL.find(k=>k.id===id);
function kpPath(k){return k.p.split(";").map(s=>{const i=s.indexOf(":"),ab=s.slice(0,i).split(">");let lab=s.slice(i+1),mk="";const m=lab.match(/!([AS])$/);if(m){mk=m[1];lab=lab.slice(0,-2);}return{a:ab[0],b:ab[1],l:lab.trim(),m:mk};});}
function kpType(k){const t=k.ty.split("|");if(t[0]==="g")return{ty:"g",unit:t[1],min:+t[2],max:+t[3],dir:t[4],good:+t[5],bad:+t[6],base:+t[7]};return{ty:t[0]};}
function kpFiltered(){const q=KP.q.trim().toLowerCase();const r=KL.filter(k=>(KP.tech==="all"||k.tech===KP.tech)&&(KP.ly==="all"||k.ly===KP.ly)&&(KP.cat==="all"||k.cat===KP.cat)&&(!KP.node||k.nd.includes(KP.node))&&(!q||(k.dn+" "+k.nm+" "+k.ab.join(" ")+" "+k.gl+" "+k.fm+" "+k.hw.join(" ")+" "+k.er.join(" ")+" "+k.nk.join(" ")+" "+k.c3).toLowerCase().includes(q)));return q?r.sort((a,b)=>kpRank(a,q)-kpRank(b,q)):r;}
function kpCnt(s){const c=s[0];if(c==="!")return'<code>'+kpE(s.slice(1))+'</code> <span class="kpC ok" title="Đã đối chiếu với nguồn công khai đã tra">✓</span>';if(c==="?")return'<span class="kpQ">'+kpE(s.slice(1))+'</span> <span class="kpC no" title="Chưa có tên counter chắc chắn: chỉ mô tả, cần tra tài liệu vendor">?</span>';return'<code>'+kpE(s)+'</code> <span class="kpC mid" title="Tên theo quy ước vendor, cần đối chiếu với counter reference đúng release">~</span>';}
function kpChips(key,list){return list.map(o=>'<button type="button" class="kpch" data-kpf="'+key+':'+o[0]+'" aria-pressed="'+(KP[key]===o[0])+'">'+o[1]+'</button>').join("");}
function kpFltHtml(){const n=kpFiltered().length;const nd=KP.node?(()=>{const sc=Object.values(KSC).map(s=>s.n[KP.node]).find(Boolean);return'<div class="kpnodechip">Nút: <b>'+kpE(sc?sc[2]:KP.node)+'</b> <button type="button" class="kpch" data-kpf="node:">Bỏ lọc ✕</button></div>';})():"";
 return'<h3>Bộ lọc</h3><div class="kpsrow"><label class="kplb">Tìm KPI, counter, công thức<input type="search" id="kpQ" value="'+kpE(KP.q)+'" placeholder="Ví dụ: RRC, pmErab, INVITE" autocomplete="off"></label><button type="button" class="btn sm" id="kpTreeBtn" aria-haspopup="tree" aria-expanded="false" title="Duyệt cây: Công nghệ, Lớp mạng, Nhóm KPI, KPI">Cây KPI ▾</button></div>'
 +'<div class="kpg"><div class="kpgt">Công nghệ</div>'+kpChips("tech",KTECH)+'</div><div class="kpg"><div class="kpgt">Lớp mạng</div>'+kpChips("ly",KLY)+'</div><div class="kpg"><div class="kpgt">Nhóm KPI (3GPP)</div>'+kpChips("cat",KCAT)+'</div>'+nd
 +'<p class="note" id="kpCount">'+n+' trên '+KL.length+' KPI. Bấm một nút trên sơ đồ để chỉ xem KPI đo ở nút đó.</p>';}
function kpListHtml(){const L=kpFiltered();if(!L.length)return'<p class="note">Không có KPI phù hợp bộ lọc.</p>';return L.map(k=>'<button type="button" class="kpit" data-kpsel="'+k.id+'" aria-pressed="'+(k.id===KP.sel)+'"><span class="kpitn">'+kpAbBadge(k)+kpE(k.dn)+'</span><span class="kpitt"><span class="tag t'+k.tech+'">'+k.tech+'</span><span class="tag">'+KLYN[k.ly]+'</span><span class="tag">'+kpE(KCATN[k.cat].split(" (")[0])+'</span></span></button>').join("");}
function kpScene(k){const sc=KSC[k.sc],P=kpPath(k),T=kpType(k);if(!sc)return"";const W=760,H=300;let s='<svg id="kpSvg" class="kpsvg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Sơ đồ nút mạng đo KPI '+kpE(k.nm)+'">';
 const nw=id=>{const n=sc.n[id];return Math.max(62,n[2].length*7.4+16);};
 s+=sc.e.map(e=>{const a=sc.n[e[0]],b=sc.n[e[1]];if(!a||!b)return"";return'<line class="kpE" x1="'+a[0]+'" y1="'+a[1]+'" x2="'+b[0]+'" y2="'+b[1]+'"/><text class="kpEL" x="'+((a[0]+b[0])/2)+'" y="'+((a[1]+b[1])/2-3)+'" text-anchor="middle">'+e[2]+'</text>';}).join("");
 const used=new Set(P.flatMap(p=>[p.a,p.b]));
 s+=Object.keys(sc.n).map(id=>{const n=sc.n[id],w=nw(id),meas=k.nd.includes(id);return'<g class="kpN '+n[4]+(meas?" meas":"")+(used.has(id)?" used":"")+'" data-kpn="'+id+'" tabindex="0" role="button" aria-label="'+kpE(n[2]+": "+n[3])+'" transform="translate('+(n[0]-w/2)+','+(n[1]-16)+')"><title>'+kpE(n[2]+" – "+n[3])+'</title>'+(meas?'<rect class="kpRing" x="-4" y="-4" width="'+(w+8)+'" height="40" rx="10"/>':"")+'<rect class="kpBox" width="'+w+'" height="32" rx="7"/><text x="'+(w/2)+'" y="20" text-anchor="middle">'+kpE(n[2])+'</text></g>';}).join("");
 const bd=[];P.forEach(p=>{if(p.m==="A")bd.push([p.b,"A"]);if(p.m==="S")bd.push([p.b,"S"]);});
 if(T.ty==="r"||T.ty==="d"){const aN=(bd.find(x=>x[1]==="A")||[])[0],sN=(bd.find(x=>x[1]==="S")||[])[0];
  const bx=(id,key,pre)=>{const n=sc.n[id];if(!n)return"";return'<g class="kpBd" transform="translate('+n[0]+','+(n[1]-24)+')"><text id="kpB'+key+'" text-anchor="middle" class="'+key+'">'+pre+' 0</text></g>';};
  s+=bx(aN,"A",T.ty==="d"?"Hoạt động":"Thử");if(sN&&sN!==aN)s+=bx(sN,"S",T.ty==="d"?"Giải phóng thường":"Thành công");else if(sN===aN){const n=sc.n[aN];s+='<g class="kpBd" transform="translate('+n[0]+','+(n[1]-37)+')"><text id="kpBS" text-anchor="middle" class="S">'+(T.ty==="d"?"Giải phóng thường":"Thành công")+' 0</text></g>';}
  s+='<g id="kpFailMark" class="kpFM" style="display:none"><text id="kpFailT" text-anchor="middle">✕</text></g>';}
 s+='<g id="kpMsg" style="display:none"><rect id="kpMsgR" rx="5" height="18"/><text id="kpMsgT" y="13" text-anchor="middle"></text></g><circle id="kpPkt" r="6" class="kpP" style="display:none"/></svg>';return s;}
function kpGaugeHtml(T){const z=T.dir==="u"?[[T.min,T.bad,"bad"],[T.bad,T.good,"mid"],[T.good,T.max,"ok"]]:[[T.min,T.good,"ok"],[T.good,T.bad,"mid"],[T.bad,T.max,"bad"]];const r=T.max-T.min;return'<div class="kpGauge"><div class="kpGz">'+z.map(a=>'<i class="'+a[2]+'" style="width:'+Math.max(0,(a[1]-a[0])/r*100).toFixed(1)+'%"></i>').join("")+'<b id="kpGneedle" style="left:0%"></b></div><div class="kpGv"><span id="kpGval">–</span> <small>'+kpE(T.unit)+'</small></div><div class="note">Vùng xanh đạt, vàng cảnh báo, đỏ không đạt (ngưỡng minh hoạ: tốt '+T.good+', xấu '+T.bad+' '+kpE(T.unit)+').</div></div>';}
function kpDetHtml(k){const T=kpType(k),P=kpPath(k),sc=KSC[k.sc],pb=KPB[k.pb]||{t:"",st:[],ca:[],pa:[],cs:[]};
 const vcol=k.tech==="SEC"?-1:({"3gpp":0,huawei:1,ericsson:2,nokia:3}[S.vendor]??-1);
 const col=a=>a.length?'<ul class="kpUl">'+a.map(x=>'<li>'+kpCnt(x)+'</li>').join("")+'</ul>':'<span class="note">chưa có</span>';
 const sec=k.tech==="SEC",ext=sec||k.tech==="TX"||k.tech==="IT";const cards=[[ext?"Chuẩn (ITU, IETF, 3GPP, NIST…)":"3GPP",'<p class="kpc3">'+kpE(k.c3)+'</p>'],[sec?"Cisco":"Huawei",col(k.hw)],[sec?"Juniper":"Ericsson",col(k.er)],[sec?"Check Point":"Nokia",col(k.nk)]];
 const tbl='<div class="kpVg">'+cards.map((c,i)=>'<div class="kpv'+(i===vcol?' hl':'')+'"><h4>'+c[0]+'</h4>'+c[1]+'</div>').join("")+'</div>'
  +'<p class="note"><span class="kpC ok">✓</span> đã đối chiếu nguồn công khai đã tra · <span class="kpC mid">~</span> tên theo quy ước vendor, cần đối chiếu counter reference đúng release · <span class="kpC no">?</span> chưa có tên chắc chắn, chỉ mô tả hướng tra. Vendor đang chọn ở thanh trên được viền đậm.</p>';
 const A=P.find(p=>p.m==="A"),Sx=P.find(p=>p.m==="S"),nm=id=>sc.n[id]?sc.n[id][2]:id;
 const pts=T.ty==="g"?'<li>Giá trị đo tại: '+k.nd.map(id=>'<b>'+kpE(nm(id))+'</b>').join(", ")+'.</li>':'<li><b>'+(T.ty==="d"?"Đang hoạt động":"Thử (attempt)")+'</b> đếm khi «'+kpE(A?A.l:"")+'» tới <b>'+kpE(A?nm(A.b):"")+'</b>.</li><li><b>'+(T.ty==="d"?"Giải phóng thường":"Thành công")+'</b> đếm khi «'+kpE(Sx?Sx.l:"")+'» tới <b>'+kpE(Sx?nm(Sx.b):"")+'</b>.</li><li>'+(T.ty==="d"?'<b>Rớt bất thường</b> đếm khi bản tin giải phóng mang nguyên nhân bất thường đi qua một chặng giữa hai điểm trên.':'<b>Thất bại</b> là mọi lần có «thử» nhưng không tới «thành công»; counter vendor tách theo nguyên nhân.')+'</li>';
 const nodes='<ul class="kpUl">'+k.nd.map(id=>sc.n[id]?'<li><b>'+kpE(sc.n[id][2])+'</b> – '+kpE(sc.n[id][3])+'</li>':"").join("")+'</ul><ul class="kpUl">'+pts+'</ul>';
 const srcIds=[...new Set(k.sr.concat((pb.cs||[]).map(c=>c[1])))].filter(i=>KSRC[i]);
 const cs=(pb.cs&&pb.cs.length?'<ul class="kpUl">'+pb.cs.map(c=>'<li>'+kpE(c[0])+(KSRC[c[1]]?' <a href="'+KSRC[c[1]][1]+'" target="_blank" rel="noopener">[nguồn]</a>':"")+'</li>').join("")+'</ul>':'<p class="note">Chưa có casestudy công khai đã tra cho nhóm KPI này.</p>');
 const gen=pb.gen?'<p class="note kpWarn">Quy trình này tổng hợp từ kinh nghiệm chung của ngành, chưa có link riêng đã tra. Cần xác nhận với tài liệu vendor và quy định của nhà mạng trước khi áp dụng.</p>':'';
 const steps=pb.st.length?'<ol class="kpSt">'+pb.st.map((s,i)=>'<li><label><input type="checkbox" class="kpTick"> '+kpE(s)+'</label></li>').join("")+'</ol>':"";
 return'<div class="panel kpHead"><div class="kpTags"><span class="tag t'+k.tech+'">'+k.tech+'</span><span class="tag">'+KLYN[k.ly]+'</span><span class="tag">'+kpE(KCATN[k.cat])+'</span></div><h2>'+kpAbBadge(k)+kpE(k.dn)+'</h2>'+(k.ab.length>1?'<p class="note">Cũng gọi là: '+kpE(k.ab.join(", "))+'</p>':"")+(k.dn!==k.nm?'<p class="note">Tên trong bộ KPI: '+kpE(k.nm)+'</p>':"")+'<p class="note">Sơ đồ: '+kpE(sc.t)+'</p></div>'
 +'<div class="panel"><h3>Vị trí KPI trên mạng (hoạt ảnh)</h3>'+kpScene(k)+'<div class="kpCtl"><button type="button" class="btn sm" id="kpPlay" data-kpact="play" aria-pressed="true">Tạm dừng</button><button type="button" class="btn sm" data-kpact="reset">Đặt lại bộ đếm</button><label class="kplb inl">Tốc độ <select id="kpSpd"><option value="0.5">0,5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></label><label class="kplb inl grow"><span id="kpPfL"></span><input type="range" id="kpPf" min="0" max="'+(T.ty==="g"?100:60)+'" value="'+KP.pf+'"></label></div>'
 +(T.ty==="g"?kpGaugeHtml(T):'<div class="kpLive"><div><span class="note">KPI mô phỏng</span><div class="kpBig" id="kpKpi">–</div></div><div id="kpLiveTxt" class="note" aria-live="polite"></div></div>')+'</div>'
 +'<div class="panel kpGl"><h3>KPI này là gì và đóng vai trò gì trong mạng</h3><p>'+kpE(k.gl)+'</p>'+kpGlExtra(k,pb)+'</div>'
 +'<div class="panel"><h3>Ý nghĩa</h3><p>'+kpE(k.mn)+'</p><p class="note"><b>Ngưỡng tham chiếu:</b> '+kpE(k.th)+' Ngưỡng thật do SLA và quy định của từng nhà mạng quyết định.</p></div>'
 +'<div class="panel"><h3>Công thức và counter</h3><p class="kpFm">'+kpE(k.fm)+'</p>'+tbl+'</div>'
 +'<div class="panel"><h3>KPI đo ở node nào</h3>'+nodes+'</div>'
 +'<div class="panel"><h3>Xử lý khi KPI không đạt: '+kpE(pb.t)+'</h3>'+gen+'<p class="note">3GPP định nghĩa KPI và counter nhưng không ban hành quy trình xử lý. Các bước dưới đây theo thứ tự nên kiểm tra; tick để theo dõi tiến độ.</p>'+steps
 +(pb.ca.length?'<h4>Nguyên nhân thường gặp</h4><ul class="kpUl">'+pb.ca.map(c=>'<li>'+kpE(c)+'</li>').join("")+'</ul>':"")
 +(pb.pa.length?'<h4>Tham số và mục cần xem</h4><ul class="kpUl">'+pb.pa.map(c=>'<li>'+kpE(c)+'</li>').join("")+'</ul>':"")
 +'<h4>Casestudy từ diễn đàn và tài liệu đã tra</h4>'+cs+'</div>'
 +'<div class="panel"><h3>Nguồn tham khảo</h3><ul class="kpUl">'+srcIds.map(i=>'<li><a href="'+KSRC[i][1]+'" target="_blank" rel="noopener">'+kpE(KSRC[i][0])+'</a></li>').join("")+'</ul><p class="note">Mô phỏng chỉ minh hoạ vị trí và cách tính KPI; số liệu trên hoạt ảnh là ngẫu nhiên.</p></div>';}
/* ---- hoạt ảnh ---- */
const KA={raf:0,k:null,P:null,T:null,i:0,ph:"idle",t:0,fail:-1,att:0,ok:0,bad:0,norm:0,iter:0,last:0,v:0,gt:0};
function kpHop(){return 430/KP.spd;}
function kpNodePos(k,id){const n=KSC[k.sc].n[id];return n?[n[0],n[1]]:[0,0];}
function kpSetTxt(id,t){const e=document.getElementById(id);if(e)e.textContent=t;}
function kpRefreshCounters(){const k=KA.k;if(!k)return;const T=KA.T;
 if(T.ty==="r"){kpSetTxt("kpBA","Thử "+KA.att);kpSetTxt("kpBS","Thành công "+KA.ok);const v=KA.att?KA.ok/KA.att*100:null;kpSetTxt("kpKpi",v===null?"–":v.toFixed(2)+" %");kpSetTxt("kpLiveTxt","Thử "+KA.att+" · thành công "+KA.ok+" · thất bại "+KA.bad+(KA.att?" · tỉ lệ lỗi tiêm "+KP.pf+"%":""));}
 else if(T.ty==="d"){kpSetTxt("kpBA","Hoạt động "+KA.att);kpSetTxt("kpBS","Giải phóng thường "+KA.norm);const v=KA.att?KA.bad/KA.att*100:null;kpSetTxt("kpKpi",v===null?"–":v.toFixed(2)+" % rớt");kpSetTxt("kpLiveTxt","Hoạt động "+KA.att+" · giải phóng thường "+KA.norm+" · rớt bất thường "+KA.bad);}}
function kpPfLabel(){const T=KA.T||kpType(kpById(KP.sel));kpSetTxt("kpPfL",(T.ty==="g"?"Mức xấu đi của điều kiện: ":(T.ty==="d"?"Tỉ lệ rớt tiêm vào: ":"Tỉ lệ lỗi tiêm vào: "))+KP.pf+"%");}
function kpStart(){const k=kpById(KP.sel);if(!k||!document.getElementById("kpSvg"))return;KA.k=k;KA.P=kpPath(k);KA.T=kpType(k);KA.i=0;KA.ph="move";KA.t=0;KA.fail=-1;KA.att=KA.ok=KA.bad=KA.norm=KA.iter=0;KA.last=0;KA.v=KA.T.base||0;KA.gt=0;kpPfLabel();kpRefreshCounters();kpNewIter();if(!KA.raf&&S.tab==="kpi")KA.raf=requestAnimationFrame(kpLoop);}
function kpNewIter(){const P=KA.P,T=KA.T;KA.i=0;KA.t=0;KA.ph="move";KA.fail=-1;KA.iter++;if(T.ty==="g")return;const ia=P.findIndex(p=>p.m==="A"),is=P.findIndex(p=>p.m==="S");if(ia<0||is<0)return;if(Math.random()*100<KP.pf){const lo=ia+1<=is?ia+1:is;KA.fail=lo+Math.floor(Math.random()*(is-lo+1));if(T.ty==="r"&&KA.fail<=ia)KA.fail=is;}}
function kpLoop(ts){KA.raf=0;if(S.tab!=="kpi"||!KA.k||!document.getElementById("kpSvg"))return;KA.raf=requestAnimationFrame(kpLoop);if(!KP.run){KA.last=ts;return;}
 const dt=Math.min(60,ts-(KA.last||ts));KA.last=ts;const k=KA.k,P=KA.P,T=KA.T,pkt=document.getElementById("kpPkt"),mg=document.getElementById("kpMsg");if(!pkt)return;
 if(T.ty==="g"){const q=KP.pf/100,tgt=T.dir==="u"?T.base*(1-0.85*q):T.base+(T.max*0.9-T.base)*q;KA.gt+=dt;KA.v+=(tgt-KA.v)*Math.min(1,dt/400);const wob=(T.max-T.min)*0.012*Math.sin(KA.gt/260);const v=Math.max(T.min,Math.min(T.max,KA.v+wob));const gv=document.getElementById("kpGval"),nd=document.getElementById("kpGneedle");if(gv)gv.textContent=v>=100?v.toFixed(0):v>=10?v.toFixed(1):v.toFixed(2);if(nd)nd.style.left=((v-T.min)/(T.max-T.min)*100).toFixed(1)+"%";}
 const hop=kpHop(),pause=150/KP.spd,endw=900/KP.spd;
 if(KA.ph==="move"){KA.t+=dt/hop;const p=P[KA.i],a=kpNodePos(k,p.a),b=kpNodePos(k,p.b),f=Math.min(1,KA.t),x=a[0]+(b[0]-a[0])*f,y=a[1]+(b[1]-a[1])*f;pkt.style.display="";pkt.setAttribute("cx",x);pkt.setAttribute("cy",y);pkt.setAttribute("class","kpP"+(KA.fail===KA.i&&f>0.55?" bad":""));
  const tx=document.getElementById("kpMsgT"),rc=document.getElementById("kpMsgR");if(tx&&rc){tx.textContent=p.l;const w=Math.max(40,p.l.length*5.6+12);rc.setAttribute("width",w);tx.setAttribute("x",w/2);const gx=Math.max(4,Math.min(760-w-4,x-w/2)),gy=Math.max(2,y-30);mg.setAttribute("transform","translate("+gx+","+gy+")");mg.style.display="";}
  if(KA.fail===KA.i&&KA.t>=0.62){KA.ph="failhold";KA.t=0;kpMark(k,P[KA.i].b,true);return;}
  if(KA.t>=1){KA.t=0;kpArrive(k,P[KA.i]);if(KA.i>=P.length-1){KA.ph="end";}else{KA.i++;KA.ph="stay";}}}
 else if(KA.ph==="stay"){KA.t+=dt;if(KA.t>=pause){KA.t=0;KA.ph="move";}}
 else if(KA.ph==="failhold"){KA.t+=dt;if(KA.t>=endw){if(T.ty==="r"){KA.bad++;}else if(T.ty==="d"){KA.bad++;}kpRefreshCounters();kpClearMark();pkt.style.display="none";mg.style.display="none";KA.ph="idle2";KA.t=0;}}
 else if(KA.ph==="end"){KA.t+=dt;if(KA.t>=endw/1.5){pkt.style.display="none";mg.style.display="none";KA.ph="idle2";KA.t=0;}}
 else if(KA.ph==="idle2"){KA.t+=dt;if(KA.t>=200/KP.spd){kpNewIter();}}}
function kpArrive(k,p){const T=KA.T;if(p.m==="A"){KA.att++;kpFlash(p.b);}if(p.m==="S"){if(T.ty==="r")KA.ok++;else if(T.ty==="d")KA.norm++;kpFlash(p.b);}kpRefreshCounters();}
function kpFlash(id){const g=document.querySelector('#kpSvg [data-kpn="'+id+'"]');if(!g)return;g.classList.remove("flash");void g.getBoundingClientRect();g.classList.add("flash");}
function kpMark(k,id,bad){const fm=document.getElementById("kpFailMark"),t=document.getElementById("kpFailT"),n=KSC[k.sc].n[id];if(!fm||!n)return;fm.setAttribute("transform","translate("+n[0]+","+(n[1]+4)+")");fm.style.display="";if(t)t.textContent="✕ lỗi";kpSetTxt("kpLiveTxt",(KA.T.ty==="d"?"Rớt bất thường":"Thất bại")+" tại «"+KA.P[KA.i].l+"» → "+n[2]+". "+document.getElementById("kpLiveTxt").textContent);}
function kpClearMark(){const fm=document.getElementById("kpFailMark");if(fm)fm.style.display="none";}
/* ---- dựng và sự kiện ---- */
let kpSig="";
function renderKpi(){const sec=document.getElementById("t-kpi");if(!sec)return;kpAbbrFill();
 if(!kpById(KP.sel))KP.sel=KL[0].id;
 const sig=[KP.sel,S.vendor,KP.tech,KP.ly,KP.cat,KP.node].join("|");
 if(sig!==kpSig||!document.getElementById("kpSvg")){kpSig=sig;
  const flt=document.getElementById("kpFlt"),lst=document.getElementById("kpList"),det=document.getElementById("kpDet");if(!flt)return;
  const q=document.getElementById("kpQ"),had=q&&document.activeElement===q;
  flt.innerHTML=kpFltHtml();lst.innerHTML=kpListHtml();
  if(det.dataset.sel!==KP.sel+"|"+S.vendor||!document.getElementById("kpSvg")){det.dataset.sel=KP.sel+"|"+S.vendor;det.innerHTML=kpDetHtml(kpById(KP.sel));kpStart();}
  if(had){const nq=document.getElementById("kpQ");if(nq){nq.focus();nq.setSelectionRange(nq.value.length,nq.value.length);}}}
 else if(!KA.raf&&S.tab==="kpi"){KA.last=0;KA.raf=requestAnimationFrame(kpLoop);}
 const sel=document.querySelector('#kpList [aria-pressed="true"]');}
function kpRefreshList(){const flt=document.getElementById("kpFlt"),lst=document.getElementById("kpList");if(!flt||!lst)return;const q=document.getElementById("kpQ"),had=q&&document.activeElement===q;flt.innerHTML=kpFltHtml();lst.innerHTML=kpListHtml();if(had){const nq=document.getElementById("kpQ");nq.focus();nq.setSelectionRange(nq.value.length,nq.value.length);}}
function kpSelect(id){KP.sel=id;kpSig="";renderKpi();const d=document.getElementById("kpDet");if(d&&window.innerWidth<1000)d.scrollIntoView({behavior:"smooth",block:"start"});}
document.addEventListener("click",e=>{const sec=e.target.closest("#t-kpi");if(!sec)return;
 const f=e.target.closest("[data-kpf]");if(f){const[kk,vv]=f.dataset.kpf.split(":");KP[kk]=vv;if(kk==="node"&&!vv)KP.node="";const fl=kpFiltered();if(fl.length&&!fl.some(x=>x.id===KP.sel)){KP.sel=fl[0].id;kpSig="";document.getElementById("kpDet").dataset.sel="";renderKpi();}else{kpRefreshList();}return;}
 const s=e.target.closest("[data-kpsel]");if(s){kpSelect(s.dataset.kpsel);return;}
 const n=e.target.closest("[data-kpn]");if(n){const id=n.dataset.kpn;KP.node=KP.node===id?"":id;const fl=kpFiltered();if(KP.node&&fl.length&&!fl.some(x=>x.id===KP.sel)){KP.sel=fl[0].id;kpSig="";document.getElementById("kpDet").dataset.sel="";renderKpi();}else kpRefreshList();return;}
 const a=e.target.closest("[data-kpact]");if(a){if(a.dataset.kpact==="play"){KP.run=!KP.run;a.setAttribute("aria-pressed",KP.run);a.textContent=KP.run?"Tạm dừng":"Chạy tiếp";}else if(a.dataset.kpact==="reset"){KA.att=KA.ok=KA.bad=KA.norm=0;kpRefreshCounters();}}});
document.addEventListener("input",e=>{if(e.target.id==="kpQ"){KP.q=e.target.value;const fl=kpFiltered();const lst=document.getElementById("kpList");lst.innerHTML=kpListHtml();kpSetTxt("kpCount",fl.length+" trên "+KL.length+" KPI. Bấm một nút trên sơ đồ để chỉ xem KPI đo ở nút đó.");}
 else if(e.target.id==="kpPf"){KP.pf=+e.target.value;kpPfLabel();}
 else if(e.target.id==="kpSpd"){KP.spd=+e.target.value;}});
document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches&&e.target.matches("#kpSvg .kpN")){e.preventDefault();e.target.dispatchEvent(new MouseEvent("click",{bubbles:true}));}});


/* ===== Cây KPI (Công nghệ → Lớp mạng → Nhóm KPI → KPI) và popup rê chuột ===== */
const KT_OPEN=new Set();let KT_ON=false,KT_BTN=null;
function ktData(){const T=[];KTECH.slice(1).forEach(t=>{const ks=KL.filter(k=>k.tech===t[0]);if(!ks.length)return;const L=[];KLY.slice(1).forEach(l=>{const k2=ks.filter(k=>k.ly===l[0]);if(!k2.length)return;const C=[];KCAT.slice(1).forEach(c=>{const k3=k2.filter(k=>k.cat===c[0]);if(k3.length)C.push([c[0],c[1],k3]);});L.push([l[0],l[1],k2.length,C]);});T.push([t[0],t[1],ks.length,L]);});return T;}
function ktRowTxt(k){return'<b class="kpab">'+kpE(k.ab[0]||k.id)+'</b><span class="ktx"> ('+kpE(k.en)+' / '+kpE(k.fn)+')</span>';}
function ktRow(k){return'<div class="ktkw"><button type="button" role="treeitem" class="ktk'+(k.id===KP.sel?' sel':'')+'" data-kptk="'+k.id+'"'+(k.id===KP.sel?' aria-selected="true"':'')+'>'+ktRowTxt(k)+'</button><button type="button" class="ktinfo" data-kti="'+k.id+'" aria-label="Xem nhanh '+kpE(k.ab[0]||k.id)+'">ⓘ</button></div>';}
function ktNode(key,lv,label,cnt,inner){const o=KT_OPEN.has(key);return'<div class="ktn" data-lv="'+lv+'"><button type="button" role="treeitem" class="kth" data-ktn="'+kpE(key)+'" aria-expanded="'+o+'"><i class="kta" aria-hidden="true">▸</i><span>'+kpE(label)+'</span><em>'+cnt+'</em></button><div class="ktc" role="group"'+(o?'':' hidden')+'>'+inner+'</div></div>';}
function ktHtml(){const D=ktData();
 const longest=KL.slice().sort((a,b)=>(b.ab[0]+b.en+b.fn).length-(a.ab[0]+a.en+a.fn).length).slice(0,6);
 let h='<div class="kttop"><span class="ktpath">Công nghệ → Lớp mạng → Nhóm KPI → KPI</span><button type="button" class="btn sm" data-ktall="1">Mở tất cả</button><button type="button" class="btn sm" data-ktall="0">Thu gọn</button></div><div role="tree" aria-label="Cây KPI">';
 const cat=(t,l)=>c=>ktNode("c:"+t[0]+"|"+l[0]+"|"+c[0],2,KCATN[c[0]]||c[1],c[2].length,c[2].map(ktRow).join(""));
 const lay=t=>l=>ktNode("l:"+t[0]+"|"+l[0],1,KLYN[l[0]]||l[1],l[2],l[3].map(cat(t,l)).join(""));
 D.forEach(t=>{h+=ktNode("t:"+t[0],0,t[1],t[2],t[3].map(lay(t)).join(""));});
 h+='</div><div class="ktsz" aria-hidden="true">'+longest.map(k=>'<div class="ktk">'+ktRowTxt(k)+'</div>').join("")+'</div>';return h;}
function ktPlace(){const p=document.getElementById("kptree");if(!p||p.hidden||!KT_BTN)return;const r=KT_BTN.getBoundingClientRect(),vw=document.documentElement.clientWidth,pw=p.offsetWidth;
 p.style.left=(window.scrollX+Math.max(8,Math.min(r.left,vw-pw-8)))+"px";p.style.top=(window.scrollY+r.bottom+6)+"px";}
function ktPathOpen(id){const k=kpById(id);if(!k)return;KT_OPEN.add("t:"+k.tech);KT_OPEN.add("l:"+k.tech+"|"+k.ly);KT_OPEN.add("c:"+k.tech+"|"+k.ly+"|"+k.cat);}
function ktOpen(btn){KT_BTN=btn;let p=document.getElementById("kptree");if(!p){p=document.createElement("div");p.id="kptree";p.className="kptree nogl";p.hidden=true;document.body.appendChild(p);}
 ktPathOpen(KP.sel);p.innerHTML=ktHtml();p.hidden=false;KT_ON=true;btn.setAttribute("aria-expanded","true");ktPlace();
 const s=p.querySelector(".ktk.sel");if(s)s.scrollIntoView({block:"nearest"});}
function ktClose(){const p=document.getElementById("kptree");if(p)p.hidden=true;KT_ON=false;kqHide();document.querySelectorAll("#kpTreeBtn").forEach(b=>b.setAttribute("aria-expanded","false"));}
function ktToggleNode(b){const key=b.dataset.ktn,o=!KT_OPEN.has(key);if(o)KT_OPEN.add(key);else KT_OPEN.delete(key);b.setAttribute("aria-expanded",o);const c=b.nextElementSibling;if(c)c.hidden=!o;ktPlace();}
function ktPick(id){const k=kpById(id);if(!k)return;ktClose();
 if(!kpFiltered().some(x=>x.id===id)){KP.tech="all";KP.ly="all";KP.cat="all";KP.q="";KP.node="";}
 kpSelect(id);const it=document.querySelector('#kpList [data-kpsel="'+id+'"]');if(it)it.scrollIntoView({block:"nearest"});}
document.addEventListener("click",e=>{
 if(e.target.closest("#kqcard")){kqHide();return;}
 const tb=e.target.closest("#kpTreeBtn");if(tb){e.preventDefault();if(KT_ON)ktClose();else ktOpen(tb);return;}
 const p=document.getElementById("kptree");
 if(p&&!p.hidden&&p.contains(e.target)){
  const n=e.target.closest("[data-ktn]");if(n){ktToggleNode(n);return;}
  const a=e.target.closest("[data-ktall]");if(a){const D=ktData();if(a.dataset.ktall==="1"){D.forEach(t=>{KT_OPEN.add("t:"+t[0]);t[3].forEach(l=>{KT_OPEN.add("l:"+t[0]+"|"+l[0]);l[3].forEach(c=>KT_OPEN.add("c:"+t[0]+"|"+l[0]+"|"+c[0]));});});}else KT_OPEN.clear();p.innerHTML=ktHtml();ktPlace();return;}
  const i=e.target.closest("[data-kti]");if(i){const el=i.parentElement.querySelector(".ktk");kqShow(el,i.dataset.kti,true);return;}
  const k=e.target.closest("[data-kptk]");if(k){ktPick(k.dataset.kptk);return;}
  return;}
 if(p&&!p.hidden)ktClose();
 if(!e.target.closest("#kqcard"))kqHide();});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&(KT_ON||!document.getElementById("kqcard").hidden)){const b=KT_BTN;const was=KT_ON;ktClose();kqHide();if(was&&b&&b.isConnected)b.focus();}});
window.addEventListener("resize",()=>{ktPlace();kqHide();});

/* ----- popup rê chuột: viết tắt, tên Anh/Việt, giải thích, ngưỡng, hoạt ảnh ngắn ----- */
const kq=document.createElement("div");kq.id="kqcard";kq.className="nogl";kq.setAttribute("role","tooltip");kq.hidden=true;document.body.appendChild(kq);
let kqCur=null,kqAnc=null,kqHideT=0,kqShowT=0,kqFlowT=0;
const kqReduce=(()=>{try{return window.matchMedia("(prefers-reduced-motion: reduce)").matches;}catch(e){return false;}})();
const kqTr=(s,n)=>{s=String(s);return s.length>n?s.slice(0,n-1)+"…":s;};
function kqSent(t,n){t=String(t||"");let c=0,i=-1,r=0;const re=/[.;]\s/g;let m;while((m=re.exec(t))){c++;r=m.index+1;if(c===2||r>n)break;}if(r>40&&r<=n)return t.slice(0,r);return t.length>n?t.slice(0,n-1)+"…":t;}
function kqFlow(k){const sc=KSC[k.sc],P=kpPath(k),T=kpType(k);if(!sc||!P.length)return"";
 const cols=[];P.forEach(p=>{[p.a,p.b].forEach(id=>{if(!cols.includes(id))cols.push(id);});});const n=cols.length,W=380;
 const x=i=>n===1?190:34+i*((W-68)/(n-1)),nm=id=>sc.n[id]?sc.n[id][2]:id,steps=P.slice(0,9),H=34+steps.length*26+8;let o="";
 const ta=T.ty==="d"?"Hoạt động":"Thử",ts=T.ty==="d"?"Giải phóng thường":"Thành công";
 cols.forEach((id,i)=>{o+='<rect x="'+(x(i)-33)+'" y="3" width="66" height="20" rx="5" class="gqb"/><text x="'+x(i)+'" y="17" text-anchor="middle" class="gqt">'+kpE(kqTr(nm(id),11))+'</text><line x1="'+x(i)+'" y1="23" x2="'+x(i)+'" y2="'+(H-4)+'" class="gqf"/>';});
 steps.forEach((p,i)=>{const y=44+i*26,xf=x(cols.indexOf(p.a)),xt=x(cols.indexOf(p.b)),dir=xt>=xf?1:-1,len=Math.abs(xt-xf)||1,mx=Math.min(Math.max((xf+xt)/2,70),W-70);
  const lab=p.l+(p.m==="A"?" · "+ta:p.m==="S"?" · "+ts:"");
  o+='<g class="gqs'+(p.m?" kq"+p.m:"")+'" data-i="'+i+'"><line x1="'+xf+'" y1="'+y+'" x2="'+(xt-dir*5)+'" y2="'+y+'" class="gqar" style="--len:'+len+'"/><path d="M'+xt+' '+y+' l'+(-dir*7)+' -3.5 l0 7 z" class="gqah"/><text x="'+mx+'" y="'+(y-5)+'" text-anchor="middle" class="gqm">'+kpE(kqTr(lab,46))+'</text></g>';});
 return'<svg class="gqfl" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Hoạt ảnh ngắn: đường chạy bản tin của KPI '+kpE(k.ab[0]||k.id)+'">'+o+'</svg>';}
function kqGauge(k){const T=kpType(k),sc=KSC[k.sc],W=380,x0=14,w=W-28,r=T.max-T.min,px=v=>x0+(v-T.min)/r*w;
 const z=T.dir==="u"?[[T.min,T.bad,"bad"],[T.bad,T.good,"mid"],[T.good,T.max,"ok"]]:[[T.min,T.good,"ok"],[T.good,T.bad,"mid"],[T.bad,T.max,"bad"]];
 const fill={ok:"var(--k1)",mid:"var(--k4)",bad:"var(--warn)"};
 const b0=px(T.base),b1=px(T.dir==="u"?T.min+r*0.12:T.max*0.9);
 let o=z.map(a=>'<rect x="'+px(a[0]).toFixed(1)+'" y="26" width="'+Math.max(0,px(a[1])-px(a[0])).toFixed(1)+'" height="14" fill="'+fill[a[2]]+'" opacity=".75"/>').join("");
 o+='<text x="'+x0+'" y="57" class="gqt">'+T.min+'</text><text x="'+(x0+w)+'" y="57" text-anchor="end" class="gqt">'+T.max+" "+kpE(T.unit)+'</text>';
 o+='<g class="kqn" style="--x0:'+b0.toFixed(1)+'px;--x1:'+b1.toFixed(1)+'px"><path d="M0 22 l-6 -10 h12 z" class="gqah"/><line x1="0" y1="22" x2="0" y2="44" class="gql"/></g>';
 o+='<text x="'+x0+'" y="14" class="gqt">'+(T.dir==="u"?"Xấu ←":"Tốt ←")+'</text><text x="'+(x0+w)+'" y="14" text-anchor="end" class="gqt">'+(T.dir==="u"?"→ Tốt":"→ Xấu")+'</text>';
 const where=k.nd.map(id=>sc&&sc.n[id]?sc.n[id][2]:id).join(", ");
 return'<svg class="gqfl" viewBox="0 0 '+W+' 64" role="img" aria-label="Hoạt ảnh ngắn: kim đồng hồ KPI '+kpE(k.ab[0]||k.id)+' di chuyển từ mức cơ sở sang mức xấu đi">'+o+'</svg><p class="kqth">Đo tại: '+kpE(where)+'. Kim chạy từ mức cơ sở sang mức xấu đi để thấy KPI đổi vùng tốt/xấu.</p>';}
function kqHtml(k){const T=kpType(k);
 let o='<div class="gqhd"><b>'+kpE(k.ab[0]||k.id)+'</b><span class="gqe">'+kpE(k.en)+'</span></div><div class="gqvi">'+kpE(k.fn)+'</div>';
 if(k.ab.length>1)o+='<div class="kqal">Còn gọi là: '+kpE(k.ab.slice(1).join(", "))+'</div>';
 o+='<div class="kqtags"><span class="tag t'+k.tech+'">'+k.tech+'</span><span class="tag">'+kpE(KLYN[k.ly])+'</span><span class="tag">'+kpE(KCATN[k.cat])+'</span></div>';
 o+='<p class="gqrole">'+kpE(kqSent(k.gl,330))+'</p>';
 o+='<div class="gqsec">Ngưỡng tham chiếu</div><p class="kqth">'+kpE(kqSent(k.th,200))+'</p>';
 o+='<div class="gqsec">'+(T.ty==="g"?"Hoạt ảnh ngắn: kim đồng hồ":"Hoạt ảnh ngắn: đường chạy bản tin đo KPI")+'</div>'+(T.ty==="g"?kqGauge(k):kqFlow(k));
 return o+'<p class="kqhint">Bấm vào KPI để xem chi tiết đầy đủ.</p>';}
function kqStartFlow(){clearInterval(kqFlowT);kqFlowT=0;const gs=kq.querySelectorAll(".gqs");if(!gs.length)return;
 if(kqReduce){gs.forEach(g=>g.classList.add("on"));return;}
 let idx=-1;const n=gs.length;const tick=()=>{idx++;if(idx>n+1){idx=-1;gs.forEach(g=>g.classList.remove("on","cur"));return;}gs.forEach((g,i)=>{g.classList.toggle("on",i<=idx);g.classList.toggle("cur",i===idx);});};tick();kqFlowT=setInterval(tick,850);}
function kqPlace(){if(!kqAnc||!kqAnc.isConnected){kqHide();return;}
 const vw=document.documentElement.clientWidth,vh=window.innerHeight,row=kqAnc.getBoundingClientRect(),box=(kqAnc.closest(".kptree,.kplist")||kqAnc).getBoundingClientRect();
 kq.style.maxWidth=Math.min(440,vw-16)+"px";const cw=kq.offsetWidth,ch=kq.offsetHeight;let x,y=Math.max(8,Math.min(row.top-6,vh-ch-8));
 if(box.right+8+cw<=vw-8)x=box.right+8;else if(box.left-8-cw>=8)x=box.left-8-cw;else{x=Math.min(Math.max(8,row.left),vw-cw-8);y=row.bottom+6;if(y+ch>vh-8){const up=row.top-ch-6;if(up>=8)y=up;else{x=vw-cw-8;y=Math.max(8,Math.min(row.top-6,vh-ch-8));}}}
 kq.style.left=x+"px";kq.style.top=y+"px";}
function kqShow(el,id,now){clearTimeout(kqHideT);clearTimeout(kqShowT);const go=()=>{const k=kpById(id);if(!k||!el.isConnected)return;if(kqCur===id&&kqAnc===el&&!kq.hidden)return;
  kqCur=id;kqAnc=el;kq.innerHTML=kqHtml(k);kq.hidden=false;kq.style.visibility="hidden";kqPlace();kq.style.visibility="";kqStartFlow();};
 if(now)go();else kqShowT=setTimeout(go,140);}
function kqHide(){clearTimeout(kqHideT);clearTimeout(kqShowT);kq.hidden=true;kqCur=null;kqAnc=null;clearInterval(kqFlowT);kqFlowT=0;}
const kqRow=t=>t&&t.closest?t.closest(".ktk[data-kptk],.kpit[data-kpsel]"):null;
const kqId=r=>r.dataset.kptk||r.dataset.kpsel;
document.addEventListener("mouseover",e=>{const r=kqRow(e.target);if(r){if(window.matchMedia&&!window.matchMedia("(hover: hover)").matches)return;kqShow(r,kqId(r),false);}else if(e.target.closest&&e.target.closest("#kqcard")){clearTimeout(kqHideT);}});
document.addEventListener("mouseout",e=>{const r=kqRow(e.target);if(r&&!(e.relatedTarget&&r.contains(e.relatedTarget))){clearTimeout(kqShowT);clearTimeout(kqHideT);kqHideT=setTimeout(kqHide,220);}});
document.addEventListener("focusin",e=>{const r=kqRow(e.target);if(r)kqShow(r,kqId(r),false);});
document.addEventListener("focusout",e=>{const r=kqRow(e.target);if(r){clearTimeout(kqShowT);clearTimeout(kqHideT);kqHideT=setTimeout(kqHide,220);}});

/* ===== Bảng tra viết tắt KPI A–Z ===== */
let KAB_ROWS=null;
function kpAbbrBuild(){const m=new Map();
 const isAb=t=>/^[A-Za-z0-9][A-Za-z0-9\-\/&.:]{1,14}$/.test(t)&&(t.match(/[A-Z0-9]/g)||[]).length>=2&&!/\s/.test(t);
 for(const k of KL){const set=new Set([k.ab[0]].concat(k.ab.slice(1).filter(isAb)));
  for(const a of set){if(!a)continue;const key=a.toUpperCase();if(!m.has(key))m.set(key,{a:a,ks:[]});const e=m.get(key);if(!e.ks.includes(k))e.ks.push(k);}}
 KAB_ROWS=[...m.values()].sort((x,y)=>x.a.localeCompare(y.a,"vi",{sensitivity:"base"}));}
function kpAbbrFirstSent(t){const i=t.search(/[.;]\s/);return(i>10&&i<220?t.slice(0,i+1):t.slice(0,200)+(t.length>200?"…":""));}
function kpAbbrHtml(q){if(!KAB_ROWS)kpAbbrBuild();q=(q||"").trim().toLowerCase();let n=0;
 const h=KAB_ROWS.filter(r=>!q||(r.a+" "+r.ks.map(k=>k.dn+" "+k.ab.join(" ")).join(" ")).toLowerCase().includes(q)).map(r=>{n++;
  return'<tr><td>'+kpE(r.a)+'</td><td>'+r.ks.map(k=>kpE(k.fn)).join("<br>")+'</td><td>'+kpE(kpAbbrFirstSent(r.ks[0].gl))+'</td><td>'+r.ks.map(k=>'<button type="button" class="btn sm kpabs" data-kpabsel="'+k.id+'" title="'+kpE(k.dn)+'">'+k.tech+' · '+kpE(k.ab[0])+'</button>').join("")+'</td></tr>';}).join("");
 return h||'<tr><td colspan="4" class="note">Không có viết tắt phù hợp.</td></tr>';}
function kpAbbrFill(){const b=document.getElementById("kpAbBody");if(b&&!b.dataset.f){b.dataset.f="1";b.innerHTML=kpAbbrHtml("");}}
document.addEventListener("input",e=>{if(e.target.id==="kpAbQ"){const b=document.getElementById("kpAbBody");if(b)b.innerHTML=kpAbbrHtml(e.target.value);}});
document.addEventListener("click",e=>{const t=e.target.closest("[data-kpabsel]");if(!t)return;KP.tech="all";KP.ly="all";KP.cat="all";KP.node="";KP.q="";kpSig="";kpSelect(t.dataset.kpabsel);const d=document.getElementById("kpDet");if(d)d.scrollIntoView({behavior:"smooth",block:"start"});});

/* ===== Menu nhóm thẻ: rê chuột để mở, bấm để cố định ===== */
(function(){
 const nav=document.getElementById('tabs');if(!nav)return;
 const shut=g=>{g.classList.remove('open');const h=g.querySelector('.tgh');if(h)h.setAttribute('aria-expanded','false');};
 const closeAll=ex=>nav.querySelectorAll('.tgrp').forEach(g=>{if(g!==ex)shut(g);});
 nav.addEventListener('click',e=>{
  const h=e.target.closest('.tgh');
  if(h){const g=h.parentElement,on=!g.classList.contains('open');closeAll(g);g.classList.toggle('open',on);h.setAttribute('aria-expanded',String(on));g.classList.remove('shut');return;}
  const t=e.target.closest('[data-tab]');
  if(t){const g=t.closest('.tgrp');if(g){shut(g);g.classList.add('shut');}}
 });
 nav.querySelectorAll('.tgrp').forEach(g=>g.addEventListener('mouseleave',()=>g.classList.remove('shut')));
 document.addEventListener('click',e=>{if(!e.target.closest('.tgrp'))closeAll();});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAll();}});
 window.tabGroups=function(){nav.querySelectorAll('.tgrp').forEach(g=>{const a=g.querySelector('[role="tab"][aria-selected="true"]');g.classList.toggle('cur',!!a);const s=g.querySelector('.tgs');if(s)s.textContent=a?a.textContent:'';});};
})();


/* tìm kiếm chung */
const RENDER={pr:()=>gxRender('pr'),tx:()=>gxRender('tx'),fw:()=>gxRender('fw'),ims:renderIms,vo:()=>gxRender('vo'),hx:()=>gxRender('hx'),it:()=>gxRender('it'),rm:()=>gxRender('rm'),sv:()=>gxRender('sv'),al:()=>gxRender('al'),rsh:renderRsh,mob:renderMob,book:renderBook,arch:renderArch,core:()=>renderCore(),prb:renderPrb,ca:renderCa,beam:renderBeam,es:renderEs,radio:renderRadio,frame:renderFrame,sig:renderSig,stack:renderStack,vendor:renderVendor,ml:()=>gxRender('ml'),kpi:renderKpi};
function renderTab(){RENDER[S.tab]();tourUi();}
function setState(){
  $$('#segMode button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===S.mode));
  $('#tabs [data-tab="ca"]').textContent=lte()?'LTE-Advanced':'5G-Advanced';
  $$('#segVendor button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.vendor===S.vendor));
  $$('#segShare button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.share===S.share));
  $$('#tabs [data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===S.tab));if(window.tabGroups)tabGroups();
  $$('.tab').forEach(t=>t.classList.toggle('on',t.id==='t-'+S.tab));
  if(tabSeen!==S.tab){tabSeen=S.tab;const n=$('#tabs'),b=$(`#tabs [data-tab="${S.tab}"]`);if(b)n.scrollTo({left:b.offsetLeft-n.offsetLeft-(n.clientWidth-b.offsetWidth)/2});}
  tabArrows();
}
/* hai mũi tên ở hai đầu thanh thẻ: cuộn qua lại, mờ đi khi đã tới đầu mút, ẩn khi mọi thẻ đã vừa màn hình */
let tabSeen='';
function tabArrows(){const n=$('#tabs');$('#tabWrap').classList.toggle('fit',n.scrollWidth<=n.clientWidth+2);$('#tabL').disabled=n.scrollLeft<=2;$('#tabR').disabled=n.scrollLeft+n.clientWidth>=n.scrollWidth-2;}
$('#tabL').addEventListener('click',()=>{const n=$('#tabs');n.scrollBy({left:-n.clientWidth*0.8});});
$('#tabR').addEventListener('click',()=>{const n=$('#tabs');n.scrollBy({left:n.clientWidth*0.8});});
$('#tabs').addEventListener('scroll',tabArrows,{passive:true});window.addEventListener('resize',tabArrows);
function renderAll(){normalize();setState();renderCtls();chips();renderTab();shareFill();}
function stopPlay(){tourStop();}
function hooks(k){
  imHooks(k);gxHooks(k);
  if(k==='band')bandDefaults();
  if(k==='ant')antDefaults();
  if(k==='proc'){S.step=0;stopSig();}
  if(k==='esProf'&&S.esProf!=='custom'){const q={low:[25,2],mid:[60,4],high:[90,8]}[S.esProf];S.esPeak=q[0];S.esNight=q[1];}
  if(k==='esPeak'||k==='esNight')S.esProf='custom';
  if(['bk','bRp','bStk','bPath','bRaType','bOpt'].includes(k))S.bkStep=0;
  if(k==='mbV')S.mbPos=0;
  if(k==='rsV'){S.rsStep=k&&S.rsV==='arch'?Math.max(0,Object.keys(RSM).indexOf(S.rsModel)):0;}
  if(k==='rsModel'&&S.rsV==='arch')S.rsStep=Object.keys(RSM).indexOf(S.rsModel);
  if(k==='rsModel'&&S.share!=='none'&&(S.rsModel==='moran'||S.rsModel==='mocn'))S.share=S.rsModel;
  if(k==='rsUe'||k==='rsCellId')S.rsStep=Math.min(S.rsStep,rsN()-1);
  if(k==='bSplit')S.bkStep=S.bSplit-1;
  if(k==='bCh')S.bkStep=Object.keys(CHMAP).indexOf(S.bCh);
  if(k==='bRsV')S.bkStep=Object.keys(RSV).indexOf(S.bRsV);
  if(k==='volte'){lteProcs();S.proc=0;S.step=0;stopSig();}
  if(k==='lAnt')S.layers=Math.min(S.layers,LANT[S.lAnt].lay);
  if(k==='coreView')S.csel=coreDefault();
  if(k==='bTech'){S.bArr=BTECH[S.bTech].def;S.bSlot=0;}
  if((k==='bArr'||k==='bTech')&&S.bArr!=='custom'){const p=BARR[S.bArr];S.bNh=p.nh;S.bNv=p.nv;S.bK=p.k;}
  if(k==='pdir'){const g=PRB&&(S.pdir==='ul'?PRB.gridNU:PRB.gridN),i=g?g.findIndex(x=>x.own):0;S.psel={rat:'nr',slot:Math.max(0,i)};}
  if(k==='tdd'||k==='ssf'||k==='scs')S.slot=0;
  if(k==='dest'){if(S.dest==='custom'){S.cx=0.6*refD();S.cy=0.3*refD();}S.ux=Math.min(S.ux,routeLen());}
}
document.addEventListener('input',e=>{
  const el=e.target;if(el.dataset&&el.dataset.ob!==undefined&&el.type==='range'){const o=S.obs[+el.dataset.ob];o[el.dataset.f]=+el.value;el.parentElement.querySelector('output').textContent=el.value+(el.dataset.f==='abs'?' dB':' %');renderRadio();return;}
  const k=el.dataset&&el.dataset.k;if(!k||el.tagName==='SELECT')return;
  S[k]=Number(el.value);const o=el.parentElement.querySelector('output');
  hooks(k);normalize();if(o)o.textContent=C[k].f(S[k]);chips();renderTab();
});
/* tham số của từng tính năng tiết kiệm điện */
