/* đổi giữa 5G SA, 5G NSA và 4G: đặt lại các lựa chọn phụ thuộc chế độ */
function switchMode(m){
  if(S.mode==='LTE'){if(S.covRat==='lte')S.covRat='nr';S.psel={rat:'nr',slot:0};}
  S.mode=m;S.slot=0;S.layer='pdcp';
  const tk=m==='LTE'?'lte':'nr';if(S.bTech!=='umts'&&S.bTech!==tk){S.bTech=tk;const k=BTECH[tk].def,p=BARR[k];S.bArr=k;S.bNh=p.nh;S.bNv=p.nv;S.bK=p.k;}
  S.sel=nsa()?'enb':'cucp';S.csel=coreDefault();S.proc=0;S.step=0;
}
document.addEventListener('click',e=>{
  const tb=e.target.closest('[data-tour]');if(tb){tourAct(tb.dataset.tour);return;}
  const t=e.target.closest('[data-mode],[data-vendor],[data-tab],[data-n],[data-c],[data-prb],[data-es],[data-eh],[data-bv],[data-cam],[data-bks],[data-bkgo],[data-mbs],[data-ims],[data-imn],[data-gxs],[data-rss],[data-share],[data-layer],[data-step],[data-slot]');if(!t)return;
  const d=t.dataset;
  if(d.mode){if(d.mode===S.mode)return;switchMode(d.mode);stopSig();stopPlay();renderAll();}
  else if(d.vendor){S.vendor=d.vendor;renderAll();}
  else if(d.tab){S.tab=d.tab;stopSig();stopPlay();renderAll();window.scrollTo({top:Math.min(window.scrollY,$('main').offsetTop-$('.bar').offsetHeight)});}
  else if(d.n){tourStop();S.sel=d.n;renderArch();tourUi();}
  else if(d.c){tourStop();S.csel=d.c;renderCore();tourUi();}
  else if(d.es){const k=esVend()+'.'+d.es;S.esOn[k]=esOn(esVend(),d.es)?0:1;renderEs();tourUi();}
  else if(d.eh!==undefined){tourStop();S.esHour=+d.eh;renderEs();tourUi();}
  else if(d.share){S.share=d.share;if(d.share!=='none'){S.rsModel=d.share;if(S.rsV==='arch')S.rsStep=Object.keys(RSM).indexOf(d.share);}tourStop();renderAll();}
  else if(d.rss!==undefined){tourStop();S.rsStep=+d.rss;renderAll();}
  else if(d.mbs!==undefined){tourStop();S.mbPos=+d.mbs;renderMob();tourUi();}
  else if(d.ims!==undefined){tourStop();imSet(+d.ims);renderIms();renderCtls();tourUi();}
  else if(d.gxs!==undefined){tourStop();const [gk,gi]=d.gxs.split(':');S[gk+'S']=+gi;const it=gxItem(gk);if(it.sync)it.sync(+gi);gxRender(gk);renderCtls();tourUi();}
  else if(d.imn!==undefined){tourStop();S.imNode=d.imn;imSync();renderIms();tourUi();}
  else if(d.bks!==undefined){tourStop();S.bkStep=+d.bks;const m=BK[S.bk];if(m.sync)m.sync(S.bkStep);renderAll();}
  else if(d.bkgo){tourStop();S.bk=d.bkgo;S.bkStep=0;S.tab='book';renderAll();window.scrollTo(0,0);}
  else if(d.cam){S.bCam=d.cam;if(d.cam==='near'){S.bSY=62;S.bSP=10;}else{S.bSY=46;S.bSP=24;}renderScene();$$('[data-cam]').forEach(b=>b.classList.toggle('pri',b.dataset.cam===S.bCam));}
  else if(d.bv){const [y,p]=d.bv.split(',').map(Number);S.bYaw=y;S.bPitch=p;drawBeam3D();}
  else if(d.prb){tourStop();const [rat,sl]=d.prb.split(':');S.psel={rat,slot:+sl};renderPrb();tourUi();}
  else if(d.layer){tourStop();S.layer=d.layer;renderStack();tourUi();}
  else if(d.step!==undefined){S.step=Number(d.step);stopSig();renderSig();}
  else if(d.slot!==undefined&&!isNaN(Number(d.slot))){tourStop();S.slot=Number(d.slot);renderFrame();tourUi();}
});
