    if(cols){if(sib)par.insertBefore(p,dir<0?sib:sib.nextSibling);else if(par!==cols&&dir<0&&cols.previousElementSibling===null)return false;else cols.parentElement.insertBefore(p,dir<0?cols:cols.nextSibling);return true;}
